window.__BOOK__['p11'].push([{"id":"b268-1","bab":"الجزء 22","sec":"أخبار خالد بن عبد الله نسبه","page":"ج22 ص5","text":"هو خالد بن عبد الله بن يزيد بن أسد بن كرز بن عامر بن عبد الله بن عبد شمس بن غمغمة بن جرير بن شق بن صعب وشق بن صعب هذا هو الكاهن المشهور بن يشكر بن رهم بن أقزل وهو سعد الصبح بن زيد بن قسر بن عبقر بن أنمار بن إراش بن عمرو بن لحيان بن الغوث بن القرز ويقال الفرز بن نبت بن مالك بن زيد بن كهلان بن سبأ بن يشجب بن يعرب بن قحطان فأما غلبة بجيلة على هذا النسب في شهرته بها فإن بجيلة ليست برجل إنما هي امرأة قد اختلف في نسبها فقال ابن الكلبي يقال لها بجيلة بنت صعب بن سعد العشيرة تزوجها أنمار بن إراش فولدت له الغوث ووداعة وصهيبة وجذيمة وأشهل وشهلاء وطريفا والحارث ومالكا وفهما وشيبة\nقال ابن الكلبي ويقال إن بجيلة إمرأة حبشية كانت قد حضنت بني أنمار جميعا غير خثعم فإنه انفرد فصار قبيلة على حدته ولم تحضنه بجيلة واحتج من قال هذا القول بقول شاعرهم\n(وما قربت بجيلة منك دوني ... بشيء غير ما دعيت بجيلة)\n(وما للغوث عندك أن نسبنا ... علينا في القرابة من فضيلة)\n(ولكنا وإياكم كثرنا ... فصرنا في المحل على جديلة)\nديلة ها هنا موضع لا قبيلة وهم أهل بيت شرف في بجيلة لولا ما يقال في عبد الله بن أسد فإن أصحاب المثالب ينفونه عن أبيه ويقولون فيه أقوالا أنا ذاكرها في موضعها من أخبار خالد المذمومة في هذا الموضع من كتابنا إن شاء الله وعلى ما قيل فيه أيضا فقد كان له ولابنه خالد سؤدد وشرف وجود وكان يقال لكرز كرز الأعنة وإياه عنى قيس بن الخطيم بقوله لما خرج يطلب النصر على الخزرج\n(فإن تنزل بذي النجدات كرز ... تلاق لديه شربا غير نزر)\n(له سجلان سجل من صريح ... وسجل رثيئة بعتيق خمر)\n(ويمنع من أراد ولا يعايا ... مقاما في المحلة وسط قسر)\nكان أسد بن كرز يدعى في الجاهلية رب بجيلة وكان ممن حرم\nالخمر في جاهليته تنزها عنها وله يقول القتال السحمي\n(فأبلغ ربنا أسد بن كرز ... بأن النأي لم يك عن تقالي)\nوله يقول القتال يعتذر\n(فأبلغ ربنا أسد بن كرز ... بأني قد ضللت وما اهتديت)\nله يقول تأبط شرا\n(وجدت ابن كرز تستهل يمينه ... ويطلق أغلال الأسير المكبل)\nكان قوم من سحمة عرضوا لجار الأسد بن كرز فأطردوا إبلا له فأوقع بهم أسد وقعة عظيمة في الجاهلية وتتبعهم حتى عاذوا به فقال القتال فيه عدة قصائد يعتذر إليه لقومه ويستقيله فعلهم بجاره ولم أذكرها ههنا لطولها وأن ذلك ليس من الغرض المطلوب في هذا الكتاب وإنما نذكرها هنا لمعا وسائره مذكور في جمهرة أنساب العرب الذي جمعت فيه أنسابها وأخبارها وسميته -","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":0,"spl":"أخبار خالد بن عبد الله نسبه — كتاب التعديل والانتضاف","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":3592},
{"id":"b268-2","bab":"الجزء 22","sec":"كتاب التعديل والانتضاف","page":"ج22 ص7","text":"- ولبني سحمة يقول أسد بن كرز في هذه القصة وكان شاعرا فاتكا مغوارا\n(ألا أبلغا أبناء سحمة كلها ... بني خثعم عني وذل لخثعم)\n(فما أنتم مني ولا أنا منكم ... فراش حريق العرفج المتضرم)\n(فلست كمن تزري المقالة عرضه ... دنيئا كعود الدوحة المترنم)\n(وما جار بيتي بالذليل فترتجى ... ظلامته يوما ولا المتهضم)\n(وأقزل آبائي وقسر عمارتي ... هما ردياني عزتي وتكرمي)\n(وأحمس يوما إن دعوت أجابني ... عرانين منهم أهل أيد وأنعم)\n(فمن جار مولى يدفع الضيم جاره ... إذا ضاع جاري يا أميمة أو دمي)\n(وكيف يخاف الضيم من كان جاره ... مع الشمس ما إن يستطاع بسلم)\nهي قصيدة طويلة ولأسد أشعار كثيرة ذكرت هذه منها ها هنا لأن تعلم إعراقهم في العلم والشعر وسائرها يذكر في كتاب النسب مع أخبار شعراء القبائل إن شاء الله تعالى","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":0,"spl":"أخبار خالد بن عبد الله نسبه — كتاب التعديل والانتضاف","tags":["الرواية والكتابة"],"loc":3593},
{"id":"b268-3","bab":"الجزء 22","sec":"جده وابنه أدركا الإسلام","page":"ج22 ص8","text":"وأدرك أسد بن كرز الإسلام هو وابنه يزيد بن أسد فأسلما فأما أسد فلا أعلمه روى عن رسول الله وآله رواية كثيرة بل ما روى شيئا وأما يزيد ابنه فروى عنه رواية يسيرة وذكر جرير بن عبد الله خبر إسلامه حدث بذلك عنه خالد بن يزيد عن إسماعيل بن أبي خالد عن قيس بن أبي حازم عن جرير بن عبد الله قال أسلم أسد بن كرز ومعه رجل من ثقيف فأهدى إلى النبي\nقوسا فقال له يا أسد من أين لك هذه النبعة فقال يا رسول الله تنبت بجبلنا بالسراة فقال الثقفي يا رسول الله الجبل لنا أم لهم فقال بل الجبل جبل قسر به سمي أبوهم قسر عبقر فقال أسد يا رسول الله ادع لي فقال اللهم اجعل نصرك ونصر دينك في عقب أسد بن كرز وما أدري ما أقول في هذا الحديث وأكره أن أكذب بما روي عن رسول الله ولكن ظاهر الأمر يوجب أنه لو كان رسول الله دعا له بهذا الدعاء لم يكن ابنه مع معاوية بصفين على علي أمير المؤمنين علي بن أبي طالب صلوات الله عليه ولا كان ابن ابنه خالد يلعنه على المنبر ويتجاوز ذلك إلى ما ساء ذكره من شنيع أخباره قبحه الله ولعنه إلا أني أذكر الشيء كما روي ومن\nقال على رسول الله وآله ما لم يقل فقد تبوأ مقعده من النار كما وعده وكان جرير بن عبد الله نافر قضاعة فبلغ ذلك أسد بن عبد الله وكان بينه وبينه أعني جريرا تباعد فأقبل في فوارس من قومه ناصرا لجرير ومعاونا له ومنجدا فزعموا أن أسدا لما أقبل في أصحابه فرآه جرير ورأى أصحابه في السلاح ارتاع وخافه فقيل له هذا أسد جاءك ناصرا لك فقال جرير ليت لي بكل بلد ابن عم عاقا مثل أسد فقال جعدة بن عبد الله الخزاعي يذكر ذلك من فعل أسد\n(تدارك ركض المرء من آل عبقر ... جريرا وقد رانت عليه حلائبه)\n(فنفس واسترخى به العقد بعد ما ... تغشاه يوم لا توارى كواكبه)\n(وقاك ابن كرز ذو الفعال بنفسه ... وما كنت وصالا له إذ تحاربه)\n(إلى أسد يأوي الذليل ببيته ... ويلجأ إذ أعيت عليه مذاهبه)\n(فتى لا يزال الدهر يحمل معظما ... إذا المجتدى المسؤول ضنت رواجبه)","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":1,"spl":"جده وابنه أدركا الإسلام — خبر على لسان جده يزيد","tags":["الرواية والكتابة"],"loc":3594},
{"id":"b268-4","bab":"الجزء 22","sec":"خبر على لسان جده يزيد","page":"ج22 ص10","text":"وأما يزيد بن أسد فقد ذكرت إسلامه وقدومه مع أبيه على النبي وقد روى عنه أيضا حديثا ذكره هشيم بن بشر الواسطي عن سنان بن أبي الحكم قال سمعت خالد بن عبد الله القسري وهو على المنبر يقول\nحدثني أبي عن جدي يزيد بن أسد قال قال رسول الله يا يزيد أحبب للناس ما تحبه لنفسك وخرج يزيد بن أسد في أيام عمر بن الخطاب في بعوث المسلمين إلى الشام فكان بها وكان مطاعا في اليمن عظيم الشأن ولما كتب عثمان إلى معاوية حين حصر يستنجده بعث معاوية إليه بيزيد بن أسد في أربعة آلاف من أهل الشام فوجد عثمان قد قتل فانصرف إلى معاوية ولم يحدث شيئا ولما كان يوم صفين قام في الناس فخطب خطبة مذكورة حرضهم فيها فذكر من\nروى عنه خبره في ذلك الموضع أنه قام وعليه عمامة خز سوداء وهو متكئ على قائم سيفه فقال بعد حمد الله تعالى والصلاة على نبيه وقد كان من قضاء الله جل وعز أن جمعنا وأهل ديننا في هذه الرقعة من الأرض والله يعلم أني كنت لذلك\nكارها ولكنهم لم يبلعونا ريقنا ولم يدعونا نرتاد لديننا وننظر لمعادنا حتى نزلوا في حريمنا وبيضتنا وقد علمنا أن بالقوم حلماء وطغاما فلسنا نأمن طغاهم على ذرارينا ونسائنا وقد كنا لا نحب أن نقاتل أهل ديننا فأحرجونا حتى صارت الأمور إلى أن يصير غدا قتالنا حمية فإنا لله وإنا إليه راجعون والحمد لله رب العالمين والذي بعث محمدا بالحق لوددت أني مت قبل هذا ولكن الله تبارك وتعالى إذا أراد أمرا لم يستطع العباد رده فنستعين بالله العظيم ثم انكفأ","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":1,"spl":"جده وابنه أدركا الإسلام — خبر على لسان جده يزيد","tags":["اللهو والمزاح"],"loc":3595},
{"id":"b268-5","bab":"الجزء 22","sec":"تخنثه في حداثته","page":"ج22 ص11","text":"ولم تكن لعبد الله بن يزيد نباهة من ذكرت من آبائه وأهل المثالب يقولون إنه دعي وكان مع عمرو بن سعيد الأشدق على شرطته أيام خلافة عبد الملك بن مروان فلما قتل عمرو هرب حتى سألت اليمانية عبد الملك فيه لما أمن الناس عام الجماعة فأمنه ونشأ خالد بن عبد الله بالمدينة وكان في حداثته يتخنث ويتتبع المغنين والمخنثين ويمشي بين عمر بن أبي ربيعة وبين النساء في رسائلهن إليه وفي رسائله إليهن وكان يقال له خالد الخريت فقال مصعب الزبيري كل ما ذكره عمر بن\nأبي ربيعة في شعره فقال أرسلت الخريت أو قال أرسلت الجري فإنما يعني خالدا القسري وكان يترسل بينه وبين النساء أخبرني بذلك الحرمي ومحمد بن مزيد وغيرهما عن الزبير عن عمه\nوأخبرني عمي قال حدثني الكراني عن العمري عن الهيثم بن عدي قال كان صديقا لعمر بن أبي ربيعة بينما عمر بن أبي ربيعة ذات يوم يمشي ومعه خالد بن عبد الله القسري وهو خالد الخزاعي الذي يذكره في شعره إذا هما بأسماء وهند اللتين كان عمر يشبب بهما وهما يتماشيان فقصداهما وجلسا معهما مليا فأخذتهم السماء ومطروا فقام خالد وجاريتان للمرأتين فظللوا عليهم بمطرفة وبردين له حتى كف المطر وتفرقوا وفي ذلك يقول عمر بن أبي ربيعة\n(أفي رسم دار دمعك المترقرق ... سفاها وما استنطاق ما ليس ينطق)\n(بحيث التقى جمع ومفضى محسر ... معالم قد كادت على الدهر تخلق)\n(ذكرت بها ما قد مضى من زماننا ... وذكرك رسم الدار مما يشوق)\n(مقاما لنا عند العشاء ومجلسا ... لنا لم يكدره علينا معوق)\n(وممشى فتاة بالكساء يكنها ... به تحت عين برقها يتألق)\n(يبل أعالي الثوب قطر وتحته ... شعاع بدا يعشي العيون ويشرق)\n(فأحسن شيء بدء أول ليلة ... وآخرها حزن إذا نتفرق)\nالغناء في هذه الأبيات لمعبد خفيف ثقيل أول بالسبابة والوسطى عن يحيى المكي وذكر الهشامي أنه منحول أخبرني محمد بن خلف بن المرزبان قال حدثني أبو العباس المروزي قال حدثنا ابن عائشة قال حضر ابن أبي عتيق عمر بن أبي ربيعة يوما وهو ينشد قوله\n(ومن كان محروبا لإهراق دمعة ... وهى غربها فليأتنا نبكه غدا)\n(نعنه على الإثكال إن كان ثاكلا ... وإن كان محزونا وإن كان مقصدا)\nال فلما أصبح ابن أبي عتيق أخذ معه خالدا الخريت وقال قم بنا إلى عمر فمضينا إليه فقال له ابن أبي عتيق قد جئنا لموعدك قال وأي موعد بيننا قال قولك فليأتنا نبكه غدا\nقد جئناك لموعدك والله لا نبرح أو تبكي إن كنت صادقا في قولك أو ننصرف على أنك غير صادق ثم مضى وتركه قال ابن عائشة خالد الخريت هو خالد القسري أخبرنا علي بن صالح بن الهيثم\nقال حدثنا أبو هفان عن إسحاق وأخبرنا محمد بن مزيد عن حماد عن أبيه عن الحزامي والمثنى ومحمد بن سلام قالوا خرجت هند والرباب إلى متنزه لهما بالعقيق في نسوة فجلستا هناك تتحدثان مليا ثم أقبل إليهما خالد القسري وهو يومئذ غلام مؤنث يصحب المغنين والمخنثين ويترسل بين عمر بن أبي ربيعة وبين النساء فجلس إليهما فذكرتا عمر بن أبي ربيعة وتشوقتاه فقالتا لخالد يا خريت وكان يعرف بذلك لك عندنا حكمك إن جئتنا بعمر بن أبي ربيعة من غير أن يعلم أنا بعثنا بك إليه فقال أفعل فكيف تريان أن أقول له قالتا تؤذنه بنا وتعلمه أنا خرجنا في سر منه ومره أن يتنكر ويلبس لبسة الاعراب ليرانا في أحسن صورة ونراه في أسوإ حال فنمزح بذلك معه فجاء خالد إلى عمر فقال له هل لك في هند والرباب وصواحبات لهما قد خرجن إلى العقيق على حال حذر منك وكتمان لك أمرهما\nقال والله إني إلى لقائهن لمشتاق قال فتنكر والبس لبسة الاعراب وهلم نمض إليهن ففعل ذلك عمر ولبس ثيابا جافية وتعمم عمة الأعراب وركب قعودا له على رحل غير جيد وصار إليهن فوقف منهن قريبا وسلم\nفعرفنه فقلن هلم إلينا يا أعرابي فجاءهن وأناخ قعوده وجعل يحدثهن وينشدهن فقلن له يا أعرابي ما أظرفك وأحسن إنشادك فما جاء بك إلى هذه الناحية\nقال جئت أنشد ضالة لي فقالت له هند أنزل إلينا واحسر عمامتك عن وجهك فقد عرفنا ضالتك وأنت الآن تقدر انك قد احتلت علينا ونحن والله احتلنا عليك وبعثنا إليك بخالد الخريت حتى\nقال لك ما قال فجئتنا على أسوأ حالاتك وأقبح ملابسك فضحك عمر ونزل إليهن فتحدث معهن حتى أمسوا ثم إنهم تفرقوا ففي ذلك يقول عمر بن أبي ربيعة","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":2,"spl":"تخنثه في حداثته","tags":[],"song":1,"loc":3596},
{"id":"b268-6","bab":"الجزء 22","sec":"تخنثه في حداثته","page":"ج22 ص11","text":"(ألم تعرف الأطلال والمتربعا ... ببطن حليات دوارس بلقعا)\n(إلى السرح من وادي المغمس بدلت ... معالمه وبلا ونكباء زعزعا)\n(فيبخلن أو يخبرن بالعلم بعد ما ... نكأن فؤادا كان قدما مفجعا)\n(لهند وأتراب لهند إذ الهوى ... جميع وإذ لم نخش أن يتصدعا)\nي هذه الأبيات ثقيل أول لمعبد\n(تبالهن بالعرفان لما رأينني ... وقلن امرؤ باغ أكل وأوضعا)\n(وقربن أسباب الهوى لمتيم ... يقيس ذراعا كلما قسن إصبعا)\nخبرني الحسن بن علي قال حدثنا أحمد بن الحارث عن\nالمدائني وذكر مثل ذلك أبو عبيدة معمر بن المثنى أن كرز بن عامر جد خالد بن عبد الله عبد كان آبقا عن مواليه عبد القيس من هجر ويقال إن أصله من يهود تيماء وكان أبق فظفرت به عبد شمس فكان فيهم عند غمغمة بن شق الكاهن ثم وهبوه لقوم من بني طهية فكان عندهم حتى أدرك وهرب فأخذته بنو أسد بن خزيمة فكان فيهم وتزوج مولاة لهم يقال لها زرنب ويقال إنها كانت بغيا فأصابها فولدت له أسد بن كرز سماه باسم أسد بن خزيمة لرقة كانت فيهم ثم أعتقوه ثم إن نفرا من أهل هجر مروا به فعرفوه فلما رجعوا إلى هجر اخذوا فداءه وصاروا إلى مواليه فاشتروه وابنه فلم يزل فيهم حتى خرج معهم في تجارة إلى الطائف فلما رأى دار بجيلة أعجبته فاشترى نفسه وابنه فجاء فنزل فيهم فأقام مدة ثم ادعى إليهم وعاونه على ذلك حي من أحمس يقال لهم بنو منبة فنفاهم أبو عامر ذو الرقعة سمي بذلك لأن عينه أصيبت فكان يغطيها بخرقة وهو ابن عبد شمس بن جوين بن شق فنزل كرز في بني سحمة هاربا من ذي الرقعة ثم وثب على ابن عم للقتال بن مالك السحمي فقتله وهرب إلى البحرين مع التجار فأقام مدة ثم مات ونشأ ابنه يزيد بن أسد يدعي في بجيلة ولا تلحقه إلى أن مات ونشأ ابنه عبد الله بن يزيد ثم مضى إلى حبيب بن مسلمة الفهري وكتب له وكان كاتبا مفوها وذلك في إمارة عثمان بن\nعفان فنال حظا وشرفا وكان يقال له خطيب الشيطان ووسم خيله القسري ثم تدسس ليملك خيلا في بلاد قسر فمنعته بجيلة ذلك أشد المنع فلم يقدر عليه حتى عظم أمره ونشأ ابنه خالد ومات هو فكان خالد في مرتبته ثم ولي العراق وقال قيس بن القتال له في هذا المعنى\n(ومن سماك باسمك يا بن كرز ... وأين المولد المعروف تدري)\nوقال بجير بن ربيعة السحمي\n(نفته من الشعبين قسر بعزها ... إلى دار عبد القيس نفي المزنم)","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":3,"spl":"تخنثه في حداثته — أبوه وابن نصير في حضرة عبد الملك بن مروان","tags":["الحب والغزل"],"loc":3597},
{"id":"b268-7","bab":"الجزء 22","sec":"أبوه وابن نصير في حضرة عبد الملك بن مروان","page":"ج22 ص17","text":"قال أبو عبيدة وكان بين عبد الله بن يزيد بن أسد بن كرز وبين أبي موسى بن نصير كلام عند عبد الملك بن مروان فقال له عبد الله إنما أنت عبد لعبد القيس فقال اسكت فقد عرفناك إن لم تعرف نفسك فقال له عبد الله أنا ابن أسد بن كرز نحن الذين نضمن الشهر ونطعم الدهر فقال له تلك قسر ولست منهم وإنما أنت عبد آبق قد كنت أراك تروم مثل ذلك فلا تقدر عليه ثم نفاه جرير بن عبد الله إلى الشام فأقام بها مدة ثم مضى إلى حبيب فقال له دع\nذكر البحرين لفرارك أتراك منهم وأنت عبد واهلك من يهود تيماء فأسكتهما عبد الملك ولم يسره ما قال عبد الله لأبي موسى بن نصير لأنه كان على شرطه عمرو بن سعيد يوم قتله فقال في ذلك أبو موسى بن نصير\n(جاريت غير سؤوم في مطاولة ... يا بن الوشائط من أبناء ذي هجر)\n(لا من نزار ولا قحطان تعرفكم ... سوى عبيد لعبد القيس أو مضر)","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":3,"spl":"تخنثه في حداثته — أبوه وابن نصير في حضرة عبد الملك بن مروان","tags":["اللهو والمزاح"],"loc":3598},
{"id":"b268-8","bab":"الجزء 22","sec":"عرفت أسرته بالكذب","page":"ج22 ص18","text":"وقال أبو عبيدة فأخبرني عبد الله بن عمر بن زيد الحكمي قال كان يزيد بن أسد يلقب خطيب الشيطان وكان أكذب الناس في كل شيء معروفا بذلك ثم نشأ ابنه عبد الله فسلك منهاجه في الكذب ثم نشأ خالد ففاق الجماعة إلا أن رياسة وسخاء كانا فيه سترا ذلك من أمره\nقال عمر بن زيد فإني لجالس على باب هشام بن عبد الملك إذ قدم إسماعيل بن عبد الله أخو خالد بخبر المغيرة بن سعد وخروجه بالكوفة فجعل يأتي بأحاديث أنكرها فقلت له من أنت يا بن أخي\nقال إسماعيل بن عبد الله بن يزيد القسري فقلت يا بن أخي لقد أنكرت ما جرى حتى عرفت نسبك فجعل يضحك أخبرني اليزيدي عن سليمان بن أبي شيخ عن محمد بن الحكم وذكره أبو عبيدة واللفظ له قالا كان خالد بن عبد الله من أجبن الناس فلما خرج عليه المغيرة عرف ذلك وهو على المنبر فدهش وتحير فقال أطعموني ماء فقال الكميت في ذلك ومدح يوسف بن عمر\n(خرجت لهم تمشي البراح ولم تكن ... كمن حصنه فيه الرتاح المضبب)\n(وما خالد يستطعم الماء فاغرا ... بعدلك والداعي إلى الموت ينعب)\nقال ابن الكلبي أول كذبة كذبتها في النسب أن خالد بن عبد الله سألني عن جدته أم كرز وكانت أمة بغيا لبني أسد يقال لها زرنب فقلت له هي زينب بنت عرعرة بن جذيمة بن نصر بن قعين فسر بذلك ووصلني","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":4,"spl":"عرفت أسرته بالكذب — أعشى همدان يهجوه ويهجو أمه","tags":["المديح","الجواري والنساء"],"loc":3599},
{"id":"b268-9","bab":"الجزء 22","sec":"بنو أسد يتبرؤون منه","page":"ج22 ص19","text":"قال قال خالد ذات يوم لمحمد بن منظور الأسدي يا أبا الصباح قد ولدتمونا فقال ما أعرف فينا ولادة لكم وإن هذا لكذب فقيل له لو أقررت للأمير بولادة ما ضرك قال أأفسد وأستنبط ما ليس مني وأقر بالكذب على قومي فأمر خالد خداشا الكندي وكان عامله بضرب مولى لعباد بن إياس الأسدي فقتله فرفع إلى خالد فلم يقده فوثب عباد على خداش فقتله وقال\n(لعمري لئن جارت قضية خالد ... عن القصد ما جارت سيوف بني نصر)\nأخبرني الحسن بن علي قال حدثنا أحمد بن الحارث قال حدثنا المدائني عن سحيم بن حصين قال قتل خداش الكندي رجلا من بني أسد وكان الكندي عاملا لخالد\nالقسري فطولب بالقود وهو على دهلك فقال والله لئن أقدت من عاملي لأقيدن من نفسي ولئن أقدت من نفسي ليقيدن أمير المؤمنين من نفسه ولئن أقاد أمير المؤمنين من نفسه ليقيدن رسول الله من نفسه ولئن أقاد رسول الله من نفسه هاه هاه يعرض بالله عز و جل لعنة الله على خالد","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":4,"spl":"عرفت أسرته بالكذب — أعشى همدان يهجوه ويهجو أمه","tags":["اللهو والمزاح"],"loc":3600},
{"id":"b268-10","bab":"الجزء 22","sec":"أعشى همدان يهجوه ويهجو أمه","page":"ج22 ص20","text":"أخبرني الحسن قال حدثنا الخراز عن المدائني عن عيسى بن يزيد وابن جعدبة وأبي اليقظان قالوا كانت أم خالد رومية نصرانية فبنى لها كنيسة في ظهر قبلة المسجد الجامع بالكوفة فكان إذا أراد المؤذن في المسجد أن يؤذن ضرب لها بالناقوس وإذا قام الخطيب على المنبر رفع النصارى أصواتهم بقراءتهم فقال أعشى همدان يهجوه ويعيره بأمه وكان الناس بالكوفة إذا ذكروه في ذلك الوقت قالوا ابن البظراء فأنف من ذلك فيقال إنه ختن أمه وهي كارهة فعيره الأعشى بذلك حين يقول\n(لعمرك ما أدري وإني لسائل ... أبظراء أم مختونة أم خالد)\n(فإن كانت الموسى جرت فوق بظرها ... فما ختنت إلا ومصان قاعد)\n(يرى سوأة من حيث أطلع رأسه ... تمر عليها مرهفات الحدائد)\nقال أيضا فيه يرميه باللواط\n(ألم تر خالدا يختار ميما ... ويترك في النكاح مشق صاد)\n(ويبغض كل آنسة لعوب ... وينكح كل عبد مستقاد)\n(ألا لعن الإله بني كريز ... فكرز من خنازير السواد)\nال المدائني في خبره وأخبرني ابن شهاب بن عبد الله قال قال لي خالد بن عبد الله القسري اكتب لي النسب فبدأت بنسب مضر فمكثت فيه أياما ثم أتيته فقال ما صنعت فقلت بدأت بنسب مضر وما أتممته فقال اقطعه قطعه الله مع أصولهم واكتب لي السيرة فقلت له فإنه يمر بي الشيء من سير علي بن أبي طالب صلوات الله عليه فأذكره فقال لا إلا أن تراه في قعر الجحيم لعن الله خالدا ومن ولاه وقبحهم وصلوات الله على أمير المؤمنين","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":4,"spl":"عرفت أسرته بالكذب — أعشى همدان يهجوه ويهجو أمه","tags":["الرواية والكتابة"],"loc":3601},
{"id":"b268-11","bab":"الجزء 22","sec":"أخبار عن زندقته","page":"ج22 ص22","text":"وقال أبو عبيدة حدثني أبو الهذيل العلاف قال صعد خالد القسري المنبر فقال إلى كم يغلب باطلنا حقكم أما آن لربكم أن يغضب لكم وكان زنديقا أمه نصرانية فكان يولي النصارى والمجوس على المسلمين ويأمرهم بامتهانهم وضربهم وكان أهل الذمة يشترون الجواري المسلمات ويطئونهن فيطلق لهم ذلك ولا يغير عليهم\nوقال المدائني كان خالد يقول لو أمرني أمير المؤمنين نقضت الكعبة حجرا حجرا ونقلتها إلى الشام قال ودخل عليه فراس بن جعدة بن هبيرة وبين يديه نبق فقال له العن علي بن أبي طالب ولك بكل نبقة دينار ففعل فأعطاه بكل نبقة دينارا\nقال المدائني وكان له عامل يقال له خالد بن أمي وكان يقول والله لخالد بن أمي أفضل أمانة من علي بن أبي طالب صلوات الله عليه وقال له يوما أيما أعظم ركيتنا أم زمزم فقال له أيها الأمير من يجعل الماء العذب النقاخ مثل الملح الأجاج وكان يسمى زمزم أم الجعلان\nأخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال أتى الفرزدق خالد بن عبد الله القسري يستحمله في ديات حملها فقال له إيه يا فرزدق كأني بك قد قلت آتي الحائك بن الحائك فأخدعه عن ماله إن أعطاني أو أذمه إن منعني فأنا حائك بن حائك ولست أعطيك شيئا فاذممني كيف شئت فهجاه الفرزدق بأشعار كثيرة منها\n(ليتني من بجيلة اللؤم حتى ... يعزل العامل الذي بالعراق)\n(فإذا عامل العراقين ولى ... عدت في أسرة الكرام العتاق)\nال وإنما أراد خالد بقوله الحائك بن الحائك تصحيح نسبه في اليمن والانتفاء من العبودية لأهل هجر","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":5,"spl":"أخبار عن زندقته — تطاوله على الخلافة والنبوة","tags":["الهجاء","الجواري والنساء"],"loc":3602},
{"id":"b268-12","bab":"الجزء 22","sec":"تطاوله على الخلافة والنبوة","page":"ج22 ص23","text":"كان خالد شديد العصبية على مضر وبلغ هشاما أنه قال ما ابني يزيد بن خالد بدون مسلمة بن هشام فكان ذلك سبب عزله إياه عن العراق قال وخطب بمكة وقد أخذ بعض التابعين فحبسه في دور آل الحضرمي فأعظم الناس ذلك وأنكروه فقال قد بلغني ما أنكرتم من أخذي عدو أمير المؤمنين ومن حاربه والله لو أمرني أمير المؤمنين أن أنقض هذه الكعبة حجرا حجرا لنقضتها والله لأمير المؤمنين أكرم على الله من أنبيائه عليهم السلام ولعن الله تعالى خالدا وأخزاه\nأخبرني أبو عبيدة الصيرفي قال حدثنا الفضل بن الحسن المصري قال حدثني عمر بن شبة قال حدثني عبيد الله بن حباب قال حدثني عطاء بن مسلم قال\nقال خالد بن عبد الله وذكر النبي فقال أيما أكرم عندكم على الرجل رسوله في حاجته أو خليفته في أهله يعرض بأن هشاما خير من النبي قال أبو عبيدة خطب خالد يوما فقال إن إبراهيم خليل الله استسقى ماء فسقاه الله ملحا أجاجا وإن أمير المؤمنين استسقى الله ماء فسقاه الله عذبا نقاخا وكان الوليد حفر بئرا بين ثنية ذي طوى وثنية الحجون فكان خالد ينقل ماءها فيوضع في حوض إلى جنب زمزم ليرى الناس فضلها قال فغارت تلك البئر فلا يدرى أين هي إلى اليوم","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":5,"spl":"أخبار عن زندقته — تطاوله على الخلافة والنبوة","tags":["السفر والحج","الرواية والكتابة"],"loc":3603},
{"id":"b268-14","bab":"الجزء 22","sec":"كرهه لعلي بن أبي طالب — سليمان أمر له بمائة سوط","page":"ج22 ص24 – ج22 ص25","text":"أخبرني أبو الحسن الأسدي قال حدثنا العباس بن ميمون طايع عن ابن عائشة قال كان خالد بن عبد الله زنديقا وكانت أمه رومية نصرانية وهبها عبد الملك لأبيه فرأى يوما عكرمة مولى ابن عباس وعلى رأسه عمامة سوداء فقال إنه بلغني أن هذا العبد يشبه علي بن أبي طالب صلوات الله عليه وسلامه وإني لأرجو أن يسود الله وجهه كما سود وجه ذاك\nقال حدثني من سمعه وقد لعن عليا صلوات الله عليه وسلامه فقال في ذكره علي بن أبي طالب بن عم محمد بن عبد الله بن عبد المطلب وزوج ابنته فاطمة وأبو الحسن والحسين هل كنيت اللهم العن خالدا واخزه وجدد على روحه العذاب\nوقال أبو عبيدة ذكر إسماعيل بن خالد بن عبد الله القسري بني أمية عند أبي العباس السفاح في دولة بني هاشم فذمهم وسبهم وقال له حماس الشاعر مولى عثمان بن عفان يا أمير المؤمنين أيسب بني عمك وعمالهم وعماتك رجل اجتمع هو والخريت في نسب أن بني أمية لحمك ودمك فكلهم ولا تؤكلهم فقال له صدقت وأمسك إسماعيل فلم يحر جوابا\nوقال ابن الكلبي كان خالد بن عبد الله أميرا على مكة فأمر رأس الحجبة أن يفتح له الباب وهو ينظر فأبى فضربه مائة سوط فخرج الشيبي إلى سليمان بن عبد الملك يشكوه فصادف الفرزدق بالباب فاسترفده فلما أذن للناس ودخلا شكا الشيبي ما لحقه من خالد ووثب الفرزدق فأنشأ يقول\n(سلوا خالدا لا أكرم الله خالدا ... متى وليت قسر قريشا تدينها)\n(أقبل رسول الله أم ذاك بعده ... فتلك قريش قد أغث سمينها)\n(رجونا هداه لا هدى الله خالدا ... فما أمه بالأم يهدى جنينها)\nحمي سليمان وأمر بقطع يد خالد وكان يزيد بن المهلب عنده فما زال يفديه ويقبل يده حتى أمر بضربه مائة سوط ويعفى عن يمينه فقال الفرزدق في ذلك\n(لعمري لقد صبت على ظهر خالد ... شآبيب ما استهللن من سبل القطر)\n(أيضرب في العصيان من كان طائعا ... ويعصي أمير المؤمنين أخو قسر)\n(فنفسك لم فيما أتيت فإنما ... جزيت جزاء بالمحدرجة السمر)\n(وأنت ابن نصرانية طال بظرها ... غذتك بأولاد الخنازير والخمر)\n(فلولا يزيد بن المهلب حلقت ... بكفك فتخاء إلى الفرخ في الوكر)\n(لعمري لقد صال ابن شيبة صولة ... أرتك نجوم الليل ظاهرة تسري)","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":6,"spl":"كرهه لعلي بن أبي طالب — سليمان أمر له بمائة سوط — هجو الفرزدق له","tags":["الجواري والنساء"],"loc":3604},
{"id":"b268-15","bab":"الجزء 22","sec":"هجو الفرزدق له","page":"ج22 ص26","text":"فحقدها خالد على الفرزدق فلما ولي وحفر نهر العراق بواسط قال فيه الفرزدق أبياتا يهجوه منها\n(وأهلكت مال الله في غير حقه ... على النهر المشؤوم غير المبارك)\n(وتضرب أقواما صحاحا ظهورهم ... وتترك حق الله في ظهر مالك)\nوقال ويقال إنها للمفرج بن المرقع\n(كأنك بالمبارك بعد شهر ... يخوض غماره نقع الكلاب)\n(كذبت خليفة الرحمن عنه ... وكيف يرى الكذوب جزا الكذاب)\nأخذ خالد الفرزدق فحبسه واعتل عليه بهجائه إياه في حفر المبارك فقال الفرزدق في السجن\n(أبلغ أمير المؤمنين رسالة ... فعجل هداك الله نزعك خالدا)\n(بنى بيعة فيها الصليب لأمه ... وهدم من بغض الإله المساجدا)\nبعث هشام إلى خالد بن سويد يأمره بإطلاق الفرزدق فأطلقه فقال الفرزدق يهجو خالدا القسري\n(ألا لعن الرحمن ظهر مطية ... أتتنا تخطى من بعيد بخالد)\n(وكيف يؤم المسلمين وأمه ... تدين بأن الله ليس بواحد)\nخبرنا الحسن قال حدثنا أحمد بن الحارث قال حدثنا المدائني قال شتم عبد الله بن عياش الهمذاني خالد بن عبد الله في أيام منصور بن جمهور فسمعه رجل من لخم فقدمه إلى منصور واستعداه عليه فقال له منصور ما تريد فقال ابن عياش أمرنا أيها الأمير برقية العقرب وفيه عجب لخمي يستنصر كلبيا على همذاني لبجلي دعي\nوقال المدائني في خبره كان خالد بن عبد الله قريبا من هشام بن عبد الملك مكينا عنده فأدل وتمرغ عليه حتى إنه التفت يوما إلى ابنه يزيد بن خالد عند هشام فقال له كيف بك يا بني إذا احتاج إليك بنو أمير المؤمنين قال أواسيهم ولو في قميصي فتبين الغضب في وجه هشام واحتملها","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":6,"spl":"كرهه لعلي بن أبي طالب — سليمان أمر له بمائة سوط — هجو الفرزدق له","tags":["الهجاء"],"loc":3605},
{"id":"b268-16","bab":"الجزء 22","sec":"لقب هشاما بابن الحمقاء","page":"ج22 ص28","text":"قال المدائني حدثني بذلك عبد الكريم مولى هشام إنه كان واقفا على رأس هشام فسمع هذا من خالد قال وكان إذا ذكر هشام قال له ابن الحمقاء فسمعها رجل من أهل الشام فقال لهشام إن هذا البطر الأشر الكافر لنعمتك ونعمة أبيك وإخوتك يذكرك بأسوأ الذكر فقال ماذا يقول لعله يقول الأحول\nقال لا والله ولكن مالا تنشق به الشفتان قال فلعله قال ابن الحمقاء فأمسك الشامي فقال قد بلغني كل ذلك عنه واتخذ خالد ضياعا كثيرة حتى بلغت غلته عشرة آلاف ألف درهم فدخل عليه دهقان كان يأنس به فقال له إن الناس يحبون جسمك وأنا أحب جسمك وروحك قد بلغت غلة ابنك أكثر من عشرة آلاف ألف سوى غلتك وإن الخلفاء لا يصبرون على هذا فاحذر فقال له خالد إن أخي أسد بن عبد الله قد كلمني بمثل هذا أفأنت أمرته قال نعم قال ويحك دعه فرب يوم كان يطلب فيه الدرهم فلا يجده","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":7,"spl":"لقب هشاما بابن الحمقاء — عرف ببخله الشديد — كان يلحن في خطبه","tags":[],"loc":3606},
{"id":"b268-18","bab":"الجزء 22","sec":"عرف ببخله الشديد — كان يلحن في خطبه","page":"ج22 ص28 – ج22 ص29","text":"وقال المدائني في خبره كان خالد بن عبد الله بخيلا على الطعام فوفد إليه رجل له به حرمة فأمر أن يكتب له بعشرة آلاف درهم وحضر الطعام فأتي به فأكل أكلا منكرا فأغضبه\nوقال للخازن لا تعرض علي صكه فعرفه الخازن ذلك فقال له ويحك فما الحيلة قال تشتري غدا كل ما يحتاج إليه في مطبخه وتهب الطباخ دراهم حتى لا يشتري شيئا وتسأله إذا أكل خالد أن يقول له إنك اليوم في ضيافة فلان فاشترى كل ما أراد حتى الحطب فبلغ خمسمائة درهم فأكل خالد فاستطاب ما صنع له فقال له الطباخ إنك كنت اليوم في ضيافة فلان\nقال له وكيف ذاك فأخبره فاستحيا خالد ودعا بصكه فصيره ثلاثين ألفا ووقع فيه وأمر الخازن بتسليمها إليه قال وكان لبعض التجار على رجل دين فأراد استعداء خالد عليه فلاذ الرجل ببواب خالد وبره فقال له سأحتال لك في أمر هذا بحيلة لا يدخله عليه أبدا\nقال فافعل فلما جلس خالد للأكل أذن البواب للتاجر فدخل وخالد يأكل سمكا فجعل يأكل أكلا شنيعا كثيرا فغاظ ذلك خالدا فلما خرج قال لبوابه فيم أتاني هذا قال يستعدي على فلان في دين يدعيه عليه قال والله إني لأعلم أنه كاذب فلا يدخلن علي وتقدم إلى صاحب الشرطة بقبض يده عن صاحبه\nوقال المدائني في خبره\nكان خالد يوما يخطب على المنبر وكان لحنة وكان له مؤدب يقال له الحسين بن رهمة الكلبي وكان يجلس بإزائه فإذا شك في شيء أومأ إليه وكان لخالد صديق من تغلب زنديق يقال له زمزم فلما قام يخطب على المنبر قام إليه التغلبي في وسط خطبته\nوقال قد حضرتني مسألة قال ويحك أما ترى الشيطان عينه في عيني يعني حسينا قال لا بد والله منها قال هاتها قال أخبرني قلمسان إذا ساف ثم رفع رأسه وكرف أي شيء يقول\nقال أراه يقول ما أطيبه يا رباه قال صدقت ما كان ليستشهد على هذا سوى ربه قال المدائني وقال خالد يوما على المنبر هذا كما قال الله عز و جل أعوذ بالله من الشيطان الرجيم ثم أرتج عليه فقال للتغلبي قم فافتح علي يا أبا زمزم سورة كذا وكذا فقال خفض عليك أيها الأمير لا يهولنك ذلك فما رأيت قط عاقلا حفظ القرآن وإنما يحفظه الحمقى من الرجال\nقال صدقت يرحمك الله وقال المدائني حدثني أبو يعقوب الثقفي قال قال خالد بن عبد الله للعريان يا عريان أعجزت عن الشرط حتى أولي غيرك فإن الغناء قد فشا وظهر قال لم أعجز وإن شئت فاعزلني فقال له خذ لي المغنيات فأحضره خمسا منهن أو ستا فأدخلهن إليه فنظر\nإلى واحدة منهن بيضاء دعجاء كأنها أشربت ماء الذهب فدعا لها بكرسي فجلست ثم قال لها أين البربط الذي كانت تضرب به فأحضر ثم سوته فغنت\n(إلى خالد حتى أنخن بخالد ... فنعم الفتى يرجى ونعم المؤمل)\nفقال اعدلي عن هذا إلى غيره فغنت\n(أروح إلى القصاص كل عشية ... أرجي ثواب الله في عدد الخطا)\nال وأقبل قاص المصر فقال له خالد أكانت هذه تروح إليك قال لا وما مثلها يروح إلي قال خذ بيدها فهي لك ومولاها بالباب فسأل عنها فقيل وهبها للقاص فتحمل عليه بأشراف الكوفة فلم يرددها حتى اشتراها منه بمائتي دينار\nوقال المدائني قال خالد في خطبته والله ما إمارة العراق مما يشرفني فبلغ ذلك هشاما فغاظه جدا وكتب إليه بلغني يا بن النصرانية أنك تقول إن إمارة العراق ليست مما يشرفك صدقت والله ما شيء يشرفك وكيف تشرف وأنت دعي إلى بجيلة القبيلة القليلة الذليلة أما والله إني لأظن أن أول ما يأتيك ضغن من قيس فيشد يديك إلى عنقك","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":7,"spl":"لقب هشاما بابن الحمقاء — عرف ببخله الشديد — كان يلحن في خطبه","tags":[],"loc":3607},
{"id":"b268-20","bab":"الجزء 22","sec":"هشام يعزله ويعذبه — أخباره مع عمر بن أبي ربيعة","page":"ج22 ص31 – ج22 ص32","text":"وقال المدائني حدثني شبيب بن شيبة عن خالد بن صفوان بن الأهتم\nقال لم تزل أفعال خالد به حتى عزله هشام وعذبه وقتل ابنه يزيد بن خالد فرأيت في رجله شريطا قد شد به والصبيان يجرونه فدخلت إلى هشام يوما فحدثته وأطلت فتنفس ثم\nقال يا خالد رب خالد كان أحب إلي قربا وألذ عندي حديثا منك قال يعني خالدا القسري فانتهزتها ورجوت أن أشفع له فتكون لي عند خالد يد فقلت يا أمير المؤمنين فما يمنعك من استئناف الصنيعة عنده فقد أدبته بما فرط منه فقال هيهات إن خالدا أوجف فأعجف وأدل فأمل وأفرط في الإساءة فأفرطنا في المكافأة فحلم الأديم ونغل الجرح وبلغ السيل الزبى والحزام الطبيين فلم يبق فيه مستصلح ولا للصنيعة عنده موضع عد إلى حديثك\nفأما أخباره في تخنثه وإرسال عمر بن أبي ربيعة إياه إلى النساء فأخبرني به علي بن صالح بن الهيثم عن أبي هفان عن إسحاق بن إبراهيم الموصلي عن عثمان بن إبراهيم الحاطبي وأخبرني الحرمي بن أبي العلاء قال حدثني الزبير بن بكار قال حدثني محمد بن الحارث بن سعد السعيدي عن إبراهيم بن قدامة الحاطبي عن أبيه واللفظ لعلي بن صالح في خبره قالا قال الحاطبي\nأتيت عمر بن أبي ربيعة بعد أن نسك بسنين فانتظرته في مجلس قومه حتى إذا تفرق القوم دنوت منه ومعي صاحب لي فقال لي صاحبي هل لك في أن تريغه عن الغزل فننظر هل بقي منه شيء عنده فقلت له دونك فقال يا أبا الخطاب أحسن والله ريسان العذري قاتله الله قال وفيم أحسن قلت حيث يقول\n(لو جز بالسيف رأسي في مودتها ... لمال لا شك يهوي نحوها راسي)\nقال نعم أحسن فقلت يا أبا الخطاب وأحسن والله تحية بن جنادة العذري قال في ماذا قلت حيث يقول\n(سرت لعينيك سلمى بعد مغفاها ... فبت مستوهنا من بعد مسراها)\n(فقلت أهلا وسهلا من هداك لنا ... إن كنت تمثالها أو كنت إياها)\nفي رواية الزبير خاصة\n(تأتي الرياح التي من نحو أرضكم ... حتى أقول دنت منا برياها)\n(وقد تراخت بها عنا نوى قذف ... هيهات مصبحها من بعد ممساها)\n(من حبها أتمنى أن يلاقيني ... من نحو بلدتها ناع فينعاها)\n(كيما أقول فراق لا لقاء له ... وتضمر اليأس نفسي ثم تسلاها)\n(ولو تموت لراعتني وقلت لها ... يا بؤس للدهر ليت الدهر أبقاها)\nيروي\n(لراعتني منيتها وقلت يا بؤس ليت الدهر أبقاها ... )\nضحك عمر ثم قال يا ويحه أحسن والله لقد هيجتما علي ما\nكان ساكنا مني فلأحدثنكما حديثا حلوا بينا أنا أول أعوامي جالس إذا بخالد الخريت قال مررت بأربع نسوة قبيل يردن ناحية كذا وكذا من مكة لم أر مثلهن قط فيهن هند فهل لك أن تأتيهن متنكرا فتسمع من حديثهن ولا يعلمن فقلت وكيف لي بأن يخفى ذلك\nقال تلبس لبسة الأعراب ثم تقعد على قعود كأنك تنشد ضالة فلا يشعرن حتى تهجم عليهن قال فجلست على قعود ثم أتيتهن فسلمت عليهن فآنسنني وسألنني أن أنشدهن فأنشدتهن لكثير وجميل وغيرهما وقلن يا أعرابي ما أملحك لو نزلت فتحدثت معنا يومنا هذا فإذا أمسيت انصرفت فأنخت قعودي وجلست معهن فحدثتهن وأنشدتهن فدنت هند فمدت يدها فجذبت عمامتي فألقتها عن رأسي ثم قالت تالله لظننت أنك خدعتنا نحن والله خدعناك أرسلنا إليك خالدا الخريت في إتياننا بك على أقبح هيئتك ونحن على أحسن هيئتنا ثم أخذن بنا في الحديث فقالت إحداهن يا سيدي لو رأيتني منذ أيام وأصبحت عند أهلي فأدخلت رأسي في جيبي فنظرت إلى حري فرأيته ملء العس والقس فصحت يا عمراه فصحت لبيك لبيك ولم أزل معهن في أحسن وقت إلى أن أمسينا فتفرقنا عن أنعم عيش فذلك حين أقول\n(ألم تعرف الأطلال والمتربعا ... ببطن حليات دوارس بلقعا)\nوذكر الأبيات انقضت أخبار خالد لعنة الله عليه أبدا\n(أنائل ما رؤيا زعمت رأيتها ... لنا عجب لو أن رؤياك تصدق)\n(أنائل ما للعيش بعدك لذة ... ولا مشرب نلقاه إلا مرنق)\n(أنائل إني والذي أنا عبده ... لقد جعلت نفسي من البين تشفق)\n(لعمرك إن البين منك يشوقني ... وبعض بعاد البين والنأي أشوق)\nلشعر لصخر بن الجعد الخضري أخبرنا بذلك محمد بن مزيد عن الزبير بن بكار أن عمه أنشده هذه القصيدة لصخر بن الجعد الخضري وأنا أذكرها بعقب أخبار صخر ومن الناس من يروي هذه الأبيات لجميل ولم يأت ذلك من وجه يصح والزبير أعلم بأشعار الحجازيين والغناء لعريب خفيف ثقيل عن الهشامي وفيه لابن المكي ثقيل أول بالوسطى عن عمرو","topic":"أخبار خالد بن عبد الله نسبه","topicNo":268,"sp":8,"spl":"هشام يعزله ويعذبه — أخباره مع عمر بن أبي ربيعة","tags":["الحب والغزل"],"song":1,"loc":3608,"partial":1},
{"id":"b269-2","bab":"الجزء 22","sec":"أخبار صخر بن الجعد ونسبه — خبره مع محبوبته كأس","page":"ج22 ص35 – ج22 ص36","text":"صخر بن الجعد الخضري والخضر ولد مالك بن طريف بن محارب بن خصفة بن قيس بن عيلان بن مضر وصخر أحد بني جحاش بن سلمة بن ثعلبة بن مالك بن طريف قال وسمي ولد مالك بن طريف الخضر لسوادهم وكان مالك شديد الأدمة وخرج ولده إليه فقيل لهم الخضر والعرب تسمي الأسود الأخضر وهو شاعر فصيح من مخضرمي الدولتين الأموية والعباسية وقد كان يعرض لابن ميادة لما انقضى ما بينه وبين حكم الخضري من المهاجاة ورام أن يهاجيه فترفع ابن ميادة عنه\nأخبرني بخبره علي بن سليمان الأخفش عن هارون بن محمد بن عبد الملك الزيات عن الزبير بن بكار مجموعا وأخبرني بأخبار له متفرقة\nالحرمي بن أبي العلاء عن الزبير بن بكار وحدثني بها غيرهما من غير رواية الزبير فذكرت كل شيء من ذلك مفردا ونسبته إلى راويه قال الزبير فيما رواه هارون عنه\nحدثني من أثق به عن عبد الرحمن بن الأحول بن الجون قال كان صخر بن الجعد مغرما بكأس بنت بجير بن جندب وكان يشبب بها فلقيه أخوها وقاص وكان شجاعا فقال له يا صخر إنك تتسبب بابنة عمك وشهرتها ولعمري ما بها عنك مذهب ولا لنا عنك مرغب فإن كانت لك فيها حاجة فهلم أزوجكها وإن لم تكن لك فيها حاجة فلا أعلمن ما عرضت لها بذكر ولا أسمعنه منك فأقسم بالله لئن فعلت ذلك ليخالطنك سيفي فقال له بل والله إن لي لأشد الحاجة إليها فوعده موعدا وخرج صخر لموعده حتى نزل بأبيات القوم فنزل منزل الضيف فقام وقاص فذبح وجمع أصحابه وأبطأ صخر عنهم فلما رأى ذلك وقاص بعث إليه أن هلم لحاجتك فأبطأ ورجع الرسول فقال مثل قوله فغضب وعمد إلى رجل من الحي ليس يعدل بصخر يقال له حصن وهو مغضب لما صنع فحمد الله وأثنى عليه وزوجه كأس وافترق القوم ومروا بصخر فأعلموه تزويج كأس بحصن فرحل عنهم من تحت الليل واندفع يهجوها بالأبيات التي قذفها فيها فيما قذفها وذلك قوله حين يقول\n(وأنكحها حصنا ليطمس حملها ... وقد حملت من قبل حصن وجرت)\nي زادت على تسعة أشهر قال وترافع القوم إلى المدينة وأميرها يومئذ طارق مولى عثمان قال فتنازعوا إليه ومعهم يومئذ رجل يقال له حزم وكان من أشد الناس على صخر شرا قال وفيه يقول صخر\n(كفى حزنا لو يعلم الناس أنني ... أدافع كأسا عند أبواب طارق)\n(أتنسين أياما لنا بسويقة ... وأيامنا بالجزع جزع الخلائق)\n(ليالي لا نخشى انصداعا من الهوى ... وأيام حزم عندنا غير لائق)\n(إذا قلت لا تفشي حديثي تعجرفت ... زيادا لودها هنا غير صادق)\nال فأقاموا عليه البينة بقذف كأس فضرب الحد وعاد إلى قومه وأسف على ما فاته من تزويج كأس فطفق يقول فيها الشعر","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":0,"spl":"أخبار صخر بن الجعد ونسبه — خبره مع محبوبته كأس","tags":["الحب والغزل","المديح"],"loc":3609},
{"id":"b269-3","bab":"الجزء 22","sec":"قصيدته في كأس","page":"ج22 ص38","text":"قال الزبير فأنشدني عمي وغيره لصخر قوله\n(لقد عاود النمس الشقية عيدها ... نعم إنه قد عاد نحسا سعودها)\n(وعاوده من حب كأس ضمانة ... على النأي كانت هيضة تستقيدها)\n(وأنى ترجيها وأصبح وصلها ... ضعيفا وأمست همه لا يكيدها)\n(وقد مر عصر وهي لا تستزيدني ... لما استودعت عندي ولا أستزيدها)\n(فما زلت حتى زلت النعل زلة ... برجلك في زوراء وعث صعودها)\n(ألا قل لكأس إن عرضت لبيتها ... فأين بكا عيني وأين قصيدها)\n(لعل البكا يا كأس إن نفع البكا ... يقرب دنيانا لنا فيعيدها)\n(وكانت تناهت لوعة الود بيننا ... فقد أصبحت يبسا وأذبل عودها)\nيروى وقد ذاء عودها يقال ذبل وذأى وذوى بمعنى واحد\n(ليالي ذات الرمس لا زال هيجها ... جنوبا ولا زالت سحاب تجودها)\n(وعيش لنا في الدهر إذ كان قلبه ... يطيب لديه بخل كأس وجودها)\n(تذكرت كأسا إذ سمعت حمامة ... بكت في ذرا نخل طوال جريدها)\n(دعت ساق حر فاستجبت لصوتها ... مولهة لم يبق إلا شريدها)\n(فيا نفس صبرا كل أسباب واصل ... ستنمي لها أسباب هجر تبيدها)\nال أبو الحسن الأخفش ستنمي لها أسباب صرم تبيدها أجود\n(وليل بدت للعين نار كأنها ... سنا كوكب للمستبين خمودها)\n(فقلت عساها نار كأس وعلها ... تشكى فأمضي نحوها وأعودها)\n(فتسمع قولي قبل حتف يصيدني ... تسر به أو قبل حتف يصيدها)\n(كأن لم نكن يا كأس إلفى مودة ... إذ الناس والأيام ترعى عهودها)\nأخبرني عبد الله بن مالك النحوي قال حدثنا محمد بن حبيب قال لما ضرب صخر بن الجعد الحد لكأس وصارت إلى زوجها ندم على ما فرط منه واستحيا من الناس للحد الذي ضربه فلحق بالشام فطالت غيبته بها ثم عاد فمر بنخل كان لأهله ولأهل كأس فباعوه وانتقلوا إلى الشام فمر بها صخر ورأى المبتاعين لها يصرمونها فبكى عند ذلك بكاء شديدا وأنشأ يقول\n(مررت على خيمات كأس فأسبلت ... مدامع عيني والرياح تميلها)\n(وفي دارهم قوم سواهم فأسبلت ... دموع من الأجفان فاض مسيلها)\n(كذاك الليالي ليس فيها بسالم ... صديق ولا يبقى عليها خليلها)\nقال وهو بالشام\n(ألا ليت شعري هل تغير بعدنا ... عن العهد أم أمسى على حاله نجد)\n(وعهدي بنجد منذ عشرين حجة ... ونحن بدنيا ثم لم نلقها بعد)\n(به الخوصة الدهماء تحت ظلالها ... رياض بها الحوذان والنفل الجعد)\nقال ومر على غدير كانت كأس تشرب منه ويحضره أهلها ويجتمعون عليه فوقف طويلا عليه يبكي وكان يقال لذلك الغدير جنان فقال صخر\n(بليت كما يبلى الرداء ولا أرى ... جنانا ولا أكناف ذروة تخلق)\n(ألوي حيازيمي بهن صبابة ... كما تتلوى الحية المتشرق)","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":1,"spl":"قصيدته في كأس — شعره في رثاء كأس","tags":["الحب والغزل","الخمر","الموت"],"loc":3610},
{"id":"b269-4","bab":"الجزء 22","sec":"شعره في رثاء كأس","page":"ج22 ص41","text":"أخبرني عبد الله بن مالك عن محمد بن حبيب قال قال السعيدي حدثني سبرة مولى يزيد بن العوام قال كان صخر بن الجعد المحاربي خدنا لعوام بن عقبة وكان عوام يهوى امرأة من قومه يقال لها سوداء فماتت فرثاها فلما سمع صخر بن الجعد المرثية قال وددت أن أعيش حتى تموت كأس فأرثيها فماتت كأس فقال\n(على أم داود السلام ورحمة ... من الله يجري كل يوم بشيرها)\n(غداة غدا الغادون عنها وغودرت ... بلماعة القيعان يستن مورها)\n(وغيبت عنها يوم ذاك وليتني ... شهدت فيحوي منكبي سريرها)\nيروى فيعلو منكبي\n(نزت كبدي لما أتاني نعيها ... فقلت أدان صدعها فمطيرها)\nخبرني الحرمي بن أبي العلاء قال حدثني الزبير قال حدثني خالد بن الوضاح قال قال عبد الأعلى بن عبيد بن محمد بن صفوان الجمحي لعبد الله بن مصعب سألني أمير المؤمنين اليوم في موكبه من الذي يقول\n(ألا يا كأس قد أفنيت شعري ... فلست بقائل إلا رجيعا)\nلم أدر لمن الشعر فقال عبد الله بن مصعب هو لصخر الخضري وأنشد باقي الأبيات وهي\n(ترجي أن تلاقي آل كأس ... كما يرجو أخو السنة الربيعا)\n(فلست بنائم إلا بحزن ... ولا مستيقظا إلا مروعا)\n(فإنك لو نظرت إذا التقينا ... إلى كبدي رأيت بها صدوعا)","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":1,"spl":"قصيدته في كأس — شعره في رثاء كأس","tags":["الجواري والنساء"],"loc":3611},
{"id":"b269-5","bab":"الجزء 22","sec":"ندمه بعد أن تزوجت كأس","page":"ج22 ص42","text":"قال ابن حبيب في رواية عبد الله بن مالك لما زوجت كأس جزع صخر بن الجعد لما فرط منه وندم وأسف وقال في ذلك\n(هنيئا لكأس قطعها الحبل بعدما ... عقدنا لكأس موثقا لا نخونها)\n(وإشماتها الأعداء لما تألبوا ... حوالي واشتدت علي ضغونها)\n(فإن حراما أن أخونك ما دعا ... بيليل قمري الحمام وجونها)\n(وقد أيقنت نفسي لقد حيل دونها ... ودونك لو يأتي بيأس يقينها)\n(ولكن أبت لا تستفيق ولا ترى ... عزاء ولا مجلود صبر يعينها)\n(لو أنا إذ الدنيا لنا مطمئنة ... دحا ظلها ثم ارجحنت غصونها)\n(لهونا ولكنا بغرة عيشنا ... عجبنا لدنيانا فكدنا نعنيها)\n(وكنا إذا نحن التقينا وما نرى ... لعينين إلا من حجاب يصونها)\n(أخذنا بأطراف الأحاديث بيننا ... وأوساطها حتى تمل فنونها)\nال ابن حبيب أرسلت كأس بعد أن زوجت إلى صخر بن الجعد تخبره أنها رأته فيما يرى النائم كأنه يلبسها خمارا وأن ذلك جدد لها شوقا إليه وصبابة فقال صخر\n(أنائل ما رؤيا زعمت رأيتها ... لنا عجب لو أن رؤياك تصدق)\n(أنائل لولا الود ما كان بيننا ... نضا مثل ما ينضو الخضاب فيخلق)","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":2,"spl":"ندمه بعد أن تزوجت كأس — جاريته سمحاء توقع به وتخدعه","tags":["الحب والغزل","الموت"],"loc":3612},
{"id":"b269-6","bab":"الجزء 22","sec":"خبره مع سيار التاجر","page":"ج22 ص43","text":"أخبرنا حبيب بن نصر قال حدثنا عبد الله بن شبيب قال حدثني محمد بن عبد الله البكري قال قدم صخر بن الجعد الخضري المدينة فأتى تاجرا من تجارها يقال له سيار فابتاع منه برا وعطرا وقال تأتينا غدوة فأقضيك وركب من تحت\nليلته فخرج إلى البادية فلما أصبح سيار سأل عنه فعرف خبره فركب في جماعة من أصحابه في طلبه حتى أتوا بئر مطلب وهي على سبعة أميال من المدينة وقد جهدوا من الحر فنزلوا عليها فأكلوا تمرا كان معهم وأراحوا دوابهم وسقوها حتى إذ برد النهار انصرفوا راجعين وبلغ الخبر صخر بن الجعد فقال\n(أهون علي بسيار وصفوته ... إذا جعلت صرارا دون سيار)\n(إن القضاء سيأتي دونه زمن ... فاطو الصحيفة واحفظها من العار)\n(يسائل الناس هل أحسستم جلبا ... محاربيا أتى من نحو أظفار)\n(وما جلبت إليهم غير راحلة ... وغير رحل وسيف جفنة عار)\n(وما أريت لهم إلا لأدفعهم ... عني ويخرجني نقضي وإمراري)\n(حتى استغاثوا بأورى بئر مطلب ... وقد تحرق منهم كل تمار)\n(وقال أولهم نصحا لآخرهم ... ألا ارجعوا واتركوا الأعراب في النار)","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":2,"spl":"ندمه بعد أن تزوجت كأس — جاريته سمحاء توقع به وتخدعه","tags":["السفر والحج","الوصف والطبيعة","الرواية والكتابة"],"loc":3613},
{"id":"b269-7","bab":"الجزء 22","sec":"جاريته سمحاء توقع به وتخدعه","page":"ج22 ص44","text":"أخبرني عبد الله بن مالك عن محمد بن حبيب قال حدثنا ابن\nالأعرابي قال كان الجعد المحاربي أبو صخر بن الجعد قد عمر حتى خرف وكان يكنى أبا الصموت وكانت له وليدة يقال لها سمحاء فقالت له يوما يا أبا الصموت زعم بنوك أنك إن مت قتلوني\nقال ولم قالت مالي إليهم ذنب غير حبي لك فأعتقها على أن تكون معه فمكثت يسيرا ثم قالت له يا أبا الصموت هذا عرابة من أهل المعدن يخطبني\nقال أين هذا مما قلت لي قالت إنه ذو مال وإنما أردت ماله لك قال فأتني به فأتته فزوجه إياها فولدت له أولادا وقوته بما كانت تصيبه من الجعد وكانت تأتي الجعد في أيام فتخضب رأسه ثم قطعته فأنشأ الجعد يقول\n(أمسى عرابة ذا مال وذا ولد ... من مال جعد وجعد غير محمود)\n(تظل تنشقه الكافور متكئا ... على السرير وتعطيني على العود)\nقال والجعد هو القائل لامرأته\n(تعالجني أم الصموت كأنما ... تداوي حصانا أوهن العظم كاسره)\n(فلا تعجبي أم الصموت فإنه ... لكل جواد معثر هو عاثره)\n(وقد كنت أصطاد الظباء موطئا ... وأضرب رأس القرن والرمح شاجره)\n(فأصبحت مثل العش طارت فراخه ... وغودر في رأس الهشيمة سائره)","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":2,"spl":"ندمه بعد أن تزوجت كأس — جاريته سمحاء توقع به وتخدعه","tags":["الرواية والكتابة"],"loc":3614},
{"id":"b269-8","bab":"الجزء 22","sec":"أولاده يتخلون عنه ويقتسمون أمواله","page":"ج22 ص46","text":"فلما كبر حمله بنوه فأتوا به مكة وقالوا له تعبد ها هنا ثم اقتسموا المال وتركوا له منه ما يصلحه فقال\n(ألا أبلغ بني جعد رسولا ... وإن حالت جبال الغور دوني)\n(فلم أر معشرا تركوا أباهم ... من الآفاق حيث تركتموني)\n(فإني والروافض حول جمع ... ومحطمهن من حصبا الحجون)\n(لو أني ذو مدافعة وحولي ... كما قد كنت أحيانا كموني)\n(إذا لمنعتكم مالي ونفسي ... بنصل السيف أو لقتلتموني)\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا محمد بن عبد الله بن عثمان البكري عن عروة بن زيد الخضري عن أبيه قال كنت في ركب فيهم صخر بن الجعد ودرن مولى الخضريين معنا ونحن نريد خيبر فنزلنا منزلا تعشينا فيه فهيجنا إبل صخر فلما ركبنا ساق بنا واندفع يرجز ويقول\n(لقد بعثت حاديا قراصفا ... )\nفردده قطعا من الليل لا ينفده ولا يقول غيره ثم قال لنا إني نسيت عقالا فرجع يطلبه في المتعشى ونزل درن يسوق بالقوم فارتجز درن ببيت صخر وقال\n(لقد بعثت حاديا قراصفا ... من منزل رحلت عنه آنفا)\n(يسوق خوصا رجفا حواجفا ... مثل القسي تقذف المقاذفا)\n(حتى ترى الرباعي العتارفا ... من شدة السير يزجى واجفا)\nال فأدركه صخر وهو في ذلك فقال له يا بن الخبيثة أتجترئ على أن تنفذ بيتا أعياني فقاتله فضربه حتى نزلنا ففرقنا بينهما\n(إذا سرها أمر وفيه مساءتي ... قضيت لها فيما تحب على نفسي)\n(وما مر يوم أرتجي منه راحة ... فأذكره إلا بكيت على أمسي)\nلشعر لأبي حفص الشطرنجي والغناء لإبراهيم ثقيل أول بالوسطى عن عمرو","topic":"أخبار صخر بن الجعد ونسبه","topicNo":269,"sp":3,"spl":"أولاده يتخلون عنه ويقتسمون أمواله","tags":["اللهو والمزاح"],"song":1,"loc":3615,"partial":1},
{"id":"b270-2","bab":"الجزء 22","sec":"أخبار أبي حفص الشطرنجي ونسبه — انقطاعه إلى علية بنت المهدي","page":"ج22 ص47 – ج22 ص48","text":"أبو حفص عمر بن عبد العزيز مولى بني العباس وكان أبوه من موالي المنصور فيما يقال وكان اسمه اسما أعجميا فلما نشأ أبو حفص وتأدب غيره وسماه عبد العزيز أخبرني بذلك عمي عن أحمد بن الطيب عن جماعة من موالي المهدي ونشأ أبو حفص في دار المهدي ومع أولاد مواليه وكان كأحدهم وتأدب وكان لاعبا بالشطرنج مشغوفا به فلقب به لغلبته عليه\nفلما مات المهدي انقطع إلى عليه وخرج معها لما زوجت وعاد معها لما عادت إلى القصر وكان يقول لها الأشعار فيما تريده من الأمور بينها وبين إخوتها وبني أخيها من الخلفاء فتنتحل بعض ذلك وتترك بعضه\nومما ينسب إليها من شعره ولها فيه غناء وقد ذكرنا ذلك في أغانيها وأخبارها\n(تحبب فإن الحب داعية الحب ... )\nهو صوت مشهور لها حدثني الحسن بن علي الخفاف قال حدثني أحمد بن الطيب السرخسي قال حدثني الكندي عن محمد بن الجهم البرمكي قال رأيت أبا حفص الشطرنجي الشاعر فرأيت منه إنسانا يلهيك حضوره عن كل غائب وتسليك مجالسته عن هموم المصائب قربة عرس وحديثه أنس جده لعب ولعبه جد دين ماجد إن لبسته على ظاهره لبست موموقا لا تمله وإن تتبعته لتستبطن خبرته وقفت على مروة لا تطير الفواحش بجنباتها وكان فيما علمته أقل ما فيه الشعر وهو الذي يقول\n(تحبب فإن الحب داعية الحب ... وكم من بعيد الدار مستوجب القرب)\n(إذا لم يكن في الحب عتب ولا رضا ... فأين حلاوات الرسائل والكتب)\n(تفكر فإن حدثت أن أخا هوى ... نجا سالما فارج النجاة من الكرب)\n(وأطيب أيام الهوى يومك الذي ... تروع بالتحريش فيه وبالعتب)\nال وفي هذه الأبيات غناء لعلية بنت المهدي وكانت تأمره أن يقول الشعر في المعاني التي تريدها فيقولها وتغني فيها قال وأنشدني لأبي حفص أيضا\n\n(عرضن للذي تحب بحب ... ثم دعه يروضه إبليس)\n(فلعل الزمان يدنيك منه ... إن هذا الهوى جليل نفيس)\n(صابر الحب لا يصرفك فيه ... من حبيب تجهم وعبوس)\n(وأقل اللجاج واصبر على الجهد ... فإن الهوى نعيم وبوس)\nي هذه الأبيات للمسدود هزج ذكره لي جحظة وغيره عنه وأما قوله\n(تحبب فإن الحب داعية الحب ... )\nقد مضت نسبته في أخبار علية","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":0,"spl":"أخبار أبي حفص الشطرنجي ونسبه — انقطاعه إلى علية بنت المهدي","tags":["الحب والغزل"],"song":2,"loc":3616,"partial":1},
{"id":"b270-3","bab":"الجزء 22","sec":"ماردة الجارية تأمره أن يجيب الرشيد على رسالته","page":"ج22 ص50","text":"أخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك وأخبرني به محمد بن خلف بن المرزبان قال حدثني أبو العباس الكاتب قال\nكان الرشيد يحب ماردة جاريته وكان خلفها بالرقة فلما قدم إلى مدينة السلام اشتاقها فكتب إليها\n\n(سلام على النازح المغترب ... تحية صب به مكتئب)\n(غزال مراتعه بالبليخ ... إلى دير زكى فقصر الخشب)\n(أيا من أعان على نفسه ... بتخليفه طائعا من أحب)\n(سأستر والستر من شيمتي ... هوى من أحب بمن لا أحب)\nلما ورد كتابه عليها أمرت أبا حفص الشطرنجي صاحب علية فأجاب الرشيد عنها بهذه الأبيات فقال\n(أتاني كتابك يا سيدي ... وفيه العجائب كل العجب)\n(أتزعم أنك لي عاشق ... وأنك بي مستهام وصب)\n(فلو كان هذا كذا لم تكن ... لتتركني نهزة للكرب)\n(وأنت ببغداد ترعى بها ... نبات اللذاذة مع من تحب)\n(فيا من جفاني ولم أجفه ... ويا من شجاني بما في الكتب)\n(كتابك قد زادني صبوة ... وأسعر قلبي بحر اللهب)\n(فهبني نعم قد كتمت الهوى ... فكيف بكتمان دمع سرب)\n(ولولا اتقاؤك يا سيدي ... لوافتك بي الناجيات النجب)\nلما قرأ الرشيد كتابها أنفذ من وقته خادما على البريد حتى حدرها\nإلى بغداد في الفرات وأمر المغنيين جميعا فغنوا في شعره قال الأصبهاني فممن غنى فيه إبراهيم الموصلي غنى فيه لحنين أحدهما ماخوري والآخر ثاني ثقيل عن الهشامي وغنى يحيى بن سعد بن بكر بن صغير العين فيه رملا ولابن جامع فيه رمل بالبنصر ولفليح بن العوراء ثاني ثقيل بالوسطى وللمعلى خفيف رمل بالوسطى ولحسين بن محرز هزج بالوسطى ولأبي زكار الأعمى هزج بالبنصر هذه الحكايات كلها عن الهشامي\nوقال كان المختار في هذه الألحان كلها عند الرشيد الذي اشتهاه منها وارتضاه لحن سليم أخبرني جعفر بن قدامة بن زياد الكاتب قال حدثني محمد بن يزيد النحوي\nقال حدثني جماعة من كتاب السلطان أن الرشيد غضب على علية بنت المهدي فأمرت أبا حفص الشطرنجي شاعرها أن يقول شعرا يعتذر فيه عنها إلى الرشيد ويسأله الرضا عنها فيستعطفه لها فقال\n(لو كان يمنع حسن العقل صاحبه ... من أن يكون له ذنب إلى أحد)\n(كانت علية أبرأ الناس كلهم ... من أن تكافا بسوء آخر الأبد)\n(مالي إذا غبت لم أذكر بواحدة ... وإن سقمت فطال السقم لم أعد)\n(ما أعجب الشيء ترجوه فتحرمه ... قد كنت أحسب أني قد ملأت يدي)\nفأتاها بالأبيات فاستحسنتها وغنت فيها وألقت الغناء على جماعة من جواري الرشيد فغنينه إياه في أول مجلس فيه معهن فطرب طربا شديدا وسألهن عن القصة فأخبرنه بها فبعث إليها فحضرت فقبل رأسها واعتذرت فقبل عذرها وسألها إعادة الصوت فأعادته عليه فبكى وقال لا جرم أني لا أغضب أبدا عليك ما عشت","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":1,"spl":"ماردة الجارية تأمره أن يجيب الرشيد على رسالته — قال في دنانير بيتين فاستحق مائتي دينار","tags":["الحب والغزل"],"song":2,"loc":3617},
{"id":"b270-4","bab":"الجزء 22","sec":"قال في دنانير بيتين فاستحق مائتي دينار","page":"ج22 ص52","text":"حدثني محمد بن يحيى الصولي قال حدثنا الحسين بن يحيى عن عمرو بن بانة قال دخل أبو حفص الشطرنجي على يحيى بن خالد وعنده ابن جامع وهو يلقي على دنانير صوتا أمره يحيى بإلقائه عليها وقال لأبي حفص قل في دنانير بيتين يغني فيهما ابن جامع ولك بكل بيت مائة دينار إن جاءت كما أريد فقال أبو حفص\n(أشبهك المسك وأشبهته ... قائمة في لونه قاعده)\n(لا شك إذ لونكما واحد ... أنكما من طينة واحده)\nال فأمر له يحيى بمائة دينار وغنى فيهما ابن جامع قال الأصبهاني لحن ابن جامع في هذين البيتين هزج أخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه قال","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":1,"spl":"ماردة الجارية تأمره أن يجيب الرشيد على رسالته — قال في دنانير بيتين فاستحق مائتي دينار","tags":["اللهو والمزاح","الرواية والكتابة"],"song":1,"loc":3618},
{"id":"b270-5","bab":"الجزء 22","sec":"عتابه ابن الرشيد لأنه لم يعده في مرضه","page":"ج22 ص53","text":"كان أبو حفص الشطرنجي ينادم أبا عيسى بن الرشيد ويقول له الشعر\nفينتحله ويفعل مثل ذلك بأخيه صالح وأخته وكذلك بعلية عمتهم وكان بنو الرشيد جميعا يزورونه ويأنسون به فمرض فعادوه جميعا سوى أبي عيسى فكتب إليه\n(إخاء أبي عيسى إخاء ابن ضرة ... وودي ود لابن أم ووالد)\n(ألم يأته أن التأدب نسبة ... تلاصق أهواء الرجال الأباعد)\n(فما باله مستعذبا من جفائنا ... موارد لم تعذب لنا من موارد)\n(أقمت ثلاثا حلف حمى مضرة ... فلم أره في أهل ودي وعائدي)\n(سلام هي الدنيا قروض وإنما ... أخوك مديم الوصل عند الشدائد)\nدثني جعفر بن الحسين قال حدثني ميمون بن هارون قال حدثنا أبي عن أبي حفص الشطرنجي قال قال لي الرشيد يوما يا حبيبي لقد أحسنت ما شئت في بيتين قلتهما قلت ما هما يا سيدي فمن شرفهما استحسانك لهما فقال قولك\n(لم ألق ذا شجن يبوح بحبه ... إلا حسبتك ذلك المحبوبا)\n(حذرا عليك وإنني بك واثق ... ألا ينال سواي منك نصيبا)\nقلت يا أمير المؤمنين ليسا لي هما للعباس بن الأحنف فقال\nصدقك والله أعجب إلي وأحسن منهما بيتاك حيث تقول\n(إذا سرها أمر وفيه مساءتي ... قضيت لها فيما تريد على نفسي)\n(وما مر يوم أرتجي فيه راحة ... فأذكره إلا بكيت على أمسي)\nي البيتين الأولين اللذين للعباس بن الأحنف ثقيل لإبراهيم الموصلي وفيهما لابن جامع رمل عن الهشامي الروايتان جميعا لعبد الرحمن وفي أبيات أبي حفص الأخيرة لحن من كتاب إبراهيم غير مجنس","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":2,"spl":"عتابه ابن الرشيد لأنه لم يعده في مرضه — دمن الجارية تسرق لحنا من إسحاق وهو سكران","tags":[],"song":1,"loc":3619},
{"id":"b270-6","bab":"الجزء 22","sec":"رثى نفسه قبل أن يموت","page":"ج22 ص55","text":"أخبرني محمد بن يحيى الصولي قال حدثني الحسين بن يحيى قال حدثني عبد الله بن الفضل قال دخلت على أبي حفص الشطرنجي شاعر علية بنت المهدي أعوده في علته التي مات فيها قال فجلست عنده فأنشدني لنفسه\n(نعى لك ظل الشباب المشيب ... ونادتك باسم سواك الخطوب)\n(فكن مستعدا لداعي الفناء ... فإن الذي هو آت قريب)\n(ألسنا نرى شهوات النفوس ... تفنى وتبقى عليها الذنوب)\n(وقبلك داوى المريض الطبيب ... فعاش المريض ومات الطبيب)\n(يخاف على نفسه من يتوب ... فكيف ترى حال من لا يتوب)\nنى في الأول والثاني إبراهيم هزجا\nانقضت أخباره\n(أبى ليلي أن يذهب ... ونيط الطرف بالكوكب)\n(ونجم دونه النسران ... بين الدلو والعقرب)\n(وهذا الصبح لا يأتي ... ولا يدنو ولا يقرب)\nالشعر لأميمة بنت عبد شمس بن عبد مناف والغناء لأسحاق هزج بالوسطى","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":2,"spl":"عتابه ابن الرشيد لأنه لم يعده في مرضه — دمن الجارية تسرق لحنا من إسحاق وهو سكران","tags":[],"song":2,"loc":3620},
{"id":"b270-7","bab":"الجزء 22","sec":"دمن الجارية تسرق لحنا من إسحاق وهو سكران","page":"ج22 ص56","text":"أخبرنا محمد بن يحيى ومحمد بن جعفر النحوي قالا حدثنا محمد بن حماد قال التقيت مع دمن جارية إسحاق بن إبراهيم الموصلي يوما فقلت لها أسمعيني شيئا أخذته من إسحاق فقالت والله ما أحد من جواريه أخذ منه صوتا قط ولا ألقى علينا شيئا قط وإنما كان يأمر من أخذ منه من الرجال مثل مخارق وعلويه ووجه القرعة الخزاعي وجواري الحارث بن بسخنر أن يلقوا علينا ما يختارون من أغانيهم وأما عنه فما أخذت شيئا قط إلا ليلة فإنه انصرف من عند المعتصم وهو سكران فقال للخادم القيم على حرمة جئني بدمن فجاءني الخادم فدعاني فخرجت معه فإذا هو في البيت الذي ينام فيه وهو يصنع في هذا الشعر\n(أبى ليلي أن يذهب ... ونيط الطرف بالكوكب)\nهو يتزايد فيه ويقومه حتى استوى له ثم قام إلى عود مصلح معلق كان يكون في بيت منامه فأخذه فغنى الصوت حتى صح له واستقام عليه وأخذته عنه فلما فرغ منه\nقال أين دمن فقلت هو ذا أنا ها هنا فارتاع وقال مذ كم أنت ها هنا قلت مذ بدأت بالصوت وقد أخذته بغير حمدك فقال خذي العود فغنيه فأخذته فغنيته حتى فرغت منه وهو يكاد أن يتميز غيظا ثم\nقال قد بقي عليك فيه شيء كثير وأنا أصلحه لك فقلت أنا مستغنية عن إصلاحك فأصلحه لنفسك فاضطجع في فراشه ونام وانصرفت فمكث أياما إذا رآني قطب وجهه وهذا الشعر تقوله أميمة بنت عبد شمس بن عبد مناف ترثي به من قتل في حروب الفجار من قريش","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":2,"spl":"عتابه ابن الرشيد لأنه لم يعده في مرضه — دمن الجارية تسرق لحنا من إسحاق وهو سكران","tags":[],"loc":3621},
{"id":"b270-9","bab":"الجزء 22","sec":"ذكر الخبر في حروب الفجار وحروب عكاظ ونسب أميمة بنت عبد شمس — أول أمر الفجار","page":"ج22 ص58 – ج22 ص59","text":"أميمة بنت عبد شمس بن عبد مناف وأمها تفخر بنت عبيد بن رواس بن كلاب وكان عند حارثة بن الأوقص بن مرة بن هلال بن فالح بن ذكوان السلمي فولدت له أمية بن حارثة وكانت هذه الحرب بين قريش وقيس عيلان في أربعة أعوام متواليات ولم يكن لقريش في أولها مدخل ثم التحقت بها فأما الفجار الأول فكانت الحرب فيه ثلاثة أيام ولم تسم باسم لشهرتها وأما الفجار الثاني فإنه كان أعظمهما لأنهم استحلوا فيه الحرم وكانت أيامه يوم نخلة وهو الذي لم يشهده رسول الله منها وشهد سائرها وكان الرؤساء فيه حرب بن أمية في القلب وعبد الله بن جدعان وهشام بن المغيرة في المجنبتين ثم يوم شمطة ثم يوم\nالعبلاء ثم يوم عكاظ ثم يوم الحرة\nقال أبو عبيدة كان أول أمر الفجار أن بدر بن معشر الغفاري أحد بني غفار بن مالك بن ضمرة بن بكر بن عبد مناه بن كنانة كان رجلا منيعا مستطيلا بمنعته على من ورد عكاظ فاتخذ مجلسا بسوق عكاظ وقعد فيه وجعل يبذخ على الناس ويقول\n(نحن بنو مدركة بن خندف ... من يطعنوا في عينه لا يطرف)\n(ومن يكونوا قومه يغطرف ... كأنهم لجة بحر مسدف)\nبدر بن معشر باسط رجليه يقول أنا أعز العرب فمن زعم أنه أعز مني فليضرب هذه بالسيف فهو أعز مني فوثب رجل من بني نصر بن معاوية يقال له الأحمر بن مازن بن أوس بن النابغة فضربه بالسيف على ركبته فأندرها ثم قال خذها إليك أيها المخندف وهو ماسك سيفه وقام أيضا رجل من هوازن فقال\n(أنا ابن همدان ذوي التغطرف ... بحر بحور زاخر لم ينزف)\n(نحن ضربنا ركبة المخندف ... أذ مدها في أشهر المعرف)\nفي هذه الضربة أشعار لقيس كثيرة لا معنى لذكرها","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":3,"spl":"ذكر الخبر في حروب الفجار وحروب عكاظ ونسب أميمة بنت عبد شمس — أول أمر الفجار — اليوم الثالث","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3622},
{"id":"b270-10","bab":"الجزء 22","sec":"اليوم الثاني من أيام الفجار الأولى","page":"ج22 ص59","text":"ثم كان اليوم الثاني من أيام الفجار الأول وكان السبب في ذلك أن شبابا من قريش وبني كنانة كانوا ذوي غرام فرأوا امرأة من بني عامر جميلة وسيمة وهي جالسة بسوق عكاظ في درع وهي فضل عليها برقع لها وقد اكتنفها شباب من العرب وهي تحدثهم فجاء الشباب من بني كنانة وقريش فأطافوا بها وسألوها أن تسفر فأبت فقام أحدهم فجلس خلفها وحل طرف ردائها وشده إلى فوق حجزتها بشوكة وهي لا تعلم فلما قامت انكشف درعها عن دبرها فضحكوا وقالوا منعتنا النظر إلى وجهك وجدت لنا بالنظر إلى دبرك فنادت يا آل عامر فثاروا وحملوا السلاح وحملته كنانة واقتتلوا قتالا شديدا ووقعت بينهم دماء فتوسط حرب بن أمية واحتمل دماء القوم وأرضى بني عامر من مثلة صاحبتهم","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":3,"spl":"ذكر الخبر في حروب الفجار وحروب عكاظ ونسب أميمة بنت عبد شمس — أول أمر الفجار — اليوم الثالث","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"loc":3623},
{"id":"b270-11","bab":"الجزء 22","sec":"اليوم الثالث من أيام الفجار الأولى","page":"ج22 ص60","text":"ثم كان اليوم الثالث من الفجار الأول وكان سببه أنه كان لرجل من بني جشم بن بكر بن هوازن دين على رجل من بني كنانة فلواه به وطال\nاقتضاؤه إياه فلم يعطه شيئا فلما أعياه وافاه الجشمي في سوق عكاظ بقرد ثم جعل ينادي من يبيعني مثل هذا الرباح بما لي على فلان بن فلان الكناني من يعطيني مثل هذا بما لي على فلان بن فلان الكناني رافعا صوته بذلك فلما طال نداؤه بذلك وتعييره به كنانة مر به رجل منهم فضرب القرد بسيفه فقتله فهتف به الجشمي يا آل هوازن وهتف الكناني يا آل كنانة فتجمع الحيان فاقتتلوا حتى تحاجزوا ولم يكن بينهم قتلى ثم كفوا وقالوا أفي رباح تريقون دماءكم وتقتلون أنفسكم وحمل ابن جدعان ذلك في ماله بين الفريقين","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":3,"spl":"ذكر الخبر في حروب الفجار وحروب عكاظ ونسب أميمة بنت عبد شمس — أول أمر الفجار — اليوم الثالث","tags":[],"loc":3624},
{"id":"b270-12","bab":"الجزء 22","sec":"اليوم الأول من أيام الفجار الثاني","page":"ج22 ص61","text":"قال ثم كان يوم الفجار الثاني وأول يوم حروبه يوم نخلة وبينه وبين مبعث النبي ست وعشرون سنة وشهد النبي ذلك اليوم مع قومه وله أربع عشرة سنة وكان يناول عمومته النبل هذا قول أبي عبيدة\nوقال غيره بل شهدها وهو ابن ثمان وعشرين سنة قال أبو عبيدة كان الذي هاج هذه الحرب يوم الفجار الآخر أن البراض بن قيس بن رافع أحد بني ضمرة بن بكر بن عبد مناة بن كنانة كان سكيرا فاسقا خلعه قومه وتبرؤوا منه فشرب في بني الديل فخلعوه فأتى مكة وأتى قريشا فنزل على حرب بن أمية فحالفه فأحسن حرب جواره وشرب بمكة حتى هم حرب أن يخلعه فقال لحرب إنه لم يبق أحد ممن يعرفني إلا خلعني سواك وإنك إن خلعتني لم ينظر إلي أحد بعدك فدعني على حلفك وأنا خارج عنك فتركه وخرج فلحق بالنعمان بن المنذر بالحيرة\nوكان النعمان يبعث إلى سوق عكاظ في وقتها بلطيمة يجيزها له سيد مضر فتباع ويشترى له بثمنها الأدم والحرير والوكاء والحذاء والبرود من العصب والوشي والمسير والعدني وكانت سوق عكاظ في أول ذي القعدة فلا تزال قائمة يباع فيها ويشترى إلى حضور الحج وكان قيامها فيما بين النخلة والطائف عشرة أميال وبها نخل وأموال لثقيف فجهز النعمان لطيمة له\nوقال من يجيزها فقال البراض أنا أجيزها على بني كنانة فقال النعمان إنما أريد رجلا يجيزها على أهل نجد فقال عروة الرحال بن عتبة بن جعفر بن كلاب وهو يومئذ رجل من هوازن أنا أجيزها أبيت اللعن فقال له البراض من بني كنانة تجيزها يا عروة\nقال نعم وعلى الناس جميعا أفكلب خليع يجيزها قال ثم شخص بها وشخص البراض وعروة يرى مكانه لا يخشاه على ما صنع حتى إذا كان بين ظهري غطفان إلى جانب فدك بأرض يقال لها أوارة قريب من الوادي الذي يقال له تيمن نام عروة في ظل شجرة ووجد البراض غفلته فقتله وهرب في عضاريط الركاب فاستاق الركاب وقال البراض في ذلك\n(وداهية يهال الناس منها ... شددت لها بني بكر ضلوعي)\n(هتكت بها بيوت بني كلاب ... وأرضعت الموالي بالضروع)\n(جمعت لها يدي بنصل سيف ... أفل فخر كالجذع الصريع)\nقال أيضا في ذلك\n(نقمت على المرء الكلابي فخره ... وكنت قديما لا اقز فخارا)\n(علوت بحد السيف مفرق رأسه ... فأسمع أهل الواديين خوارا)\nال وأم عروة الرحال نفيرة بنت أبي ربيعة بن نهيك بن هلال بن عامر بن صعصعة فقال لبيد بن ربيعة يحض على الطلب بدمه\n(فأبلغ إن عرضت بني نمير ... وأخوال القتيل بني هلال)\n(بأن الوافد الرحال أضحى ... مقيما عند تيمن ذي الظلال)\nقال أبو عبيدة فحدثني أبو عمرو بن العلاء قال لقي البراض بشر بن أبي خازم فقال له هذه القلائص لك على أن تأتي حرب بن أمية وعبد الله بن جدعان وهشاما والوليد ابني المغيرة فتخبرهم أن البراض قتل عروة فإني أخاف أن يسبق الخبر إلى قيس أن يكتموه حتى يقتلوا به رجلا من قومك عظيما فقال له وما يؤمنك أن تكون أنت ذلك القتيل\nقال إن هوازن لا ترضى أن تقتل بسيدها رجلا خليعا طريدا من بني ضمرة قال ومر بهما الحليس بن يزيد أحد بني الحارث بن عبد مناة بن كنانة وهو يومئذ سيد الأحابيش من\nبني كنانة والأحابيش من بني الحارث بن عبد مناة بن كنانة وهو نفاثة بن الديل وبنو لحيان من خزاعة والقارة وهو أثيع بن الهون بن خزيمة وعضل بن دمس بن ملحم بن عائذ بن أثيع بن الهون كانوا تحالفوا على سائر بني بكر بن عبد مناة فقال لهم الحليس مالي أراكم نجيا فأخبروه الخبر ثم ارتحلوا وكتموا الخبر على اتفاق منهم\nقال وكانت العرب إذا قدمت عكاظ دفعت أسلحتها إلى ابن جدعان حتى يفرغوا من أسواقهم وحجهم ثم يردها عليهم إذا ظعنوا وكان سيدا حكيما مثريا من المال فجاءه القوم فأخبروه خبر البراض وقتله عروة وأخبروا حرب بن أمية وهشاما والوليد ابني المغيرة فجاء حرب إلى عبد الله بن جدعان فقال له احتبس قبلك سلاح هوازن فقال له ابن جدعان أبالغدر تأمرني يا حرب والله لو أعلم أنه لا يبقى منها سيف إلا ضربت به ولا رمح إلا طعنت به ما أمسكت منها شيئا ولكن لكم مائة درع ومائة رمح ومائة سيف في مالي تستعينون بها ثم صاح ابن جدعان في الناس من كان له قبلي سلاح فليأت وليأخذه فأخذ الناس أسلحتهم وبعث ابن جدعان وحرب بن أمية وهشام والوليد إلى أبي براء إنه قد كان بعد خروجنا حرب وقد خفنا تفاقم الأمر فلا تنكروا خروجنا وساروا","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":4,"spl":"اليوم الأول من أيام الفجار الثاني","tags":["الجواري والنساء"],"loc":3625},
{"id":"b270-13","bab":"الجزء 22","sec":"اليوم الأول من أيام الفجار الثاني","page":"ج22 ص61","text":"راجعين إلى مكة فلما كان آخر النهار بلغ أبا براء قتل البراض عروة فقال خدعني حرب وابن جدعان وركب فيمن حضر عكاظ من هوازن في أثر القوم فأدركوهم بنخلة فاقتتلوا حتى دخلت قريش الحرم وجن عليهم الليل فكفوا ونادى الأدرم بن شعيب أحد بني عامر بن ربيعة بن صعصعة يا معشر قريش ميعاد ما بيننا هذه الليلة من العام المقبل بعكاظ وكان يومئذ رؤساء قريش حرب بن أمية في القلب وابن جدعان في إحدى المجنبتين وهشام بن المغيرة في الأخرى وكان رؤساء قيس عامر بن مالك ملاعب الأسنة على بني عامر وكدام بن عمير على فهم وعدوان ومسعود بن سهم على ثقيف وسبيع بن ربيعة النصري علي بني نصر بن معاوية والصمة بن الحارث وهو أبو دريد بن الصمة علي بني جشم وكانت الراية مع حرب بن أمية وهي راية قصي التي يقال لها العقاب فقال في ذلك خداش بن زهير\n(يا شدة ما شددنا غير كاذبة ... على سخينة لولا الليل والحرم)\n(إذ يتقينا هشام بالوليد ولو ... أنا ثقفنا هشاما شالت الخدم)\n(بين الأراك وبين المرج تبطحهم ... زرق الأسنة في أطرافها السهم)\n(فإن سمعتم بجيش سالك سرفا ... وبطن مر فأخفوا الجرس واكتتموا)\nوزعموا أن عبد الملك بن مروان استنشد رجلا من قيس هذه الكلمة فجعل يحيد عن قوله سخينة فقال عبد الملك إنا قوم لم يزل يعجبنا السخن فهات فلما فرغ\nقال يا أخا قيس ما أرى صاحبك زاد على التمني والاستنشاء قال وقدم البراض باللطيمة مكة وكان يأكلها وكان عامر بن يزيد بن الملوح بن يعمر الكناني نازلا في أخواله من بني نمير بن عامر وكان ناكحا فيهم فهمت بنو كلاب بقتله فمنعته بنو نمير ثم شخصوا به حتى نزل في قومه واستغوت كنانة بني أسد وبني نمير واستغاثوا بهم فلم تغثهم ولم يشهد الفجار أحد من هذين الحيين","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":5,"spl":"اليوم الأول من أيام الفجار الثاني","tags":["السفر والحج"],"loc":3626},
{"id":"b270-14","bab":"الجزء 22","sec":"اليوم الثاني من أيام الفجار الثاني","page":"ج22 ص67","text":"ثم كان اليوم الثاني من الفجار الثاني وهو يوم شمطة فتجمعت كنانة وقريش بأسرها وبنو عبد مناة والأحابيش وأعطت قريش رؤوس القبائل أسلحة تامة وأعطى عبدالله بن جدعان خاصة من ماله مائة رجل من كنانة أسلحة تامة وأداة وجمعت هوازن وخرجت فلم تخرج معهم كلاب ولا كعب ولا شهد هذان البطنان من أيام الفجار إلا يوم نخلة مع أبي براء عامر بن مالك وكان القوم جميعا متساندين على كل قبيلة سيدهم فكان على بني هاشم وبني المطلب ولفهم الزبير بن عبد المطلب ومعهم النبي إلا أن بني المطلب وإن كانوا مع بني هاشم كان يرأسهم الزبير بن عبد المطلب بن هاشم ورجل منهم وهو عبد يزيد بن هاشم بن المطلب بن عبد مناف وأم الزبير الشفاء بنت هاشم بن عبد مناف وكان على بني عبد شمس ولفها حرب بن أمية ومعه أخواه أبو سفين وسفيان ومعهم بنو نوفل بن عبد مناف يرأسهم بعد حرب مطعم بن عدي بن نوفل وكان على بني عبد الدار ولفها خويلد بن أسد وعثمان بن الحويرث وكان على بني زهرة ولفها مخرمة بن نوفل بن وهيب بن عبد مناف بن زهرة وأخوه صفوان وكان على بني تيم بن مرة ولفها عبد الله بن جدعان وعلى بني مخزوم هشام بن المغيرة وعلى بني سهم العاصي بن وائل وعلى بني جمح ولفها أمية بن خلف وعلى بني عدي زيد بن عمرو بن نفيل والخطاب بن نفيل عمه وعلى بني عامر بن لؤي عمرو بن عبد شمس بن عبد ود أبو سهل بن عمرو وعلى بني الحارث بن فهر عبد الله بن الجراح أبو أبي عبيدة عامر بن عبد الله بن الجراح وعلى بني\nبكر بلعاء بن قيس ومات في تلك الأيام وكان جثامة بن قيس أخوه مكانه وعلى الأحابيش الحليس بن يزيد وكانت هوازن متساندين كذلك وكان عطية بن عفيف النصري على بني نصر بن معاوية\nوقيل بل كان عليهم أبو أسماء بن الضريبة وكان الخنيسق الجشمي على بني جشم وسعد ابني بكر وكان وهب بن معتب على ثقيف ومعه أخوه مسعود وكان على بني عامر بن ربيعة وحلفائهم من بني جسر بن محارب سلمة بن إسماعيل أحد بني البكاء ومعه خالد بن هوذة أحد بني الحارث بن ربيعة وعلى بني هلال بن عامر بن صعصعة ربيعة بن أبي ظبيان بن ربيعة بن أبي ربيعة بن نهيك بن هلال بن عامر\nقال فسبقت هوازن قريشا فنزلت شمطة من عكاظ وظنوا أن كنانة لم توافهم وأقبلت قريش فنزلت من دون المسيل وجعل حرب بني كنانة في بطن الوادي\nوقال لهم لا تبرحوا مكانكم ولو أبيحت قريش فكانت هوازن من وراء المسيل قال أبو عبيدة فحدثني أبو عمرو بن العلاء قال كان ابن جدعان في إحدى المجنبتين وفي الأخرى هشام بن المغيرة وحرب في القلب وكانت الدائرة في أول النهار لكنانة فلما كان آخر النهار تداعت هوازن وصبروا واستحر القتل في قريش فلما رأى ذلك بنو الحارث بن كنانة وهم في بطن الوادي مالوا إلى قريش وتركوا مكانهم فلما استحر القتل بهم قال أبو مساحق بلعاء بن قيس لقومه\nألحقو برخم وهو جبل ففعلوا وانهزم الناس وكان رسول الله لا يصير في فئة إلا انهزم من يحاذيها فقال حرب بن أمية وعبد الله بن جدعان ألا ترون إلى هذا الغلام ما يحمل على فئة إلا انهزمت وفي ذلك يقول خداش بن زهير في كلمة له\n(فأبلغ إن عرضت بنا هشاما ... وعبد الله أبلغ والوليدا)\n(أولئك إن يكن في الناس خير ... فإن لديهم حسبا وجودا)\n(هم خير المعاشر من قريش ... وأوراها إذا قدحت زنودا)\n(بأنا يوم شمطة قد أقمنا ... عمود المجد إن له عمودا)\n(جلبنا الخيل ساهمة إليهم ... عوابس يدرعن النقع قودا)\n(فبتنا نعقد السيما وباتوا ... وقلنا صبحوا الإنس الحديدا)\n(فجاؤوا عارضا بردا وجئنا ... كما أضرمت في الغاب الوقودا)\n(ونادوا يا لعمرو لا تفروا ... فقلنا لا فرار ولا صدودا)\nوله نعقد السيما أي العلامات\n(فعاركنا الكماة وعاركونا ... عراك النمر عاركت الأسودا)\n(فولوا نضرب الهامات منهم ... بما انتهكوا المحارم والحدودا)\n(تركنا بطن شمطة من علاء ... كأن خلالها معزا شريدا)\n(ولم أر مثلهم هزموا وفلوا ... ولا كذيادنا عنقا مذودا)\nوله يا لعمرو يعني عمرو بن عامر بن ربيعة بن عامر بن صعصعة","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":6,"spl":"اليوم الثاني من أيام الفجار الثاني","tags":["الجواري والنساء"],"loc":3627},
{"id":"b270-15","bab":"الجزء 22","sec":"اليوم الثالث من أيام الفجار وهو يوم العبلاء","page":"ج22 ص70","text":"ثم كان اليوم الثالث من أيام الفجار وهو يوم العبلاء فجمع القوم بعضهم لبعض والتقوا على قرن الحول بالعبلاء وهو موضع قريب من عكاظ ورؤساؤهم يومئذ على ما كانوا عليه يوم شمطة وكذلك من كان على المجنبتين فاقتتلوا قتالا شديدا فانهزمت كنانة فقال خداش بن زهير في ذلك\n(ألم يبلغك بالعبلاء أنا ... ضربنا خندفا حتى استقادوا)\n(نبني بالمنازل عز قيس ... وودوا لو تسيخ بنا البلاد)\nقال أيضا\n(ألم يبلغك ما لاقت قريش ... وحي بني كنانة إذ أثيروا)\n(دهمناهم بأرعن مكفهر ... فظل لنا بعقوتهم زئير)\n(نقوم مارن الخطي فيهم ... يجيء على أسنتنا الجزير)","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":7,"spl":"اليوم الثالث من أيام الفجار وهو يوم العبلاء","tags":["اللهو والمزاح"],"loc":3628},
{"id":"b270-16","bab":"الجزء 22","sec":"اليوم الرابع من أيام الفجار وهو يوم عكاظ","page":"ج22 ص71","text":"ثم كان اليوم الرابع من أيامهم يوم عكاظ فالتقوا في هذه المواضع على رأس الحول وقد جمع بعضهم لبعض واحتشدوا والرؤساء بحالهم وحمل عبد الله بن جدعان يومئذ ألف رجل من بني كنانة على ألف بعير وخشيت قريش أن يجري عليها مثل ما جرى يوم العبلاء فقيد حرب وسفيان وأبو سفيان بنو أمية بن عبد شمس أنفسهم وقالوا لا نبرح حتى نموت مكاننا وعلى أبي سفيان يومئذ درعان قد ظاهر بينهما وزعم أبو عمرو بن العلاء أن أبا سفيان بن أمية خاصة قيد نفسه فسمي هؤلاء الثلاثة يومئذ العنابس وهي الأسود واحدها عنبسة فاقتتل الناس يومئذ قتالا شديدا وثبت الفريقان حتى همت بنو بكر بن عبد مناة وسائر بطون كنانة بالهرب وكانت بنو مخزوم تلي كنانة فحافظت حفاظا شديدا وكان أشدهم يومئذ بنو المغيرة فإنهم صبروا وأبلوا بلاء حسنا فلما رأت ذلك بنو عبد مناة من كنانة تذامروا فرجعوا وحمل بلعاء بن قيس وهو يقول\n(إن عكاظ مأوانا فخلوه ... وذا المجاز بعد أن تحلوه)\nخرج الحليس بن يزيد أحد بني الحارث بن عبد مناة بن كنانة وهو رئيس الأحابيش يومئذ فدعا إلى المبارزة فبرز إليه الحدثان بن سعد\nالنصري فطعنه الحدثان فدق عضده وتحاجزا واقتتل القوم قتالا شديدا وحملت قريش وكنانة على قيس من كل وجه فانهزمت قيس كلها إلا بني نصر فإنهم صبروا ثم هربت بنو نصر وثبت بنو دهمان فلم يغنوا شيئا فانهزموا وكان عليهم سبيع بن أبي ربيعة أحد بني دهمان فعقل نفسه ونادى يا آل هوازن يا آل هوازن يا آل نصر فلم يعرج عليه أحد وأجفلوا منهزمين فكر بنو أمية خاصة في بني دهمان ومعهم الخنيسق وقشعة الجشميان فقاتلوا فلم يغنوا شيئا فانهزموا وكان مسعود بن معتب الثقفي قد ضرب على امرأته سبيعة بنت عبد شمس بن عبد مناف خباء\nوقال لها من دخله من قريش فهو آمن فجعلت توصل في خبائها ليتسع فقال لها لا يتجاوزني خباؤك فإني لا أمضي لك إلا من أحاط به الخباء فأحفظها فقالت أما والله إني لأظن أنك ستود أن لو زدت في توسعته فلما انهزمت قيس دخلوا خباءها مستجيرين بها فأجار لها حرب بن أمية جيرانها\nوقال لها يا عمة من تمسك بأطناب خبائك أو دار حوله فهو آمن فنادت بذلك فاستدارت قيس بخبائها حتى كثروا جدا فلم يبق أحد لا نجاة عنده إلا دار بخبائها فقيل لذلك الموضع مدار قيس وكان يضرب به المثل فتغضب قيس منه وكان زوجها مسعود بن معتب بن مالك بن كعب بن عمرو بن سعد بن عوف بن قيس وهو من ثقيف قد أخرج معه يومئذ بنيه من سبيعة وهم عروة ولوحة ونويرة والأسود\nفكانوا يدورون وهم غلمان في قيس يأخذون بأيديهم إلى خباء أمهم ليجيروهم فيسودوا بذلك أمرتهم أمهم أن يفعلوا فأخبرني الحرمي والطوسي قالا\nحدثنا الزبير بن بكار قال حدثني محمد بن الحسن عن المحرز بن جعفر وغيره أن كنانة وقيسا لما توافوا من العام المقبل من مقتل عروة بن عتبة بن جعفر بن كلاب ضرب مسعود الثقفي على امرأته سبيعة بنت عبد شمس أم بنيه خباء فرآها تبكي حين تدانى الناس فقال لها ما يبكيك فقالت لما يصاب غدا من قومي فقال لها من دخل خباءك فهو آمن فجعلت توصل فيه القطعة بعد القطعة والخرقة والشيء ليتسع فخرج وهب بن معتب حتى وقف عليها\nوقال لها لا يبقى طنب من أطناب هذا البيت إلا ربطت به رجلا من بني كنانة فلما صف القوم بعضهم لبعض خرجت سبيعة فنادت بأعلى صوتها إن وهبا يأتلي ويحلف ألا يبقى طنب من أطناب هذا البيت إلا ربط به رجلا من كنانة فالجد الجد فلما هزمت قيس لجأ نفر منهم إلى خباء سبيعة بنت عبد شمس فأجارهم حرب بن أمية\nأخبرني هاشم بن محمد قال حدثنا أبو غسان دماذ عن أبي عبيدة قال لما هزمت قيس لجأت إلى خباء سبيعة حتى أخرجوها منه فخرجت فنادت من تعلق بطنب من أطناب بيتي فهو آمن من ذمتي فداروا بخبائها حتى صاروا حلقة فأمضى ذلك كله حرب بن أمية لعمته فكان يضرب في الجاهلية بمدار قيس المثل ويعيرون بمدارهم يومئذ بخباء سبيعة بنت عبد شمس قال\nوقال ضرار بن الخطاب الفهري قوله\n(ألم تسأل الناس عن شأننا ... ولم يثبت الأمر كالخابر)\n(غداة عكاظ إذا استكملت ... هوازن في كفها الحاضر)\n(وجاءت سليم تهز القنا ... على كل سلهبة ضامر)\n(وجئنا إليهم على المضمرات ... بأرعن ذي لجب زاخر)\n(فلما التقينا أذقناهم ... طعانا بسمر القنا العائر)\n(ففرت سليم ولم يصبروا ... وطارت شعاعا بنو عامر)","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":8,"spl":"اليوم الرابع من أيام الفجار وهو يوم عكاظ","tags":["الجواري والنساء"],"loc":3629},
{"id":"b270-17","bab":"الجزء 22","sec":"اليوم الرابع من أيام الفجار وهو يوم عكاظ","page":"ج22 ص71","text":"(وفرت ثقيف إلى لاتها ... بمنقلب الخائب الخاسر)\n(وقاتلت العنس شطر النها ... رثم تولت مع الصادر)\n(على أن دهمانها حافظت ... أخيرا لدى دارة الدائر)\nقال خداش بن زهير\n(أتتنا قريش حافلين بجمعهم ... عليهم من الرحمن واق وناصر)\n(فلما دنونا للقباب وأهلها ... أتيح لنا ريب مع الليل ناجر)\n(أتيحت لنا بكر وحول لوائها ... كتائب يخشاها العزيز المكاثر)\n(جئت دونهم بكر فلم تستطعهم ... كأنهم بالمشرفية سامر)\n(وما برحت خيل تثور وتدعى ... ويلحق منهم أولون وآخر)\n(لدن غدوة حتى أتى وانجلى لنا ... عماية يوم شره متظاهر)\n(وما زال ذاك الدأب حتى تخاذلت ... هوازن وارفضت سليم وعامر)\n(وكانت قريش يفلق الصخر حدها ... إذا أوهن الناس الجدود العواثر)","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":9,"spl":"اليوم الرابع من أيام الفجار وهو يوم عكاظ — اجتماع القبائل على الصلح","tags":["الوصف والطبيعة"],"loc":3630},
{"id":"b270-18","bab":"الجزء 22","sec":"اليوم الخامس من حرب الفجار وهو يوم حريرة","page":"ج22 ص75","text":"ثم كان اليوم الخامس وهو يوم الحريرة وهي حرة إلى جانب عكاظ والرؤساء بحالهم إلا بلعاء بن قيس فإنه قد مات فصار أخوه مكانه على عشيرته فاقتتلوا فانهزمت كنانة وقتل يومئذ أبو سفيان بن أمية وثمانية رهط من بني كنانة قتلهم عثمان بن أسد من بني عمرو بن عامر بن ربيعة وقتل ورقاء بن الحارث أحد بني عمرو بن عامر من بني كنانة وخمسة نفر وقال خداش بن زهير في ذلك\n(لقد بلوكم فأبلوكم بلاءهم ... يوم الحريرة ضربا غير تكذيب)\n(إن توعدوني فإني لابن عمكم ... وقد أصابوكم منه بشؤبوب)\n(وإن ورقاء قد أردى أبا كنف ... وابني إياس وعمرا وابن أيوب)\n(وإن عثمان قد أردى ثمانية ... منكم وأنتم على خبر وتجريب)\nم كان الرجل منهم بعد ذلك يلقى الرجل والرجلان يلقيان الرجلين فيقتل بعضهم بعضا فلقى ابن محمية بن عبد الله الديلي زهير بن ربيعة أبا خداش فقال زهير إني حرام جئت معتمرا فقال له ما تلقى طوال الدهر إلا قلت أنا معتمر ثم قتله فقال الشويعر الليثي واسمه ربيعة بن علس\n(تركنا ثاويا يزقو صداه ... زهيرا بالعوالي والصفاح)\n(أتيح له ابن محمية بن عبد ... فأعجله التسوم بالبطاح)\nم تداعوا إلى الصلح على أن يدي من عليه فضل في القتلى الفضل إلى أهله فأبى ذلك وهب بن معتب وخالف قومه واندس إلى هوازن حتى أغارت على بني كنانة فكان منهم بنو عمرو بن عامر بن ربيعة عليهم سلمة بن سعدي البكائي وبنو هلال عليهم ربيعة بن أبي ظبيان الهلالي وبنو نصر بن معاوية عليهم مالك بن عوف وهو يومئذ أمرد فأغاروا على بني ليث بن بكر بصحراء الغميم فكانت لبني ليث أول النهار فقتلوا عبيد بن عوف البكائي قتله بنو مدلج وسبيع بن المؤمل الجسري حليف بني عامر ثم كانت على بني ليث آخر النهار فانهزموا\nواستحر القتل في بني الملوح بن يعمر بن ليث وأصابوا نعما ونساء حينئذ فكان ممن قتل في حروب الفجار من قريش العوام بن خويلد قتله مرة بن معتب وقتل حزام بن خويلد وأحيحة بن أبي أحيحة ومعمر بن حبيب الجمحي وجرح حرب بن أمية وقتل من قيس الصمة أبو دريد بن الصمة قتله جعفر بن الأحنف","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":9,"spl":"اليوم الرابع من أيام الفجار وهو يوم عكاظ — اجتماع القبائل على الصلح","tags":["الموت"],"loc":3631},
{"id":"b270-19","bab":"الجزء 22","sec":"اجتماع القبائل على الصلح","page":"ج22 ص76","text":"ثم تراضوا بأن يعدوا القتلى فيدوا من فضل فكان الفضل لقيس على قريش وكنانة فاجتمعت القبائل على الصلح وتعاقدوا ألا يعرض بعضهم لبعض فرهن حرب بن أمية ابنه أبا سفيان بن حرب ورهن الحارث بن كلدة العبدي ابنه النصر ورهن سفيان بن عوف أحد بني الحارث بن عبد مناة ابنه الحارث حتى وديت الفضول ويقال إن عتبة بن ربيعة تقدم يومئذ فقال يا معشر قريش هلموا إلى صلة الأرحام والصلح قالوا وما صلحكم هنا فإنا موتورون فقال على أن ندي قتلاكم ونتصدق عليكم بقتلانا فرضوا بذلك وساد عتبة مذ يومئذ قال فلما رأت هوازن رهائن قريش بأيديهم رغبوا في العفو فأطلقوهم","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":9,"spl":"اليوم الرابع من أيام الفجار وهو يوم عكاظ — اجتماع القبائل على الصلح","tags":["اللهو والمزاح"],"loc":3632},
{"id":"b270-21","bab":"الجزء 22","sec":"النبي شهد الفجار إلا يوم نحلة — أميمة ترثي قومها","page":"ج22 ص77 – ج22 ص78","text":"قال أبو عبيدة ولم يشهد الفجار من بني هاشم غير الزبير بن عبد المطلب وشهد النبي وآله سائر الأيام إلا يوم نخلة وكان يناول عمه وأهله النبل قال وشهدها وهو ابن عشرين سنة وطعن النبي وآله أبا براء ملاعب الأسنة وسئل وآله عن مشهده\nيومئذ فقال ما سرني أني لم أشهده إنهم تعدوا على قومي عرضوا عليهم أن يدفعوا إليهم البراض صاحبهم فأبوا قال وكان الفضل عشرين قتيلا من هوازن فوادهم حرب بن أمية فيما تروي قريش وبنو كنانة تزعم أن القتلى الفاضلين قتلاهم وأنهم هم ودوهم وزعم قوم من قريش أن أبا طالب وحمزة والعباس بني عبد المطلب عليهما السلام شهدوا هذه الحروب ولم يرد ذلك أهل العلم بأخبار العرب\nقال أبو عبيدة ولما انهزمت قيس خرج مسعود بن معتب لا يعرج على شيء حتى أتى سبيعة بنت عبد شمس زوجته فجعل أنفه بين ثدييها وقال أنا بالله وبك فقالت كلا زعمت أنك ستملأ بيتي من أسرى قومي اجلس فأنت آمن\nوقالت أميمة بنت عبد شمس ترثي ابن أخيها أبا سفيان بن أمية ومن قتل من قومها والأبيات التي فيها الغناء منها\n(أبى ليلك لا يذهب ... ونيط الطرف بالكوكب)\n(ونجم دونه الأهوال ... بين الدلو والعقرب)\n(وهذا الصبح لا يأتي ... ولا يدنو ولا يقرب)\n(بعقر عشيرة منا ... كرام الخيم والمنصب)\n(أحال عليهم دهر ... حديد الناب والمخلب)\n(فحل بهم وقد أمنوا ... ولم يقصر ولم يشطب)\n(وما عنه إذا ما حل ... من منجى ولا مهرب)\n(ألا يا عين فابكيهم ... بدمع منك مستغرب)\n(فإن أبك فهم عزي ... وهم ركني وهم منكب)\n(وهم أصلي وهم فرعي ... وهم نسبي إذا أنسب)\n(وهم مجدي وهم شرفي ... وهم حصني إذا أرهب)\n(وهم رمحي وهم ترسي ... وهم سيفي إذا أغضب)\n(فكم من قائل منهم ... إذا ما قال لا يكذب)\n(وكم من ناطق فيهم ... خطيب مصقع معرب)\n(وكم من فارس فيهم ... كمي معلم محرب)\n(وكم من مدرة فيهم ... أريب حول قلب)\n(وكم من جحفل فيهم ... عظيم النار والموكب)\n(وكم من خضرم فيهم ... نجيب ماجد منجب)\n\n(أحب هبوط الواديين وإنني ... لمشتهر بالواديين غريب)\n(أحقا عباد الله أن لست خارجا ... ولا والجا إلا علي رقيب)\n(ولا زائرا فردا ولا في جماعة ... من الناس إلا قيل أنت مريب)\n(وهل ريبة في أن تحن نجيبة ... إلى إلفها أو أن يحن نجيب)\nلشعر فيما ذكره أبو عمرو الشيباني في أشعار بني جعدة وذكره أبو الحسن المدائني في أخبار رواها لمالك بن الصمصامة الجعدي ومن الناس من يرويه لابن الدمينة ويدخله في قصيدته التي على هذه القافية والروي والغناء لإسحاق هزج بالبنصر عن عمرو","topic":"أخبار أبي حفص الشطرنجي ونسبه","topicNo":270,"sp":10,"spl":"النبي شهد الفجار إلا يوم نحلة — أميمة ترثي قومها","tags":[],"song":1,"loc":3633},
{"id":"b271-2","bab":"الجزء 22","sec":"أخبار مالك ونسبه — كان يهوى جنوب بنت محصن الجعدية","page":"ج22 ص80 – ج22 ص81","text":"هو مالك بن الصمصامة بن سعد بن مالك أحد بني جعدة بن كعب بن ربيعة بن عامر بن صعصعة شاعر بدوي مقل\nأخبرني بخبره هاشم بن محمد الخزاعي ومحمد بن خلف بن المرزبان قالا أخبرنا أحمد بن الحارث الخزاز عن المدائني ونسخت خبره أيضا من كتاب أبي عمرو الشيباني قالوا كان مالك بن الصمصامة الجعدي فارسا شجاعا جوادا جميل الوجه وكان يهوى جنوب بنت محصن الجعدية وكان أخوها الأصبغ بن محصن من فرسان العرب وشجعانهم وأهل النجدة والبأس منهم فنمى إليه نبذ من خبر مالك فآلى يمينا جزما لئن بلغه أنه عرض لها أوزارها ليقتلنه ولئن بلغه أنه ذكرها في شعر أو عرض بها ليأسرنه ولا يطلقه إلا أن يجز ناصيته في نادي قومه فبلغ ذلك مالك بن الصمصامة فقال\n(إذا شئت فاقرني إلى جنب عيهب ... أجب ونضوي للقلوص جنيب)\n(فما الحلق بعد الأسر شر بقية ... من الصد والهجران وهي قريب)\n(ألا أيها الساقي الذي بل دلوه ... بقريان يسقي هل عليك رقيب)\n(إذا أنت لم تشرب بقريان شربة ... وحانية الجدران ظلت تلوب)\n(أحب هبوط الواديين وإنني ... لمشتهر بالواديين غريب)\n(أحقا عباد الله أن لست خارجا ... ولا والجا إلا علي رقيب)\n(ولا زائرا وحدي ولا في جماعة ... من الناس إلا قيل أنت مريب)\n(وهل ريبة في أن تحن نجيبة ... إلى إلفها أو أن يحن نجيب)","topic":"أخبار مالك ونسبه","topicNo":271,"sp":0,"spl":"أخبار مالك ونسبه — كان يهوى جنوب بنت محصن الجعدية — كان يراها ولا يستطيع مخاطبتها","tags":["الجواري والنساء","الرواية والكتابة"],"loc":3634},
{"id":"b271-3","bab":"الجزء 22","sec":"كان يراها ولا يستطيع مخاطبتها","page":"ج22 ص82","text":"وقال أبو عمرو خاصة حدثنا فتيان من بني جعدة أنها أقبلت ذات يوم وهو جالس في مجلس فيه أخوها فلما رآها عرفها ولم يقدر على الكلام بسبب أخيها فأغمي عليه وفطن أخوها لما به فتغافل عنه وأسنده بعض فتيان العشيرة إلى صدره فما تحرك ولا أحار جوابا ساعة من نهاره وانصرف أخوها كالخجل فلما أفاق قال\n(ألمت فما حيت وعاجت فأسرعت ... إلى جرعة بين المخارم فالنحر)\n(خليلي قد حانت وفاتي فاحفروا ... برابية بين المخافر والبتر)\n(لكيما تقول العبدلية كلما ... رأت جدثي سقيت يا قبر من قبر)\nقال المدائني في خبره انتجع أهل بيت جنوب ناحية حسي والحمى وقد أصابها الغيث فأمرعت فلما أرادوا الرحيل وقف لهم مالك بن الصمصامة حتى إذا بلغته جنوب أخذ بخطام بعيرها ثم أنشأ يقول\n(أريتك إن أزمعتم اليوم نية ... وغالك مصطاف الحمى ومرابعه)\n(أترعين ما استودعت أم أنت كالذي ... إذا ما نأى هانت عليه ودائعه)\nفبكت وقالت بل أرعى والله ما استودعت ولا أكون كمن هانت عليه ودائعه فأرسل بعيرها وبكى حتى سقط مغشيا عليه وهي واقفة ثم أفاق وقام فانصرف وهو يقول\n(ألا إن حسيا دونه قلة الحمى ... منى النفس لو كانت تنال شرائعه)\n(وكيف ومن دون الورود عوائق ... وأصبغ حامي ما أحب ومانعه)\n(فلا أنا فيما صدني عنه طامع ... ولا أرتجي وصل الذي هو قاطعه)\n\n(يا دار هند عفاها كل هطال ... بالخبت مثل سحيق اليمنة البالي)\n(أرب فيها ولي ما يغيرها ... والريح مما تعفيها بأذيال)\n(دار وقفت بها صحبي أسائلها ... والدمع قد بل مني جيب سربالي)\n(شوقا إلى الحي أيام الجميع بها ... وكيف يطرب أو يشتاق أمثالي)\nوله أرب فيها أي أقام فيها وثبت والولي الثاني من أمطار السنة أولها الوسمي والثاني الولي ويروى\n(جرت عليها رياح الصيف فاطرقت ... )\nاطرقت تلبدت الشعر لعبيد بن الأبرص والغناء لإبراهيم هزج بإطلاق الوتر في مجرى الوسطى عن إسحاق وفيه لابن جامع رمل بالوسطى وقد نسب لحنه هذا إلى إبراهيم ولحن إبراهيم إليه","topic":"أخبار مالك ونسبه","topicNo":271,"sp":0,"spl":"أخبار مالك ونسبه — كان يهوى جنوب بنت محصن الجعدية — كان يراها ولا يستطيع مخاطبتها","tags":[],"song":1,"loc":3635,"partial":1},
{"id":"b272-1","bab":"الجزء 22","sec":"أخبار عبيد بن الأبرص ونسبه","page":"ج22 ص85","text":"قال أبو عمرو الشيباني هو عبيد بن الأبرص بن حنتم بن عامر بن مالك بن زهير بن مالك بن الحارث بن سعد بن ثعلبة بن دودان بن أسد بن خزيمة بن مدركة بن إلياس بن مضر شاعر فحل فصيح من شعراء الجاهلية وجعله ابن سلام في الطبقة الرابعة من فحول الجاهلية وقرن به طرفة وعلقمة بن عبدة وعدي بن زيد أخبرنا أبو خليفة عن محمد بن سلام قال عبيد بن الأبرص قديم الذكر عظيم الشهرة وشعره مضطرب ذاهب لا أعرف له إلا قوله في كلمته\n(أقفر من أهله ملحوب ... )\nولا أدري ما بعد ذلك","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":0,"spl":"أخبار عبيد بن الأبرص ونسبه — امرؤ القيس يرفض دية أبيه ويهدد بني أسد فينشد عبيد بن الأبرص","tags":["الرواية والكتابة"],"loc":3636,"partial":1},
{"id":"b272-2","bab":"الجزء 22","sec":"اتهم بأخته ماوية","page":"ج22 ص86","text":"أخبرنا عبد الله بن مالك النحوي الضرير قال حدثنا محمد بن حبيب عن ابن الأعرابي وأبي عمرو الشيباني قالا كان من حديث عبيد بن الأبرص أنه كان رجلا محتاجا ولم يكن له مال فأقبل ذات يوم ومعه غنيمة له ومعه أخته ماوية ليوردا غنمها الماء فمنعه رجل من بني مالك بن ثعلبة وجبهه فانطلق حزينا مهموما للذي صنع به المالكي حتى أتى شجرات فاستظل تحتهن فنام هو وأخته فزعموا أن المالكي نظر إليه وأخته إلى جنبه فقال\n(ذاك عبيد قد أصاب ميا ... يا ليته ألقحها صبيا)\n(فحملت فوضعت ضاويا ... )\nسمعه عبيد فرفع يديه ثم ابتهل فقال اللهم إن كان فلان ظلمني ورماني بالبهتان فأدلني منه أي اجعل لي منه دولة وانصرني عليه ووضع رأسه فنام ولم يكن قبل ذلك يقول الشعر فذكر أنه أتاه آت في المنام بكبة من شعر حتى ألقاها في فيه ثم قال قم فقام وهو يرتجز يعني بني مالك وكان يقال لهم بنو الزنية\nيقول\n(أيا بني الزنية ما غركم ... فلكم الويل بسربال حجر)\nم استمر بعد ذلك في الشعر وكان شاعر بني أسد غير مدافع","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":0,"spl":"أخبار عبيد بن الأبرص ونسبه — امرؤ القيس يرفض دية أبيه ويهدد بني أسد فينشد عبيد بن الأبرص","tags":["الرواية والكتابة"],"loc":3637,"partial":1},
{"id":"b272-3","bab":"الجزء 22","sec":"امرؤ القيس يرفض دية أبيه ويهدد بني أسد فينشد عبيد بن الأبرص","page":"ج22 ص87","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال اجتمعت بنو أسد بعد قتلهم حجر بن عمرو والد امرئ القيس إلى امرئ القيس ابنه على أن يعطوه ألف بعير دية أبيه أو يقيدوه من أي رجل شاء من بني أسد أو يمهلهم حولا فقال أما الدية فما ظننت أنكم تعرضونها على مثلي وأما القود فلو قيد إلي ألف من بني أسد ما رضيتهم ولا رأيتهم كفؤا لحجر وأما النظرة فلكم ثم ستعرفونني في فرسان قحطان أحكم فيكم ظبا السيوف وشبا الأسنة حتى أشفي نفسي وأنال ثأري فقال عبيد بن الأبرص في ذلك\n(يا ذا المخوفنا بقتل ... أبيه إذلالا وحينا)\n(أزعمت أنك قد قتلت ... سراتنا كذبا ومينا)\n(هلا على حجر ابن أمم ... قطام تبكي لا علينا)\n(إنا إذا عض الثقاف ... برأس صعدتنا لوينا)\n(نحمي حقيقتنا وبعض ... الناس يسقط بين بينا)\n(هلا سألت جموع كندة ... يوم ولوا أين أينا)\nلغناء لحنين رمل في مجرى الوسطى مطلق عن الهشامي وفيه ليحيى المكي خفيف ثقيل قال وتمام هذه الأبيات\n(أيام نضرب هامهم ... ببواتر حتى انحنينا)\n(وجموع غسان الملوك ... أتينهم وقد انطوينا)\n(لحقا أياطلهن قد ... عالجن أسفارا وأينا)\nالأياطل الخواصر أي هن ضوامرها\n(نحن الألى فاجمع جمو ... عك ثم وجههم إلينا)\n(واعلم بأن جيادنا ... آلين لا يقضين دينا)\n(ولقد أبحنا ما حميت ... ولا مبيح لما حمينا)\n(هذا ولو قدرت عليك ... رماح قومي ما انتهينا)\n(حتى تنوشك نوشة ... عاداتهن إذا انتوينا)\n(نغلي السباء بكل عاتقة ... شمول ما صحونا)\n(ونهين في لذاتنا ... عظم التلاد إذا انتشينا)\n(لا يبلغ الباني ولو ... رفع الدعائم ما بنينا)\n(كم من رئيس قد قتلناه ... وضيم قد أبينا)\n(ولرب سيد معشر ... ضخم الدسيعة قد رمينا)\n(عقبانه بظلال عقبان ... تتمم ما نوينا)\n(حتى تركنا شلوه ... جزر السباع وقد مضينا)\n(إنا لعمرك ما يضام ... حليفنا أبدا لدينا)\n(وأوانس مثل الدمى ... حور العيون قد استبينا)","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":0,"spl":"أخبار عبيد بن الأبرص ونسبه — امرؤ القيس يرفض دية أبيه ويهدد بني أسد فينشد عبيد بن الأبرص","tags":[],"song":1,"loc":3638},
{"id":"b272-4","bab":"الجزء 22","sec":"وفاء ثعبان له","page":"ج22 ص89","text":"وقرأت في بعض الكتب عن ابن الكلبي عن أبيه وهو خبر مصنوع يتبين التوليد فيه أن عبيد بن الأبرص سافر في ركب من بني أسد فبيناهم يسيرون إذا\nهم بشجاع يتمعك على الرمضاء فاتحا فاه من العطش وكانت مع عبيد فضلة من ماء ليس معه ماء غيرها فنزل فسقاه الشجاع عن آخره حتى روي وانتعش فأنساب في الرمل فلما كان من الليل ونام القوم ندت رواحلهم فلم ير لشيء منها أثر فقام كل واحد يطلب راحلته فتفرقوا فبينا عبيد كذلك وقد أيقن بالهلكة والموت إذا هو بهاتف يهتف به\n(يا أيها الساري المضل مذهبه ... دونك هذا البكر منا فاركبه)\n(وبكرك الشارد أيضا فاجنبه ... حتى إذا الليل تجلى غيهبه)\n(فحط عنه رحله وسيبه ... )\nقال له عبيد يا هذا المخاطب نشدتك الله إلا أخبرتني من أنت فأنشأ يقول\n(أنا الشجاع الذي ألفيته رمضا ... في قفرة بين أحجار وأعقاد)\n(فجدت بالماء لما ضن حامله ... وزدت فيه ولم تبخل بإنكاد)\n(الخير يبقى وإن طال الزمان به ... والشر أخبث ما أوعيت من زاد)\nفركب البكر وجنب بكره وسار فبلغ أهله مع الصبح فنزل عنه وحل رحله وخلاه فغاب عن عينه وجاء من سلم من القوم بعد ثلاث","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":1,"spl":"وفاء ثعبان له — عبيد يقتل في يوم البؤس","tags":["السفر والحج","الوصف والطبيعة","الموت"],"loc":3639,"partial":1},
{"id":"b272-5","bab":"الجزء 22","sec":"كان للمنذر بن ماء السماء يومان","page":"ج22 ص91","text":"أخبرني محمد بن عمران المؤدب وعمي قالا حدثنا محمد بن عبيد قال حدثني محمد بن يزيد بن زياد الكلبي عن الشرقي بن القطامي قال كان المنذر بن ماء السماء قد نادمه رجلان من بني أسد أحدهما خالد بن المضلل والآخر عمرو بن مسعود بن كلدة فأغضباه في بعض المنطق فأمر بأن يحفر لكل واحد حفيرة بظهر الحيرة ثم يجعلا في تابوتين ويدفنا في الحفرتين ففعل ذلك بهما حتى إذا أصبح سأل عنهما فأخبر بهلاكهما فندم على ذلك وغمه وفي عمرو بن مسعود وخالد بن المضلل الأسديين يقول شاعر بني أسد\n(يا قبر بين بيوت آل محرق ... جادت عليك رواعد وبروق)\n(أما البكاء فقل عنك كثيره ... ولئن بكيت فللبكاء خليق)\nثم ركب المنذر حتى نظر إليهما فأمر ببناء الغريين عليهما فبنيا عليهما وجعل لنفسه يومين في السنة يجلس فيهما عند الغريين يسمى أحدهما يوم نعيم والآخر يوم بؤس فأول من يطلع عليه يوم نعيمه يعطيه مائة من الإبل شوما أي سودا وأول من يطلع عليه يوم بؤسه يعطيه\nرأس ظربان أسود ثم يأمر به فيذبح ويغرى بدمه الغريان فلبث بذلك برهة من دهره","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":1,"spl":"وفاء ثعبان له — عبيد يقتل في يوم البؤس","tags":["الرواية والكتابة"],"loc":3640},
{"id":"b272-6","bab":"الجزء 22","sec":"عبيد يقتل في يوم البؤس","page":"ج22 ص92","text":"ثم إن عبيد بن الأبرص كان أول من أشرف عليه في يوم بؤسه فقال هلا كان الذبح لغيرك يا عبيد فقال أتتك بحائن رجلاه فأرسلها مثلا فقال له المنذر أو أجل بلغ إناه فقال له المنذر أنشدني فقد كان شعرك يعجبني فقال عبيد حال الجريض دون القريض وبلغ الحزام الطبيين فأرسلها مثلا فقال له النعمان أسمعني فقال المنايا على الحوايا فأرسلها مثلا فقال له آخر ما أشد جزعك من الموت فقال لا يرحل رحلك من ليس معك فأرسلها مثلا فقال له المنذر قد أمللتني فأرحني قبل أن آمر بك فقال عبيد من عز بز فأرسلها مثلا فقال المنذر أنشدني قولك\n(أقفر من أهله ملحوب ... )\nقال عبيد\n(أقفر من أهله عبيد ... فليس يبدي ولا يعيد)\n(عنت له عنة نكود ... وحان منها له ورود)\nقال له المنذر يا عبيد ويحك أنشدني قبل أن أذبحك فقال عبيد\n(والله إن مت لما ضرني ... وإن أعش ما عشت في واحده)\nقال المنذر إنه لا بد من الموت ولو أن النعمان عرض لي في يوم بؤس لذبحته فاختر إن شئت الأكحل وإن شئت الأبجل وإن شئت الوريد فقال عبيد ثلاث خصال كسحابات عاد واردها شر وراد وحاديها شر حاد ومعادها شر معاد ولا خير فيه لمرتاد وإن كنت لا محالة قاتلي فاسقني الخمر حتى إذا ماتت مفاصلي وذهلت لها ذواهلي فشأنك وما تريد فأمر المنذر بحاجته من الخمر حتى إذا أخذت منه وطابت نفسه دعا به المنذر ليقتله فلما مثل بين يديه أنشأ يقول\n(وخيرني ذو البؤس في يوم بؤسه ... خصالا أرى في كلها الموت قد برق)\n(كما خيرت عاد من الدهر مرة ... سحائب ما فيها لذي خيرة أنق)\n(سحائب ريح لم توكل ببلدة ... فتتركها إلا كما ليلة الطلق)\nفأمر به المنذر ففصد فلما مات غري بدمه الغريان","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":1,"spl":"وفاء ثعبان له — عبيد يقتل في يوم البؤس","tags":["السفر والحج","الخمر"],"song":1,"loc":3641,"partialRef":{"sid":"b272-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b272-7","bab":"الجزء 22","sec":"خبر الطائي الذي يرمز إلى وفاء العرب بالعهد","page":"ج22 ص94","text":"فلم يزل كذلك حتى مر به رجل من طيىء يقال له حنظلة بن أبي عفراء أو ابن أبي عفر فقال له أبيت اللعن والله ما أتيتك زائرا ولأهلي من خيرك مائرا فلا تكن ميرتهم قتلى فقال لا بد من ذلك فاسأل حاجة أقضينها لك فقال تؤجلني سنة أرجع فيها إلى أهلي وأحكم من أمرهم ما أريد ثم أصير إليك فأنفذ في حكمك فقال ومن يكفل بك حتى تعود فنظر في وجوه جلسائه فعرف منهم شريك بن عمرو أبا الحوفزان بن شريك فأنشد يقول\n(يا شريك يا بن عمرو ... ما من الموت محاله)\n(يا شريك يا بن عمرو ... يا أخا من لا أخاله)\n(يا أخا شيبان فك اليوم ... رهنا قد أناله)\n(يا أخا كل مضاف ... وحيا من لا حيا له)\n(إن شيبان قبيل ... أكرم الله رجاله)\n(وأبوك الخير عمرو ... وشراحيل الحما له)\n(رقياك اليوم في المجد ... وفي حسن المقاله)\nوثب شريك وقال أبيت اللعن يدي بيده ودمي بدمه إن لم يعد\nإلى أجله فأطلقه المنذر فلما كان من القابل جلس في مجلسه ينتظر حنظلة أن يأتيه فأبطأ عليه فأمر بشريك فقرب ليقتله فلم يشعر إلا براكب قد طلع عليهم فتأملوه فإذا هو حنظلة قد أقبل متكفنا متحنطا معه نادبته تندبه وقد قامت نادبة شريك تندبه فلما رآه المنذر عجب من وفائهما وكرمهما فأطلقهما وأبطل تلك السنة","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":2,"spl":"خبر الطائي الذي يرمز إلى وفاء العرب بالعهد","tags":["الموت"],"loc":3642},
{"id":"b272-8","bab":"الجزء 22","sec":"خبر آخر عن مقتل عبيد بن الأبرص","page":"ج22 ص95","text":"أخبرني الحسن بن علي قال حدثني عبد الله بن أبي سعد قال حدثنا علي بن الصباح عن هشام بن الكلبي قال كان من حديث عبيد بن الأبرص وقتله أن المنذر بن ماء السماء بنى الغريين فقيل له ما تريد إليهما وكان بناهما على قبري رجلين من بني أسد كانا نديميه أحدهما خالد بن المضلل الفقعسي والآخر عمرو بن مسعود فقال ما أنا بملك إن خالف الناس أمري لا يمرن أحد من وفود العرب إلا بينهما وكان له يومان في السنة يوم يسميه يوم النعيم ويوم يسميه يوم البؤس فإذا كان في يوم نعيمه أتي بأول من يطلع عليه فحباه وكساه ونادمه يومه وحمله فإذا كان يوم بؤسه أتي بأول من يطلع عليه فأعطاه رأس ظربان أسود ثم أمر به فذبح وغري بدمه الغريان فبينا هو جالس في يوم بؤسه إذ أشرف عليه عبيد فقال لرجل كان معه من هذا الشقي فقال له هذا عبيد بن الأبرص الأسدي الشاعر فأتي به فقال له الرجل الذي كان معه اتركه أبيت اللعن فإني أظن أن عنده من حسن القريض أفضل مما تدرك في قتله فاسمع منه فإن سمعت حسنا استزدته وإن لم يعجبك فما أقدرك على قتله فإذا نزلت فادع به قال\nفنزل وطعم وشرب وبينه وبين الناس حجاب ستر يراهم منه ولا يرونه فدعا بعبيد من وراء الستر فقال له رديفه هلا كان الذبح لغيرك يا عبيد فقال أتتك بحائن رجلاه فأرسلها مثلا فقال ما ترى يا عبيد قال أرى الحوايا عليها المنايا فقال فهل قلت شيئا فقال حال الجريض دون القريض فقال أنشدني\n(أقفر من أهله ملحوب ... )\nقال\n(أقفر من أهله عبيد ... فليس يبدي ولا يعيد)\n(عنت له خطة نكود ... وحان منها له ورود)\nقال أنشدنا\n(هي الخمر تكنى بأم الطلى ... كما الذئب يكنى أبا جعده)\nأبى أن ينشدهم شيئا مما أرادوا فأمر به فقتل فأما خبر عمرو بن مسعود وخالد بن المضلل ومقتلهما فإنهما كانا نديمين للمنذر بن ماء السماء فيما ذكره خالد بن كلثوم فراجعاه بعض القول على سكره فغضب فأمر بقتلهما\nوقيل بل دفنهما حيين فلما أصبح سأل عنهما فأخبر خبرهما فندم على فعله فأمر بإبل فنحرت على قبريهما وغري بدمائها قبراهما إعظاما لهما وحزن عليهما وبنى الغريين فوق قبريهما وأمر فيهما بما قدمت ذكره من أخبارهما فقالت نادبة الأسديين\n(ألا بكر الناعي بخير بني أسد ... بعمرو بن مسعود وبالسيد الصمد)\nقال بعض شعراء بني أسد يرثي خالد بن المضلل وعمرو بن مسعود وفيه غناء\n\n(يا قبر بين بيوت آل محرق ... جادت عليك رواعد وبروق)\n(أما البكاء فقل عنك كثيره ... ولئن بكيت فبالبكاء خليق)\nالغناء لابن سريج ثقيل أول مطلق في مجرى الوسطى من جامع أغانيه ومما يغنى به أيضا من شعر عبيد\n(طاف الخيال علينا ليلة الوادي ... من أم عمرو ولم يلمم لميعاد)\n(أني اهتديت لركب طال سيرهم ... في سبسب بين دكداك وأعقاد)\n(اذهب إليك فإني من بني أسد ... أهل القباب وأهل الجود والنادي)\nلغناء للغريض ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وفيه ثقيل أول بالوسطى ذكر الهشامي أنه لأبي زكار الأعمى وذكر حبش أنه لابن سريج وفي هذه القصيدة يقول يخاطب حجر بن الحارث أبا امرئ القيس وكان حجر يتوعده في شيء بلغه عنه ثم استصلحه فقال يخاطبه\n(أبلغ أبا كرب عني وإخوته ... قولا سيذهب غورا بعد إنجاد)\n(لا أعرفنك بعد الموت تندبني ... وفي حياتي ما زودتني زادي)\n(إن أمامك يوما أنت مدركه ... لا حاضر مفلت منه ولا بادي)\n(فانظر إلى ظل ملك أنت تاركه ... هل ترسين أواخيه بأوتاد)\n(الخير يبقى وإن طال الزمان به ... والشر أخبث ما أوعيت من زاد)","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":3,"spl":"خبر آخر عن مقتل عبيد بن الأبرص","tags":[],"song":2,"loc":3643,"partialRef":{"sid":"b272-1","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b272-9","bab":"الجزء 22","sec":"عمر بن الخطاب يبكي مع نساء بني مخزوم خالد بن الوليد","page":"ج22 ص98","text":"أخبرنا عيسى بن الحسين قال حدثنا أحمد بن الحارث الخزاعي عن المدائني عن أبي بكر الهذلي قال\nسمع عمر بن الخطاب نساء بني مخزوم يبكين على خالد بن الوليد فبكى وقال ليقل نساء بني مخزوم في أبي سليمان ما شئن فإنهن لا يكذبن وعلى مثل أبي سليمان تبكي البواكي فقال له طلحة بن عبيد الله إنك وإياه لكما قال عبيد بن الأبرص\n(لا ألفينك بعد الموت تندبني ... وفي حياتي ما زودتني زادي)\nخبرني عمي قال حدثني عبد الله بن أبي سعد قال حدثني محمد بن عبد الله الغبدي قال حدثني سيف الكاتب قال وليت ولاية فمررت بصديق لي في بعض المنازل فنزلت به قال فنلنا من الطعام والشراب ثم غلب علينا النبيذ فنمنا فانتبهت من نومي فإذا أنا بكلب قد دخل على كلب الرجل فجعل يبش به ويسلم\nعليه لا أنكر من كلامهما شيئا ثم جعل الكلب الداخل عليه يخبره عن طريقه بطول سفره وقال له هل عندك شيء تطعمنيه قال نعم قد بقي لهم في موضع كذا وكذا طعام وليس عليه شيء فذهبا إليه فكأني أسمع ولوغهما في الإناء حتى أكلا ما كان هناك فيه ثم سأله نبيذا فقال نعم لهم نبيذ في إناء آخر ليس له غطاء فذهبا إليه فشربا ثم قال له هل تطربني بشيء قل إي وعيشك صوت كان أبو يزيد يغنيه فيجيده ثم غناه في شعر عبيد بن الأبرص\n(طاف الخيال علينا ليلة الوادي ... لآل أسماء لم يلمم لميعاد)\n(أنى اهتديت لركب طال سيرهم ... في سبسب بين دكداك وأعقاد)\nال فلم يزل يغنيه هذا الصوت ويشربان مليا حتى فني ذلك النبيذ ثم خرج الكلب الداخل فخفت والله على نفسي أن أذكر ذلك لصاحب المنزل فأمسكت وما أذكر أني سمعت أحسن من ذلك الغناء ومما يغني فيه من شعره قوله\n(لمن جمال قبيل الصبح مزمومه ... ميممات بلادا غير معلومه)\n(فيهن هند وقد هام الفؤاد بها ... بيضاء آنسة بالحسن موسومه)\nالغناء لابن سريج رمل عن يونس والهشامي وحبش ومنها قوله\n\n(در در الشباب والشعر الأسود ... والضامرات تحت الرحال)\n(فالخناذيذ كالقداح من الشوحط ... يحملن شكة الأبطال)\n(ليس رسم على الدفين ببال ... فلوى ذروة فجنبي أثال)\n(تلك عرسي قد عيرتني خلالي ... ألبين تريد أم لدلال)\nلغناء لطويس خفيف رمل لا شك فيه وفيه ثقيل أول ذكر علي بن يحيى أنه لطويس أيضا ووجدته في صنعة عبد العزيز بن عبد الله بن طاهر وفي الثالث والرابع من الأبيات لدلال خفيف رمل بالبنصر عن عبد الله بن موسى والهشامي\n(لمن الديار كأنها لم تحلل ... بجنوب أسنمة فقف العنصل)\n(درست معالمها فباقي رسمها ... خلق كعنوان الكتاب المحول)\n(دار لسعدي إذ سعاد كأنها ... رشأ غضيض الطرف رخص المفصل)\nروضه من الكامل جنوب أسنمة أودية معروفة والقف الكثيب من الرمل ليس بالمشرف ولا الممتد والعنصل بصل معروف الشعر لربيعة بن مقروم الضبي والغناء فيه لسياط هزج بالبنصر عن الهشامي","topic":"أخبار عبيد بن الأبرص ونسبه","topicNo":272,"sp":4,"spl":"عمر بن الخطاب يبكي مع نساء بني مخزوم خالد بن الوليد","tags":[],"song":4,"loc":3644},
{"id":"b273-2","bab":"الجزء 22","sec":"أخبار ربيعة بن مقروم ونسبه — هجوه ضابئ بن الحارث","page":"ج22 ص101 – ج22 ص102","text":"هو ربيعة بن مقروم الضبي بن قيس بن جابر بن خالد بن عمرو بن عبد الله بن السيد بن مالك بن بكر بن سعد بن ضبة بن أد بن طابخة بن إلياس بن مضر بن نزار شاعر إسلامي مخضرم أدرك الجاهلية والإسلام وكان ممن أصفق عليه كسرى ثم عاش في الإسلام زمانا\nقال أبو عمرو الشيباني كان ربيعة بن مقروم باع عجرد بن عبد عمرو بن ضمرة بن جابر بن قطن بن نهشل بن درام لقحة إلى أجل فلما بايعه وجد ابن مقروم ضابئ بن الحارث عند عجرد وقد نهاه عن إنظاره بالثمن فقال ابن مقروم يعرض بضابئ إنه أعان عليه وكان ضلعه معه\n(أعجر ابن المليحة إن همي ... إذا ما لج عذالي لعان)\nوله لعان أي عان من العناء عناني الشيء يعنيني وهو لي عان\n(يرى مالا أرى ويقول قولا ... وليس على الأمور بمستعان)\n(ويحلف عند صاحبه لشاة ... أحب إلي من تلك الثمان)\n(وحامل ضب ضغن لم يضرني ... بعيد قلبه حلو اللسان)\n(ولو أني أشاء نقمت منه ... بشغب من لسان تيحان)\n(ولكني وصلت الحبل منه ... مواصلة بحبل أبي بيان)\n(ترفع في بني قطن وحلت ... بيوت المجد يبنيهن باني)\nعني حلت بنو قطن بيوت المجد\n(وضمرة إن ضمرة خير جار ... إلى قطن بأسباب متان)\n(هجان الحي كالذهب المصفى ... صبيحة ديمة يجنيه جان)\nال أبو عمرو الذهب في معدنه إذا جاءه المطر ليلا لاح من غد عند طلوع الشمس فيتتبع ويؤخذ","topic":"أخبار ربيعة بن مقروم ونسبه","topicNo":273,"sp":0,"spl":"أخبار ربيعة بن مقروم ونسبه — هجوه ضابئ بن الحارث — مدحه مسعود بن سالم الذي خلصه من الأسر","tags":["الحب والغزل","الهجاء","الوصف والطبيعة"],"loc":3645},
{"id":"b273-3","bab":"الجزء 22","sec":"مدحه مسعود بن سالم الذي خلصه من الأسر","page":"ج22 ص103","text":"قال أبو عمرو وأسر ربيعة بن مقروم واستيق ماله فتخلصه مسعود بن سالم بن أبي سلمى بن ذبيان بن عامر بن ثعلبة بن ذؤيب بن السيد فقال ربيعة بن مقروم فيه قوله\n(كفاني أبو الأشوس المنكرات ... كفاه الإله الذي يجذر)\n(أعز من السيد في منصب ... إليه العزازة والمفخر)\nقال يمدحه أيضا\n(بان الخليط فأمسى القلب معمودا ... وأخلفتك ابنة الحر المواعيدا)\n(كأنها ظبية بكر أطاع لها ... من حومل تلعات الحي أو أودا)\n(قامت تريك غداة البين منسدلا ... تجللت فوق متنيها العناقيدا)\n(وباردا طيبا عذبا مذاقته ... شربته مزجا بالظلم مشهودا)\n(وجسرة أجد تدمى مناسمها ... أعملتها بي حتى تقطع البيدا)\n(كلفتها فأتى حتما تكلفها ... ظهيرة كأجيج النار صيخودا)\n(في مهمة قذف يخشى الهلاك به ... أصداؤه لا تني بالليل تغريدا)\n(لما تشكت إلي الأين قلت لها ... لا تستريحن ما لم ألق مسعودا)\n(ما لم ألاق امرأ جزلا مواهبه ... رحب الفناء كريم الفعل محمودا)\n(وقد سمعت بقوم يحمدون فلم ... أسمع بمثلك لا حلما ولا جودا)\n(ولا عفافا ولا صبرا لنائبة ... ولا أخبر عنك الباطل السيدا)\nالسيد قبيل الممدوح من آل ضبة\n(لا حلمك الحلم موجود عليه ولا ... يلفى عطاؤك في الأقوام منكودا)\n(وقد سبقت لغايات الجواد وقد ... أشبهت آباءك الشم الصناديدا)\n(هذا ثنائي بما أوليت من حسن ... لا زلت برا قرير العين محسودا)\nال أبو عمرو كان لضابئ بن الحارث البرجمي على عجرد بن عبد عمرو دين بايعه به نعما واستخار الله في ذلك وبايعه ربيعة بن مقروم ولم يستخر الله تعالى ثم خافه ضابئ فاستجار بربيعة بن مقروم في مطالبته إياه فضمن له جواره فوفى عجرد لضابئ ولم يف لربيعة فقال ربيعة\n(أعجرد إني من أماني باطل ... وقول غدا شيخ لذاك سؤوم)\n(وإن اختلافي نصف حول محرم ... إليكم بني هند علي عظيم)\n(فلا أعرفني بعد حول محرم ... وقول خلا يشكونني فألوم)\n(ويلتمسوا ودي وعطفي بعد ما ... تناشد قولي وائل وتميم)\n(وإن لم يكن إلا اختلافي إليكم ... فإني امرؤ عرضي علي كريم)\n(فلا تفسدوا ما كان بيني وبينكم ... بني قطن إن المليم مليم)\nاجتمعت عشيرة عجرد عليه وأخذوه بإعطاء ربيعة ماله فأعطاه إياه","topic":"أخبار ربيعة بن مقروم ونسبه","topicNo":273,"sp":0,"spl":"أخبار ربيعة بن مقروم ونسبه — هجوه ضابئ بن الحارث — مدحه مسعود بن سالم الذي خلصه من الأسر","tags":["المديح","الوصف والطبيعة"],"loc":3646},
{"id":"b273-4","bab":"الجزء 22","sec":"حماد الراوية ينشد الوليد بن يزيد شعر ربيعة بن مقروم","page":"ج22 ص105","text":"أخبرني جعفر بن قدامة قال حدثني حماد بن إسحاق عن أبيه عن\nالهيثم بن عدي عن حماد الراوية قال دخلت على الوليد بن يزيد وهو مصطبح وبين يديه معبد ومالك وابن عائشة وأبو كامل وحكم الوادي وعمر الوادي يغنونه وعلى رأسه وصيفة تسقيه لم أر مثلها تماما وكمالا وجمالا فقال لي يا حماد أمرت هؤلاء أن يغنوا صوتا يوافق صفة هذه الوصيفة وجعلتها لمن وافق صفتها نحلة فما أتى أحد منهم بشيء فأنشدني أنت ما يوافق صفتها وهي لك فأنشدته قول ربيعة بن مقروم الضبي\n(دار لسعدي إذ سعاد كأنها ... رشأ غرير الطرف رخص المفصل)\n(شماء واضحة العوارض طفلة ... كالبدر من خلل السحاب المنجلي)\n(وكأنما ريح القرنفل نشرها ... أو حنوة خلطت خزامى حومل)\n(وكأن فاها بعد ما طرق الكرى ... كأس تصفق بالرحيق السلسل)\n(لو أنها عرضت لأشمط راهب ... في رأس مشرفة الذرا متبتل)\n(جآر ساعات النيام لربه ... حتى تخدد لحمه مستعمل)\n(لصبا لبهجتها وحسن حديثها ... ولهم من ناموسه بتنزل)\nقال الوليد أصبت وصفها فاخترها أو ألف دينار فاخترت الألف الدينار فأمرها فدخلت إلى حرمه وأخذت المال","topic":"أخبار ربيعة بن مقروم ونسبه","topicNo":273,"sp":1,"spl":"حماد الراوية ينشد الوليد بن يزيد شعر ربيعة بن مقروم — مختارات من شعره","tags":["الوصف والطبيعة","الرواية والكتابة"],"loc":3647},
{"id":"b273-5","bab":"الجزء 22","sec":"مختارات من شعره","page":"ج22 ص107","text":"وهذه القصيدة من فاخر الشعر وجيده وحسنه فمن مختارها ونادرها قوله\n(بل إن ترى شمطا تفرغ لمتي ... وحنا قناتي وارتقى في مسحلي)\n(ودلفت من كبر كأني خاتل ... قنصا ومن يدبب لصيد يختل)\n(فلقد أرى حسن القناة قويمها ... كالنصل أخلصه جلاء الصيقل)\n(أزمان اذ أنا والجديد إلى بلى ... تصبي الغواني ميعتي وتنقلي)\nنى بذلك معبد ثقيلا أول\n(ولقد شهدت الخيل يوم طرادها ... بسليم أوظفة القوائم هيكل)\n(متقاذف شنج النسا عبل الشوى ... سباق أندية الجياد عميثل)\n(لولا أكفكفه لكان إذا جرى ... منه العزيم يدق فأس المسحل)\n(وإذا جرى منه الحميم رأيته ... يهوي بفارسه هوي الأجدل)\n(وإذا تعلل بالسياط جيادها ... أعطاك نائيه ولم يتعلل)\n(ودعوا نزال فكنت أول نازل ... وعلام أركبه إذا لم أنزل)\n(ولقد جمعت المال من جمع امرئ ... ورفعت نفسي عن لئيم المأكل)\n(ودخلت أبنية الملوك عليهم ... ولشر قول المرء ما لم يفعل)\n(ولرب ذي حنق علي كأنما ... تغلي عداوة صدره كالمرجل)\n(أزجيته عني فأبصر قصده ... وكويته فوق النواظر من عل)\n(وأخي محافظة عصى عذاله ... وأطاع لذته معم مخول)\n(هش يراح إلى الندى نبهته ... والصبح ساطع لونه لم ينجل)\n(فأتيت حانوتا به فصبحته ... من عاتق بمزاجها لم تقتل)\n(صهباء إلياسية أغلى بها ... يسر كريم الخيم غير مبخل)\n(ومعرس عرض الرداء عرسته ... من بعد آخر مثله في المنزل)\n(ولقد أصبت من المعيشة لينها ... وأصابني منه الزمان بكلكل)\n(فإذا وذاك كأنه ما لم يكن ... إلا تذكره لمن لم يجهل)\n(ولقد أتت مائة علي أعدها ... حولا فحولا لا بلاها مبتل)\n(فإذا الشباب كمبذل أنضيته ... والدهر يبلي كل جدة مبذل)\n(هلا سألت وخبر قوم عندهم ... وشفاء غيك خابرا أن تسألي)\n(هل نكرم الأضياف إن نزلوا بنا ... ونسود بالمعروف غير تنحل)\n(ونحل بالثغر المخوف عدوه ... ونرد حال العارض المتهلل)\n(ونعين غارمنا ونمنع جارنا ... ونزين مولى ذكرنا في المحفل)\n(وإذا امرؤ منا حبا فكأنه ... مما يخاف على مناكب يذبل)\n(ومتى تقم عند اجتماع عشيرة ... خطباؤنا بين العشيرة يفصل)\n(ويرى العدو لنا دروءا صعبة ... عند النجوم منيعة المتأول)\n(وإذا الحمالة أثقلت حمالها ... فعلى سوائمنا ثقيل المحمل)\n(ونحق في أموالنا لحليفنا ... حقا يبوء به وإن لم يسأل)\nهذه جملة جمعت فيها أغاني من أشعار اليهود إذ كانت نسبتهم وأخبارهم مختلطة فمن ذلك\n(أنى تذكر زينب القلب ... وطلاب وصل عزيزة صعب)\n(ما روضة جاد الربيع لها ... موشية ما حولها جدب)\n(بألذ منها إذ تقول لنا ... سيرا قليلا يلحق الركب)\nلشعر لأوس بن ذبي القرظي والغناء لابن سريج ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وزعم عمرو أن فيه لحنا من الثقيل الأول بالوسطى لمالك وأن فيه صنعة لابن محرز ولم يجنسها","topic":"أخبار ربيعة بن مقروم ونسبه","topicNo":273,"sp":1,"spl":"حماد الراوية ينشد الوليد بن يزيد شعر ربيعة بن مقروم — مختارات من شعره","tags":[],"song":2,"loc":3648},
{"id":"b274-2","bab":"الجزء 22","sec":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم — كان ساكنو المدينة يسمون العمالقة","page":"ج22 ص110 – ج22 ص111","text":"أوس بن ذبي اليهودي رجل من بني قريظة وبنو قريظة وبنو النضير يقال لهم الكاهنان وهم من ولد الكاهن بن هارون بن عمران أخي موسى بن عمران على محمد وآله وعليهما وكانوا نزولا بنواحي يثرب بعد وفاة موسى بن عمران عليه السلام وقبل تفرق الأزد عند انفجار سيل العرم ونزول الأوس والخزرج بيثرب\nأخبرني بذلك علي بن سليمان الأخفش عن جعفر بن محمد العاصي أبي المنهال عيينة بن المنهال المهلبي عن أبي سليمان جعفر بن سعد عن العماري قال كان ساكنو المدينة في أول الدهر قبل بني إسرائيل قوما من الأمم الماضية يقال لهم العماليق وكانوا قد تفرقوا في البلاد وكانوا أهل عز وبغي شديد فكان ساكني المدينة منهم بنو هف وبنو سعد وبنو الأزرق وبنو مطروق وكان ملك الحجاز منهم رجل يقال له الأرقم ينزل ما بين تيماء\nإلى فدك وكانوا قد ملأوا المدينة ولهم بها نخل كثير وزروع وكان موسى بن عمران عليه السلام قد بعث الجنود إلى الجبابرة من أهل القرى يغزونهم فبعث موسى عليه السلام إلى العماليق جيشا من بني إسرائيل وأمرهم أن يقتلوهم جميعا إذا ظهروا عليهم ولا يستبقوا منهم أحدا فقدم الجيش الحجاز فأظهرهم الله عز و جل على العماليق فقتلوهم أجمعين إلا ابنا للأرقم فإنه كان وضيئا جميلا فضنوا به على القتل وقالوا نذهب به إلى موسى بن عمران فيرى فيه رأيه فرجعوا إلى الشام فوجدوا موسى عليه السلام قد توفي فقالت لهم بنو إسرائيل ما صنعتم فقالوا أظهرنا الله جل وعز عليهم فقتلناهم ولم يبق منهم أحد غير غلام كان شابا جميلا فنفسنا به عن القتل وقلنا نأتي به موسى عليه السلام فيرى فيه رأيه فقالوا لهم هذه معصية قد أمرتم ألا تستبقوا منهم أحدا والله لا تدخلون علينا الشام أبدا","topic":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم","topicNo":274,"sp":0,"spl":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم — كان ساكنو المدينة يسمون العمالقة","tags":["السفر والحج","الموت"],"loc":3649},
{"id":"b274-4","bab":"الجزء 22","sec":"المدينة أول استيطان اليهود — كان مع بني إسرائيل بطون من العرب","page":"ج22 ص112 – ج22 ص114","text":"فلما منعوا ذلك قالوا ما كان خيرا لنا من منازل القوم الذين قتلناهم بالحجاز نرجع إليهم فنقيم بها فرجعوا على حاميتهم حتى قدموا المدينة فنزلوها وكان ذلك الجيش أول سكنى اليهود المدينة فانتشروا في نواحي المدينة كلها إلى العالية فاتخذوا بها الآطام والأموال والمزارع ولبثوا بالمدينة زمانا طويلا\nثم ظهرت الروم على بني إسرائيل جميعا بالشام فوطئوهم وقتلوهم ونكحوا نساءهم فخرج بنو النضير وبنو قريظة وبنو بهدل هاربين منهم إلى من بالحجاز من بني إسرائيل لما غلبتهم الروم على الشام فلما فصلوا عنها بأهليهم بعث ملك الروم في طلبهم ليردهم فأعجزوه وكان ما بين الشام والحجاز مفاوز فلما بلغ طلب الروم التمر انقطعت أعناقهم عطشا فماتوا وسمي الموضع تمر الروم فهو اسمه إلى اليوم فلما قدم بنو النضير وبنو قريظة وبهدل المدينة نزلوا الغابة فوجدوها وبية فكرهوها وبعثوا رائدا أمروه أن يلتمس لهم منزلا سواها فخرج حتى أتى العالية وهي بطحان ومهزور واديان من حرة على تلاع أرض عذبة بها مياه عذبة تنبت حر الشجر فرجع إليهم فقال قد وجدت لكم بلدا طيبا نزها على حرة يصب فيها واديان على تلاع عذبة ومدرة طيبة في متأخر الحرة ومدافع الشرج\nقال فتحول القوم إليها من منزلهم ذلك فنزل بنو النضير ومن معهم على بطحان وكانت لهم إبل نواعم فاتخذوها أموالا ونزلت بنو قريظة وبهدل ومن معهم على مهزور فكانت لهم تلاعه وما سقي من بعاث وسموات فكان ممن يسكن المدينة حين نزلها الأوس والخزرج من قبائل بني إسرائيل بنو عكرمة وبنو ثعلبة وبنو محمر وبنو زغورا وبنو قينقاع وبنو زيد وبنو النضير وبنو قريظة وبنو بهدل وبنو عوف وبنو\nالفصيص فكان يسكن يثرب جماعة من أبناء اليهود فيهم الشرف والثروة والعز على سائر اليهود وكان بنو مرانة في موضع بني حارثة ولهم كان الأطم الذي يقال له الخال\nوكان معهم من غير بني إسرائيل بطون من العرب منهم بنو الحرمان حي من اليمن وبنو مرثد حي من بلي وبنو أنيف من بلي أيضا وبنو معاوية حي من بني سليم ثم من بني الحارث بن بهثة وبنو الشظية حي من غسان وكان يقال لبني قريظة وبني النضير خاصة من اليهود الكاهنان نسبوا بذلك إلى جدهم الذي يقال له الكاهن كما يقال العمران والحسنان والقمران قال كعب بن سعد القرظي\n(بالكاهنين قررتم في دياركم ... جما ثواكم ومن أجلاكم جدبا)\nقال العباس بن مرداس السلمي يرد على خوات بن جبير لما هجاهم\n(هجوت صريح الكاهنين وفيكم ... لهم نعم كانت مدى الدهر ترتبا)\nلما أرسل الله سيل العرم على أهل مأرب وهم الأزد قام رائدهم\nفقال من كان ذا جمل مفن ووطب مدن وقربة وشن فلينقلب عن بقرات النعم فهذا اليوم يوم هم وليلحق بالثني من شن قال وهو بالسراة فكان الذين نزلوه أزد شنوءة ثم\nقال لهم ومن كان ذا فاقة وفقر وصبر على أزمات الدهر فليلحق ببطن مر فكان الذين سكنوه خزاعة ثم قال لهم من كان منكم يريد الخمر والخمير والأمر والتأمير والديباج والحرير فليلحق ببصرى والحفير وهي من أرض الشام فكان الذين سكنوه غسان ثم\nقال لهم ومن كان منكم ذا هم بعيد وجمل شديد ومزاد جديد فليلحق بقصر عمان الجديد فكان الذين نزلوه أزد عمان ثم قال ومن كان يريد الراسخات في الوحل المطعمات في المحل فليلحق بيثرب ذات النخل","topic":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم","topicNo":274,"sp":1,"spl":"المدينة أول استيطان اليهود — كان مع بني إسرائيل بطون من العرب","tags":["الهجاء"],"loc":3650},
{"id":"b274-6","bab":"الجزء 22","sec":"الأوس والخزرج أول من نزلوا المدينة — أبو جبيلة أمر أن يمكر باليهود حتى يقتل رؤوسهم","page":"ج22 ص115 – ج22 ص116","text":"فكان الذين نزلوها الأوس والخزرج فلما توجهوا إلى المدينة ووردوها نزلوا في صرار ثم تفرقوا وكان منهم من لجأ إلى عفاء من أرض لا ساكن فيه فنزلوا به ومنهم من لجأ إلى قرية من قراها فكانوا مع أهلها فأقامت الأوس والخزرج في منازلهم التي نزلوها بالمدينة في جهد وضيق في المعاش ليسوا بأصحاب إبل ولا شاة لأن المدينة ليست بلاد نعم وليسوا\nبأصحاب نخل ولا زرع وليس للرجال منهم إلا الأعذاق اليسيرة والمزرعة يستخرجها من أرض موات والأموال لليهود فلبثت الأوس والخزرج بذلك حينا\nثم إن مالك بن العجلان وفد إلى جبيلة الغساني وهو يومئذ ملك غسان فسأله عن قومه وعن منزلهم فأخبره بحالهم وضيق معاشهم فقال له أبو جبيلة والله ما نزل قوم منا بلدا قط إلا غلبوا أهله عليه فما بالكم ثم أمره بالمضي إلى قومه وقال له أعلمهم أني سائر إليهم فرجع مالك بن العجلان فأخبرهم بأمر أبي جبيلة ثم قال لليهود\nإن الملك يريد زيارتكم فأعدوا نزلا فأعدوه وأقبل أبو جبيلة سائرا من الشام في جمع كثيف حتى قدم المدينة فنزل بذي حرض ثم أرسل إلى الأوس والخزرج فذكر لهم الذي قدم له وأجمع أن يمكر باليهود حتى يقتل رؤوسهم وأشرافهم وخشي إن لم يمكر بهم أن يتحصنوا في آطامهم فيمنعوا منه حتى يطول حصاره إياهم فأمر ببنيان حائر واسع فبني ثم أرسل إلى اليهود أن أبا جبيلة الملك قد أحب أن تأتوه فلم يبق وجه من وجوه القوم إلا أتاه وجعل الرجل يأتي معه بخاصته وحشمه رجاء أن يحبوهم فلما اجتمعوا ببابه أمر رجالا من جنده أن يدخلوا الحائر ويدخلوهم رجلا رجلا فلم يزل الحجاب يأذنون لهم كذلك ويقتلهم الجند الذين في الحائر حتى أتوا على آخرهم فقالت سارة القريظية ترثي من قتل منهم أبو\nجبيلة تقول\n(بنفسي أمة لم تغن شيئا ... بذي حرض تعفيها الرياح)\n(كهول من قريظة أتلفتها ... سيوف الخزرجية والرماح)\n(رزئنا والرزية ذات ثقل ... يمر لأهلها الماء القراح)\n(ولو أربو بأمرهم لجالت ... هنالك دونهم جأوا رداح)","topic":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم","topicNo":274,"sp":2,"spl":"الأوس والخزرج أول من نزلوا المدينة — أبو جبيلة أمر أن يمكر باليهود حتى يقتل رؤوسهم — مدح ا","tags":["السفر والحج"],"loc":3651},
{"id":"b274-7","bab":"الجزء 22","sec":"مدح الرمق لأبي جبيلة","page":"ج22 ص117","text":"وقال الرمق وهو عبيد بن سالم بن مالك بن عوف بن عمرو بن عوف بن الخزرج يمدح أبا جبيلة الغساني\n(لم يقض دينك في الحسان ... وقد غنيت وقد غنينا)\n(الراشقات المرشقات ... الجازيات بما جزينا)\n(أمثال غزلان الصرائم ... يأتزرن ويرتدينا)\n(الريط والديباج ... والزرد المضاعف والبرينا)\n(وأبو جبيلة خير من ... يمشي وأوفاهم يمينا)\n(وأبره برا وأعلمه ... بعلم الصالحينا)\n(أبقت لنا الأيام والحرب المهمة تعترينا ... )\n(كبشا لنا ذكرا يفل حسامه الذكر السنينا ... )\n(ومعاقلا شما وأسيافا يقمن وينحنينا ... )\n(ومحلة زوراء ترجف ... بالرجال المصلتينا)\nفلما أنشدوا أبا جبيلة ما قال الرمق أرسل إليه فجيء به وكان رجلا ضئيلا غير وضيء فلما رآه قال عسل طيب ووعاء سوء فذهبت مثلا وقال للأوس والخزرج إن لم تغلبوا على هذه البلاد بعد من قتلت من أشراف أهلها فلا خير فيكم ثم رحل إلى الشام","topic":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم","topicNo":274,"sp":2,"spl":"الأوس والخزرج أول من نزلوا المدينة — أبو جبيلة أمر أن يمكر باليهود حتى يقتل رؤوسهم — مدح ا","tags":["المديح","السفر والحج"],"loc":3652,"partial":1},
{"id":"b274-8","bab":"الجزء 22","sec":"شعر للصامت بن أصرم يذكر فيه قتل أبي جبيلة","page":"ج22 ص118","text":"وقال الصامت بن أصرم النوفلي يذكر قتل أبي جبيلة اليهود\n(سائل قريظة من يقسم سبيها ... يوم العريض ومن أفاء المغنما)\n(جاءتهم الملحاء يخفق ظلها ... وكتيبة خشناء تدعو أسلما)\n(عمي الذي جلب الهمام لقومه ... حتى أحل على اليهود الصيلما)\nعني بقوله من يقسم سبيها نسوة سباهن أبو جبيلة من بني قريظة وكان رآهن فأعجبنه وأعطى مالك بن العجلان منهم امرأة\nقال أبو المنهال أحد بني المعلى إنهم أقاموا زمنا بعد ما صنع ويهود تعترض عليهم وتناوئهم فقال مالك بن العجلان لقومه والله ما أثخنا يهود غلبة كما نريد فهل لكم أن أصنع لكم طعاما ثم أرسل في مائة من أشراف من بقي من اليهود فإذا جاؤوني فاقتلوهم جميعا فقالوا نفعل فلما جاءهم رسول مالك قالوا والله لا نأتيهم أبدا وقد قتل أبو جبيلة منا من قتل فقال لهم مالك إن ذلك كان على غير هوى منا وإنما أردنا أن نمحوه وتعلموا حالكم عندنا فأجابوه فجعل كلما دخل عليه رجل منهم أمر به مالك فقتل حتى قتل منهم بضعة وثمانين رجلا ثم إن رجلا منهم أقبل حتى قام على باب مالك فتسمع فلم يسمع صوتا فقال أرى أسرع ورد وأبعد صدر فرجع وحذر أصحابه الذين بقوا فلم يأت منهم أحد فقال رجل من اليهود لمالك بن العجلان\n(فسفهت قيلة أحلامها ... ففيمن بقيت وفيمن تسود)\nقال مالك\n(فإني امرؤ من بني سالم بن ... عوف وأنت امرء من يهود)\nال وصورت اليهود مالكا في بيعهم وكنائسهم فكانوا يلعنونه كلما دخلوها فقال مالك بن العجلان في ذلك قوله\n(تحامي اليهود بتلعانها ... تحامي الحمير بأبوالها)\n(فماذا علي بأن يلعنوا ... وتأتي المنايا بأذلالها)\nقال فلما قتل مالك من يهود من قتل ذلوا وقل امتناعهم وخافوا خوفا شديدا وجعلوا كلما هاجمهم أحد من الأوس والخزرج بشيء يكرهونه لم يمش بعضهم إلى بعض كما كانوا يفعلون قبل ذلك ولكن يذهب اليهودي إلى جيرانه الذين هو بين أظهرهم فيقول إنما نحن جيرانكم ومواليكم فكان كل قوم من يهود قد لجأوا إلى بطن من الأوس والخزرج يتعززون بهم\nوذكر أبو عمرو الشيباني أن أوس بن ذبي القرظي كانت له امرأة من بني قريظة أسلمت وفارقته ثم نازعتها نفسها إليه فأتته وجعلت ترغبه في الإسلام فقال فيها\n(دعتني إلى الإسلام يوم لقيتها ... فقلت لها لا بل تعالي تهودي)\n(فنحن على توراة موسى ودينه ... ونعم لعمري الدين دين محمد)\n(كلانا يرى أن الرسالة دينه ... ومن يهد أبواب المراشد يرشد)\nمن الأغاني في أشعار اليهود\n(أعاذلتي ألا لا تعذليني ... فكم من أمر عاذلة عصيت)\n(دعيني وارشدي إن كنت أغوى ... ولا تغوي زعمت كما غويت)\n(أعاذل قد أطلت اللوم حتى ... لواني منته لقد انتهيت)\n(وحتى لو يكون فتى أناس ... بكى من عذل عاذلة بكيت)\n(وصفراء المعاصم قد دعتني ... إلى وصل فقلت لها أبيت)\n(وزق قد جررت إلى الندامى ... وزق قد شربت وقد سقيت)\nالشعر للسموأل بن عاديا فيما رواه السكري عن الطوسي ورواه أبو خليفة عن محمد بن سلام والغناء لابن محرز خفيف ثقيل بالسبابة في مجرى الوسطى عن إسحاق في الأول والثاني والرابع والخامس من الأبيات وزعم ابن المكي أنه لمعبد وزعم عمرو بن بانة أنه لمالك ولدحمان أيضا في الأول والثاني والخامس والسادس رمل بالوسطى وزعم ابن المكي أن هذا الرمل لابن سريج وفي الأول والثاني والسادس رمل بالوسطى لأبي عبيد مولى فائد ثاني ثقيل عن يحيى المكي وزعم الهشامي أن الرمل لعبد العزيز الدفاف","topic":"أخبار أوس ونسب اليهود النازلين بيثرب وأخبارهم","topicNo":274,"sp":3,"spl":"شعر للصامت بن أصرم يذكر فيه قتل أبي جبيلة","tags":[],"song":1,"loc":3653},
{"id":"b275-2","bab":"الجزء 22","sec":"أخبار السموأل ونسبه — يضرب به المثل في الوفاء","page":"ج22 ص121 – ج22 ص122","text":"هو السموأل بن عريض بن عاديا بن حباء ذكر ذلك أبو خليفة عن محمد بن سلام والسكري عن الطوسي وابن حبيب وذكر أن الناس يدرجون عريضا في النسب وينسبونه إلى عاديا جده\nوقال عمر بن شبة هو السموأل بن عاديا ولم يذكر عريضا وحكى عبد الله بن أبي سعد عن دارم بن عقال وهو من ولد السموأل أن عاديا بن رفاعة بن ثعلبة بن كعب بن عمرو مزيقيا بن عامر ماء السماء وهذا عندي محال لأن الأعشى أدرك شريح بن السموأل وأدرك الإسلام وعمرو مزيقيا قديم لا يجوز أن يكون بينه وبين السموأل ثلاثة آباء ولا عشرة بل أكثر والله أعلم\nوقد قيل إن أمه كانت من غسان وكلهم قالوا إنه كان صاحب الحصن المعروف بالأبلق بتيماء المشهور بالوفاء وقيل بل هو من ولد الكاهن بن هارون بن عمران وكان هذا الحصن لجده عاديا واحتفر فيه بئر روية عذبة وقد ذكرته الشعراء في أشعارها قال السموأل\n(فبالأبلق الفرد بيتي به ... وبيت النضير سوى الأبلق)\nقال السموأل يذكر بناء جده الحصن\n(بنى لي عاديا حصنا حصينا ... وماء كلما شئت استقيت)\nكانت العرب تنزل به فيضيفها وتمتار من حصنه وتقيم هناك سوقا وبه يضرب المثل في الوفاء لإسلامه ابنه حتى قتل ولم يخن أمانته في أدراع أودعها","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":0,"spl":"أخبار السموأل ونسبه — يضرب به المثل في الوفاء — خبر امرئ القيس مع السموأل","tags":["الخمر"],"loc":3654},
{"id":"b275-3","bab":"الجزء 22","sec":"خبر امرئ القيس مع السموأل","page":"ج22 ص123","text":"وكان السبب في ذلك فيما ذكر لنا محمد بن السائب الكلبي أن امرأ القيس بن حجر لما سار إلى الشام يريد قيصر نزل على السموأل بن عاديا بحصنه الأبلق بعد إيقاعه ببني كنانة على أنهم بنو أسد وكراهة أصحابه لفعله وتفرقهم عنه حتى بقي وحده واحتاج إلى الهرب فطلبه المنذر بن ماء السماء ووجه في طلبه جيوشا من إياد وبهراء وتنوخ وجيشا من الأساورة أمده بهم أنو شروان وخذلته حمير وتفرقوا عنه فلجأ إلى السموأل ومعه أدراع كانت لأبيه خمسة الفضفاضة والضافية والمحصنة والخريق وأم الذيول وكانت الملوك من بني آكل المرار يتوارثونها ملك عن ملك ومعه\nبنته هند وابن عمه يزيد بن الحارث بن معاوية بن الحارث وسلاح ومال كان بقي معه ورجل من بني فزارة يقال له الربيع بن ضبع شاعر فقال له الفزاري قل في السموأل شعرا تمدحه به فإن الشعر يعجبه وأنشده الربيع شعرا مدحه به وهو يقول\n(ولقد أتيت بني المصاص مفاخرا ... وإلى السموأل زرته بالأبلق)\n(فأتيت أفضل من تحمل حاجة ... إن جئته في غارم أو مرهق)\n(عرفت له الأقوام كل فضيلة ... وحوى المكارم سابقا لم يسبق)\nال فقال امرؤ القيس فيه قصيدته\n(طرقتك هند بعد طول تجنب ... وهنا ولم تك قبل ذلك تطرق)\nال وقال الفرازي إن السموأل يمنع منك حتى يرى ذات عينك وهو في حصن حصين ومال كثير فقدم به على السموأل وعرفه إياه وأنشداه الشعر فعرف لهما حقهما وضرب على هند قبة من أدم وأنزل القوم في مجلس له براح فكانت عنده ما شاء الله ثم إن امرأ القيس سأله أن يكتب له إلى الحارث بن أبي شمر الغساني أن يوصله إلى قيصر ففعل واستصحب معه رجلا يدله على الطريق وأودع بنيه وماله وأدراعه السموأل ورحل إلى الشام وخلف ابن عمه يزيد بن الحارث مع ابنته هند\nقال ونزل الحارث بن ظالم في بعض غاراته بالأبلق ويقال بل الحارث بن أبي شمر الغساني ويقال بل كان المنذر وجه بالحارث بن ظالم في خيل وأمره بأخذ مال امرئ القيس من السموأل فلما\nنزل به تحصن منه وكان له ابن قد يفع وخرج إلى قنص له فلما رجع أخذه الحارث بن ظالم ثم قال للسموأل أتعرف هذا قال نعم هذا ابني قال أفتسلم ما قبلك أم أقتله قال شأنك به فلست أخفر ذمتي ولا أسلم مال جاري فضرب الحارث وسط الغلام فقطعه قطعتين وانصرف عنه فقال السموأل في ذلك\n(وفيت بأدرع الكندي إني ... إذا ما ذم أقوام وفيت)\n(وأوصى عاديا يوما بألا ... تهدم يا سموأل ما بنيت)\n(بنى لي عاديا حصنا حصينا ... وماء كلما شئت استقيت)","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":0,"spl":"أخبار السموأل ونسبه — يضرب به المثل في الوفاء — خبر امرئ القيس مع السموأل","tags":["المديح"],"loc":3655},
{"id":"b275-4","bab":"الجزء 22","sec":"شريح بن السموأل يخطو خطى أبيه","page":"ج22 ص125","text":"وقال الأعشى يمدح السموأل ويستجير بابنه شريح بن السموأل من رجل كلبي كان الأعشى هجاه ثم ظفر به فأسره وهو لا يعرفه فنزل بشريح بن السموأل وأحسن ضيافته ومر بالأسرى فناداه الأعشى\n(شريح لا تسلمني اليوم إذ علقت ... حبالك اليوم بعد القيد أظفاري)\n(قد سرت ما بين بلقاء إلى عدن ... وطال في العجم تكراري وتسياري)\n(فكان أكرمهم عهدا وأوثقهم ... عقدا أبوك بعرف غير إنكار)\n(كالغيث ما استمطروه جاد وابله ... وفي الشدائد كالمستأسد الضاري)\n(كن كالسموأل إذ طاف الهمام به ... في جحفل كسواد الليل جرار)\n(إذ سامه خطتي خسف فقال له ... قل ما تشاء فإني سامع حار)\n(فقال غدر وثكل أنت بينهما ... فاختر وما فيهما حظ لمختار)\n(فشك غير طويل ثم قال له ... اقتل أسيرك إني مانع جاري)\n(وسوف يعقبنيه إن ظفرت به ... رب كريم وبيض ذات أطهار)\n(لا سرهن لدينا ذاهب هدرا ... وحافظات إذا استودعن أسراري)\n(فاختار أدراعه كيلا يسب بها ... ولم يكن وعده فيها بختار)\nجاء شريح إلى الكلبي فقال له هب لي هذا الأسير المضرور فقال هو لك فأطلقه وقال له أقم عندي حتى أكرمك وأحبوك فقال له الأعشى إن تمام إحسانك إلي أن تعطيني ناقة ناجية وتخليني الساعة فأعطاه ناقة ناجية فركبها ومضى من ساعته وبلغ الكلبي أن الذي وهب لشريح هو الأعشى فأرسل إلى شريح ابعث إلي الأسير الذي وهبت لك حتى أحبوه وأعطيه فقال قد مضى فأرسل الكلبي في أثره فلم يلحقه","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":1,"spl":"شريح بن السموأل يخطو خطى أبيه — سعية بن عريض","tags":["الهجاء","المديح"],"loc":3656},
{"id":"b275-5","bab":"الجزء 22","sec":"سعية بن عريض","page":"ج22 ص127","text":"سعية بن عريض بن عاديا أخو السموأل شاعر فمن شعره الذي يغنى فيه قوله\n(يا دار سعدى بمقصى تلعة النعم ... حييت دارا على الإقواءوالقدم)\n(عجنا فما كلمتنا الدار إذ سئلت ... وما بها عن جواب خلت من صمم)\n(وما بجزعك إلا الوحش ساكنة ... وهامد من رماد القدر والحمم)\nلشعر لسعية بن عريض والغناء لابن محرز ثقيل أول بالسبابة في مجرى البنصر عن إسحاق وفيه خفيف ثقيل عن الهشامي وله فيه خفيف ثقيل عن الهشامي ويقال إنه لمالك وفيه لابن جؤذرة رمل عن الهشامي وسعية بن عريض القائل وفيه غناء\n\n(لباب هل عندك من نائل ... لعاشق ذي حاجة سائل)\n(عللته منك بما لم ينل ... يا ربما عللت بالباطل)\nلغناء لابن سريج رمل بالسبابة في مجرى الوسطى عن إسحاق وفيه لابن الهربذ خفيف رمل بالوسطى عن عمرو وفيه لمتيم رمل آخر من جامعها وفيه لحن ليونس غير مجنس وأول هذه القصيدة\n(لباب يا أخت بني مالك ... لا تشتري العاجل بالآجل)\n(لباب داويني ولا تقتلي ... قد فضل الشافي على القاتل)\n(إن تسألي بي فاسألي خابرا ... والعلم قد يكفي لدى السائل)\n(ينبيك من كان بنا عالما ... عنا وما العالم كالجاهل)\n(أنا إذا حارت دواعي الهوى ... وأنصت السامع للقائل)\n(واعتلج القوم بألبابهم ... في المنطق الفاصل والنائل)\n(لا نجعل الباطل حقا ولا ... نلظ دون الحق بالباطل)\n(نخاف أن تسفه أحلامنا ... فنخمل الدهر مع الخامل)\nخبرني محمد بن خلف وكيع قال حدثني أحمد بن الهيثم الفراسي قال حدثني العمري عن العتبي قال كان معاوية يتمثل كثيرا إذا اجتمع الناس في مجلسه بهذا الشعر\n(إنا إذا مالت دواعي الهوى ... وأنصت السامع للقائل)\n(لا نجعل الباطل حقا ولا ... نلظ دون الحق بالباطل)\n(نخاف أن تسفه أحلامنا ... فنخمل الدهر مع الخامل)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال أخبرني عبد الملك بن عبد العزيز قال أخبرني خالي يوسف بن الماجشون قال كان عبد الملك بن مروان إذا جلس للقضاء بين الناس أقام وصيفا على رأسه ينشده\n(إنا إذا مالت دواعي الهوى ... وأنصت السامع للقائل)\n(واصطرع القوم بألبابهم ... نقضي بحكم عادل فاصل)\n(لا نجعل الباطل حقا ولا ... نلظ دون الحق بالباطل)\n(نخاف أن تسفه أحلامنا ... فنخمل الدهر مع الخامل)\nثم يجتهد عبد الملك في الحق بين الخصمين","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":1,"spl":"شريح بن السموأل يخطو خطى أبيه — سعية بن عريض","tags":["الحب والغزل"],"song":2,"loc":3657},
{"id":"b275-6","bab":"الجزء 22","sec":"إخوانه ينقطعون عنه في افتقاره ويعودون عند اغتنائه","page":"ج22 ص129","text":"أخبرني وكيع والحسن بن علي قالا حدثنا أبو قلابة قال حدثنا الأصمعي عن أبي الزناد عن أبيه عن رجال من الأنصار\nأن سعية بن عربض أخا السموأل بن عاديا كان ينادم قوما من الأوس والخزرج ويأتونه فيقيمون عنده ويزورونه في أوقات قد ألف زيارتهم فيها فأغار عليه بعض ملوك اليمن فانتسف من ماله حتى افتقر ولم\nيبق له مال فانقطع عنه إخوانه وجفوه فلما أخصب وعادت حاله وتراجعت راجعوه فقال في ذلك\n(أرى الخلان لما قل مالي ... وأجحفت النوائب ودعوني)\n(فلما أن غنيت وعاد مالي ... أراهم لا أبالك راجعوني)\n(وكان القوم خلانا لمالي ... وإخوانا لما خولت دوني)\n(فلما مر مالي باعدوني ... ولما عاد مالي عاودوني)\nمن أشعار اليهود ويغنى به\n(هل تعرف الدار خف ساكنها ... بالحجر فالمستوى إلى ثمد)\n(دار لبهنانة خدلجة ... تضحك عن مثل جامد البرد)\n(نعم ضجيج الفتى إذا برد الليل ... وغارت كواكب الأسد)\n(يا من لقلب متيم سدم ... عان رهين أحيط بالعقد)\n(أزجره وهو غير مزدجر ... عنها وطرفي مقارن السهد)\n(تمشي الهوينا إذا مشت فضلا ... مشى النزيف المبهور في صعد)\n(تظل من زور بيت جارتها ... واضعة كفها على الكبد)\nلشعر لأبي الزناد اليهودي العديمي والغناء لابن مسجح ثقيل أول بالوسطى في الثلاثة الأبيات الأول عن الهشامي ويحيى المكي وفيها لمعبد خفيف ثقيل أول عن الهشامي وقال أظنه من منحول يحيى بن المكي وقد نسب قوم هذا اللحن المنسوب إلى معبد إلى ابن مسجح ولابن محرز في يا من لقلب وما بعده خفيف ثقيل مطلق في مجرى الوسطى عن إسحاق وذكر عمرو أن فيها لحنا لمعبد لم يذكر طريقته وذكر ذلك في -","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":2,"spl":"إخوانه ينقطعون عنه في افتقاره ويعودون عند اغتنائه — أخبار الربيع بن أبي الحقيق — لقاؤه بال","tags":["اللهو والمزاح"],"song":1,"loc":3658},
{"id":"b275-7","bab":"الجزء 22","sec":"كتاب عملة الواثق","page":"ج22 ص131","text":"- قديما غير مجنس وهذا الشعر يقوله أبو الزناد في أهل تيماء يرثيهم وذكر ذلك عمر بن شبة\nومن الغناء في أشعار اليهود من قريظة والنضير\n\n(دور عفت بقرى الخابور غيرها ... بعد الأنيس سوافي الريح والمطر)\n(إن تمس دارك ممن كان ساكنها ... وحشا فذلك صرف الدهر والغير)\n(وقد تحل بها بيض ترائبها ... كأنها بين كثبان النقا البقر)\nلشعر للربيع بن أبي الحقيق روى ذلك السكري عن الطوسي وعن محمد بن حبيب والغناء لابن محرز خفيف ثقيل أول بالوسطى عن عمرو وهو صوت مشهور ابتداؤه نشيد","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":2,"spl":"إخوانه ينقطعون عنه في افتقاره ويعودون عند اغتنائه — أخبار الربيع بن أبي الحقيق — لقاؤه بال","tags":["الوصف والطبيعة"],"song":1,"loc":3659},
{"id":"b275-9","bab":"الجزء 22","sec":"أخبار الربيع بن أبي الحقيق — لقاؤه بالنابغة الذبياني","page":"ج22 ص132 – ج22 ص133","text":"كان الربيع من شعراء اليهود من بني قريظة وهم وبنو النضير جميعا من ولد هارون بن عمران يقال لهما الكاهنان وكان الربيع أحد الرؤساء في يوم حرب بعاث وكان حليفا للخزرج هو وقومه فكانت رياسة بني قريظة للربيع ورياسة الخزرج لعمرو بن النعمان البياضي وكان رئيس بني النضير يومئذ سلام بن مشكم\nأخبرني عمي ومحمد بن حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن الحسن الأنصاري قال حدثني الحسن بن موسى مولى بني مازن بن النجار عن أبي عبيدة قال أقبل النابغة الذبياني يريد سوق بني قينقاع فلحقه الربيع بن أبي الحقيق نازلا من أطمة فلما أشرفا على السوق سمعا الضجة وكانت\nسوقا عظيمة فحاصت بالنابغة ناقته فأنشأ يقول\n(كادت تهال من الأصوات راحلتي ... )\nم قال للربيع بن أبي الحقيق أجز يا ربيع فقال\n(والنفر منها إذا ما أوجست خلق ... )\nقال النابغة ما رأيت كاليوم شعرا ثم قال\n(لولا أنهنهها بالسوط لاجتذبت ... )\nجز يا ربيع فقال\n(مني الزمام وإني راكب لبق ... )\nقال النابغة\n(قد ملت الحبس في الآطام واستعفت ... )\nجز يا ربيع فقال\n(إلى مناهلها لو أنها طلق ... )\nقال النابغة أنت يا ربيع أشعر الناس","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":2,"spl":"إخوانه ينقطعون عنه في افتقاره ويعودون عند اغتنائه — أخبار الربيع بن أبي الحقيق — لقاؤه بال","tags":["الحب والغزل","الرواية والكتابة"],"loc":3660,"partial":1},
{"id":"b275-10","bab":"الجزء 22","sec":"أبان بن عثمان يتمثل دائما بشعره","page":"ج22 ص134","text":"حدثنا أحمد بن عبد العزيز الجوهري ومحمد بن العباس اليزيدي قالا حدثنا عمر بن شبة قال حدثني الحزامي قال حدثني سعيد بن\nمحمد الزبيري قال حدثنا ابن أبي الزناد عن أبيه قال قل ما جلست إلى أبان بن عثمان إلا سمعته يتمثل بأبيات ابن أبي الحقيق\n(سئمت وأمسيت رهن الفراش من جرم قومي ومن مغرم ... )\n(ومن سفه الرأي بعد النهى ... وغيب الرشاد ولم يفهم)\n(فلو أن قومي أطاعوا الحليم ... لم يتعدوا ولم نظلم)\n(لكن قومي أطاعوا الغواة ... حتى تعكص أهل الدم)\n(فأودى السفيه برأي الحليم ... وانتشر الأمر لم يبرم)\nأخبرني هاشم بن محمد الخزاعي قال حدثنا معاذ عن أبي عبيدة قال قال الربيع بن أبي الحقيق يعاتب قوما من الأنصار في شيء بينهم وبينه\n(رأيت بني العنقاء زالوا وملكهم ... وآبوا بأنف في العشيرة مرغم)\n(فإن يقتلوا نندم لذاك وإن بقوا ... فلا بد يوما من عقوق ومأتم)\n(وإنا فويق الرأس شؤبوب مزنة ... لها برد ما يغش م الأرض يحطم)\n\n(ولنا بئر رواء جمة ... من يردها بإناء يغترف)\n(تدلج الجون على أكنافها ... بدلاء ذات أمراس صدف)\n(كل حاجاتي قد قضيتها ... غير حاجاتي من بطن الجرف)\nلشعر لكعب بن الأشرف اليهودي والغناء لمالك ثقيل أول عن يحيى المكي قال وفيه لابن عائشة خفيف ثقيل ولمعبد ثاني ثقيل قال يحيى في كتابه وقد خلط الرواة في ألحانهم ونسبوا لحن كل واحد منهم إلى صاحبه وذكر الهشامي أن فيه لابن جامع خفيف رمل بالبنصر وفيه لجعدب لحن من كتاب إبراهيم غير مجنس","topic":"أخبار السموأل ونسبه","topicNo":275,"sp":3,"spl":"أبان بن عثمان يتمثل دائما بشعره","tags":[],"song":1,"loc":3661,"partial":1},
{"id":"b276-2","bab":"الجزء 22","sec":"أخبار كعب ونسبه ومقتله — ذكر خبره في ذلك","page":"ج22 ص136 – ج22 ص137","text":"كعب بن الأشرف مختلف في نسبه فزعم ابن حبيب أنه من طيىء وأمه من بني النضير وأن أباه توفي وهو صغير فحملته أمه إلى أخواله فنشأ فيهم وساد وكبر أمره وقيل بل هو من بني النضير وكان شاعرا فارسا وله مناقضات مع حسان بن ثابت وغيره في الحروب التي كانت بين الأوس والخزرج تذكر في مواضعها إن شاء الله تعالى وهو شاعر من شعراء اليهود فحل فصيح وكان عدوا للنبي يهجوه ويهجو أصحابه ويخذل منه العرب فبعث النبي نفرا من أصحابه فقتلوه في داره\nكان كعب بن الأشرف يهجو النبي ويحرض عليه كفار قريش في شعره وكان النبي قدم المدينة وهي أخلاط منهم المسلمون الذين تجمعهم دعوة النبي ومنهم المشركون الذين يعبدون الأوثان ومنهم اليهود وهم أهل الحلقة والحصون وهم حلفاء الحيين الأوس\nوالخزرج فأراد النبي إذ قدم استصلاحهم كلهم وكان الرجل يكون مسلما وأبوه مشرك ويكون مسلما وأخوه مشرك وكان المشركون واليهود حين قدم النبي يؤذونه وأصحابه أشد الأذى فأمر الله نبيه والمسلمين بالصبر على ذلك والعفو عنهم وأنزل في شأنهم ( ولتسمعن من الذين أوتوا الكتاب من قبلكم\nالآية وأنزل فيهم ( ود كثير من أهل الكتاب لو يردونكم من بعد إيمانكم\nإلى قوله ( واصفحوا\nفلما أبى كعب بن الأشرف أن ينزع عن أذى النبي وأصحابه أمر النبي سعد بن معاذ أن يبعث إليه رهطا فيقتلوه فبعث إليه محمد بن مسلمة وأبا عبس بن جبير والحارث بن أخي سعد في خمسة رهط فأتوه عشية وهو في مجلس قومه بالعوالي فلما رآهم كعب أنكر شأنهم وكان يذعر منهم فقال لهم ما جاء بكم فقالوا جئنا لنبيعك أدراعا نستنفق أثمانها فقال والله لئن فعلتم ذلك لقد جهدتم مذ نزل بكم هذا الرجل ثم واعدهم أن يأتوه عشاء حين تهدأ أعين الناس فجاؤوا فناداه رجل منهم فقام ليخرج فقالت امرأته ما طرقوك ساعتهم هذه بشيء مما تحب فقال بلى إنهم قد حدثوني حديثهم وخرج إليهم فاعتنقه أبو عبس وضربه محمد بن مسلمة بالسيف في خاصرته وانحنوا عليه حتى قتلوه فرعبت اليهود ومن كان معهم من المشركين وغدوا على النبي فقالوا قد طرق صاحبنا الليلة وهو سيد من سادتنا فقتل فذكر لهم ما كان يؤذى به في أشعاره ودعاهم إلى أن يكتب بينهم وبين\nالمسلمين كتابا فكتبت الصحيفة بذلك في دار الحارث وكانت بعد النبي عند علي بن أبي طالب رضي الله عنه\n(هل بالديار التي بالقاع من أحد ... باق فيسمع صوت المدلج الساري)\n(تلك المنازل من صفراء ليس بها ... نار تضيء ولا أصوات سمار)\nيروى ليس بها حي يجيب الشعر لبيهس الجرمي والغناء لأحمد بن المكي ثقيل أول بالوسطى عن الهشامي وقال عمرو بن بانة فيه ثاني ثقيل بالبنصر يقال إنه لابن محرز وقال الهشامي فيه لحباب بن إبراهيم خفيف ثقيل وهو مأخوذ من لحن ابن صاحب الوضوء\n(ارفع ضعيفك لا يحر بك ضعفه ... )","topic":"أخبار كعب ونسبه ومقتله","topicNo":276,"sp":0,"spl":"أخبار كعب ونسبه ومقتله — ذكر خبره في ذلك","tags":[],"song":1,"loc":3662,"partialRef":{"sid":"b21-13","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b277-2","bab":"الجزء 22","sec":"أخبار بيهس ونسبه — اختلاف الرواة في أمر صفراء خليلته","page":"ج22 ص139 – ج22 ص140","text":"بيهس بن صهيب بن عامر بن عبد الله بن نائل بن مالك بن عبيد بن علقمة بن سعيد بن كثير بن غالب بن عدي بن بيهس بن طرود بن قدامة بن جرم بن ربان بن حلوان بن عمران بن الحاف بن قضاعة ويكنى أبا المقدام شاعر فارس شجاع من شعراء الدولة الأموية وكان يبدو بنواحي الشام مع قبائل جرم وكلب وعذرة ويحضر إذا حضروا فيكون بأجناد الشام وكان مع المهلب بن أبي صفرة في حروبه للأزارقة وكانت له مواقف مشهورة وبلاء حسن وبعض أخباره في ذلك يذكر بعقب أخباره في هذا الشعر\nوقد اختلف الرواة في أمر صفراء التي ذكرها في شعره هذا فذكر\nالقحذمي أنها كانت زوجته وولدت له ابنا ثم طلقها فتزوجت رجلا من بني أسد وماتت عنده فرثاها وذكر أبو عمرو الشيباني أنها كانت بنت عمه دنية وأنه كان يهواها فلم يزوجها وخطبها الأسدي وكان موسرا فزوجها\nقال أبو عمرو وكان بيهس بن صهيب الجرمي يهوى امرأة من قومه يقال لها صفراء بنت عبد الله بن عامر بن عبد الله بن نائل وهي بنت عمه دنية وكان يتحدث إليها ويجلس في بيتها ويكتم وجده بها ولا يظهره لأحد ولا يخطبها لأبيها لأنه كان صعلوكا لا مال له فكان ينتظر أن يثري وكان من أحسن الشباب وجها وشارة وحديثا وشعرا فكان نساء الحي يتعرضن له ويجلسن إليه ويتحدثن معه فمرت به صفراء فرأته جالسا مع فتاة منهن فهجرته زمانا لا تجيبه إذا دعاها ولا تخرج إليه إذا زارها وعرض له سفر فخرج إليه ثم عاد وقد زوجها أبوها رجلا من بني أسد فأخرجها وانتقل عن دارهم بها فقال بيهس بن صهيب\n(سقى دمنة صفراء كانت تحلها ... بنوء الثريا طلها وذهابها)\n(وصاب عليها كل أسحم هاطل ... ولا زال مخضرا مريعا جنابها)\n(أحب ثرى أرض إلي وإن نأت ... محلك منها نبتها وترابها)\n(على أنها غضبى علي وحبذا ... رضاها إذا ما أرضيت وعتابها)\n(وقد هاج لي حينا فراقك غدوة ... وسعيك في فيفاء تعوي ذئابها)\n(نظرت وقد زال الحمول ووازنوا ... بركوة والوادي وخفت ركابها)\n(فقلت لأصحابي أبالقرب منهم ... جرى الطير أم نادى ببين غرابها)","topic":"أخبار بيهس ونسبه","topicNo":277,"sp":0,"spl":"أخبار بيهس ونسبه — اختلاف الرواة في أمر صفراء خليلته — رثاؤه صفراء","tags":["الجواري والنساء","السفر والحج"],"loc":3663},
{"id":"b277-3","bab":"الجزء 22","sec":"رثاؤه صفراء","page":"ج22 ص142","text":"قال أبو عمرو ثم ماتت صفراء قبل أن يدخل بها زوجها فقال بيهس يرثيها\n(هل بالديار التي بالقاع من أحد ... باق فيسمع صوت المدلج الساري)\n(تلك المنازل من صفراء ليس بها ... نار تضيء ولا أصوات سمار)\n(عفت معارفها هوج مغبرة ... تسفي عليها تراب الأبطح الهاري)\n(حتى تنكرت منها كل معرفة ... إلا الرماد نخيلا بين أحجار)\n(طال الوقوف بها والعين تسبقني ... فوق الرداء بوادي دمعها الجاري)\n(إن أصبح اليوم لا أهل ذوو لطف ... ألهو لديهم ولا صفراء في الدار)\n(أرعى بعيني نجوم الليل مرتقبا ... يا طول ذلك من هم وإسهار)\n(فقد يكون لي الأهل الكرام وقد ... ألهو بصفراء ذات المنظر الواري)\n(من المواجد أعراقا إذا نسبت ... لا تحرم المال عن ضيف وعن جار)\n(لم تلق بؤسا ولم يضرر بها عوز ... ولم تزخف مع الصالي إلى النار)\n(كذلك الدهر إن الدهر ذو غير ... على الأنام وذو نقض وإمرار)\n(قد كاد يعتادني من ذكرها جزع ... لولا الحياء ولولا رهبة العار)\n(سقى الإله قبورا في بني أسد ... حول الربيعة غيثا صوب مدرار)\n(من الذي بعدكم أرضى به بدلا ... أو من أحدث حاجاتي وأسراري)","topic":"أخبار بيهس ونسبه","topicNo":277,"sp":0,"spl":"أخبار بيهس ونسبه — اختلاف الرواة في أمر صفراء خليلته — رثاؤه صفراء","tags":["الوصف والطبيعة","الموت"],"loc":3664},
{"id":"b277-4","bab":"الجزء 22","sec":"ينشد على قبرها","page":"ج22 ص143","text":"قال أبو عمرو واجتاز بيهس في بلاد بني أسد فمر بقبر صفراء وهو في موضع يقال له الأحض ومعه ركب من قومه وكانوا قد انتجعوا بلاد بني أسد فأوسعوا لهم وكان بينهم صهر وحلف فنزل بيهس على القبر فقال له أصحابه ألا ترحل فقال أما والله حتى أظل نهاري كله عنده وأقضي وطرا فنزلوا معه عند قبرها فأنشأ يقول وهو يبكي\n(ألما على قبر لصفراء فاقرآ ... السلام وقولا حينا أيها القبر)\n(وما كان شيئا غير أن لست صابرا ... دعاءك قبرا دونه حجج عشر)\n(برابية فيها كرام أحبة ... على أنها إلا مضاجعهم قفر)\n(عشية قال الركب من غرض بنا ... تروح أبا المقدام قد جنح العصر)\n(فقلت لهم يوم قليل وليلة ... لصفراء قد طال التجنب والهجر)\n(وبت وبات الناس حولي هجدا ... كأن علي الليل من طوله شهر)\n(إذا قلت هذا حين أهجع ساعة ... تطاول بي ليل كواكبه زهر)\n(أقول إذا ما الجنب مل مكانه ... أشوك يجافي الجنب أم تحته جمر)\n(فلو أن صخرا من عماية راسيا ... يقاسي الذي ألقى لقد مله الصخر)\nال وأما القحذمي فإنه ذكر فيما أخبرني به هاشم بن محمد الخزاعي عن عيسى بن إسماعيل تينة عنه أنه كان تزوجها ثم طلقها بعد أن ولدت منه ابنا فتزوجها رجل من بني أسد فماتت عنده\nوذكر من شعره ومراثيه لها قريبا مما تقدم ذكره وذكر أن بيهس بن صهيب كان من فرسان العرب وكان مع المهلب بن أبي صفرة في حروبه للأزارقة وكان يبدو بنواحي الشام مع قبائل جرم وكلب ويحضر إذا حضروا فيكون من أجناد الشام\nقال أبو عمرو ولما هدأت الفتنة بعد مرج راهط وسكن الناس مر غلام من قيس بطوائف من جرم وعذرة وكلب وكانوا متجاورين على ماء لهم فيقال إن بعض أحداثهم نخس بيهس به ناقته فألقته فاندقت عنقه فمات فاستعدى قومه عليهم عبد الملك فبعث إلى تلك البطون من جاءه بوجوههم وذوي الأخطار منهم فحبسهم وهرب بيهس بن صهيب الجرمي وكان قد اتهم أنه هو الذي نخس به فنزل على محمد بن مروان\nفعاذ به واستجاره فأجاره إلا من حد توجبه عليه شهادة فرضي بذلك وقال وهو متوار عند محمد\n(لقد كانت حوادث معضلات ... وأيام أغصت بالشراب)\n(وما ذنب المعاشر في غلام ... تقطر بين أحواض الجباب)\n(على قوداء أفرطها جلال ... وغض فهي باقية الهباب)\n(ترامت باليدين فأرهقته ... كما زل النطيح من القباب)\n(فإني والعقاب وما أرجي ... لكالساعي إلى وضح السراب)\n(فلما أن دنا فرج بربي ... يكشف عن مخفقة يباب)\n(من البلدان ليس بها غريب ... تخب بأرضها زل الذئاب)\n(فظني بالخليفة أن فيه ... أمانا للبريء وللمصاب)\n(وأن محمدا سيعود يوما ... ويرجع عن مراجعة العتاب)\n(فيجبر صبيتي ويحوط جاري ... ويؤمن بعدها أبدا صحابي)\n(هو الفرع الذي بنيت عليه ... بيوت الأطيبين ذوي الحجاب)\nال فلم يزل محمد بن مروان قائما وقاعدا في أمرهم مع أخيه حتى أمن بيهس بن صهيب وعشيرته واحتمل دية المقتول لقيس وأرضاهم\n\n(نزل المشيب فما له تحويل ... ومضى الشباب فما إليه سبيل)\n(ولقد أراني والشباب يقودني ... ورداؤه حسن علي جميل)\nلشعر للكميت بن معروف الأسدي والغناء لمعبد خفيف ولحنه من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى الوسطى عن إسحاق","topic":"أخبار بيهس ونسبه","topicNo":277,"sp":1,"spl":"ينشد على قبرها","tags":["السفر والحج"],"song":1,"loc":3665},
{"id":"b278-2","bab":"الجزء 22","sec":"أخبار الكميت بن معروف ونسبه — هو سليل أسرة من الشعراء","page":"ج22 ص146 – ج22 ص147","text":"هو الكميت بن معروف بن الكميت بن ثعلبة بن رباب بن الأشتر بن جحوان بن فقعس بن طري بن عمرو بن قعين بن الحارث بن ثعلبة بن دودان بن أسد بن خزيمة بن مدركة بن إلياس بن مضر شاعر من شعراء الإسلام بدوي أمه سعدة بنت فريد بن خيثمة بن نوفل بن نضلة\nوالكميت أحد المعرقين في الشعر أبوه معروف شاعر وأمه سعدة شاعرة وأخوه خيثمة أعشى بني أسد شاعر وابنه معروف الكميت شاعر فأما أبوه فهو القائل لعبد الله بن المساور بن هند\n(إن مناخي أمس يا بن مساور ... إليك لمن شرب النقاخ المصرد)\n(تباعدت فوق الحق من آل فقعس ... ولم ترج فيهم ردة اليوم أو غد)\n(وقلت غنى لا فقر في العيش بعده ... وكل فتى للنائبات بمرصد)\n(كأنك لم تعلم محل بيوتكم ... مع الحي بين الغور والمتنجد)\n(فلولا رجال من جذيمة قصرة ... عددت بلائي ثم قلت له عدد)\nأمه سعدة القائلة له وقد تزوج بنت أبي مهوش على مراغمة لها وكراهة لذلك فغضبت سعدة وقالت فيه\n(عليك بأنقاض العراق فقد علت ... عليك بتخدين النساء الكرائم)\n(لعمري لقد راش ابن سعدة نفسه ... بريش الذنابى لا بريش القوادم)\n(بنى لك معروف بناء هدمته ... وللشرف العادي بان وهادم)\nهي القائلة ترثي ابنها الكميت\n(لأم البلاد الويل ماذا تضمنت ... بأكناف طورى من عفاف ونائل)\n(ومن وقعات بالرجال كأنها ... إذا عنت الأحداث وقع المناصل)\n(يعزي المعزى عن كميت فتنتهي ... مقالته والصدر جم البلابل)","topic":"أخبار الكميت بن معروف ونسبه","topicNo":278,"sp":0,"spl":"أخبار الكميت بن معروف ونسبه — هو سليل أسرة من الشعراء — وابنه يتغزل","tags":["الجواري والنساء"],"loc":3666},
{"id":"b278-3","bab":"الجزء 22","sec":"أخوه يرثيه","page":"ج22 ص148","text":"وأعشى بني أسد أخو الكميت واسمه خيثمة الذي يقول يرثي الكميت وغيره من أهل بيته\n(هون عليك فإن الدهر منجدب ... كل امرئ عن أخيه سوف ينشعب)\n(فلا يغرنك من دهر تقلبه ... إن الليالي بالفتيان تنقلب)\n(نام الخلي وبت الليل مرتفقا ... كما تزاور يخشى دفه النكب)\n(إذا رجعت إلى نفسي أحدثها ... عمن تضمن من أصحابي القلب)\n(من إخوة وبني عم رزئتهم ... والدهر فيه على مستعتب عتب)\n(عاودت وجدا على وجد أكابده ... حتى تكاد بنات الصدر تلتهب)\n(هل بعد صخر وهل بعد الكميت أخ ... أم هل يعود لنا دهر فنصطحب)\n(لقد علمت ولو مليت بعدهم ... أني سأنهل بالشرب الذي شربوا)","topic":"أخبار الكميت بن معروف ونسبه","topicNo":278,"sp":0,"spl":"أخبار الكميت بن معروف ونسبه — هو سليل أسرة من الشعراء — وابنه يتغزل","tags":["الوصف والطبيعة"],"loc":3667},
{"id":"b278-4","bab":"الجزء 22","sec":"وابنه يتغزل","page":"ج22 ص149","text":"ومعروف بن الكميت القائل\n(قد كنت أحسبني جلدا فهيجني ... بالشيب منزلة من أم عمار)\n(كانت منازل لا ورهاء جافية ... على الحدوج ولا عطلا بمقفار)\n(وما تجاورنا إذ نخن نسكنها ... ولا تفرقنا إلا بمقدار)\n\n(أرقت لبرق دونه شذوان ... يمان وأهوى البرق كل يماني)\n(فليت القلاص الأدم قد وخدت بنا ... بواد يمان ذي ربا ومجاني)\nلشعر ليعلى الأحول الأزدي وجدت ذلك بخط أبي العباس محمد بن يزيد المبرد في شعر الأزد وقال عمرو بن أبي عمرو الشيباني عن أبيه هي ليعلى الأحول كما روى غيره قال ويقال إنها لعمرو بن أبي عمارة الأزدي من بني خنيس ويقال إنها لجواس بن حيان من أزد عمان وأول هذه القصيدة في رواية أبي عمرو أبيات فيها غناء أيضا وهي\n(أويحكما يا واشيي أم معمر ... بمن وإلى من جئتما تشيان)\n(بمن لو أراه عانيا لفديته ... ومن لو رآني عانيا لفداني)\nعريب في هذين البيتين ثقيل أول ولعمرو بن بانة فيهما هزج بالوسطى من كتابه وجامع صنعته وقال ابن المكي لمحمد بن الحسن بن مصعب فيه هزج بالأصابع كلها","topic":"أخبار الكميت بن معروف ونسبه","topicNo":278,"sp":0,"spl":"أخبار الكميت بن معروف ونسبه — هو سليل أسرة من الشعراء — وابنه يتغزل","tags":["اللهو والمزاح"],"song":2,"loc":3668},
{"id":"b279-3","bab":"الجزء 22","sec":"أخبار يعلى ونسبه — كان خليعا يجمع الصعاليك — شعره في سجنه","page":"ج22 ص150 – ج22 ص151 – ج22 ص152","text":"يعلى الأحول بن مسلم بن أبي قيس أحد بني يشكر بن عمرو بن رالان ورالان هو يشكر ويشكر لقب لقب به بن عمران بن عمرو بن عدي بن حارثة بن لوذان بن كهف الظلام هكذا وجدته بخط المبرد بن ثعلبة بن عمرو بن عامر\nشاعر إسلامي لص من شعراء الدولة الأموية وقال هذه القصيدة وهو محبوس بمكة عند نافع بن علقمة الكناني في خلافة عبد الملك بن مروان قال أبو عمرو وكان يعلى الأحول الأزدي لصا فاتكا خاربا وكان خليعا يجمع صعاليك الأزد وخلعاءهم فيغير بهم على أحياء العرب ويقطع الطريق على السابلة فشكي إلى نافع بن علقمة بن الحارث بن محرث الكناني ثم الفقيمي وهو خال مروان بن الحكم وكان والي مكة فأخذ به عشيرته الأزديين فلم ينفعه ذلك واجتمع إليه شيوخ الحي فعرفوه\nأنه خلع قد تبرؤوا منه ومن جرائره إلى العرب وأنه لو أخذ به سائر الأزد ما وضع يده في أيديهم فلم يقبل ذلك منهم وألزمهم إحضاره وضم إليهم شرطا يطلبونه إذا طرق الحي حتى يجيئوه به فلما اشتد عليهم في أمره طلبوه حتى وجدوه فأتوا به فقيده وأودعه الحبس فقال في محبسه\n(أرقت لبرق دونه شذوان ... يمان وأهوى البرق كل يمان)\n(فبت لدى البيت الحرام أشيمه ... ومطواي من شوق له أرقان)\nلمطو الصاحب\n(إذا قلت شيماه يقولان والهوى ... يصادف منا بعض ما تريان)\n(جرى منه أطراف الشرى فمشيع ... فأبيان فالحيان من دمران)\n(فمران فالأقباص أقباص أملج ... فماوان من واديهما شطنان)\n(هنالك لو طوفتما لوجدتما ... صديقا من إخوان بها وغوان)\n(وعزف الحمام الورق في ظل أيكة ... وبالحي ذي الرودين عزف قيان)\n(ألا ليت حاجاتي اللواتي حبسنني ... لدى نافع قضين منذ زمان)\n(وما بي بغض للبلاد ولا قلى ... ولكن شوقا في سواه دعاني)\n(فليت القلاص الأدم قد وخدت بنا ... بواد يمان ذي ربا ومجاني)\n(بواد يمان ينبت السدر صدره ... وأسفله بالمرخ والشبهان)\n(يدافعنا من جانبيه كليهما ... عزيفان من طرفائه هدبان)\n(وليت لنا بالجوز واللوز غيلة ... جناها لنا من بطن حلية جاني)\nلغيلة شجر الأراك إذا كانت رطبة ويروى في موضع من بطن حلية من حب جيحة\n(وليت لنا بالديك مكاء روضة ... على فنن من بطن حلية داني)\n(وليت لنا من ماء حزنة شربة ... مبردة باتت على طهمان)\nيروى من ماء حمياء\n(إن السلام وحسن كل تحية ... تغدو على ابن مجزز وتروح)\n(هلا فدى ابن مجزز متفحش ... شنج اليدين على العطاء شحيح)\nالشعر لجواس العذري والغناء لسائب بن خاثر خفيف ثقيل بالوسطى عن يحيى المكي والهشامي من رواية حماد عن أبيه في أخبار سائب خاثر وأغانيه","topic":"أخبار يعلى ونسبه","topicNo":279,"sp":0,"spl":"أخبار يعلى ونسبه — كان خليعا يجمع الصعاليك — شعره في سجنه","tags":["الحب والغزل"],"song":1,"loc":3669},
{"id":"b280-2","bab":"الجزء 22","sec":"نسب جواس وخبره في هذا الشعر — احتكم هو وجميل إلى يهود تيماء","page":"ج22 ص154 – ج22 ص155","text":"هو جواس بن قطبة العذري أحد بني الأحب رهط بثينة وجواس وأخوه عبد الله الذي كان يهاجي جميلا ابنا عمها دنية وهما ابنا قطبة بن ثعلبة بن الهون بن عمرو بن الأحب بن حن بن ربيعة بن حرام بن عتبة بن عبيد بن كثير بن عجرة\nوكان جواس شريفا في قومه شاعرا فذكر أبو عمرو الشيباني أن جميل بن عبد الله بن معمر لما هاجى جواسا تنافرا إلى يهود تيماء فقالوا لجميل يا جميل قل في نفسك ما شئت فأنت والله الشاعر الجميل الوجه الشريف وقل أنت يا جواس في نفسك وفي أبيك ما شئت ولا تذكرن أنت يا جميل أباك في فخر فإنه كان يسوق معنا الغنم بتيماء عليه شملة لا تواري استه ونفروا عليه جواسا قال ونشب الشر\nبين جميل وجواس وكانت تحته أم الجسير أخت بثينة التي يذكرها جميل في شعره إذ يقول\n(يا خليلي إن أم جسير ... حين يدنو الضجيع من علله)\n(روضة ذات حنوة وخزامى ... جاد فيها الربيع من سبله)\nفغضب لجميل نفر من قومه يقال لهم بنو سفيان فجاؤوا إلى جواس ليلا وهو في بيته فضربوه وعروا امرأته أم الجسير في تلك الليلة فقال جميل\n(ما عر حواس استها إذ يسبهم ... بصقري بني سفيان قيس وعاصم)\n(هما جردا أم الجسير وأوقعا ... أمر وأدهى من وقيعة سالم)\nعني سالم بن دارة فقال جواس\n(ما ضرب الجواس إلا فجاءة ... على غفلة من عينه وهو نائم)\n(فإلا تعجلني المنية يصطبح ... بكأسك حصناكم حصين وعاصم)\n(ويعطي بنو سفيان ما شئت عنوة ... كما كنت تعطيني وأنفك راغم)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":0,"spl":"نسب جواس وخبره في هذا الشعر — احتكم هو وجميل إلى يهود تيماء — خبر ابن مجزز","tags":["جواس","الوصف والطبيعة"],"loc":3670},
{"id":"b280-3","bab":"الجزء 22","sec":"هو وجميل يحدوان ركاب مروان","page":"ج22 ص156","text":"وقال أبو عمرو الشيباني حج مروان بن الحكم فسار بين يديه جميل بن عبد الله بن معمر\nوجواس بن قطبة وجواس بن القعطل الكلبي فقال لجميل انزل فسق بنا فنزل جميل فقال\n(يا بثن حيي ودعينا أو صلي ... وهوني الأمر فزوري واعجلي)\n(ثمت أيا ما أردت فافعلي ... إني لآتي ما أتيت مؤتلي)\nقال له مروان عد عن هذا فقال\n(أنا جميل والحجاز وطني ... فيه سهوى نفسي وفيه شجني)\n(هذا إذا كان السياق ددني ... )\nقال لجواس بن قطبة انزل أنت يا جواس فسق بنا فنزل فقال وقد كان بلغه عن مروان أنه توعده إن هاجى جميلا\n(لست بعبد للمطايا أسوقها ... ولكنني أرمي بهن الفيافيا)\n(أتاني عن مروان بالغيب أنه ... مبيح دمي أو قاطع من لسانيا)\n(وفي الأرض منجاة وفسحة مذهب ... إذا نحن رققنا لهن المثانيا)\nقال له مروان أما إن ذلك لا ينفعك إذا وجب عليك حق فاركب لا ركبت\nثم قال لجواس بن القعطل ويقال بل القصة كلها مع جواس بن قطبة انزل فارجز بنا فنزل فقال هذه الأبيات\n(يقول أميري هل تسوق ركابنا ... فقلت اتخذ حاد لهن سوائيا)\n(تكرمت عن سوق المطي ولم يكن ... سياق المطايا همتي ورجائيا)\n(جعلت أبي رهنا وعرضي سادرا ... إلى أهل بيت لم يكونوا كفائيا)\n(إلى شر بيت من قضاعة منصبا ... وفي شر قوم منهم قد بدا ليا)\nقال له اركب لا ركبت","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":0,"spl":"نسب جواس وخبره في هذا الشعر — احتكم هو وجميل إلى يهود تيماء — خبر ابن مجزز","tags":["جواس","السفر والحج"],"loc":3671,"partial":1},
{"id":"b280-4","bab":"الجزء 22","sec":"خبر ابن مجزز","page":"ج22 ص158","text":"والأبيات التي فيها الغناء يرثي بها جواس بن قطبة العذري علقمة بن مجزز قال أبو عمرو الشيباني وكان عمر بن الخطاب رضي الله عنه بعث علقمة بن مجزز الكناني ثم المدلجي في جيش إلى الحبشة وكانوا لا يشربون قطرة من ماء إلا بإذن الملك وإلا قوتلوا عليه فنزل الجيش على ماء قد ألقت لهم فيه الحبشة سما فوردوه مغترين فشربوا منه فماتوا عن آخرهم وكانوا قد أكلوا هناك تمرا فنبت ذلك النوى الذي ألقوه نخلا في بلاد الحبشة وكان يقال له نخل ابن مجزز فأراد عمر أن يجهز إليهم جيشا عظيما فشهد عنده أن رسول الله قال اتركوا الحبشة ما تركوكم وقال وددت لو أن بيني وبينهم بحرا من نار فقال جواس العذري يرثي علقمة بن مجزز\n(إن السلام وحسن كل تحية ... تغدو على ابن مجزز وتروح)\n(فإذا تجرد حافراك وأصبحت ... في الفجر نائحة عليك تنوح)\n(وتخيروا لك من جياد ثيابهم ... كفنا عليك من البياض يلوح)\n(فهناك لا تغني مودة ناصح ... حذرا عليك إذا يسد صريح)\n(هلا فدى ابن مجزز متفحش ... شنج اليدين على العطاء شحيح)\n(متمرع ورع وليس بماجد ... متملح وحديثه مقبوح)\nفيمن هلك مع ابن مجزز يقول جواس\n(ألهفي لفتيان كأن وجوههم ... دنانير وافت مهلك ابن مجزز)\n\n(أحبتنا بأبي أنتم ... وسقيا لكم حيثما كنتم)\n(أطلتم عذابي بميعادكم ... وقلتم نزور فما زرتم)\n(فأمسك قلبي على لوعتي ... ونمت دموعي بما أكتم)\n(ففيم أسأتم وأخلفتم ... وقدما وفيتم وأحسنتم)\nلشعر لإبراهيم بن المدبر والغناء لعريب خفيف ثقيل","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":0,"spl":"نسب جواس وخبره في هذا الشعر — احتكم هو وجميل إلى يهود تيماء — خبر ابن مجزز","tags":["جواس"],"song":1,"loc":3672},
{"id":"b280-6","bab":"الجزء 22","sec":"أخبار إبراهيم بن المدبر — ينشد المتوكل في مرضه","page":"ج22 ص159 – ج22 ص160","text":"أبو إسحاق إبراهيم بن المدبر شاعر كاتب متقدم من وجوه كتاب أهل العراق ومتقدميهم وذوي الجاه والمتصرفين في كبار الأعمال ومذكور الولايات وكان المتوكل يقدمه ويؤثره ويفضله وكانت بينه وبين عريب حال مشهورة كان يهواها وتهواه ولهما في ذلك أخبار كثيرة قد ذكرت بعضها في أخبار عريب وأذكر باقيها ها هنا\nأخبرني أحمد بن جعفر جحظة قال حدثني إبراهيم بن المدبر قال مرض المتوكل مرضة خيف عليه منها ثم عوفي وأذن للناس في الوصول إليه فدخلوا على طبقاتهم كافة ودخلت معهم فلما رآني استدناني حتى قمت وراء الفتح ونظر إلي مستنطقا فأنشدته\n(يوم أتانا بالسرور ... فالحمد لله الكبير)\n(أخلصت فيه شكره ... ووفيت فيه بالنذور)\n(لما اعتللت تصدعت ... شعب القلوب من الصدور)\n(من بين ملتهب الفؤاد ... وبين مكتئب الضمير)\n(يا عدتي للدين والدنيا ... وللخطب الخطير)\n(كانت جفوني ثرة الآماق ... بالدمع الغزير)\n(لو لم أمت جزعا لعمرك ... إنني عين الصبور)\n(يومي هنالك كالسنين ... وساعتي مثل الشهور)\n(يا جعفر المتوكل العالي ... على البدر المنير)\n(اليوم عاد الدين غضض ... العود ذا ورق نضير)\n(واليوم أصبحت الخلافة ... وهي أرسى من ثبير)\n(قد حالفتك وعاقدتك ... على مطاولة الدهور)\n(يا رحمة للعالمين ... ويا ضياء المستنير)\n(يا حجة الله التي ... ظهرت له بهدى ونور)\n(لله أنت فما نشاهد ... منك من كرم وخير)\n(حتى نقول ومن بقربك ... من ولي أو نصير)\n(البدر ينطق بيننا ... أم جعفر فوق السرير)\n(فإذا تواترت العظائم ... كنت منقطع النظير)\n(وإذا تعذرت العطايا ... كنت فياض البحور)\n(تمضي الصواب بلا وزير ... أو ظهير أو مشير)\nقال المتوكل للفتح أن إبراهيم لينطق عن نية خالصة وود\nمحض وما قضينا حقه فتقدم بأن يحمل إليه الساعة خمسون ألف درهم وتقدم إلى عبيد الله بن يحيى بأن يوليه عملا سريا ينتفع به","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":1,"spl":"أخبار إبراهيم بن المدبر — ينشد المتوكل في مرضه — المتوكل يودعه السجن فينشد وهو محبوس","tags":["جواس","الوصف والطبيعة"],"loc":3673},
{"id":"b280-7","bab":"الجزء 22","sec":"المتوكل يودعه السجن فينشد وهو محبوس","page":"ج22 ص162","text":"حدثني عمي قال حدثني محمد بن داود بن الجراح قال كان أحمد بن المدبر ولي لعبيد الله بن يحيى بن خاقان عملا فلم يحمد أثره فيه وعمل على أن ينكبه وبلغ أحمد ذلك فهرب وكان عبيد الله منحرفا عن إبراهيم شديد النفاسة عليه برأي المتوكل فيه فأغراه به وعرفه خبر أخيه وادعى عليه مالا جليلا وذكر أنه عند إبراهيم أخيه وأوغر صدره عليه حتى أذن له في حبسه فقال وهو محبوس\n(تسلي ليس طول الحبس عارا ... وفيه لنا من الله اختيار)\n(فلولا الحبس ما بلي اصطبار ... ولولا الليل ما عرف النهار)\n(وما الأيام إلا معقبات ... ولا السلطان إلا مستعار)\n(وعن قدر حبست فلا نقيض ... وفيما قدر الله الخيار)\n(سيفرج ما ترين إلى قليل ... مقدره وإن طال الإسار)\nلإبراهيم في حبسه أشعار كثيرة حسان مختارة منها قوله في قصيدة أولها\n(أدموعها أم لؤلؤ متناثر ... يندى به ورد جني ناضر)\nقول فيها\n(لا تؤيسنك من كريم نبوة ... فالسيف ينبو وهو عضب باتر)\n(هذا الزمان تسومني أيامه ... خسفا وهأنذا عليه صابر)\n(إن طال ليلي في الإسار فطالما ... أفنيت دهرا ليلة متقاصر)\n(والحبس يحجبني وفي أكنافه ... مني على الضراء ليث خادر)\n(عجبا له كيف التقت أبوابه ... والجود فيه والغمام الباكر)\n(هلا تقطع أو تصدع أو وهى ... فعذرته لكنه بي فاخر)\nمنها قوله في قصيدة أولها\n(ألا طرقت سلمى لدى وقعة الساري ... فريدا وحيدا موثقا نازح الدار)\n(هو الحبس ما فيه علي غضاضة ... وهل كان في حبس الخليفة من عار)\nقول فيها\n(ألست ترين الخمر يظهر حسنها ... وبهجتها بالحبس في الطين والقار)\n(وما أنا إلا كالجواد يصونه ... مقومه للسبق في طي مضمار)\n(أو الدرة الزهراء في قعر لجة ... فلا تجتلى إلا بهول وأخطار)\n(وهل هو إلا منزل مثل منزلي ... وبيت ودار مثل بيتي أو داري)\n(فلا تنكري طول المدى وأذى العدى ... فان نهايات الأمور لإقصار)\n(لعل وراء الغيب أمرا يسرنا ... يقدره في علمه الخالق الباري)\n(وإني لأرجو أن أصول بجعفر ... فأهضم أعدائي وأدرك بالثار)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":1,"spl":"أخبار إبراهيم بن المدبر — ينشد المتوكل في مرضه — المتوكل يودعه السجن فينشد وهو محبوس","tags":["جواس","الحب والغزل"],"loc":3674},
{"id":"b280-8","bab":"الجزء 22","sec":"مدح من خلصه من السجن","page":"ج22 ص164","text":"فأخبرني عمي عن محمد بن داود أن حبسه طال فلم يكن لأحد في خلاصه منه حيلة مع عضل عبيد الله وقصده إياه حتى تخلصه محمد بن عبد الله بن طاهر وجود المسألة في أمره ولم يلتفت إلى عبيد الله وبذل أن يحتمل في ماله كل ما يطالب به فأعفاه المتوكل من ذلك ووهبه له وكان إبراهيم استغاث به ومدحه فقال\n(دعوتك من كرب فلبيت دعوتي ... ولم تعترضني إذ دعوت المعاذر)\n(إليك وقد حلئت أوردت همتي ... وقد أعجزتني عن همومي المصادر)\n(نمى بك عبد الله في العز والعلا ... وحاز لك المجد المؤثل طاهر)\n(فأنتم بنو الدنيا وأملاك جوها ... وساستها والأعظمون الأكابر)\n(مآثر كانت للحسين ومصعب ... وطلحة لا تحوي مداها المفاخر)\n(إذا بذلوا قيل الغيوث البواكر ... وإن غضبوا قيل الليوث الهواصر)\n(تطيعكم يوم اللقاء البواتر ... وتزهو بكم يوم المقام المنابر)\n(وما لكم غير الأسرة مجلس ... ولا لكم غير السيوف مخاصر)\n(ولي حاجة إن شئت أحرزت مجدها ... وسرك منها أول ثم آخر)\n(كلام أمير المؤمنين وعطفه ... فمالي بعد الله غيرك ناصر)\n(وإن ساعد المقدور فالنجح واقع ... وإلا فإني مخلص الود شاكر)\nدثني جعفر بن قدامة قال كتبت عريب من سر من رأى إلى إبراهيم بن المدبر كتابا تتشوقه فيه وتخبره باستيحاشها له واهتمامها بأمره وأنها قد سألت الخليفة في أمره فوعدها بما تحب فأجابها عن كتابها وكتب في آخر الكتاب\n(لعمرك ما صوت بديع لمعبد ... بأحسن عندي من كتاب عريب)\n(تأملت في أثنائه خط كاتب ... ورقة مشتاق ولفظ خطيب)\n(وراجعني من وصلها ما استرقني ... وزهدني في وصل كل حبيب)\n(فصرت لها عبدا مقرا بملكها ... ومستمسكا من ودها بنصيب)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":2,"spl":"مدح من خلصه من السجن — أحب جارية أحبت سواه","tags":["جواس","المديح"],"loc":3675},
{"id":"b280-9","bab":"الجزء 22","sec":"أحب جارية أحبت سواه","page":"ج22 ص165","text":"أخبرني جعفر بن قدامة قال كان علي بن يحيى المنجم وإبراهيم بن المدبر مجتمعين في منزل بعض الوجوه بسر من رأى على حال أنس وكانت تغنيهم جارية يقال لها نبت جارية البكرية المغنية من جواري القيان فأقبل عليها إبراهيم بن المدبر بنظره ومزحه وتجميشه وهي مقبلة على فتى كان أمرد من أولاد الموالي\nيقال له مظفر كانت تهواه وكان أحسن الناس وجها ولم يزل ذلك دأبهم إلى أن افترقوا فكتب إليه علي بن يحيى يقول\n(لقد فتنت نبت فتى الظرف والندى ... بمقلة ريم فاتر الطرف أحور)\n(وشدو يروق السامعين ويملأ ال ... قلوب سرورا مونق متخير)\n(فأصبح في فخ الهوى متقنصا ... عزيز على إخوانه ابن المدبر)\n(ولم تدر ما يلقى بها ولو أنها ... درت روحت من حره المتسعر)\n(وذاك بها صب ونبت خلية ... ومشغولة عنه بوجه مظفر)\n(ولو أنصفت نبت لما عدلت به ... سواه وحازت حسن مرأى ومخبر)\nكتب إليه إبراهيم بن المدبر\n(طربت إلى قطربل وبلشكر ... وراجعت غيا ليس عني بمقصر)\n(وذكرني شعر أتاني مونق ... حبائب قلبي في أوائل أعصري)\n(فنهنهت نفسي عن تذكر ما مضى ... وقلت أفيقي لات حين تذكر)\n(أبا حسن ما كنت تعرف بالخنا ... ولا بعلو في المكان المؤخر)\n(وما زلت محمود الشمائل مرتضى الخلائق معروفا بعرف ومنكر ... )\n(أترمي بنبت من جفاها تخيرا ... وباعدها عنه برأي موقر)\n(ودافعها عن سرها وهي تشتكي ... إليه تباريح الهوى المتسعر)\n(ولو كان تباعا دواعي نفسه ... إذا لقضى أوطاره ابن المدبر)\n(على أنه لو حصحص الحق باعها ... ولو كان مشغوفا بها بمظفر)\n(بلؤلؤة زهراء يشرق ضوءها ... وغرة وجه كالصباج المشهر)\n(إلى الله أشكو أن هذا وهذه ... غزالا كثيب ذي أقاح منور)\n(وأنت فقد طالبتها فوجدتها ... لها خلق لا يرعوي ذو توعر)\n(وحاولت منها سلوة عن مظفر ... فما لان منها العطف عند التخير)\n(نصحتك عن ود ولم أك جاهدا ... فإن شئت فاقبل قول ذي النصح أو ذر)\nكتب إليه علي بن يحيى المنجم\n(لعمري لقد أحسنت يا بن المدبر ... وما زلت في الإحسان عين المشهر)\n(ظرفت ومن يجمع من العلم مثل ما ... جمعت أبا إسحاق يظرف ويشهر)\nلإبراهيم في نبت هذه أشعار كثيرة منها قوله\n(نبت إذا سكتت كان السكوت لها ... زينا وإن نطقت فالدر ينتشر)\n(وإنما أقصدت قلبي بمقلتها ... ما كان سهم ولا قوس ولا وتر)\nقوله\n(يا نبت يا نبت قد هام الفؤاد بكم ... وأنت والله أحلى الخلق إنسانا)\n(ألا صليني فإني قد شغفت بكم ... إن شئت سرا وإن أحببت إعلانا)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":2,"spl":"مدح من خلصه من السجن — أحب جارية أحبت سواه","tags":["جواس","الحب والغزل","الجواري والنساء"],"loc":3676,"partial":1},
{"id":"b280-10","bab":"الجزء 22","sec":"خبر خاتم عريب","page":"ج22 ص168","text":"أخبرني جعفر بن قدامة قال كان في إصبع إبراهيم بن المدبر خاتمان وهبتهما له عريب وكانا مشهورين لها فاجتمع مع أبي العبيس بن حمدون في اليوم التاسع والعشرين من شعبان على شرب فلما سكرا اتفقا على أن يصير إبراهيم إلى أبي العبيس ويقيم عنده من غد إن لم ير الهلال وأخذ الخاتمين منه رهنا ورئي الهلال في تلك الليلة وأصبح الناس صياما فكتب إبراهيم إلى أبي العبيس يطالبه بالخاتمين فدافعه وعبث به فكتب إليه من غد\n(كيف أصبحت يا جعلت فداكا ... إنني أشتكي إليك جفاكا)\n(قد تمادى بك الجفاء وما كنت ... حقيقا ولا حريا بذاكا)\n(كن شبيها بمن مضى جعل الله ... لك العمر دائما ورعاكا)\n(إن شهر الصيام شهر فكاك ... أنت فيه ونحن نرجو الفكاكا)\n(فاردد الخاتمين ردا جميلا ... قد تنعمت فيهما ما كفاكا)\n(يا أبا عبد الله دعوة داع ... يرتجي نجح أمره إذ دعاكا)\nعني أبا عبدالله بن حمدون والد أبي العبيس المخاطب بهذا الشعر\n(خاتماي اللذان عند أبي العبآس قد شارفا لديه الهلاكا ... )\n(وهو حر وقد حكاك كما أننك ... في المكرمات تحكي أباكا)\nبعث بالخاتمين إليه","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":3,"spl":"خبر خاتم عريب — نسبة هذا الصوت","tags":["جواس","اللهو والمزاح"],"loc":3677,"partial":1},
{"id":"b280-11","bab":"الجزء 22","sec":"أرسل يستريز أبا العبيس","page":"ج22 ص169","text":"وأخبرني جعفر قال زارت عريب إبراهيم بن المدبر وهو في داره على الشاطئ في المطيرة واقترحت عليه حضور أبي العبيس فكتب إليه إبراهيم\n(قل لابن حمدون ذاك الأريب ... وذاك الظريف وذاك الحسيب)\n(كتابي إليك بشكوى عريب ... لوجد شديد وشوق عجيب)\n(وشوقي إليك كشوق الغريب ... إلى أرضه بعد طول المغيب)\n(ويومي إن أنت تممته ... بقربك ذو كل حسن وطيب)\n(حباني الزمان كما أشتهي ... بقرب الحبيب وبعد الرقيب)\n(فما زلت أشرب من كفه ... وأسقيه سقي اللطيف الأديب)\n(ويشكو إلي وأشكو إليه ... بقول عفيف وقول مريب)\n(إلى أن بدالي وجه الصباح ... كوجهك ذاك العجيب الغريب)\n(فلا تخلنا يا نظام السرور ... منك فأنت شفاء الكئيب)\n(وغن لنا هزجا ممسكا ... تخف له حركات اللبيب)\n(فإنك قد حزت حسن الغناء ... وقد فزت منه بأوفى نصيب)\n(وكن بأبي أنت رجع الجواب ... فداؤك أنفسنا من مجيب)\nخبرني جعفر قال غنى أبو العبيس بن حمدون يوما عند إبراهيم\n(إني سألتك بالذي ... أدنى إليك من الوريد)\n(إلا وصلت حبالنا ... وكفيتنا شر الوعيد)\nفزاد فيه إبراهيم قوله\n(الهجر لا مستحسن ... بعد المواثق والعهود)\n(وأراك مغراة به ... أفما غرضت من الصدود)\n(إني أجدد لذتي ... ما لاح لي يوم جديد)\n(شربي معتقة الكروم ... ونزهتي ورد الخدود)\nغنى هذه الأبيات أبو العبيس متصلة باللحن الأول في البيتين وصار الجميع صوتا واحدا إلى الآن والأبيات الأخيرة لإبراهيم بن المدبر والأولان ليسا له","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":3,"spl":"خبر خاتم عريب — نسبة هذا الصوت","tags":["جواس"],"song":1,"loc":3678},
{"id":"b280-12","bab":"الجزء 22","sec":"نسبة هذا الصوت","page":"ج22 ص170","text":"الغناء في البيتين الأولين خفيف ثقيل مزموم لأبي العبيس وفيهما لحنان خفيف ثقيل آخر مطلق وفيهما لعريب ثاني ثقيل بالوسطى\nقال جعفر وغنته يوما كراعة بسر من رأى ونحن حضور عنده\n(يا معشر الناس أما مسلم ... يشفع عند المذنب العاتب)\n(ذاك الذي يهرب من وصلنا ... تعلقوا بالله بالهارب)\nزاد فيهما قوله\n(ملكته حبلي ولكنه ... ألقاه من زهد على غاربي)\n(وقال إني في الهوى كاذب ... فانتقم الله من الكاذب)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":3,"spl":"خبر خاتم عريب — نسبة هذا الصوت","tags":["جواس","الحب والغزل"],"loc":3679},
{"id":"b280-13","bab":"الجزء 22","sec":"يسترحم أبا عبد الله بن حمدون في نكبته","page":"ج22 ص171","text":"حدثني عمي قال حدثني محمد بن داود قال كتب إبراهيم بن المدبر إلى أبي عبد الله بن حمدون في أيام نكبته يسأله اذكار المتوكل والفتح بأمره\n(كم ترى يبقى على ذا بدني ... قد بلي من طول هم وضني)\n(أنا في أسر وأسباب ردى ... وحديد فادح يكلمني)\n(بابن حمدون فتى الجود الذي ... أنا منه في جنى ورد جني)\n(ما الذي ترقبه أم ما ترى ... في أخ مضطهد مرتهن)\n(وأبو عمران موسى حنق ... حاقد يطلبني بالإحن)\n(وعبيد الله أيضا مثله ... ونجاح بي مجد ما يني)\n(ليس يشفيه سوى سفك دمي ... أو يراني مدرجا في كفني)\n(والأمير الفتح إن أذكرته ... حرمتي قام بأمري وعني)\n(فأل صدق حين أدعو باسمه ... وسرور حين يعرو حزني)\n(قل له يا حسن ما أوليتني ... ما لما أوليتني من ثمن)\n(زاد إحسانك عندي عظما ... أنه باد لمن يعرفني)\n(لست أدري كيف أجزيك به ... غير أني مثقل بالمنن)\n(ما رأى القوم كذنبي عندهم ... عظم ذنبي أنني لم أخن)\n(ذاك فعلي وتراثي عن أبي ... واقتدائي بأخي في السنن)\n(سنة صالحة معروفة ... هي منا في قديم الزمن)\n(ظفر الأعداء بي عن حيلة ... ولعل الله أن يظفرني)\n(ليت أني وهم في مجلس ... يظهر الحق به للفطن)\n(فترى لي ولهم ملحمة ... يهلك الخائن فيها والدني)\n(والذي أسأل أن ينصفني ... حاكم يقضي بما يلزمني)\n(قل لحمدون خليلي وابنه ... ولعيسى حركوه يا بني)\nعني يا بني الزانية فلم يزالوا في أمره حتى خلصوه حدثني محمد بن يحيى الصولي قال كان إبراهيم بن المدبر يحب جارية للمغنية المعروفة بالبكرية بسر من رأى فقال فيها\n(غادرت قلبي في إسار لديك ... فويلتا منك وويلي عليك)\n(قد يعلم الله على عرشه ... أني أعاني الموت شوقا إليك)\n(مني بفك الأسر أو فاقتلي ... أيهما أحببت من حسنييك)\n(قد كنت لا أعدي على ظالم ... فصرت لا أعدي على مقلتيك)\n(الخمر من فيك لمن ذاقه ... والورد للناظر من وجنتيك)\n(يا حسرتا إن مت طوع الهوى ... ولم أنل ما أرتجيه لديك)\nوأنشدها أبو عبد الله بن حمدون هذه الأبيات وغنت بها وجعل يكرر قوله\n(الخمر من فيك لمن ذاقه ... )\nيقول هذا والله قول خبير مجرب فاستحيت من ذلك وسبت إبراهيم فبلغه ذلك فكتب إلى أبي عبد الله يقول\n(ألم يشقك التماع البرق في السحر ... بلى وهيج من وجد ومن ذكر)\n(ما زال دمعي غزير القطر مسجما ... سحا بأربعة تجري من الدرر)\n(وقلت للغيث لما جاد وابله ... وما شجاني من الأحزان والسهر)\n(يا عارضا ماطرا أمطر على كبدي ... فإنها كبد حرى من الفكر)\n(لشد ما نال مني الدهر واعتلقت ... يد الزمان وأوهت من قوى مرري)\n(يا واحدي من عباد الله كلهم ... ويا غناي ويا كهفي ويا وزري)\n(أحين أنشدت شعري في معذبتي ... أما رثيت لها من شدة الحصر)\n(وما شفعت بها شعري وقلت به ... في ريقها البارد السلسال ذي الخصر)\n(لبئس مستنصحا في مثل ذلك يا ... نفسي فداؤك من مستنصح غدر)\n(واليوم يوم كريم ليس يكرمه ... الا كريم من الفتيان ذو خطر)\n(نشدتك الله فاصبحه بصحبته ... مباكرا فألذ الشرب في البكر)\n(وأجمع نداماك فيه واقترح رملا ... صوتا تغنيه ذات الدل والخفر)\n(يرتاح للدجن قلبي وهو مقتسم ... بين الهموم ارتياح الأرض للمطر)\n(يا غادرا يا أحب الناس كلهم ... إلي والله من أنثى ومن ذكر)\n(ويا رجائي ويا سؤلي ويا أملي ... ويا حياتي ويا سمعي ويا بصري)\n(ويا مناي ويا نوري ويا فرحي ... ويا سروري ويا شمسي ويا قمري)\n(لا تقبلي قول حسادي علي ولا ... والله ما صدقوا في القول والخبر)\n(أدالني الله من دهر يضعضعني ... فقد حجبت عن التسليم والنظر)\n(إن يحجبوا عنك في تقديرهم بصري ... فكيف لم يحجبوا ذكري ولا فكري)\n(يا قوم قلبي ضعيف من تذكرها ... وقلبها فارغ أقسى من الحجر)\n(الله يعلم أني هائم دنف ... بغادة ليتها حظي من البشر)\nخبرني محمد بن خلف بن المرزبان قال حدثني عبد الله بن محمد المروزي قال حدثني الفضل بن العباس بن المأمون قال\nزارتني عريب يوما ومعها عدة من جواريها فوافتنا ونحن على شرابنا فتحدثت معنا ساعة وسألتها أن تقيم عندنا فأبت وقالت قد وعدت جماعة من أهل الأدب والظرف أن أصير إليهم وهم في جزيرة المربد منهم إبراهيم بن المدبر وسعيد بن حميد ويحيى بن عيسى بن منارة فحلفت عليها فأقامت ودعت بدواة وقرطاس وكتبت إليهم سطرا واحدا ( بسم الله الرحمن الرحيم","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":4,"spl":"يسترحم أبا عبد الله بن حمدون في نكبته","tags":["جواس","الحب والغزل"],"loc":3680,"partial":1},
{"id":"b280-15","bab":"الجزء 22","sec":"يسترحم أبا عبد الله بن حمدون في نكبته — عريب تهيم به حبا","page":"ج22 ص171 – ج22 ص175","text":"أردت ولولا ولعلي ووجهت الرقعة إليهم فلما وصلت قرأوها وعيوا بجوابها فأخذها إبراهيم بن المدبر فكتب تحت أردت ليت وتحت لولا ماذا وتحت لعلي أرجو ووجه بالرقعة إليها فلما قرأتها طربت ونعرت وقالت أنا أترك هؤلاء وأقعد عنكم تركني الله إذا من يديه وقامت فمضت وقالت لكم فيمن أتخلفه عندكم من جواري كفاية\nأخبرني محمد بن خلف قال حدثني عبد الله بن المعتز قال قرأت في مكاتبات لعريب فصلا من جواب أجابت به إبراهيم بن المدبر مكاتبة بديعة بعيادة قد استبطأت عيادتك قدمت قبلك وعذرتك فما ذكرت عذرا ضعيفا لا ينبغي أن يفرح به فأستديم الله نعمة عندك قال وكتبت إليه أيضا أستوهب الله حياتك قرأت رقعتك المسكينة التي كلفتها مسألتك عن أحوالنا ونحن نرجو من الله أحسن عوائده عندنا وندعوه ببقائك ونسأله\nالإجابة فلا تعود نفسك جعلني الله فداءها هذا الجفاء والثقة مني بالاحتمال وسرعة الرجوع وكتبت إليه وقد بلغها صومه يوم عاشوراء قبل الله صومك وتلقاه بتبليغك ما التمست كيف ترى نفسك نفسي فداؤك ولم كدرت جسمك في آب أخرجه الله عنك في عافية فإنه فظ غليظ وأنت محرور وإطعام عشرة مساكين أعظم لأجرك ولو علمت لصمت لصومك مساعدة لك وكان الثواب في حسناتك دوني لأن نيتي في الصوم كاذبة\nأخبرني جعفر بن قدامة قال اتصلت لعريب أشغال دائمة في أيام تركوا رسى وخدمتها فيما هنالك فلم يرها إبراهيم بن المدبر مدة فكتب إليها\n(إلى الله أشكو وحشتي وتفجعي ... وبعد المدى بيني وبين عريب)\n(مضى دونها شهران لم أحل فيهما ... بعيش ولا من قربها بنصيب)\n(فكنت غريبا بين أهلي وجيرتي ... ولست إذا أبصرتها بغريب)\n(وإن حبيبا لم ير الناس مثله ... حقيق بأن يفدى بكل حبيب)\nعريب في هذه الأبيات خفيف ثقيل من رواية ابن المعتز وهو من مشهور غنائها","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":5,"spl":"يسترحم أبا عبد الله بن حمدون في نكبته — عريب تهيم به حبا — مكاتبات عريب إليه","tags":["جواس","الجواري والنساء"],"song":1,"loc":3681},
{"id":"b280-16","bab":"الجزء 22","sec":"مكاتبات عريب إليه","page":"ج22 ص177","text":"وقال ابن المعتز في ذكره مكاتبات عريب إلى إبراهيم بن المدبر وقد كتب إليها يشكو علته كيف أصبحت أنعم الله صباحك ومبيتك وأرجو أن يكون صالحا وإنما أردت إزعاج قلبي فقط وكتبت إليه تدعو له في شهر رمضان أفديك بسمعي وبصري وأهل الله هذا الشهر عليك باليمن والمغفرة وأعانك على المفترض فيه والمتنفل وبلغك مثله أعواما وفرج عنك وعني فيه\nقال وكتبت إليه فداؤك السمع والبصر والأم والأب ومن عرفني وعرفته كيف ترى نفسك وقيتها الأذى وأعمى الله شانئك ومقه الله عند هذه الدعوة وأرجو أن تكون قد أجيبت إن شاء الله وكيف ترى الصوم عرفك الله بركته وأعانك على طاعته وأرجو أن تكون سالما من كل مكروه بحول الله وقوته وواشوقي إليك وواحشتي لك ردك الله إلى أحسن ما عودك ولا أشمت بي فيك عدوا ولا حاسدا وقد وافاني كتابك لا عدمته إلا بالغنى عنه بك وذكرت حامله فوجهت رسولي إليه ليدخله فأسأله عن خبرك فوجدته منصرفا ولو رأيته لفرشت خدي له وكان لذلك أهلا\nوكتبت إليه وقد عتبت عليه في شيء بلغها عنه وهب الله لنا بقاءك ممتعا بالنعم ما زلت أمس في ذكرك فمرة بمدحك ومرة بشكرك ومرة بأكلك وذكرك بما فيك لونا لونا اجحد ذنبك الآن وهات حجج الكتاب ونفاقهم فأما خبرنا أمس فإما شربنا من فضلة نبيذك على تذكارك رطلا رطلا وقد رفعنا حسباننا إليك فأرفع حسبانك إلينا وخبرنا من زارك أمس وألهاك وأي شيء كانت القصة على جهتها ولا تخطرف فتحوجنا إلى كشفك والبحث عنك\nوعن حالك وقل الحق فمن صدق نجا وما أحوجك إلى تأديب فإنك لا تحسن أن تؤدبه والحق أقول إنه يعتريك كزاز شديد يجوز حد البرد وكفاك بهذا من قولي عقوبة وإن عدت سمعت أكثر من هذا والسلام\nحدثني عمي قال حدثني محمد بن داود قال كان عيسى بن إبراهيم النصراني المكنى أبا الخير كاتب سعيد بن صالح يسعى على إبراهيم بن المدبر في أيام نكبته فلما زالت ومات سعيد نكب عيسى بن إبراهيم وحبس ونهبت داره فقال فيه إبراهيم بن المدبر\n(قل لأبي الشر إن مررت به ... مقالة عريت من اللبس)\n(ألبسك الله من قوارعه ... آخذة بالخناق والنفس)\n(لا زلت يا بن البظراء مرتهنا ... في شر حال وضيق محتبس)\n(أقول لما رأيت منزله ... منتهبا خاليا من الأنس)\n(يا منزلا قد عفا من الطفس ... وساحة أخليت من الدنس)\n(من لاقتراف الفحشاء بعد أبي الشرر ... ومن للقبيح والنجس)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":5,"spl":"يسترحم أبا عبد الله بن حمدون في نكبته — عريب تهيم به حبا — مكاتبات عريب إليه","tags":["جواس","المديح"],"loc":3682},
{"id":"b280-17","bab":"الجزء 22","sec":"ولي الثغور الجزرية بعد نكبته","page":"ج22 ص179","text":"أخبرني جعفر بن قدامة قال ولي إبراهيم بن المدبر بعقب نكبته وزوالها عنه الثغور الجزرية فكان أكثر مقامه بمنبج فخرج في بعض أيام ولايته إلى نواحي دلوك ورعبان وخلف بمنبج جارية كان يتحظاها مغنية يقال لها غادر فحدثني بعض كتابه انه كان معه بدلوك وهو على جبل من جبالها فيه دير يعرف بدير سليمان من احسن بلاد الله وانزهها فنزل عليه ودعا بطعام خفيف فأكل وشرب ثم دعا بداوة وقرطاس فكتب\n(أبا ساقيينا وسط دير سليمان ... أديرا الكؤوس فانهلاني وعلاني)\n(وخصا بصافيها أبا جعفر أخي ... وذا ثقتي بين الأنام وخلصاني)\n(وميلا بها نحو ابن سلام الذي ... أود وعودا بعد ذاك لنعمان)\n(وعما بها الندمان والصحب إنني ... تنكرت عيشي بعد صحبي وإخواني)\n(ولا تتركا نفسي تمت بسقامها ... لذكرى حبيب قد شجاني وعناني)\n(ترحلت عنه عن صدود وهجرة ... وأقبل نحوي وهو باك فأبكاني)\n(وفارقته والله يجمع شملنا ... بلوعة محزون وغلة حران)\n(وليلة عين المرج زار خياله ... فهيج لي شوقا وجدد أشجاني)\n(فأشرفت أعلى الدير أنظر طامحا ... بألمح آماق وأنظر إنسان)\n(لعلي أرى أبيات منبج رؤية ... تسكن من وجدي وتكشف أحزاني)\n(فقصر طرفي واستهل بعبرة ... وفديت من لو كان يدري لفداني)\n(ومثله شوقي إليه مقابلي ... وناجاه قلبي بالضمير وناجاني)\nرأت على ظهر دفتر فيه شعر إبراهيم بن المدبر أهداه مجموعا إلى أخيه احمد فلما وصل إليه قرأه وكتب عليه بخطه\n(أبا إسحاق إن تكن الليالي ... عطفن عليك بالخطب الجسيم)\n(فلم أر صرف هذا الدهر يجري ... بمكروه على غير الكريم)\nخبرني جعفر بن قدامة قال حدثني ميمون بن هارون قال اجتمعت مع عريب في مجلس انس بسر من رأى عند أبي عيسى بن المتوكل وإبراهيم بن المدبر يومئذ ببغداد فمر لنا احسن يوم وذكرته عريب فتشوقته و أحسنت الثناء عليه والذكر له فكتبت إليه بذلك من غد وشرحته له فأجابني عن كتابي وكتب في آخره\n(أتعلم يا ميمون ماذا تهيجه ... بذكرك أحبابي وحفظهم العهدا)\n(ووصف عريب في كريم وفائها ... وإجمالها ذكري وإخلاصها الودا)\n(عليها سلامي إن تكن دارها نأت ... فقد قرب الله الذي بيننا جدا)\n(سقى الله دارا بعدنا جمعتكم ... و سكن رب العرش ساكنها الخلدا)\n(وخص أبا عيسى الأمير بنعمة ... وأسعد فيما أرتجيه له الجدا)\n(فما ثم من مجد و طول و سودد ... ورأي أصيل بصدع الحجر الصلدا)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":6,"spl":"ولي الثغور الجزرية بعد نكبته — خبر صلحه مع عريب وشعره فيها","tags":["جواس","المديح"],"loc":3683},
{"id":"b280-18","bab":"الجزء 22","sec":"خبر صلحه مع عريب وشعره فيها","page":"ج22 ص181","text":"حدثني جحظة قال حدثني عبد الله بن حمدون قال اجتمعت أنا وإبراهيم بن المدبر وابن منارة والقاسم وابن زرزور في بستان بالمطيرة وفي يوم غيم يهريق رذاذه ويقطر احسن قطر ونحن في أطيب عيش واحسن يوم فلم نشعر إلا بعريب قد أقبلت من بعيد فوثب إبراهيم بن المدبر من بيننا فخرج حافيا حتى تلقاها واخذ بركابها حتى نزلت وقبل الأرض بين يديها وكانت قد هجرته مدة لشيء أنكرته عليه فجاءت وجلست و أقبلت عليه متبسمة وقالت إنما جئت إلى من هاهنا لا إليك فاعتذر وشيعنا قوله وشفعنا له فرضيت و أقامت عندنا يومئذ وباتت واصطبحنا من غد واقامت عندنا فقال إبراهيم\n(بأبي من حقق الظن به ... فأتانا زائرا مبتديا)\n(كان كالغيث تراخى مدة ... وأتى بعد قنوط مرويا)\n(طاب يومان لنا في قربه ... بعد شهرين لهجر مضيا)\n(فأقر الله عيني وشفى ... سقما كان لجسمي مبليا)\nعريب في هذا الشعر لحنان رمل وهزج بالوسطى أنشدني الصولي رحمه الله لإبراهيم بن المدبر في عريب\n(زعموا أني أحب عريبا ... صدقوا والله حبا عجيبا)\n(حل من قلبي هواها محلا ... لم تدع فيه لخلق نصيبا)\n(ليقل من قد رأى الناس قدما ... هل رأى مثل عريب يا عريبا)\n(هي شمس والنساء نجوم ... فإذا لاحت أفلن غيوبا)\nأنشدني الصولي أيضا له فيها\n(إلا يا عريب وقيت الردى ... وجنبك الله صرف الزمن)\n(فإنك أصبحت زين النساء ... وواحدة الناس في كل فن)\n(فقربك يدني لذيذ الحياة ... وبعدك ينفي لذيذ الوسن)\n(فنعم الجليس ونعم الأنيس ... ونعم السمير ونعم السكن)\nأنشدني أيضا له\n(أن عريبا خلقت وحدها ... في كل ما يحسن من أمرها)\n(ونعمة لله في خلقه ... يقصر العالم عن شكرها)\n(أشهد في جاريتيها على ... أنهما محسنتا دهرها)\n(فبدعة تبدع في شدوها ... وتحفة تتحف في زمرها)\n(يا رب أمتعها بما خولت ... وامدد لنا يا رب في عمرها)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":6,"spl":"ولي الثغور الجزرية بعد نكبته — خبر صلحه مع عريب وشعره فيها","tags":["جواس"],"song":1,"loc":3684},
{"id":"b280-19","bab":"الجزء 22","sec":"شيعه أهل البصرة بحزن","page":"ج22 ص183","text":"اخبرنا أبو الفياض سوار بن أبي شراعة القيسي البصري قال كان إبراهيم بن المدبر يتولى البصرة وكان محسنا إلى أهل البلد احسانا يعمهم ويشتمل على جماعتهم نفعه ويخصنا من ذلك بأوفر حظ واجزل نصيب فلما صرف عن البصيرة شيعة أهلها وتفجعوا لفراقه وساءهم صرفه فجعل يرد الناس من تشييعهم على قدر مراتبهم في الأنس به حتى لم يبق معه إلا أبي فقال له يا أبا شراعة أن المشيع مودع لا محالة وقد بلغت أقصى الغايات فبحقي عليك إلا انصرفت ثم قال يا غلام احمل إلى أبي شراعة ما امرتك له به فأحظر ثيابا وطيبا ومالا فودعه أبي ثم قال\n(يا أبا إسحاق سر في دعة ... وامض مصحوبا فما منك خلف)\n(ليت شعري أي ارض أجدبت ... فأغيث بك من جهد العجف)\n(نزل الرحم من الله بهم ... وحرمناك لذنب قد سلف)\n(إنما أنت ربيع باكر ... حيثما صرفه الله انصرف)\nخبرني علي بن العباس بن طلحة الكاتب قال قرأت جوابا بخط إبراهيم بن المدبر في أضعاف رقعة كتبتها إليه عريب فوجدته قد كتب تحت فصل من الكتاب تسأله فيه عن خبره\n(وساءلتموه بعدكم كيف حاله ... وذلك أمر بين ليس يشكل)\n(فلا تسألوا عن قلبه فهو عندكم ... ولكن عن الجسم المخلف فاسألوا)\nخبرني علي بن العباس قال حدثني أبي قال","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":7,"spl":"شيعه أهل البصرة بحزن — رسالة إلى عريب يشكو بعدها","tags":["جواس","اللهو والمزاح","الرواية والكتابة"],"loc":3685},
{"id":"b280-20","bab":"الجزء 22","sec":"رسالة إلى عريب يشكو بعدها","page":"ج22 ص184","text":"كنت عند إبراهيم بن المدبر فزارته بدعة وتحفة وأخرجتا إليه رقعة من عريب فقرأناها فإذا فيها بنفسي أنت وسمعي وبصري وقل ذاك لك أصبح يومنا هذا طيبا طيب الله عيشك قد احتجبت سماؤه ورق هواؤه وتكامل صفاؤه فكأنه أنت في رقة شمائلك وطيب محضرك ومخبرك لافقدت ذلك أبدا منك ولم يصادف حسنه وطيبه مني نشاطا ولا طربا لأمور صدتني عن ذلك اكره تنغيص ما أشتهيه لك من السرور بنشرها وقد بعثت إليك ببدعة وتحفة ليؤنساك وتسربهما سرك الله وسرني بك فكتب إليها يقول\n(كيف السرور وأنت نازحة ... عني وكيف يسوغ لي الطرب)\n(أن غبت غاب العيش وانقطعت ... أسبابه وألحت الكرب)\nأنفذ الجواب إليها فلم يلبث أن جاءت فبادر إليها وتلقاها حافيا حتى جاء بها على حمار مصري كان تحتها إلى صدر مجلسه يطأ الحمار على بساطه وما عليه حتى اخذ بركابها وأنزلها في صدر مجلسه وجلس بين يديها ثم قال\n(ألا رب يوم قصر الله طوله ... بقرب عريب حبذا هو من قرب)\n(بها تحسن الدنيا وينعم عيشها ... وتجتمع السراء للعين والقلب)\nحدثني علي بن سليمان قال أنشدني أبي قال أنشدني إبراهيم بن المدبر وقد كتب إلى بدعة وتحفة يستدعيهما فتأخرتا فكتب إليهما\n(قل يا رسول لهذه ... ولهذه بأبي هما)\n(قد كان وصلكما لنا ... حسنا ففيم قطعتما)\n(أعريب سيدة النساء ... بهجرنا أمرتكما)\n(كلا وبيت الله بل ... هذا جفاء منكما)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":7,"spl":"شيعه أهل البصرة بحزن — رسالة إلى عريب يشكو بعدها","tags":["جواس"],"loc":3686},
{"id":"b280-21","bab":"الجزء 22","sec":"عريب تغني صوتا من شعره","page":"ج22 ص185","text":"و أنشدني علي بن العباس لإبراهيم بن المدبر وفيه لعريب هزج وقال\n(إلا يا بأبي أنتم ... نأت دار بنا عنكم)\n(فإن كنتم تبدلتم ... فما من بدل منكم)\n(وإن كنتم على العهد ... فأحسنتهم وأجملتم)\n(ويا ليت المنى حقت ... فنبديها ولا تكتم)\n(فكنتم حيثما كنا ... وكنا حيثما كنتم)\nوحدثني علي قال حدثني أبي قال دخلت ليلة على إبراهيم بن المدبر في أيام نكبته ببغداد في ليلة غيم فلاح برق من قطب الشمال ونحن نتحدث فقطع الحديث وأمسك ساعة مفكرا ثم اقبل علي فقال\n(بارق شرد الكرى ... لاح من نحو ما ترى)\n(هاج للقلب شجوه ... فاعترى منه ما اعترى)\n(أيها الشادن الذي ... صاد قلبي وما درى)\n(كن عليما بشقوتي ... فيك من بين ذا الورى)\nحدثني عن أبيه قال كنت عند إبراهيم بن المدبر فزارته بدعة وتحفة وأقامتا عنده فأنشدنا يومئذ\n(أيها الزائران حيا كما الله ... ومن أنتما له بالسلام)\n(ما رأينا في الدهر بدرا وشمسا ... طرقا ثم رجعا بالكلام)\n(كيف خلفتما عريبا سقاها الله ... رب العباد صوب الغمام)\n(هي كالشمس والحسان نجوم ... ليس ضوء النهار مثل الظلام)\n(جمعت كل ما تفرق في الناس ... وصارت فريدة في الأنام)\nأنشدني عن أبيه لإبراهيم بن المدبر وهو محبوس\n(و أني لأستنشي الشمال إذا جرت ... حنينا إلى ألاف قلبي وأحبابي)\n(وأهدي مع الريح الجنوب اليهم ... سلامي وشكوى طول حزني وأوصابي)\n(فياليت شعري هل عريب عليمة ... بذلك أو نام الأحبة عما بي)\nدثني عمي عن محمد بن داود قال\nكان إبراهيم بن المدبر صديق أبي الصقر إسماعيل بن بلبل فلم يرض فعله لما نكب ولا نيابته عنه فقال فيه\n(لا تطل عذلي عناء ... إن في العذل بلاء)\n(لست أبكي بطن مر ... فكديا فكداء)\n(إنما أبكي خليلا ... خان في الود الصفاء)\n(يا أبا الصقر سقاك الله ... تهتانا رواء)\n(و أدام الله نعماك ... وملاك البقاء)\n(لم تجاهلت ودادي ... وتناسيت الإخاء)\n(كنت برا فعلى رأسي ... تعلمت الجفاء)\n(لا تميلن مع الريح ... إذا هبت رخاء)\n(ربما هبت عقيما ... تترك الدنيا هباء)\nخبرني علي بن العباس قال حدثني أبي قال كنت عند إبراهيم بن المدبر وزارته عريب فقال لها رأيت البارحة في النوم أبا العبيس وقد غنى في هذا الشعر وأنت تراسلينه فيه\n(يا خليلي أرقنا حزنا ... لسنا برق تبدى موهنا)\nكأني أجزته بهذا البيت وسألتكما أن تضيفاه إلى الأول\n(وجلا عن وجه دعد موهنا ... عجبا منه سنا أبدى سنا)\nفقالت ما أملح والله الابتداء و الإجازة فاجعل ذلك في اليقظة واكتب إلى أبي العبيس وسله عني وعنك الحضور فكتب إليه إبراهيم\n(يا أبا العباس يا أفتى الورى ... زارنا طيفك في سكر الكرى)\n(وتغنى لي صوتا حسنا ... في سنا برق على الأفق سرى)\n(وعريب عندنا حاصلة ... زين من يمشي على وجه الثرى)\n(نحن أضيافك في منزلنا ... نتمناك فكن أنت القرى)\nال فسار إليهما أبو العبيس وحدثه إبراهيم برؤياه فحفظا الشعر وغنيا فيه بقيمة يومهما\n(ألا حي قبل البين من أنت عاشقه ... ومن أنت مشتاق إليه وشائقه)\n(ومن لا تواتي داره غير فينة ... ومن أنت تبكي كل يوم تفارقه)\nلشعر لقيس بن جروة الطائي الأجئي قاله في غارة أغارها عمرو بن هند على ابل لطيئ فحرض زرارة بن عدس عمرو بن هند على طيئ وقال له انهم يتوعدونك فغزاهم واتصلت الأحوال إلى أن أوقع عمرو ببني تميم في يوم أوارة وخبر ذلك يذكر ها هنا لتعلق بعض أخباره ببعض والغناء لإبراهيم الموصلي ثقيل أول بالوسطى عن الهشامي ومن مجموع غناء إبراهيم","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":8,"spl":"عريب تغني صوتا من شعره","tags":["جواس"],"song":1,"loc":3687},
{"id":"b280-22","bab":"الجزء 22","sec":"يوم أوارة","page":"ج22 ص189","text":"نسخت ذلك من كتاب عمر بن محمد بن عبد الملك الزيات بخطه وذكر أن احمد بن الهيثم بن فراس اخبره به عن العمري عن هشام بن الكلبي عن أبيه وغيره من أشياخ طيئ\nقال وحدثني محمد بن أبي السري عن هشام بن الكلبي قالوا كان من حديث يوم أوارة أن عمرو بن المنذر بن ماء السماء وهو عمرو بن هند يعرف باسم أمه هند بنت الحارث الملك المنصور بن حجر آكل المرار الكندي وهو الذي يقال له مضرط الحجارة انه كان عاقد هذا الحي من طيئ على ألا ينازعوا ولا يفاخروا ولا يغزوا وان عمرو بن هند غزا اليمامة فرجع منفضا فمر بطيئ فقال له زرارة بن عدس بن زيد بن\nعبد الله بن دارم الحنظلي أبيت اللعن أصب من هذا الحي شيئا قال له ويلك أن لهم عقدا قال وان كان فلم يزل به حتى أصاب نسوة وأذوادا فقال في ذلك الطائي وهو قيس بن جروة أحد الأجئيين قال\n(إلا حي قبل البين من أنت عاشقه ... ومن أنت مشتاق إليه وشائقه)\n(ومن لا تواتي داره غير فينة ... ومن أنت تبكي كل يوم تفارقه)\n(وتعدو بصحراء الثوية ناقتي ... كعدو النحوص قد أمخت نواهقه)\n(إلى الملك الخير ابن هند تزوره ... وليس من الفوت الذي هو سابقه)\n(وإن نساء هن ما قال قائل ... غنيمة سوء بينهن مهارقه)\n(ولو نيل في عهد لنا لحم أرنب ... رددنا وهذا العهد أنت معالقه)\n(فهبك ابن هند لم تعقك أمانة ... وما المرء إلا عقدة ومواثقه)\n(وكنا أناسا خافضين بنعمة ... يسيل بنا تلع الملا و أبارقه)\n(فأقسمت لا أحتل إلا بصهوة ... حرام علي رمله وشقائقه)\n(وأقسم جهدا بالمنازل من منى ... وما خب في بطحائهن درادقه)\n(لئن لم تغير بعض ما قد فعلتم ... لأنتحين العظم ذو أنا عارقه)\nسمي عارقا بهذا البيت فبلغ هذا الشعر عمرو بن هند فقال زرارة بن عدس ابيت اللعن انه يتوعدك فقال عمرو بن هند لترملة بن شعاث الطائي وهو ابن عم عارق أيهجوني ابن عمك ويتوعدني قال والله ما هجاك ولكنه قد قال\n(والله لو كان ابن جفنة جاركم ... لكسا الوجوه غضاضة وهوانا)\n(وسلاسلا يبرقن في أعناقكم ... واذا لقطع تكلم الأقرانا)\n(ولكان عادته على جيرانه ... ذهبا وريطا رادعا وجفانا)\nالوا الرداع المصبوغ بالزعفران وانما أراد ترمله أن يذهب سخيمته فقال والله لأقتلنه فبلغ ذلك عارقا فأنشأ يقول\n(من مبلغ عمرو بن هند رسالة ... إذا استحقبتها العيس تنضى على البعد)\n(أيوعدني والرمل بيني وبينه ... تبين رويدا ما أمامه من هند)\n(ومن أجأ دوني رعان كأنها ... قنابل خيل من كميت ومن ورد)\n(غدرت بأمر أنت كنت اجتذبتنا ... عليه وشر الشيمة الغدر بالعهد)\n(فقد يترك الغدر الفتى وطعامه ... إذا هو أمسى حلبة من دم الفصد)\nبلغ عمرو بن هند شعره هذا فغزا طيئا فأسر أسرى من طيئ من بني عدي بن اخزم وهم رهط حاتم بن عبد الله فيهم رجل من الأجئيين يقال له قيس بن جحدر وهو جد الطرماح بن حكيم وهو ابن خالة حاتم فوفد حاتم فيهم إلى عمرو بن هند وكذلك كان يصنع فسأله إياهم فوهبهم له إلا قيس بن جحدر لأنه كان من الاجئيين من رهط عارق فقال حاتم\n(فككت عديا كلها من إسارها ... فأنعم وشفعني بقيس بن جحدر)\n(أبوه أبي و الأمهات امهاتنا ... فأنعم فدتك اليوم نفسي ومعشري)\nفأطلقه","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":9,"spl":"يوم أوارة — خبر مالك بن المنذر عند زرارة بن عدس","tags":["جواس"],"loc":3688},
{"id":"b280-23","bab":"الجزء 22","sec":"خبر مالك بن المنذر عند زرارة بن عدس","page":"ج22 ص192","text":"قال وبلغنا أن المنذر بن ماء السماء وضع ابنا له صغيرا ويقال بل كان أخا له صغيرا يقال له مالك عند زرارة وانه خرج ذات يوم يتصيد فأخفق ولم يصب شيئا فرجع فمر بإبل لرجل من بني عبد الله بن دارم يقال له سويد بن ربيعة بن زيد بن عبد الله بن دارم وكان عند سويد ابنة زرارة بن عدس فولدت له سبعة غلمة فأمر مالك بن المنذر بناقة سمينة منها فنحرها ثم اشتوى وسويد نائم فلما انتبه شد على مالك بعصا فضربه بها فأمه ومات الغلام وخرج سويد هاربا حتى لحق بمكة وعلم انه لا يأمن\nفحالف بني نوفل بن عبد مناة واختط بمكة فمن ولده أبو اهاب بن عزيز بن قيس بن سويد وكانت طيئ تطلب عثرات زرارة وبني أبيه حتى بلغهم ما صنعوا بأخي الملك فأنشأ عمرو بن ثعلبة بن ملقط الطائي يقول\n(من مبلغ عمرا بأن المرء ... لم يخلق صباره)\n(وحوادث الأيام لا ... تبقى لها إلا الحجارة)\n(أن ابن عجزة أمه ... بالسفح أسفل من أواره)\nال هشام أول ولد المرأة يقال له زكمة والآخر عجزة\n(تسفي الرياح خلاله سحيا وقد سلبوا إزاراه ... )\n(فاقتل زرارة لا أرى ... في القوم أفضل من زراره)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":9,"spl":"يوم أوارة — خبر مالك بن المنذر عند زرارة بن عدس","tags":["جواس","السفر والحج"],"loc":3689,"partial":1},
{"id":"b280-25","bab":"الجزء 22","sec":"هرب زرارة بعد مصرع مالك — خبر أن الشقي وافد البراجم","page":"ج22 ص193 – ج22 ص194","text":"فلما بلغ هذا الشعر عمرو بن هند بكى حتى فاضت عيناه وبلغ الخبر زرارة فهرب وركب عمرو بن هند في طلبه فلم يقدر عليه فأخذ امرأته وهي حبلى فقال أذكر في بطنك أم أنثى قالت لا علم لي بذلك\nقال ما فعل زرارة الغادر الفاجر فقالت أن كان ما علمت لطيب العرق سمين المرق ويأكل ما وجد ولا يسأل عما فقد لا ينام ليلة يخاف ولا يشبع ليلة يضاف فبقر بطنها فقال قوم زرارة لزرارة ولله ما قتلت أخاه فأت الملك فاصدقه الخبر فأتاه زرارة فأخبره الخبر فقال جئني بسويد فقال قد لحق بمكة قال فعلي ببنيه السبعة فأتي ببنيه وبأمهم بنت زرارة وهم غلمة بعضهم فوق\nبعض فأمر بقتلهم فتناولوا أحدهم فضربوا عنقه وتعلق بزرارة الآخرون فتناولوهم فقال زرارة يا بعضي دع بعضا فذهبت مثلا وقتلوا وآلى عمرو بن هند بألية ليحرقن من بني حنظلة مائة رجل فخرج يريدهم وبعث على مقدمته الطائي عمرو بن ثعلبة بن عتاب بن ملقط فوجدوا القوم قد نذروا فأخذوا منهم ثمانية وتسعين رجلا بأسفل أوارة من ناحية البحرين فحبسهم ولحقه عمرو بن هند حتى انتهى إلى أوارة فضربت فيه قبته فأمر لهم بأخدود فحفر لهم ثم اضرمه نارا فلما احتدمت وتلظت قذف بهم فيها فاحترقوا\nو أقبل راكب من البراجم وهو بطن من بني حنظلة عند المساء ولا يدري بشيء مما كان يوضع له بعيره فأناخ فقال له عمرو بن هند ما جاء بك قال حب الطعام قد اقويت ثلاثا لم اذق طعاما فلما سطع الدخان ظننته دخان طعام فقال له عمرو بن هند ممن أنت قال من البراجم قال عمرو أن الشقي واقد البراجم فذهب مثلا ورمى به في النار فهجت العرب تميما بذلك فقال ابن الصعق العامري\n(ألا أبلغ لديك بني تميم ... بآية ما يحبون الطعاما)\nأقام عمرو بن هند لا يرى أحدا فقيل له ابيت اللعن لو تحللت\nبامراة منهم فقد احرقت تسعة وتسعين رجلا فدعا بامراة من بني حنظلة فقال لها من أنت قالت أنا الحمراء بنت ضمرة بن جابر بن قطن بن نهشل بن دارم فقال أني لأظنك اعجمية فقالت ما أنا بأعجمية ولا ولدتني العجم\n(إني لبنت ضمرة بن جابر ... ساد معدا كابرا عن كابر)\n(إني لأخت ضمرة بن ضمره ... إذا البلاد لفعت بجمره)\nال عمرو أما والله لولا مخافة أن تلدي مثلك لصرفتك عن النار قالت أما والذي أساله أن يضع وسادك ويخفض عمادك ويسلبك ملكك ما قتلت إلا نساء أعاليها ثدي وأسفلها دمي قال اقذفوها في النار فالتفتت فقالت ألا فتى يكون مكان عجوز فلما أبطؤوا عليها قالت صار الفتيان حمما فذهبت مثلا فأحرقت وكان زوجها يقال له هوذة بن جرول بن نهشل بن دارم","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":10,"spl":"هرب زرارة بعد مصرع مالك — خبر أن الشقي وافد البراجم — شعر للقيط يعير فيه بني مالك","tags":["جواس"],"loc":3690},
{"id":"b280-26","bab":"الجزء 22","sec":"شعر للقيط يعير فيه بني مالك","page":"ج22 ص195","text":"فقال لقيط بن زرارة يعير بني مالك بن حنظلة بأخذ من أخذ منهم الملك وقتله اياهم ونزولهم معه\n(لمن دمنة أقفرت بالجناب ... إلى السفح بين الملا فالهضاب)\n(بكيت لعرفان آياتها ... وهاج لك الشوق نعب الغراب)\n(فأبلغ لديك بني مالك ... مغلغلة وسراة الرباب)\n(فإن امرأ أنتم حوله ... تحفون قبته بالقباب)\n(يهين سراتكم عامدا ... ويقتلكم مثل قتل الكلاب)\n(فلو كنتم إبلا أملحت ... لقد نزعت للمياه العذاب)\n(ولكنكم غنم تصطفى ... ويترك سائرها للذئاب)\n(لعمر أبيك أبي لخير ما ... أردت بقتلهم من صواب)\n(ولا نعمة إن خير الملوك ... أفضلهم نعمة في الرقاب)\nفيها يقول الطرماح بن حكيم ويذكر هذا\n(واسأل زرارة و المأمور ما فعلت ... قتلى أوارة من رعلان واللدد)\n(ودارما قد قذفنا منهم مائة ... في جاحم النار إذ يلقون بالخدد)\n(ينزون بالمشتوي منها ويوقدها ... عمرو ولولا شحوم القوم لم تقد)\nال فحدثني الكلبي عن المفضل الضبي قال لما حضر زرارة الموت جمع بنيه وأهل بيته ثم قال انه لم يبق لي عند أحد من العرب وتر إلا قد أدركته غير تحضيض الطائي بن ملقط الملك علينا حتى صنع ما صنع فأيكم يضمن لي طلب ذلك من طيئ قال عمرو بن عمرو بن عدس بن زيد أنا لك بذلك يا عم ومات زرارة فغزا عمرو بن عمرو جديلة ففاتوهم وأصاب ناسا من بني طريف بن مالك وطريف بن عمرو بن ثمامة وقال في ذلك شعرا","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":10,"spl":"هرب زرارة بعد مصرع مالك — خبر أن الشقي وافد البراجم — شعر للقيط يعير فيه بني مالك","tags":["جواس","الموت"],"loc":3691},
{"id":"b280-27","bab":"الجزء 22","sec":"لقيط بن زرارة يخطب بنت ذي الجدين","page":"ج22 ص197","text":"وكان زرارة بن عدس بن زيد رجلا شريفا فنظرت ذات يوم إلى ابنه لقيط ورأى منه خيلاء ونشاطا وجعل يضرب غلمانه وهو يومئذ شاب فقال له زرارة لقد أصبحت تصنع صنيعا كأنما جئتني بمائة من هجان المنذر بن ماء السماء أو نكحت بنت ذي الجدين بن قيس بن خالد\nقال لقيط لله علي إلا يمس رأسي غسل ولا آكل لحما ولا اشرب خمرا حتى أجمعهما جميعا أو أموت فخرج لقيط ومعه ابن خال له يقال له القراد بن إهاب وكلاهما كان شاعرا شريفا فسارا حتى أتيا بني شيبان فسلما على ناديهم ثم\nقال لقيط أفيكم قيس بن خالد ذو الجدين وكان سيد ربيعة يومئذ قالوا نعم قال فأيكم هو قال قيس أنا قيس فما حاجتك قال جئتك خاطبا ابنتك وكانت على قيس يمين ألا يخطب إليه أحد ابنته علانية ألا أصابه بشر وسمع به فقال له قيس ومن أنت\nقال أنا لقيط بن زرارة بن عدس بن زيد قال قيس عجبا منك ياذا القصة هلا كان هذا بيني وبينك قال ولم يا عم فو الله انك لرغبة وما بي من نضاة أي ما بي عار ولئن ناجيتك لا أخدعك ولئن عالنتك لا أفضحك فأعجب قيسا كلامه وقال كفء كريم إني زوجتك ومهرتك مائة ناقة ليس فيها مظائر ولا ناب ولا كزوم ولا تبيت عندنا عزبا\nولا محروما ثم أرسل إلى أم الجارية أني قد زوجت لقيط بن زرارة ابنتي القدور فاصنعيها واضربي لها ذلك البلق فإن لقيط بن زرارة لا يبيت فينا عزبا وجلس لقيط يتحدث معهم فذكروا الغزو فقال لقيط أما الغزو فأردها للقاح وأهزلها للجمال وأما المقام فأسمنها للجمال وأحبها للنساء فأعجب ذلك قيسا و أمر لقيطا فذهب إلى البلق فجلس فيه وبعثت إليه أم الجارية بمجمرة وبخور وقالت للجارية اذهبي بها إليه فو الله لئن ردها ما فيه خير ولئن وضعها تحته ما فيه خير فلما جاءته الجارية بالمجمرة بخر شعره ولحيته ثم ردها عليها فلما رجعت الجارية إليها خبرتها بما صنع فقالت انه لخليق للخير فلما امسى لقيط أهديت الجارية إليه فمازحها بكلام اشمأزت منه فنام وطرح عليه طرف خميصة وباتت إلى جنبه فلما استثقل انسلت فرجعت إلى أمها فانتبه لقيط فلم يرها فخرج حتى أتى ابن خاله قرادا وهو في اسفل الوادي فقال ارحل بعيرك واياك أن يسمع رغاؤها فتوجها إلى المنذر بن ماء السماء واصبح قيس ففقد لقيطا فسكت ولم يدر ما الذي ذهب به ومضى لقيط حتى أتى المنذر فاخبره ما كان من قول أبيه وقوله فأعطاه مائة من هجائنه فبعث بها مع قراد إلى أبيه زرارة ثم مضى إلى كسرى فكساه وأعطاه جواهر ثم انصرف لقيط من عند كسرى فأتى أباه فاخبرة خبرة وأقام يسيرا ثم خرج هو وقراد حتى جاءا محلة بني شيبان فوجداهم قد انتجعوا فخرجا في طلبهم حتى وقعا في الرمل فقال لقيط\n(انظر قراد وهاتا نضرة جزعا ... عرض الشقائق هل بينت أظعانا)\n(فيهن اترجة نضح العبير بها ... تكسي ترائبها شذرا ومرجانا)\nصية اب لابنته وهي ترحل للزواج فخرجا حتى اتيا قيس بن خالد فجهزها ابوها فلما ارادت الرحيل قال لها يا بنية كوني لزوجك أمة يكن لك عبدا وليكن اكثر طيبك الماء فانك إنما يذهب بك إلى الأعداء واراك أن ولدت فستلدين لنا غيظا طويلا واعلمي أن زوجك فارس مضر وانه يوشك أن يقتل أو يموت فلا تخمشي عليه وجها ولا تحلقي شعرا قالت له أما والله لقد ربيتني صغيرة واقصيتني كبيرة وزودتني عند الفراق شر زاد وارتحل بها لقيط فجعلت لا تمر بحي من العرب إلا قالت يالقيط اهؤلاء قومك فيقول لا حتى طلعت على محلة بني عبد الله بن دارم فرأت القباب والخيل العراب قالت يالقيط أهؤلاء قومك\nقال نعم فأقام اياما يطعم وينحر ثم بنى بها فأقامت عنده حتى قتل يوم جبلة فبعث إليها أبوها أخا لها فحملت فلما ركبت بعيرها أقبلت حتى وقفت على نادي بني عبد الله بن دارم فقالت يا بني دارم اوصيكم بالغرائب خيرا فوالله ما رأيت مثل لقيط لم تخمش عليه امرأة وجها ولم تحلق عليه شعرا فلولا أني غربية لخمشت وحلقت فحبب الله بين نساءكم وعادى بين رعائكم فاثنوا عليها خيرا","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":11,"spl":"لقيط بن زرارة يخطب بنت ذي الجدين","tags":["جواس","الهجاء"],"loc":3692},
{"id":"b280-28","bab":"الجزء 22","sec":"لقيط بن زرارة يخطب بنت ذي الجدين","page":"ج22 ص197","text":"ثم مضت حتى قدمت على ابيها فزوجها من قومه فجعل زوجها يسمعها تذكر لقيطا وتحزن عليه فقال لها أي شيء رأيت من لقيط احسن في عينك قالت خرج يوم دجن وقد تطيب وشرب فطرد البقر فصرع منها ثم أتاني وبه نضح دماء فضمني ضمة وشمني شمة فليتني مت ثمة فلم أرى منظرا كان احسن من لقيط فمكث عنه حتى إذا كان يوم دجن شرب وتطيب ثم ركب فطرد البقر ثم أتاها وبه نضح دم والطيب وريح الشراب فضمها إليه وقبلها ثم\nقال لها كيف ترين اانا أم لقيط فقالت ماء ولا كصداء ومرعى ولا كالسعدان فذهبت مثلا وصداء ركية ليس في الأرض ركية أطيب منها وقد ذكرها التميمي في شعره\n(أني وتهيامي بزينب كالذي ... يخالس من احواض صداء مشربا)\n(يرى دون برد الماء هولا وذادة ... إذا اشتد صاحوا قبل أن يتحببا)\nقول قبل أن يروى يقال تحببت من الشراب أي رويت وبضعت منه ايضا أي رويت منه والتحبب الري\n(وكاتبه في الخد بالمسك جعفرا ... بنفسي مخط المسك من حيث أثرا)\n(لئن كتبت في الخد سطرا بكفها ... لقد أودعت قلبي من الحب اسطرا)\n(فيا من لمملوك لملك يمينه ... مطيع لها فيما اسر واظهرا)\n(ويا من هواها في السريرة جعفر ... سقى الله من سقيا ثناياك جعفرا)\nالشعر لمحبوبة شاعرة المتوكل والغناء لعريب خفيف رمل مطلق","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":12,"spl":"لقيط بن زرارة يخطب بنت ذي الجدين — أخبار محبوبة — فاقت علي بن الجهم في سرعة البديهة","tags":["جواس"],"song":1,"loc":3693},
{"id":"b280-30","bab":"الجزء 22","sec":"أخبار محبوبة — فاقت علي بن الجهم في سرعة البديهة","page":"ج22 ص201 – ج22 ص202","text":"كانت محبوبة مولدة من مولدات البصرة شاعرة شريفة مطبوعة لا تكاد فضل الشاعرة اليمامية أن تتقدمها وكانت محبوبة اجمل من فضل واعف وملكها المتوكل وهي بكر اهداها له عبد الله بن طاهر وبقيت بعده فما طمع فيها أحد وكانت أيضا تغني غناء ليس بالفاخر البارع\nأخبرني بذلك جحظة عن احمد بن حمدون واخبرني جعفر بن قدامة قال حدثني علي بن يحيى المنجم كان علي بن الجهم يقرب من أنس المتوكل جدا ولا يكتمه شيئا من سره مع حرمه و أحاديث خلواته فقال له\nيوما أني دخلت على قبيحة فوجدتها قد كتبت اسمي على خدها بغالية فلا و الله ما رأيت شيئا احسن من سواد تلك الغالية على بياض ذلك الخد فقل في هذا شيئا قال وكانت محبوبة حاضرة للكلام من وراء الستر وكان عبد الله بن طاهر أهداها في جملة أربعمائة وصيفة الى المتوكل قال فدعا علي بن الجهم بدواة فإلى أن أتوه بها وابتدأ يفكر قالت محبوبة على البديهة من غير فكر ولا روية\n(وكاتبة بالمسك في الخد جعفرا ... بنفسي فخط المسك من حيث أثرا)\n(لئن كتبت في الخد سطرا بكفها ... لقد أودعت قلبي من الحب أسطرا)\n(فيا من لمملوك لملك يمينه ... مطيع له فيما أسر وأظهرا)\n(ويا من مناها في السريرة جعفر ... سقى الله من سقيا ثناياك جعفرا)\nال وبقي علي بن الجهم واجما لا ينطق بحرف وأمر المتوكل بالأبيات فبعث بها إلى عريب أمر أن تغني فيها قال علي بن يحيى قال علي بن الجهم بعد ذلك تحيرت والله وتقلبت خواطري فو الله ما قدرت على حرف واحد أقوله","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":12,"spl":"لقيط بن زرارة يخطب بنت ذي الجدين — أخبار محبوبة — فاقت علي بن الجهم في سرعة البديهة","tags":["جواس","الحب والغزل"],"loc":3694},
{"id":"b280-31","bab":"الجزء 22","sec":"شعرها في تفاحة","page":"ج22 ص203","text":"أخبرني جعفر بن قدامة قال حدثني ابن خرداذبه قال حدثني علي بن الجهم قال كنت يوما عند المتوكل وهو يشرب ونحن بين يديه\nفدفع إلى محبوبة تفاحة مغلفة فقلبتها وانصرفت عن حضرته إلى الموضع الذي كانت تجلس فيه إذا شرب ثم خرجت جارية لها ومعها رقعة فدفعتها إلى المتوكل فقرأها وضحك ضحكا شديدا ثم رمى بها إلينا فقرأناها وإذا فيها\n(يا طيب تفاحة خلوت بها ... تشعل نار الهوى على كبدي)\n(أبكي ليها وأشتكي دنفي ... وما ألاقي من شدة الكمد)\n(لو أن تفاحة بكت لبكت ... من رحمتي هذه التي بيدي)\n(أن كنت لا ترحمين ما لقيت ... نفسي من الجهد فارحمي جسدي)\nال فو الله ما بقي أحد إلا استظرفها واستملحها وأمر المتوكل فغني في هذا الشعر صوت شرب عليه بقية يومه حدثني جعفر بن قدامة قال حدثني علي بن يحيى المنجم أن جواري المتوكل تفرقن بعد قتله فصار إلى وصيف عدة منهن وأخذ محبوبة فيمن أخذ فاصطبح يوما وأمر بإحضار جواري المتوكل فأحضرن عليهن الثياب الملونة والمذهبة والحلي وقد تزين وتعطرن إلا محبوبة فإنها جاءت مرهاء متسلبة عليها ثياب بياض غير فاخرة حزنا على المتوكل فغنى الجواري جميعا وشربن وطرب وصيف وشرب ثم قال لها يا محبوبة غني فأخذت العود وغنت وهي تبكي وتقول\n(اي عيش يطيب لي ... لا أرى فيه جعفرا)\n(ملكا قد رأته عيني ... قتيلا معفرا)\n(كل من كان ذا هيام ... وحزن فقد برا)\n(غير محبوبة التي ... لو ترى الموت يشترى)\n(لا شترته بملكها ... كل هذا لتقبرا)\n(إن موت الكئيب أصلح ... من أن يعمرا)\nاشتد ذلك على وصيف وهم بقتلها وكان بغا حاضرا فاستوهبها منه فوهبها له فأعتقها وأمر بإخراجها وان تكون بحيث تختار من البلاد فخرجت من سر من رأى إلى بغداد وأخملت ذكرها طول عمرها","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":13,"spl":"شعرها في تفاحة — خصام وصلح مع المتوكل","tags":["جواس"],"loc":3695},
{"id":"b280-32","bab":"الجزء 22","sec":"خصام وصلح مع المتوكل","page":"ج22 ص205","text":"أخبرني جعفر بن قدامة قال حدثني ملاوي الهيثمي قال قال لي علي بن الجهم كانت محبوبة أهديت إلى المتوكل أهداها إليه عبد الله بن طاهر في جملة أربعمائة جارية وكانت بارعة الحسن والظرف والادب مغنية محسنة فحظيت عند المتوكل حتى انه كان يجلسها خلف ستارة وراء ظهره إذا جلس للشرب فيدخل رأسه إليها ويحدثها ويراها في كل ساعة فغاضبها يوما وهجرها ومنع جواريه جميعا من كلامها ثم نازعته نفسه إليها و أراد ذلك ثم منعته العزة وامتنعت من ابتدائه إدلالا عليه بمحلها منه\nقال علي بن الجهم فبكرت إليه يوما فقال لي أني رأيت البارحة محبوبة في نومي كأني قد صالحتها فقلت أقر الله عينك يا أمير المؤمنين و أنامك على خير وأيقظك على سرور وأرجوا أن يكون هذا الصلح في اليقظة فبينا هو يحدثني واجيبه إذا بوصيفة قد جاءته فأسرت إليه شيئا فقال لي أتدري ما أسرت هذه إلي قلت لا قال حدثتني أنها\nاجتازت بمحبوبة الساعة وهي في حجرتها تغني أفلا تعجب من هذا إني مغاضبها وهي متهاونة بذلك لا تبدؤني بصلح ثم لا ترضى حتى تغني في حجرتها قم بنا يا علي حتى نسمع ما تغني ثم قام وتبعته حتى انتهى إلى حجرتها فإذا هي تغني وتقول\n(أدور في القصر لا أرى أحدا ... اشكو إليه ولا يكلمني)\n(حتى كأني ركبت معصية ... ليست لها توبة تخلصني)\n(فهل لنا شافع إلى ملك ... قد زارني في الكرى فصالحني)\n(حتى إذا ما الصباح لاح لنا ... عاد إلى هجره فصارمني)\nطرب المتوكل وأحست بمكانه فأمرت خدمها فخرجوا إليه وتنحينا وخرجت إليه فحدثته إنها رأته في منامها وقد صالحها فانتبهت وقالت هذه الأبيات وغنت فيها فحدثها هو أيضا برؤياه واصطلحا وبعث إلى كل واحد منا بجائزة وخلعة ولما قتل تسلى عنه جميع جواريه غيرها فإنها لم تزل حزينة متسلبه هاجرة لكل لذة حتى ماتت ولها فيه مراث كثيرة\n(يا ذا الذي بعذابي ظل مفتخرا ... هل أنت إلا مليك جار إذ قدرا)\n(لولا الهوى لتجازينا على قدر ... وإن أفق منه يوما ما فسوف ترى)\nلشعر يقال انه للواثق انه للواثق قال في خادم له غضب عليه ويقال أن أبا حفص الشطرنجي قاله له والغناء لعبيدة الطنبورية رمل مطلق وفيه لحن للواثق آخر قد ذكر في","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":13,"spl":"شعرها في تفاحة — خصام وصلح مع المتوكل","tags":["جواس"],"song":1,"loc":3696},
{"id":"b280-33","bab":"الجزء 22","sec":"أخبار عبيدة الطنبورية","page":"ج22 ص206","text":"كانت عبيدة من المحسنات المتقدمات في الصنعة و الآداب يشهد لها بذلك إسحاق وحسبها بشهادته وكان أبو حشيشة يعظمها ويعترف لها بالرياسة والأستاذية وكانت من احسن الناس وجها وأطيبهم صوتا ذكرها جحظة في كتاب الطنبوريين والطنبوريات وقرأت عليه خبرها فيه فقال كانت من المحسنات وكانت لا تخلو من عشق ولم يعرف في الدنيا امرأة اعظم منها في الطنبور وكانت لها صنعة عجيبة فمنها في الرمل\n(كن لي شفيعا إليكا ... إن خف ذاك عليكا)\n(وأعفني من سؤالي ... سواك ما في يديكا)\n(يا من أعز و أهوى ... مالي أهون عليكا)","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":14,"spl":"أخبار عبيدة الطنبورية — غنت في حضرة إسحاق الموصلي دون أن تعرفه","tags":["جواس","الجواري والنساء","الموت"],"loc":3697},
{"id":"b280-34","bab":"الجزء 22","sec":"غنت في حضرة إسحاق الموصلي دون أن تعرفه","page":"ج22 ص207","text":"أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق قال قال لي علي بن الهيثم اليزيدي\nكان أبو محمد يعني أبي رحمه الله إسحاق بن إبراهيم الموصلي يألفني ويدعوني ويعاشرني فجاء يوما إلى أبي الحسن إسحاق بن إبراهيم فلم يصادفه فرجع ومر بي وأنا مشرف من جناح لي فوقف وسلم علي\nوأخبرني بقصته وقال هل تنشط اليوم للميسر إلي فقلت له ما على الأرض شيء احب إلي من ذلك ولكني أخبرك بقصتي ولا أكتمك فقال هاتها فقلت عندي اليوم محمد بن عمرو بن مسعدة وهارون بن احمد بن هشام وقد دعونا عبيدة الطنبورية وهي حاضرة والساعة يجيء الرجلان فامض في حفظ الله فإني أجلس معهم حتى تنتظم أمورهم و أروح إليك فقال لي فهلا عرضت علي المقام عندك فقلت له لو علمت أن ذلك مما تنشط له و الله لرغبت إليك فيه فإن تفضلت بذلك كان اعظم لمئتك فقال أفعل فإني قد كنت أشتهي أن أسمع عبيدة ولكن لي عليك شريطة\nقلت هاتها قال إنها أن عرفتني وسألتموني أن اغني بحضرتها لم يخف عليها أمري وانقطعت فلم تصنع شيئا فدعوها على جبلتها فقلت إفعل ما أمرت به فنزل ورد دابته وعرفت صاحبي ما جرى فكتماها آمره وأكلنا ما حضر وقدم النبيذ فغنت لحنا لها تقول\n(قريب غير مقترب ... ومؤتلف كمجتنب)\n(له ودي ولي منه ... داوعي الهم والكرب)\n(أواصله على سبب ... ويهجرني بلا سبب)\n(ويظلمني على ثقة ... بإن إليه منقلبي)\nطرب إسحاق وشرب نصفا ثم غنت وشرب نصفا ولم يزل\nكذلك حتى والى بين عشرة أنصاف وشربناها معه وقام ليصلي فقال لها هارون بن احمد بن هشام ويحك يا عبيدة ما تبالين والله متى مت قالت ولم\nقال أتدرين من المستحسن غناءك والشارب عليه ما شرب قالت لا و الله قال إسحاق بن إبراهيم الموصلي فلا تعرفيه انك قد عرفته فلما جاء إسحاق ابتدأت تغني فلحقتها هيبة له واختلاط فنقصت نقصانا بينا فقال لنا أعرفتموها من أنا فقلنا له نعم عرفها إياك هارون بن احمد فقال إسحاق نقوم إذا فننصرف فإنه لا خير في عشرتكم الليلة ولا فائدة لي ولا لكم فقام فانصرف حدثني بهذا الخبر جحظة عن جماعة منهم العباس بن أبي العبيس فذكر مثله وقال فيه أن الصوت الذي غنته\n(يا ذا الذي بعذابي ظل مفتخرا ... )\nدمها مسدود على نفسه حدثني جحظة قال حدثني محمد بن سعيد الحاجب قال حدثني ملاحظ غلام أبي العباس بن الرشيد وكان في خدمة سعيد الحاجب قال اجتمع الطنبوريون عند أبي العباس بن الرشيد يوما وفيهم المسدود وعبيدة فقالوا للمسدود غن فقال لا و الله لا تقدمت عبيدة وهي الأستاذة فما غنى حتى غنت و حدثني جحظة قال حدثني شرائح الخزاعي صاحب ساباط شرائح بسويقة نصر وساباط شرائح مشهور قال\nكانت عبيدة تعشقني فتزوجت فمرت بي يوما فسألتها الدخول الي فقالت يا كشخان كيف أدخل إليك وقد أقعدت في بيتك صاحب مصلحة ولم تدخل وحدثني جحظة قال وهب لي جعفر بن المأمون طنبورها فإذا عليه مكتوب بأبنوس\n(كل شيء سوى الخيانة ... في الحب يحتمل)\nخبار عن فسقها وفجورها وحدثني جحظة وجعفر بن قدامة وخبر جعفر أتم إلا أني قرأته على جحظة فعرفه وذكر لي انه سمعه قالا جميعا حدثنا احمد بن الطيب السرخسي\nقال كان علي بن أحمد بن بسطام المروزي وهو ابن بنت شبيب بن واج وشبيب أحد النفر الذي سترهم المنصور خلف قبته يوم قتل أبا مسلم وقال لهم إذا صفقت فاخرجوا فاضربوه بسيوفكم ففعل وفعلوا فكان علي بن احمد هذا يتعشق عبيدة الطنبورية وهو شاب وانفق عليها مالا جليلا فكتبت إليه أسأله عن خبرها ومن هي ومن أين خرجت فكتب الي كانت عبيدة بنت رجل يقال له صباح مولى أبي السمراء الغساني نديم عبد الله بن","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":14,"spl":"أخبار عبيدة الطنبورية — غنت في حضرة إسحاق الموصلي دون أن تعرفه","tags":["جواس","الحب والغزل"],"loc":3698,"partialRef":{"sid":"b96-16","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b280-35","bab":"الجزء 22","sec":"غنت في حضرة إسحاق الموصلي دون أن تعرفه","page":"ج22 ص207","text":"طاهر وأبو السمراء أحد العدة الذين وصلهم عبد الله بن طاهر في يوم واحد لكل رجل منهم مائة ألف دينار وكان الزبيدي الطنبوري أخو نظم العمياء يختلف إلى أبي السمراء وكان صباح صاحب أبي السمراء فكان الزبيدي إذا سار إلى أبي السمراء فلم يصادفه أقام عند صباح والد عبيدة وبآت وشرب وغنى و انس وكان لعبيدة صوت حسن وطبع جيد فسمعت غناء الزبيدي فوقع في قلبها واشتهته وسمع الزبيدي صوتها وعرف طبعها فعلمها وواظب عليها ومات أبوها ورقت حالها وقد حذقت الغناء على الطنبور فخرجت تغني وتقنع باليسير وكانت مليحة مقبولة خفيفة الروح فلم يزل أمرها يزيد حتى تقدمت وكبر حظها واشتهاها الناس وحلت تكتها وسمحت ورغب فيها الفتيان فكان أول من تعشقها علي بن الفرج الرخجي أخو عمر وكان حسن الوجه كثير المال فكنت أراها عنده وكنا نتعاشر على الفروسية ثم ولدت من علي بن الفرج بنتا فحجبها لأجل ذلك فكانت تحتال في الأوقات بعلة الحمام وغيره فتلم بمن كانت توده ويودها فكنت ممن تلم به وأنا حينئذ شاب ورثت عن أبي مالا عظيما وضياعا جليلة ثم ماتت بنتها من علي بن الفرج وصادف ذلك نكبتهم واختلال حال علي بن الفرج فطلقها فخرجت فكانت تخرج بدينارين للنهار ودينارين لليل واعترت بأبي السمراء ونزلت في بعض دوره وتزوجت أمها بوكيل له فتعشقت غلاما من آل حمزة بن مالك يقال له شرائح وهو صاحب ساباط شرائح ببغداد وكان يغني بالمعزفة غناء\nمليحا وكان حسن الوجه لا عيب في جماله إلا انه كان متغير النكهة وكانت شديدة الغلمة لا تحرم أحدا ولا تكرهه من حد الكهول إلى الطفل حتى تعلقت شابا يعرف بأبي كرب بن أبي الخطاب مشرط الوجه أفطس قبيحا شديد الأدمة فقيل لها أي شي رأيت في أبي كرب فقالت قد تمتعت بكل جنس من الرجال إلا السودان فان نفسي تبشعهم وهذا بين الأسود والابيض وبيته فارغ لما أريد وهو صفعاني إذا أردت ووكيلي إذا أردت\nقال وكان لها غلام يضرب عليها يقال له علي ويلقب ظئر عبيدة فكانت إذا خلت في البيت وشبقت اعتمدت عليه وقالت هو بمنزلة بغل الطحان يصلح للحمل والطحن والركوب وكان عمروبن بانة إذا حصل عنده إخوان له يدعوها لهم تغنيهم مع جواريه وإنما عرفها من داري لانه بعث يدعوني فدخل غلامه قرآها عندي فوصفها له فكتب إلي يسألني أن أجيئه بها معي ففعلت وكان عنده محمد بن عمرو بن مسعدة والحارث بن جمعة والحسن بن سليمان البرقي وهارون بن احمد بن هشام فعدلوا كلهم إلى استماع غنائها والاقتراح له والإقبال عليه ومال إليها جواريه وما خرجت إلا وقد عقدت بين الجماعة مودة وكان جواري عمرو بن بانة يشتقن إليها فيسألنه أن يدعوها فيقول لهن ابعثن إلى علي حتى يبعث بها إليكن فإنه يميل إليها وهو\nصديقي و أخشى أن يظن أني قد أفسدتها عليه ولم يكن به هذا إنما كان به الديناران اللذان يريد أن يحدرها بهما وكان عمرو من أبخل الناس وكان صوت إسحاق بن إبراهيم عليها\n(يا ذا الذي بعذابي ظل مفتخرا ... )\nكان صوت علويه ومخارق عليها\n(قريب غير مقترب ... )\nهذان الصوتان جميعا من صنعتها","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":15,"spl":"غنت في حضرة إسحاق الموصلي دون أن تعرفه — إسحاق يرثيها","tags":["جواس"],"loc":3699,"partialRef":{"sid":"b280-34","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b280-36","bab":"الجزء 22","sec":"إسحاق يرثيها","page":"ج22 ص213","text":"وكان إسحاق بن إبراهيم بن مصعب يشتهي أن يسمعها ويمنع نفسه ذلك لتيهه ولبدمكته وتوقيه أن يبلغ المعتصم عنه شيء يعيبه وماتت عبيدة من نزف أصابها فأفرط حتى أتلفها وفي عبيدة يقول بعض الشعراء ومن الناس من ينسبه إلى إسحاق\n(أمست عبيدة في الاحسان واحدة ... فالله جار لها من كل محذور)\n(من احسن الناس وجها حين تبصرها ... وأحذق الناس أن غنت بطنبور)\nخبرني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك الخزاعي قال سمعت إسحاق يقول الطنبور إذا تجاوز عبيدة هذيان\n\n(سقمت حتى ملني العائد ... وذبت حتى شمت الحاسد)\n(وكنت خلوا من رسيس الهوى ... حتى رماني طرفك الصائد)\nالشعر فيما أخبرني به جحظة لخالد الكاتب ووجدته في شعر محمد بن أمية له والغناء لأحمد بن صدقة الطنبوري رمل مطلق وقد مضت أخبار خالد الكاتب و محمد بن أمية ونذكر ها هنا أخبار احمد بن صدقة","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":15,"spl":"غنت في حضرة إسحاق الموصلي دون أن تعرفه — إسحاق يرثيها","tags":["جواس"],"song":1,"loc":3700},
{"id":"b280-37","bab":"الجزء 22","sec":"أخبار أحمد بن صدقة","page":"ج22 ص215","text":"هو احمد بن صدقة بن أبي صدقة وكان أبوه حجازيا مغنيا قدم على الرشيد وغنى له وقد ذكرت أخباره في صدر هذا الكتاب وكان احمد بن صدقة طنبوريا محسنا مقدما حاذقا حسن الغناء محكم الصنعة وله غناء كثير من الأرمال و الأهزاج وما جرى مجراها من غناء الطنبوريين وكان ينزل الشام فوصف للمتوكل فأمر بإحضاره فقدم عليه وغناه فاستحسن غناءه وأجزل صلته واشتهاه الناس وكثر من يدعوه فكسب بذلك اكثر مما كسبه مع المتوكل أضعافا أخبرني بذلك جحظة و قال كانت له صنعة ظريفة كثيرة ذكر منها الصوت المتقدم ذكره ووصفه وقرظه وذكر بعده هذا الصوت\n(وشادن ينطق بالظرف ... حسن حبيبي منتهى الوصف)\n(هام فؤادي وجرت عبرتي ... لا بعد الإلف من الإلف)\nال وهو رمل مطلق ولو حلفت أنهما ليسا عند أحد من مغني زماننا إلا عند واحد ما حنثت يعني نفسه","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":16,"spl":"أخبار أحمد بن صدقة — دخل على المأمون يوم السعانين","tags":["جواس"],"loc":3701},
{"id":"b280-38","bab":"الجزء 22","sec":"خبره مع خالد بن يزيد","page":"ج22 ص216","text":"حدثني محمد بن مزيد قال حدثنا حماد بن إسحاق قال حدثني احمد بن صدقة قال اجتزت بخالد بن يزيد الكاتب فقلت له أنشدني بيتين من شعرك حتى اغني فيهما قال و أي حظ لي في ذلك تأخذ أنت الجائزة و أحصل أنا الإثم فحلفت له أني أن أفدت بشعرك فائدة جعلت لك فيها حظا أو أذكرت به الخليفة وسألته فيك أما الحظ من جهتك فأنت أنزل من ذلك ولكن عسى أن تفلح في مسألة الخليفة ثم أنشدني\n(تقول سلا فمن المدنف ... ومن عينه أبدا تذرف)\n(ومن قلبه قلق خافق ... عليك وأحشاؤه ترجف)\nلما جلس المأمون للشرب دعاني وقد كان غضب على حظية له فحضرت مع المغنين فلما طابت نفسه وجهت إليه بتفاحة من عنبر عليها مكتوب بالذهب يا سيدي سلوت وعلم الله أني ما عرفت شيئا من الخبر و انتهى الدور الي فغنيت البيتين فاحمر وجه المأمون وانقلبت عيناه\nوقال لي يا بن الفاعلة ألك علي وعلى حرمي صاحب خبر فوثبت و قلت يا سيدي ما السبب فقال لي من أين عرفت قصتي مع جاريتي فغنيت في معنى ما بيننا فحلفت له أني لا أعرف شيئا من ذلك و حدثته حديثي مع خالد فلما انتهيت إلى قوله أنت انزل من ذلك ضحك وقال صدق وإن هذا الاتفاق ظريف ثم أمر لي بخمسة آلاف درهم ولخالد بمثلها","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":16,"spl":"أخبار أحمد بن صدقة — دخل على المأمون يوم السعانين","tags":["جواس"],"loc":3702},
{"id":"b280-39","bab":"الجزء 22","sec":"دخل على المأمون يوم السعانين","page":"ج22 ص217","text":"أخبرني محمد قال حدثنا حماد قال حدثني أحمد بن صدقة قال دخلت على المأمون في يوم السعانين وبين يديه عشرون وصيفة جلبا روميات مزنرات قد تزين بالديباج الرومي وعلقن في أعناقهن صلبان الذهب وفي أيديهن الخوص و الزيتون فقال لي المأمون ويلك يا أحمد قد قلت في هؤلاء أبياتا فغنني فيها ثم أنشدني قوله\n(ظباء كالدنانير ... ملاح في المقاصير)\n(جلاهن السعانين ... علينا في الزنانير)\n(و قد زرفن أصداغا ... كأذناب الزرازير)\n(وأقبلن بأوساط ... كأوساط الزنابير)\nحفظتها وغنيته فيها فلم يزل يشرب و ترقص الوصائف بين يديه أنواع الرقص من الدستبند إلى الإيلا حتى سكر فأمر لي بألف\nدينار و أمر بأن ينثر على الجواري ثلاثة آلاف دينار فقبضت الألف ونثرت الثلاثة الألاف عليهن فانتهبتها معهن حدثني جحظة قال حدثني جعفر بن المأمون\nقال اجتمعنا عند الفضل بن العباس بن المأمون ومعنا المسدود بن صدقة وكان أحمد قد حلق في ذلك اليوم رأسه فاستعجلوا بسلافة كانت لهم فأخذ المسدود سكرجة خردل فصبها على راس أحمد بن صدقة و\nقال كلوا هذه حتى تجيء تلك فحلف أحمد بالطلاق إلا يقيم فانصرف ولما كان من غد جمعهما الفضل بن العباس فتقدم المسدود ودخل أحمد وطنبور المسدود موضوع فجسه ثم\nقال من كان يسبح في هذا الماء فلما انتفعنا بالمسدود سائر يومه على أن الفضل قد خلع عليهما وحملهما ولم يزل أحمد مقيما حتى بلغه موت بنية له بالشأم فشخص نحو منزله وخرج عليه الأعراب فأخذوا ما معه وقتلوه قال جحظة وقال بعض الشعراء يهجو احمد بن صدقة وكانت له صديقة فقطعته فعيره بذلك و نسبها إلى إنها هربت منه لانه أبخر\n(هربت صديقة أحمد ... هربت من الريق الردي)\n(هربت فإن عادت إلى ... طنبوره فاقطع يدي)\n\n(ألم تعلموا أني تخاف عرامتي ... و أن قناتي لا تلين على القسر)\n(و إني و إياكم كمن نبه القطا ... ولو لم تنبه باتت الطير لا تسري)\n(أناة و حلما و انتظارا بكم غدا ... فما أنا بالواني ولا الضرع الغمر)\n(أظن صروف الدهر والجهل منكم ... ستحملكم مني على مركب وعر)\nالشعر للحارث بن وعلة الجرمي و الغناء لابن جامع ثقيل بالبنصر عن عمرو وفيه لسياط لحن ذكره إبراهيم ولم يجنسه و قيل أن الشعر لوعلة نفسه","topic":"نسب جواس وخبره في هذا الشعر","topicNo":280,"sp":16,"spl":"أخبار أحمد بن صدقة — دخل على المأمون يوم السعانين","tags":["جواس"],"song":1,"loc":3703},
{"id":"b281-1","bab":"الجزء 22","sec":"أخبار الحارث بن وعلة اسمه و نسبه","page":"ج22 ص220","text":"الحارث بن وعلة بن عبد الله بن الحارث بن بلع بن سبيلة بن الهون بن أعجب بن قدامة بن حرم بن زبان وهو علاف و إليه تنسب الرحال العلافية وهو أول من اتخذها بن حلوان بن عمران بن الحاف بن قضاعة وقد ذكرت متقدما الاختلاف في قضاعة ومن نسبه معديا ومن نسبه حميريا و الرحال العلافية مشهورة عند الناس قد ذكرتها الشعراء في أشعارها قال ذو الرمة\n(وليل كجلباب العروس ادرعته ... بأربعة و الشخص في العين واحد)\n(أحم علافي وأبيض صارم ... وأعيس مهري وأروع ماجد)\nوكان وعلة الجرمي وابنه الحارث من فرسان قضاعة و أنجادها و أعلامها وشعرائها وشهد وعلة الكلاب الثاني فأفلت بعد أن أدركه قيس بن عاصم المنقري و طلبه فقاته ركضا و عدوا و خبره يذكر بعد هذا في موضعه أن شاء الله تعالى فأخبرني عمي قال حدثني الكراني قال حدثنا العمري عن العتبي قال كتب عبد الرحمن بن محمد بن الاشعث إلى الحجاج متبدئا أما بعد فإن مثلي و مثلك كما قال القائل\n(سائل مجاور جرم هل جنيت لها ... حربا تفرق بين الجيرة الخلط)\n(أم هل دلفت بجرار له لجب ... يغشى الأماعيز بين السهل و الفرط)\nالشعر لوعلة الجرمي هذا مثلي و مثلك فسأحملك على أصبعه وأريحك من مركبه فكتب الحجاج بذلك إلى عبد الملك فكتب إليه جوابه أما بعد فإني قد أجبت عدو الرحمن بلا حول ولا قوة إلا بالله و لعمر الله لقد صدق و خلع سلطان الله بيمينه و طاعته بشماله و خرج من الدين عريانا كما ولدته أمه ثم لم يصبر عبد الملك على أن يدع جوابه بشعر فقال وعلى أن مثلي و مثله ما قال الآخر\n(أناة وحملا وانتظارا بكم غدا ... فما أنا بالواني ولا الضرع الغمر)\n(أظن صروف الدهر و الجهل منهم ... ستحملهم مني على مركب وعر)\nليت شعري أسما عدو الرحمن لدعائم دين الله يهدمها أم رام الخلافة أن ينالها وأوشك أن يوهن الله شوكته فاستعن بالله واعلم أن الله مع الذين اتقوا والذين هم محسنون\nقال مؤلف هذا الكتاب الشعر الذي تمثل به عبد الرحمن بن محمد بن الأشعث لوعلة الجرمي والشعر الذي تمثل به عبد الملك لابنه الحارث بن وعلة\nأخبرني محمد بن جعفر النحوي قال حدثني طلحة بن عبد الله الطلحي عن احمد بن إبراهيم عن أبي عبيدة قال قتلت نهد أخا وعلة الجرمي فاستعان بقومه فلم يعينوه فاستعان بحلفاء من بني نمير و كانوا له حلفاء و إخوانا فأعوناه حتى أدرك بثأره فقال في ذلك\n(سائل مجاور جرم هل جنيت لها ... حربا تزيل بين الجيرة الخلط)\n(أم هل علوت بجرار له لجب ... يغشى المخارم بين السهل والفرط)\n(حتى تركت نساء الحي ضاحية ... في ساحة الدار يستوقدن بالغبط)","topic":"أخبار الحارث بن وعلة اسمه و نسبه","topicNo":281,"sp":0,"spl":"أخبار الحارث بن وعلة اسمه و نسبه","tags":[],"loc":3704},
{"id":"b281-2","bab":"الجزء 22","sec":"فراره من قيس بن عاصم","page":"ج22 ص222","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا الرياشي قال\nخرج رجل من بني تميم انه قيس بن عاصم قال الرياشي و حقق أبو عبيدة انه قيس يوم الكلاب يلتمس أن يصيب رجلا من ملوك اليمن له فداء فبينا هو في ذلك إذ أدرك وعلة الجرمي وعليه مقطعات له فقال له على يمينك\nقال على يساري أقصد لي قال هيهات منك اليمن قال العراق مني أبعد قال انك لن ترى أهلك العام قال ولا أهلك تراهم و جعل وعلة يركض فرسه فإذا ظن إنها قد أعيت وثب عنها فعدا معها وصاح بها فتجري وهو يجاريها فإذا أعيا وثب فركبها حتى نجا فسأل عنه قيس فعرف انه وعلة الجرمي فانصرف و تركه فقال وعلة في ذلك\n(فدى لكما رحلي أمي و خالتي ... غداة الكلاب إذ تحز الدوابر)\n(نجوت نجاء لم ير الناس مثله ... كأني عقاب عند تيمن كاسر)\n(ولما رأيت الخيل تدعو مقاعسا ... تنازعني من ثغرة النحر جائز)\n(فإن استطع لا تلتبس بي مقاعس ... ولا يرني ميدنهم و المحاضر)\n(ولا تك لي جرارة مضرية ... إذا ما غدت قوت العيال تبادر)\nما قوله تحز الداوبر فان أهل اليمن لما انهزموا قال قيس بن عاصم لقومه لا تشتغلوا بأسرهم فيفوتكم أكثرهم ولكن اتبعوا المنهزمين فجزوا أعصابهم من أعقابهم ودعوهم في مواضعهم فإذا لم يبق أحد رجعتم إليهم فأخذتموهم ففعلوا ذلك أهل اليمن يومئذ ثمانية آلاف عليهم\nأربعة املاك يقال لهم اليزيدون وهم يزيد بن عبد المدان ويزيد بن هوبر و يزيد بن المأمور و يزيد بن مخزم هؤلاء الأربعة اليزيدون و الخامس عبد يغوث بن وقاص فقتل اليزيدون أربعتهم في الوقعة و أسر عبد يغوث بن وقاص فقتلته الرباب برجل منها وقد ذكر خبر مقتله متقدما في صوت يغني فيه وهو\n(إلا لا تلوماني كفى اللوم مابيا ... )\nأما قوله\n(ولما رأيت الخيل تدعو مقاعسا ... )\nإن بني تميم لما التقت مع بني الحارث بن كعب في هذا اليوم تداعت تميم في المعمعة يا آل كعب فتنادى أهل اليمن يا آل كعب فتنادوا يا آل الحارث فتنادى أهل اليمن يا آل الحارث فتنادوا يا آل مقاعس وتميزوا بها من أهل اليمن\n(و الله لا نظرت عيني إليك ولو ... سالت مساربها شوقا إليك دما)\n(أن كنت خنت ولم أضمر خيانتكم ... فالله يأخذ ممن خان أو ظلما)\n(سماجة لمحب خان صاحبه ... ما خان قط محب يعرف الكرما)\nلشعر لعلي بن عبد الله الجعفري و الغناء للقاسم بن زرزور و لحنه ثقيل أول مطلق ابتداؤه نشيد و كان إبراهيم بن أبي العبيس يذكر انه لأبيه","topic":"أخبار الحارث بن وعلة اسمه و نسبه","topicNo":281,"sp":1,"spl":"فراره من قيس بن عاصم","tags":[],"song":1,"loc":3705,"partial":1},
{"id":"b282-2","bab":"الجزء 22","sec":"أخبار علي بن عبد الله بن جعفر و نسبه — كان متديثا في شعره","page":"ج22 ص224 – ج22 ص225","text":"هو علي بن عبد الله بن جعفر بن إبراهيم بن محمد بن علي بن عبد الله بن جعفر بن أبي طالب عليهم السلام و أمه ولادة بنت الحجل بن عنبسة بن سعيد بن العاصي بن أمية شاعر ظريف حجازي كان عمر بن الفرج الرخجي حمله من الحجاز إلى سر من رأى مع من حمل من الطالبيين فحبسه المتوكل معهم\nحدثنا محمد بن العباس اليزيدي قال حدثنا محمد بن الحسن بن مسعود الزرقي قال حدثنا عمر بن عثمان الزهري المعروف بابن أبي قباحة قال رفع عمر بن الفرج علي بن عبد الله بن جعفر الجعفري إلى المتوكل أيام حج المنتصر فحبسه المتوكل لأنه كان شيخ القوم وكبيرهم وكان أغلظ لعمر بن الفرج\nقال علي بن عبد الله مكثت في الحبس مدة فدخل علي رجل من الكتاب يوما فقال أريد هذا الجعفري الذي تديث في شعره فقلت له إلي فأنا هو فعدل إلي وقال جعلت فذاك أحب أن تنشدني بيتيك اللذين\nتديثت فيهما فأنشدته\n(ولما بدا لي أنهما لا تودني ... و أن هواها ليس عني بمنجل)\n(تمنيت أن تهوى سواي لعلها ... تذوق حرارات الهوى فترق لي)\nال فكتبهما ثم قال لي اسمع جعلت فداك بيتين قلتهما في الغيرة فقلت هاتهما فأنشدني\n(ربما سرني صدودك عني ... في طلابيك وامتناعك مني)\n(حذرا أن أكون مفتاح غيري ... فإذا ما خلوت كنت التمني)","topic":"أخبار علي بن عبد الله بن جعفر و نسبه","topicNo":282,"sp":0,"spl":"أخبار علي بن عبد الله بن جعفر و نسبه — كان متديثا في شعره — انفته و كبرياؤه","tags":["الحب والغزل","الجواري والنساء"],"loc":3706},
{"id":"b282-3","bab":"الجزء 22","sec":"انفته و كبرياؤه","page":"ج22 ص226","text":"حدثني اليزيدي قال حدثنا محمد بن الحسن بن مسعود قال أخبرني العباس بن عيسى العقيلي أن علي بن عبد الله الجعفري أنشده\n(والله والله ربي ... وتلك أقصى يميني)\n(لو شئت إلا أصلي ... لما وضعت جبيني)\nحدثنا اليزيدي قال حدثنا محمد بن الحسن بن مسعود قال أخبرني العباس بن عيسى قال حدثني علي بن عبد الله الجعفري قال مرت بي امرأة في الطواف و أنا جالس أنشد صديقا لي هذا البيت\n(أهوى هوى الدين واللذات تعجبني ... فكيف لي بهوى اللذات والدين)\nالتفتت المرأة إلي و قالت دع أيهما شئت وخذ الآخر حدثنا اليزيدي قال حدثنا محمد بن الحسن الزرقي قال حدثنا عبد الله بن شبيب قال أنشدني علي بن عبد الله بن جعفر الجعفري لنفسه\n(و الله لا نظرت عيني إليك ولو ... سالت مساربها شوقا إليك دما)\n(إلا مفاجأة عند اللقاء ولا ... نازعتك الدهر إلا ناسيا كلما)\n(أن كنت خنت ولم أضمر خيانتكم ... فا لله يأخذ ممن خان أو ظلما)\n(سماجة لمحب خان صاحبه ... ما خان قط محب يعرف الكرما)\nال عبد الله بن شبيب علي بن عبد الله لنفسه\n(وقف الهوى بي حيث أنت فليس لي ... متأخر عنه ولا متقدم)\n(أجد الملامة في هواك لذيذة ... حبا لذكرك فليلمني اللوم)\n(و أهنتني فأهنت نفسي جاهدا ... ما من يهون عليك ممن يكرم)\n(أشبهت أعدائي فصرت أحبهم ... إذ صار حظي منك حظي منهم)\n\n(أتعرف رسم الدار من أم معبد ... نعم فرماك الشوق قبل التجلد)\n(فيالك من شوق ويا لك عبرة ... سوابقها مثل الجمان المبدد)\nلشعر لعتيبة بن مرداس المعروف بابن فسوة والغناء لجميلة خفيف ثقيل بالبنصر عن ابن المكي وذكر الهشامي أن فيه لمعبد لحنا من الثقيل الأول وانه يظنه مكن منحول يحيى إليه","topic":"أخبار علي بن عبد الله بن جعفر و نسبه","topicNo":282,"sp":0,"spl":"أخبار علي بن عبد الله بن جعفر و نسبه — كان متديثا في شعره — انفته و كبرياؤه","tags":["الحب والغزل"],"song":2,"loc":3707},
{"id":"b283-2","bab":"الجزء 22","sec":"أخبار عتيبة ونسبه — سبب تلقيبه بابن فسوة","page":"ج22 ص227 – ج22 ص228","text":"عتيبة بن مرداس أحد بني كعب بن عمرو بن تميم لم يقع إلي من نسبه غير هذا وهو شاعر مقل غير معدود في الفحول مخضرم ممن أدرك الجاهلية والإسلام هجاء خبيث اللسان بذي\nوابن فسوة لقب لزمه في نفسه و لم يكن أبوه يلقب بفسوة إنما لقب هو بهذا وقد اختلف في سبب تلقيبه بذلك فذكر إسحاق الموصلي عن أبي عمرو الشيباني نسخت ذلك من كتاب إسحاق بخطه أن عتيبة بن مرداس كان فاحشا كثير الشر قد أدرك الجاهلية فأقبل ابن عم له من الحج وكان من أهل بيت منهم يقال لهم بنو فسوة فقال لهم عتيبة كيف كنت يا بن فسوة فوثب مغضبا فركب راحلته و\nقال بئس لعمر الله ما حييت به ابن عمك قدم عليك من سفر و نزل دارك فقام إليه عتيبة مستحييا وقال له لا تغضب يا بن عم فإنما مازحتك فأبى أن ينزل فقال له انزل و أنا اشتري منك هذا الاسم فاتسمى به وظن أن ذلك لا يضره\nقال لا أفعل أو تشتريه مني بمحضر من العشيرة قال نعم فجمعهم وأعطاه بردا وجملا وكبشين وقال لهم عتيبة اشهدوا أني قد قبلت هذا النبز و أخذت الثمن و أني ابن فسوة فزالت عن ابن عمه يومئذ\nوغلبت عليه وهجي بذلك فقال فيه بعض الشعراء\n(أودى ابن فسوة إلا نعته الإبلا ... )\nو عمر عمرا طويلا و إنما قال\n(أودى ابن فسوة إلا نعته الأبلا ... )\nأنه كان أوصف الناس لها وأغراهم بوصفها ليس له كبير شعر إلا وهو مضمن وصفها","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":0,"spl":"أخبار عتيبة ونسبه — سبب تلقيبه بابن فسوة — سبب آخر للقبة","tags":["الهجاء","السفر والحج"],"loc":3708,"partial":1},
{"id":"b283-3","bab":"الجزء 22","sec":"سبب آخر للقبة","page":"ج22 ص229","text":"و أخبرني محمد بن الحسن بن دريد قال أخبرنا أبو حاتم عن أبي عبيدة قال إنما سمي عتيبة بن مرداس ابن فسوة لأنه كان له جار من عبد القيس فكان يتحدث إلى ابنته وكان لها حظ من جمال و كانت تعجبه ويهيم بها فكان أحداث بني تميم إذا ذكروا العبدي قالوا\nقال ابن فسوة و فعل ابن فسوة فأكثروا عليه من ذلك حتى مل فعمل على التحول عنهم و بلغ ذلك عتيبة فأتاه فطلب إليه أن يقيم و أن يحتمل اسمه و يشتريه منه ببعير فلم يفعل قال العبدي فتحولت عنهم وشاع في الناس انه قد ابتاع مني و غلب عليه فأنشأ عتيبة يقول من كلمة له\n(وحول مولانا علينا اسم أمه ... إلا رب مولى ناقص غير زائد)\nخبرني جعفر بن قدامة قال حدثنا أحمد بن الحارث قال حدثنا المدائني عن أبي بكر الهذلي وابن دأب وابن حعدبة قالوا أتى عتيبة بن مرداس وهو ابن فسوة عبد الله بن العباس عليهما السلام وهو عامل لعلي بن أبي طالب صلوات الله عليه على البصرة\nو تحته يومئذ شميلة بنت جنادة ابن بنت أبي أزهر الزهرانية وكانت قبله تحت مجاشع بن مسعود السلمي فأستأذن عليه فأذن له وكان لا يزال يأتي أمراء البصرة فيمدحهم فيعطونه و يخافون لسانه فلما دخل على ابن عباس\nقال له ما جاء بك إلي يا بن فسوة فقال له وهل عنك مقصر أو وراءك معدى جئتك لتعينني على مروءتي وتصل قرابتي فقال له ابن عباس وما مروءة من يعصي الرحمن ويقول البهتان و يقطع ما أمر الله به أن يوصل و الله لئن أعطيتك لاعيننك على الكفر و العصيان انطلق فأنا أقسم بالله لئن بلغني انك هجوت أحدا من العرب لأقطعن لسانك فأراد الكلام فمنعه من حضر وحبسه يومه ذلك ثم أخرجه عن البصرة","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":0,"spl":"أخبار عتيبة ونسبه — سبب تلقيبه بابن فسوة — سبب آخر للقبة","tags":["المديح","الجواري والنساء","اللهو والمزاح"],"loc":3709},
{"id":"b283-4","bab":"الجزء 22","sec":"مدح الحسن و ابن جعفر","page":"ج22 ص230","text":"فوفد إلى المدينة بعد مقتل علي عليه السلام فلقي الحسن بن علي عليهما السلام وعبد الله بن جعفر عليهما السلام فسألاه عن خبره مع ابن عباس عليه السلام فأخبرهما فاشتريا عرضه بما أرضاه فقال عتيبة يمدح الحسن جعفر عليهما السلام و يلوم ابن عباس رضي الله عنهما\n(أتيت ابن عباس فلم يقض حاجتي ... و لم يرج معروفي و لم يخش منكري)\n(حبست فلم أنطق بعذر لحاجة ... وسد خصاص البيت من كل منظر)\n(وجئت و أصوات الخصوم وراءه ... كصوت الحمام في القليب المغور)\n(وما أنا إذ زاحمت مصراع بابه ... بذي صولة ضار ولا بحزور)\nفلو كنت من زهران لم ينس حاجتي ... و لكنني مولى جميل بن معمر\nكان حليفا لجميل بن معمر القرشي\n(وباتت لعبد الله من دون حاجتي ... شميلة تلهو بالحديث المفتر)\n(ولم يقترب من ضوء نار تحثها ... شميلة إلا أن تصلى بمجمر)\n(تطالع أهل السوق و الباب دونها ... بمستفلك الذفرى أسيل المدثر)\n(إذا هي همت بالخروج يردها ... عن الباب مصراعا منيف مجير)\nجدت بخط إسحاق الموصلي مجير محير و المحير المصهرج و الحيار الصهروج\n(فليت قلوصي عربت أو رحلتها ... إلى حسن في داره و ابن جعفر)\n(إلى ابن رسول الله يأمر بالتقى ... وللدين يدعو و الكتاب المطهر)\n(إلى معشر لا يخصفون نعالهم ... ولا يلبسون السبت ما لم يحضر)\n(فلما عرفت البأس منه وقد بدت ... أيادي سبا الحاجات للمتذكر)\n(تسنمت حرجوجا كان بغامها ... أحيح ابن ماء في يراع مفجر)\n(فما زلت في التسيار حتى أنختها ... إلى ابن رسول الأمة المتخير)\n(فلا تدعني إذ رحلت إليكم ... بني هاشم أن تصدروني بمصدر)\nوهي قصيدة طويلة هذا ذكر في الخبر منها وأخبرني بهذا الخبر أحمد بن عبد العزيز الجوهري و احمد بن عبيد الله بن عمار عن عمر بن شبة عن المدائني مثل ما مضى أو قريبا منه ولم يتجاوز عمر بن شبة المدائني في إسناده","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":1,"spl":"مدح الحسن و ابن جعفر — كان خبيث اللسان مخوف المعرة","tags":["المديح"],"loc":3710},
{"id":"b283-5","bab":"الجزء 22","sec":"كان خبيث اللسان مخوف المعرة","page":"ج22 ص232","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال قال ابن الأعرابي كان عتيبة بن مرداس السلمي شاعرا خبيث اللسان مخوف المعرة في جاهليته وإسلامه و كان يقدم على أمراء العراق وأشراف الناس فيصيب منهم بشعره فقدم على ابن عامر بن كريز و كان جوادا فلما استؤذن له عليه أرسل إليه انك و الله ما تسأل بحسب ولا دين ولا منزلة وما أرى لرجل من قريش أن يعطيك شيئا و أمر به فلكز و أهين فقال ابن فسوة\n(و كائن تخطت ناقتي وزميلها ... إلى ابن كريز من نحوس وأسعد)\n(وأغبر مسحول التراب ترى له ... حيا طردته الريح من كل مطرد)\n(لعمرك إني عند باب ابن عامر ... لكالظبي عند الرمية المتردد)\n(فلم أر يوما مثله إذ تكشفت ... ضبابته عني ولما أقيد)\nبلغ قوله ابن عامر فخاف لسانه وما يأتي به بعد هذا ورجع له وأحسن القوم رفدة و قالوا هذا شاعر فارس و شيخ من شيوخ قومه واليسير\nيرضيه فقال ردوه فرد فقال له ايه يا عتيبة اردد علي ما قلت فقال ما قلت إلا خيرا قال هاته فقال قلت\n(أتعرف رسم الدار من أم معبد ... نعم فرماك الشوق قبل التجلد)\n(فيا لك من شوق ويا لك عبرة ... سوابقها مثل الجمان المبدد)\n(وكائن تخطت ناقتي وزميلها ... إلى ابن كريز من نحوس وأسعد)\n(فتى يشتري حسن الثناء بماله ... ويعلم أن المرء غير مخلد)\n(إذا ما ملمات الأمور اعترينه ... تجلى الدجى عن كوكب متوقد)\nتبسم ابن عامر و قال لعمري ما هكذا قلت و لكنه قول مستأنف وأعطاه حتى رضي وانصرف","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":1,"spl":"مدح الحسن و ابن جعفر — كان خبيث اللسان مخوف المعرة","tags":["المديح","الوصف والطبيعة","الموت"],"loc":3711},
{"id":"b283-6","bab":"الجزء 22","sec":"ابن الأعرابي يستجيد أبياتا له فينشدها","page":"ج22 ص233","text":"قال وأنشدنا ابن الأعرابي له بعقب هذا الخبر و كان يستحسن هذه الأبيات و يستجيدها\n(منعمة لم يغذها أهل بلدة ... ولا أهل مصر فهي هيفاء ناهد)\n(فريعت فلم تخبا و لكن تأودت ... كما انتص مكحول المدامع فارد)\n(وأهوت لتنتاش الرواق فلم تقم ... إليه ولكن طأطأته الولائد)\n(قليلة لحم الناظرين يزينها ... شباب ومحفوض من العيش بارد)\n(تناهى إلى لهو الحديث كأنها ... أخو سقم قد أسلمته العوائد)\n(ترى القرط منها في قناة كأنها ... بمهلكة لولا البرا والمعاقد)\nوقال أبو عمرو الشيباني أغار رجل من بني تغلب يقال له الهذيل بعقب مقتل عثمان على بني تميم فأصاب نعما كثيرا فورد بها ماء لبني مازن بن مالك بن عمرو بن تميم يقال له سفار فإذا عليه الأسود و خالد ابنا نعيم بن قعنب بن الحارث بن عمرو بن همام بن رباح في إبل لهما قد أورداها فأراد الهذيل أخذها فتفرقت فتفرق اصحابه في طلبها وهو قائم على راس ركية من سفار فرماه أحدهما فقتله فوقع في الركية فكانت قبره ويقال بل رماه عبد اسود لمالك بن عروة المازني فقال عتيبة بن مرداس الذي يقال له ابن فسوة في ذلك\n(من مبلغ فتيان تغلب أنه ... خلا للهذيل من سفار قليب)\n(إذا صوت الأصداء صوت وسطها ... فتى تغلبي في القليب غريب)\n(فأعددت يربوعا لتغلب إنهم ... أناس غذتهم فتنة وحروب)\n(حويت لقاح ابني نعيم بن قعنب ... وإنك إن أحرزتها لكسوب)\nقال أبو عمرو أيضا كان عبد الله بن عامر بن كريز قد تزوج أخت بشر بن كهف أحد بني خزاعة بن مازن فكان أثيرا عنده واستعمله على الحمى فسأله ابن فسوة أن يرعيه فأبى ومنعه وطرد ابله فقال في ذلك\n(من يك أرعاه الحمى أخواته ... فما لي من أخت عوان ولا بكر)\n(وماضرها أن لم تكن رعت الحمى ... ولم تطلب الخير الممنع من بشر)\n(متى يجيء يوما إلى المال وارثي ... يجد قبض كف غير ملأى ولا صفر)\n(يجد مهرة مثل القناة طمرة ... وغضب إذا ماهز لم يرض بالهبر)\n(فإن تمنعوا منها حماكم فإنه ... مباح لها ما بين إنبط فالكدر)\n(إذا ما امرؤ أثنى بفضل ابن عمه ... فلعنه رب العالمين على بشر)","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":2,"spl":"ابن الأعرابي يستجيد أبياتا له فينشدها — مدح قومه وهجا بني سعد","tags":["المديح"],"loc":3712},
{"id":"b283-7","bab":"الجزء 22","sec":"مدح قومه وهجا بني سعد","page":"ج22 ص235","text":"وقال أبو عمرو الشيباني ونسخته أيضا من خط إسحاق الموصلي وجمعت الروايتين أن ابن فسوة نزل ببني سعد بن مالك من بني قيس بن ثعلبة وبات بهم ومعه جارية له يقال لها جوزاء فسرقوا عيبة له فيها ثيابه و ثياب جاريته فرحل عنهم فلما عاد إلى قومه أعلمهم ما فعله به بنو سعد بن مالك فركب معه فرسان منهم حتى اغاروا على إبل لبني سعد فأخذوا منها صرمة واستاقوها فدفعوها إليه فقال يمدح قومه ويهجو بني سعد بقوله\n(جزى الله قومي من شفيع وشاهد ... جزاء سليمان النبي المكرم)\n(هم القوم لا قوم ابن دارة سالم ... ولا ضابئ إذ أسلما شر مسلم)\n(وما عيبة الجوزاء إذ غدرت بها ... سراة بني قيس بسر مكتم)\n(إذا ما لقيت الحي سعد بن مالك ... على زم فانزل خائفا أو تقدم)\n(أناس أجارونا فكان جوارهم ... شعاعا كلحم الجازر المتقسم)\n(لقد دنست أعراض سعد بن مالك ... كما دنست رجل البغي من الدم)\n(لهم نسوة طلس الثياب مواجن ... ينادين من يبتاع عودا بدرهم)\n(إذا أيم قيسية مات بعلها ... و كان لها جار فليست بأيم)\n(يمشي ابن بشر بينهن مقابلا ... بأير كإير الارجحي المخرم)\n(إذا راح من أبياتهن كأنما ... طليت بتنوم قفاه وخمخم)\nفيه رواية إسحاق\n(تسوق الجواري منخراه كأنما ... دلكن بتنوم قفاه و خمخم)\n\n(قد طال شوقي وعادني طربي ... من ذكر خود كريمة النسب)\n(غراء مثل الهلال صورتها ... أو مثل تمثال صورة الذهب)\nيروي بيعة الرهب الشعر لعبد الله بن العجلان النهدي و الغناء لمالك ولحنه من القدر الأوسط من الثقيل الأول بالسبابة في مجرى الوسطى\nعن إسحاق وله فيه أيضا خفيف ثقيل بالوسطى عن عمرو وذكر الهشامي انه لابن مسجح","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":2,"spl":"ابن الأعرابي يستجيد أبياتا له فينشدها — مدح قومه وهجا بني سعد","tags":["المديح"],"song":1,"loc":3713},
{"id":"b283-9","bab":"الجزء 22","sec":"أخبار عبد الله بن العجلان — قصته مع امرأته هند","page":"ج22 ص237 – ج22 ص238","text":"هو عبد الله بن العجلان بن عبد الاحب بن عامر بن كعب بن صباح بن نهد بن زيد بن ليث بن اسود بن اسلم بن الحاف بن قضاعة شاعر جاهلي أحد المتيمين من الشعراء ومن قتله الحب منهم و كانت له زوجة يقال لها هند فطلقها ثم ندم على ذلك فتزوجت زوجا غيره فمات أسفا عليها\nأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي قال كان عبد الله بن العجلان النهدي سيدا في قومه و ابن سيد من ساداتهم و كان أبوه أكثر بني نهد مالا و كانت هند امرأة عبد الله بن العجلان التي يذكرها في شعره امرأة من قومه من بني نهد و كانت احب الناس إليه وأحظاهم عنده فمكثت معه سنين سبعا أو ثمانيا لم تلد فقال له أبوه انه لا ولد لي غيرك ولا ولد لك وهذه المرأة عاقر فطلقها و تزوج غيرها فأبى ذلك عليه فآلى إلا يكلمه أبدا حتى يطلقها فأقام على أمره ثم عمد إليه يوما وقد شرب الخمر حتى سكر وهو جالس مع هند فأرسل إليه أن صر إلي فقالت له هند لا تمض إليه فو الله ما\nيريدك لخير و إنما يريدك لأنه بلغه انك سكران فطمع فيك أن يقسم عليك فتطلقني فنم مكانك ولا تمض إليه فأبى وعصاها فتعلقت بثوبه فضربها بمسواك فأرسلته و كان في يدها زعفران فأثر في ثوبه مكان يدها و مضى إلى أبيه فعادوه في أمرها وأنبه و ضعفه و جمع عليه مشيخة الحي وفتيانهم فتناولوه بألسنتهم و عيروه بشغفه بها و ضعف حزمه و لم يزالوا به حتى طلقها فلما اصبح خبر بذلك و قد علمت به هند فاحتجبت عنه و عادت إلى أبيها فأسف عليها أسفا شديدا فلما رجعت إلى أبيها خطبها رجل من بني نمير فزوجها أبوها منه فبنى بها عندهم و أخرجها إلى بلده فلم يزل عبد الله بن العجلان دنفا سقيما يقول فيها الشعر ويبكيها حتى مات أسفا عليها و عرضوا عليه فتيات الحي جميعا فلم يقبل واحدة منهن و قال في طلاقه إياها\n(فارقت هندا طائعا ... فندمت عند فراقها)\n(فالعين تذري دمعة ... كالدر من آماقها)\n(متحليا فوق الرداء ... يجول من رقراقها)\n(خود رداح طفلة ... ما الفحش من أخلاقها)\nلقد ألذ حديثها ... و أسر عند عناقها\nوفي هذه القصيدة يقول\n(إن كنت ساقية ببزل ... الادم أو بحقاقها)\n(فاسقي بني نهد إذا ... شربوا خيار زقاقها)\n(فالخيل تعلم كيف نلحقها ... غداة لحاقها)\n(بأسنة زرق صبحنا ... القوم حد رقاقها)\n(حتى ترى قصد القنا ... والبيض في أعناقها)\nال أبو عمرو الشيباني لما طلق عبد الله بن العجلان هندا أنكحت في بني عامر و كانت بينهم وبين نهد مغاورات فجمعت نهد لبني عامر جميعا فأغاروا على طوائف منهم فيهم بنو العجلان وبنو الوحيد و بنو الحريش و بنو قشير و نذروا بهم فاقتتلوا قتالا شديدا ثم انهزمت بنو عامر و غنمت نهد أموالهم و قتل في المعركة ابن لمعاوية بن قشير بن كعب وسبعة بنين له و قرط وجدعان ابنا سلمة بن قشير و مرداس بن جزعة بن كعب و حسين بن عمرو بن معاوية ومسحقة بن المجمع الجعفي فقال عبد الله بن العجلان في ذلك\n(ألا أبلغ بني العجلان عني ... فلا ينبيك بالحدثان غيري)\n(بأنا قد قتلنا الخير قرطا ... و جرنا في سراة بني قشير)\n(وأفلتنا بنو شكل رجالا ... حفاة يربئون على سمير)","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":3,"spl":"أخبار عبد الله بن العجلان — قصته مع امرأته هند","tags":["الحب والغزل"],"loc":3714},
{"id":"b283-10","bab":"الجزء 22","sec":"امرأة قيسية ترثي قتلى قيس","page":"ج22 ص241","text":"وقالت امرأة من بني قيس ترثي قتلاهم\n(أصبتم يا بني نهد بن زيد ... قروما عند قعقعة السلاح)\n(إذا اشتد الزمان و كان محلا ... و حاذر فيه إخوان السماح)\n(أهانوا المال في اللزبات صبرا ... و جادوا بالمتالي و اللقاح)\n(فبكي مالكا وابكي بجيرا ... و شدادا لمشتجر الرماح)\n(و كعبا فاندبيه معا و قرطا ... أولئك معشري هدوا جناحي)\n(و بكي إن بكيت على حسيل ... و مرداس قتيل بني صباح)\nقال و أسر عبد الله بن العجلان رجلا من بني الوحيد فمن عليه وأطلقه ووعده الوحيدي الثواب فلم يف فقال عبد الله\n(و قالوا لن تنال الدهر فقرا ... إذا شكرتك نعمتك الوحيد)\n(فيا ندما ندمت على رزام ... و مخلفه كما خلع العتود)\nال أبو عمرو ثم أن بني عامر جمعوا لبني نهد فقالت هند امرأة عبد الله بن العجلان التي كانت ناكحا فيهم لغلام منهم يتيم فقير من بني عامر لك خمس عشرة ناقة على أن تأتي قومي فتنذرهم قبل أن يأتيهم بنو عامر فقال أفعل فحملته على ناقة لزوجها ناجية وزودته تمرا ووطبا من لبن فركب فجد في السير و فني اللبن فأتاهم و الحي\nخلوف في غزو و ميرة فنزل بهم و قد يبس لسانه فلما كلموه لم يقدر على أن يجيبهم وأومأ لهم إلى لسانه فأمر خراش بن عبد الله بلبن وسمن فأسخن و سقاه إياه فابتل لسانه و تكلم و قال لهم أتيتم أنا رسول هند إليكم تنذركم فاجتمعت بنو نهد و استعدت ووافتهم بنو عامر فلحقوهم على الخيل فاقتتلوا قتالا شديدا فانهزمت بنو عامر فقال عبد الله بن العجلان في ذلك\n(عاود عيني نصبها و غرورها ... أهم عناها أم قذاها يعورها)\n(أم الدار أمست قد تعفت كأنها ... زبور يمان رقشته سطورها)\n(ذكرت بها هندا وأترابها الألى ... بها يكذب الواشي ويعصى أميرها)\n(فما معول تبكي لفقد أليفها ... إذا ذكرته لا يكف زفيرها)\n(بأغزر مني عبرة إذ رأيتها ... بحث بها قبل الصباح بعيرها)\n(ألم يأت هندا كيفما صنع قومها ... بني عامر إذ جاء يسعى نذيرها)\n(فقالوا لنا إنا نحب لقاءكم ... و إنا نحيي أرضكم و نزورها)\n(فقلنا إذا لا تنكل الدهر عنكم ... بصم القنا اللائي الدماء تميرها)\n(فلا غرو أن الخيل تنحط في القنا ... تمطر من تحت العوالي ذكورها)\n(تأوه مما مسها من كريهة ... و تصفي الخدود و الرماح تصورها)\n(وأربابها صرعى ببرقة أخرب ... تجررهم ضبعانها ونسورها)\n(فأبلغ أبا الحجاج عني رسالة ... مغلغلة لا يغلبنك بسورها)\n(فأنت منعت السلم يوم لقيتنا ... بكفيك تسدي غية و تنيرها)\n(فذوقوا على ما كان من فرط إحنة ... حلائبنا إذ غاب عنا نصيرها)","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":4,"spl":"امرأة قيسية ترثي قتلى قيس","tags":["الجواري والنساء","السفر والحج"],"loc":3715},
{"id":"b283-11","bab":"الجزء 22","sec":"كيف انتهى حبه لهند","page":"ج22 ص243","text":"قال أبو عمرو فلما اشتد ما بعبد الله بن العجلان من السقم خرج سرا من أبيه مخاطرا بنفسه حتى أتى أرض بني عامر لا يرهب ما بينهم من الشر و الترات حتى نزل ببني نمير و قصد خباء هند فلما قارب دارها رآها وهي جالسة على الحوض وزوجها يسقي و يذود الإبل عن مائة فلما نظر إليها و نظرت إليه رمى بنفسه عن بعيره و أقبل يشتد إليها وأقبلت تشتد إليه فاعتنق كل واحد منهما صاحبه و جعلا يبكيان و ينشجان و يشهقان حتى سقطا على وجوههما و أقبل زوج هند ينظر ما حالهما فوجدهما ميتين\nقال أبو عمرو و أخبرني بعض بني نهد أن عبد الله بن العجلان أراد المضي إلى بلادهم فمنعه أبوه و خوفه الثارات و قال نجتمع معهم في الشهر الحرام بعكاظ أو بمكة و لم يزل يدافعه بذلك حتى جاء الوقت فحج و حج أبوه معه فنظر إلى زوج هند وهو يطوف بالبيت وأثر كفها في ثوبه بخلوق فرجع إلى أبيه في منزله و أخبره بما رأى ثم سقط على وجهه فمات هذه رواية أبي عمرو وقد أخبرني محمد بن خلف وكيع قال حدثني عبد الله بن علي بن\nالحسن قال حدثنا نصر بن علي عن الاصمعي عن عبد العزيز بن أبي سلمة عن أيوب عن ابن سيرين قال خرج عبد الله بن العجلان في الجاهلية فقال\n(ألا إن هندا أصبحت منك محرما ... و أصبحت من أدنى حموتها حما)\n(وأصبحت كالمقمور جفن سلاحه ... يقلب بالكفين قوسا وأسهما)\nم مد بها صوته فمات قال ابن سيرين فما سمعت أحدا مات عشقا غير هذا وهذا الخبر عندي خطأ لأن أكثر الرواة يروي هذين البيتين لمسافر بن أبي عمرو بن أمية قالهما لما خرج إلى النعمان بن المنذر يستعينه في مهر هند بنت عتبة بن ربيعة فقدم أبو سفيان بن حرب فسأله عن أخبار مكة و هل حدث بعده شيء فقال لا إلا أني تزوجت هندا بنت عتبة فمات مسافرا أسفا عليها و يدل على صحة ذلك قوله\n(وأصبحت من أدنى حموتها حما ... )\nأنه ابن عم أبي سفيان بن حرب لحا و ليس النميري المتزوج هندا النهدية ابن عم عبد الله بن العجلان فيكون من أحمائها و القول الأول على هذا أصح","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":5,"spl":"كيف انتهى حبه لهند — مختارات من شعره في هند","tags":["الجواري والنساء","السفر والحج","الموت"],"loc":3716,"partialRef":{"sid":"b88-2","gi":0,"vi":0,"side":1},"partial":1},
{"id":"b283-12","bab":"الجزء 22","sec":"مختارات من شعره في هند","page":"ج22 ص245","text":"ومن مختار ما قاله ابن العجلان في هند\n(ألا أبلغا هندا سلامي فإن نأت ... فقلبي مذ شطت بها الدار مدنف)\n(ولم أر هندا بعد موقف ساعة ... بأنعم في أهل الديار تطوف)\n(أتت بين أتراب تمايس إذ مشت ... دبيب القطا أوهن منهن أقطف)\n(بباكرن مرآة جليا و تارة ... ذكيا وبالأيدي مداك ومسوف)\n(أشارت إلينا في خفاة وراعها ... سراة الضحى مني على الحي موقف)\n(وقالت تباعد يا بن عمي فإنني ... منيت بذي صول يغار ويعنف)\nخبرني الحسن بن علي قال أنشدنا فضل اليزيدي عن إسحاق لعبد الله بن العجلان النهدي قال إسحاق وفيه غناء\n(خليلي زورا قبل شحط النوى هندا ... ولا تأمنا من دار ذي لطف بعدا)\n(ولا تعجلا لم يدر صاحب حاجة ... أغيا يلاقي في التعجل أم رشدا)\n(ومرا عليها بارك الله فيكما ... وإن لم تكن هند لوجهيكما قصدا)\n(و قولا لها ليس الضلال أجازنا ... و لكننا جزنا لنلقاكم عمدا)\n\n(ألا يا ظبية البلد ... براني طول ذا الكمد)\n(فردي يا معذبتي ... فؤادي أو خذي جسدي)\n(بليت لشقوتي بكم ... غلاما ظاهر الجلد)\n(فشيب حبكم رأسي ... و بيض هجركم كبدي)\nلشعر للمؤمل بن أميل و الغناء لإبراهيم ثقيل أول بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"أخبار عتيبة ونسبه","topicNo":283,"sp":5,"spl":"كيف انتهى حبه لهند — مختارات من شعره في هند","tags":["اللهو والمزاح"],"song":1,"loc":3717},
{"id":"b284-1","bab":"الجزء 22","sec":"أخبار المؤمل و نسبه","page":"ج22 ص246","text":"المؤمل بن أميل بن أسيد المحاربي من محارب بن خصفة بن قيس بن عيلان بن مضر شاعر كوفي من مخضرمي شعراء الدولتين الأموية و العباسية و كانت شهرته في العباسبة أكثر لأنه كان من الجند المرتزقة معهم ومن يخصهم و يخدمهم من أوليائهم وانقطع إلى المهدي في حياة أبيه و بعده وهو صالح المذهب في شعره ليس من المبرزين الفحول ولا المرذولين وفي شعره لين وله طبع صالح و كان يهوى امرأة من أهل الحيرة يقال لها هند و فيها يقول قصيدته المشهورة\n(شف المؤمل يوم الحيرة النظر ... ليت المؤمل لم يخلق له بصر)\nقال إنه رأى في منامه رجلا أدخل أصبعيه في عينيه وقال هذا ما تمنيت فأصبح أعمى","topic":"أخبار المؤمل و نسبه","topicNo":284,"sp":0,"spl":"أخبار المؤمل و نسبه — المنصور يسترد ما اغدقه عليه المهدي","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3718},
{"id":"b284-2","bab":"الجزء 22","sec":"المنصور يسترد ما اغدقه عليه المهدي","page":"ج22 ص247","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثنا عبد الله بن الحسن الحراني قال حدثني أبو قدامة قال حدثني المؤمل قال\nقدمت على المهدي وهو بالري وهو إذ ذاك ولي عهد فامتدحته بأبيات فأمر لي بعشرين ألف درهم فكتب بذلك صاحب البريد إلى أبي جعفر المنصور وهو بمدينة السلام يخبره أن الأمير المهدي أمر لشاعر بعشرين ألف درهم فكتب إليه يعذله و يلومه و يقول له إنما ينبغي أن تعطي لشاعر بعد أن يقيم ببابك سنة أربعة آلاف درهم و كتب إلى كاتب المهدي أن يوجه إليه بالشاعر فطلب ولم يقدر عليه وكتب إلى أبي جعفر انه قد يوجه إلى مدينة السلام فأجلس قائدا من قوداه على جسر النهروان وأمره أن يتصفح الناس رجلا رجلا فجعل لا يمر به قافلة إلا تصفح من فيها حتى مرت به القافلة التي فيها المؤمل فتصفحهم فلما سأله من أنت\nقال أنا المؤمل بن أميل المحاربي الشاعر أحد زوار الأمير المهدي فقال إياك طلبت قال المؤمل فكاد قلبي ينصدع خوفا من أبي جعفر فقبض علي وأسلمني إلى الربيع فأدخلني إلى أبي جعفر و\nقال له هذا الشاعر الذي أخذ من المهدي عشرين آلفا قد ظفرنا به فقال أدخلوه الي فأدخلت إليه فسلمت تسليم فزع مروع فرد السلام و قال ليس لك ها هنا إلا خير أنت المؤمل بن أميل قلت\nنعم اصلح الله أمير المؤمنين أنا المؤمل بن أميل قال أتيت غلاما غرا كريما فخدعته فانخدع قلت نعم أصلح الله الأمير أتيت غلاما غرا كريما فخدعته فانخدع قال فكأن ذلك أعجبه فقال أنشدني ما قلت فيه فأنشدته","topic":"أخبار المؤمل و نسبه","topicNo":284,"sp":0,"spl":"أخبار المؤمل و نسبه — المنصور يسترد ما اغدقه عليه المهدي","tags":["الرواية والكتابة"],"loc":3719},
{"id":"b284-4","bab":"الجزء 22","sec":"قصيدته في المهدي — مبايعته لموسى و هارون","page":"ج22 ص249 – ج22 ص250","text":"هو المهدي إلا أن فيه ... مشابهة من القمر المنير تشابه ذا و ذا فهما إذا ما ... أنارا مشكلان على البصير فهذا في الظلام سراج ليل ... و هذا في النهار ضياء نور و لكن فضل الرحمن هذا ... على ذا بالمنابر و السرير وبالملك العزيز فذا أمير ... و ماذا بالأمير ولا الوزير و بعض الشهر ينقص ذا وهذا ... منير عند نقصان الشهور فيا بن خليفة الله المصفى ... به تعلو مفاخرة الفخور لئن فت الملوك و قد توافوا ... إليك من السهولة والوعور لقد سبق الملوك أبوك حتى ... بقوا من بين كاب أو حسير و جئت مصليا تجري حثيثا ... و ما بك حين تجري من فتور فقال الناس ما هذان إلا ... كما بين الخليق إلى الجدير لئن سبق الكبير لأهل سبق ... له فضل الكبير على الصغير و إن بلغ الصغير مدى كبير ... فقد خلق الصغير من الكبير\nفقال و الله لقد أحسنت و لكن هذا لا يساوي عشرين ألف درهم فأين المال قلت هو هذا قال يا ربيع امض معه فأعطه أربعة آلاف درهم وخذ الباقي\nقال المؤمل فخرج معي الربيع وحط ثقلي ووزن لي من المال أربعة آلاف درهم و أخذ الباقي فلما ولي المهدي الخلافة ولي ابن ثوبان المظالم فكان يجلس للناس بالرصافة فأذا ملأ كساءه رقاعا رفعها إلى المهدي فرفعت إليه رقعة فلما دخل بها ابن ثوبان جعل المهدي ينظر في الرقاع حتى إذا وصل إلى رقعتي ضحك فقال له ابن ثوبان أصلح الله أمير المؤمنين ما رأيتك ضحكت من شيء من هذه الرقاع إلا الرقعة فقال هذه رقعة أعرف سببها ردوا إليه عشرين ألف درهم فردوها إلي و انصرفت\nأخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن سعد بن أبي سعد قال حدثني الحكم بن موسى السلولي قال حدثني سعد بن أخي العوفي قال قدم على المهدي في بيعة ابن ابنيه موسى وهارون المؤمل بن أميل المحاربي و الحسين بن يزيد بن أبي الحكم السلولي و قد أوفدهما هاشم بن سعد الحميري من الكوفة فقدما على المهدي في عسكره فأنشده المؤمل\n(هاك بياعنا يا خير و ال ... فقد جدنا به لك طائعينا)\n(فإن تفعل فأنت لذاك أهل ... ففضلك يا بن خير الناس فينا)\n(وعدلك يا بن وارث خير خلق ... نبي الله خير المرسلينا)\n(فإن أبا أبيك وأنت منه ... هو العباس وارثه يقينا)\n(أبان به الكتاب وذاك حق ... ولسنا للكتاب مكذبينا)\n(بكم فتحت وأنتم غير شك ... لها بالعدل أكرم خاتمينا)\n(فدونكها فأنت لها محل ... حباك بها إله العالمينا)\n(ولو قيدت لغيركم اشمأزت ... وأعيت أن تطيع القائدينا)\nأمر لهما بثلاثين ألف درهم فجيء بالمال فألقي بينهما فأخذ كل واحد منهما بدرة وصدع الأخرى بينهما فأخذ هذا نصفا وهذا نصفا أخبرني جعفر بن قدامة قال حدثنا حماد بن إسحاق عن أبيه عن عبد الله بن أمين عن أبي محمد اليزيدي عن المؤمل بن أميل قال صرت إلى المهدي بجرجان فمدحته بقولي\n(تعز ودع عنك سلمى وسر ... حثيثا على سائرات البغال)\n(وكل جواد له ميعة ... يخب بسرحك بعد الكلال)\n(إلى الشمس شمس بني هاشم ... وما الشمس كالبدر أو كالهلال)\n(و يضحكه أن يدوم السؤال ... و يتلف في ضحكه كل مال)\nاستحسنها المهدي وأمر لي بعشرة آلاف ردهم و شاع الشعر و كان في عسكره رجل يعرف بأبي الهوسات يغني فغنى في الشعر لرفقائه و بلغ ذلك المهدي فبعث إليه سرا فدخل عليه فغناه فأمر له بخمسة\nآلاف درهم و أمر لي بعشرة آلاف درهم أخرى و كتب بذلك صاحب البريد إلى المنصور ثم ذكر باقي الخبر على ما تقدم قبله و زاد فيه أن المنصور\nقال له جئت إلى غلام حدث فخدعته حتى أعطاك من مال الله عشرين ألف درهم لشعر قلته فيه غير جيد و أعطاك من رقيق المسلمين ما لا يملكه و أعطاك من الكراع و الأثاث ما أسرف فيه يا ربيع خذ منه ثمانية عشر ألف درهم و أعطه ألفين و لاتعرض لشيء من الأثاث و الدواب و الرقيق ففي ذلك غناؤه فأخذت مني بخواتهما ووضعت في الخزائن فلما ولي المهدي دخلت إليه في المتظلمين فلما رآني ضحك و قال مظلمة أعرفها ولا احتاج إلى بينة عليها و جعل يضحك و أمر بالمال فرد إلي بعينه وزاد فيه عشرة آلاف","topic":"أخبار المؤمل و نسبه","topicNo":284,"sp":1,"spl":"قصيدته في المهدي — مبايعته لموسى و هارون","tags":["المديح"],"loc":3720},
{"id":"b284-5","bab":"الجزء 22","sec":"كان شيخا مصفرا أعمى","page":"ج22 ص252","text":"أخبرني الحسن بن علي الخفاف قال حدثنا محمد بن القاسم بن مهرويه قال حدثني حذيفة بن محمد الطائي قال حدثني أبي قال رأيت المؤمل شيخا مصفرا نحيفا أعمى فقلت له لقد صدقت في قولك\n(وقد زعموا لي أنها نذرت دمي ... و مالي بحمد الله لحم و لا دم)\nقال نعم فديتك و ما كنت أقول إلا حقا قال محمد بن القاسم و حدثني عبد الله بن طاهر أن أول هذا الشعر\n(حلمت بكم في نومتي فغضبتم ... ولا ذنب لي أن كنت في النوم أحلم)\n(سأطرد عني النوم كيلا أراكم ... إذا ما أتاني النوم و الناس نوم)\n(تصارمني و الله يعلم أنني ... أبربها من والديها وأرحم)\n\n(و قد زعموا لي إنها نذرت دمي ... وما لي بحمد الله لحم ولا دم)\n(برى حبها لحمي ولم يبق لي دما ... وإن زعموا أني صحيح مسلم)\n(فلم أر مثل الحب صح سقيمه ... ولا مثل من لا يعرف الحب يسقم)\n(ستقتل جلدا باليا فوق أعظم ... وليس يبالي القتل جلد وأعظم)\nي هذه الأبيات التي أولها\n(وقد زعموا لي إنها نذرت دمي ... )\nلنبيه لحم من خفيف الثقيل المطلق في مجرى الوسطى عن ابن المكي أخبرني الحسن بن علي قال حدثنا ابن مهرويه قال حدثني محمد بن احمد بن علي قال لما قال المؤمل\n(شف المؤمل يوم الحيرة النظر ... ليت المؤمل لم يخلق له بصر)\nمي وأري في منامه هذا ما تمنيت أخبرني حبيب بن نصر قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الحسن الشيباني قال را ى المؤمل في منامه قائلا يقول أنت المتألي على الله إلا يعذب المحبين حيث تقول\n(يكفي المحبين في الدنيا عذابهم ... و الله لا عذبتهم بعدها سقر)\nفقال له نعم فقال كذبت يا عدو الله ثم ادخل إصبعيه في عينيه و قال له أنت القائل\n(شف المؤمل يوم الحيرة النظر ... ليت المؤمل لم يخلق له بصر)\nذا ما تمنيت فانتبه فزعا فإذا هو قد عمي اخبرني الحسن بن علي قال حدثنا احمد بن زهير قال حدثنا مصعب الزبيري قال انشد المهدي قول المؤمل\n(قتلت شاعر هذا الحي من مضر ... و الله يعلم ما ترضى بذا مضر)\nضحك و قال لو علمنا إنها فعلت ما رضينا ولغضبنا له وأنكرنا\n(بكيت حذار البين علما بما الذي ... إليه فؤادي عند ذلك صائر)\n(و قال أناس لو صبرت وإنني ... على كل مكروه سوى البين صابر)\nلشعر لأبي مالك الأعرج و الغناء لإبراهيم الموصلي خفيف ثقيل بالوسطى من جامع صنعته ورواية الهشامي قال الهشامي وفيه ليزيد حوراء ثاني ثقيل ولسليم ثقيل أول","topic":"أخبار المؤمل و نسبه","topicNo":284,"sp":2,"spl":"كان شيخا مصفرا أعمى","tags":["الحب والغزل"],"song":2,"loc":3721,"partial":1},
{"id":"b285-2","bab":"الجزء 22","sec":"أخبار أبي مالك ونسبه — رثاؤه لأبيه","page":"ج22 ص254 – ج22 ص255","text":"أبو مالك النضر بن أبي النضر التميمي هذا اكثر ما وجدته من نسبه وكان مولده ومنشؤه بالبادية ثم وفد إلى الرشيد و مدحه وخدمه فأحمد مذهبه ولحظته عناية من الفضل بن يحيى فبلغ ما أحب وهو صالح الشعر متوسط المذهب ليس من طبقة شعراء عصره المجيدين ولا من المرذولين\nأخبرني أبو دلف هاشم بن محمد الخزاعي قال حدثنا احمد بن الهيثم بن فراس قال كان أبو مالك النضر بن أبي النضر التميمي مع الرشيد وكان أبوه مقيما بالبادية فأصاب قوم من عشيرته الطريق وقطعوه عن بعض القوافل فخرج عامل ديار مضر و كان يقال له جيال إلى ناحية كانت فيها طوائف من بني تميم فقصدهم وهم غارون فأخذ منهم\nجماعة فيهم أبو النضر أبو أبي مالك الأعرج و كان ذا مال فطلبه فيمن طلب من الجناة وطمع في ماله فضربه ضربا أتى فيه على نفسه و بلغ ذلك أبا مالك فقال يرثيه\n(فيم يلحى على بكائي العذول ... والذي نابني فظيع جليل)\n(عد هذا الملام عني إلى غيري ... فقلبي ببثه مشغول)\n(راعني والدي جنت كف جيال ... عليه فراح وهو قتيل)\n(أيها الفاجعي بركني وعزي ... هبلتني إن أرعك الهبول)\n(سمتني خطة الصغار وأظلمت ... نهاري علي غالتك غول)\n(ما عداني الجفاء عنك ولكن ... لم يدلني من الزمان مديل)\n(زال عنا السرور إذ زلت عنا ... وازدهانا بكاؤنا والعويل)\n(ورأينا القريب منا بعيدا ... وجفانا صديقنا والخليل)\n(ورمانا العدو من كل وجه ... وتجنى على العزيز الذليل)\n(يا أبا النضر سوف أبكيك ما عشت ... سويا وذاك مني قليل)\n(حملت نعشك الملائكة الأبرار ... إذ مالنا إليك سبيل)\n(غير أني كذبتك الود لم تقطر ... جفوني دما وأنت قتيل)\n(رضيت مقلتي بإرسال دمعي ... وعلى مثلك النفوس تسيل)\n(أسواك الذي أجود عليه ... بدمي إنني إذا لبخيل)\n(عثر الدهر فيك عثرة سوء ... لم يقل مثلها المعين المقيل)\n(قل إن ضن بالحياة فإني ... بعده للحياة قال ملول)\n(إن بالسفح من ضباعة قومي ... ليس منهم وهم أدان وصول)\n(لا يزورون جارهم من قريب ... وهم في التراب صرعى حلول)\n(حفرة حشوها وفاء وحلم ... وندى فاضل ولب أصيل)\n(وعفاف عما يشين وحلم ... راجح الوزن بالرواسي يميل)\n(ويمين بنانها غير جعد ... وجبين صلت وخد أسيل)\n(وامرؤ أشرقت صفيحة خديه ... عليه بشاشة وقبول)\n\n(لئن مصر فاتتني بما كنت أرتجي ... وأخلفني فيها الذي كنت آمل)\n(فما كل ما يخشى الفتى بمصيبه ... ولا كل ما يرجو الفتى هو نائل)\nلشعر لأبي دهمان والغناء لابن جامع ثقيل أول بالوسطى عن الهشامي انتهت أخبار مالك ونسبه","topic":"أخبار أبي مالك ونسبه","topicNo":285,"sp":0,"spl":"أخبار أبي مالك ونسبه — رثاؤه لأبيه — كان أميرا على نيسابور","tags":[],"song":1,"loc":3722},
{"id":"b285-3","bab":"الجزء 22","sec":"أخبار أبي دهمان","page":"ج22 ص257","text":"أبو دهمان الغلابي شاعر من شعراء البصرة ممن أدرك دولتي بني أمية وبني العباس ومدح المهدي وكان طيبا ظريفا مليح النادرة وهو القائل لما ضرب المهدي أبا العتاهية بسبب عشقه عتبة\n(لولا الذي أحدث الخليفة في العشاق ... من ضربهم إذا عشقوا)\n(لبحت باسم الذي أحب ولكني ... امرؤ قد ثناني الفرق)\nحدثني بذلك الصولي عن محمد بن موسى عن محمد بن أبي العتاهية وأخبرني جحظة عن حماد بن إسحاق عن أبيه قال قال رجل لأبي دهمان ألا أحدثك بظريفة قال بلى قال كنا عند فلان فمد رجله هكذا فضرط ومد المحدث رجله يحكيه فضرط فقال له أبو دهمان يا هذا أنت أحذق خلق الله بحكاية","topic":"أخبار أبي مالك ونسبه","topicNo":285,"sp":0,"spl":"أخبار أبي مالك ونسبه — رثاؤه لأبيه — كان أميرا على نيسابور","tags":["المديح","اللهو والمزاح"],"loc":3723},
{"id":"b285-4","bab":"الجزء 22","sec":"كان أميرا على نيسابور","page":"ج22 ص258","text":"نسخت من كتاب بخط ميمون بن هارون بلغني أن أبا دهمان مر وهو أمير بنيسابور على رجل جالس ومعه صديق له يسايره فقام الناس إليه ودعوا له إلا ذلك الرجل فقال أبو دهمان لصديقه\nوهو يسايره أما ترى ذلك الرجل في النظارة وترى تيهه علي فقال له وكيف يتيه عليك وأنت الأمير قال لأنه قد ناكني وأنا غلام وأخبرني الحسن بن علي\nقال حدثنا أحمد بن الحارث عن المدائني قال مرض أبو دهمان مرضا أشفى منه على الموت فأوصى وأملى وصيته على كاتبه وأوصى فيها بعتق غلام كان له واقفا فلما فرغ غدا الغلام بالرقعة فأتربها ونظر إليه أبو دهمان فقال له نعم أتربها يا بن الزانية عسى أن يكون أنجح للحاجة لا شفاني الله إن أنجحت وأمر به فأخرج لوقته فبيع\n(يكركما كر الكليبي مهره ... وما كر إلا خيفة أن يعيرا)\n(فلا صلح حتى تزحف الخيل والقنا ... بنا وبكم او يصدر الأمر مصدرا)\nلشعر لأبي حزابة التميمي والغناء لابن جامع ثاني ثقيل بالبنصر وهذا الشعر يرثي به أبو حزابة رجلا من بني كليب بن يربوع يقال له ناشرة اليربوعي قتل بسجستان في فتنة ابن الزبير وكان سيدا شجاعا","topic":"أخبار أبي مالك ونسبه","topicNo":285,"sp":0,"spl":"أخبار أبي مالك ونسبه — رثاؤه لأبيه — كان أميرا على نيسابور","tags":[],"song":1,"loc":3724},
{"id":"b285-5","bab":"الجزء 22","sec":"رثاؤه لناشرة اليربوعي","page":"ج22 ص259","text":"أنشدنيه جعفر بن قدامة قال أنشدني أبو هفان وأحمد بن أبي طاهر قالا أنشدنا عبد الله بن احمد العدوي لأبي حزابة يرثي ناشرة اليربوعي وقتل بسجستان في فتنة ابن الزبير قال\n(لعمري لقد هدت قريش عروشنا ... بأبيض نفاح العشيات أزهرا)\n(وكان حصادا للمنايا زرعنه ... فهلا تركن النبت ما كان أخضرا)\n(لحا الله قوما أسلموك وجردوا ... عناجيج أعطتها يمينك ضمرا)\n(أما كان فيهم ماجد ذو حفيظة ... يرى الموت في بعض المواطن أفخرا)\n(يكر كما كر الكليبي مهره ... وما كر إلا خشية أن يعيرا)\nريد ما كان في هؤلاء القوم من يكر كما كر ناشرة الكليبي مهره","topic":"أخبار أبي مالك ونسبه","topicNo":285,"sp":1,"spl":"رثاؤه لناشرة اليربوعي","tags":["الموت"],"loc":3725},
{"id":"b286-2","bab":"الجزء 22","sec":"أخبار أبي حزابة ونسبه — أبطىء عليه بالجائزة فأنشد","page":"ج22 ص260 – ج22 ص261","text":"أبو حزابة اسمه الوليد بن حنيفة أحد بني ربيعة بن حنظلة بن مالك بن زيد مناة ين تميم شاعر من شعراء الدولة الأموية بدوي حضر وسكن البصرة ثم اكتتب في الديوان و ضرب عليه البعث إلى سجستان فكان بها مدة وعاد إلى البصرة وخرج مع ابن الأشعث لما خرج على عبد الملك و أظنه قتل معه وكان شاعرا راجزا فصيحا خبيث اللسان هجاء\nفأخبرنا الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك الزيات قال حدثنا محمد الهيثم الشامي قال حدثني عمي أبو فراس عن العذري قال دخل أبو حزابة على طلحة الطلحات الخزاعي وقد استعمله يزيد بن معاوية على سجستان و كان أبو حزابة قد مدحه فأبطأت عليه الجائزة من جهته ورأى ما يعطى غيره من الجوائز فأنشده\n(وأدليت دلوي في دلاء كثيرة ... فجئن ملاء غير دلوي كما هيا)\n(وأهلكني ألا تزال رغيبة ... تقصر دوني أو تحل ورائيا)\n(أراني إذا استمطرت منك سحابة ... لتمطرني عادت عجاجا وسافيا)\nال فرماه طلحة بحق فيه درة فأصاب صدره ووقعت في حجره و يقال بل أعطاه أربعة أحجار و قال له لا تخدع عنها فباعها بأربعين آلفا ومات طلحة بسجستان ثم ولي من بعده رجل من بني عبد شمس يقال له عبد الله بن علي بن عدي و كان شحيحا فقال له أبو حزابة\n(يا بن علي برح الخفاء ... قد علم الجيران والاكفاء)\n(انك أنت النزل واللفاء ... أنت لعين طلحة الفداء)\n(بنو عدي كلهم سواء ... كأنهم زينية جراء)","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":0,"spl":"أخبار أبي حزابة ونسبه — أبطىء عليه بالجائزة فأنشد — قصيدة يرثي فيها طلحة ويذم عبد الله بن ","tags":["الهجاء","المديح"],"loc":3726},
{"id":"b286-3","bab":"الجزء 22","sec":"قصيدة يرثي فيها طلحة ويذم عبد الله بن علي","page":"ج22 ص262","text":"قال ثم وليها بعد عبد الله بن علي عبد العزيز بن عبد الله بن عامر بن كريز أيام الفتنة فاستأذنه أبو حزابة أن يأتي البصرة فأذن له فقدمها وكان الناس يحضرون المربد ويتناشدون الاشعار ويتحادثون ساعة من\nالنهار فشهدهم أبو حزابة وأنشدهم مرثية له في طلحة الطلحات يضمنها ذما لعبد الله بن علي وهي قوله\n(هيهات هيهات الجناب الأخضر ... والنائل الغمر الذي لا ينزر)\n(واراه عنا الجدث المغور ... قد علم غداة استعبروا)\n(والقبر بين الطلحات يحفر ... أن لن يروا مثلك حتى ينشروا)\n(أنا أتانا جرز محمر ... أنكرة سريرنا و المنبر)\n(و المسجد المحتضر المطهر ... وخلف يا طلح منك أعور)\n(بلية يا ربنا لا نسخر ... أقل من شبرين حين يشبر)\n(مثل أبي القعواء لا بل أقصر ... )\nهجو عون بن سلامة قال وأبو القعواء حاجب لطلحة كان قصيرا فقال عون بن عبد الرحمن بن سلامة وسلامة أمه وهو رجل من بني تميم بن مرة قيس بئسما قلت أتشاهر الناس بشتم قريش فقال له إني لم اعم إنما سميت رجلا واحدا فأغلظ له عون حتى انصرف عن ذلك الموضع ثم أمر عون ابن أخ له فدعا أبا حزابة فأطعمه وسقاه و خلط في شرابه شبرما فسلحه فخرج أبو حزابة وقد أخذه بطنه فسلح\nعلى بابهم وفي طريقه حتى بلغ أهله ومرض أشهرا ثم عوفي فركب فرسا له ثم أتى المربد فإذا عون بن سلامة واقف فصاح به فوقف ولو لم يقف كان أخف لهجائه فقال له أبو حزابة\n(يا عون قف واستمع الملامه ... لا سلم الله على سلامه)\n(زنجية تحسبها نعامه ... شكاء شان جسمها دمامه)\n(ذات حر كريشتي حمامه ... بينهما بظر كرأس الهامه)\n(أعلمتها وعالم العلامه ... لو أن تحت بظرها صمامه)\n(لدفعت قدما بها أمامه ... )\nكان الناس يصيحون به\n(أعلمتها وعالم العلامة ... )\nخبرني عمي قال حدثنا احمد بن الهيثم بن فراس قال حدثني عمي أبو فراس عن الهيثم بن عدي قال كان عبد الله بن خلف أبو طلحة الطلحات مع عائشة يوم الجمل و قتل معها يومئذ وعلى بني خلف نزلت عائشة بالبصرة في القصر المعروف بقصر بني خلف وكان هوى طلحة الطلحات أمويا وكانت بنو أمية مكرمين له فأنشد أبو حزابة يوما طلحة\n(يا طلح بأبي مجدك الأخلافا ... والبخل لا يعترف اعترافا)\n(إن لنا أحمرة عجافا ... يأكلن كل ليلة إكافا)","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":0,"spl":"أخبار أبي حزابة ونسبه — أبطىء عليه بالجائزة فأنشد — قصيدة يرثي فيها طلحة ويذم عبد الله بن ","tags":["الهجاء","اللهو والمزاح"],"loc":3727,"partial":1},
{"id":"b286-4","bab":"الجزء 22","sec":"رفض الوقوف بباب يزيد بن معاوية","page":"ج22 ص265","text":"فأمر له طلحة بإبل ودراهم و قال له هذه مكان أحمرتك أخبرني عمي قال حدثنا الكراني قال حدثني العمري عن لقيط قال قيل لأبي حزابة لو أتيت يزيد بن معاوية لفرض لك وشرفك وألحقك بعلية أصحابه فلست دونهم وكان أبو حزابة يومئذ غلاما حدثا وكان معاوية حيا ويزيد أميرا يومئذ فلما أكثر قومه عليه في ذلك وفي قولهم إنك ستشرف بمصيرك إليه قال\n(يشرفني سيفي وقلب مجانب ... لكل لئيم باخل ومعلهج)\n(وكري على الأبطال طرءفا كأنه ... ظليم وضربي فوق رأس المدجج)\n(وقولي إذا ما النفس جاشت وأجهشت ... مخافة يوم شره متأجج)\n(عليك غمار الموت يا نفس إنني ... جريء على درء الشجاع المهجهج)\nلما أكثر عليه قومه وعنفوه في تأخره أتى يزيد بن معاوية فأقام ببابه شهرا لا يصل إليه فرجع و قال والله لا يراني ما حملت عيناي الماء إلا أسيرا أو قتيلا وأنشأ يقول\n(فو الله لا آتي يزيد ولو حوت ... أنامله ما بين شرق إلى غرب)\n(لأن يزيدا غير الله ما به ... جنوح إلى السوءى مصر على الذنب)\n(فقل لبني حرب تقوا الله وحده ... ولا تسعدوه في البطالة واللعب)\n(ولا تأمنوا التغيير أن دام فعله ... ولم ينهه عن ذاك شيخ بني حرب)\n(أيشربها صرفا إذا الليل جنه ... معتقة كالمسك تختال في العلب)\n(و يلحى عليها شاربيها وقلبه ... يهيم بها أن غاب يوما عن الشرب)","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":1,"spl":"رفض الوقوف بباب يزيد بن معاوية — خبر رهن سرجه","tags":["اللهو والمزاح","الوصف والطبيعة"],"loc":3728},
{"id":"b286-5","bab":"الجزء 22","sec":"خبر رهن سرجه","page":"ج22 ص266","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة عن المدائني قال لما خرج عبد الرحمن بن محمد بن الأشعث على الحجاج وكان معه أبو حزابة فمروا بدستبى وبها مستراد الصناجة وكانت لا يبيت بها أحد إلا بمائة درهم فبات بها أبو حزابة ورهن عندها سرجه فلما أصبح وقف لعبد الرحمن فلما أقبل صاح به وقال\n(أمر عضال نابني في العج ... كأنني مطالب بخرج)\n(ومستراد ذهبت بالسرج ... في فتنة الناس وهذا الهرج)\nعرف ابن الأشعث القصة وضحك وأمر بان يفتك له سرجه ويعطى معه ألف درهم وبلغت القصة الحجاج فقال أيجاهر في عسكره بالفجور فيضحك ولا ينكر ظفرت به أن شاء الله","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":1,"spl":"رفض الوقوف بباب يزيد بن معاوية — خبر رهن سرجه","tags":["اللهو والمزاح","السفر والحج","الخمر"],"loc":3729},
{"id":"b286-6","bab":"الجزء 22","sec":"هجوه عبد الله بن علي","page":"ج22 ص267","text":"أخبرني عمي قال حدثنا الكراني عن العمري عن العتبي قال مدح أبو حزابة عبد الله بن علي العبشمي وهو على سجستان فلم يثبه فقال يهجوه\n(هبت تعاتبني أما ... مة في السماحة والفضال)\n(وأبيت عند عتابها ... إلا خلائق ذي النوال)\n(أعطي أخي وأحوطه ... جهدي وأبذل جل مالي)\n(وأقيه عند تشاجر الأبطال ... بالأسل النهال)\n(حفظا له ورعاية ... للخاليات من الليالي)\n(إذ نحن نشرب قهوة ... درياقة كدم الغزال)\n(حمراء يذهب ريحها ... ما في الرؤوس من الخبال)\n(وإذا تشعشع في الإناء ... رمت أخاها باغتيال)\n(وعلا الحباب فخلته ... عقدا ينظم من لآلي)\n(تشفي السقيم بريحها ... و تميته قبل الإجال)\n(تلك التي تركت فؤاد ... أبي حزابة في ضلال)\n(لا يستفيق ولا يفيق ... نزيفها في كل حال)\n(وإذا الكماة تنازلوا ... ومشى الرجال إلى الرجال)\n(وبدت كتائب تمتري ... مهج الكتائب بالعوالي)\n(فأبو حزابة عند ذاك ... أخو الكريهة والنزال)\n(يمشي الهوينى معلما ... بالسيف مشيا غير آل)\n(كالليث يترك قرنه ... متجدلا بين الرمال)\n(إني نذير بني تميم ... من أخي قيل وقال)\n(من لا يجود ولا يسود ... ولا يجير من الهزال)\n(وتراه حين يجيئه السؤال ... يولع بالسعال)\n(متشاغلا متنحنحا ... كالكلب جمجم للعظال)\n(فارفض قريشا كلها ... من أجل ذي الداء العضال)\nعني عبد الله بن علي العبشمي أخبرني الحسن بن علي قال حدثنا هارون بن محمد بن عبد الملك قال حدثني محمد بن الهيثم الشامي قال حدثني عمي أبو فراس عن العذري\nقال دخل أبو حزابة على عمارة بن تميم و محمد بن الحجاج وقد قدما سجستان لحرب عبد الرحمن بن محمد بن الأشعث وكان عبد الرحمن لما قدماها هرب ولم يبق بسجستان من أصحابه إلا سبعمائة رجل من بني تميم كانوا مقيمين بها فقال لهما أبو حزابة إن الرجل قد هرب منكما ولم يبق من أصحابه أحد وإنما بسجستان من كان بها من بني تميم قبل قدومه فقالا\nله ما لهم عندنا أمان لأنهم قد كانوا مع ابن الأشعث وخلعوا الطاعة فقال ما خلعوها ولكنه ورد عليهم في جمع عظيم لم يكن لهم بدفعه طاقة فلم يجيباه إلى ما أراد وعاد إلى قومه وحاصرهم أهل الشام فاستقتلت بنو تميم فكانوا يخرجون في كل يوم إليهم فيواقعونهم ويكسبونهم بالليل وينهبون أطرافهم حتى ضجروا بذلك فلما رأى عمارة فعلهم صالحهم وخرجوا إليه فلما رأى قلتهم قال أما كنتم إلا ما أرى قالوا نعم فان شئت أن نقيلك الصلح أقلناك وعدنا للحرب فقال أنا غني عن ذلك وآمنهم فقال أبو حزابة في ذلك","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":2,"spl":"هجوه عبد الله بن علي — مدحه لبني تميم","tags":["الحب والغزل","المديح"],"loc":3730},
{"id":"b286-7","bab":"الجزء 22","sec":"مدحه لبني تميم","page":"ج22 ص269","text":"(لله عينا من رأى من فوارس ... أكر على المكروه منهم وأصبرا)\n(وأكرم لو لاقوا سوادا مقاربا ... ولكن لقوا طما من البحر أخضرا)\n(فما برحوا حتى أعضوا سيوفهم ... ذرى الهام منهم والحديد المسمرا)\n(وحتى حسبناهم فوارس كهمس ... حيوا بعد ما ماتوا من الدهر أعصرا)\n\n(إذا الله لم يسق إلا الكرام ... فسقى وجوه بني حنبل)\n(وسقى ديارهم باكرا ... من الغيث في الزمن الممحل)\n(تكفكفه بالعشي الجنوب ... وتفرغه هزة الشمأل)\nكأن الرباب دوين السحاب ... نعام تعلق بالأرجل\nالشعر لزهير السكب التميمي المازني والغناء لإبراهيم خفيف رمل بالبنصر عن الهشامي وحبش","topic":"أخبار أبي حزابة ونسبه","topicNo":286,"sp":2,"spl":"هجوه عبد الله بن علي — مدحه لبني تميم","tags":["الموت"],"song":1,"loc":3731},
{"id":"b287-1","bab":"الجزء 22","sec":"نسب زهير السكب وأخباره","page":"ج22 ص271","text":"هو زهير بن عروة بن جلهمة بن حجر بن خزاعي شاعر جاهلي وإنما لقب السكب ببيت قاله وقال فيه\n(برق يضيء خلال البيت أسكوب ... )\nعره في الرغبة بالعودة إلى عشيرته أخبرني يحيى بن علي بن يحيى إجازة قال حدثنا أبو هفان عن سعيد بن هريم عن أبيه قال كان زهير بن عروة المازني الملقب بالسكب جاهليا وكان من أشراف بني مازن وأشدائهم وفرسانهم وشعرائهم فغاضب قومه في شيء ذمه منهم وفارقهم إلى غيرهم من بني تميم فلحقه فيهم ضيم و أراد الرجوع إلى عشيرته فأبت نفسه ذلك عليه فقال يتشوق ناسا منهم كانوا بني عمه دينه يقال لهم بنو حنبل\n(إذا لله لم يسق إلا الكرام ... فسقى وجوه بني حنبل)\n(ملثا أحم دواني السحاب ... هزيم الصلاصل والأزمل)\n(تكركره خضخضات الجنوب ... وتفرغه هزة الشمأل)\n(كأن الرباب دوين السحاب ... نعام تعلق بالأرجل)\n(فنعم بنو العم والأقربون ... لدى حطمة الزمن الممحل)\n(ونعم المواسون في النائبات ... للجار والمعتفي المرمل)\n(ونعم الحماة الكفاة العظيم ... إذا غائظ الأمر لم يحلل)\n(ميامين صبر لدى المعضلات ... على موجع الحدث المعضل)\n(مباذيل عفوا جزيل العطاء ... إذا فضلة الزاد لم تبذل)\n(هم سبقوا يوم جري الكرام ... ذوي السبق في الزمن الاول)\n(وساموا إلى المجد أهل الفعال ... فطالوا بفعلهم الأطول)\nخبرنا هاشم بن محمد الخزاعي قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال سأل رجل أبا عمرو بن العلاء عن الرباب فقال أما تراه معلقا بالسحاب كالذيل له أما سمعت قول صاحبنا السكب\n(كأن الرباب دوين السحاب ... نعام تعلق بالأرجل)\n\n(سلا عن تذكره تكتما ... وكان رهينا بها مغرما)\n(وأقصر عنها وآثارها ... تذكره داءها الأقدما)\nلشعر للنمر بن تولب والغناء لخزرج خفيف ثقيل أول بالوسطى عن الهشامي","topic":"نسب زهير السكب وأخباره","topicNo":287,"sp":0,"spl":"نسب زهير السكب وأخباره","tags":["الرواية والكتابة"],"song":1,"loc":3732,"partial":1},
{"id":"b288-2","bab":"الجزء 22","sec":"أخبار النمر بن تولب ونسبه — سمي بالكيس لجودة شعره","page":"ج22 ص273 – ج22 ص274","text":"هو النمر بن تولب بن أقيش بن عبد كعب بن عوف بن الحارث بن عوف بن وائل بن قيس بن عكل واسم عكل عوف بن عبد مناف بن أد بن طابخة بن إلياس بن مضر بن نزار شاعر مقل مخضرم أدرك الجاهلية وأسلم فحسن إسلامه ووفد إلى النبي وكتب له كتابا فكان في أيدي أهله وروى عنه حديثا سأذكره في موضعه وكان النمر أحد أجواد العرب المذكورين وفرسانهم\nحدثنا محمد بن العباس اليزيدي قال أخبرنا محمد بن حبيب قال قال الأصمعي كان أبو عمرو بن العلاء يسمي النمر بن تولب الكيس لجودة شعره وحسنه أخبرنا محمد بن خلف بن المرزبان قال حدثنا عبد الله بن محمد قال أخبرنا محمد بن سلام الجمحي وأخبرنا به أبو خليفة في كتابه إلي عن محمد بن سلام قال\nكان النمر بن تولب جوادا لا يليق شيئا وكان شاعرا فصيحا جريئا على المنطق وكان أبو عمرو بن العلاء يسميه الكيس لحسن شعره أخبرني هاشم بن محمد أبو دلف الخزاعي\nقال أخبرنا الرياشي قال حدثنا الأصمعي قال حدثنا قرة بن خالد عن يزيد بن عبد الله بن الشخير أخي مطرف وأخبرني أبو خليفة في كتابه إلي قال\nحدثنا محمد بن سلام قال وفد النمر بن تولب على النبي وكتب له كتابا أخبرناه قرة بن خالد السدوسي وسعيد بن إياس الجريري عن أبي العلاء يزيد بن عبد الله بن الشخير أخي مطرف","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":0,"spl":"أخبار النمر بن تولب ونسبه — سمي بالكيس لجودة شعره — حظي بكتاب من رسول الله — كان مثالا للك","tags":["اللهو والمزاح","الرواية والكتابة"],"loc":3733}]);
window.__BOOK__['p11'].push([{"id":"b288-4","bab":"الجزء 22","sec":"حظي بكتاب من رسول الله — كان مثالا للكرم","page":"ج22 ص275 – ج22 ص276","text":"أخبرني عمي عن القاسم عن محمد الأنباري عن أحمد بن عبيد عن الأصمعي عن قرة بن خالد عن يزيد بن عبد الله أخي مطرف واللفظ قريب بعضه من بعض\nقال بينما نحن بهذا المربد جلوس يعني مربد البصرة إذ أتى علينا أعرابي أشعث الرأس فوقف علينا فقلنا والله لكأن هذا الرجل ليس من أهل هذا البلد\nقال أجل وإذا معه قطعة من جراب أو أديم فقال هذا كتاب كتبه لي رسول الله فقرأناه فإذا فيه مكتوب بسم الله الرحمن الرحيم هذا كتاب من محمد رسول الله لبني زهير هكذا\nقال أحمد بن عبيد وقال الباقون لبني زهير بن أقيش حي من عكل إنكم إن شهدتم أن لا إله إلا الله وأني رسول الله وأقمتم الصلاة وآتيتم الزكاة وفارقتم المشركين\nوأعطيتم الخمس من الغنائم وسهم النبي والصفي فأنتم آمنون بأمان الله وأمان رسوله وقال أحمد بن عبيد الله في خبرة خاصه لكم ما للمسلمين وعليكم ما عليهم وقالوا جميعا في الخبر فقال له القوم حدثنا رحمك الله ما سمعت من رسول الله فقال سمعت رسول الله يقول ( صوم شهر الصبر وصوم ثلاثة أيام من كل شهر يذهبن كثيرا من وحر الصدر\nقال له القوم أأنت سمعت هذا من رسول الله فقال أراكم تخافون أن أكذب على رسول الله لا حدثتكم حديثا ثم أهوى إلى الصحيفة وانصاع مدبرا قال يزيد بن عبد الله فقيل لي بعد ما مضى هذا النمر بن تولب العكلي الشاعر\nأخبرني محمد بن خلف قال حدثنا عبد الله بن محمد بن خلف قال اخبرنا محمد بن سلام قال خرج النمر بن تولب بعدما كبر في إبله فسأله سائل فأعطاه فحل إبله فلما رجعت الإبل إذا فحلها ليس فيها فهتفت به امرأته وعذلته وقالت فهلا غير فحل إبلك فقال له\n(دعيني وأمري سأكفيكه ... وكوني قعيدة بيت ضباعا)\n(فإنك لن ترشدي غاويا ... ولن تدركي لك حظا مضاعا)\nوقال أيضا في عذلها إياه\n(بكرت باللوم تلحانا ... في بعير ضل أو حانا)\n(علقت لوا تكررها ... إن لوا ذاك أعيانا)\nال وأدرك الإسلام فأسلم","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":0,"spl":"أخبار النمر بن تولب ونسبه — سمي بالكيس لجودة شعره — حظي بكتاب من رسول الله — كان مثالا للك","tags":["الرواية والكتابة"],"loc":3734},
{"id":"b288-5","bab":"الجزء 22","sec":"شعره بعد أن خدعته زوجه","page":"ج22 ص277","text":"أخبرني الحسن بن علي قال حدثنا أحمد بن زهير قال حدثنا محمد بن سلام قال كان للنمر بن تولب أخ يقال له الحارث بن تولب وكان سيدا معظما فأغار الحارث على بني أسد فسبى امرأة منهم يقال لها جمرة بنت نوفل فوهبها لأخيه النمر بن تولب ففركته فحبسها حتى استقرت وولدت له أولادا ثم قالت له في بعض أيامها أزرني أهلي فإني قد اشتقت إليهم فقال لها أني أخاف أن صرت إلى اهلك أن تغلبيني على نفسك فواثقته لترجعن إليه فخرج بها في الشهر الحرام حتى أقدمها بلاد بني أسد فلما أطل على الحي تركته واقفا وانصرفت إلى منزل بعلها الأول فمكثت طويلا فلم ترجع إليه فعرف ما صنعت وأنها اختدعته فانصرف و قال\n(جزى الله عنا جمرة ابنة نوفل ... جزاء مغل بالأمانة كاذب)\n(لهان عليها أمس موقف راكب ... إلى جانب السرحات أخيب خائب)\n(وقد سألت عني الوشاة ليكذبوا ... علي وقد أبليتها في النوائب)\n(وصدت كأن الشمس تحت قناعها ... بدا حاجب منها وضنت بحاجب)\nقال فيها أيضا\n(كل خليل عليه الرعاث ... والحبلات كذوب ملق)\nالحبلات واحداتها حبلة وهي جنس من الحلي قدر ثمر الطلح\n(وقامت إلي فأحلفتها ... بهدي قلائده تختفق)\n(بأن لا أخونك فيما علمت ... فإن الخيانة شر الخلق)\nقال فيها أشعارا كثيرة يطول ذكرها أخبرني اليزيدي عن محمد بن حبيب قال كان أبو عمرو يشبه شعر النمر بشعر حاتم الطائي","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":1,"spl":"شعره بعد أن خدعته زوجه — نسي امرأته بحب جديد","tags":["الحب والغزل","الجواري والنساء"],"loc":3735},
{"id":"b288-6","bab":"الجزء 22","sec":"صالح بن حسان يعتبره أفتى الشعراء","page":"ج22 ص278","text":"أخبرني الحسين بن علي قال حدثنا أحمد بن زهير قال حدثنا مصعب بن عبد الله الزبيري قال بلغني أن صالح بن حسان قال يوما لجلسائه أي الشعراء أفتى قالوا عمر بن أبي ربيعة وقالوا جميل وأكثروا القول فقال أفتاهم النمر بن تولب حين يقول\n(أهيم بدعد ما حييت وإن أمت ... فواحزنا من ذا يهيم بها بعدي)\nخبرني الحسن قال حدثنا أحمد بن زهير عن محمد بن سلام قال حج النمر بن تولب بعد هرب جمرة منه فنزل بمنى ونزلت جمرة مع زوجها قريبا منه فعرفته فبعثت إليه بالسلام وسألته عن خبره ووصته خيرا بولده منها فقال\n(فحييت عن شحط بخير حديثنا ... ولا يأمن الأيام إلا المضلل)\n(يود الفتى طول السلامة والغنى ... فكيف يرى طول السلامة يفعل)\nخبرني ابن المرزبان قال حدثنا أبو محمد اليزيدي عن الأصمعي وأخبرنا اليزيدي عن ابن حبيب عن الأصمعي قال لما وفد النمر بن تولب على النبي أنشده\n(يا قوم إني رجل عندي خبر ... لله من آياته هذا القمر)\n(والشمس والشعرى آيات أخر ... من يتسام بالهدى فالخبث شر)\n(إنا أتيناك وقد طال السفر ... نقود خيلا رجعا فيها ضرر)\n(نطعمها اللحم إذا عز الشجر ... )\nال اليزيدي عن ابن حبيب خاصة قال الأصمعي أطعمها اللحم أسقيها اللبن والعرب تقول اللبن أحد اللحمين و قال ابن\nحبيب قال ابن الأعرابي كانت العرب إذا لم تجد العلف دقت اللحم اليابس فأطعمته الخيل","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":1,"spl":"شعره بعد أن خدعته زوجه — نسي امرأته بحب جديد","tags":[],"loc":3736,"partial":1},
{"id":"b288-7","bab":"الجزء 22","sec":"نسي امرأته بحب جديد","page":"ج22 ص280","text":"أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي عن ابن عياش وأخبرنا ابن المرزبان قال أخبرني عيسى بن يونس قال حدثني محمد بن الفضل\nقال حدثنا الهيثم بن عدي عن ابن عباس قال لما فارق النمر بن تولب امرأته الأسدية جزع عليها حتى خيف على عقله ومكث أياما لا يطعم ولا ينام فلما رأت عشيرته منه ذلك أقبلوا عليه يلومونه ويعيرونه و قالوا أن في نساء العرب مندوحة و متسعا وذكروا له امرأة من فخذه الأدنين يقال لها دعد ووصفوها له بالجمال و الصلاح فتزوجها ووقعت من قلبه وشغلته عن ذكر جمرة وفيها يقول\n(أهيم بدعد ما حييت فإن أمت ... أوكل بدعد من يهيم بها بعدي)\nالناس يروون هذا البيت لنصيب وهو خطأ أخبرني اليزيدي عن عبد الرحمن ابن أخي الأصمعي عن عمه وأخبرني إبراهيم بن محمد الصائغ عن ابن قتيبة عن عبد الرحمن عن عمه عن حماد بن ربيعة انه قال أظرف الناس النمر بن تولب حيث يقول\n(أهيم بدعد ما حييت فإن أمت ... أوكل بدعد من يهيم بها بعدي)","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":1,"spl":"شعره بعد أن خدعته زوجه — نسي امرأته بحب جديد","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":3737},
{"id":"b288-8","bab":"الجزء 22","sec":"رثاؤه لزوجه جمرة","page":"ج22 ص281","text":"أخبرني ابن المرزبان قال أخبرني عبد الله بن محمد قال أخبرني محمد بن سلام قال لما بلغ النمر بن تولب أن امرأته جمرة توفيت نعاها له رجل من قومه يقال له حزام أو حرام فقال\n(ألم تر أن جمرة جاء منها ... بيان الحق إن صدق الكلام)\n(نعاها بالندي لنا حزام ... حديث ما تحدث يا حرام)\n(فلا تبعد وقد بعدت وأجرى ... على جدث تضمنها الغمام)\nال الأصمعي يقال بعد وأبعد أخبرني أبو الحسن الأسدي قال حدثنا الرياشي عن الأصمعي عن أبي عمرو وأخبرني به هاشم بن محمد أبو دلف الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة عن أبي عمرو و قال أدرك النمر بن تولب النبي فأسلم وحسن إسلامه وعمر فطال عمره وكان جوادا واسع القرى كثير الأضياف وهابا لماله فلما كبر خرف وأهتر فكان هجيراه اصبحوا الراكب اغبقوا الراكب اقروا انحروا للضيف أعطوا السائل تحملوا لهذا في حمالته كذا و كذا\nلعادته بذلك فلم يزل يهذي بهذا وشبهه مدة خرفه حتى مات قال وخرفت امرأة من حي كرام عظيم خطرهم وخطرها فيهم فكان هجيراها زوجوني قولوا لزوجي يدخل مهدوا لي إلى جانب زوجي فقال عمر بن الخطاب وقد بلغه خبرها ما لهج به أخو عكل النمر بن تولب في خرفه أفخر وأسرى وأجمل مما لهجت به صاحبتكم ثم ترحم عليه","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":2,"spl":"رثاؤه لزوجه جمرة — يتحمل دية عن صديقه","tags":["الجواري والنساء","الموت","الرواية والكتابة"],"loc":3738},
{"id":"b288-9","bab":"الجزء 22","sec":"رثى اخاه الحارث","page":"ج22 ص282","text":"أخبرني ابن المرزبان قال حدثني أبو بكر العامري قال حدثني علي بن المغيرة الأثرم عن أبي عبيدة قال مات الحارث بن تولب فرثاه النمر فقال\n(لا زال صوب من ربيع وصيف ... يجود على حسن الغميم فيثرب)\n(فو الله ما أسقي البلاد لحبها ... و لكنما أسقيك حار بن تولب)\n(تضمنت أدواء العشيرة بينها ... و أنت على أعواد نعش مقلب)\n(كأن امرأ في الناس كنت ابن أمه ... على فلج من بطن دجلة مطنب)\nال حماد الراوية كان النمر بن تولب كثير البيت السائر و البيت المتمثل به فمن ذلك قوله\n(لا تغضبن على امرئ في ماله ... و على كرائم صلب مالك فاغضب)\n(و إذا تصبك خصاصة فارج الغنى ... و إلى الذي يعطي الرغائب فارغب)\nوقوله\n(تلبس لدهرك أثوابه ... فلن يبتني الناس ما هدما)\n(وأحبب حبيبك حبا رويدا ... فليس يعولك أن تصرما)\n(و أبغض بغيضك بغضا رويدا ... إذا أنت حاولت أن تحكما)\nقوله\n(أعاذل إن يصبح صداي بقفرة ... بعيد فأنى ناصري وقريبي)\n(ترى أن ما أبقيت لم أك ربه ... وأن الذي أفنيت كان نصيبي)","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":2,"spl":"رثاؤه لزوجه جمرة — يتحمل دية عن صديقه","tags":["الموت","الرواية والكتابة"],"loc":3739},
{"id":"b288-10","bab":"الجزء 22","sec":"يتحمل دية عن صديقه","page":"ج22 ص282","text":"نسخت من كتاب بخط السكري أبي سعيد قال محمد بن حبيب كان للنمر بن تولب صديق فأتاه النمر في ناس من قومه يسألونه في دية احتملوها فلما رآهم وسألوه تبسم فقال النمر\n(تبسم ضاحكا لما رآني ... وأصحابي لدي عن التمام)\nقال له الرجل إن لي نفسا تأمرني أن أعطيكم ونفسا تأمرني ألا أفعل فقال النمر\n(أما خليلي فإني غير معجله ... حتى يؤامر نفسيه كما زعما)\n(نفس له من نفوس الناس صالحة ... تعطي الجزيل و نفس ترضع الغنما)\nم قال النمر لأصحابه لا تسألوا أحدا فالدية كلها علي","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":2,"spl":"رثاؤه لزوجه جمرة — يتحمل دية عن صديقه","tags":["الخمر","الرواية والكتابة"],"loc":3740},
{"id":"b288-11","bab":"الجزء 22","sec":"خبر السيف الذي علاه الصدأ","page":"ج22 ص283","text":"أخبرني احمد بن عبد العزيز الجوهري قال حدثنا علي بن محمد\nالنوفلي قال حدثنا أبي قال حدثنا الحسن بن محمد بن عبد الله بن حسن بن علي قال جاء أعرابي إلى أبي وهو مستتر بسويقة قبل مخرجه ومعه سيف قد علاه الصدأ فقال يا بن رسول الله إني كنت ببطن قديد أرعى إبلي و فيها فحل قطم قد كنت ضربته فحقد علي و أنا لا ادري فخلا بي فشد علي يريدني و أنا أحضر و دنا مني حتى أن لعابه ليسقط على رأسي لقربه مني فأنا اشتد وأنا أنظر إلى الأرض لعلي أرى شيئا أذبه عني به إذ وقعت عيني على هذا السيف قد فحص عنه السيل فظننته عودا باليا فضربت بيدي إليه فأخذته فإذا سيف فذببت به البعير عني ذبا و الله ما أردت به الذي بلغت منه فأصبت خيشومه فرميت بفقمه فعلمت انه سيف جيد وظننته من سيوف القوم الذين كانوا قتلوا في وقعة قديد و ها هوذا قد أهديته لك يا بن رسول الله\nقال فأخذه مني أبي وسر به و جلس الأعرابي يحادثه فبينا هو كذلك إذا أقبلت غنم لأبي ثلاثمائة شاة فيها رعاؤها فقال له أبي يا أعرابي هذه الغنم و الرعاة لك مكافأة لك عن هذا السيف\nقال ثم أرسل به إلى المدينة أو أرسل إلى قين فأتي به من المدينة فأمر به فحلي فخرج أكرم سيوف الناس فأمر ما تخذ له جفن ودفعه إلى أختي فاطمة بنت محمد فلما كان اليوم الذي قتل\nفيه قاتل بغير ذلك السيف قال وبقي ذلك السيف عند أختي فاطمة بنت محمد فزرتها يوما وهي بينبع في جماعة من أهل بيتي و كانت عند ابن عمها الحسن بن إبراهيم بن عبد الله بن الحسن عليهم أجمعين السلام فخرجت إلينا وكانت برزة تجلس لاهلها كما يجلس الرجال و تحدثهم فجلست تحدثنا و أمرت مولى لها فنحر لنا جزورا ليهيئ لنا طعاما فنظرت إليها و الجزور في النخل باركة و قد بردت وهي تسلخ فقالت أني لا أرى في هذه الجزور مضربا حسنا ثم دعت بالسيف و قالت يا حسن فدتك أختك هذا سيف أبيك فخذه واجمع يديك في قائمة ثم اضرب به أثناءها من خلفها تريد عراقيبها وقد أثبتها للبروك وهي أربعة أعظم\nقال فأخذت السيف ثم مضيت نحوها فضربت عراقيبها فقطعتها و الله أربعتها و سبقني السيف فدخل في الأرض فأشفقت عليه أن ينكسر أن اجتذبته فحفرت عنه حتى استخرجته قال فذكرت حينئذ قول النمر بن تولب\n(أبقى الحوادث و الأيام من نمر ... أسباد سيف كريم أثره بادي)\n(تظل تحفر عنه الأرض مندفعا ... بعد الذراعين و القيدين و الهادي)\nيروى\n(تظل تحفر عنه إن ظفرت به ... )","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":3,"spl":"خبر السيف الذي علاه الصدأ — مختارات من شعره","tags":["المديح","الجواري والنساء"],"loc":3741,"partial":1},
{"id":"b288-12","bab":"الجزء 22","sec":"مختارات من شعره","page":"ج22 ص286","text":"أخبرني علي بن صالح بن الهيثم قال حدثنا عمر بن شبة قال أخبرني أحمد بن معاوية الباهلي عن أبي عبيدة قال قيل للنمر بن تولب كيف أصبحت يا أبا ربيعة فأنشأ يقول\n(أصبحت لا يحمل بعضي بعضا ... أشكو العروق الآبضات أبضا)\n(كما تشكى الأرحبي الغرضا ... كأنما كان شبابي قرضا)\nخبرني هاشم بن محمد أبو دلف الخزاعي قال حدثنا الرياشي عن الأصمعي قال أنشدني حماد بن الأخطل بن النمر بن تولب لجده\n(أعذني رب من حصر وعي ... ومن نفس أعالجها علاجا)\n(ومن حاجات نفس فاعصمني ... فإن لمضمرات النفس حاجا)\n(فأنت وليها وبرئت منها ... إليك فما قضيت فلا خلاجا)\nم قال كان النمر أفتى خلق الله فقلت وما كانت فتوته قال أو ليس فتى من يقول\n(أهيم بدعد ما حييت فإن أمت ... فواحزنا من ذا يهيم بها بعدي)\n\n(أيا صاحبي رحلي دنا الموت فانزلا ... برابية إني مقيم لياليا)\n(وخطا بأطراف الأسنة مضجعي ... وردا على عيني فضل ردائيا)\n(ولا تحسداني بارك الله فيكما ... من الأرض ذات العرض أن توسعا ليا)\n(لعمري لئن غالت خراسان هامتي ... لقد كنت عن بابي خراسان نائيا)\n(فياليت شعري هل أبيتن ليلة ... بجنب الغضا أزجي القلاص النواجيا)\nلشعر لمالك بن الريب و الغناء لمعبد مما لا يشك فيه من غنائه خفيف ثقيل أول بالوسطى في مجراها عن إسحاق و يونس و عمرو و دنانير وفيه خفيف ثقيل آخر لابن عائشة من رواية علي بن يحيى وفيه لابن سريج هزج بالخصر في مجرى البنصر عن ابن المكي وفيه لإبراهيم رمل بالوسطى عن عبد الله بن موسى في الأول و الثالث من الأبيات ولإبراهيم ثقيل أول في الخامس ثم الرابع عن الهشامي و قيل أن الرمل المنسوب إليه لنبيه","topic":"أخبار النمر بن تولب ونسبه","topicNo":288,"sp":3,"spl":"خبر السيف الذي علاه الصدأ — مختارات من شعره","tags":[],"song":1,"loc":3742},
{"id":"b289-2","bab":"الجزء 22","sec":"أخبار مالك بن الريب و نسبه — كان من الشعراء اللصوص","page":"ج22 ص287 – ج22 ص288","text":"هو مالك بن الريب بن حوط بن قرط بن حسل بن ربيعة بن كابية بن حرقوص بن مازن بن مالك بن عمرو بن تميم\nكان شاعرا فاتكا لصا و منشؤه في بادية بني تميم بالبصرة من شعراء الإسلام في أول أيام بني أمية أخبرني بخبره علي بن سليمان الاخفش قال أخبرنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي\nوعن هشام بن الكلبي وعن الفضل بن محمد وإسحاق بن الجصاص و حماد الرواية و كلهم قد حكى من خبره نحوا مما حكاه الآخرون قالوا استعمل معاوية بن أبي سفيان سعيد بن عثمان بن عفان على خراسان فمضى سعيد بجنده في طريق فارس فلقيه بها مالك بن الريب المازني و كان من أجمل الناس وجها و أحسنهم ثيابا فلما رآه سعيد أعجبه و\nقال له مالك و يحك تفسد نفسك بقطع الطريق وما يدعوك إلى ما يبلغني عنك من العبث و الفساد وفيك هذا الفضل قال يدعوني إليه العجز عن المعالي ومساواة ذوي المروءات و مكافأة الإخوان قال فإن أنا أغنيتك\nواستصحبتك أتكف عما كنت تفعل قال أي و الله أيها الأمير أكف كفا لم يكف أحد أحسن منه قال فاستصحبه وأجرى له خمسمائة درهم في كل شهر قالوا وكان السبب الذي من أجله وقع مالك بن الريب إلى ناحية فارس أنه كان يقطع الطريق هو وأصحاب له منهم شظاظ وهو مولى لبني تميم و كان أخبثهم وأبو حردبة أحد بني أثالة بن مازن و غويث أحد بني كعب بن مالك بن حنظلة و فيهم يقول الراجز\n(الله نجاك من القصيم ... وبطن فلج وبني تميم)\n(ومن بني حردبة الأثيم ... ومالك وسيفه المسموم)\n(ومن شظاظ الأحمر الزنيم ... ومن غويث فاتح العكوم)\nساموا الناس شرا و طلبهم مروان بن الحكم وهو عامل على المدينة فهربوا فكتب إلى الحارث بن حاطب الجمحي وهو عامله على بني عمرو بن حنظلة يطلبهم فهربوا منه","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":0,"spl":"أخبار مالك بن الريب و نسبه — كان من الشعراء اللصوص — توعد الحارث بن حاطب","tags":["اللهو والمزاح"],"loc":3743},
{"id":"b289-3","bab":"الجزء 22","sec":"توعد الحارث بن حاطب","page":"ج22 ص289","text":"وبلغ مالك بن الريب أن الحارث بن حاطب يتوعده فقال\n(تألى حلفة في غير جرم ... أميري حارث شبه الصرار)\nعلي لأجلدن في غير جرم ... ولا أدنى فينفعني اعتذاري وقلت وقد ضممت إلي جأشي ... تحلل لا تأل علي حار فإني سوف يكفينيك عزمي ... ونص العيس بالبلد القفار وعنس ذات معجمة أمون ... علنداة موثقة الفقار تزيف إذا تواهقت المطايا ... كما زاف المشرف للخطار وإن ضربت بلحييها و عامت ... تفصم عنهما حلق السفار مراحا غير ما ضغن ولكن ... لجاجا حين تشتبه الصحاري إذا ما استقبلت جونا بهيما ... تفرج عن مخيسة حضار إذا ما حال روض رباب دوني ... وتثليث فشأنك بالبكاري وأنياب سيخلفهن سيفي ... وشدات الكمي على التجار فإن أسطع أرح منه أناسي ... بضربة فاتك غير اعتذار وإن يفلت فإني سوف أبغي ... بنيه بالمدينة أو صرار\n(ألا من مبلغ مروان عني ... فإني ليس دهري بالفرار)\n(ولا جزع من الحدثان يوما ... ولكني أرود لكم و بار)\nبار أرض لم يطأ أحد ثراها\n(بهزمار تراد العيس فيها ... إذا أشفقن من قلق الصفار)\n(وهن يحشن بالأعناق حوشا ... كأن عظامهن قداح بار)\n(كأن الرحل أسأر من قراها ... هلال عشية بعد السرار)\n(رأيت وقد أتى بحران دوني ... لليلى بالغميم ضوء نار)\n(إذا ما قلت قد خمدت زهاها ... عصي الرند والعصف السواري)\n(يشب وقودها ويلوح وهنا ... كما لاح الشبوب من الصوار)\n(كأن النار اذ شبت لليلى ... أضاءت جيد مغزلة نوار)\n(و تصطاد القلوب على مطاها ... بلا جعد القرون ولا قصار)\n(وتبسم عن نقي اللون عذب ... كما شيف الأقاحي بالقطار)\n(أتجزع أن عرفت ببطن قو ... و صحراء الأديهم رسم دار)\n(وإن حل الخليط و لست فيهم ... مرابع بين دحل إلى سرار)\n(إذا حلوا بعائجة خلاء ... يقطف نور حنوتها العذاري)\nبعث إليه الحارث رجلا من الأنصار فأخذه وأخذ أبا جردبة فبعث بأبي حردبة وتخلف الأنصاري مع القوم الذين كان مالك فيهم وأمر غلاما له فجعل يسوق مالكا فتغفل مالك غلام الأنصاري وعليه السيف فانتزعه منه وقتله به وشد على الأنصاري فضربه بالسيف حتى قتله وجعل يقتل من كان معه يمينا وشمالا ثم لحق بأبي حردبة فتخلصه وركبا إبل الأنصاري و خرجا فرارا من ذلك هاربين حتى أتيا البحرين واجتمع إليهما أصحابهما ثم قطعوا إلى فارس فرارا من ذلك الحدث الذي أحدثه مالك فلم يزل بفارس حتى قدم عليه سعيد بن عثمان فاستصحبه","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":0,"spl":"أخبار مالك بن الريب و نسبه — كان من الشعراء اللصوص — توعد الحارث بن حاطب","tags":["السفر والحج"],"loc":3744},
{"id":"b289-4","bab":"الجزء 22","sec":"شعره في مهربه","page":"ج22 ص292","text":"فقال مالك في مهربه ذلك\n(أحقا على السلطان أما الذي له ... فيعطي وأما ما يراد فيمنع)\n(إذا ما جعلت الرمل بيني وبينه ... وأعرض سهب بين يبرين بلقع)\n(من الأدمى لا يستجم بها القطا ... تكل الرياح دونه فتقطع)\n(فشأنكم يا آل مروان فاطلبوا ... سقاطي فما فيه لباغيه مطمع)\n(وما أنا كالغير المقيم لأهله ... على القيد في بحبوحة الضيم يرتع)\n(ولولا رسول الله أن كان منكم ... تبين من بالنصف يرضى ويقنع)\nقال أيضا\n(لو كنتم تنكرون العذر قلت لكم ... يا آل مروان جاري منكم الحكم)\n(وأتقكم يمين الله ضاحية ... عند الشهود وقد توفي به الذمم)\n(لا كنت أحدث سوءا في إمارتكم ... ولا الذي فات مني قبل ينتقم)\n(نحن الذين إذا خفتم مجللة ... قلتم لنا إننا منكم لتعتصموا)\n(حتى إذا انفرجت عنكم دجنتها ... صرتم كجرم فلا إل ولا رحم)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":1,"spl":"شعره في مهربه — قوله في محاولة إغتياله","tags":["الموت"],"loc":3745},
{"id":"b289-5","bab":"الجزء 22","sec":"قوله في محاولة إغتياله","page":"ج22 ص293","text":"وقال مالك حين قتل غلام الأنصاري الذي كان يقوده\n(غلام يقول السيف يثقل عاتقي ... إذا قادني وسط الرجال المجحدل)\n(فلولا ذباب السيف ظل يقودني ... بنسعته شثن البنان حزنبل)\nالوا وبينما مالك بن الريب ذات ليلة في بعض هناته وهو نائم وكان\nلا ينام إلا متوشحا بالسيف إذ هو بشيء قد جثم عليه لا يدري ما هو فانتفض به مالك فسقط عنه ثم انتحى له بالسيف فقده نصفين ثم نظر إليه فإذا هو رجل أسود كان يقطع الطريق في تلك الناحية فقال مالك في ذلك\n(أدلجت في مهمه ما إن أرى أحدا ... حتى إذا حان تعريس لمن نزلا)\n(وضعت جنبي وقلت الله يكلؤني ... مهما تنم عنك من عين فما غفلا)\n(والسيف بيني وبين الثوب مشعره ... أخشى الحوادث إني لم أكن وكلا)\n(ما نمت إلا قليلا نمته شئزا ... حتى وجدت على جثماني الثقلا)\n(داهية من دواهي الليل بيتني ... مجاهدا يبتغي نفسي وما ختلا)\n(أهويت نفحا له والليل ساتره ... إلا توخيته والجرس فانخزلا)\n(لما ثنى الله عني شر عدوته ... رقدت لا مثبتا ذعرا ولا بعلا)\n(أما ترى الدار قفرا لا أنيس بها ... إلا الوحوش وأمسى أهلها احتملا)\n(بين المنيفة حيث استن مدفعها ... وبين فردة من وحشيها قبلا)\n(وقد تقول وما تخفي لجارتها ... إني أرى مالك بن الريب قد نحلا)\n(من يشهد الحرب يصلاها ويسعرها ... تراه مما كسته شاحبا وجلا)\n(خذها فإني لضراب إذا اختلفت ... أيدي الرجال بضرب يختل البطلا)\nقال مالك في ذلك أيضا\n(يا عاملا تحت الظلام مطية ... متخايلا لا بل وغير مخاتل)\n(أني أنخت لشابك أنيابه ... مستأنس بدجى الظلام منازل)\n(لا يستريع عظيمة يرمى بها ... حصبا يحفز عن عظام الكاهل)\n(حربا تنصبه بنبت هواجر ... عاري الأشاجع كالحسام الناصل)\n(لم يدر ما غرف القصور وفيؤها ... طاو بنخل سوادها المتمايل)\n(يقظ الفؤاد إذا القلوب تآنست ... جزعا ونبه كل أروع باسل)\n(حيث الدجى متطلعا لغفوله ... كالذئب في غلس الظلام الخاتل)\n(فوجدته ثبت الجنان مشيعا ... ركاب منسج كل أمر هائل)\n(فقراك أبيض كالعقيقة صارما ... ذا رونق يعني الضريبة فاصل)\n(فركبت ردعك بين ثني فائز ... يعلو به أثر الدماء وشائل)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":1,"spl":"شعره في مهربه — قوله في محاولة إغتياله","tags":["الوصف والطبيعة"],"loc":3746},
{"id":"b289-6","bab":"الجزء 22","sec":"عرض عليه أن يكون سائس إبل فرفض","page":"ج22 ص295","text":"قال وانطلق مالك بن الريب مع سعيد بن عثمان إلى خراسان حتى\nإذا كانوا في بعض مسيرهم احتاجوا إلى لبن فطلبوا صاحب إبلهم فلم يجدوه فقال مالك لغلام من غلمان سعيد أدن مني فلانة لناقة كانت لسعيد عزيزة فأدناها منه فمسحها وأبس بها حتى درت ثم حلبها فإذا أحسن حلب حلبه الناس وأغزره درة فانطلق الغلام إلى سعيد فأخبره فقال سعيد لمالك هل لك أن تقوم بأمر إبلي فتكون فيها وأجزل لك الرزق إلى ما أرزقك وأضع عنك الغزو فقال مالك في ذلك\n(أني لأستحيي الفوارس أن أرى ... بأرض العدا بو المخاض الروائم)\n(وإني لأستحيي إذا الحرب شمرت ... أن ارخي دون الحرب ثوب المسالم)\n(وما أنا بالنائي الحفيظة في الوغى ... ولا المتقي في السلم جر الجرائم)\n(ولا المتأبي في العواقب للذي ... أهم به من فاتكات العزائم)\n(ولكنني مستوحد العزم مقدم ... على غمرات الحادث المتفاقم)\n(قليل اختلاف الرأي في الحر باسل ... جميع الفؤاد عند حل العظائم)\nفلما سمع ذلك منه سعيد بن عثمان علم أنه ليس بصاحب إبل وأنه صاحب حرب فانطلق به معه قالوا وبينما مالك بن الريب ليلة نائم في بعض مفازاته إذ بيته ذئب فزجره فلم يزدجر فأعاد فلم يبرح فوثب إليه بالسيف فضربه فقتله وقال مالك في ذلك\n(أذئب الغضا قد صرت للناس ضحكة ... تغادي بك الركبان شرقا إلى غرب)\n(فأنت وإن كنت الجريء جنانه ... منيت بضرغام من الأسد الغلب)\n(بمن لا ينام الليل إلا وسيفه ... رهينة أقوام سراع إلى الشغب)\n(ألم ترني يا ذئب إذ جئت طارقا ... تخاتلني أني أمرؤ وافر اللب)\n(زجرتك مرات فلما غلبتني ... ولم تنزجر نهنهت غربك بالضرب)\n(فصرت لقى لما علاك ابن حرة ... بأبيض قطاع ينجي من الكرب)\n(ألا رب يوم ريب لو كنت شاهدا ... لهالك ذكري عند معمعمة الحرب)\n(ولست ترى إلا كميا مجدلا ... يداه جميعا تثبتان من الترب)\n(وآخر يهوي طائر القلب هاربا ... وكنت أمرأ في الهيج مجتمع القلب)\n(أصول بذي الزرين أمشي عرضنة ... إلى الموت والأقران كالإبل الجرب)\n(أرى الموت لا أنحاش عنه تكرما ... ولو شئت لم أركب على المركب الصعب)\n(ولكن أبت نفسي وكانت أبية ... تقاعس أو ينصاع قوم من الرعب)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":2,"spl":"عرض عليه أن يكون سائس إبل فرفض — شعره حين فارق ابنته","tags":["اللهو والمزاح","الوصف والطبيعة"],"loc":3747},
{"id":"b289-7","bab":"الجزء 22","sec":"شعره حين فارق ابنته","page":"ج22 ص297","text":"قال أبو عبيدة لما خرج مالك بن الريب مع سعيد بن عثمان تعلقت ابنته بثوبه وبكت وقالت له أخشى أن يطول سفرك أو يحول الموت بيننا فلا نلتقي فبكى وأنشأ يقول\n(ولقد قلت لابنتي وهي تبكي ... بدخيل الهموم قلبا كئيبا)\nوهي تذري من الدموع على الخدين ... من لوعة الفراق غروبا عبرات يكدن يجرحن ما جزن ... به أو يدعن فيه ندوبا حذر الحتف أن يصيب أباها ... ويلاقي في غير أهل شعوبا اسكتي قد حززت بالدمع قلبي ... طالما حز دمعكن القلوبا فعسى الله أن يدفع عني ... ريب ما تحذرين حتى أؤوبا ليس شيء يشاؤه ذو المعالي ... بعزيز عليه فادعي المجيبا ودعي أن تقطعي الأن قلبي ... أو تريني في رحلتي تعذيبا أنا في قبضة الإله إذا كن ... ت بعيدا أو كنت منك قريبا كم رأينا امرأ أتى من بعيد ... ومقيما على الفراش أصيبا فدعيني من انتحابك إني ... لا أبالي إذا اعتزمت النحيبا حسبي الله ثم قربت للسير ... علاة أنجب بها مركوبا\nخبرني هاشم بن محمد الخزاعي قال حدثنا دماذ عن أبي عبيدة قال كان سبب خروج مالك بن الريب إلى خراسان واكتتابه مع سعيد بن عثمان هربا من ضرطة فسألته كيف كان ذلك قال مر مالك بليلى الاخيلية فجلس إليها يحادثها طويلا وأنشدها فأقبلت عليه وأعجبت به حتى طمع في وصلها ثم إذا هو بفتى قد جاء إليها كأنه نصل\nسيف فجلس إليها فأعرضت عن مالك وتهاونت به حتى كأنه عندها عصفور وأقبلت على صاحبها مليا من نهارها فغاظه ذلك من فعلها وأقبل على الرجل فقال من أنت فقال توبة بن الحمير فقال هل لك في المصارعة\nقال وما دعاك إلى ذلك وأنت ضيفنا وجارنا قال لا بد منه فظن أن ذلك لخوفه منه فازداد لجاجا فقام توبة فصارعه فلما سقط مالك إلى الأرض ضرط ضرطة هائلة فضحكت ليلى منه واستحيا مالك فاكتتب بخراسان وقال لا أقيم في بلد العرب أبدا وقد تحدثت عني بهذا الحديث فلم يزل بخراسان حتى مات فقبره هناك معروف","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":2,"spl":"عرض عليه أن يكون سائس إبل فرفض — شعره حين فارق ابنته","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"loc":3748},
{"id":"b289-8","bab":"الجزء 22","sec":"يتذاكر واصحابه ماضيهم في السرقة","page":"ج22 ص299","text":"وقال المدائني وحدثني أبو الهيثم قال اجتمع مالك بن الريب وأبو حردبة وشظاظ يوما فقالوا تعالوا نتحدث بأعجب ما عملناه في سرقتنا فقال أبو حردبة أعجب ما صنعت وأعجب ما سرقت أني صحبت رفقة فيها رجل على رحل فأعجبني فقلت لصاحبي والله لأسرقن رحله ثم لا رضيت أو آخذ عليه جعالة فرمقته حتى رأيته قد خفق برأسه فأخذت بخطام جمله فقدته وعدلت به عن الطريق حتى إذا صيرته في مكان لا يغاث فيه إن استغاث أنخت البعير وصرعته فأوثقت يده ورجله وقدت الجمل فغيبته ثم رجعت إلى الرفقة وقد فقدوا صاحبهم فهم يسترجعون فقلت ما\nلكم فقالوا صاحب لنا فقدناه فقلت أنا أعلم الناس بأثره فجعلوا لي جعالة فخرجت بهم أتبع الأثر حتى وقفوا عليه فقالوا مالك قال لا أدري نعست فانتبهت لخمسين فارسا قد أخذوني فقاتلتهم فغلبوني\nقال أبو حردبة فجعلت أضحك من كذبه وأعطوني جعالتي وذهبوا بصاحبهم وأعجب ما سرقت انه مر بي رجل معه ناقة و جمل وهو على الناقة فقلت لأخذنهما جميعا فجعلت أعارضه وقد رأيته قد خفق برأسه فدرت فأخذت الجمل فحللته وسقته فغيبته في القصيم وهو الموضع الذي كانوا يسرقون فيه ثم انتبه فالتفت فلم ير جمله فنزل وعقل راحلته ومضى في طلب الجمل ودرت فحللت عقال ناقته و سقتها فقالوا لأبي حردبة و يحك فحتام تكون هكذا\nقال اسكتوا فكأنكم بي وقد تبت واشتريت فرسا وخرجت مجاهدا فبينا أنا واقف إذ جاءني سهم كأنه قطعة رشاء فوقع في نحري فمت شهيدا قال فكان كذلك تاب وقدم البصرة فاشترى فرسا وغزا الروم فأصابه سهم في نحره فاستشهد ثم قالوا لشظاظ أخبرنا أنت أعجب ما أخذت في لصوصيتك ورأيت فيها فقال نعم كان فلان رجل من أهل البصرة له بنت عم ذات مال كثير وهو وليها و كانت له نسوة فأبت أن تتزوجه فحلف ألا يزوجها من أحد ضرارا لها و كان يخطبها رجل غني من أهل البصرة فحرصت عليه وأبى الآخر أن يزوجها منه ثم إن ولي الأمر حج حتى إذا كان\nبالدو على مرحلة من البصرة حذاءها قريب منه جبل يقال له سنام وهو منزل الرفاق إذا صدرت أو وردت مات الولي فدفن برابية وشيد على قبره فتزوجت الرجل الذي كان يخطبها\nقال شظاظ و خرجت رفقة من البصرة معهم بز و متاع فتبصرتهم وما معهم وأتبعتهم حتى نزلوا فلما ناموا بيتهم وأخذت من متاعهم ثم إن القوم أخذوني وضربوني ضربا شديدا وجردوني\nقال وذلك في ليلة قرة و سلبوني كل قليل وكثير فتركوني عريانا وتماوت لهم وارتحل القوم فقلت كيف أصنع ثم ذكرت قبر الرجل فأتيته فنزعت لوحه ثم احتفرت فيه سربا فدخلت فيه ثم سددت علي باللوح و\nقلت لعلي الآن أدفأ فأتبعهم قال ومر الرجل الذي تزوج بالمرأة في الرفقة فمر بالقبر الذي أنا فيه فوقف عليه و قال لرفيقه و الله لأنزلن إلى قبر فلان حتى أنظر هل يحمي الآن بضع فلانة\nقال شظاظ فعرفت صوته فقلعت اللوح ثم خرجت عليه بالسيف من القبر بلى ورب الكعبة لأحمينها فوقع والله على وجهه مغشيا عليه لا يتحرك و لا يعقل فسقط من يده خطام الراحلة فأخذت وعهد الله بخطامها فجلست عليها و عليها كل أداة وثياب ونقد كان معه ثم وجهتها قصد مطلع الشمس هاربا من الناس فنجوت بها فكنت بعد ذلك أسمعه يحدث الناس بالبصرة ويحلف لهم أن الميت الذي كان منعه من تزويج المرأة خرج عليه من قبره بسلبه و كفنه فبقي يومه ثم هرب منه والناس يعجبون منه فعاقلهم يكذبه و الأحمق\nمنهم يصدقه وأنا اعرف القصة فأضحك منهم كالمتعجب قالوا فزدنا قال فأنا أزيدكم أعجب من هذا وأحمق من هذا إني لأمشي في الطريق أبتغي شيئا أسرقه\nقال فلا و الله ما وجدت شيئا قال و كان هناك شجرة ينام من تحتها الركبان بمكان ليس فيه ظل غيرها وإذا أنا برجل يسير على حمار له فقلت أتسمع\nقال نعم قلت أن المقيل الذي تريد أن تقيله يخسف بالدواب فيه فاحذره فلم يلتفت إلى قولي قال ورمقته حتى إذا نام أقبلت على حماره فاستقته حتى إذا برزت به قطعت طرف ذنبه وأذنيه وأخذت الحمار فخبأته وأبصرته حين استيقظ من نومه فقام يطلب الحمار ويقفو أثره فبينا هو كذلك إذ نظر إلى طرف ذنبه و أذنيه فقال لعمري لقد حذرت لو نفعني الحذر واستمر هاربا خوف أن يخسف به فأخذت جميع ما بقي من رحله فحملته على الحمار واستمر فألحق بأهلي","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":3,"spl":"يتذاكر واصحابه ماضيهم في السرقة","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"loc":3749},
{"id":"b289-10","bab":"الجزء 22","sec":"يتذاكر واصحابه ماضيهم في السرقة — موته","page":"ج22 ص299 – ج22 ص302","text":"قال أبو الهيثم ثم صلب الحجاج رجلا من الشراة بالبصرة وراح عشيا لينظر إليه فإذا برجل بإزائه مقبل بوجهه عليه فدنا منه فسمعه يقول للمصلوب طال ما ركبت فأعقب فقال الحجاج من هذا قالوا هذا شظاظ اللص قال لا جرم والله ليعقبنك ثم وقف أمر بالمصلوب فأنزل وصلب شظاظ مكانه\nقال ابن الأعرابي مرض مالك بن الريب عند قفول سعيد بن عثمان من خراسان في\nطريقه فلما أشرف على الموت تخلف معه مرة الكاتب و رجل آخر من قومه من بني تميم وهما اللذان يقول فيهما\n(أيا صاحبي رحلي دنا الموت فانزلا ... برابية إني مقيم لياليا)\nمات في منزله ذلك فدفناه وقبره هناك معروف إلى الآن و قال قبل موته قصيدته هذه يرثي بها نفسه قال أبو عبيدة الذي قاله ثلاثة عشر بيتا و الباقي منحول ولده الناس عليه\n(فما بيضة بات الظليم يحفها ... ويرفع عنها حؤجؤا متجافيا)\n(بأحسن منها يوم قالت أظاعن ... مع الركل أم ثاو ولدينا لياليا)\n(وهبت شمال آخر الليل قرة ... ولا ثوب إلا بردها وردائيا)\n(وما زال بردى طيبا من ثيابها ... إلى الحول حتى أنهج الثوب باليا)\nلشعر لعبد بني الحسحاس و الغناء لابن سريج في الأول و الثاني من الأبيات ثاني ثقيل بالسبابة في مجرى الوسطى عن إسحاق وفي الثالث و الرابع لمخارق خفيف ثقيل عمله على صنعة إسحاق في\n(أماوي إن المال غاد ورائح ... )\nكاده بذلك ليقال أن لحنه أخذه منه وألقاه على عجوز عمير فألقته\nعلى الناس حتى بلغ الرشيد خبره ثم كشفه فعلم حقيقته ومن لا يعلم ينسبه إلى غيره وقد ذكر حبش انه لإبراهيم وذكر غيره أنه لابن المكي وقد شرحت هذا الخبر في أخبار إسحاق","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":4,"spl":"يتذاكر واصحابه ماضيهم في السرقة — موته — عمر بن الخطاب يستجيد بيتا له","tags":[],"song":1,"loc":3750,"partialRef":{"sid":"b7-27","gi":7,"vi":0,"side":0},"partial":1},
{"id":"b289-12","bab":"الجزء 22","sec":"أخبار عبد بني الحسحاس — تمثل الرسول ببيت له","page":"ج22 ص304 – ج22 ص305","text":"اسمه سحيم وكان عبدا أسود نوبيا أعجيما مطبوعا في الشعر فاشتراه بنو الحسحاس وهم بطن من بني أسد قال أبو عبيدة الحسحاس بن نفاثة بن سعيد بن عمرو بن مالك بن ثعلبة بن دودان بن أسد بن خزيمة قال أبو عبيدة فيما أخبرنا هاشم بن محمد الخزاعي عن أبي حاتم عنه كان عبد بني الحسحاس عبدا أسود أعجميا فكان إذا أنشد الشعر استحسنه أم استحسنه غيره منه يقول أهشنت والله يريد أحسنت والله وأدرك النبي ويقال إنه تمثل بكلمات من شعره غير موزونة\nأخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن منصور قال حدثنا الحسن بن موسى قال حدثنا حماد بن سلمة عن علي بن زيد عن الحسن أن النبي تمثل\n(كفى بالإسلام والشيب ناهيا ... )\nقال أبو بكر يا رسول الله\n(كفى الشيب و الإسلام للمرء ناهيا ... )\nفجعل لا يطيقه فقال أبو بكر أشهد انك رسول الله ( وما علمناه الشعر وما ينبغي له\nال محمد بن خلف وحدثني احمد بن شداد عن أبي سلمة التبوذكي عن حماد بن سلمة عن رجل عن الحسن مثله وروى عن أبي بكر الهذلي أن اسم عبد بني الحسحاس حية وأخبرنا أبو خليفة عن محمد بن سلام قال كان عبد بني الحسحاس حلو الشعر رقيق الحواشي وفي سواده يقول\n(وما ضر أثوابي سوادي وإنني ... لكالمسك لا يسلو عن المسك ذائقه)\n(كسيت قميصا ذا سواد وتحته ... قميص من القوهي بيض بنائقه)\nيروى وتحته قميص من الإحسان أخبرني الحسن بن علي قال حدثنا أحمد بن أبي خيثمة قال أنشدني مصعب بن عبد الله الزبيري لعبد بني الحسحاس و كان يستحسن هذا الشعر ويعجب به قال\n(أشعار عبد بني الحسحاس قمن له ... عند الفخار مقام الأصل والورق)\n(إن كنت عبدا فنفسي حرة كرما ... أو أسود اللون إني أبيض الخلق)\nقال الأثرم حدثني السري بن صالح بن أبي مسهر قال أخبرني بعض الأعراب أن أول ما تكلم به عبد بني الحسحاس من الشعر أنهم أرسلوه رائدا فجاء وهو يقول\n(أنعت غيثا حسنا نباته ... كالحبشي حوله بناته)\nقالوا شاعر و الله ثم انطلق بالشعر بعد ذلك","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":4,"spl":"يتذاكر واصحابه ماضيهم في السرقة — موته — عمر بن الخطاب يستجيد بيتا له","tags":["الحب والغزل","اللهو والمزاح"],"loc":3751,"partial":1},
{"id":"b289-13","bab":"الجزء 22","sec":"عمر بن الخطاب يستجيد بيتا له","page":"ج22 ص306","text":"أخبرنا أبو خليفة عن محمد بن سلام قال أنشد سحيم عمر بن الخطاب قوله\n(عميرة ودع إن تجهزت غاديا ... كفى الشيب والإسلام للمرء ناهيا)\nقال عمر لو قلت شعرك كله مثل هذا لأعطيتك عليه","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":4,"spl":"يتذاكر واصحابه ماضيهم في السرقة — موته — عمر بن الخطاب يستجيد بيتا له","tags":["الرواية والكتابة"],"loc":3752},
{"id":"b289-14","bab":"الجزء 22","sec":"عثمان بن عفان يقول لا حاجة لي إليه","page":"ج22 ص307","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز قال حدثني خالي يوسف بن الماجشون قال كان عبد الله بن أبي ربيعة عاملا لعثمان بن عفان على الجند فكتب إلى عثمان إني قد اشريت غلاما حبشيا يقول الشعر فكتب إليه عثمان لا حاجة لي إليه فاردده فإنما حظ أهل العبد الشاعر منه إن شبع أن يتشبب بنسائهم وإن جاع أن يهجوهم فرده فاشتراه أحد بني الحسحاس\nوروى إبراهيم بن المنذر الحزامي هذا الخبر عن ابن الماجشون قال كان عبد الله بن أبي ربيعة مثل ما رواه الزبير إلا أنه قال فيه إن جاع هر و إن شبع فر\nأخبرني محمد بن خلف بن المرزبان حدثني أبو بكر العامري عن الأثرم عن أبي عبيدة وأخبرنا به أبو خليفة عن محمد بن سلام قال أنشد عبد بني الحسحاس عمر قوله\n(توسدني كفا وتثني بمعصم ... علي وتحوي رجلها من ورائيا)\nقال عمر ويلك إنك مقتول أخبرني محمد بن جعفر الصيدلاني قال حدثني أحمد بن القاسم قال حدثني إسحاق بن محمد النخعي عن ابن أبي عائشة قال أنشد عبد بني الحسحاس عمر قوله ( كفى الشيب و الإسلام للمرء ناهيا ...\nقال له عمر لو قدمت الإسلام على الشيب لأجزتك أخبرني أحمد بن عبد العزيز وحبيب بن نصر قالا حدثنا عمر بن شبة قال حدثنا معاذ بن معاذ وأبو عاصم عن ابن عون عن محمد بن سيف أن عبد بني الحسحاس أنشد عمر هذا وذكر الحديث مثل الذي قبله أخبرني محمد بن خلف قال حدثنا إسحاق بن محمد قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال كان عبد بني الحسحاس قبيح الوجه وفي قبحه يقول\n(أتيت نساء الحارثيين غدوة ... بوجه يراه الله غير جميل)\n(فشبهنني كلبا ولست بفوقه ... ولا دونه إن كان غير قليل)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":5,"spl":"عثمان بن عفان يقول لا حاجة لي إليه — شبب بنساء مواليه","tags":["اللهو والمزاح","الرواية والكتابة"],"loc":3753},
{"id":"b289-15","bab":"الجزء 22","sec":"شبب بنساء مواليه","page":"ج22 ص308","text":"أخبرني أبو خليفة عن محمد بن سلام قال أتي عثمان بن عفان بعبد بني الحسحاس ليشتريه فأعجب به فقالوا انه شاعر وأرادوا أن يرغبوه فيه فقال لا حاجة لي به إذ الشاعر لا\nحريم له إن شبع تشبب بنساء أهله وان جاع هجاهم فاشتراه غيره فلما رحل قال في طريقه\n(اشوقا ولما تمض لي غير ليلة ... فكيف إذا سار المطي بنا شهرا)\n(وما كنت أخشى مالكا أن يبيعني ... بشيء ولو أحست أنامله صفرا)\n(أخوكم و مولى مالكم وحليفكم ... ومن قد ثوى فيكم وعاشركم دهرا)\nلما بلغهم شعره هذا رثوا له فاستردوه فكان يشبب بنسائهم حتى قال\n(ولقد تحدر من كريمة بعضكم ... عرق على متن الفراش و طيب)\nال فقتلوه أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز عن خاله يوسف بن الماجشون بمثل هذه الرواية وزاد فيها فلما استردوه نشب يقول الشعر في نسائهم فأخبرني من رآه واضعا إحدى رجليه على الأخرى يقرض الشعر ويشبب بأخت مولاه وكانت عليلة يقول\n(ماذا يريد السقام من قمر ... كل جمال لوجهه تبع)\n(ما يرتجي خاب من محاسنها ... آما له في القباح متسع)\n(غير من لونها و صفرها ... فزيد فيه الجمال والبدع)\n(لو كان يبغي الفداء قلت له ... ها أنا دون الحبيب يا وجع)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":5,"spl":"عثمان بن عفان يقول لا حاجة لي إليه — شبب بنساء مواليه","tags":["الحب والغزل"],"loc":3754},
{"id":"b289-16","bab":"الجزء 22","sec":"مجلس له مع نسوة من بني صبير بن يربوع","page":"ج22 ص310","text":"أ خبرني محمد بن خلف قال حدثنا أبو بكر العامري عن علي بن المغيرة الأثرم قال قال أبو عبيدة الذي تناهى إلينا من حديث سحيم عبد بني الحسحاس انه جالس نسوة من بني صبير بن يربوع و كان من شأنهم إذا جلسوا للتغزل أن يتعابثوا بشق الثياب وشدة المغالبة على ابداء المحاسن فقال سحيم\n(كأن الصبيريات يوم لقيننا ... ظباء حنت أعناقها في المكانس)\n(فكم قد شققنا من رداء منير ... ومن برقع عن طفلة غير ناعس)\n(إذا شق برد شق بالبرد برقع ... على ذاك حتى كلنا غير لابس)\nفيقال إنه لما قال هذا الشعر اتهمه مولاه فجلس له في مكان كان إذا رعى نام فيه فلما اضطجع تنفس الصعداء ثم قال\n(يا ذكرة مالك في الحاضر ... تذكرها وأنت في الصادر)\n(من كل بيضاء لها كفل ... مثل سنام البكرة المائر)\nال فظهر سيده من الموضع الذي كان فيه كامنا و قال له مالك فلجلج في منطقه فاستراب به فأجمع على قتله فلما ورد الماء خرجت إليه صاحبته فحادثته وأخبرته بما يراد به فقام ينفض ثوبه\nويعفي أثره و يلقط رضا من مسكها كان كسرها في لعبه معها وأنشأ يقول\n(أتكتم حييتم على النأي تكتما ... تحية من أمسى بحبك مغرما)\n(وما تكتمين إن أتيت دنية ... ولا إن ركبنا يا بنة القوم محرما)\n(ومثلك قد أبرزت من خدر أمها ... إلى مجلس تجر بردا مسهما)\nلغناء للغريض ثقيل أول بالوسطى وفيه ليحيى المكي ثاني ثقيل قال\n(وماشية مشي القطاة أتبعتها ... من الستر تخشى أهلها أن تكلما)\n(فقالت صه يا ويح غيرك إنني ... سمعت حديثا بينهم يقطر الدما)\n(فنفضت ثوبيها ونظرت حولها ... ولم أخش هذا الليل أن يتصرما)\n(أعفي بآثار الثياب مبيتها ... وألقط رضا من وقوف تحطما)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":6,"spl":"مجلس له مع نسوة من بني صبير بن يربوع — أحرق في أخدود","tags":["الجواري والنساء"],"song":1,"loc":3755},
{"id":"b289-17","bab":"الجزء 22","sec":"أحرق في أخدود","page":"ج22 ص312","text":"قال وغدوا به ليقتلوه فلما رأته امرأة كانت بينها وبينه مودة ثم فسدت ضحكت به شماتة فنظر إليها و قال\n(فإن تضحكي مني فيا رب ليلة ... تركتك فيها كالبقاء المفرج)\nلما قدم ليقتل قال\n(شدوا وثاق العبد لا يفلتكم ... إن الحياة من الممات قريب)\n(فلقد تحدر من جبين فتاتكم ... عرق على متن الفراش و طيب)\nال وقدم فقتل و ذكر ابن دأب أنه حفر له أخدود وألقي فيه وألقي عليه الحطب فأحرق أخبرني محمد بن مزيد بن أبي الأزهر قال حدثنا حماد بن إسحاق عن أبيه عن المدائني عن أبي بكر الهذلي\nقال كان عبد بني الحسحاس يسمى حية وكان لسيده بنت بكر فأعجبها فأمرته أن يتمارض ففعل وعصب رأسه فقالت للشيخ أسرح أيها الرجل إبلك ولا تكلها إلى العبد فكان فيها أياما ثم\nقال له كيف تجدك قال صالحا قال فرح في إبلك العشية فراح فيها فقالت الجارية لأبيها ما أحسبك إلا قد ضيعت إبلك العشية أن وكلتها إلى حية فخرج في آثار إبله فوجده مستلقيا في ظل شجرة وهو يقول\n(يارب شجو لك في الحاضر ... تذكرها وأنت في الصادر)\n(من كل حمراء جمالية ... طيبة القادم و الآخر)\nفقال الشيخ أن لهذا لشأنا وانصرف ولم يره وجهه وأتى أهل الماء و قال لهم تعلموا و الله أن هذا العبد قد فضحنا وأخبرهم الخبر وأنشدهم ما\nقال فقالوا اقتله فنحن طوعك فلما جاءهم وثبوا عليه فقالوا له قلت و فعلت فقال دعوني إلى غد حتى أعذرها عند أهل الماء فقالوا إن هذا صواب فتركوه فلما كان الغد اجتمعوا فنادى يا أهل الماء ما فيكم امرأة إلا قد أصبتها إلا فلانة فإني على موعد منها فأخذوه فقتلوه ومما يغنى فيه من قصيدة سحيم عبد بني الحسحاس و قال أن من الناس من يرويها لغيره\n(تجمعن من شتى ثلاثا وأربعا ... وواحدة حتى كملن ثمانيا)\n(وأقبلن من أقصى الخيام يعلنني ... بقبة ما أبقين نصلا يمانيا)\n(يعدن مريضا هن قد هجن داءه ... ألا إنما بعض العوائد دائيا)\nيه لحنان كلاهما من الثقيل الأول و الذي ابتداؤه تجمعن من شتى ثلاث لبنان و الذي أوله وأقبلن من أقصى الخيام ذكر الهشامي أنه لإسحاق وليس يشبه صنعته ولا أدري لمن هو","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":6,"spl":"مجلس له مع نسوة من بني صبير بن يربوع — أحرق في أخدود","tags":["الحب والغزل"],"loc":3756},
{"id":"b289-18","bab":"الجزء 22","sec":"مخارق يكيد لإسحاق","page":"ج22 ص313","text":"أخبرني جحظة عن ابن حمدون أن مخارقا عمل لحنا في هذا الشعر\n(وهبت شمالا آخر الليل قرة ... ولا ثوب إلا بردها وردائيا)\nعلى عمل صنعة إسحاق في ( أماوي أن المال غاد ورائح ...\nيكيد به إسحاق وألقاه على عجوز عمير الباذ عيسى و قال لها إذا سئلت عنه فقولي أخذته من عجوز مدنية ودار الصوت حتى غني به الخليفة فقال لإسحاق ويلك أخذت لحن هذا الصوت تغنيه كله فحلف له بكل يمين يرضاه أنه لم يفعل وتضمن له كشف القصة ثم أقبل على من غناهم الصوت فقال عمن أخذته فقال عن فلان فلقيه فسأله عمن أخذه فعرفه ولم يزل يكشف عن القصة حتى انتهت من كل وجه إلى عجوز عمير فسئلت عن ذلك فقالت أخذته عن عجوز مدنيه فدخل إسحاق على عمير فحلف له بالطلاق و العتاق وكل محرج من الأيمان ألا يكلمه أبدا و لا يدخل داره ولا يترك كيده وعداوته أو يصدقه عن حال هذا الصوت وقصته فصدقه عمير عن القصة فحدث بها الواثق بحضرة عمير ومخارق فلم يمكن مخارقا دفع ذلك و خجل خجلا بان فيه وبطل ما أراده بإسحاق\n(ثلاثة أبيات فبيت أحبه ... وبيتان ليسا من هواي ولا شكلي)\n(ألا أيها البيت الذي حيل دونه ... بنا أنت من بيت وأهلك من أهل)\nلشعر لجميل و الغناء لإسحاق ماخوري بالبنصر من جامع أغانيه وفيه رمل مجهول ذكره حبش لعلويه ولم أجد طريقته","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":7,"spl":"مخارق يكيد لإسحاق — متمم العبدي و الجويرية اعجب بفصاحة لسان الجويرية ورقة ألفاظها","tags":[],"song":1,"loc":3757},
{"id":"b289-19","bab":"الجزء 22","sec":"متمم العبدي و الجويرية اعجب بفصاحة لسان الجويرية ورقة ألفاظها","page":"ج22 ص315","text":"أخبرني الحسين بن يحيى المرادي عن حماد بن إسحاق عن أبيه قال حدثني متمم العبدي قال خرجت من مكة زائرا لقبر النبي فإني لبسوق الجحفة إذا جويرية تسوق بعيرا وتترنم بصوت مليح طيب حلو في هذا الشعر\n(ألا أيها البيت الذي حيل دونه ... بنا أنت من بيت وأهلك من أهل)\n(بنا أنت من بيت وحولك لذة ... وظلك لو يسطاع بالبارد السهل)\n(ثلاثة أبيات فبيت أحبه ... وبيتان ليسا من هواي ولا شكلي)\nقلت لمن هذا الشعر يا جويرية قالت أما ترى تلك الكوة الموقاة بالكلة الحمراء قلت أراها قالت من هناك نهض هذا الشعر قلت أو قائله في الأحياء قالت هيهات لو أن لميت أن يرجع لطول غيبته لكان ذلك فأعجبني فصاحة لسانها ورقة ألفاظها فقلت لها ألك أبوان فقالت فقدت خيرهما وأجلهما ولي أم قلت وأين أمك قالت منك بمرأى ومسمع قال فإذا امرأة تبيع الخرز على ظهر الطريق\nبالجحفة فأتيتها فقلت يا أمتاه استمعي مني فقالت لها يا أمه فاستمعي من عمي ما يلقيه إليك فقالت حياك الله هيه هل من جائية خبر قلت أهذه ابنتك قالت كذا كان يقول أبوها\nقلت أفتزوجينها قالت ألعلة رغبت فيها فما هي و الله من عندها جمال ولا لها مال قلت لحلاوة لسانها و حسن عقلها فقالت أينا أملك بها أنا أم هي بنفسها\nقلت بل هي بنفسها قالت فإياها فخاطب فقلت لعلها أن تستحي من الجواب في مثل هذا فقالت ما ذاك عندها أنا أخبر بها فقلت يا جارية أما تستمعين ما تقول أمك\nقال قد سمعت قلت فما عندك قالت أو ليس حسبك أن قلت إني أستحي من الجواب في مثل هذا فإن كنت أستحي في شيء فلم أفعله أتريد أن تكون الأعلى وأكون بساطك لا والله لا يشد علي رجل حواءه وأنا أجد مذقة لبن أو بقلة ألين بها معاي\nقال فورد والله علي أعجب كلام على وجه الأرض فقلت أو أتزوجك و الإذن فيه إليك وأعطي الله عهدا أني لا أقربك أبدا إلا عن إرادتك قالت إذا و الله لا تكون لي في هذا إرادة أبدا ولا بعد الأبد إن كان بعده بعد فقلت فقد رضيت بذلك فتزوجتها وحملتها وأمها معي إلى العراق وأقامت معي نحوا من ثلاثين سنة ما ضممت عليها حواي قط و كانت قد علقت من أغاني المدينة أصواتا كثيرة فكانت ربما ترنمت بها فأشتهيها فقلت دعيني من أغانيك هذه فإنها تبعثني على الدنو منك قال فما سمعتها رافعة صوتها بغناء بعد ذلك حتى فارقت الدنيا وإن أمها عندي حتى الساعة فقلت ما ادري متى دار في سمعي حديث امرأة أعجب من حديث هذه\n\n(أيها الناس إن رأيي يريني ... وهو الرأي طوفة في البلاد)\n(بالعوالي وبالقنابل تردي ... بالبطاريق مشية العواد)\n(وبجيش عرمرم عربي ... جحفل يستجيب صوت المنادي)\n(من تميم وخندف وإياد ... و البهاليل حمير ومراد)\n(فإذا سرت سارت الناس خلفي ... ومعي كالجبال في كل واد)\n(سقني ثم سق حمير قومي ... كأس خمر أولي النهى و العماد)\nلشعر لحسان بن تبع و الغناء لأحمد النصيبي خفيف ثقيل أول بالسبابة في مجرى الوسطى عن إسحاق وفيه ليونس لحن من كتابه","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":7,"spl":"مخارق يكيد لإسحاق — متمم العبدي و الجويرية اعجب بفصاحة لسان الجويرية ورقة ألفاظها","tags":["الجواري والنساء"],"song":1,"loc":3758},
{"id":"b289-20","bab":"الجزء 22","sec":"كان ينشد وجوه قومه","page":"ج22 ص318","text":"أخبرني بخبر حسان الذي من أجله قال هذا الشعر علي بن سليمان الأخفش عن السكري عن ابن حبيب عن ابن الأعرابي وعن أبي عبيدة و أبي عمرو وابن الكلبي وغيرهم قال\nكان حسان بن تبع أحول أعسر بعيد الهمة شديد البطش فدخل إليه يوما وجوه قومه وهم الأقيال من حمير فلما أخذوا مواضعهم ابتدأهم فأنشدهم\n(أيها الناس إن رأيي يريني ... وهو الرأي طوفة في البلاد)\n(بالعوالي وبالقنابل تردي ... بالبطاريق مشية العواد)\nذكر الأبيات التي مضت آنفا ثم قال لهم استعدوا لذلك فلم يراجعه أحد لهيبته فلما كان بعد ثلاثة خرج وتبعه وطئ أرض العجم و قال لأبلغن من البلاد حيث لم يبلغ أحد من التبابعة فجال بهم في ارض خراسان ثم مضى إلى المغرب حتى بلغ رومية وخلف عليها\nابن عم له وأقبل إلى أرض العراق حتى إذا صار على شاطئ الفرات قالت وجوه حمير ما لنا نفني أعمارنا مع هذا نطوف في الأرض كلها ونفرق بيننا وبين بلدنا وأولادنا و عيالنا وأموالنا فلا ندري من نخلف عليهم بعدنا فكلموا أخاه عمرا و قالوا له كلم أخاك في الرجوع إلى بلده وملكه\nقال هو أعسر من ذلك وأنكر فقالوا فاقتله ونملكك علينا فأنت أحق بالملك من أخيك وأنت أعقل وأحسن نظرا لقومك فقال أخاف ألا تفعلوا وأكون قد قتلت أخي وخرج الملك عن يدي فواثقوه حتى ثلج إلى قولهم وأجمع الرؤساء على قتل أخيه كلهم إلا ذا رعين فإنه خالفهم\nوقال ليس هذا برأي يذهب الملك من حمير فشجعه الباقون على قتل أخيه فقال ذو رعين أن قتلته باد ملكك فلما رأى ذو رعين ما أجمع عليه القوم أتاه بصحيفة مختومة فقال يا عمرو إني مستودعك هذا الكتاب فضعه عندك في مكان حريز وكتب فيه\n(ألا من يشتري سهرا بنوم ... سعيد من يبيت قرير عين)\n(فإن تك حمير غدرت وخانت ... فمعذرة الإله لذي رعين)","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":8,"spl":"كان ينشد وجوه قومه","tags":["الخمر"],"loc":3759},
{"id":"b289-21","bab":"الجزء 22","sec":"قتله أخوه وهو نائم فامتنع منه النوم","page":"ج22 ص319","text":"ثم إن عمرا أتى حسان أخاه وهو نائم على فراشه فقتله واستولى على ملكه فلم يبارك فيه وسلط الله عليه السهر وامتنع منه النوم فسأل الأطباء و الكهان و العياف فقال له كاهن منهم إنه ما قتل أخاه رجل قط إلا منع\nنومه فقال عمرو هؤلاء رؤساء حمير حملوني على قتله ليرجعوا إلى بلادهم ولم ينظروا إلي ولا لأخي فجعل يقتل من أشار عليه منهم بقتله فقتلهم رجلا رجلا حتى خلص إلي ذي رعين وأيقن بالشر فقال له ذو رعين ألم تعلم أني أعلمتك ما في قتله ونهيتك وبينت هذا\nقال وفيم هو قال في الكتاب الذي استودعتك فدعا بالكتاب فلم يجده فقال ذو رعين ذهب دمي على أخذي بالحزم فصرت كمن أشار بالخطأ ثم سأل الملك أن ينعم في طلبه ففعل فأتى به فقرأه فإذا فيه البيتان فلما قرأهما\nقال لقد أخذت بالحزم قال إني خشيت ما رأيتك صنعت بأصحابي قال وتشتت أمر حمير حين قتل أشرافها واختلفت عليه حتى وثب على عمرو لخيعة ينوف ولم يكن من أهل بيت المملكة فقتله واستولى على ملكه وكان يقال له ذو شناتر الحميري وكان فاسقا يعمل عمل قوم لوط وكان يبعث إلى أولاد الملوك فيلوط بهم و كانت حمير إذا ليط بالغلام لم تملكه ولم ترتفع به و كانت له مشربة يكون فيها يشرف على حرسه فإذا أتي بالغلام أخرج رأسه إليهم وفي فيه السواك فيقطعون مشافر ناقة المنكوح وذنبها فإذا خرج صيح به أرطب أم يباس فمكث بذلك زمانا حتى نشأ زرعة ذو نواس و كانت له ذؤابة وبها سمي ذا نواس وهو الذي تهود وتسمى يوسف وهو صاحب الأخدود بنجران و كانوا نصارى فخوفهم وحرق الإنجيل وهدم الكنائس ومن أجله غزت الحبشة\nاليمن لانهم نصارى فلما غلبوا على اليمن اعترض البحر واقتحمه على فرس فغرق فلما نشأ ذو نواس قيل له كأنك وقد فعل بك كذا وكذا فأخذ سكينا لطيفا خفيفا وسمه وجعل له غلافا فلما دعا به لخيعة جعله بين أخمصه ونعله وأتاه على ناقة له يقال لها سراب فأناخها وصعد إليه فلما قام يجامعه كما كان يفعل انحنى زرعة فأخذ السكين فوجأ بها بطنه فقتله واحتز رأسه فجعل السواك في فيه وأطلعه من الكوة فرفع الحرس رؤوسهم فرأوه ونزل زرعة فصاحوا زرعة يا ذا نواس أرطب أم يباس فقال ستعلم الأحراس است ذي نواس رطب أم يباس وجاء إلى ناقته فركبها فلما رأى الحرس اطلاع الرأس صعدوا إليه فإذا هو قد قتل فأتوا زرعة فقالوا ما ينبغي أن يملكنا غيرك بعد أن أرحتنا من هذا الفاسق واجتمعت حمير إليه ثم كان من قصته ما ذكرناه آنفا\n(يا ربة البيت قومي غير صاغرة ... ضمي إليك رحال القوم و القربا)\n(في ليلة من جمادى ذات أندية ... لا يبصر الكلب من ظلمائها الطنبا)\n(لا ينبح الكلب فيها غير واحدة ... حتى يلف على خيشومه الذنبا)\nلشعر لمرة بن محكان السعدي والغناء لابن سريج رمل بالوسطى وله فيه أيضا خفيف ثقيل بالوسطى كلاهما عن عمرو وذكر حبش أن فيه لمعبد ثاني ثقيل بالوسطى و الله أعلم","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":9,"spl":"قتله أخوه وهو نائم فامتنع منه النوم","tags":["الحب والغزل"],"song":1,"loc":3760},
{"id":"b289-23","bab":"الجزء 22","sec":"أخبار مرة بن محكان — كان شريفا جوادا شديد السخاء","page":"ج22 ص321 – ج22 ص322","text":"هو مرة بن محكان ولم يقع إلينا باقي نسبه أحد بني سعد بن زيد مناة بن تميم شاعر مقل إسلامي من شعراء الدولة الأموية وكان في عصر جرير والفرزدق فأحملا ذكره لنباهتهما في الشعر\nوكان مرة شريفا جوادا وهو أحد من حبس في المناحرة والإطعام أخبرني الحسن بن علي قال حدثنا أحمد بن الحارث الخراز عن المدائني قال كان مرة بن محكان سخيا وكان أبو البكراء يوائمه في الشرف وهما جميعا من بني الربيع فأنهب مرة بن محكان ماله الناس فحبسه عبيد الله بن زياد فقال في ذلك الأبيرد الرياحي\n(حبست كريما أن يجود بماله ... سعى في ثأى من قومه متفاقم)\n(كأن دماء القوم إذ علقوا به ... على مكفهر من ثنايا المخارم)\n(فإن أنت عاقبت ابن محكان في الندى ... فعاقب هداك الله أعظم حاتم)\nال فأطلقه عبيد الله بن زياد فذبح أبو البكراء مائة شاة فنحر مرة بن محكان مائة بعير فقال بعض شعراء بني تميم يمدح مرة\n(شرى مائة فأنهبها جوادا ... وأنت تناهب الحدف القهادا)\nلحدف صغار الغنم والقهاد البيض أخبرني أحمد بن محمد الأسدي أبو الحسن قال حدثنا الرياشي قال سئل أبو عبيدة عن معنى قول مرة بن محكان\n(ضمني إليك رحال القوم والقربا ... )\nما الفائدة في هذا فقال كان الضيف إذا نزل بالعرب في الجاهلية ضموا إليهم رحله وبقي سلاحه معه لا يؤخذ خوفا من البيات فقال مرة بن محكان يخاطب امرأته ضمي إليك رحال هؤلاء الضيفان و سلاحهم فإنهم عندي في عز وأمن من الغارات و البيات فليسوا ممن يحتاج أن يبيت لا بسا سلاحه","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":10,"spl":"أخبار مرة بن محكان — كان شريفا جوادا شديد السخاء — قتله مصعب بن الزبير","tags":["المديح"],"loc":3761,"partial":1},
{"id":"b289-24","bab":"الجزء 22","sec":"قتله مصعب بن الزبير","page":"ج22 ص323","text":"أخبرني محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن يونس قال كان الحارث بن أبي ربيعة على البصرة أيام\nابن الزبير فخاصم إليه رجل من بني تميم يقال له مرة بن محكان رجلا فلما أراد إمضاء الحكم عليه نشأ مرة بن محكان يقول\n(أحار تثبت في القضاء فإنه ... إذا ما إمام جار في الحكم أقصدا)\n(وإنك موقوف على الحكم فاحتفظ ... ومهما تصبه اليوم تدرك به غدا)\n(فإني مما أدرك الأمر بالأنى ... وأقطع في رأس الأمير المهندا)\nلما ولي مصعب بن الزبير دعاه فأنشده الأبيات فقال أما و الله لأقطعن السيف في رأسك قبل أن تقطعه في رأسي و أمر به فحبس ثم دس إليه من قتله أخبرني الحسين بن يحيى عن حماد عن أبيه عن ابن جامع عن يونس قال جاء رجل من قريش إلى الغريض فقال له بأبي أنت و أمي إني جئتك قاصدا من الطائف أسألك عن صوت تغنيني إياه قال وما هو قال لحنك في هذا الشعر\n(نشرب لون الرازقي بياضه ... أو الزعفران خالط المسك رادعه)\nفقال لا سبيل إلى ذلك هذا الصوت قد نهتني الجن عنه ولكني أغنيك في شعر لمرة بن محكان وقد طرقه ضيف في ليلة شاتية فأنزلهم ونحر لهم ناقته ثم غناه قوله\n(يا ربة البيت قومي غير صاغرة ... ضمي إليك رحال القوم والقربا)\nفأطربه ثم قال له الغريض هذا لعن أخذته من عبيد بن سريج وسأغنيك لحنا عملته في شعر على وزن هذا الشعر ورويه للحطيئة ثم غناه\n(ما نقموا من بغيض لا أبالهم ... في بائس جاء يحدو أينقا شزبا)\n(جاءت به من بلاد الطور تحمله ... حصاء لم تترك دون العصا شذبا)\nقام القرشي فقبل رأسه فقال له فدتك نفسي وأهلي لو لم أقدم مكة لعمرة ولا لبر وتقوى ثم قدمت إليها لأراك وأسمع منك لكان ذلك قليلا ثم انصرف وحدثني بعض مشايخ الكتاب أنه دخل على أبي العبيس بن حمدون يوما فسأله أن يقيم عند فأقام وأتاهم أبو العبيس بالطعام فأكلوا ثم قدم الشراب فشربوا وغناهم أبو العبيس يومئذ هذا الصوت\n(ألا مت أعطيت صبرا وعزمة ... غداة رأيت الحي للبين غاديا)\n(ولم تعتصر عينيك فكهة مازح ... كأنك قد أبدعت إذ ظلت باكيا)\nأحسن ما شاء ثم ضرب ستارته و قال\n(يا ربة البيت غني غير صاغرة ... )\nاندفعت عرفان فغنت\n(يا ربة البيت قومي غير صاغرة ... ضمي إليك رحال القوم والقربا)\nال فما سمعت غناء قط أحسن مما سمعته من غنائهما يومئذ","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":10,"spl":"أخبار مرة بن محكان — كان شريفا جوادا شديد السخاء — قتله مصعب بن الزبير","tags":[],"loc":3762,"partial":1},
{"id":"b289-25","bab":"الجزء 22","sec":"نسبة هذا الصوت","page":"ج22 ص326","text":"\n(ألا مت لا أعطيت صبرا وعزمة ... غداة رأيت الحي للبين غاديا)\n(ولم تعتصر عينيك فكهة مازح ... كأنك قد أبدعت إذ ظلت باكيا)\n(فصيرت دمعا أن بكيت تلددا ... به لفراق الإلف كفؤا موازيا)\n(لقد جل قدر الدمع عندك أن ترى ... بكاءك للبين المشت مساويا)\nلشعر لأعرابي أنشدناه الحرمي بن أبي العلاء عن الحسين بن محمد بن أبي طالب الديناري عن إسحاق الموصلي لأعرابي قال الديناري وكان إسحاق كثيرا ما ينشد الشعر للأعراب وهو قائله وأظن هذا الشعر له و الغناء لعمرو بن بانة ثقيل أول بالبنصر من كتابه\nصوت فإن تك من شيبان أمي فإنني ... لأبيض من عجل عريض المفارق وكيف بذكري أم هارون بعد ما ... خبطن بأيديهن رمل الشقائق كأن نقا من عالج أزرت به ... إذا الزل ألهاهن شد المناطق وإنا لتغلي في الشتاء قدورنا ... ونصبر تحت اللامعات الخوافق\nروضه من الطويل الشعر للعديل بن الفرخ العجلي و الغناء لمعبد خفيف ثقيل من أصوات قليلة الأشباه عن يونس وإسحاق وفيه لهشام بن المرية لحن من كتاب إبراهيم وفيه لسنان الكاتب ثقيل أول عن الهشامي وحبش و قال حبش خاصة فيه للهذلي أيضا ثاني ثقيل بالوسطى","topic":"أخبار مالك بن الريب و نسبه","topicNo":289,"sp":11,"spl":"نسبة هذا الصوت","tags":["الرواية والكتابة"],"song":1,"loc":3763},
{"id":"b290-1","bab":"الجزء 22","sec":"أخبار العديل ونسبه","page":"ج22 ص327","text":"العديل بن الفرخ بن معن بن الأسود بن عمرو بن عوف بن ربيعة بن جابر بن ثعلبة بن سمي بن الحارث وهو العكابة بن ربيعة بن عجل بن لجيم بن صعب بن علي بن بكر بن وائل بن قاسط بن هنب بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة بن نزار و\nقال أبو عبيدة كان العكابة اسم كلب للحارث بن ربيعة بن عجل فلقب باسم كلبه وغلب عليه قال وكان عجل من محمقي العرب قيل له أن لكل فرس جواد اسما وان فرسك هذا سابق جواد فسمه ففقأ إحدى عينيه وقال قد سميته الأعور وفيه يقول الشاعر\n(رمتني بنو عجل بداء أبيهم ... وهل أحد في الناس أحمق من عجل)\n(أليس أبوهم عار عين جواده ... فصارت بن الأمثال تضرب بالجهل)","topic":"أخبار العديل ونسبه","topicNo":290,"sp":0,"spl":"أخبار العديل ونسبه — عرفت أسرته بالشعر و الفروسية","tags":[],"loc":3764},
{"id":"b290-2","bab":"الجزء 22","sec":"عرفت أسرته بالشعر و الفروسية","page":"ج22 ص328","text":"والعديل شاعر مقل من شعراء الدولة الأموية وكان له ثمانية إخوة وأمهم جميعا امرأة من بني شيبان ومنهم من كان شاعرا فارسا أسود وسوادة وشملة وقيل سلمة والحارث وكان يقال لأمهم درماء وكان للعديل وإخوته ابن عم يسمى عمرا فتزوج بنت عم لهم بغير\nأمرهم فغضبوا ورصدوه ليضربوه وخرج عمرو ومعه عبد له يسمى دابغا فوثب العديل وإخوته فأخذوا سيوفهم فقالت أمهم إني أعوذ بالله من شركم فقال لها ابنها الأسود وأي شيء تخافين علينا فو الله لو حملنا بأسيافنا على هذا الحنو حنو قراقر لما قاموا لنا فانطلقوا حتى لقوا عمرا فلما رآهم ذعر منهم وناشدهم فأبوا فحمل عليه سوادة فضرب عمرا ضربة بالسيف وضربه عمرو فقطع رجله فقال سوادة\n(ألا من يشتري رجلا برجل ... تأبى للقيام فلا تقوم)\nقال عمرو ولدابغ اضرب وأنت حر فحمل دابغ فقتل منهم رجلا وحمل عمرو فقتل آخر وتداولاهم فقتلا منهم أربعة وضرب العديل على رأسه ثم تفرقوا وهرب دابغ حتى أتى الشأم فداوى ربضة بن النعمان الشيباني للعديل ضربته ومكث مدة ثم خرج العديل بعد ذلك حاجا فقيل له إن دابغا قد جاء حاجا وهو يرتحل فيأخذ طريق الشأم وقد اكترى فجعل العديل عليه الرصد حتى إذا خرج دابغ ركب العديل راحلته وهو متلثم وانطلق يتبعه حتى لقيه خلف الركاب يحدو بشعر العديل ويقول\n(يا دار سلمى أقفرت من ذي قار ... وهل بإقفار الديار من عار)\n(وقد كسين عرقا مثل القار ... يخرجن من تحت خلال الأوبار)\nلحقه العديل فحبس عليه بعيره وهو لا يعرفه ويسير رويدا ودابغ\nيمشي رويدا وتقدمت إبله فذهبت وإنما يريد أن يباعده عنها بوادي حنين ثم قال له العديل والله لقد استرخى حقب رحلي أنزل فأغير الرحل وتعينني فنزل فغير الرحل وجعل دابغ يعينه حتى إذا شد الرحل أخرج العديل السيف فضربه حتى برد ثم ركب راحلته فنجا وأنشأ يقول\n(ألم ترني جللت بالسيف دابغا ... وإن كان ثأرا لم يصبه غليلي)\n(بوادي حنين ليلة البدر رعته ... بأبيض من ماء الحديد صقيل)\n(وقلت لهم هذا الطريق أمامكم ... ولم أك إذ صاروا لهم بدليل)\nقال أبو اليقطان كان العديل هجا جرثومة العنزي الجلاني فقال فيه\n(أهاجي بني جلان إذ لم يكن لها ... حديث ولا في الأولين قديم)\nأجابه جرثومة فقال\n(وإن امرأ يهجو الكرام ولم ينل ... من الثأر إلا دابغا للئيم)\n(أتطلب في جلان وترا ترومه ... وفاتك بالأوتار شر غريم)\nالوا واستعدى مولى دابغ على العديل الحجاج بن يوسف وطالبه بالقود فيه فهرب العديل من الحجاج إلى بلد الروم فلما صار إلى بلد الروم لجأ إلى قيصر فأمنه فقال في الحجاج\n(أخوف بالحجاج حتى كأنما ... يحرك عظم في الفؤاد مهيض)\n(ودون يد الحجاج من أن تنالني ... بساط لأيدي الناعجات عريض)\n(مهامه أشباه كأن سرابها ... ملاء بأيدي الراحضات رحيض)\nبلغ شعره الحجاج فكتب إلى قيصر لتبعثن به أو لأغزينك جيشا يكون أوله عندك وآخره عندي فبعث به قيصر إلى الحجاج فقال له الحجاج لما أدخل عليه أأنت القائل ودون يد الحجاج من أن تنالني فكيف رأيت الله أمكن منك قال بل أنا القائل أيها الأمير\n(فلو كنت في سلمى أجا وشعابها ... لكان لحجاج علي سبيل)\n(خليل أمير المؤمنين وسيفه ... لكل إمام مصطفى وخليل)\n(بنى قبة الإسلام حتى كأنما ... هدى الناس من بعد الضلال رسول)\nخلى سبيله وتحمل دية دابغ في ماله","topic":"أخبار العديل ونسبه","topicNo":290,"sp":0,"spl":"أخبار العديل ونسبه — عرفت أسرته بالشعر و الفروسية","tags":["الهجاء"],"loc":3765},
{"id":"b290-3","bab":"الجزء 22","sec":"الحجاج يعفو عن العديل بعد ان هجاه ثم عاد فمدحه","page":"ج22 ص331","text":"أخبرني عمي وحبيب بن نصر المهلبي قالا حدثنا عبد الله بن أبي سعد قال حدثني محمد بن منصور بن عطية الغنوي قال أخبرني جعفر بن عبيد الله بن جعفر عن أبي عثمان البقطري قال\nخرج العديل بن الفرخ يريد الحجاج فلما صار ببابه حجبه الحاجب فوثب عليه العديل وقال إنه لن يدخل على الأمير بعد رجالات قريش أكبر مني ولا أولى بهذا الباب فنازعه الحاجب الكلام فأحفظه وانصرف العديل\nعن باب الحجاج إلى يزيد بن المهلب فلما دخل إليه أنشأ يقول\n(لئن أرتج الحجاج بالبخل بابه ... فباب الفتى الأزدي بالعرف يفتح)\n(فتى لا يبالي الدهر ما قل ماله ... إذا جعلت أيدي المكارم تسنح)\n(يداه يد بالعرف تنهب ما حوت ... وأخرى على الأعداء تسطو وتجرح)\n(إذا ما أتاه المرملون تيقنوا ... بأن الغنى فيهم وشيكا سيسرح)\n(أقام على العافين حراس بابه ... ينادونهم والحر بالحر يفرح)\n(هلموا إلى سيب الأمير وعرفه ... فإن عطاياه على الناس تنفح)\n(وليس كعلج من ثمود بكفه ... من الجود والمعروف حزم مطوح)\nفقال له يزيد عرضت بنا وخاطرت بدمك وبالله لا يصل إليك وأنت في حيزي فأمر له بخمسين ألف درهم وحمله على أفراس وقال له الحق بعلياء نجد واحذر أن تعلقك حبائل الحجاج أو تحتجنك محاجنه وابعث إلي في كل عام ذلك علي مثل هذا فارتحل وبلغ الحجاج خبره فأحفظه ذلك على يزيد وطلب العديل ففاته وقال لما نجا\n(ودون يد الحجاج من أن تنالني ... بساط لأيدي الناعجات عريض)\nال ثم ظفر به الحجاج بعد ذلك فقال إيه أنشدني قولك\n(ودون يد الحجاج من أن تنالني ... )\nقال لم أقل هذا أيها الأمير ولكني قلت\n(إذا ذكر الحجاج أضمرت خيفة ... لها بين أحناء الضلوع نقيض)\nتبسم الحجاج وقال أولى لك وعفا عنه وفرض له","topic":"أخبار العديل ونسبه","topicNo":290,"sp":1,"spl":"الحجاج يعفو عن العديل بعد ان هجاه ثم عاد فمدحه — شفع له سادات بكر عند الحجاج","tags":["السفر والحج"],"loc":3766,"partialRef":{"sid":"b290-2","gi":5,"vi":1,"side":0},"partial":1},
{"id":"b290-4","bab":"الجزء 22","sec":"شفع له سادات بكر عند الحجاج","page":"ج22 ص333","text":"وقال أبو عمرو الشيباني لما لج الحجاج في طلب العديل لفظته الأرض ونبا به كل مكان هرب إليه فأتى بكر بن وائل وهم يومئذ بادون جميع منهم بنو شيبان وبنو عجل وبنو يشكر فشكا إليهم أمره\nوقال لهم أنا مقتول أفتسلمونني هكذا وأنتم أعز العرب قالوا لا والله ولكن الحجاج لا يراغم ونحن نستوهبك منه فإن أجابنا فقد كفيت وأن حادنا في أمرك منعناك وسألنا أمير المؤمنين أن يهبك لنا فأقام فيهم واجتمعت وجوه بكر بن وائل إلى الحجاج فقالوا له أيها الأمير إنا قد جنينا جميعا عليك جناية لا يغفر مثلها وها نحن قد استسلمنا وألقيتنا بأيدينا إليك فإما وهبت فأهل ذلك أنت وإما عاقبت فكنت المسلط الملك العادل فتبسم\nوقال قد عفوت عن كل جرم إلا جرم الفاسق العديل فقاموا على أرجلهم فقالوا مثلك أيها الأمير لا يستثني على أهل طاعته وأوليائه في شيء فإن رأيت ألا\nتكدر مننك باستثناء وأن تهب لنا العديل في أول من تهب قال قد فعلت فهاتوه قبحه الله فأتوه به فلما مثل بين يديه أنشأ يقول","topic":"أخبار العديل ونسبه","topicNo":290,"sp":1,"spl":"الحجاج يعفو عن العديل بعد ان هجاه ثم عاد فمدحه — شفع له سادات بكر عند الحجاج","tags":["المديح","السفر والحج"],"loc":3767},
{"id":"b290-5","bab":"الجزء 22","sec":"ماذا قال في حضرة الحجاج","page":"ج22 ص334","text":"(فلو كنت في سلمى أجا وشعابها ... لكان لحجاج علي دليل)\n(بنى قبة الإسلام حتى كأنما ... هدى الناس من بعد الضلال رسول)\n(إذا جار حكم الناس ألجأ حكمه ... إلى الله قاض بالكتاب عقول)\n(خليل أمير المؤمنين وسيفه ... لكل إمام صاحب وخليل)\n(به نصر الله الخليفة منهم ... وثبت ملكا كاد عنه يزول)\nيروى به نصر الله الإمام عليهم\n(فأنت كسيف الله في الأرض خالد ... تصول بعون الله حين تصول)\n(وجازيت أصحاب البلاء بلاءهم ... فما منهم عما تحب نكول)\n(وصلت بمران العراق فأصبحت ... مناكبها للوطء وهي ذلول)\nقام الواحد مقام الجمع في قوله ذلول\n(أذقت الحمام ابني عباد فأصبحوا ... بمنزل موهون الجناح ثكول)\n(ومن قطري نلت ذاك وحوله ... كتائب من رجالة وخيول)\n(إذا ما أتت باب ابن يوسف ناقتي ... أتت خير منزول به ونزيل)\n(وما خفت شيئا غير ربي وحده ... إذا ما انتحيت النفس كيف أقول)\n(ترى الثقلين الجن والإنس أصبحا ... على طاعة الحجاج حين يقول)\nقال له الحجاج أولى لك فقد نجوت وفرض له وأعطاه عطاءه فقال يمدح سائر قبائل وائل ويذكر دفعها عنه ويفتخر بها\n(صرم الغواني واستراح عواذلي ... وصحوت بعد صبابة وتمايل)\n(وذكرت يوم لوى عتيق نسوة ... يخطرن بين أكلة ومراحل)\n(لعب النعيم بهن في أظلاله ... حتى لبسن زمان عيش غافل)\n\n(يأخذن زينتهن أحسن ما ترى ... وإذا عطلن فهن غير عواطل)\n(وإذا خبأن خدودهن أريننا ... حدق المها وأجدن سهم القاتل)\n(ورمينني لا يستترن بجنة ... إلا الصبا وعلمن أين مقاتلي)\n(يلبسن أردية الشباب لأهلها ... ويجر باطلهن حبل الباطل)\nلغناء في هذه الأبيات الأربعة لابن سريج ثاني ثقيل بالوسطى من رواية يحيى المكي وذكر الهشامي أنه من منحول يحيى المكي إلى ابن سريج\n(بيض الأنوق كأنهن ومن يرد ... بيض الأنوق فوكرها بمعاقل)\n(زعم الغواني أن جهلك قد صحا ... وسواد رأسك فضل شيب شامل)\n(ورآك أهلك منهم ورأيتهم ... ولقد تكون مع الشباب الخاذل)\n(وإذا تطاولت الجبال رأيتنا ... ولقد تكون مع الشباب الخاذل)\n(وإذا سألت ابني نزار بينا ... مجدي ومنزلتي من ابني وائل)\n(حدبت بنو بكر علي وفيهم ... كل المكارم والعديد الكامل)\n(خطروا ورائي بالقنا وتجمعت ... منهم قبائل أردفوا بقبائل)\n(إن الفوارس من لجيم لم تزل ... فيهم مهابة كل أبيض ناعل)\n(متعمم بالتاج يسجد حوله ... من آل هوذة للمكارم حامل)\n(أو رهط حنظلة الذين رماحهم ... سم الفوارس حتف موت عاجل)\n(قوم إذا شهروا السيوف رأوا لها ... حقا ولم يك سلها للباطل)\n(ولئن فخرت بهم لمثل قديمهم ... بسط المفاخر للسان القائل)\n(أولاد ثعلبة الذين لمثلهم ... حلم الحليم ورد جهل الجاهل)\n(ولمجد يشكر سورة عادية ... وأب إذا ذكروه ليس بخامل)\n(وبنو القدار إذا عددت صنيعهم ... وضح القديم لهم بكل محافل)\n(وإذا فخرت بتغلب ابنة وائل ... فاذكر مكارم من ندى وشمائل)\n(ولتغلب الغلباء عز بين ... عادية ويزيد فوق الكاهل)\n(تسطو على النعمان وابن محرق ... وابني قطام بعزة وتناول)\n(بالمقربات يبتن حول رحالهم ... كالقد بعد أجلة وصواهل)\n(أولاد أعوج والصريح كأنها ... عقبان يوم دجنة ومخايل)\n(يلقطن بعد أزومهن على الشبا ... علق الشيكم بألسن وجحافل)\n(قوم هم قتلوا ابن هند عنوة ... وقنا الرماح تذود ورد الناهل)\n(منهم أبو حنش وكان بكفه ... ري السنان وري صدر العامل)\n(ومهلهل الشعراء إن فخروا به ... وندى كليب عند فضل النائل)\n(حجب المنية دون واحد أمه ... من أن تبيت وصدرها ببلابل)\n(كفى مجالسة السباب فلم يكن ... يستب مجلسه وحق النازل)\n(حتى أجار على الملوك فلم يدع ... حربا ولا صعرا لرأس مائل)\n(في كل حي للهذيل ورهطه ... نعم وأخذ كريمة بتناول)\n(بيض كرائم ردهن لعنوة ... أسل القنا وأخذن غير أرامل)\n(أبناؤهن من الهذيل ورهطه ... مثل الملوك وعشن غير عوامل)\nقال أبو عمرو أيضا قال العديل لرجل من موالي الحجاج كان وجهه في جيش إلى بني عجل يطلب العديل حين هرب منه فلم يقدر عليه فاستاق إبله وأحرق بيته وسلب امرأته وبناته وأخذ حليهن فدخل العديل يوما على الحجاج ومولاه هذا بين يديه واقف فتعلق بثوبه وأقبل عليه وأنشأ يقول\n(سلبت بناتي حليهن فلم تدع ... سوارا ولا طوقا على النحر مذهبا)\nكذا في الشعر سلبت بناتي والغناء فيه سلبت الجواري حليهن","topic":"أخبار العديل ونسبه","topicNo":290,"sp":2,"spl":"ماذا قال في حضرة الحجاج","tags":["الحب والغزل"],"song":2,"loc":3768},
{"id":"b290-6","bab":"الجزء 22","sec":"ماذا قال في حضرة الحجاج","page":"ج22 ص334","text":"(وما عز في الآذان حتى كأنما ... تعطل بالبيض الأوانس ربربا)\n(عواطل إلا أن ترى بخدودها ... قسامة عتق أو بنانا مخضبا)\n(فككت البرين عن خدال ... كأنها برادي غيل ماؤه قد تنضبا)\n(من الدر والياقوت عن كل حرة ... ترى سمطها بين الجمان مثقبا)\n(دعون أمير المؤمنين فلم يجب ... دعاء ولم يسمعن أما ولا أبا)\nنى في الأول والرابع من هذه الأبيات أحمد النصيبي الهمذاني ثان\nثقيل بالسبابة في مجرى الوسطى عن إسحاق وفيهما ثقيل أول بالسبابة والوسطى نسبه ابن المكي إلى عبد الرحيم الدفاف ونسبه الهشامي إلى عبد الله بن العباس","topic":"أخبار العديل ونسبه","topicNo":290,"sp":3,"spl":"ماذا قال في حضرة الحجاج — العديل ومالك بن مسمع","tags":["اللهو والمزاح"],"loc":3769},
{"id":"b290-7","bab":"الجزء 22","sec":"شماتته بعدو له أصيب في أنفه","page":"ج22 ص339","text":"وقال أبو عمرو الشيباني أصاب رجل من رهط العديل من بني العكابة أنف رجل من بني عجل يقال له جبار فقال العديل في ذلك وكان عدوا له\n(ألم تر جبارا ومارن أنفه ... له ثلم يهوين أن يتنخعا)\n(ونحن جدعنا أنفه فكأنما ... يرى الناس أعداء إذا هو أطلعا)\n(كلوا أنف جبار بكارا فإنما ... تركناه عن فرط من الشر أجدعا)\n(معاقد من أيديهم وأنوفهم ... بكارا ونيبا تركب الحزن ظلعا)\nال وكان رجل من رهط العديل أيضا ضرب يد وكيع أحد بني الطاغية وهما يشربان فقطعها وافترقا ثم هرب العديل وأبوه إلى بني قيس بن سعد لما قال الشعر الأول يفخر بقطع أنف جبار ويد وكيع لأنهم حلفوا أن يقطعوا أنفه ويده دون من فعل ذلك بهم فلجأ إلى عفير بن جبير بن هلال بن مرة بن عبد الله بن معاوية بن عبد بن سعد بن جشم بن قيس بن عجل فقال العديل في ذلك\n(تركت وكيعا بعد ما شاب رأسه ... أشل اليمين مستقيم الأخادع)\n(فشرب بها ورق الإفال وكل بها ... طعام الذليل وانجحر في المخادع)\nقالت بنو قيس بن سعد للفرخ أبي العديل يا فرخ أنصف قومك وأعطهم حقهم فركب إليهم الفرخ ومعه حسان بن وقاف ودينار رجلان من بني الحارث فأسرته بنو الطاغية وانتزعوه من الرجلين وتوجهوا به نحو البصرة فرجع حسان ودينار إلى قومهما مستنفرين لهم فركب النفير في طلب بني الطاغية فأدركوا منهم رجلا فأسروه بدل الفرخ ثم إن عفيرا لحق بهم فاشترى منهم الجراحة بسبعين بعيرا وأخذ الفرخ منهم فأطلقه فقال العديل في ذلك\n(ما زال في قيس بن سعد لجارهم ... على عهد ذي القرنين معط ومانع)\n(هم استنقذوا حسان قسرا وأنتم ... لئام المقام والرماح شوارع)\n(غدرتم بدينار وحسان غدرة ... وبالفرخ لما جاءكم وهو طائع)\n(فلولا بنو قيس بن سعد لأصبحت ... علي شدادا قبضهن الأصابع)\n(ألا تسألون ابن المشتم عنهم ... جعامة والجيران واف وظالع)\nخبرني جعفر بن قدامة قال حدثنا الرياشي عن الأصمعي قال قال أبو النجم للعديل بن الفرخ أرأيت قولك\n(فإن تك من شيبان أمي فإنني ... لأبيض عجلي عريض المفارق)\nكنت شاكا في نسبك حين قلت هذا فقال له العديل أفشككت في نفسك أو شعرك حين قلت\n(أنا أبو النجم وشعري شعري ... لله دري ما يجن صدري)\nفأمسك أبو النجم واستحيا","topic":"أخبار العديل ونسبه","topicNo":290,"sp":3,"spl":"ماذا قال في حضرة الحجاج — العديل ومالك بن مسمع","tags":["الرواية والكتابة"],"loc":3770},
{"id":"b290-8","bab":"الجزء 22","sec":"العديل ومالك بن مسمع","page":"ج22 ص341","text":"أخبرني أبو دلف هاشم بن محمد الخزاعي قال حدثنا الرياشي عن العتبي قال حمل زياد إلى معاوية مالا من البصرة ففزعت تميم والأزد وربيعة إلى مالك بن مسمع وكانت ربيعة مجتمعة عليه كاجتماعها على كليب في حياته واستغاثوا به وقالوا يحمل المال ونبقى بلا عطاء فركب مالك في ربيعة واجتمع الناس إليه فلحق بالمال فرده وضرب فسطاطا بالمربد وأنفق المال في الناس حتى وفاهم عطاءهم ثم\nقال إن شتم الآن أن تحملوا فاحملوا فما راجعه زياد في ذلك بحرف لما ولي حمزة بن عبد الله بن الزبير البصرة جمع مالا ليحمله إلى أبيه فاجتمع الناس إلى مالك واستغاثوا به ففعل مثل فعله بزياد فقال العديل بن الفرخ في ذلك\n(إذا ما خشينا من أمير ظلامة ... دعونا أبا غسان يوما فعسكرا)\n(ترى الناس أفواجا إلى باب داره ... إذا شاء جاؤوا دارعين وحسرا)\nأول هذه القصيدة\n(أمن منزل من أم سكن عشية ... ظللت به أبكي حزينا مفكرا)\nمعي كل مسترخي الإزار كأنه ... إذا ما مشى من جن غيل وعبقرا يزجي المطايا لا يبالي كليهما ... مقلصة خوصا من الأين ضمرا","topic":"أخبار العديل ونسبه","topicNo":290,"sp":3,"spl":"ماذا قال في حضرة الحجاج — العديل ومالك بن مسمع","tags":["الخمر"],"loc":3771},
{"id":"b290-9","bab":"الجزء 22","sec":"الفرزدق يقول العديل شاعر بكر بن وائل","page":"ج22 ص342","text":"أخبرني حبيب بن نصر المهلبي قال حدثنا عبد الله بن أبي سعد قال حدثني علي بن الحسن الشيباني قال حدثني عبدة بن عصمة بن معبد القيسي قال\nحدثني جدي أبو أمي فراس بن خندف عن أبيه عن جده علي بن شفيع قال لقيت الفرزدق منصرفه عن بكر بن وائل فقلت له يا أبا فراس من شاعر بكر بن وائل ممن خلفته خلفك\nقال أميم بني عجل يعني العديل بن الفرخ على أنه ضائع الشعر سروق للبيوت أخبرني جعفر بن قدامة قال حدثني محمد بن عبد الله بن مالك الخزاعي عن إسحاق عن الهيثم بن عدي عن حماد الراوية قال لما قدم الحجاج العراق قال العديل بن الفرخ\n(دعوا الجبن يا أهل العراق فإنما ... يهان ويسبى كل من لا يقاتل)\n(لقد جرد الحجاج للحق سيفه ... ألا فاستقيموا لا يميلن مائل)\n(وخافوه حتى القوم بين ضلوعهم ... كنزو القطا ضمت عليه الحبائل)\n(وأصبح كالبازي يقلب طرفه ... على مرقب والطير منه دواحل)\nال فقال الحجاج وقد بلغته لأصحابه ما تقولون قالوا نقول إنه مدحك فقال كلا ولكنه حرض علي أهل العراق وأمر بطلبه فهرب وقال\n(أخوف بالحجاج حتى كأنما ... يحرك عظم في الفؤاد مهيض)\n(ودون يد الحجاج من أن تنالني ... بساط لأيدي الناعجات عريض)\n(مهامه أشباه كأن سرابها ... ملاء بأيدي الغاسلات رحيض)\nجد الحجاج في طلبه حتى ضاقت عليه الأرض فأتى واسطا وتنكر وأخذ رقعة بيده ودخل إلى الحجاج في أصحاب المظالم فلما وقف بين يديه أنشأ يقول\n(هأنذا ضاقت بي الأرض كلها ... إليك وقد جولت كل مكان)\n(فلو كنت في ثهلان أو شعبتي أجا ... لخلتك إلا أن تصد تراني)\nقال له الحجاج العديل أنت قال نعم أيها الأمير فلوى قضيب خيزران كان في يده في عنقه وجعل يقوله إيه\n(بساط لأيدي الناعجات عريض ... )\nفقال لا بساط إلا عفوك قال اذهب حيث شئت أخبرني محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم بن فراس قال حدثنا العمري عن الهيثم بن عدي عن ابن عياش\nقال كان حوشب بن يزيد بن الحويرث بن رويم الشيباني وعكرمة بن ربعي البكري يتنازعان الشرف ويتباريان في إطعام الطعام ونحر الجزر في عسكر مصعب وكاد حوشب يغلب عكرمة لسعة يده\nقال وقدم عبد العزيز بن يسار مولى بجير قال وهو زوج أم شعبة الفقيه بسفائن دقيق فأتاه عكرمة فقال له الله الله في قد كاد حوشب أن يستعليني ويغلبني بماله فبعني هذا الدقيق بتأخير ولك فيه مثل ثمنه ربحا فقال خذه وأعطاه إياه فدفعه إلى قومه وفرقه بينهم وأمرهم بعجنه كله فعجنوه كله ثم جاء بالعجين كله فجمعه في هوة عظيمة وأمر به فغطي بالحشيش وجاء برمكة فقربوها إلى فرس حوشب حتى طلبها وأفلت ثم ركضوها بين يديه وهو يتبعها حتى ألقوها في ذلك العجين وتبعها الفرس حتى تورطا في العجين وبقيا فيه جميعا وخرج قوم عكرمة يصيحون في العسكر يا معشر المسلمين أدركوا فرس حوشب فقد غرق في خميرة عكرمة فخرج الناس تعجبا من ذلك أن تكون خميرة يغرق فيها فرس فلم يبق في العسكر أحد إلا ركب ينظر وجاؤوا إلى الفرس وهو غريق في العجين ما يبين منه إلا رأسه وعنقه فما أخرج إلا بالعمد والحبال وغلب عليه عكرمة وافتضح حوشب فقال العديل بن الفرخ يمدحهما ويفخر بهما\n(وعكرمة الفياض فينا وحوشب ... هما فتيا الناس اللذا لم يغمرا)\n(هما فتيا الناس اللذا لم ينلهما ... رئيس ولا الأقيال من آل حميرا)\nال وفي حوشب يقول الشاعر\n(وأجود بالمال من حاتم ... وأنحر للجزر من حوشب)","topic":"أخبار العديل ونسبه","topicNo":290,"sp":4,"spl":"الفرزدق يقول العديل شاعر بكر بن وائل — غزله بين السهل والفحل","tags":["الحب والغزل","المديح"],"loc":3772,"partialRef":{"sid":"b290-2","gi":5,"vi":1,"side":1},"partial":1},
{"id":"b290-10","bab":"الجزء 22","sec":"غزله بين السهل والفحل","page":"ج22 ص344","text":"أخبرني محمد بن يونس الكاتب قال حدثنا أحمد بن عبيد عن الأصمعي قال دخلت على الرشيد يوما وهو محموم فقال أنشدني يا أصمعي شعرا مليحا فقلت أرصينا فحلا تريده يا أمير المؤمنين أم شجيا سهلا فقال بل غزلا بين الفحل والسهل فأنشدته للعديل بن الفرخ العجلي\n(صحا عن طلاب البيض قبل مشيبه ... وراجع غض الطرف فهو خفيض)\n(كأني لم أرع الصبا ويروقني ... من الحي أحوى المقلتين غضيض)\n(دعاني له يوما هوى فأجابه ... فؤاد إذا يلقى المراض مريض)\n(لمستأنسات بالحديث كأنه ... تهلل غر برقهن وميض)\nفقال لي أعدها فما زلت أكررها عليه حتى حفظها","topic":"أخبار العديل ونسبه","topicNo":290,"sp":4,"spl":"الفرزدق يقول العديل شاعر بكر بن وائل — غزله بين السهل والفحل","tags":["الرواية والكتابة"],"loc":3773},
{"id":"b290-11","bab":"الجزء 22","sec":"مات فرثاه الفرزدق","page":"ج22 ص345","text":"أخبرني أبو الحسن الأسدي قال حدثني الرياشي عن محمد بن سلام قال قدم العديل بن الفرخ البصرة ومدح مالك بن مسمع الجحدري\nفوصله فأقام بالبصرة واستطابها وكان مقيما عند مالك فلم يزل بها إلى أن مات وكان ينادم الفرزدق ويصطحبان فقال الفرزدق يرثيه\n(وما ولدت مثل العديل حليلة ... قديما ولا مستحدثات الحلائل)\n(وما زال مذ شدت يداه إزاره ... به تفتح الأبواب بكر بن وائل)\n\n(إني بدهماء عز ما أجد ... عاودني من حبابها زؤد)\n(عاودني حبها وقد شحطت ... صرف نواها فإنني كمد)\nوله عز ما أجد أي شد ما أجد وحبابها حبها وهو واحد ليس بجمع والزؤد الفزع والذعر وصرف نواها الوجه الذي تصرف إليه قصدها إذا نأت والكمد شدة الحزن الشعر لصخر الغي الهذلي هكذا ذكر الأصمعي وأبو عمرو الشيباني وذكر إسحاق عن أبي عبيدة أنه رأى جماعة من شعراء هذيل يختلفون في هذه القصيدة فيرويها بعضهم لصخر الغي ويرويها بعضهم لعمرو ذي الكلب وأن الهيثم بن عدي حدثه عن حماد الراوية أنها لعمرو ذي الكلب","topic":"أخبار العديل ونسبه","topicNo":290,"sp":5,"spl":"مات فرثاه الفرزدق","tags":["المديح","الموت"],"song":1,"loc":3774},
{"id":"b291-2","bab":"الجزء 22","sec":"أخبار صخر الغي ونسبه — مناسبة قصيدة له","page":"ج22 ص346 – ج22 ص347","text":"هو صخر بن عبد الله الخيثمي أحد بني خيثم بن عمرو بن الحارث بن تميم بن سعد بن هذيل هذا أكثر ما وجدته من نسبه ولقب بصخر الغي لخلاعته وشدة بأسه وكثرة شره\nفمن روى هذه القصيدة له ذكر أن السبب فيها أن جارا لبني خناعة بن سعد بن هذيل من بني الرمداء كان جاورهم رجل من بني مزينة وقيل إنه كان جارا لأبي المثلم الشاعر وهو أخوهم فقتله صخر الغي فمشى أبو المثلم إلى قومه وبعثهم على مطالبته بدم جارهم المزني والإدراك بثأره فبلغ ذلك صخرا فقال هذه القصيدة يذكر أبا المثلم وما فعله فأولها البيتان اللذان فيهما الغناء وفيها يقول\n(ولست عبدا للموعدين ولا ... أقبل ضيما أتى به أحد)\n(جاءت كبير كيما أخفرها ... والقوم صيد كأنهم رمدوا)\n(في المزني الذي حششت به ... مال ضريك تلاده نكد)\n(إن أمتسكه فبالفداء وإن ... أقتل بسيفي فإنه قود)\nولصخر وأبي المثلم في هذا مناقضات وقصائد قالاها وأجاب كل واحد منهما صاحبه يطول ذكرها وليس من جنس هذا الكتاب","topic":"أخبار صخر الغي ونسبه","topicNo":291,"sp":0,"spl":"أخبار صخر الغي ونسبه — مناسبة قصيدة له — كان أخوه الاعلم أحد صعاليك هذيل","tags":[],"loc":3775},
{"id":"b291-3","bab":"الجزء 22","sec":"كان أخوه الاعلم أحد صعاليك هذيل","page":"ج22 ص348","text":"وحكى الاثرم عن أبي عبيدة أنه حدث عن عبد الله بن إبراهيم الجمحي قال كان الأعلم أخو صخر الغي أحد صعاليك هذيل وكان يعدو على رجليه عدوا لا يلحق واسمه حبيب بن عبد الله فخرج هو وأخواه صخر وصخير حتى أصبحوا تحت جبل يقال له السطاع في يوم من أيام الصيف شديد الحر وهو متأبط قربة لهم فيها ماء فأيبستها السموم وعطشوا حتى لم يكادوا أن يبصروا من العطش فقال الأعلم لصاحبيه أشرب من القربة لعلي أن أرد الماء فأروى منه وانتظراني مكانكما وكانت بنو عدي بن الديل على ذلك الماء وهو ماء الأطواء يتفيؤون بنخل متأخر عن الماء قدر رمية سهم فأقبل يمشي متلثما وقد وضع سيفه وقوسه ونبله فيما بينه وبين صاحبه فلما برز للقوم مشى رويدا مشتملا فقال بعض القوم من ترون الرجل فقالوا نراه بعض بني مدلج بن مرة ثم قالوا لبعضهم الق الفتى فاعرفه فقال لهم ما تريدون بذلك الرجل هو آتيكم إذا شرب فدعوه فليس بمفيتنا فأقبل يمشي حتى رمى بأرسه في الحوض مدبرا عنهم بوجهه فلما روي أفرغ على رأسه من الماء\nثم أعاد نقابه ورجع في طريقه رويدا فصاح القوم بعبد لهم كان على الماء هل عرفت الرجل الذي صدر قال لا فقالوا فهل رأيت وجهه قال نعم هو مشقوق الشفة فقالوا هذا الأعلم وقد صار بينه وبين الماء مقدار رمية سهم آخر فعدوا في أثره وفيهم رجل يقال له جذيمة ليس في القوم مثله عدوا فأغروه به وطردوه فأعجزهم ومر على سيفه وقوسه ونبله فأخذه ثم مر بصاحبيه فصاح بهما فضبرا معه فأعجزوهم فقال الأعلم في ذلك\n(لما رأيت القوم بالعلياء ... دون قدى المناصب)\n(وفريت من فزع فلا ... أرمى ولا ودعت صاحب)\n(يغرون صاحبهم بنا ... جهدا وأغري غير كاذب)\n(أغري أخي صخرا ليعجزهم ... ومدوا بالحلائب)\n(وخشيت وقع ضريبة ... قد جربت كل التجارب)\n(فأكون صيدهم بها ... وأصير للضبع السواغب)\n(جزرا وللطير المربة ... والذئاب وللثعالب)\nوهي قصيدة طويلة\nصوت صخر يرثي أخاه\nوقالوا جميعا خرج صخر الغي وأخوه أبو عمرو في غزاة لهما فباتا في أرض رملة فنهشت أخاه أبا عمرو حية فمات فقال يرثيه\n(لعمر أبي عمرو لقد ساقه المنا ... إلى جدث يوزى له بالأهاضب)\n(لحية جحر في وجار مقيمة ... تنمى بها سوق المنا والجوالب)\n(أخي لا أخا لي بعده سبقت به ... منيته جمع الرقى والطبائب)\n(وذلك مما يحدث الدهر إنه ... له كل مطلوب حثيث وطالب)\nوزى له يمنى له والإزاء مهراق الدلو والأهاضب الجبال وقال الأثرم عن أبي عبيدة خرج صخر الغي في طائفة من قومه يقدمها خوفا من أبي المثلم فأغار على بني المصطلق من خزاعة فانتظر بقية أصحابه ونذرت به بنو المصطلق فأحاطوا به فقال\n(لو أن أصحابي بنو معاويه ... أهل جنوب النخلة الشاميه)\n(ورهط دهمان ورهط عاديه ... ما تركوني للذئاب العاويه)\nجعل يرميهم ويرتجز ويقول\n(لو أن أصحابي بنو خناعه ... أهل الندى والمجد والبراعه)\n(تحت جلود البقر القراعه ... لمنعوا من هذه اليراعه)","topic":"أخبار صخر الغي ونسبه","topicNo":291,"sp":0,"spl":"أخبار صخر الغي ونسبه — مناسبة قصيدة له — كان أخوه الاعلم أحد صعاليك هذيل","tags":["الموت","الرواية والكتابة"],"loc":3776},
{"id":"b291-4","bab":"الجزء 22","sec":"شعره وهو يقاتل حتى قتل","page":"ج22 ص351","text":"وقال أيضا وهو يقاتلهم\n(لو أني حولي من قريم رجلا ... بيض الوجوه يحملون النبلا)\n(لمنعوني نجدة ورسلا ... سفع الوجوه لم يكونوا عزلا)\nقول منعوني بنجدة وشدة وعلى رسلهم بأهون سعي قال فلم يزل يقاتلهم حتى قتلوه وبلغ ذلك أبا المثلم فقال يرثيه\n(لو كان للدهر مال عند متلده ... لكان للدهر صخر مال قنيان)\n(آبي الهضيمة آت بالعظيمة متلاف ... الكريمة لا سقط ولا واني)\n(حامي الحقيقة نسال الوديقة معتاق ... الوسيقة جلد غير ثنيان)\n(رقاء مرقبة مناع مغلبة ... ركاب سلهبة قطاع أقران)\n(هباط أودية شهاد أندية ... حمال ألوية سرحان فتيان)\nلسرحان الأسد في لغة هذيل وفي كلام غيرهم الذئب\n(يحمي الصحاب إذا جد الضراب ويكفي ... القائلين إذا ما كبل العاني)\n(فيترك القرن مصفرا أنامله ... كأن في ريطتيه نضخ إرقان)\nلإرقان اليرقان يعني صفرته\n(يعطيك ما لا تكاد النفس تسلمه ... من التلاد وهوب غير منان)","topic":"أخبار صخر الغي ونسبه","topicNo":291,"sp":1,"spl":"شعره وهو يقاتل حتى قتل","tags":[],"loc":3777},
{"id":"b292-2","bab":"الجزء 22","sec":"نسب عمرو ذي الكلب وأخباره — خبره مع أم جليحة","page":"ج22 ص352 – ج22 ص353","text":"هو عمرو بن العجلان بن عامر بن برد بن منبه أحد بني كاهل بن لحيان بن هذيل قال السكري عن محمد بن حبيب عن ابن الأعرابي إنما سمي ذا الكلب لأنه كان له كلب لا يفارقه\nوعن الأثرم عن أبي عبيدة أنه قال لم يكن له كلب لا يفارقه إنما خرج غازيا ومعه كلب يصطاد به فقال له أصحابه يا ذا الكلب فثبتت عليه قال ومن الناس من يقول له عمرو الكلب ولا يقول فيه ذو قال وكان يغزو بني فهم غزوا متصلا فنام ليلة في بعض غزواته فوثب عليه نمران فأكلاه فادعت فهم قتله هكذا في هذه الرواية\nوقد أخبرني علي بن سليمان الأخفش قال حدثنا أبو سعيد السكري عن محمد بن حبيب عن ابن الأعرابي وأبي عبيدة عن ابن الأعرابي عن المفضل وغيرهم من الرواة قالوا\nكان من حديث عمرو ذي الكلب الهذلي وكان من رجالهم أنه كان قد علق امرأة من فهم يقال لها أم جليحة فأحبها وأحبته وكان أهلها قد وجدوا عليها وعليه وطلبوا دمه إلى أن جاءها عاما من ذلك فنذروا به فخرجوا في أثره وخرج هاربا منهم فتبعوه يومهم ذلك وهم على أثره حتى أمسى وهاجت عليه ريح شديدة في ليلة ظلماء فبينا هو يسير على ظهر الطريق إذ رأى نارا عن يمينه فقال أخطأت والله الطريق وإن النار لعلى الطريق فحار وشك وقصد للنار حتى أتاها وقد كان يصيح فإذا رجل قد أوقد نارا ليس معه أحد فقال له عمرو ذو الكلب من أنت\nقال أنا رجل من عدوان قال فما اسم هذا المكان قال السد فعلم أنه قد هلك وأخطأ والسد شيء لا يجاوز قال ويلك فلم أوقدت فوالله ما تشتوي ولا تصطلي وما أوقدت إلا لمنية عمرو الشقي هل عندك شيء تطعمني\nقال نعم فأخرج له ثمرات قد نقاها في يده فلما رآها قال ثمرات تتبعها عبرات من نساء خفرات ثم قال اسقني قال ماذا ألبنا قال لا ولكن اسقني ماء قراحا فإني مقتول صباحا ثم انطلق فأسند في السد ورأى القوم الذين جاؤوا في طلبه أثره حيث أخطأ فاتبعوه حتى وجدوه فدخل غارا في السد فلما ظهروا للسد علموا أنه في الغار فنادوه فقالوا يا عمرو قال ما تشاؤون قالوا اخرج قال فلم دخلت إذن قالوا بلى فاخرج قال لا أخرج قالوا فأنشدنا قولك\n(ومقعد كربة قد كنت منها ... مكان الإصبعين من القبال)\nقال ها هي ذه أنا فيها قال وعن له رجل من القوم فرماه عمرو فقتله فقالوا أقتلته يا عدو الله فقال أجل ولقد بقيت معي أربعة أسهم كأنها أنياب أم جليحة لا تصلون إلي أو أقتل بكل سهم منها رجلا منكم فقالوا لعبدهم يا أبا نجاد ادخل عليه وأنت حر فتهيأ للدخول أبو نجاد عليه فقال له عمرو ويلك يا أبا نجاد ما ينفعك أن تكون حرا إذا قتلتك فنكص عنه فلما رأوا ذلك صعدوا فنقبوا عليه ثم رموه حتى قتلوه وأخذوا سلبه فرجعوا به إلى أم جليحة وهي تتشوف فلما رأوها قالوا لها يا أم جليحة ما رأيك في عمرو قالت رأيي والله أنكم طلبتموه سريعا ووجدتموه منيعا ووضعتموه صريعا فقالوا والله لقد قتلناه فقالت والله ما أراكم فعلتم ولئن كنتم فعلتم لرب ثدي منكم قد افترشه وضب قد احترشه فطرحوا إليها ثيابه فأخذتها فشمتها فقالت ريح عطر وثوب عمرو أما والله ما وجدتموه ذا حجزة جافية ولا عانة وافية ولا ضالة كافية","topic":"نسب عمرو ذي الكلب وأخباره","topicNo":292,"sp":0,"spl":"نسب عمرو ذي الكلب وأخباره — خبره مع أم جليحة — اخته ريطة ترثيه","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3778},
{"id":"b292-3","bab":"الجزء 22","sec":"اخته ريطة ترثيه","page":"ج22 ص355","text":"وقالت ريطة أخت عمرو ذي الكلب ترثيه\n(كل امرئ لمحال الدهر مكروب ... وكل من غالب الايام مغلوب)\n(وكل حي وإن غزوا وإن سلموا ... يوما طريقهم في الشر دعبوب)\n(أبلغ هذيلا وأبلغ من يبلغها ... عني رسولا وبعض القول تكذيب)\n(بأن ذا الكلب عمرا خيرهم نسبا ... ببطن شريان يعوي حوله الذيب)\n(الطاعن الطعنة النجلاء يتبعها ... مثعنجر من نجيع الجوف أسكوب)\n(والتارك القرن مصفرا أنامله ... كأنة من نقيع الورس مخضوب)\n(تمشي النسور إليه وهي لاهية ... مشي العذارى عليهن الجلابيب)\n(والمخرج العاتق العذراء مذعنة ... في السبي ينفح من أردانها الطيب)\n\n(يا دار عمرة من محتلها الجرعا ... هاجت لي الهم والأحزان والوجعا)\n(أرى بعيني إذا مالت حمولتهم ... بطن السلوطح لا ينظرون من تبعا)\n(طورا أراهم وطورا لا أبينهم ... إذا ترفع حدج ساعة لمعا)\nلشعر للقيط الأيادي ينذر قومه قصد كسرى لهم والغناء لكردم بن معبد هزج بالبنصر من روايتي حبش والهشامي","topic":"نسب عمرو ذي الكلب وأخباره","topicNo":292,"sp":0,"spl":"نسب عمرو ذي الكلب وأخباره — خبره مع أم جليحة — اخته ريطة ترثيه","tags":[],"song":1,"loc":3779},
{"id":"b293-2","bab":"الجزء 22","sec":"خبر لقيط ونسبه والسبب في قوله الشعر — سبب غزو كسرى لإياد","page":"ج22 ص356 – ج22 ص357","text":"هو لقيط بن يعمر شاعر جاهلي قديم مقل ليس يعرف له شعر غير هذه القصيدة وقطع من الشعر لطاف متفرقة\nأخبرني بخبر هذا الشعر عمي قال حدثني القاسم بن محمد الأنباري قال حدثني أحمد بن عبيد قال حدثني الكلبي عن الشرقي بن القطامي قال كان سبب غزو كسرى إيادا أن بلادهم أجدبت فارتحلوا حتى نزلوا بسنداد ونواحيها فأقاموا بها دهرا حتى أخصبوا وكثروا وكانوا يعبدون صنما يقال له ذو الكعبين وعبدته بكر بن وائل من بعدهم فانتشروا ما بين سنداد إلى كاظمة والى بارق والخورنق واستطالوا على الفرات حتى خالطوا أرض الجزيرة ولم يزالوا يغيرون على ما يليهم من أرض السواد ويغزون ملوك آل نصر حتى أصابوا امرأة من أشراف العجم كانت\nعروسا قد هديت إلى زوجها فولي ذلك منها سفهاؤهم وأحداثهم فسار إليهم من كان يليهم من الأعاجم فانحازت إياد إلى العراق وجعلوا يعبرون إبلهم في القراقير ويقطعون بها الفرات وجعل راجزهم يقول\n(بئس مناخ الحلقات الدهم ... في ساحة القرقور وسط اليم)\nعبروا الفرات وتبعهم الأعاجم فقالت كاهنة من إياد تسجع لهم\n(إن يقتلوا منكم غلاما سلما ... أو يأخذوا ذاك شيخا هما)\n(تخضبوا نحورهم دما ... وترووا منهم سيوفا ظما)\nخرج غلام منهم يقال له ثواب بن محجن بإبل لأبيه فلقيته الأعاجم فقتلوه وأخذوا الإبل ولقيتهم إياد في آخر النهار فهزمت الأعاجم قال وحدثني بعض أهل العلم أن إيادا بيتت ذلك الجمع حين عبروا شط الفرات الغربي فلم يفلت منهم إلا القليل وجمعوا به جماجمهم وأجسادهم فكانت كالتل العظيم و كان إلى جانبهم دير فسمي دير الجماجم و بلغ كسرى الخبر فبعث مالك بن حارثة أحد بني كعب بن زهير بن جشم في آثارهم ووجه معه أربعة آلاف من الأساورة فكتب إليهم لقيط\n(يا دار عمرة من محتلها الجزعا ... هاجت لي الهم والأحزان والوجعا)\nوفيها يقول قال الشرقي بن القطامي أنشدنيها أبو حمزة الثمالي\n(يا قام لا تأمنوا أن كنتم غيرا ... على نسائكم كسرى وما جمعا)\n(هو الجلاء الذي تبقى مذلته ... إن طار طائركم يوما وإن وقعا)\n(هو الفناء الذي يجتث أصلكم ... فمن رأى ذا رأيا ومن سمعا)\n(فقلدوا أمركم لله دركم ... رحب الذراع بأمر الحرب مضطلعا)\n(لا مترفا إن رخاء العيش ساعده ... ولا إذا حل مكروه به خشعا)\n(لا يطعم النوم إلا ريث يبعثه ... هم يكاد حشاه يقطع الضلعا)\n(مسهد النوم تعنيه ثغوركم ... يروم منها إلى الأعداء مطلعا)\n(ما انفك يحلب هذا الدهر أشطره ... يكون متبعا طورا ومتبعا)\n(فليس يشغله مال يثمره ... عنكم ولا ولد يبغي له الرفعا)\n(حتى استمرت على شزر مريرته ... مستحكم السن لا قحما ولا ضرعا)\n(كمالك بن قنان أو كصاحبه ... زيد القنا حين لاقى الحارثين معا)\n(إذ عابه عائب يوما فقال له ... دمث لجنبك قبل الليل مضطجعا)\n(فساوروه فألفوه أخا علل ... في الحرب يختتل الرئبال والسبعا)\n(عبل الذراع أبيا ذا مزابنة ... في الحرب لا عاجزا نكسا ولا ورعا)\n(مستنجدا يتحدى الناس كلهم ... لو صارعوه جميعا في الورى صرعا)\n(هذا كتابي إليكم و النذير لكم ... لمن رأى الرأي بالإبرام قد نصعا)\n(وقد بذلت لكم نصحي بلا دخل ... فاسيقظوا إن خير العلم ما نفعا)\nوجعل عنوان الكتاب\n(سلام في الصحيفة من لقيط ... إلى من بالجزيرة من إياد)\n(بأن الليث كسرى قد أتاكم ... فلا يحبسكم سوق النقاد)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":0,"spl":"خبر لقيط ونسبه والسبب في قوله الشعر — سبب غزو كسرى لإياد","tags":["الجواري والنساء"],"loc":3780},
{"id":"b293-3","bab":"الجزء 22","sec":"وقعة مرج الاكم","page":"ج22 ص360","text":"قال وسار مالك بن حارثة التغلبي بالأعاجم حتى لقي إيادا وهم غارون لم يتلفتوا إلى قول لقيط وتحذيره إياهم ثقة بإن كسرى لا يقدم عليهم فلقيهم بالجزيرة في موضع يقال له مرج الأكم فاقتتلوا قتالا شديدا فظفر بهم وهزمهم وأنفذ ما كانوا أصابوا من الأعاجم يوم الفرات ولحقت إياد بأطراف الشأم ولم تتوسطها خوفا من غسان يوم الحارثين ولاجتماع قضاعة وغسان في بلد خوفا من أن يصيروا يدا واحدة عليهم فأقاموا حتى أمنوا ثم إنهم تطرفوهم إلى أن لحقوا بقومهم ببلد الروم بناحية أنقرة ففي ذلك يقول الشاعر\n(حلوا بأنقرة يسيل عليهم ... ماء الفرات يجيء من أطواد)\n\n(اللبين يا ليلى جمالك ترحل ... ليقطع منا البين ما كان يوصل)\n(تعللنا بالوعد ثمت تلتوي ... بموعودها حتى يموت المعلل)\n(ألم تر أن الحبل أصبح واهنا ... وأخلف من ليلى الذي كنت آمل)\n(فلا الحبل من ليلى يؤاتيك وصله ... ولا أنت تنهى القلب عناه فيذهل)\nروضه من الطويل الشعر لنصيب الأصغر مولى المهدي و الغناء ليحيى المكي خفيف رمل بالبنصر وكذا نسبته تدل عليه وذكر عمرو بن بانة في نسخته أن خفيف الرمل لمالك وأنه بالوسطى والصحيح أنه لابن المكي","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":1,"spl":"وقعة مرج الاكم — بسم الله الرحمن الرحيم أخبار نصيب الأصغر — مدحه هارون الرشيد","tags":["الحب والغزل"],"song":1,"loc":3781},
{"id":"b293-5","bab":"الجزء 23","sec":"بسم الله الرحمن الرحيم أخبار نصيب الأصغر — مدحه هارون الرشيد","page":"ج22 ص361 – ج23 ص5","text":"نصيب مولى المهدي عبد نشأ باليمامة واشتري للمهدي في حياة المنصور فلما سمع شعره قال والله ما هو بدون نصيب مولى بني مروان فأعتقه وزوجة أمة له يقال لها جعفرة وكناه أبا الحجناء وأقطعه ضيعة بالسواد وعمر بعده\nوهذه القصيدة يمدح بها هارون الرشيد وهي من جيد شعره وفيها يقول\n(خليلي إني ما يزال يشوقني ... قطين الحمى والظاعن المتحمل)\n(فأقسمت لا أنسى ليالي منعج ... ولا مأسل إذ منزل الحي مأسل)\n(أمن أجل آيات ورسم كأنه ... بقية وحي أو رداء مسلسل)\n(جرى الدمع من عينيك حتى كأنه ... تحدر در أو جمان مفصل)\n(فيا أيها الزنجي مالك والصبا ... أفق عن طلاب البيض إن كنت تعقل)\n(فمثلك من أحبوشة الزنج قطعت ... وسائل أسباب بها يتوسل)\n(قصدنا أمير المؤمنين ودونه ... مهامه موماة من الأرض مجهل)\n(على أرحبيات طوى السير فانطوت ... شمائلها مما تحل وترحل)\n(إلى ملك صلت الجبين كأنه ... صفيحة مسنون جلا عنه صيقل)\n(إذا أنبلج البابان والستر دونه ... بدا مثل ما يبدو الأغر المحجل)\n(شريكان فينا منه عين بصيرة ... كلوء وقلب حافظ ليس يغفل)\n(فما فات عينيه وعاه بقلبه ... فآخر ما يرعى سواء وأول)\n(وما نازعت فينا أمورك هفوة ... ولا خطلة في الرأي والرأي يخطل)\n(إذا اشتبهت أعناقه بينت له ... معارف في أعجازه وهو مقبل)\n(لئن نال عبد الله قبل خلافة ... لأنت من العهد الذي نلت أفضل)\n(وما زادك العهد الذي نلت بسطة ... ولكن بتقوى الله أنت مسربل)\n(ورثت رسول الله عضوا ومفصلا ... وذا من رسول الله عضو ومفصل)\n(إذا ما دهتنا من زمان ملمة ... فليس لنا إلا عليك المعول)\n(على ثقة منا تحن قلوبنا ... إليك كما كنا أباك نؤمل)\nهي قصيدة طويلة هذا مختار من جميعها","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":1,"spl":"وقعة مرج الاكم — بسم الله الرحمن الرحيم أخبار نصيب الأصغر — مدحه هارون الرشيد","tags":["المديح"],"loc":3782},
{"id":"b293-6","bab":"الجزء 23","sec":"انفق مال المهدي فأوثقه بالحديد","page":"ج23 ص7","text":"أخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثنا عبد الله بن أبي سعد قال حدثني محمد بن عبد الله بن مالك قال حدثني أبي\nقال وجه المهدي نصيبا الشاعر مولاه إلى اليمين في شراء إبل مهرية ووجه معه رجلا من الشيعة وكتب معه إلى عامله على اليمن بعشرين ألف دينار\nقال فمد أبو الحجناء يده في الدنانير ينفقها في الأكل والشرب وشراء الجواري والتزويج فكتب الشيعي بخبره إلى المهدي فكتب المهدي في حمله موثقا في الحديد فلما دخل على المهدي أنشده شعره وقال\n(تأوبني ثقل من الهم موجع ... فأرق عيني والخليون هجع)\n(هموم توالت لو أطاف يسيرها ... بسلمى لظلت شمها تتصدع)\n(ولكنها نيطت فناء بحملها ... جهير المنايا حائن النفس مجزع)\n(وعادت بلاد الله ظلماء حندسا ... فخلت دجى ظلمائها لا تقشع)\nوهي قصيدة طويلة يقول فيها\n(إليك أمير المؤمين ولم أجد ... سواك مجيرا منك يدني ويمنع)\n(تلمست هل من شافع لي فلم أجد ... سوى رحمة أعطاكها الله تشفع)\n(لئن جلت الأجرام مني وأفظعت ... لعفوك عن جرمي أجل وأوسع)\n(لئن لم تسعني يابن عم محمد ... لما عجزت عني وسائل أربع)\n(طبعت عليها صبغة ثم لم تزل ... على صالح الأخلاق والدين تطبع)\n(تغابيك عن ذي الذنب ترجو صلاحه ... وأنت ترى ما كان يأتي ويصنع)\n(وعفوك عمن لو تكون جريمة ... لطارت به في الجو نكباء زعزع)\n(وأنك لا تنفك تنعش عاثرا ... ولم تعترضه حين يكبوا ويخمع)\n(وحلمك عن ذي الجهل من بعدما جرى ... به عنق من طائش الجهل أشنع)\n(ففيهن لي إما شفعن منافع ... وفي الأربع الأولى إليهن أفزع)\n(مناصحتي بالفعل إن كنت نائيا ... إذا كان دان منك بالقول يخدع)\n(وثانية ظني بك الخير غائبا ... وإن قلت عبد ظاهر الغش مسبع)\n(وثالثة أني على ما هويته ... وإن كثر الأعداء في وشنعوا)\n(ورابعة إليك يسوقني ... ولائي فمولاك الذي لا يضيع)\n(وإني لمولاك الذي إن جفوته ... أتى مستكينا راهبا يتضرع)\n(وإني لمولاك الضعيف فأعفني ... فإني لعفو منك أهل وموضع)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":2,"spl":"انفق مال المهدي فأوثقه بالحديد — رأته ابنته مقيدا فبكت فأنشد","tags":["الجواري والنساء"],"loc":3783},
{"id":"b293-7","bab":"الجزء 23","sec":"المهدي يقبل شفاعته ويزوجه","page":"ج23 ص9","text":"فقطع المهدي عليه الإنشاد ثم قال له ومن أعتقك يابن السوداء فأومأ بيده إلى الهادي وقال ألأمير موسى يا أمير المؤمنين فقال المهدي لموسى أعتقته يا بني قال نعم يا أمير المؤمنين فأمضى المهدي ذلك وأمر بحديده ففك عنه وخلع عليه عدة من الخلع الوشي والخز والسواد والبياض ووصله بألفي دينار وأمر له بجارية يقال لها جعفرة جميلة فائقة من روقة الرقيق فقال له سالم قيم الرقيق لا أدفعها إليك أو تعطيني ألف درهم فقال قصيدته\n(أاذن الحي فانصاعوا بترحال ... فهاج بينهم شوقي وبلبالي)\nقام بها بين يدي المهدي فلما قال\n(ما زلت تبذل لي الأموال مجتهدا ... حتى لأصبحت ذا أهل وذا مال)\n(زوجتني يابن خير الناس جارية ... ما كان أمثالها يهدى لأمثالي)\n(زوجتني بضة بيضاء ناعمة ... كأنها درة في كف لآل)\n(حتى توهمت أن الله عجلها ... يابن الخلائف لي من خير أعمالي)\n(فسالني سالم ألفا فقلت له ... أني لي الألف يا قبحت من سال)\nأراد من سائل كما قالوا شاكي السلاح وشائك\n(هيهات ألفك إلا أن أجيء بها ... من فضل مولى لطيف المن مفضال)\nأمر له المهدي بألف دينار ولسالم بألف درهم","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":2,"spl":"انفق مال المهدي فأوثقه بالحديد — رأته ابنته مقيدا فبكت فأنشد","tags":["الجواري والنساء"],"loc":3784},
{"id":"b293-8","bab":"الجزء 23","sec":"رأته ابنته مقيدا فبكت فأنشد","page":"ج23 ص10","text":"قال ابن أبي سعد وحدثني غير محمد بن عبد الله أنه حبس باليمن مدة طويلة ثم أشخص إلى المهدي فقال وهو في الحبس ودخلت إليه ابنته حجناء فلما رأت قيوده بكت فقال\n(لقد أصبحت حجناء تبكي لوالد ... بدرة عين قل عنه غناؤها)\n(أحجناء صبرا كل نفس رهينة ... بموت ومكتوب عليها بلاؤها)\n(أحجناء أسباب المنايا بمرصد ... فإلا يعاجل غدوها فمساؤها)\n(أحجناء إن أفلت من السجن تلقني ... حتوف منايا لا يرد قضاؤها)\n(أحجناء إن أضحى أبوك ودلوه ... تعرت عرا منها ورث رشاؤها)\n(لقد كان يدلي في رجال كثيرة ... فيمتح ملأى وهي صفر دلاؤها)\n(أحجناء إن يصبح أبوك ونفسه ... قليل تمنيها قصير عزاؤها)\n(لقد كان في دنيا تفيأ ظلها ... عليه ومجلوب إليه بهاؤها)\nال ابن أبي سعد ولما دخل نصيب على المهدي مقيدا رفده ثمامة بن الوليد العبسي عنده واستعطفه له وسوغ عذره عنده ولم يزل يرفق به حتى أمر بإطلاقه وكان نصيب في متقدم الأيام منقطعا إلى أخيه شيبة فقال فيه","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":2,"spl":"انفق مال المهدي فأوثقه بالحديد — رأته ابنته مقيدا فبكت فأنشد","tags":["الحب والغزل","الجواري والنساء"],"loc":3785},
{"id":"b293-9","bab":"الجزء 23","sec":"شعره في مدح ثمامة العبسي","page":"ج23 ص11","text":"(أثمام إنك قد فككت ثماما ... حلقا برين من النصيب عظاما)\n(حلقا توسطها العمود فلزها ... لولا ثمامة والإله لداما)\n(الله أنقذني به من هوة ... تيهاء مهلكة تكون رجاما)\n(فلأشكرنك يا ثمامة ما جرت ... فرق السحاب كنهورا وركاما)\n(ولاشكرنك يا ثمامة ما دعت ... ورق الحمام على الغصون حماما)\n(وخلفت شيبة في المقام ولا أرى ... كمقام شيبة في الرجال مقاما)\n(أغنى إذا التمس الرجال غناءه ... في كل نازلة تكون غراما)\n(وأعم منفعة وأكرم حائطا ... تهدي إليه تحية وسلاما)\n(لا يبعدن ابن الوليد فإنه ... قد نال من كل الأمور جساما)\n(لو من سوى رهط النبي خليفة ... يدعى لكان خليفة وإماما)\nال ابن أبي سعد ودخل نصيب على ثمامة بعد وفاة أخيه شيبة وهو يفرق خيله على الناس فأمر له بفرس منها فأبى أن يقبله وبكى ثم قال\n(يا شيبة الخير إما كنت لي شجنا ... آليت بعدك لا أبكي على شجن)\n(أضحت جياد أبي القعقاع مقسمة ... في الأقربين بلا من ولا ثمن)\n(ورثتهم فتعزوا عنك إذ ورثوا ... وما ورثتك غير الهم والحزن)\nجعل ثمامة ومن عنده حاضر من أهله وإخوانه يبكون وشيبة بن الوليد هذا وأخوه من وجوه قواد المهدي\nوفي شيبة يقول أبو محمد اليزيدي يهجوه وكان عارضه في شيء من النحو بحضرة المهدي\n(عش بجد فلن يضرك نوك ... إنما عيش من ترى بالجدود)\n(عش بجد وكن هبنقة القيسي ... جهلا أو شيبة بن الوليد)\nخبرنا بذلك محمد بن العباس اليزيدي عن عمه عن أبيه أخبرني عمي قال حدثنا القاسم بن محمد الأنباري قال حدثنا عبد الله بن بشر البجلي عن النضر بن طاهر قال أتى نصيب مولى المهدي عبد الله بن محمد بن الأشعث وهو يتقلد صنعاء للمهدي فمدحه فلم يثبه واستكساه بردا فلم يكسه فقال يهجوه\n(سأكسوك من صنعاء ما قد كسوتني ... مقطعة تبقى على قدم الدهر)\n(إذا طويت كانت فضوحك طيها ... وإن نشرت زادتك خزيا على النشر)\n(أغرك أن بيضت بيت حمامة ... وقلت أنا شبعان منتفج الخصر)\n(لقد كنت في سلح سلحت مخافة ... الحرورية الشارين داع إلى الضر)\n(ولكنه يأبى بك البهر كلما ... جريت مع الجاري وضيق من الصدر)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":3,"spl":"شعره في مدح ثمامة العبسي — تساجل هو والربيع بن عبد الله حول فرس","tags":["المديح"],"loc":3786},
{"id":"b293-10","bab":"الجزء 23","sec":"تساجل هو والربيع بن عبد الله حول فرس","page":"ج23 ص13","text":"قال النضر وكان النصيب ملعونا هجاء فأهدى للربيع بن عبد الله بن الربيع الحارثي فرسا فقبله ثم ندم خوفا من ثقل الثواب فجعل يعيب الفرس ويذكر بطأه وعجزه فبلع ذلك النصيب فقال\n(عبت جوادنا ورغبت عنه ... وما فيه لعمرك من معاب)\n(وما بجوادنا عجز ولكن ... أظنك قد عجزت عن الثواب)\nأجابه الربيع فقال\n(رويدك لا تكن عجلا إلينا ... أتاك بما يسوءك من جواب)\n(وجدت جوادكم فدما بطيئا ... فمالكم لدينا من ثواب)\nلما كان بعد أيام رأى النصيب الفرس تحت الربيع فقال له\n(أخذت مشهرا في كل أرض ... فعجل يا ربيع مشهراتي)\n(يمانية تخيرها يمان ... منمنمة البيوت مقطعات)\n(وجارية أضلت والديها ... مولدة وبيضا وافيات)\n(فعجلها وأنفذها إلينا ... ودعنا من بنات الترهات)\nأجابه الربيع فقال\n(بعثت بمقرف حطم إلينا ... بطيء الحضر ثم تقول هات)\nقال النصيب\n(في سبيل الله أودى فرسي ... ثم عللت بأبيات هزج)\n(كنت أرجو من ربيع فرجا ... فإذا ما عنده لي من فرج)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":3,"spl":"شعره في مدح ثمامة العبسي — تساجل هو والربيع بن عبد الله حول فرس","tags":["الهجاء","الجواري والنساء"],"loc":3787},
{"id":"b293-11","bab":"الجزء 23","sec":"الربيع يجيزه دراهم عوضا عن جارية وعده بها","page":"ج23 ص14","text":"قال ثم خرج الربيع إلى مكة وقد كان وعد النصيب جارية فلم يعطه وأمر ابنه أن يدفع إليه ألفي درهم ففعل فقال النصيب\n(ألا أبلغا عني الربيع رسالة ... ربيع بني عبد المدان الأكارم)\n(أعزت عليك البيض لما أرغتها ... فرغت إلى إعداد بيض الدراهم)\n(الم تر أني غير مستطرف الغنى ... حديث وأني من ذؤابة هاشم)\n(وأنك لم تهبط من الأرض تلعة ... ولا نجوة إلا بعهدي وخاتمي)\nال ثم قدم الربيع فأهدى إلى دفافة بن عبد العزيز العبسي طبق تمر فقال فيه دفافة\n(بعثت بتمر في طبيق كأنما ... بعثت بياقوت توقد كالجمر)\n(فلو أن ما تهدي سنيا قبلته ... ولكنما أهديت مثلك في القدر)\n(كأن الذي أهديت من بعد شقة ... إلينا من الملقى على ضفة الجسر)\nفأجابه الربيع فقال\n(سل الناس إما كنت لا بد طالبا ... إليهم بألا يحملوك على القدر)\n(فإنك إن تحمل على القدر لا تنل ... يد الدهر من بر فتيلا ولا بحر)\n(لقد كنت مني في غدير وروضة ... وفي عسل جم وما شئت من خمر)\n(وما كنت منانا ولكن كفرتني ... وأظهرت لي ذما فأظهرت من عذري)\n(لعمري لقد أعطيت ما لست أهله ... ولا أهل ما يلقى على ضفة الجسر)\nبلغت أبياتهما نصيبا فشمت بالربيع وقال فيه هذه القصيدة\n(رضيتكما حرصا ومنعا ولم يكن ... يهيجكما إلا الحقير من الأمر)\n(متى يجتمع يوما حريص ومانع ... فليس إلى حمد سبيل ولا أجر)\n(أحار بن كعب إن عبسا تغلغلت ... إلى السير من نجران في طلب التمر)\n(فكيف ترى عبسا وعبس حريصة ... إذا طمعت في التمر من ذلك العبر)\n(لقد كنتما في التمر لله أنتما ... شبيهين بالملقى على ضفة الجسر)\nخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد النحوي قال حدثت من غير وجه أن النصيب دخل على الفضل بن يحيى بن خالد مسلما فوجد عنده جماعة من الشعراء قد امتدحوه فهم ينشدونه ويأمر لهم بالجوائز ولم يكن امتدحه ولا أعد له شيئا فلما فرغوا وكان يروي قولا في نفسه استأذن في الإنشاد ثم أنشد قصيدته التي أولها قوله","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":4,"spl":"الربيع يجيزه دراهم عوضا عن جارية وعده بها","tags":[],"loc":3788},
{"id":"b293-12","bab":"الجزء 23","sec":"يشبب بمية ثم يمدح الفضل بن يحيى","page":"ج23 ص15","text":"(طرقتك مية والمزار شطيب ... وتثيبك الهجران وهي قريب)\n(لله مية خلة لو أنها ... تجزي الوداد بودها وتثيب)\n(وكأن مية حين أتلع جيدها ... رشأ أغن من الظباء ربيب)\n(نصفان ما تحت المؤزر عاتك ... دعص أغر وفوق ذاك قضيب)\n(ما للمنازل لا تكاد تجيب ... أنى يجيبك جندل وجبوب)\n(جادتك من سبل الثريا ديمة ... ريا ومن نوء السماك ذنوب)\n(فلقد عهدت بك الحلال بغبطة ... والدهر غض والجناب خصيب)\n(إذ للشباب علي من ورق الصبا ... ظل وإذ غصن الشباب رطيب)\n(طرب الفؤاد ولات حين تطرب ... إن الموكل بالصبا لطروب)\n(وتقول مية ما لمثلك والصبا ... واللون أسود حالك غربيب)\n(شاب الغراب وما أراك تشيب ... وطلابك البيض الحسان عجيب)\n(أعلاقة أسبابهن وإنما ... أفنان رأسك فلفل وزبيب)\n(لا تهزئي مني فربت عائب ... مالا يعيب الناس وهو معيب)\n(ولقد يصاحبني الكرام وطالما ... يسمو إلي السيد المحجوب)\n(وأجر من حلل الملوك طرائفا ... منها علي عصائب وسبيب)\n(وأسالب الحسناء فضل إزارها ... فأصورها وإزارها مسلوب)\n(وأقول منقوح البدي كأنه ... برد تنافسه التجار قشيب)\nقول فيها في مدح الفضل\n(والبرمكي إذا تقارب سنه ... أو باعدته السن فهو نجيب)\n(خرق العطاء إذا استهل عطاؤه ... لا متبع منا ولا محسوب)\n(يا آل برمك ما رأينا مثلكم ... ما منكم إلا أغر وهوب)\n(وإذا بدا الفضل بن يحيى هبته ... لجلاله إن الجليل مهيب)\n(قاد الجياد إلى العدا وكأنها ... رجل الجراد تسوقهن جنوب)\n(قبا تباري في الأعنة شزبا ... تدع الحزون كأنهن سهوب)\n(من كل مضطرب العنان كأنه ... ذئب يبادره الفريسة ذيب)\n(تهوي بكل مغاور عاداته ... صدق اللقاء فما له تكذيب)\n(حتى صبحن الطالبي بعارض ... فيه المنايا تغتدي وتؤوب)\n(خاف ابن عبد الله ما خوفته ... فجفاك ثم أتاك وهو منيب)\n(ولقد رآك الموت إلا أنه ... بالظن يخطئ مرة ويصيب)\n(فرمى إليك بنفسه فنجا بها ... أجل إليه ينتهي مكتوب)\n(فكسوته ثوب الأمان وإنه ... لا حبله واه ولا مقضوب)\n(شمنا إليك مخيلة لا خلبا ... في الشيم إذ بعض البروق خلوب)\n(إنا على ثقة وظن صادق ... مما نؤمله فليس نخيب)\nقال فاستحسنها الفضل وأمر له بثلاثين ألف درهم فقبضها ووثب قائما وهو يقول\n(إني سأمتدح الفضل الذي حنيت ... منا عليه قلوب البر والضلع)\n(جاد الربيع الذي كنا نؤمله ... فكلنا بربيع الفضل مرتبع)\n(كانت تطول بنا في الأرض نجعتنا ... فاليوم عند أبي العباس ننتجع)\n(إن ضاق مذهبنا أو حل ساحتنا ... ضنك وأزم فعند الفضل متسع)\n(ما سلم الله نفس الفضل من تلف ... فما أبالي أقام الناس أم رجعوا)\n(إن يمنعوا ما حوت منا أكفهم ... فلن يضر أبا الحجناء ما منعوا)\n(أو حلؤونا وذادوا عن حياضهم ... يوم الشروع ففي غدرانك الشرع)\n(يا ممسكا بعرا الدنيا إذا خشيت ... منها الزلازل والأمر الذي يقع)\n(قد ضرستك الليالي وهي خالية ... وأحكمتك النهى والأزلم الجذع)\n(فغادرا منك حزنا عن معاسرة ... سهل الجناب يسيرا حين يتبع)\n(لم يفتلتك نقيرا عن مخادعة ... دهي الرجال وللسؤال تنخدع)\n(فأنت مصطلح بالملك تحمله ... كما أبوك بثقل الملك مضطلع)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":5,"spl":"يشبب بمية ثم يمدح الفضل بن يحيى — يمدح زبيدة زوج الرشيد في الحج","tags":["المديح","اللهو والمزاح","السفر والحج"],"loc":3789},
{"id":"b293-13","bab":"الجزء 23","sec":"يمدح زبيدة زوج الرشيد في الحج","page":"ج23 ص18","text":"قال ابن أبي سعد لما حجت أم جعفر زبيدة لقيها النصيب فترجل\nعن فرسه وأنشأ يقول\n(سيستبشر البيت الحرام وزمزم ... بأم ولي العهد زين المواسم)\n(ويعلم من وافى المحصب أنها ... ستحمل ثقل الغرم عن كل غارم)\n(بنو هاشم زين البرية كلها ... وأم ولي العهد زين لهاشم)\n(سليلة أملاك تفرعت الذرى ... كرام لابناء الملوك الأكارم)\n(فوالله ما ندري أفضل حديثها ... عليهم به تسمو ام المتقادم)\n(يظن الذي أعطته منها رغيبة ... يقص عليه الناس أحلام نائم)\nأمرت له بعشرة آلاف درهم وفرس فأعطيه بلا سرج فتلقاها لما رحلت وقال\n(لقد سادت زبيدة كل حي ... وميت ما خلا الملك الهماما)\n(تقى وسماحة وخلوص مجد ... إذا الأنساب أخلصت الكراما)\n(إذا نزلت منازلها قريش ... نزلت الأنف منها والسناما)\n(بلغت من المفاخر كل فخر ... وجاوزت الكلام فلا كلاما)\n(وأعطيت اللهى لكن طرفي ... يريد السرج منكم واللجاما)\nأمرت له بسرج ولجام","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":5,"spl":"يشبب بمية ثم يمدح الفضل بن يحيى — يمدح زبيدة زوج الرشيد في الحج","tags":["السفر والحج"],"loc":3790},
{"id":"b293-14","bab":"الجزء 23","sec":"ابنته الحجناء تمدح المهدي وابنته العباسة","page":"ج23 ص20","text":"قال ابن أبي سعد خرج المهدي يتنزه بعيسى باذ وقدم النصيب ومعه ابنته حجناء فدخل على المهدي وهي معه فأنشدته قولها فيه\n(رب عيش ولذة ونعيم ... وبهاء بمشرق الميدان)\n(بسط الله فيه أبهى بساط ... من بهار وزاهر الحواذان)\n(ثم من ناضر من العشب الأخضر ... يزهو شقائق النعمان)\n(مده الله بالتحاسين حتى ... قصرت دون طوله العينان)\n(خففت حافتاه حيث تناهى ... بخيام في العين كالظلمان)\n(زينوا وسطها بطارمة مثل ... الثريا يحفها النسران)\n(ثم حشو الخيام بيض كأمثال ... المها في صرائم الكثبان)\n(يتجاوبن في غناء شجي ... أسعداني يا نخلتي حلوان)\n(فبقصر السلام من سلم ... الله وأبقى خليفة الرحمن)\n(ولديه الغزلان بل هن أبهى ... عنده من شوادن الغزلان)\n(يا له منظرا ويوم سرور ... شهدت لذتيه كل حصان)\nأمر لها المهدي بعشرة آلاف درهم وله بمثلها قال ثم دخلت\nالحجناء على العباسة بنت المهدي فأنشدتها تقول\n(أتيناك يا عباسة الخير والحيا ... وقد عجفت أدم المهارى وكلت)\n(وما تركت منا السنون بقية ... سوى رمة منا من الجهد رمت)\n(فقال لنا من ينصح الرأي نفسه ... وقد ولت الأموال عنا فقلت)\n(عليك ابنة المهدي عوذي ببابها ... فإن محل الخير في حيث حلت)\nأمرت لها بثلاثة آلاف درهم وكسوة وطيب فقالت\n(أغنيتني يابنة المهدي أي غنى ... بأعجرين كثير فيهما الورق)\nي اغنيتني على عقب ما أغناني أخوك بأعجرين بكيسين\n(من ضرب تسع وتسعين محككة ... مثل المصابيح في الظلماء تأتلق)\n(أما الحسود فقد أمسى تغيظه ... غما وكاد برجع الريق يختنق)\n(وذو الصداقة مسرور بنا فرح ... بادي البشارة ضاح وجهه شرق)\nقال ابن أبي سعد","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":6,"spl":"ابنته الحجناء تمدح المهدي وابنته العباسة — مدحه صديقه إسحاق بن الصباح","tags":["الحب والغزل"],"loc":3791},
{"id":"b293-15","bab":"الجزء 23","sec":"مدحه صديقه إسحاق بن الصباح","page":"ج23 ص21","text":"كان إسحاق بن الصباح الأشعثي صديقا للنصيب وقدم قدمة من الحجاز فدخل على إسحاق وهو يهب لجماعة وردوا عليه برا وتمرا فيحملونه على إبلهم ويمضون فوهب لنصيب جارية حسناء يقال لها مسرورة فأردفها خلفه ومضى وهو يقول\n(إذا احتقبوا برا فأنت حقيبتي ... من البشريات الثقال الحقائب)\n(ظفرت بها من أشعثي مهذب ... أغر طويل الباع جم المواهب)\n(فدى لك يا أسحاق كل مبخل ... ضجور إذا غضت شداد النوائب)\n(إذا ما بخيل القوم غيب ماله ... فمالك عد حاضر غير غائب)\n(إذا اكتسب القوم الثراء فإنما ... ترى الحمد غنما من كريم المكاسب)\nقال فيه أيضا\n(فتى من بني الصباح يهتز للندى ... كما اهتز مسنون الغرار عتيق)\n(فتى لا يذم الضيف والجار رفده ... ولا ي جتويه صاحب ورفيق)\n(أغر لابناء السبيل موارد ... إلى بيته تهديهم وطريق)\n(وإن عد أنساب الملوك وجدته ... إلى نسب يعلوهم ويفوق)\n(فما في بني الصباح إن بعد المدى ... على الناس إلا سابق وعريق)\n(وإني لمن شاحنتم لمشاحن ... وإني لمن صادقتم لصديق)","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":6,"spl":"ابنته الحجناء تمدح المهدي وابنته العباسة — مدحه صديقه إسحاق بن الصباح","tags":["الجواري والنساء","السفر والحج"],"loc":3792},
{"id":"b293-16","bab":"الجزء 23","sec":"زار خزيمة بن خازم ومدحه","page":"ج23 ص22","text":"قال وكان النصيب إذا قدم على المهدي استهداه القواد منه وسألوه أن يأمره بزيارتهم فكان فيمن استزاره خزيمة بن خازم فوصله وحمله وقال فيه\n(وجدتك يا خزيمة أريحيا ... بما تحوي وذا حسب صميم)\n(تميم كان خير بني معد ... وأنت اليوم خير بني تميم)\n(سوى رهط النبي وهم أديم ... وأنت قددت من ذاك الأديم)\nقال فيه أيضا\n(يا أفضل الناس عودا عند معجمه ... إذا تفاضل يوما معجم العود)\n(أني لواحد شعر قد عرفت به ... وذا خزيمة أضحى واحد الجود)\n(إن يعطك اليوم معروفا يعدك غدا ... فأنت في نائل منه وموعود)\n(وقد رأينا تميما غير مكرهة ... ألقت إليك جميعا بالمقاليد)\n(فأنت أكرمها نفسا وأفضلها ... إن الصناديد أبناء الصناديد)\nوقال وكان في غزاة سمالو مع المهدي فوقف به فرسه ومر به جعد مولى عبد الله بن هشام بن عمرو وبين يديه فرس يجنب فقال له قد ترى قيام فرسي تحتي فاردد إلى جنيبك حتى يتروح فرسي ساعة فسكت ولم يجبه فقال فيه\n(أنادي بأعلى الصوت جعدا وقد يرى ... مكاني ولكن لا يجيب ويسمع)\n(ولم يرني أهلا لحسن إجابة ... ولا سوئها إني إلى الله أرجع)\n(فلو أنني جازيت جعدا بفعله ... لقد لاح لي فيه من الشعر موضع)\n(ولكنني جافيت عنه لغيره ... بحسن الذي يأتي إلي ويصنع)\n(رأيتك لم تحفظ قرابة بيننا ... وما زالت القربى لدى الناس تنفع)\nال وسأل عبيد الله بن يحيى بن سليمان مركبا فأعطاه إياه وجعل معه شريكا له فيه فقال\n(لقد مدحت عبيدا إذ طمعت به ... وقد تملقته لو ينفع الملق)\n(فعاد يسأل ما أصبحت سائله ... فكلنا سائل في الحرص متفق)\n(أحين سار مديحي فيكم طرقا ... وحيث غنت به الركبان والرفق)\n(قطعت حبل رجاء كنت آمله ... فيما لديك فأضحى وهو منحذق)\n(قد كان أورق عودي من أبيك فقد ... لحيت عودي فجف العود والورق)\n(من نازع الكلب عرقا يرتجي شبعا ... كمصطل بحريق وهو يحترق)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال كتب إلي أبو محمد إسحاق بن أبي إبراهيم يقول أنشدت الفضل بن يحيى قول أبي الحجناء نصيب\n(عند الملوك مضرة ومنافع ... وأرى البرامك لا تضر وتنفع)\n(إن العروق إذا استسر بها الثرى ... أشر البنات بها وطاب المزرع)\n(فإذا نكرت من امرئ أعراقه ... وقديمه فانظر إلى ما يصنع)\nال فأعجبه الشعر فقال يا أبا محمد كأني والله لم أسمع هذا القول إلا الساعة وما له عندي عيب إلا أني لم أكافئه عليه قال قلت وكيف ذلك أصلحك الله وقد وهبت له ثلاثين ألف درهم فقال لا والله ما ثلاثون ألف\nدينار بمكافئة له فكيف ثلاثون ألف درهم أخبرني أحمد بن عبد الله بن عمار قال أخبرني أحمد بن سليمان بن أبي شيخ قال كان أبي يستملح قول نصيب وقد رأى كثرة الشعراء على باب الفضل بن يحيى فلما دخل الناس إليه قال له\n(ما لقينا من جود فضل بن يحيى ... ترك الناس كلهم شعراء)\nيقول ما في الدنيا أحسن من هذا المعنى وعلى أنه قد أخذ منهم مالا جليلا ولكن قلما سمعت بطبقته مثله\n(طاف الخيال ولات حين تطرب ... أن زار طيف موهنا من زينب)\n(طرقت فنفرت الكرى عن نائم ... كانت وسادته ذراع الأرحبي)\n(فبكى الشباب وعهده وزمانه ... بعد المشيب وما بكاء الأشيب)\nعروضه من الكامل - الشعر لأبي شراعة القيسي والغناء لدعامة البصري خفيف رمل بالبنصر من كتاب الهشامي","topic":"خبر لقيط ونسبه والسبب في قوله الشعر","topicNo":293,"sp":7,"spl":"زار خزيمة بن خازم ومدحه","tags":["المديح"],"song":1,"loc":3793},
{"id":"b294-2","bab":"الجزء 23","sec":"أخبار أبي شراعة ونسبه — كان سمحا يجود بكل ما عنده","page":"ج23 ص25 – ج23 ص26","text":"هو فيما كتب به إلينا أبنه أبو الفياض سوار بن أبي شراعة من أخباره ونسبه أحمد بن محمد بن شراعة بن ثعلبة بن محمد بن عمير بن أبي نعيم بن خالد بن عبدة بن مالك بن مرة بن عباد بن ضبيعة بن قيس بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل شاعر بصري من شعراء الدولة العباسية جيد الشعر جزله ليس برقيق الطبع ولا سهل اللفظ وهو كالبدوي الشعر في مذهبه وكان فصيحا يتعاطى الرسائل والخطب مع شعره وكانت به لوثة وهوج وأمه من بني تميم من بني العنبر وابنه أبو الفياض سوار بن أبي شراعة أحد الشعراء الرواة قدم علينا بمدينة السلام بعد سنة ثلثمائة فكتب عنه أصحابنا قطعا من الأخبار واللغة وفاتني فلم ألقه وكتب إلي وإلى أبي رحمه الله بإجازة أخباره على يدي بعض إخواننا فكانت أخبار أبيه من ذلك\nفمنها ما حكاه عنه أنه كان جوادا لا يليق شيئا ولا يسأل ما يقدر عليه إلا سمح به وأنه وقف عليه سائل يوما فرمى إليه بنعله وانصرف حافيا فعثر فدميت إصبعه فقال في ذلك\n(ألا لا أبالي في العلا ما أصابني ... وإن نقبت نعلاي أو حفيت رجلي)\n(فلم تر عيني قط أحسن منظرا ... من النكب يدمى في المواساة والبذل)\n(ولست أبالي من تأوب منزلي ... إذا بقيت عندي السروايل أو نعلي)","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":0,"spl":"أخبار أبي شراعة ونسبه — كان سمحا يجود بكل ما عنده — أخوه يتهمه بالجنون فينشد شعرا","tags":["اللهو والمزاح"],"loc":3794},
{"id":"b294-3","bab":"الجزء 23","sec":"أخوه يتهمه بالجنون فينشد شعرا","page":"ج23 ص27","text":"قال وبلغه أن أخاه يقول إن أخي مجنون قد أفقرنا ونفسه فقال\n(أأنبز مجنونا إذا جدت بالذي ... ملكت وإن دافعت عنه فعاقل)\n(فداموا على الزور الذي قرفوا به ... ودمت على الإعطاء ما جاء سائل)\n(أبيت وتأبى لي رجال أشحة ... على المجد تنميهم تميم ووائل)\nقال وقال أيضا في ذلك\n(أئن كنت في الفتيان آلوت سيدا ... كثير شحوب اللون مختلف العصب)\n(فما لك من مولاك إلا حفاظه ... وما المرء إلا باللسان وبالقلب)\n(هما الأصغران الذائدان عن الفتى ... مكارهه والصاحبان على الخطب)\n(فإلا أطق سعي الكرام فإنني ... أفك عن العاني وأصبر في الحرب)\nخبرني عمي قال أخبرني ميمون بن هارون قال حدثني إبراهيم بن المدبر قال كان عندي أبو شراعة بالبصرة وأنا أتولاها وكان عندي عمير المغني\nالمدني وكان عمير بن مرة غطفانيا وكان يغني صوتا يجيده واختاره عليه وهو\n(أتحسب ذات الخال راجية ربا ... وقد صدعت قلبا يجن بها حبا)\nاقترحه أبو شراعة على عمير فقال أعطني دراهم حتى أقبل اقتراحك فقال له أبو شراعة أخذ المغني من الشاعر يدل على ضعف الشاعر ولكني أعرضك لأبي إسحاق فغناه إياه ثلاث مرات وقد شرب عليه ثلاثة أرطال وقال\n(عدوت إلى المري عدوة فاتك ... معن خليع للعواذل والعذر)\n(فقال لشيء ما أرى قلت حاجة ... مغلغلة بين المخنق والنحر)\n(فلما لواني يستثيب زجرته ... وقلت اغترف إنا كلانا على بحر)\n(أليس أبو إسحاق فيه غنى لنا ... فيجدي على قيس وأجدي على بكر)\n(فغنى بذات الخال حتى استخفني ... وكاد أديم الأرض من تحتنا يجري)","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":0,"spl":"أخبار أبي شراعة ونسبه — كان سمحا يجود بكل ما عنده — أخوه يتهمه بالجنون فينشد شعرا","tags":[],"loc":3795},
{"id":"b294-4","bab":"الجزء 23","sec":"يمدح صديقه ابن المدبر وقد وهبه مالا","page":"ج23 ص28","text":"حدثني علي بن سليمان الأخفش قال حدثني محمد بن يزيد المبرد قال كان أبو شراعة صديقا لإبن المدبر أيام تقلده البصرة وكان لا يفارقه في\nسائر أحواله ولا يمنعه حاجة يسأله إياها ولا يشفع لأحد إلا شفعه فلما عزل إبراهيم بن المدبر شيعه الناس وشيعه أبو شراعة فجعل يرد الناس حتى لم يبق غيره فقال له يا أبا شراعة غاية كل مودع الفراق فانصرف راشدا مكلوءا من غير قلى والله ولا ملل وأمر له بعشرة آلاف درهم فعانقه أبو شراعة وبكى فأطال ثم أنشأ يقول\n(يا أبا إسحاق سر في دعة ... وامض مصحوبا فما منك خلف)\n(ليت شعري أي أرض اجدبت ... فأغيثت بك من جهد العجف)\n(نزل الرحم من الله بهم ... وحرمناك لذنب قد سلف)\n(إنما أنت ربيع باكر ... حيثما صرفه الله انصرف)\nال أبو الفياض سوار بن أبي شراعة دخل أبي علي إبراهيم بن المدبر وعنده منجم فما رآه إبراهيم بن المدبر في رؤية الهلال لشهر رمضان فحكم المنجم بأنه يرى وحلف إبراهيم بعتق غلمانه أنه لا يرى فرئي في تلك الليلة فأعتق غلمانه فلما أصبح دخل الناس يهنئونه بالشهر فأنشده أبو شراعة يقول\n(أيها المكثر التجني على المال ... إذا ما خلا من السؤال)\n(أفتنا في الذين أعتقت بالأمس ... مواليك أم موالي الهلال)\n(لم يكن وكدك الهلال ولكن ... تتألى لصالح الأعمال)\n(إنما لذتاك في المال شتى ... صونك العرض وابتذال المال)\n(ما نبالي إذا بقيت سليما ... من تولت به صروف الليالي)\nقال أبوالفياض وكان أبو شراعة صديق السدري فدعا يوما إخوانه وأغفل أبا شراعة فمر به الرياشي فقال يا أبا شراعة ألست عند السدري معنا فقال لم يدعنا ومر به جماعة من إخوانه فسألوه عن مثل ذلك ومر به عيسى بن أبي حرب الصفار وكان ممن دعي فجلس وحلف ألا يبرح حتى يأتيه السدري فيعتذر إليه ويدعوه فقال أبو شراعة\n(أير حمار في حر أم شعري ... وخصيتاه في حر أم قدري)\n(إن أنا لم أشفعهما بوفر ... لو كنت ذا وفر دعاني السدري)\n(أو كان من هم هشام أمري ... أو راح إبراهيم يطري ذكري)\n(وابن الرياشي الضعيف الأمر ... يخاف إن أردف ألا يجري)\n(وانت يا عيسى سقاك المسري ... نعم صديق عسرة ويسر)\nال أبو الفياض سقطت دارنا بالبصرة فعوتب أبي علي بنائها وقيل له استعن بإخوانك إن عجزت عنه فقال\n(تلوم ابنة البكري حين أؤوبها ... هزيلا وبعض الآئبين سمين)\n(وقالت لحاك الله تستحسن العرا ... عن الدار إن النائبات فنون)\n(وحولك إخوان كرام لهم غنى ... فقلت لإخواني الكرام عيون)\n(ذريني أمت قبل احتلال محلة ... لها في وجوه السائلين غضون)\n(سأفدي بمالي ماء وجهي إنني ... بما فيه من ماء الحياء ضنين)\nقال سوار بن أبي شراعة كان إخوان أبي يجتمعون عند الحسين بن أيوب بن جعفر بن سليمان في ليالي شهر رمضان فيهم الرياشي والجماز فقال أبي في ذلك\n(لو كنت من شعية الجماز أقعدني ... مقاعدا قربهن الريف والشرف)\n(لكنني كنت للعباس متبعا ... وليس في مركب العباس مرتدف)\n(قد بقيت من ليالي الشهر واحدة ... فعاودوا مالح البقال وانصرفوا)","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":1,"spl":"يمدح صديقه ابن المدبر وقد وهبه مالا — طلق ليلة تزوج نديمة بيان","tags":["اللهو والمزاح"],"loc":3796},
{"id":"b294-5","bab":"الجزء 23","sec":"طلق ليلة تزوج نديمة بيان","page":"ج23 ص30","text":"قال وتزوج نديم لأبي شراعة يقال له بيان امرأة فاتفق عرسه في ليلة طلق فيها أبو شراعة امرأته فعوتب في ذلك وقيل بات بيان عروسا وبت عزبا فقال في ذلك\n(رأت عرس بيان فهبت تلومني ... رويدك لوما فالمطلق أحوط)\n(رويدك حتى يرجع البر أهله ... ويرحم رب العرس من حيث يغبط)\n(إذا قال للطحان عند حسابه ... أعد نظرا إني أظنك تغلط)\n(فما راعه إلا دعاء وليدة ... هلم إلى السواق إن كنت تنشط)\n(هنالك يدعو أمه فيسبها ... ويلتبش الأجر العقوق فيحبط)\n(فياذا العلا إني لفضلك شاكر ... أبيت وحيدا كلما شئت أضرط)","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":1,"spl":"يمدح صديقه ابن المدبر وقد وهبه مالا — طلق ليلة تزوج نديمة بيان","tags":["الجواري والنساء"],"loc":3797},
{"id":"b294-6","bab":"الجزء 23","sec":"شمن ببيان لأنه عجز عن امرأته","page":"ج23 ص31","text":"قال ثم بلغه عن بيان هذا أنه عجز عن امرأته ولم يصل إليها ولقي منها شرا فقال في ذلك\n(رمى الدهر في صحبي وفرق جلاسي ... وباعدهم عني بظعن وإعراس)\n(فكلهم يبغي غلافا لأيره ... وأقعدني عن ذاك فقري وإفلاسي)\n(فشكرا لربي خان بيان أيره ... وأسعى بأيري في الظلام على الناس)\n(يمسحه بالكف حتى يقيمه ... وهل ينفع الكفان من ثقل الرأس)\nقال أبو الفياض سوار نظر إلي أبي يوما وقد سألت عمي حاجة فردني فبكى ثم قال\n(حبي لإغناء سوار يجشمني ... خوض الدجى واعتساف المهمه البيد)\n(كي لا تهون على الأعمام حاجته ... ولا يعلل عنها بالمواعيد)\n(ولا يوليهم إن جاء يسألها ... أكتاف معرضة في العيس مردود)\n(إذا بكى قال منهم ذو الحفاظ له ... لقد بليت بخلق غير محمود)\nال وتمارى أبو شراعة ورجل من أهل بغداد في النبيذ فجعل البغدادي يذم نبيذ التمر والدبس فقال أبو شراعة\n(إذا انتخبت حبه ودبسه ... ثم أجدت ضربه ومرسه)\n(ثم أطلت في الإناء حبسه ... شربت منه البابلي نفسه)\nقال وأعوز أبا شراعه يومئذ النبيذ فطلب من نديمين كانا له فاعتل أحدهما بحلاوة نبيذه والآخر بحموضته فاشترى من نباذ يقال له أبو مظلومة\nدستيجة بدرهمين وكتب إليهما\n(سيغني عن حلاوة دبس يحيى ... ويغني عن حموض أبي أميه)\n(أبو مظلومة الشيخ المولي ... إذا اتزنت يداه درهميه)\nخبرني علي بن سليمان قال حدثنا محمد بن يزيد قال كان أبو شراعة قبيح الوجه جدا فنظر يوما في المرآة فأطال ثم قال الحمد لله الذي لا يحمد على الشر غيره","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":2,"spl":"شمن ببيان لأنه عجز عن امرأته — فضل النبيذ على امرأته فطلقها","tags":["الرواية والكتابة"],"loc":3798},
{"id":"b294-7","bab":"الجزء 23","sec":"فضل النبيذ على امرأته فطلقها","page":"ج23 ص33","text":"قال سوار بن أبي شراعة حلف أبي ألا يشرب نبيذا بطلاق امرأة كانت عنده فهجره حولين ثم حنث فشرب وطلق امرأته وأنشأ يقول\n(فمن كان لم يسمع عجيبا فإنني ... عجيب الحديث يا أميم وصادقه)\n(وقد كان لي أنسان يا أم مالك ... وكل إذا فتشتني أنا عاشقه)\n(عزيزة والكأس التي من يحلها ... تخادعه عن عقله فتصادقه)\n(تحاربتا عندي فعطلت دنها ... وأكوابها والدهر جم بوائقه)\n(وحرمتها حولين ثم أزلني ... حديث الندامى والنشيد أوافقه)\n(فلما شربت الكأس بانت بأختها ... فبان الغزال المستحب خلائقه)\n(فما أطيب الكأس التي أعتضت منكم ... ولكنها ليست بريم أعانقه)\nال أبو الفياض قال أبي قصدت الحسن بن رجاء بالأهواز فصادفت\nببابه دعبل بن علي الخزاعي وجماعة من الشعراء وقد اعتل عليهم بدين لزمه ومصادرة فكتب إليه\n(المال والعقل شيء يستعان به ... على المقام بأبواب السلاطين)\n(وأنت تعلم أني منهما عطل ... إذا تأملتني يابن الدهاقين)\n(هل تعلم اليوم بالأهواز من رجل ... سواك يصلح للدنيا وللدين)\nال فوعدنا وعدا قربه ثم تدافع فكتب إليه\n(آذنت جبتي بأمر قبيح ... من فراق للطيلسان الفسيح)\n(فكأني بمن يزيد على الجبة ... في ظل دار سهل بن نوح)\n(أنت روح الأهواز يابن رجاء ... أي شيء يعيش إلا بروح)\nأذن لي وللجماعة وقضى حوائجنا قال أبو الفياض وحدثني أبي قال حججت فأتيت دار سعيد بن سلم فنحرت فيها ناقة وقلت\n(وردت دار سعيد وهي خالية ... وكان أبيض مطعاما ذرى الإبل)\n(فارتحت فيها أصيلا عند ذكرته ... وصحبتي بمنى لاهون في شغل)\n(فابتعت من إبل الجمال دهشرة ... موسومة لم تكن بالحقة العطل)\n(نحرتها عن سعيد ثم قلت لهم ... زوروا الحطيم فإني غير مرتحل)\nقال وبلغت الأبيات وفعلي ولده فأحسنوا المكافأة وأجزلوا الصلة قال فقال له صديق له وأنت أيضا قد استجدت لهم النحيرة فضحك ثم قال أغرك وصفي لها أشهد الله أني ما بلغت بها دار سعيد إلا بين عمودين وقال أبو الفياض","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":2,"spl":"شمن ببيان لأنه عجز عن امرأته — فضل النبيذ على امرأته فطلقها","tags":["الجواري والنساء"],"loc":3799},
{"id":"b294-8","bab":"الجزء 23","sec":"عير أبا أمامة لأنه عالة على أمه","page":"ج23 ص35","text":"كان أبو أمامة محمد بن محمد بن عبد الرحمن بن سعيد بن سلم وأمه سعدى بنت عمرو بن سعيد بن سلم صديقا لأبي شراعة وكانت أمه سعدى تعوله فكان أبو شراعة لا يزال يعبث به وبلغه أن أبا أمامة يقول إنما معاش أبي شراعة من السلطان ورفده ولولا ذاك لكان فقيرا فقال فيه\n(عيرتني نائل السلطان أطلبه ... يا ضل رأيك بين الخرق والنزق)\n(لولا امتنان من السلطان تجهله ... أصبحت بالسود في مقعوعس خلق)\nلسود موضع تنزله باهلة بالبادية\n(رث الردا بين أهدام مرقعة ... يبيت فيها بليل الجائع الفرق)\n(لا شيء أثبت بالإنسان معرفة ... من التي حزمت جنبيه بالخرق)\n(فأين دارك منها وهي مؤمنة ... بالله معروفة الإسلام والشفق)\n(وأين رزقك إلا من يدي مرة ... ما بت من مالها إلا على سرق)\n(تبيت والهر ممدودا عيونكما ... إلى تطعمها مخضرة الحدق)\n(ما بين رزقيكما إن قاس ذو فطن ... فرق سوى أنه يأتيك في طبق)\n(شاركه في صيده للفأر تأكله ... كما تشاركه في الوجه والخلق)\nال أبو الفياض وزاره أبو أمامة يوما فوجد عنده طفشيلا فأكله كله فقال أبو شراعة يمازحه\n(عين جودي لبرمة الطفشيل ... واستهلي فالصبر غير جميل)\n(فجعتني بها يد لم تدع للذر ... في صحن قدرها من مقيل)\n(كان والله لحمها من فصيل ... راتع يرتعي كريم البقول)\n(فخلطنا بلحمه عدس الشام ... إلى حمص لنا مبلول)\n(فأتتنا كأنها روضة بالحزن ... تدعو الجيران للتطفيل)\n(ثم أكفأت فوقها جفنة الحي ... وعلقت صحفتي في زبيل)\n(فمنى الله لي بفظ غليظ ... ما أراه يقر بالتنزيل)\n(فانتحى دائبا يدبل منها ... قلت إن الثريد للتدبيل)\n(فتغني صوتا ليوضح عندي ... حي أم العلاء قبل الرحيل)","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":3,"spl":"عير أبا أمامة لأنه عالة على أمه","tags":["الجواري والنساء"],"loc":3800},
{"id":"b294-9","bab":"الجزء 23","sec":"كتب أبوه إلى سعيد بن موسى يستهديه نبيذا","page":"ج23 ص37","text":"أخبري علي بن سليمان الأخفش قال حدثني سوار بن أبي شراعة قال كتب أبي إلى سعيد بن موسى بن سعيد بن مسلم بن قتيبة يستهديه نبيذا فكتب إليه سعيد إذا سألتني جعلني الله فداءك حاجة فاشطط واحتكم فيها حكم الصبي على أهله فإن ذلك يسرني وأسارع إلى إجابتك فيه وأمر له بما التمس من النبيذ فمزجه صاحب شرابه وبعث به إليه فكتب إليه أبو شراعة أستنسيء الله أجلك وأستعيذه من الآفات لك وأستعينه على شكر ما وهب من النعمة فيك إنه لذلك ولي وبه ملي أتاني غلامك المليح قده السعيد بملكك جده بكتاب قرأته غير مستكره اللفظ ولا مزور عن القصد ينطق بحكمتك ويبين عن فضلك فوالله ما أوضح لي خفيا ولا زادني بك علما وإذا أنت تسأل فيه أن تهب وتحب أن تحمد ولا غرو أن تفعل ذلك ومن كثب أخذته لا عن كلالة وغير كلالة ورثته موسى أبوك وسعيد جدك وعمرو عمك ولك دار الصلة ودار الضيافة وصاحب البغلة الشهباء وحصين بن الحمام وعروة بن الورد ففي أي\nغلوات المجد يطمع قرينك أن يستولي على المدى والأمد دونك وكتابك إلي أن أتحكم عليك تحكم الصبي على أهله فلشد ما جررت إلي معروفك ودللت على الأنس بك وحاشى للمحكوم له والمحكوم عليه في ذلك الحسب العتيق والمنظر الأنيق الذي يسر القلب ويلائم الروح ويطرد الهم\n(تدب خلال شؤون الفتى ... دبيب دبى النملة المنتعش)\n(إذا فتحت فغمت ريحها ... وإن سيل خمارها قال خش)\nش كلمة فارسية تفسيرها طيب فإن كنت رعيت لها عهدا وحفظت لها عندك يدا فانظر رب الحانوت فامطله دينه واقطع السبب بينك وبينه فقد أساء صحبتها وأفسد بالماء حسها وسلط عليها عدوها واعلم بأن أباك المتمثل بقوله\n(يرى درجات المجد لا يستطيعها ... فيقعد وسط القوم لا يتكلم)\nوقد بسطت قدرتك لسانك وأكثرت لك الحمد فدونك نهزة البديهة منه\n(وبادر بمعروف إذا كنت قادرا ... زوال افتقار أو غنى عنك يعقب)\nقد بعثت إليك بقرابة مع الرسول وأنشأت في أثرها أقول\n(إليك أبن موسى الجود أعملت ناقتي ... مجللة يضفو عليها جلالها)\n(كتوم الوحي لا تشتكي ألم السرى ... سواء عليها موتها واعتلالها)\n(إذا شربت أبصرت ما جوف بطنها ... وإن ظمئت لم يبد منها هزالها)\n(وإن حملت حملا تكلفت حملها ... وإن حط عنها لم أقل كيف حالها)\n(بعثنا بها تسمو العيون وراءها ... إليك وما يخشى عليها كلالها)\n(وغنى مغنينا بصوت فشاقني ... متى راجع من أم عمرو خيالها)\n(أحب لكم قيس بن عيلان كلها ... ويعجبني فرسانها ورجالها)\n(ومالي لا أهوى بقاء قبيلة ... أبوك لها بدر وأنت هلالها)\nال فبعث إليه برسوله الذي حمل إليه النبيذ واستملحه في شعره وبصاحب شرابه وكل ما كان في خزانته من الشراب وبثلثمائة دينار","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":4,"spl":"كتب أبوه إلى سعيد بن موسى يستهديه نبيذا","tags":["الخمر","الرواية والكتابة"],"loc":3801},
{"id":"b294-10","bab":"الجزء 23","sec":"مساجلة حول جارية يقال لها مليحة","page":"ج23 ص39","text":"أخبرني الأخفش عن المبرد وسوار بن أبي شراعة جميعا أن أبا الفياض سوار بن أبي شراعة كان يهوى قينة بالبصرة يقال لها مليحة فدعيت ذات يوم إلى مجلس لم يكن حاضره وحضر أبو علي البصير ذلك المجلس فجمشها بعض من حضر فلم تلتفت إليه وعرف أبو علي ذلك فكتب إلى أبي الفياض\n(لك عندي بشارة فاستمعها ... وأجبني عنها أبا الفياض)\n(كنت في مجلس مليحة فيه ... وهي سقم الصحاح برء المراض)\n(وقديما عهدتني لست في حقك ... والذب عنك ذا إغماض)\n(فتغفلتها تغفل خصم ... وتأملتها تأمل قاض)\n(ورمتها العيون من كل أفق ... وتشاكوا بالوحي والإيماض)\n(من كهول وسادة سمحاء ... باللها باخلين بالأعراض)\n(وصفات القيان أولها الغدر ... عليه في وصلهن التراضي)\n(فتشوفت ذاك منها وأعددت ... نكيري وسورتي وامتعاضي)\n(فحمت جانب المزاح وعمتهم ... جميعا بالصد والإعراض)\n(وكفاني وفاؤها لك حتى ... آذن الليل جمعهم بارفضاض)\nأجابه أبو الفياض\n(ليت شعري ماذا دعاك إلى أن ... هجت شوقي وزدت في إمراضي)\n(ذكرتني بشراك داء قديما ... من سقام علي لا شك قاضي)\n(إن تكن أحسنت مليحة في وصلي ... وعاصت رياضة الرواض)\n(وأقامت على الوفاء ولم ترع ... لوحي منهم ولا إيماض)\n(فعلى صحة الوفاء تعاقدنا ... وصون النفوس والأعراض)\n(وعلينا من العفاف ثياب ... هن أبهى من حاليات الرياض)\n(ليس حظي منها سوى النظر الختل ... وإني به لجذلان راض)\n(لحظات يقعن في ساحة القلب ... وقوع السهام في الأغراض)\n(وابتسام كالبرق أو هو أخفى ... بين ستري تحرز وانقباض)\n(لا أخاف انتقاضها آخر الدهر ... بغدر ولا تخاف انتقاضي)\n(فأبن لي ألست تحمد ذا ... الود وقاك الردى أبو الفياض)\nال أبو الفياض اتصل بأبي شراعة أن أبا ناظرة السدوسي يغتابه وكان مع آل أبي سفيان بن ثور فقال يهجوهم\n(لعن الإله بني سدوس كلهم ... ورمى بمنجوف ورية قاف)\n(قد سبني عضر وطهم فسببتهم ... ذنب الدنيء يناط بالأشراف)\nال أبو الفياض وكان بين بعض بني عمنا وبين أبي شراعة وحشة ثم صالحوه ودعوه إلى طعامهم فأبى وقال أمثلي يخرج من صوم إلى طعم ومن شتيمة إلى وليمة ومالي ولكم مثل إلا قول المتلمس\n(فإن تقبلوا بالود نقبل بمثله ... وإلا فإنا نحن آبى وأشمس)\nقال فيهم\n(بني سوار إن رثت ثيابي ... وكل عن العشيرة فضل مالي)\n(فمطرح ومتروك كلامي ... وتجفوني الأقارب والموالي)\n(ألم أك من سراة بني نعيم ... أحل البيت ذا العمد الطوال)\n(وحولي كل أصيد تغلبي ... أبي الضيم مشترك النوال)\n(إذا حضر الغداء فغير مغن ... ويغني حين تشتجر العوالي)\n(وأبقوني فلست بمستكين ... لصاحب ثروة أخرى الليالي)\n(ولا بممسح المثرين كيما ... أمسح من طعامهم سبالي)\n(أنا ابن العنبرية أزرتني ... إزار المكرمات إزار خالي)\n(فإن يكن الغنى مجدا فإني ... سأدعو الله بالرزق الحلال)\n\n(إذا أبصرتك العين من بعد غاية ... وأوقعت شكا فيك أثبتك القلب)\n(ولو أن ركبا يمموك لقادهم ... نسيمك حتى يستدل بك الركب)\nلشعر لعبد الله بن محمد بن البواب والغناء لأحمد بن صدقة الطنبوري رمل مطلق في مجرى البنصر رواية الهشامي","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":5,"spl":"مساجلة حول جارية يقال لها مليحة","tags":["اللهو والمزاح","الوصف والطبيعة"],"song":1,"loc":3802},
{"id":"b294-12","bab":"الجزء 23","sec":"أخبار ابن البواب — أعطاه الأمين فمدحه","page":"ج23 ص43 – ج23 ص44","text":"هو عبد الله بن محمد بن عتاب بن إسحاق من أهل بخارى وجه بجدة وجماعة معه رهينة إلى الحجاج بن يوسف فنزلوا عنده بواسط فأقطعهم سكة بها فاختطوها ونزلوها طول أيام بني أمية ثم انقطعوا من الدولة العباسية إلى الربيع فخدموه وكان عبد الله بن محمد هذا يخلف الفضل بن الربيع على حجبة الخلفاء وكان أبوه محمد بن عتاب يخلف الربيع في أيام أبي جعفر وكان معه فرآه أبو جعفر مع أبيه فسأله عنه فأخبره فكساه قباء خز وكساه تحته قباء كتان مرقوع القب\nوقال له هذا يخفى تحت ذاك ذكر لي أحمد بن القاسم بن يوسف عن محمد بن عبد الله بن محمد البواب عن أبيه وكان عبد الله صالح الشعر قليله وراوية لأخبار الخلفاء عالما بأمورهم روى عنه أبو زيد عمر بن شبة ونظراؤه وقد مضت في هذا الكتاب وتأتي أخبار من روايته\nقال أحمد بن القاسم اليوسفي حدثني محمد بن عبد الله البواب قال حدثني أبي قال حجبت موسى وهارون خليفة للفضل بن الربيع وخدم محمدا الأمين فأغناه وأعطاه ومدحه ونال من المأمون وعرض به فأخبرني إسماعيل بن يوسف قال حدثني عبد الله بن أحمد الباهلي قال حدثني الحسين بن الضحاك قال لما أتي المأمون بشعر ابن البواب الذي يقول فيه\n(أيبخل فرد الحسن فرد صفاته ... علي وقد أفردته بهوى فرد)\n(رأى الله عبد الله خير عباده ... فملكه والله أعلم بالعبد)\n(ألا إنما المأمون للناس عصمة ... مميزة بين الضلالة والرشد)\nعلويه في هذه الأبيات رمل بالوسطى قال فقال المأمون أليس هو القائل\n(أعيني جودا وابكيا لي محمدا ... ولا تدخرا دمعا عليه وأسعدا)\n(فلا فرح المأمون بالملك بعده ... ولا زال في الدنيا طريدا مشردا)\nهيهات وواحدة بواحدة ولم يصله بشيء\nهكذا روي عن الحسين بن الضحاك وقد روي أن هذين الشعرين جميعا للحسين وأن قول المأمون هذا بعينه فيه","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":6,"spl":"أخبار ابن البواب — أعطاه الأمين فمدحه — نسب إلى إسحاق شعرا ذميما رديئا","tags":["المديح","اللهو والمزاح"],"song":1,"loc":3803},
{"id":"b294-13","bab":"الجزء 23","sec":"نسب إلى إسحاق شعرا ذميما رديئا","page":"ج23 ص44","text":"قال أحمد بن القاسم حدثني جزء بن قطن وأخبرني بهذا الخبر الحسين بن يحيى عن حماد بن إسحاق قالا جميعا وقع بين إسحاق وبين ابن البواب شر فقال ابن البواب شعرا ذميما رديئا ونسبه إلى إسحاق وأشاعه ليعيره به وهو\n(إنما أنت يا عنان سراج ... زيته الظرف والفتيلة عقل)\n(قاده للشقاء مني فؤادي ... رجل حب لكم وللحب رجل)\n(هضم اليوم حبكم كل حب ... في فؤادي فصار حبك فجل)\n(أنت ريحانة وراح ولكن ... كل أنثى سواك خل وبقل)\nقال حماد في خبره وبلغ ذلك أبي فقال له\n(الشعر قد أعيا عليك فخله ... وخذ العصا واقعد على الأبواب)\nجاء ابن البواب إلى إبراهيم جدي فشكا أبي إليه فقال له مالك وله يا بني فقال له أبي تعرض لي فأجبته وإن كف لم أرجع إلى مساءته فتتاركا","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":6,"spl":"أخبار ابن البواب — أعطاه الأمين فمدحه — نسب إلى إسحاق شعرا ذميما رديئا","tags":[],"loc":3804},
{"id":"b294-14","bab":"الجزء 23","sec":"خبره مع جارية يهواها اسمها عبادة","page":"ج23 ص45","text":"قال أحمد بن القاسم أخبرني محمد بن الحسن بن الفضل قال أخبرني إبراهيم بن أحمد بن عبد الرحيم قال\nكان بالكرخ نخاس يكنى أبا عمير وكان له جوار قيان لهن ظرف وأدب وكان عبد الله بن محمد البواب يألف جارية منهن يقال لها عبادة ويكثر غشيان منزل أبي عمير من أجلها فضاق ضيقة شديدة فانقطع عن ذلك وكره أن يقصر عما كان يستعمله من برهم فتعلم بضيقته ثم نازعته نفسه إلى لقائها وزيارتها وصعب عليه الصبر عنها فأتاه فأصاب في منزله جماعة ممن كان يألف جواريه فرحب به أبو عمير والجارية والقوم جميعا واستبطأوا زيارته وعاتبوه على تأخره عنهم فجعل يجمجم في عدره ولا يصرح فأقام عندهم فلما أخذ فيه النبيذ أنشأ يقول\n(لو تشكى أبو عمير قليلا ... لأتيناه من طريق العياده)\n(فقضينا من العيادة حقا ... ونظرنا في مقلتي عباده)\nقال له أبو عمير مالي ولك يا أخي أنظر في مقلتي عبادة متى شئت غير ممنوع ودعني أنا في عافية لا تتمن لي المرض لتمودني وقال أحمد بن القاسم كان عبد الله بن إسماعيل بن علي بن ريطة يألف ابن البواب ويعاشره فشرب عنده يوما حتى سكر ونام فلما أفاق في السحر أراد الإنصراف فحلف عليه واحتبسه وكان عبد الله يهوى جارية له من جواري عمرو بن بانة فبعث إلى عمرو بن بانة فدعاه وسأله إحضار الجارية فأحضرها وانتبه عبد الله بن إسماعيل من نومه وهو يتململ خمارا فلما رآها نشط وجلس فشرب وتمموا يومهم فقال عبد الله بن محمد بن البواب في ذلك\n(وكريم المجد محض أبوه ... فهو الصفو اللباب النضار)\n(هاشمي لقروم إذا ما ... أظلمت أوجه قوم أناروا)\n(رمت القهوة بالنوم وهنا ... عينه فالجفن فيه انكسار)\n(فهو من طرف يفديك طورا ... ويعاطيك اللواتي أداروا)\n(ساعة ثم انثنى حين دبت ... ومشت فيه السلاف العقار)\n(وأبت عيني اغتماضا فلما ... حان من أخرى النجوم انحدار)\n(قلت عبد الله حاذرت أمرا ... ليس يغني خائفيه الحذار)\n(فاستوى كالهنداوني لما ... أن رأى أن ليس يغني الفرار)\n(قلت خذها مثل مصباح ليل ... طيرت في حافتيه الشرار)\n(أقبلت قطرا نطافا ولما ... يتعب العاصر منها اعتصار)\n(هي كالياقوت حمراء شيبت ... وعلا الحمرة منها اصفرار)\n(كالدنانير جرى في ذراها ... فضة فالحسن منها قصار)\n(تنطق الخرس وبالصمت ترمي ... معشرا نطقا إذا ما أحاروا)\nال أحمد وحدثني يعقوب بن العباس الهاشمي أبو إسماعيل النقيب قال لما طال سخط المأمون على ابن البواب قال قصيدة يمدحه بها ودس من غناه في بعضها لما وجد منه نشاطا فسأل من قائلها فأخبر به فرضي عنه ورده إلى رسمه من الخدمة وأنشدني أبو إسماعيل القصيدة وهي قوله","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":7,"spl":"خبره مع جارية يهواها اسمها عبادة — قصيدته في مدح المأمون","tags":["المديح","الجواري والنساء"],"loc":3805},
{"id":"b294-15","bab":"الجزء 23","sec":"قصيدته في مدح المأمون","page":"ج23 ص47","text":"(هل للمحب معين ... إذ شط عنه القرين)\n(فليس يبكي لشجو ... الحزين إلا الحزين)\n(يا ظاعنا غاب عنا ... غداة بان القطين)\n(أبكى العيون وكانت ... به تقر العيون)\n(يا أيها المأمون ... المبارك الميمون)\n(لقد صفت بك دنيا ... للمسلمين ودين)\n(عليك نور جلال ... ونور ملك مبين)\n(القول منك فعال ... والظن منك يقين)\n(مامن يديك شمال ... كلتا يديك يمين)\n(كأنما أنت في الجود ... والتقى هارون)\n(من نال من كل فضل ... ما ناله المأمون)\n(تألف الناس منه ... فضل وجود ولين)\n(كالبدر يبدو عليه ... سكينة وسكون)\n(فالرزق من راحتيه ... مقسم مضمون)\n(وكل خصلة فضل ... كانت فمنه تكون)\nالأبيات التي فيها الغناء المذكور آنفا أربعة أبيات أنشدنيها الأخفش وهي قوله\n(أفق أيها القلب المعذب كم تصبو ... فلا النأي عن سلماك يسلي ولا القرب)\n(أقول غداة استخبرت مم علتي ... من الحب كرب ليس يشبهه كرب)\n(إذا أبصرتك العين من بعد غاية ... فأدخلت شكا فيك أثبتك القلب)\n(ولو أن ركبا يمموك لقادهم ... نسيمك حتى يستدل بك الركب)\nقال الأخفش مثل هذا البيت الأخير قول الشاعر\n(واستودعت نشرها الديار فما ... تزداد طيبا إلا على القدم)\nخبرني الحسن بن يحيى عن حماد بن إسحاق قال رأيت محمد بن عبد الله البواب وقد جاء إلى أبي مسلما فاحتبسه ورأيته وهو شيخ كبير وكان ضخما طويلا عظيم الساقين كأنهما دنان وكان يشد في ساقيه خرزا أسود لئلا تصيبهما العين","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":7,"spl":"خبره مع جارية يهواها اسمها عبادة — قصيدته في مدح المأمون","tags":["الحب والغزل"],"loc":3806},
{"id":"b294-16","bab":"الجزء 23","sec":"مدح أبا دلف بعد أن أملق فوهبه مالا","page":"ج23 ص49","text":"وقال محمد بن القاسم أملق عبد الله بن محمد البواب حين جفاه الخليفة وعلت سنه عن الخدمة فرحل إلى أبي دلف القاسم بن عيسى ومدحه بقصيدة مهوب له ثلاثين ألف درهم وعاد بها إلى بغداد فما نفدت حتى مات وهي قوله\n(طرقتك صائدة القلوب رباب ... ونأت فليس لها إليك مآب)\n(وتصرمت منها العهود وغلقت ... من دون نيل طلابها الأبواب)\n(فلأصدفن عن الهوى وطلابه ... فالحب فيه بلية وعذاب)\n(وأخص بالمدح المهذب سيدا ... نفحاته للمجتدين رغاب)\n(وإلى أبي دلف رحلت مطيتي ... قد شفها الإرقال والإتعاب)\n(تعلو بنا قلل الجبال ودونها ... مما هوت أهوية وشعاب)\n(فإذا حللت لدي الأمير بأرضه ... نلت المنى وتقضت الآراب)\n(ملك تأثل عن أبيه وجده ... مجدا يقصر دونه الطلاب)\n(وإذا وزنت قديم ذي حسب به ... خضعت لفضل قديمه الأحساب)\n(قوم علوا أملاك كل قبيلة ... فالناس كلهم لهم أذناب)\n(ضربت عليه المكرمات قبابها ... فعلا العمود وطالت الأطناب)\n(عقم النساء بمثله وتعطلت ... من أن تضمن مثله الأصلاب)\n\n(صغير هواك عذبني ... فكيف به إذا احتنكا)\n(وأنت جمعت من قلبي ... هوى قد كان مشتركا)\n(وحبس هواك يقتلني ... وقتلي لا يحل لكا)\n(أما ترثي لمكتئب ... إذا ضحك الخلي بكى)\nالشعر لمحمد بن عبد الملك الزيات والغناء لأبي حشيشة رمل بالوسطى عن الهشامي","topic":"أخبار أبي شراعة ونسبه","topicNo":294,"sp":8,"spl":"مدح أبا دلف بعد أن أملق فوهبه مالا","tags":["الحب والغزل"],"song":1,"loc":3807},
{"id":"b295-1","bab":"الجزء 23","sec":"أخبار محمد بن عبد الملك الزيات ونسبه","page":"ج23 ص51","text":"هو محمد بن عبد الملك الزيات بن أبان بن أبي حمزة الزيات وأصله من جبل ويكنى أبا جعفر وكان أبوه تاجرا من تجار الكرخ المياسير فكان يحثه على التجارة وملازمتها فيأبى إلا الكتابة وطلبها وقصد المعالي حتى بلغ منها أن وزر ثلاث دفعات وهو أول من تولى ذلك وتم له\nأخبرني الأخفش علي بن سليمان قال حدثني عمر بن محمد بن عبد الملك قال كان جدي موسرا من تجار الكرخ وكان يريد من أبي أن يتعلق بالتجارة ويتشاغل بها فيمتنع من ذلك ويلزم الأدب وطلبه ويخالط الكتاب ويلازم الدواوين فقال له ذات يوم والله ما أرى ما أنت ملازمه ينفعك وليضرنك لأنك تدع عاجل المنفعة وما أنت فيه مكفي ولك ولأبيك فيه مال وجاه وتطلب الآجل الذي لا تدري كيف تكون فيه فقال والله لتعلمن أينا ينتفع بما هو فيه أأنا أم أنت ثم شخص إلى الحسن بن سهل بفم الصلح فامتدحه بقصيدته التي أولها\n(كأنها حين تناءى خطوها ... أخنس موشي الشوى يرعى القبل)\nأعطاه عشرة آلاف درهم فعاد بها إلى أبيه فقال له أبوه لا ألومك بعدها على ما أنت فيه أخبرني جحظة والصولي قالا حدثنا ميمون بن هارون قال لما مدح محمد بن عبد الملك الحسن بن سهل ووصله بعشرة آلاف درهم مثل بين يديه وقال له\n(لم أمتدحك رجاء المال أطلبه ... لكن لتلبسني التحجيل والغررا)\n(وليس ذلك إلا أنني رجل ... لا أطلب الورد حتى أعرف الصدرا)\nكان محمد بن عبد الملك شاعرا مجيدا لا يقاس به أحد من الكتاب وإن كان إبراهيم بن العباس مثله في ذلك فإن إبراهيم مقل وصاحب قصار ومقطعات وكان محمد شاعرا يطيل فيجيد ويأتي بالقصار فيجيد وكان بليغا حسن اللفظ إذا تكلم وإذا كتب","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":0,"spl":"أخبار محمد بن عبد الملك الزيات ونسبه — خبر عن عدله وإنصافه الناس","tags":["محمد بن عبد الملك الزيات","المديح","اللهو والمزاح"],"loc":3808},
{"id":"b295-2","bab":"الجزء 23","sec":"خبر عن عدله وإنصافه الناس","page":"ج23 ص52","text":"فحدثني عمي رحمه الله قال حدثني هارون بن محمد بن عبد الملك قال جلس أبي يوما للمظالم فلما انقضى المجلس رأى رجلا جالسا فقال\nله ألك حاجة قال نعم تدنيني إليك فإني مظلوم فأدناه فقال أني مظلوم وقد أعوزني الإنصاف قال ومن ظلمك قال أنت ولست أصل إليك فأذكر حاجتي\nقال ومن يحجبك عني وقد ترى مجلسي مبذولا قال يحجبني عنك هيبتي لك وطول لسانك وفصاحتك واطراد حجتك قال ففيم ظلمتك قال ضيعتي الفلانية أخذها وكيلك غصبا بغير ثمن فإذا وجب عليها خراج أديته بإسمي لئلا يثبت لك اسم بملكها فيبطل ملكي فوكيلك يأخذ غلتها وأنا أؤدي خراجها وهذا مما لم يسمع في الظلم مثله فقال محمد هذا قول تحتاج عليه إلى بينة وشهود وأشياء فقال له الرجل أيؤمنني الوزير من غضبه حتى أجيب\nقال قد أمنتك قال البينة هم الشهود وإذا شهدوا فليس يحتاج معهم إلى شيء فما معنى قولك بينة وشهود وأشياء أيش هذه الأشياء إلا العي والحصر والتغطرس فضحك\nوقال صدقت والبلاء موكل بالمنطق وإني لأرى فيك مصطنعا ثم وقع له برد ضيعته وبأن يطلق له كر حنطة وكر شعير ومائة دينار يستعين بها على عمارة ضيعته وصيره من أصحابه واصطنعه أخبرني الصولي قال حدثني أحمد بن محمد الطالقاني قال حدثني عبيد الله بن محمد بن عبد الملك قال","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":0,"spl":"أخبار محمد بن عبد الملك الزيات ونسبه — خبر عن عدله وإنصافه الناس","tags":["محمد بن عبد الملك الزيات","اللهو والمزاح"],"loc":3809},
{"id":"b295-3","bab":"الجزء 23","sec":"هدد إبراهيم بن المهدي بقصيدة يخاطب فيها المأمون","page":"ج23 ص53","text":"لما وثب إبراهيم بن المهدي على الخلافة اقترض من مياسير التجار\nمالا فأخذ من جدي عبد الملك عشرة آلاف درهم وقال له أنا أردها إذا جاءني مال ولم يتم أمره فاستخفى ثم ظهر ورضي عنه المأمون فطالبه الناس بأموالهم فقال إنما أخذتها للمسلمين وأردت قضاءها من فيئهم والأمر الآن إلى غيري فعمل أبي محمد بن عبد الملك قصيدة يخاطب فيها المأمون ومضى بها إلى إبراهيم بن المهدي فأقرأه أياها\nوقال والله لئن لم تعطني المال الذي اقترضته من أبي لأوصلن هذه القصيدة إلى المأمون فخاف أن يقرأها المأمون فيتدبر ما قاله فيوقع به فقال له خذ مني بعض المال ونجم علي بعضه ففعل أبي ذلك بعد أن حلفه إبراهيم بأوكد الأيمان ألا يظهر القصيدة في حياة المأمون فوفى له أبي بذلك ووفى إبراهيم بأداء المال كله والقصيدة قوله\n(ألم تر أن الشيء للشيء علة ... تكون له كالنار تقدح بالزند)\n(كذلك جربت الأمور وإنما ... يدلك ما قد كان قبل على البعد)\n(وظني بإبراهيم أن مكانه ... )\n... سيبعث يوما مثل أيامه النكد رأيت حسينا حين صار محمد ... بغير أمان في يديه ولا عقد فلو كان أمضى السيف فيه بضربة ... فصيره بالقاع منعفر الخد إذا لم تكن للجند فيه بقية ... فقد كان ما خبرت من خبر الجند هم قتلوه بعد أن قتلوا له ... ثلاثين ألفا من كهول ومن مرد\n(وما نصروه عن يد سلفت له ... ولا قتلوه يوم ذلك عن حقد)\n(ولكنه الغدر الصراح وخفة ... الحلوم وبعد الرأي عن سنن القصد)\n(فذلك يوم كان للناس عبرة ... سيبقى بقاء الوحي في الحجر الصلد)\n(وما يوم إبراهيم إن طال عمره ... بأبعد في المكروه من يومه عندي)\n(تذكر أمير المؤمنين مقامه ... وأيمانه في الهزل منه وفي الجد)\n(أما والذي أمسيت عبدا خليفة ... له شر أيمان الخليفة والعبد)\n(إذا هز أعواد المنابر باسته ... تغنى بليلى أو بمية أو هند)\n(فوالله ما من توبة نزعت به ... إليك ولا ميل إليك ولا ود)\n(ولكن إخلاص الضمير مقرب ... إلى الله زلفى لا تخيب ولا تكدي)\n(أتاك بها طوعا إليك بأنفه ... على رغمه واستأثر الله بالحمد)\n(فلا تتركن للناس موضع شبهة ... فإنك مجزي بحسب الذي تسدي)\n(فقد غلطوا للناس في نصب مثله ... ومن ليس للمنصور بابن ولا المهدي)\n(فكيف بمن قد بايع الناس والتقت ... ببيعته الركبان غورا إلى نجد)\n(ومن سك تسليم الخلافة سمعه ... ينادى به بين السماطين من بعد)\n(وأي امرئ سمى بها قط نفسه ... ففارقها حتى يغيب في اللحد)\n(وتزعم هذي النابتية أنه ... إمام لها فيما تسر وما تبدي)\n(يقولون سني وأية سنة ... تقوم بجون اللون صعل القفا جعد)\n(وقد جعلوا رخص الطعام بعهده ... زعيما له باليمن والكوكب السعد)\n(إذا ما رأوا يوما غلاء رأيتهم ... يحنون تحنانا إلى ذلك العهد)\n(وإقباله في العيد يوجف حوله ... وجيف الجياد واصطفاق القنا الجرد)\n(ورجالة يمشون بالبيض قبله ... وقد تبعوه بالقضيب وبالبرد)\n(فإن قلت قد رام الخلافة غيره ... فلم يؤت فيما كان حاول من جد)\n(فلم أجزه إذ خيب الله سعيه ... على خطإ إذ كان منه ولا عمد)\n(ولم أرض بعد العفو حتى رفعته ... وللعم أولى بالتعهد والرفد)\n(فليس سواء خارجي رمى به ... إليك سفاه الرأي والرأي قد يردي)\n(تعاوت له من كل أوب عصابة ... متى يوردوا لا يصدروه عن الورد)\n(ومن هو في بيت الخلافة تلتقى ... به وبك الآباء في ذروة المجد)\n(فمولاك مولاه وجندك جنده ... وهل يجمع القين الحسامين في غمد)\n(وقد رابني من أهل بيتك أنني ... رأيت لهم وجدا به أيما وجد)\n(يقولون لا تبعد من ابن ملمة ... صبور عليها النفس ذي مرة جلد)\n(فدانا وهانت نفسه دون ملكنا ... عليه لذي الحال التي قل من يفدي)\n(على حين أعطى الناس صفق أكفهم ... علي بن موسى بالولاية والعهد)\n(فما كان فينا من أبى الضيم غيره ... كريم كفى ما في القبول وفي الرد)\n(وجرد إبراهيم للموت نفسه ... وأبدى سلاحا فوق ذي ميعة نهد)\n(وأبلى ومن يبلغ من الأمر جهده ... فليس بمذموم وإن كان لم يجد)\n(فهذي أمور قد يخاف ذوو النهى ... مغبتها والله يهديك للرشد)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":1,"spl":"هدد إبراهيم بن المهدي بقصيدة يخاطب فيها المأمون","tags":["محمد بن عبد الملك الزيات"],"loc":3810,"partial":1},
{"id":"b295-4","bab":"الجزء 23","sec":"رأيه في يحيى بن خاقان","page":"ج23 ص57","text":"أخبرني الصولي قال حدثني عبد الله بن الحسين القطربلي عن جعفر بن محمد بن خلف قال قال لي المعلى بن أيوب كيف كان محل يحيى بن خاقان عند محمد بن عبد الملك ومقداره فقلت له سمعت محمدا يذكره فقال هو مهزول الألفاظ عليل المعاني سخيف العقل ضعيف العقدة واهي العزم مأفون الرأي\nقال عبد الله ولما تولى محمد بن عبد الملك الوزارة اشترط ألا يلبس القباء وأن يلبس الدراعة ويتقلد عليها سيفا بحمائل فأجيب إلى ذلك أخبرني الصولي\nقال حدثني أبو ذكوان قال حدثني طماس قال ميمون بن هارون كان محمد بن عبد الملك يقول الرحمة خور في الطبيعة وضعف في المنة ما رحمت شيئا قط فكانوا يطعنون عليه في دينه بهذا القول فلما وضع في الثقل والحديد قال ارحموني فقالوا له وهل رحمت شيئا قط\nفترحم هذه شهادتك على نفسك وحكمك عليها أخبرني الصولي قال حدثني أبو ذكوان قال حدثني طماس قال جاء أبو دنقش الحاجب إلى محمد بن عبد الملك برسالة من المعتصم ليحضر فدخل ليلبس ثيابه ورأى ابن دنقش الحاجب غلمانا لهم روقة فقال وهو يظن أنه لا يسمع\n(وعلى اللواط فلا تلومن كاتبا ... إن اللواط سجية الكتاب)\nقال محمد له\n(وكما اللواط سجية الكتاب ... فكذا الحلاق سجية الحجاب)\nفاستحيا ابن دنقش واعتذر إليه فقال له إنما يقع العذر لو لم يقع الإقتصاص فأما وقد كافأتك فلا","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":2,"spl":"رأيه في يحيى بن خاقان — سرق منديله فأنشد شعرا","tags":["محمد بن عبد الملك الزيات","السفر والحج","الرواية والكتابة"],"loc":3811},
{"id":"b295-5","bab":"الجزء 23","sec":"رثاؤه أم أبنه عمر","page":"ج23 ص58","text":"أخبرني الصولي قال حدثني محمد بن موسى قال أنشدني الحسن بن وهب لمحمد بن عبد الملك أبياتا يرثي بها سكرانة أم ابنه عمر وجعل الحسن يتعجب من جودتها ويقول\n(يقول لي الخلان لو زرت قبرها ... فقلت وهل غير الفؤاد لها قبر)\n(على حين لم أحدث فأجهل قدرها ... ولم أبلغ السن التي معها الصبر)\nخبرني محمد بن خلف وكيع قال حدثني عبد الرحمن بن سعيد الأزرقي قال استبطأ عبد الله بن طاهر محمد بن عبد الملك في بعض\nأموره واتهمه بعدوله عن شيء أراده إلى سواه فكتب إليه محمد بن عبد الملك يعتذر من ذلك وكتب في آخر كتابه يقول\n(أتزعم أنني أهوى خليلا ... سواك على التداني والبعاد)\n(جحدت إذا موالاتي عليا ... وقلت بأنني مولى زياد)\nرأت في بعض الكتب كان عبد الله بن الحسن الأصبهاني يخلف عمرو بن مسعدة على ديوان الرسائل فكتب إلى خالد بن يزيد بن مزيد إن المعتصم جعل أمير المؤمنين ينفخ منك في غير فحم ويخاطب أمرأ غير ذي فهم فقال محمد بن عبد الملك هذا كلام ساقط سخيف جعل أمير المؤمنين ينفخ بالزق كأنه حداد وأبطل الكتاب ثم كتب محمد بن عبد الملك إلى عبد الله بن طاهر وأنت تجري أمرك على الأربح فالأربح والأرجح فالأرجح لا تسعى بنقصان ولا تميل برجحان فقال عبد الله الأصبهاني الحمد لله قد أظهر من سخافة اللفظ ما دل على رجوعه إلى صناعته من التجارة بذكره ربح السلع ورجحان الميزان ونقصان الكيل والخسران من رأس المال فضحك المعتصم\nوقال ما أسرع ما انتصف الأصبهاني من محمد وحقدها عليه ابن الزيات حتى نكبه أخبرني الأخفش عن المبرد قال نظر رجل كان يعادى يونس النحوي إليه وهو يهادى بين اثنين من الكبر فقال له يا أبا عبد الرحمن أبلغت ما أرى فعلم يونس أنه قال له\nذلك شامتا فقال هذا الذي كنت أرجو فلا بلغته فأخذه محمد بن عبد الملك الزيات فجعله في شعر فقال\n(وعائب عابني بشيب ... لم يعد لما ألم وقته)\n(فقلت إذ عابني بشيبي ... يا عائب الشيب لا بلغته)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":2,"spl":"رأيه في يحيى بن خاقان — سرق منديله فأنشد شعرا","tags":["محمد بن عبد الملك الزيات"],"loc":3812},
{"id":"b295-6","bab":"الجزء 23","sec":"سرق منديله فأنشد شعرا","page":"ج23 ص59","text":"وذكر أبو مروان الخزاعي أن أبا دهمان المغني سرق من محمد بن عبد الملك منديلا دبقيا فجعله تحت عمامته وبلغ محمدا فقال فيه\n(ونديم سارق خاتلني ... وهو عندي غير مذموم الخلق)\n(ضاعف الكور على هامته ... وطوى منديلنا طي الخرق)\n(يا أبا دهمان لو جاملتنا ... لكفيناك مؤونات السرق)\nخبرنا أبو مسلم محمد بن بحر الأصبهاني قال كنت عند أبي الحسين بن أبي البغل لما انصرف عن بغداد بعد إشخاصه إليها للوزارة وبطلان ما نذره من ذلك ورجوعه فجعل يحدثنا بخبره ثم قال لله در محمد بن عبد الملك الزيات حيث يقول\n(ما أعجب الشيء ترجوه فتحرمه ... قد كنت أحسب أني قد ملأت يدي)\n(مالي إذا غبت لم أذكر بصالحة ... وإن مرضت فطال السقم لم أعد)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":2,"spl":"رأيه في يحيى بن خاقان — سرق منديله فأنشد شعرا","tags":["محمد بن عبد الملك الزيات","الرواية والكتابة"],"loc":3813},
{"id":"b295-7","bab":"الجزء 23","sec":"تبادل المدح مع عبد الله بن العباس","page":"ج23 ص60","text":"أخبرني الصولي قال حدثني عون بن محمد الكندي قال حدثني\nعبد الله بن العباس بن الفضل بن الربيع قال وصفني محمد بن عبد الملك للمعتصم وقال ما له نظير في ملاحة الشعر والغناء والعلم بأمور الملوك فلقيته فشكرته وقلت جعلت فداءك أتصف شعري وأنت أشعر الناس ألست القائل\n(ألم تعجب لمكتئب حزين ... خدين صبابة وحليف صبر)\n(يقول إذا سألت به بخير ... وكيف يكون مهجور بخير)\nال وأين هذا من قولك\n(بقول لي كيف أصبحت ... كيف يصبح مثلي)\nاء ولا كصداء ومرعى ولا كالسعدان أخبرني الصولي قال حدثني عون بن محمد قال لقي الكنجي محمد بن عبد الملك فسلم عليه فلم يجبه فقال الكنجي\n(هذا وأنت ابن زيات تصغرنا ... فكيف لو كنت يا هذا ابن عطار)\nبلغ ذلك محمدا فقال كيف ينتصف من ساقط أحمق وضعه رفعه وعقابه ثوابه أخبرني الصولي قال أخبرني عبد الله بن محمد الأزدي قال حدثني يعقوب بن التمار قال قال محمد بن عبد الملك لبعض أصحابه ما أخرك عنا قال موت أخي قال بأي علة قال عضت أصبعه فأرة فضربته الحمرة فقال\nمحمد ما يرد القيامة شهيد أخس سببا ولا أنذل قاتلا ولا أضيع ميتة ولا أظرف قتله من أخيك","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":3,"spl":"تبادل المدح مع عبد الله بن العباس — رده على راشد الكاتب","tags":["محمد بن عبد الملك الزيات"],"loc":3814},
{"id":"b295-8","bab":"الجزء 23","sec":"أحمد بن أبي داود يحرض الشعراء على هجائه","page":"ج23 ص61","text":"أخبرني عمي عن ابي العيناء قال كان محمد بن عبد الملك يعادي أحمد بن أبي داود ويهجوه فكان أحمد يجمع الشعراء ويحرضهم على هجائه ويصلهم ثم قال فيه أحمد بيتين كانا أجود ما هجي به وهما\n(أحسن من خمسين بيتا سدى ... جمعك إياهن في بيت)\n(ما أحوج الناس إلى مطرة ... تذهب عنهم وضر الزيت)\nكان ابن أبي داود يقول ليس أحد من العرب إلا وهو يقدر على قول الشعر طبعا ركب فيهم قل قوله أو كثر","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":3,"spl":"تبادل المدح مع عبد الله بن العباس — رده على راشد الكاتب","tags":["محمد بن عبد الملك الزيات","الهجاء"],"loc":3815},
{"id":"b295-9","bab":"الجزء 23","sec":"قصيدة أبي تمام في مدحه","page":"ج23 ص62","text":"أخبرنا الصولي قال حدثنا محمد بن موسى عن الحسن بن وهب قال أنشد أبو تمام محمد بن عبد الملك قصيدته التي يقول فيها\n(لهان علينا أن نقول وتفعلا ... )\nفأثابه عليها ووقع عليه\n(رأيتك سهل البيع سمحا وإنما ... يغالى إذا ما ضن بالشيء بائعه)\n(فأما الذي هانت بضائع بيعه ... فيوشك أن تبقى عليه بضائعه)\n(هو الماء إن أحممته طاب ورده ... ويفسد منه أن تباح شرائعه)\nأجابه أبو تمام وقال\n(أبا جعفر إن كنت أصبحت شاعرا ... أسامح في بيعي له من أبايعه)\n(فقد كنت قبلي شاعرا تاجرا به ... تساهل من عادت عليك منافعه)\n(فصرت وزيرا والوزارة مكرع ... يغص به بعد اللذاذة كارعه)\n(وكم من وزير قد رأينا مسلطا ... فعاد وقد سدت عليه مطالعه)\n(ولله قوس لا تطيش سهامها ... ولله سيف لا تفل مقاطعه)\nدثني الصولي قال حدثني محمد بن يحيى بن عباد قال حدثني أبي قال حج محمد بن عبد الملك في آخر أيام المأمون فلما قدم كتب إليه راشد الكاتب قوله\n(لا تنس عهدي ولا مودتيه ... واشتق إلى طلعتي ورؤيتيه)\n(إن غبت عنا فلم تغب كثرة ... الذكر فلا تغفلن هديتيه)\n(التمر والنقل والمساويك والقسب ... وخير النعال حسن شيه)\n(فإن تجاوزت ما أقول إلى العصب ... فذاك المأمول منك ليه)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":3,"spl":"تبادل المدح مع عبد الله بن العباس — رده على راشد الكاتب","tags":["محمد بن عبد الملك الزيات","الرواية والكتابة"],"loc":3816,"partial":1},
{"id":"b295-10","bab":"الجزء 23","sec":"رده على راشد الكاتب","page":"ج23 ص63","text":"فأجابه محمد بن عبد الملك\n(إنك مني بحيث يطرد الناظر ... من تحت ماء دمعتيه)\n(ولا ومن زادني تودده ... على صحابي بفضل غيبتيه)\n(ما أحسن الترك والخلاف لما ... تريد مني وما تقول ليه)\n(يا بأبي أنت ما نسيتك في ... يوم دعائي ولا هديتيه)\n(ناجيت بالذكر والدعاء لك الله ... لدى البيت رافعا يديه)\n(حتى إذا ما ظننت بالملك القادر ... أن قد أجاب دعوتيه)\n(قمت إلى موضع النعال وقد ... أقمت عشرين صاحبا معيه)\n(وقلت لي صاحب أريد له ... نعلا ولو من جلود راحتيه)\n(فانقطع القول عند واحدة ... قال الذي اختار يا بشارتيه)\n(فقلت عندي لك البشارة والشكر ... وقلا في جنب حاجتيه)\n(ثم تخيرت بعد ذاك من العصب ... اليماني بفضل خبرتيه)\n(موشية لم أزل ببائعها ... أرغب حتى زها علي بيه)\n(يرفع في سومه وأرغبه ... حتى التقى زهده ورغبتيه)\n(وقد أتاك الذي أمرت به ... فاعذر بكثر الإنعام قلتيه)\nخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":3,"spl":"تبادل المدح مع عبد الله بن العباس — رده على راشد الكاتب","tags":["محمد بن عبد الملك الزيات","الحكمة والمواعظ"],"loc":3817},
{"id":"b295-11","bab":"الجزء 23","sec":"رثى برذونه بعد أن أخذه المعتصم منه","page":"ج23 ص64","text":"كان لمحمد بن عبد الملك برذون أشهب لم ير مثله فراهة وحسنا فسعى به محمد بن خالد حيلويه إلى المعتصم ووصف له فراهته\nفبعث المعتصم إليه فأخذه منه فقال محمد بن عبد الملك يرثيه\n(كيف العزاء وقد مضى لسبيله ... عنا فودعنا الأصم الأشهب)\n(دب الوشاة فأبعدوك وربما ... بعد الفتى وهو الأحب الأقرب)\n(لله يوم نأيت عني ظاعنا ... وسلبت قربك أي علق أسلب)\n(نفس مفرقة أقام فريقها ... ومضى لطيته فريق يجنب)\n(فالآن إذ كملت أداتك كلها ... ودعا العيون إليك لون معجب)\n(واختير من سر الحدائد خيرها ... لك خالصا ومن الحلي الأغرب)\n(وغدوت طنان اللجام كأنما ... في كل عضو منك صنج يضرب)\n(وكأن سرجك إذ علاك غمامة ... وكأنما تحت الغمامة كوكب)\n(ورأى علي بك الصديق جلالة ... وغدا العدو وصدره يتلهب)\n(أنساك لا زالت إذا منسية ... نفسي ولا زالت يميني تنكب)\n(أضمرت منك اليأس حين رأيتني ... وقوى حبالي من قواك تقضب)\n(ورجعت حين رجعت منك بحسرة ... لله ما فعل الأصم الأشيب)\nأخبرني محمد بن خلف بن المرزبان رضوان الله عليه قال حدثني محمد بن ناصح رحمة الله عليه قال لحقت غلات أهل البت آفة في أيام محمد بن عبد الملك من جراد وعطش فتظلم إليه جماعة منهم فوجه ببعض أصحابه ناظرا في أمرهم وكان في بصره ضعف فكتب إليه محمد بن علي البتي\n(أتيت أمرا يا أبا جعفر ... لم يأته بر ولا فاجر)\n(أغثت أهل البت إذ أهلكوا ... بناظر ليس له ناظر)\nبلغه فضحك ورد الناظر ووقع لهم بما سألوا بغير نظر","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":4,"spl":"رثى برذونه بعد أن أخذه المعتصم منه","tags":["محمد بن عبد الملك الزيات","اللهو والمزاح","الوصف والطبيعة"],"loc":3818},
{"id":"b295-12","bab":"الجزء 23","sec":"مساجلة بينه وبين علي بن جبلة","page":"ج23 ص66","text":"أخبرني الصولي رضي الله عنه قال حدثني محمد بن يحيى بن أبي عباد عن أبيه رضي الله عنهما قال قال علي بن جبلة يهجو محمد بن عبد الملك الزيات وكان قد قصد أبا دلف القاسم بن عيسى في بعض أمره\n(يا بائع الزيت عرج غير مرموق ... لتشغلن عن الأرطال والسوق)\n(من رام شتمك لم ينزع إلى كذب ... في منتماك وأبداه بتحقيق)\n(أبوك عبد وللأم التي فلقت ... عن أم رأسك هن غير محلوق)\n(إن أنت عددت أصلا لا تسب به ... يوما فأمك مني ذات تطليق)\n(ولن تطيق بحول أن تزيل شجا ... أثبته منك في مستنزل الريق)\n(الله أنشاك من نوك ومن كذب ... لا تعطفن إلى لؤم لمخلوق)\n(ماذا يقول امرؤ غشاك مدحته ... إلا ابن زانية أو فرخ زنديق)\nفأجابه محمد\n(اشمخ بأنفك ياذا السيء الأدب ... ما شئت واضرب قذال الأرض بالذنب)\n(وارفع بصوتك تدعو من بذي عدن ... ومن بقالي قلا بالويل والحرب)\n(ما أنت إلا امرؤ أعطى بلاغته ... فضل العذار ولم يربع على أدب)\n(فاجمح لعلك يوما أن تعض على ... لجم دلاصية تثنيك من كثب)\n(إني اعتذرت فما أحسنت تسمع من ... عذري ومن قبل ما أحسنت في الطلب)\n(صبرا أبا دلف في كل قافية ... كالقدر وقفا على الجارات بالعقب)\n(يا رب إن كان ما أنشأت من عرب ... شروى أبي دلف فاسخط على العرب)\n(إن التعصب أبدى منك داهية ... كانت تحجب دون الوهم بالحجب)\nأجابه علي بن جبلة\n(نبهت عن سنة عينيك فاصطبر ... واسحب بذيلك هل تقفو على أثر)\n(إن يرحض الله عني عار مطلبي ... إليك رفدا ألا فانجد به وغر)\n(إني ودعواك أن تأتي بمكرمة ... كمنبض القوس عن سهم بلا وتر)\n(فاردد جفونك حسرى عن أبي دلف ... ولا ملامة أن تعشى عن القمر)\n(لا يسخطن امرؤ إن ذل من حسب ... فالله أنزله في محكم السور)\n(لم آت سوءا ولم أسخط على أحد ... إلا على طلبي في مجتدى عسر)\n(أقصر أبا جعفر عن سطوة جمحت ... إن لم تقصر بها مالت إلى القصر)\nأجابه محمد بن عبد الملك\n(يا أيها العائبي ولم ير لي ... عيبا أما تنتهي فتزدجر)\n(هل لك وتر لدي تطلبه ... فأنت صلد ما فيك معتصر)\n(فالحمد والمجد والثناءلنا ... وللحسود التراب والحجر)\nهي طويلة يقول فيها\n(تعيش فينا ولا تلائمنا ... كما تعيش الحمير والبقر)\n(تغلي علينا الأشعار منك وما ... عندك نفع يرجى ولا ضرر)\nخبرني عمي رحمه الله قال حدثني عمر بن نصر الكاتب قال حدثني عمي علي بن الحسن بن عبد الأعلى قال محمد اجتاز بديع غلام عمير المأموني بمحمد بن عبد الملك الزيات وكان أحسن خلق الله وجها وكان محمد يحبه ويجن به جنونا فقال\n(راح علينا راكبا طرفه ... أغيد مثل الرشأ الآنس)\n(قد لبس القرطق واستمسكت ... كفاه من ذي برق يابس)\n(وقلد السيف على غنجه ... كأنه في وقعة الداحس)\n(أقول لما أن بدا مقبلا ... يا ليتني فارس ذا الفارس)\nخبرني الأخفش قال حدثني محمد بن يزيد قال دامت الأمطار بسر من رأى فتأخر الحسن بن وهب عن محمد بن عبد الملك الزيات وهو يومئذ وزير والحسن يكتب له فاستبطأه محمد بن عبد الملك فكتب إليه الحسن يقول\n(أوجب العذر في تراخي اللقاء ... ما توالى من هذه الأنواء)\n(لست أدري ماذا أقول وأشكو ... من سماء تعوقني عن سماء)\n(غير أني أدعو على تلك بالثكل ... وأدعو لهذه بالبقاء)\n(فسلام الإله أهديه غضا ... لك مني يا سيد الوزراء)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":5,"spl":"مساجلة بينه وبين علي بن جبلة","tags":["محمد بن عبد الملك الزيات","المديح"],"loc":3819},
{"id":"b295-13","bab":"الجزء 23","sec":"مساجلة بينه وبين الحسن بن وهب","page":"ج23 ص69","text":"أخبرني الصولي قال حدثنا محمد بن موسى قال أعتل الحسن بن وهب فتأخر عن محمد بن عبد الملك أياما كثيرة فلم يأته رسوله ولا تعرف خبره فكتب إليه الحسن قوله\n(أيهذا الوزير أيدك الله ... وأبقاك لي بقاء طويلا)\n(أجميلا تراه يا أكرم الناس ... لكيما أراه أيضا جميلا)\n(إنني قد أقمت عشرا عليلا ... ما ترى مرسلا إلي رسولا)\n(إن يكن موجب التعمد في الصحة ... منا علي منك طويلا)\n(فهو أولى يا سيد الناس برا ... وافتقادا لمن يكون عليلا)\n(فلماذا تركتني عرضة الظن ... من الحاسدين جيلا فجيلا)\n(ألذنب فما علمت سوى الشكر ... قرينا لنيتي ودخيلا)\n(أم ملال فما علمتك للصاحب ... مثلي على الزمان ملولا)\n(قد أتى الله بالشفاء فما ... أعرف مما أنكرت إلا قليلا)\n(وأكلت الدراج وهو غذاء ... أفلت علتي عليه أفولا)\n(بعد ما كنت قد حملت من العلة ... عبئا على الطباع ثقيلا)\n(ولعلي قدمت قبلك آتيك ... غدا إن وجدت فيه سبيلا)\nفأجابه محمد بن عبد الملك\n(دفع الله عنك نائبة الدهر ... وحاشاك أن تكون عليلا)\n(أشهد الله ما علمت وماذاك ... من العذر جائزا مقبولا)\n(ولعمري أن لو علمت فلازمتك ... حولا لكان عندي قليلا)\n(إنني أرتجي وإن لم يكن ما ... كان مما نقمت إلا جليلا)\n(أن أكون الذي إذا أضمر الإخلاص ... لم يلتمس عليه كفيلا)\n(ثم لا يبذل المودة حتى ... يجعل الجهد دونها مبذولا)\n(فإذا قال كان ما قال إذ كان ... بعيدا من طبعه أن يقولا)\n(فاجعلن لي إلى التعلق بالعذر ... سبيلا إن لم أجد لي سبيلا)\n(فقديما ما جاد بالصفح والعفو ... وما سامح الخليل الخليلا)\nال وكتب محمد بن عبد الملك إلى الحسن بن وهب وقد تأخر عنه\n(قالوا جفاك فلا عهد ولا خبر ... ماذا تراه دهاه قلت أيلول)\n(شهر تجذ حبال الوصل فيه فما ... عقد من الوصل إلا وهو محلول)\nال وكان محمد قد ندبه لأن يخرج في أمر مهم فأجابه الحسن فقال\n(إني بحول امريء أعليت رتبته ... فحظه منك تعظيم وتبجيل)\n(وأنت عدته في نيل همته ... وأنت في كل ما يهواه مأمول)\n(ما غالني عنك أيلول بلذته ... وطيبه ولنعم الشهر أيلول)\n(الليل لا قصر فيه ولا طول ... والجو صاف وظهر الكأس مرحول)\n(والعود مستنطق عن كل معجبة ... يضحي بها كل قلب وهو متبول)\n(لكن توقع وشك البين عن بلد ... تحله فوكاء العين محلول)\n(مالي إذا شمرت بي عنك مبتكرا ... دهم البغال أو الهوج المراسيل)\n(إلا رعاياتك اللاتي يعود بها ... حد الحوادث عني وهو مفلول)\nال وكان الحسن بن وهب يساير محمدا على مسناة فعدل عن المسناة لئلا يضيق لمحمد الطريق فظن محمد أنه أشفق على نفسه من المسناه فعدل عنها ولم يساعده على طريقه وظن بنفسه أن يصيبها ما يصيبه فقال له محمد\n(قد رأيناك إذ تركت المسناة ... وحاذيتني يسار الطريق)\n(ولعمري ما ذاك منك وقد جد ... بك الجد من فعال الشفيق)\nقال له الحسن\n(إن يكن خوفي الحتوف أراني ... أن تراني مشبها بالعقوق)\n(فلقد جارت الظنون على المشفق ... والظن مولع بالشفيق)\n(غرر السيد الأجل وقد سار ... على الحرف من يمين الطريق)\n(فأخذت الشمال بقيا على السيد ... إذ هالني سلوك المضيق)\n(إن عندي مودة لك حازت ... ما حوى عاشق من المعشوق)\n(طود عز خصصت منه ببر ... صار قدري به مع العيوق)\n(وبنفسي وإخوتي وأبي البر ... وعمي وأسرتي وصديقي)\n(من إذا ما روعت أمن روعي ... وإذا ما شرقت سوغ ريقي)\nأخبرني علي بن سليمان الأخفش والصولي قالا حدثنا المبرد قال استسقى الحسن بن وهب من محمد بن عبد الملك نبيذا ببلد الروم وهو مع المعتصم فسقاه وكتب إليه\n(لم تلق مثلي صاحبا ... أندى يدا وأعم جودا)\n(يسقى النديم بقفرة ... لم يسق فيها الماء عودا)\n(صفراء صافية كأن ... بكأسها درا نضيدا)\n(وأجود حين أجود لا ... حصرا بذاك ولا بليدا)\n(وإذا استقل بشكرها ... أوجبت بالشكر المزيدا)\n(خذها إليك كأنما ... كسيت زجاجتها عقودا)\n(واجعل عليك بأن تقوم ... بشكرها أبدا عهودا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":6,"spl":"مساجلة بينه وبين الحسن بن وهب","tags":["محمد بن عبد الملك الزيات","الوصف والطبيعة","الرواية والكتابة"],"loc":3820},
{"id":"b295-14","bab":"الجزء 23","sec":"شعر للحسن بن وهب في يوم لهوا به","page":"ج23 ص72","text":"أخبرني الصولي قال حدثني أحمد بن محمد الأنصاري قال حدثني هارون بن محمد بن عبد الملك قال دعا محمد بن عبد الملك قبل وزارته الحسن بن وهب في آخر أيام المأمون فجاءه ودخلا حماما له وأقاما على لهوهما ثم طلب الحسن بن وهب لعمل احتيج فيه إليه فمضى وبطل يومهم فكتب الحسن إليه\n(سقيا لنضر الوجه بسامه ... مهذب الأخلاق قمقامه)\n(تكسبه شكرا على أنها ... مطبقة السن للوامه)\n(زرناه في يوم علا قدره ... من سائر الأيام في عامه)\n(أسعده الله وأحظى به ... وجاده الغيث بإرهامه)\n(فكان مسرورا بنا باذلا ... لرحله الرحب وحمامه)\n(نخدمه وهو لنا خادم ... بفضله من دون خدامه)\n(ثم سقانا قهوة لم يدع ... أطيب منها بقرى شامه)\n(صهباء دلت على دنها ... وحدثت عن ضعف إسلامه)\nأجابه محمد بن عبد الملك رحمه الله تعالى\n(وزائر لذ لنا يومه ... لو ساعد الدهر بإتمامه)\n(ماذا لقينا من دواوينه ... وخطه فيها بأقلامه)\n(أسر ما كنا فمن مازح ... أو شارب قد عب في جامه)\n(فارقنا فالنفس مطروفة ... بواكف الدمع وسجامه)\n(وعاد بالمدح لنا منعما ... به إلى سالف إنعامه)\n(ليت وأنى لي بها منية ... لو كنت فيه بعض قوامه)\n(يشكر ما نال على أنه ... لا يشكر الحر لحمامه)\n(أمسحه فيه وأدنو له ... من خلفه طورا وقدمه)\n(جعلت نفس جنة للصبا ... وبعت إسلامي بإسلامه)\n(فصار ما يشرب حلا له ... وصرت مأخوذا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":7,"spl":"شعر للحسن بن وهب في يوم لهوا به — قوله لما قيد بالحديد","tags":["محمد بن عبد الملك الزيات","المديح","السفر والحج"],"loc":3821},
{"id":"b295-15","bab":"الجزء 23","sec":"قوله لما قيد بالحديد","page":"ج23 ص73","text":"أخبرني الحسن بن القاسم الكاتب قال سمعت القاسم بن\nيحدث عن أبيه قال قال أحمد الأحول لما قبض على محمد بن عبد الملك الزيات تلطفت في الوصول إليه فأريته في حديد ثقيل فقلت له أعزز علي ما أرى فقال\n(سل ديار الحي ما غيرها ... ومحاها ومحا منظرها)\n(وهي اللاتي إذا ما انقلبت ... صيرت معروفها منكرها)\n(إنما الدنيا كظل زائل ... نحمد الله كذا قدرها)\nي هذه الأبيات رمل طنبوري لا أدري لمن هو ومما يغنى فيه من شعر محمد بن عبد الملك الزيات\n(ظالمي ما علمته ... معتد لا عدمته)\n(مطمعي بالوصال ... ممتنع حين رمته)\n(مرصد بالخلاف ... والمنع من حيث سمته)\n(هاجر إن وصلته ... صابر إن صرمته)\n(كم وكم قد طويت ما ... بي وكم قد كتمته)\n(رب هم طويت فيك ... وغيظ كظمته)\n(وحياة سئمتها ... والهوا ما سئمته)\n(رمت شيئا هويته ... ليس لي ما حرمته)\n(قال إذ صرح البكاء ... بما قد سترته)\n(لو بكى طول دهره ... بدم ما رحمته)\nالغناء لأبي العبيس بن حمدون خفيف ثقيل بالبنصر\n\n(إذا أحببت لم أسل ... وإن واصلت لم أقطع)\n(وإن عاتبني الناس ... تصاممت فلم أسمع)\n(وقد جربت ما ضر ... وقد جربت ما ينفع)\n(فما مثل الهوى أنهك ... للجسم ولا أضرع)\n(ولا كالهجر في القرب ... إلى الموت ولا أسرع)\n(وإن أوجعني العذل ... فنيران الهوى أوجع)\n(وهذا عدم العقل ... فما أسطيع أن أصنع)\n(ولا والله ما عندي ... لما قد حل بي مدفع)\n(ولا في لهجرانك ... لولا ظلمكم موضع)\nلغناء لعريب لحنان خفيف ثقيل بالبنصر وهزج بالوسطى","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":7,"spl":"شعر للحسن بن وهب في يوم لهوا به — قوله لما قيد بالحديد","tags":["محمد بن عبد الملك الزيات"],"song":2,"loc":3822},
{"id":"b295-16","bab":"الجزء 23","sec":"امتداحه الحسن بن سهل","page":"ج23 ص75","text":"أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد قال حدثني الحسن بن رجاء قال قدم محمد بن عبد الملك على الحسن بن سهل إلى فم الصلح وامتدحه بقصيدته التي أولها\n(كأنها حين تناءى خطوه ... أخنس موشي الشوى يرعى القلل)\nوقال فيها\n(إلى الأمير الحسن استنجدتها ... أي مراد ومناخ ومحل)\n(سيف أمير المؤمنين المنتضى ... وحصن ذي الرياستين المقتبل)\n(آباؤك الغر الألى جدهم ... كسرى أنو شروان والناس همل)\n(من كل ذي تاج إذا قال مضى ... كل الذي قال وإن هم فعل)\n(فأين لا أين وأنى مثلكم ... أنتم الأملاك والناس خول)\nفأمر له بعشرة آلاف درهم قال ومرض الواثق فدخل إليه الحسن بن سهل عائدا ومحمد بن عبد الملك يومئذ وزيره والحسن بن سهل متعطل فجعل الحسن بن سهل يتكلم في العلة وعلاجها وما يصلح للواثق من الدواء والعلاج والغذاء أحسن كلام\nقال فحسده محمد بن عبد الملك وقال له من أين لك هذا العلم يا أبا محمد قال إني كنت أستصحب من أهل كل صنعة رؤساء أهلها وأتعلم منهم ثم لا أرضى إلا ببلوغ الغاية فقال له محمد وكان حسودا ومتى كان ذلك قال في زمان قلت في\n(فأين لا أين وأنى مثلكم ... أنتم الأملاك والناس خول)\nخجل محمد بن عبد الملك وأطرق وعدل عن الجواب أخبرني محمد بن خلف بن المرزبان قال حدثني حماد بن إسحاق قال حدثني ميمون بن هارون بن خلف قال كنت أسير بالقرب من محمد بن عبد الملك الزيات وهو يريد يومئذ منزله حتى مر بدار إبراهيم بن رباح فرأى فيها قبة مشيدة فقال\n(أما القباب فقد أراها شيدت ... وعسى أمور بعد ذاك تكون)\n(عبد عرت منه خلائق جهله ... إذ راح وهو من الثراء سمين)\nما كان إلا أيام حتى أوقع به","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":8,"spl":"امتداحه الحسن بن سهل — ابن أبي دواد يتحامل عليه ويكيد له","tags":["محمد بن عبد الملك الزيات","الرواية والكتابة"],"loc":3823},
{"id":"b295-17","bab":"الجزء 23","sec":"ابن أبي دواد يتحامل عليه ويكيد له","page":"ج23 ص77","text":"أخبرني عمي قال حدثني الحسن بن علي بن عبد الأعلى عن أبيه قال كان الواثق قد أصلح بين محمد بن عبد الملك الزيات وبين أحمد بن أبي دواد فكف محمد عن ذكره وجعل ابن أبي دواد يخلو بالواثق ويغريه به حتى قبض عليه وكان فيما بلغه عنه أنه قد عزم على الفتك به والتدبير عليه فقبض الواثق عليه ثم أطلقه بعد مدة ثم وزر للمتوكل وكان محمد بن عبد الملك أشار بابن الواثق وأشار ابن أبي دواد بالمتوكل وقام وقعد في أمره حتى ولي وعممه بيده وألبسه البردة وقبل بين عينيه وكان المتوكل قبل ذلك يدخل على محمد بن عبد الملك في حياة الواثق يشكو إليه جفاءه له فيتجهمه محمد ويغلظ له الرد إلى أن\nقال يوما بحضرته ألا تعجبون إلى هذا العاصي يعادي أمير المؤمنين ثم يسألني أن أصلح له قلبه اذهب ويلك فأصلح نفسك له حتى يصلح لك قلبه فكان موقع ذلك يحسن عند الواثق فدخل إليه يوما وقد كان\nقال للواثق إن جعفرا يدخل إلي وله شعر قفا وطرة مثل النساء فقد فضحك فأمره بأن يحلقهما ويضرب بشعرهما وجهه فلما دخل إليه المتوكل فعل ذلك به وتجهمه بالقبيح فلما ولي الخلافة خشي إن نكبه عاجلا أن يستتر أسبابه فتفوته بغيته فيه فاستوزره وخلع عليه وجعل ابن أبي دواد يغريه به ويجد عنده لذلك موقعا واستماعا حتى قبض عليه وقتله فلم\nيجد له من أملاكه كلها من عين وورق وأثاث وضيعة إلا ما كانت قيمته مائة ألف دينار فندم على ذلك ولم يجد منه عوضا وكان أمره مما يعتد على أحمد بن أبي دواد ويقول أطمعتني في باطل وحملتني على أمر لم أجد منه عوضا أخبرني محمد بن يحيى الصولي قال زعم محمد بن عيسى الفساطيطي أن محمد بن عبد الملك اجتاز بدندن الكاتب وعليه خلع الوزارة للمتوكل لما وزر له فقال دندن\n(راح الشقي بخلعة النكر ... مثل الهدي لليلة النحر)\n(لاتم شهر بعد خلعته ... حتى تراه طافي الجمر)\n(ويرى يطاين من إساءته ... يهوي له بقواصم الظهر)\nكان الامر كما قال","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":8,"spl":"امتداحه الحسن بن سهل — ابن أبي دواد يتحامل عليه ويكيد له","tags":["محمد بن عبد الملك الزيات"],"loc":3824},
{"id":"b295-19","bab":"الجزء 23","sec":"خبر قتله — رثاه الحسن بن وهب","page":"ج23 ص78 – ج23 ص79","text":"قال علي بن الحسين بن عبد الأعلى فلما قبض عليه المتوكل استعمل له تنور حديد وجعل فيه مسامير لا يقدر معها أن يتحرك إلا دخلت في جسده ثم أحماه له وجعله فيه فكان يصيح ارحموني فيقال له اسكت أنت كنت تقول ما رحمت أحدا قط والرحمة ضعف في الطبيعة وخور في المنة فاصبر على حكمك وخرج عليه عبادة فقال أردت أن تشويني فشووك\nأخبرني طاهر بن عبد الله بن طاهر الهاشمي قال قال العباس بن طومار أمر المتوكل عبادة أن يدخل إلى محمد بن عبد الملك الزيات وقد أحمى تنور حديد وجعله فيه فيكايده فدخل إليه فوقف بإزائه ثم\nقال اسمع يا محمد كان في جيراننا حفار يحفر القبور فمرضت مخنثة من جيراني وكانت صاحبة لي فبادر فحفر لها قبرا من الطمع في الدراهم فبرأت هي ومرض هو بعد أيام فدخلت إليه صاحبتي وهو بالنزع فقالت وي يا فلان حفرت لي قبرا وأنا في عافية أو ما علمت أنه من حفر بئر سوء وقع فيها وحياتك يا محمد لقد دفناه في ذلك القبر والعقبى لك قال فوالله ما برح من إزاء محمد بن عبد الملك يؤذيه ويكايده إلى أن مات قال الصولي\nوقال الحسن بن وهب يرثي محمد بن عبد الملك وكان في حياته ينتفي منها ويجحدها ثم شاعت بعد ذلك ووجدت بخطه\n(يكاد القلب من جزع يطير ... إذا ما قيل قد قتل الوزير)\n(أمير المؤمنين هدمت ركنا ... عليه رحاكم كانت تدور)\n(سيبلى الملك من جزع عليه ... ويخرب حين تضطرب الأمور)\n(فمهلا يا بني العباس مهلا ... فقد كويت بفعلكم الصدور)\n(إلى كم تنكبون الناس ظلما ... لكم في كل ملحمة عقير)\n(جزيتم ناصرا لكم المنايا ... وليس كذلكم يجزى النصير)\n(فكنتم سائقا أرسا إليكم ... وذلك من فعالكم شهير)\n(وكأن صلاحه لو شئتموه ... قريبا لا يحاوله البصير)\n(كأن الله صيركم ملوكا ... لئلا تعدلوا ولأن تجوروا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":9,"spl":"خبر قتله — رثاه الحسن بن وهب — أخبار أبي حشيشة","tags":["محمد بن عبد الملك الزيات"],"loc":3825},
{"id":"b295-20","bab":"الجزء 23","sec":"أخبار أبي حشيشة","page":"ج23 ص81","text":"أبو حشيشة لقب غلب عليه وهو محمد بن أمية بن أبي أمية يكنى أبا جعفر وكان أهله جميعا متصلين بإبراهيم بن المهدي وكان هو من بينهم معنيا بالطنبور يغني أحسن غناء وخدم جماعة من الخلفاء أولهم المأمون ومن بعده إلى المعتمد وله يقول أبو صالح بن يزداد وكتب بها في استتاره\n(جعلت فداك يا بن أبي أميه ... أرى الأيام قد حكمت عليه)\n(وملني الصديق وخان عهدي ... فما أقرا لكم كتبا إليه)\n(فإن كان الضمير كما بدالي ... فهذا والإله هو البليه)\nكان أكثر انقطاعه إلى أبي أحمد بن الرشيد أيام حياته وكان أبوه وجده وأخواله كتابا وقرأت على أحمد بن جعفر جحظة ما ذكره عن أبي حشيشة في كتابه الذي ألفه في أخبار مراتب الطنبوريين والطنبوريات وكان من ذلك أنه قال\nشاهدت أبا حشيشة مدة وكان يتغنى في أشعار خالد الكاتب وبني أمية وكانت معه فقر من الأحاديث يضعها مواضعها وكانت له صنعة تقدم فيها كل طنبوري لا أحاشي من قولي ذلك فمنها\n(كأن هموم الناس في الأرض كلها ... علي وقلبي بينهم قلب واحد)\n(ولي شاهدا عدل سهاد وعبرة ... وكم مدع للحب من غير شاهد)\nهو خفيف رمل مطلق قال جحظة ورأيته في القدمة التي قدمها مع ابن المدبر بين يدي المعتمد وقد غناه من شعر علي بن محمد بن نصر\n(حرمت بذل نوالك ... واسوأتا من فعالك)\n(لما مللت وصالي ... آيستني من وصالك)\nوهب له مائتي دينار واللحن رمل مطلق","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":9,"spl":"خبر قتله — رثاه الحسن بن وهب — أخبار أبي حشيشة","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3826},
{"id":"b295-21","bab":"الجزء 23","sec":"عريب تفضله على الشيخين","page":"ج23 ص82","text":"أخبرني حجظة فيما قرأته عليه قال حدثني ابن نوبخت يعني علي بن العباس قال رأيته وقد حضرت عريب عند ابن المدبر وهو يغني فقالت له عريب أحسنت يا أبا جعفر ولو عاش الشيخان ما قلت لهما هذا تعني علويه ومخارقا\nحدثني أبو حشيشة قال هجم علي خادم أسود فقال لي البس ثيابك فعلمت أن هذا لا يكون إلا عن أمر خليفة أو أمير فلم أراجعه حتى لبست ثيابي فمضيت معه فعبر بي الجسر وأدخلني إلى دار لا أعرفها ثم اجتاز بي في رواق فيه حجر تفوح منهن رائحة الطعام والشراب فأدخلت منهن إلى حجرة مفروشة وجاءني بمائدة كأنها جزعة يمانية قد نشرت في عراصها الحبرة فأكلت وسقاني رطلين وجاءني بصندوق ففتحه فإذا فيه طنابير فقال لي اختر فاخترت واحدا وأخذ بيدي فأدخلني إلى دار فيها سماعة وفيها رجلان على أحدهما قباء غليظ وعلى الآخر ثياب ملحم وخز فقال لي صاحب الخز اجلس فجلست فقال أكلت وشربت فقلت نعم قال عندنا قلت نعم قال تغني ما نقول لك فقلت له قل فقال تغني بصنعتك\n(يا كثير الإقبال والإنصراف ... وملولا ولو أشأ قلت خاف)\nهو رمل مطلق فغنيته إياه وجعل يطلب مني صوتا بعد صوت من صنعتي فأغنيه ويستعيده ويشرب هو والرجل وأسقى بالأنصاف المختوتة إلى أن صلوا العشاء الآخرة وهم لا يشربون إلا على الصوت الأول لا يريدون غيره ثم أومأ إلي الخادم قم فقمت فقال لي صاحب القباء منهما أتعرفني\nقلت لا والله قال أنا إسحاق بن إبراهيم الطاهري وهذا محمد بن راشد الخناق والله لئن بلغني أنك تقول إنك رأيتني لأضربنك مائتي سوط انصرف فخرجت ودفع إلى الخادم ثلاثمائة دينار فجهدت أن يقبل منها شيئا على سبيل البر فما فعل\nحدثني جحظة قال حدثني أبو حشيشة قال وجه إلي إسحاق بن إبراهيم الطاهري فصرت إليه وهو في داره التي على طرف الخندق فدعا بجونة فأكل وأكلت من ناحية ودعا بستارة وقال تغن بصنعتك\n(عاد الهوى بالكأس بردا ... فأطع إمارة من تبدى)\nهو خفيف رمل مطلق فغنيته مرارا ثم ضرب الستارة وقال قولوه فقالته جارية فأحسنت غاية الإحسان فضحك ثم قال كيف تراه فقلت قد والله بغضوه إلي فازداد في الضحك وأنا أرمق جبة خز خضراء كانت عليه فقال كم ترمق هذه الجبة يا غلام كانت عشرة أثواب خز فقطعت منها هذه الجبة فهات التسعة فجيء بها فدفعها إلي فكنت أبيع رذالها بستين دينار\nحدثني جحظة قال حدثني أبو حشيشة أن بني الجنيد الإسكافيين كانوا أول من اصطنعه وأنهم كانوا يسمونه الظريف وأن أول منزل ابتاعه من أموالهم إلى أن شاع خبره وتفاقم أمره\nقال وكانوا آكل الناس رأيت رجلا منهم وقد أكل هو وابن عم له اثنين وعشرين رأسا كبارا وشربا فسكرا وناما ثم انتبها في وقت الظهر فدعوا بالطعام فعادا إلى الأكل ما أنكر منهما شيئا","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":10,"spl":"عريب تفضله على الشيخين — أمر له المأمون بخمسين ألف درهم","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"loc":3827},
{"id":"b295-22","bab":"الجزء 23","sec":"أمر له المأمون بخمسين ألف درهم","page":"ج23 ص85","text":"ونسخت من كتاب ألفه أبو حشيشة وجمع فيه أخباره مع من عاشره وخدم من الخلفاء وهو كتاب مشهور قال أول من سمعني من الخلفاء المأمون وهو بدمشق وصفني له مخارق فأمر بأشخاصي إليه وأمر لي بخمسين ألف درهم أتجهز بها فلما وصلت إليه أدناني وأعجب بي\nوقال للمعتصم هذا ابن من خدمك وخدم آباءك وأجدادك يا أبا إسحاق جد هذا أمية كاتب جدك المهدي على كتابه السر وبيت المال والخاتم وحج المهدي أربع حجج كان جد هذا زميله فيها واشتهى المأمون من غنائي\n(كان ينهى فنهى حين انتهى ... وانجلت عنه غيابات الصبا)\n(خلع اللهو وأضحى مسبلا ... للنهى فضل قميص وردا)\n(كيف يرجو البيض من أوله ... في عيون البيض شيب وجلا)\n(كان كحلا لمآقيها فقد ... صار بالشيب لعينيها قذى)\nلشعر لدعبل والغناء لمحمد بن حسين بن محرز رمل بالوسطى قال أبو حشيشة وكان مخارق قد نهاني أن أغني ما فيه ذكر الشيب من هذا الشعر وأن اقتصر على البيتين الأولين لأن المأمون كان يشتد عليه ذكر الشيب ويكرهه جدا من المغنين وأمر ألا يغنيه أحد بشعر قيل في الشيب أو فيه ذكر له فسكرت يوما فمررت في الشعر كله فقال يا مخارق ألا تحسن أدب هذا الفتى فنقفني مخارق نقفة صلبة فما عدت بعدها لذكر\nشيء فيه الشيب","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":10,"spl":"عريب تفضله على الشيخين — أمر له المأمون بخمسين ألف درهم","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3828},
{"id":"b295-23","bab":"الجزء 23","sec":"الصوت الذي كان المعتصم يشتهيه","page":"ج23 ص86","text":"وذكر أبو حشيشة في كتابه هذا مما كان يشتهيه عليه المأمون وغيره من الخلفاء أصواتا كثيرة ولا فائدة في ذكرها ها هنا لأنها طويلة فذكرت مما كان يختاره عليه كل خليفة صوتا قال أبو حشيشة كان المعتصم يشتهي علي\n(أسرفت في سوء الصنيع ... وفتكت بي فتك الخليع)\n(وولعت بي متمردا ... والعذر في طرف الولوع)\n(صيرت حبك شافعا ... فأتيت من قبل الشفيع)\nلشعر لأصرم بن حميد والغناء لأبي حشيشة قال وكان الواثق يختار من غنائي\n(يا تاركي متلدد العواد ... جذلان العداة)\n(انظر إلي بعين راض ... نظرة قبل الممات)\n(خليتني بين الوعيد ... وبين ألسنة الوشاة)\n(ماذا يرجى بالحياة ... منغص روح الحياة)\nلشعر لمحمد بن سعيد الأسدي والغناء لأبي حشيشة خفيف رمل قال وكان المتوكل يحبني ويستخفني وكانت أغانيه التي يشتهيها علي كثيرة منها\n\n(أطعت الهوى وخلعت العذارا ... وباكرت بعد القراح العقارا)\n(ونازعك الكأس من هاشم ... كريم يحب عليها الوقارا)\n(فتى فرق الحمد أمواله ... يجر القميص ويرخي الإزارا)\n(رأى الله جعفر خير الأنام ... فملكه ووقاه الحذارا)\nلشعر والغناء لأبي حشيشة قال وكان الفتح بن خاقان يشتهي علي\n(قالوا عشقت فقلت أحسن من مشى ... والعشق ليس على الكريم بعار)\n(يامن شكوت إليه طول صبابتي ... فأجابني بتجهم الإنكار)\nال وكان المستعين يشتهي علي\n(وما أنس لا أنس منها الخشوع ... وفيض الدموع وغمز اليد)\n(وخدي مضافا إلى خدها ... قياما إلى الصبح لم نرقد)\nلشعر لمحمد بن أبي أمية والغناء لأبي حشيشة قال وأخبرني محمد بن علي بن عصمة وكان إليه الزهد في الدنيا كلها قال حضرت المعتز وقد ورد عليه جواب كتابه إلى محمد بن عبد الله بن\nطاهر وكان كتب إليه يطلبني منه فكتب إليه محمد إني عليل لا فضل في للخدمة قال أبو عصمة فقال لي المعتز يا أبا محمد صديقك أبو حشيشة يؤثر علينا آل طاهر فقلت له يا سيدي أنا أعلم الناس بخبره هو والله عليل ما فيه موضع لخدمة أمير المؤمين قال ثم ذكرني المعتمد وحرضه علي ابن حمدون فكتب إلي أبي أيوب سليمان بن عبد الله بن طاهر وهو يومئذ أمير بغداد في إشخاصي فشخصني إليه من ساعتي فأكرمني وأدنى في مجلسي وأمر لي بجائزة واشتهى علي\n(قلبي يحبك يا منى ... قلبي ويبغض من يحبك)\n(لأكون فردا في هواك ... فليت شعري كيف قلبك)\nلشعر لأحمد بن يوسف الكاتب والصنعة لأبي حشيشة رمل","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":11,"spl":"الصوت الذي كان المعتصم يشتهيه","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"song":4,"loc":3829},
{"id":"b295-24","bab":"الجزء 23","sec":"خبره مع إبراهيم بن المهدي","page":"ج23 ص88","text":"قال أبو حشيشة سمع إبراهيم بن المهدي أصواتا من غناء محمد بن الحارث بن بسخنر وعمرو بن بانة فاستحسنها وأخذها جواريه وقال الطنبور كله باطل فإن كان فيه شيء حق فهذا واشتهى أن يسمعني فهبته هيبة شديدة وقلت إن رضيني لم يزد ذلك في قدري وإن لم يرضني بقيت وصمة آخر الدهر وكان يطلبني من محمد بن الحارث بن بسخنر خاصة ومن إسحاق بن عمرو بن بزيع فكنت أفر منهما حتى صرت بسر من رأى وأنا في تلك الأيام منقطع إلى أبي أحمد بن الرشيد ونحن في مضارب لم نكن سكنا\nالمنازل بعد فوافى إلى أبي أحمد بن الرشيد رسول إبراهيم بن المهدي فأبلغه السلام وقال يقول لك عمك قد أعيتني الحيل في هذا الخبيث وأنا أحب أن أسمعه وهو يهرب مني فأحب أن تبعث به إلي ويكون زيرب معه تؤنسه فقال لي أبو أحمد لا بد أن تمضي إلى عمي فجهدت كل الجهد أن يعفيني فأبى فلما رأيت أنه لا بد لي منه لبست ثيابي ومضيت إليه وهو نازل في دسكرة فرحب بي وقرب وبسطني كل البسط ومعي زيرب ودعا بالنبيذ وأمر خدما له كبارا فجلسوا معي وشربوا وسقوني وعرض لي بكل حيلة أن أغني فهبته هيبة شديدة وحصرت وشرب ودعا بثلاث جوار فخرجن وجلسن وقال لهن قلن\n(كيف احتيالي وأنت لا تصل ... عيل اصطباري وقلت الحيل)\n(إن كان جسمي هواك ينحله ... فإن قلبي عليك يتكل)\nلشعر لخالد الكاتب والغناء لأبي حشيشة رمل وكان يسميه الرهباني عمله على لحن من ألحان النصارى سمعه من رهبان في الليل يرددونه فغناه عليه فقالته إحداهن فذهب عقلي وسمعت شيئا لم أسمع مثله قط فقال يا خليلي أهذا لك فقلت نعم أصلح الله الأمير وأخذتني رعدة ثم قال لهن إيه قلن\n(رب مالي وللهوى ... ما لهذا الهوى دوا)\n(حاز طرفي الذي هوى ... الحسن قلبي وما حوى)\nلشعر لخالد والغناء لأبي حشيشة رمل فغنته فسمعت ما هو أعجب من الأول فقال يا خليلي هذا لك قلت نعم يا سيدي قال هكذا أخذناهما من محمد بن الحارث ثم شرب رطلا آخر فقلت يا نفس دعاك الرجل يسمعك أو يسمعك وقويت عزمي وتغنيته بشعر خالد الكاتب وهو هذا\n(لئن لج قلبك في ذكره ... ولج حبيبك في هجره)\n(لقد أورث العين طول البكا ... وعز الفؤاد على صبره)\n(فإن أذهب القلب وجد به ... فجسمك لا شك في إثره)\n(وأي محب تجافى الهوى ... بطول التفكر لم يبره)\nفجعل يردد البيت الأول والبيت الأخير وقال لي لا تخرجن يا خليلي من هذا إلى غيره فلم أزل أردده عليه حتى شرب ثلاثا واسترحت ساعة وشربت وطابت نفسي ثم استعادني فغنيته فأعجب به خلاف الأول فنظر إلي وضحك ولم يقل شيئا وشرب رطلا رابعا وجاءت المغرب فقال لي يا خليلي ما أشك في أنك قد أوحشت ابني منك فامض في حفظ الله تعالى فخرجت أطير فرحا بانصرافي سالما فلما وافيت أبا أحمد وبصر بي من بعيد قال حنطة أو شعير فقلت بل سمسم وشهد انج على رغم أنف من رغم فقال ويحك أتراني لا أعرف فضلك ولكن أحببت أن أستعين برأيه\nعلى رأيي فيك وقصصت عليه القصة فسره ذلك ولم يرض حتى دس إليه محمد بن راشد الخناق فسأله عني فقال ما ظننت أن يكون في صناعته مثله قال أبو حشيشة وسمع إسحاق بن إبراهيم الموصلي غنائي فاستحسنه فسئل عني فقال غناء الطنبور كله ضعيف وما سمعت فيه قط أقوى ولا أصح من هذا","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":12,"spl":"خبره مع إبراهيم بن المهدي — موته","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"song":3,"loc":3830},
{"id":"b295-25","bab":"الجزء 23","sec":"موته","page":"ج23 ص91","text":"حدثني جحظة قال كان سبب موت أبي حشيشة بسر من رأى أن قلما غلام الفضل بن كاووس صار إليه في يوم بارد فدعاه إلى الصبوح فقال له أنا لا آكل إلا طعاما حارا وليس عندك إلا فضيلة من مجلية قال تساعدني وتأكل معي فأكل منها فجمدت دم قلبه فمات فحمله إبراهيم بن المدبر إلى بناته وما كسبه بسر من رأى معه فاقتسمنه بينهن\n(سقيا لقاطول لا أرى بلدا ... أوطنه الموطنون يشبهها)\n(أمنا وخفضا ولا كبهجتها ... أرغد أرض عيشا وأرفهها)\nلبيت الأول من البيتين لعنان جارية الناطفي والثاني يقال إنه لعمرو الوراق ويقال أنه لأبي نواس ويقال بل هو لها والغناء لعريب خفيف رمل وكان الشعر سقيا لبغداد فغيرته عريب وجعلت مكانه سقيا لقاطول","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":12,"spl":"خبره مع إبراهيم بن المهدي — موته","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3831},
{"id":"b295-27","bab":"الجزء 23","sec":"أخبار عنان — مساجلة بينها وبين أبي نواس","page":"ج23 ص91 – ج23 ص92","text":"كانت عنان مولدة من مولدات اليمامة وبها نشأت وتأدبت واشتراها الناطفي ورباها وكانت صفراء جميلة الوجه شكلة مليحة الأدب والشعر سريعة البديهة وكان فحول الشعراء يساجلونها ويقارضونها فتنتصف منهم\nأخبرني محمد بن جعفر الصيدلاني صهر المبرد النحوي وعلي بن صالح بن الهيثم قال حدثنا أبو هفان عن الجماز قال دخل أبو نواس يوما على عنان جارية الناطفي فتحدثا ساعة ثم قال لها قد قلت شعرا فقالت هات فقال\n(إن لي أيرا خبيثا ... لونه يحكي الكميتا)\n(لو رأى في الجو صدعا ... لنزا حتى يموتا)\n(أو رآه فوق سقف ... لتحول عنكبوتا)\n(أو رآه جوف بحر ... خلته في البحر حوتا)\nقال فما لبثت أن قالت\n(زوجوا هذا بألف ... وأظن الألف قوتا)\n(إنني أخشى عليه ... إن تمادى أن يموتا)\n(بادروا ما حل بالمسكين ... خوفا أن يفوتا)\n(قبل أن ينتكس الداء ... فلا يأتي ويوتى)\nال ودخل إليها يوما فقال\n(ماذا ترين لصب ... يريد منك قطيره)\nأجابته\n(إياي تعني بهذا ... عليك فاجلد عميره)\nقال لها\n(أريد هذا وأخشى ... على يدي منك غيره)\nال فخجلت وقالت تعست وتعس من يغار عليك أخبرنا أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني أبو أحمد بن معاوية قال سمعت أبا حنش يقول قال لي الناطفي لو جئت إلى عنان فطارحتها فعزمت على الغدو فبت ليلتين أحوك بيتين ثم غدوت عليها فقلت\n(أحب الملاح البيض قلبي وربما ... أحب الملاح الصفر من ولد الحبش)\n(بكيت على صفراء منهن مرة ... بكاء أصاب العين مني بالعمش)\nفقالت\n(بكيت عليها أن قلبي يحبها ... وأن فؤادي كالجناحين ذو رعش)\n(تغنيتنا بالشعر لما أتيتنا ... فدونك خذه محكما يا أبا حنش)\nخبرني أحمد قال حدثني عمر بن شبة قال حدثني أحمد بن معاوية قال سمعت مروان بن أبي حفصة يقول لقيني الناطفي فدعاني إلى عنان فانطلقت معه فدخل إليها قبلي فقال لها قد جئتك بأشعر الناس مروان بن أبي حفصة فوجدها عليلة فقالت له إني عن مروان لفي شغل فأهوى إليها بسوط فضربها به وقال لي ادخل فدخلت وهي تبكي فرأيت الدموع تنحدر من عينيها فقلت\n(بكت عنان فجرى دمعها ... كالدر إذ يسبق من خيطه)\nقالت وهي تبكي\n(فليت من يضربها ظالما ... تيبس يمناه على سوطه)\nقلت أعتق مروان ما يملك إن كان في الجن والإنس أشعر منها أخبرني الجوهري قال حدثنا أبو زيد عن أحمد بن معاوية قال قال لي رجل تصفحت كتبا فوجدت فيها بيتا جهدت جهدي أن أجد من يجيزه فلم أجد فقال لي صديق عليك بعنان جارية الناطفي فجئتها فأنشدتها\n\n(وما زال يشكو الحب حتى رأيته ... تنفس في أحشائه وتكلما)\nما لبثت أن قالت\n(ويبكي فأبكي رحمة لبكائه ... إذا ما بكى دمعا بكيت له دما)\nفي هذين البيتين لحن من الرمل أظنه لجحظة أو لبعض طبقته","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":13,"spl":"أخبار عنان — مساجلة بينها وبين أبي نواس — مولاها يطلب منها أن تعايي أحد الشعراء","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3832},
{"id":"b295-28","bab":"الجزء 23","sec":"مولاها يطلب منها أن تعايي أحد الشعراء","page":"ج23 ص95","text":"قرأت في بعض الكتب دخل بعض الشعراء على عنان جارية الناطفي فقال لها مولاها عاييه فقالت\n(سقيا لبغداد لا أرى بلدا ... يسكنه الساكنون يشبهها)\nقال\n(كأنها فضة مموهة ... أخلص تمويهها مموهها)\nقالت\n(أمن وخفض ولا كبهجتها ... أرغد أرض عيشا وأرفهها)\nانقطع أخبرني أحمد بن عبيد الله بن عمار قال حدثني ابن أبي سعيد قال\nحدثني مسعود بن عيسى قال أخبرني موسى بن عبد الله التميمي قال دخل أبو نواس على الناطفي وعنان جالسة تبكي وخدها على رزة من مصراع الباب وقد كان الناطفي ضربها فأومأ إلى أبي نواس أن يحركها بشيء فقال أبو نواس\n(عنان لو جدت لي فإني من ... عمري في آمن الرسول بما)\nردت عليه عنان\n(فإن تمادى ولا تماديت في ... قطعك حبلي أكن كمن ختما)\nرد عليها أبو نواس فقال\n(علقت من لو أتى على أنفس ... الماضين والغابرين ما ندما)\nردت عليه\n(لو نظرت عينها إلى حجر ... ولد فيه فتورهما سقما)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":13,"spl":"أخبار عنان — مساجلة بينها وبين أبي نواس — مولاها يطلب منها أن تعايي أحد الشعراء","tags":["محمد بن عبد الملك الزيات","الجواري والنساء"],"loc":3833},
{"id":"b295-29","bab":"الجزء 23","sec":"اصرارها على إعادة خاتمها من أبي نواس","page":"ج23 ص96","text":"أخبرني أبن عمار قال حدثني محمد بن القاسم بن مهرويه قال حدثني محمد بن أبي مروان الكاتب قال أخذ أبو نواس من عنان جارية الناطفي خاتما فصه أحمد فأخذه أحمد بن خالد حيلويه من أبي نواس فطلبته منه عنان فبعث إليها مكانه خاتما فصة أخضر فاتهمته في ذلك فكتب أبو نواس إلى أحمد بن خالد فقال\n(فدتك نفسي يا أبا جعفر ... جارية كالقمر الأزهر)\n(تعلقتني وتعلقتها ... طفلين في المهد إلى المكبر)\n(كنت وكانت نتهادى الهوى ... بخاتمينا غير مستنكر)\n(حنت إلى الخاتم مني وقد ... سلبتني إياه مذ أشهر)\n(فأرسلت فيه فغالطتها ... بخاتم في قده أخضر)\n(قالت لقد كان لنا خاتم ... أحمر أهداه إلينا سري)\n(لكنه علق غيري فقد ... أهدى له الخاتم لا أمتري)\n(كفرت بالله وآياته ... إن أنا لم أهجره فليصبر)\n(أو فأت بالمخرج من تهمتي ... إياه في خاتمنا الأحمر)\n(فاردده تردد وصلها إنها ... قرة عيني يا أبا جعفر)\n(فإنني متهم عندها ... وأنت قد تعلم أني بري)\nال فرد إليه الخاتم وبعث إليه معه بألفي درهم أخبرني ابن عمار وعلي بن سليمان الأخفش قال حدثنا محمد بن يزيد المبرد عن المازني عن الأصمعي\nوقال ابن عمار في خبره عن بعض أصحابه أظنه المازني عن الأصمعي قال ما رأيت أثر النبيذ في وجه الرشيد قط إلا مرة واحدة فإني دخلت إليه أنا وأبو حفص الشطرنجي فرأيت التخثر في وجهه فقال لنا استبقا إلى بيت بل إلى أبيات فمن أصاب ما في نفسي فله عشرة آلاف درهم قال فأشفقت ومنعتني هيبته قال فقال أبو حفص\n(كلما درات الزجاجة زادته ... اشتياقا وحرقة فبكاك)\nقال أحسنت فلك عشرة آلاف درهم\nقال فزالت الهيبة عني فقلت\n(لم ينلك الرجاء أن تحضريني ... وتجافت أمنيتي عن سواك)\nقال لله درك لك عشرون ألف درهم قال فأطرق مليا ثم رفع رأسه إلي فقال أنا والله أشعر منكما ثم قال\n(فتمنيت أن يغشيني الله ... نعاسا لعل عيني تراك)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":14,"spl":"اصرارها على إعادة خاتمها من أبي نواس — الأصمعي يصرف الرشيد عنها بعد أن طلبت زبيدة منه ذلك","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"loc":3834},
{"id":"b295-30","bab":"الجزء 23","sec":"الأصمعي يصرف الرشيد عنها بعد أن طلبت زبيدة منه ذلك","page":"ج23 ص98","text":"أخبرني ابن عمار والأخفش قالا حدثنا محمد بن يزيد عن المازني قال\nقال الأصمعي بعثت إلي أم جعفر أن أمير المؤمنين قد لهج بذكر هذه الجارية عنان فإن صرفته عنها فلك حكمك\nقال فكنت أريغ لأن أجد للقول فيها موضعا فلا أجده ولا أقدم عليه هيبة له إذ دخلت يوما فرأيت في وجهه أثر الغضب فانخزلت فقال مالك يا أصمعي\nقلت رأيت في وجه أمير المؤمنين أثر غضب فلعن الله من أغضبه فقال هذا الناطفي والله لولا أني لم أجر في حكم قط متعمدا لجعلت على كل جبل منه قطعة وما لي في جاريته أرب غير الشعر فذكرت رسالة أم جعفر فقلت له أجل والله ما فيها غير الشعر أفيسر أمير المؤمنين أن يجامع الفرزدق فضحك حتى استلقى واتصل قولي بأم جعفر فأجزلت لي الجائزة\nأخبرني عمي والحسن بن علي قالا حدثنا عمر بن محمد بن عبد الملك الزيات قال حدثني محمد بن هارون عن يعقوب بن إبراهيم\nأن الرشيد طلب من الناطفي جاريته فأبى أن يبيعها بأقل من مائة ألف دينار فقال أعطيك مائة ألف دينار على أن تأخذ بالدينار سبعة دراهم فامتنع عليه وأمر أن تحمل إليه فذكروا أنها دخلت مجلسه فجلست في هيئتها تنتظره فدخل عليها فقال لها ويلك إن هذا قد اعتاص علي في أمرك قالت وما يمنعك أن توفيه وترضيه فقال ليس يقنع بما أعطيه وأمرها بالإنصراف فبلغني أن الناطفي تصدق بثلاثين ألف درهم حين رجعت إليه فلم تزل في قلب الرشيد حتى مات مولاها فلما مات بعث مسرورا الخادم فأخرجها إلى باب الكرخ فأقامها على سرير وعليها رداء رشيدي قد جللها فنودي عليها من يزيد بعد أن شاور الفقهاء فيها\nوقال هذه كبد رطبة وعلى الرجل دين فأشاروا ببيعها قال فبلغني أنها كانت تقول وهي في المصطبة أهان الله من أهانني وأذل من أذلني فلكزها مسرور بيده وبلغ بها مسرور مائتي ألف درهم فجاء رجل فقال علي زيادة خمسة وعشرين ألف درهم فلكزه مسرور\nوقال أتزيد على أمير المؤمنين ثم بلغ بها مائتين وخمسين ألفا وأخذها له قال ولم يكن فيها شيء يعاب وطلبوا لها عيبا لئلا تصيبها العين فأوقعوا بخنصر رجلها شيئا وأولدها ابنين\nقال أظنهما ماتا صغيرين ثم خرج بها إلى خراسان فمات هناك وماتت عنان بعده قال وأنشدنا لأبي نواس في قصيدة يمدح بها يزيد بن مزيد ويذكر عنان في تشبيبها\n(عنان يا من تشبه العينا ... أنت على الحب تلومينا)\n(حسنك حسن لا أرى مثله ... قد ترك الناس مجانينا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":14,"spl":"اصرارها على إعادة خاتمها من أبي نواس — الأصمعي يصرف الرشيد عنها بعد أن طلبت زبيدة منه ذلك","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"loc":3835},
{"id":"b295-31","bab":"الجزء 23","sec":"مطارحة شعرية بينها وبين العباس بن الأحنف","page":"ج23 ص100","text":"أخبرني عمي قال حدثنا الحسن بن عليل العنزي قال حدثني أحمد بن القاسم العجلي قال حدثني أبو القاسم النخعي قال كان العباس بن الأحنف يهوى عنان جارية الناطفي فجاءني يوما فقال امض بنا إلى عنان جارية الناطفي فصرنا إليها فرأيتها كالمهاجرة له فجلسنا قليلا ثم ابتدأ العباس فقال\n(قال عباس وقد أجهد ... من وجد شديد)\n(ليس لي صبر على الهجر ... ولا لذع الصدود)\n(لا ولا يصبر للهجر ... فؤاد من حديد)\nقالت عنان\n(من تراه كان أغنى ... منك عن هذا الصدود)\n(بعد وصل لك مني ... فيه إرغام الحسود)\n(فاتخذ للهجر إن شئت ... فؤادا من حديد)\n(ما رأيناك على ما ... كنت تجني بجليد)\nقال العباس\n(لو تجودين لصب ... راح ذا وجد شديد)\n(وأخي جهل بما قد ... كان يجني بالصدود)\n(ليس من أحدث هجرا ... لصديق بسديد)\n(ليس منه الموت إن لم ... تصليه ببعيد)\nقال فقلت للعباس ويحك ما هذا الأمر قال أنا جنيت على نفسي بتتايهي عليها فلم أبرح حتى ترضيتها له أخبرني الحسن بن علي قال حدثنا الحارث بن يحيى بن حمد بن أبي مية قال حدثني يحيى بن محمد أن الرشيد كان يساوم بعنان جارية النطاف فبلغ ذلك أم جعفر فشق عليها فدست إلى أبي نواس أن يحتال في أمرها فقال يهجوها\n(إن عنان للنطاف جارية ... أصبح حرها للنيك ميدانا)\n(ما يشتريها إلا ابن زانية ... أو قلطبان يكون من كانا)\nبلغ ذلك الرشيد فكان يقول لعن الله أبا نواس وقبحه فلقد أفسد علي لذتي في عنان بما قال فيها ومنعني من شرائها\n(مالي وللخمر وقد أرعشت ... مني يميني هات باليسرى)\n(حتى تراني مائلا مسندا ... لا أستطيع الكأس بالأخرى)\nلشعر للحسن بن وهب والغناء لعبد الله بن العباس الربيعي خفيف ثقيل بالوسطى وفيه أيضا له خفيف رمل بالبنصر","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":15,"spl":"مطارحة شعرية بينها وبين العباس بن الأحنف — أخبار الحسن بن وهب — البحتري يجتاز بمنزله ويرثي","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3836},
{"id":"b295-33","bab":"الجزء 23","sec":"أخبار الحسن بن وهب — البحتري يجتاز بمنزله ويرثيه","page":"ج23 ص101 – ج23 ص102","text":"هو الحسن بن وهب بن سعيد كاتب شاعر مترسل فصيح أديب وأخوه سليمان بن وهب فحل من الكتاب ويكنى أبا علي وهو عريق في الكتابة ولأولاده نجابة مشهورة تستغني عن وصف ذلك وكانوا يقولون إنهم من بني الحارث بن كعب وأصلهم نصارى وفي بني الحارث نصارى كثير\nوفي الحسن بن وهب يقول البحتري\n(يا أخا الحارث بن كعب بن عمرو ... أشهورا تصوم أم أياما)\nكان البحتري مداحا لهم وله في الحسن وقد اجتاز بمنزله بعد وفاته\n(أناة أيها الفلك المدار ... أنهب ما تطرق أم جبار)\n(نزلنا منزل الحسن بن وهب ... وقد درست مغانيه القفار)\nيقول فيها يصف صبوحا كانوا قد اصطبحوه\n(أقمنا أكلنا أكل استلاب ... هناك وشربنا شرب يدار)\n(تنازعنا المدامة وهي صرف ... وأعجلنا الطبائخ وهي نار)\n(ولم يك ذاك سخفا غير أني ... رأيت الشرب سخفهم الوقار)\nخبرني الصولي وذكر ذلك عن جماعة من الكتاب أن الحسن بن وهب كان أشد تمسكا بالنسب إلى بني الحارث بن كعب من أخيه سليمان وكان سليمان ينكر ذلك ويعاتب عليه أخاه الحسن وابنه أحمد بن سليمان وأصلهم من قرية من سواد واسط في جسر سابور يقال لها سارقيقا","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":15,"spl":"مطارحة شعرية بينها وبين العباس بن الأحنف — أخبار الحسن بن وهب — البحتري يجتاز بمنزله ويرثي","tags":["محمد بن عبد الملك الزيات","الوصف والطبيعة","الخمر"],"loc":3837},
{"id":"b295-34","bab":"الجزء 23","sec":"كانوا يتسابقون لحفظ شعره","page":"ج23 ص103","text":"أخبرني عمي قال حدثني عمر بن نصر الكاتب وكان من مشايخ الكتاب بسر من رأى قال كنا نتهادى ونحن في الديوان أشعار الحسن بن وهب ونتباهى بحفظها قال وأنشدني له وكتب بها إلى أخيه سليمان بن وهب من مدينة السلام وهو محبوس في أيام الواثق\n(خطب أبا أيوب جل محله ... فإذا جزعت من الخطوب فمن لها)\n(إن الذي عقد الذي انعقدت به ... عقد المكاره فيك يحسن حلها)\n(فاصبر لعل الصبر يفتق ما ترى ... وعسى بها أن ينجلي ولعلها)\nال وكتب إليه أيضا وهو في الحبس بسر من رأى\n(خليلي من عبد المدان تروحا ... ونصا صدور العيس حسرى وطلحا)\n(فإن سليمان بن وهب ببلدة ... أصاب صميم القلب مني فأقرحا)\n(أسائل عنه الحارسين لحبسه ... إذا ما أتوني كيف أمسى وأصبحا)\n(فلا يهنئ الأعداء أسر ابن حرة ... يراه العدا أندى يمينا وأسمحا)\n(وأنهض للأمر الجليل بعزمة ... وأقرع للباب الأصم وأفتحا)\nخبرني محمد بن يحيى الصولي قال حدثني محمد بن موسى بن حماد قال وجه الحسن بن وهب إلى أبي تمام وهو بالموصل خلعا فيها خز وشي فامتدحه بقصيدة أولها\n(أبو علي وسمي منتجعه ... فاحلل بأعلى واديه أو جرعه)\nم وصف الخلعة فقال\n(وقد أتاني الرسول بالملبس الفخم ... لصيف امريء ومرتبعه)\n(لو أنها جللت أويسا لقد ... أسرعت الكبرياء في ورعه)\n(رائق خز أجيد سابره ... سكب تدين الصبا لمدرعه)\n(وسر وشي كأن شعري أحيانا ... نسيب العيون من بدعه)\n(تركتني ساهر الجفون على ... أزلم دهر بحسنها جذعه)\nعني الدهر والدهر يقال له الأزلم الجذع والأزلم الطويل\nالجذع الجديد يقول هو قديم سالف ويومه جديد قال لقيط الإيادي\n(يا قوم بيضتكم لا تفضحن بها ... إني أخاف عليها الأزلم الجذعا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":16,"spl":"كانوا يتسابقون لحفظ شعره — يتمثل ببيت لحسان بن ثابت","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"loc":3838},
{"id":"b295-35","bab":"الجزء 23","sec":"قوله بعد أن حبسه محمد بن عبد الملك","page":"ج23 ص105","text":"أخبري الصولي قال حدثنا محمد بن يزيد المبرد قال لما حبس محمد بن عبد الملك الزيات سليمان بن وهب وطالبه بالأموال وقت نكبته قال الحسن بن وهب\n(خليلي من عبد المدان تروحا ... ونصا صدور العيس حسرى وطلحا)\n(فإن سليمان بن وهب بمنزل ... أصاب صميم القلب مني فافرحا)\n(أسائل عنه الحارسين لحبسه ... اذا ما أتوني كيف أمسى وأصبحا)\n(فلا يهنىء الأعداء حبس ابن حرة ... يراه العدا أندى يمينا وأسمحا)\n(وقولا لهم صبرا قليلا وأصبحوا ... فما أقرب الليل البهيم من الضحا)\nقال وقيل له وسليمان محبوس كيف أصبحت قال أصبحت والله\nقليل النشاط كال القريحة صدىء الذهن ميت الخاطر من سوء فعل الزمان وتوارد الأحزان وتغير الإخوان قال وآلى ألا يذوق طعاما طيبا ولا يشرب ماء باردا ما دام أخوه محبوسا فوفى بذلك أخبرني الصولي قال أخبرني أبو الأسود قال كان للحسن بن وهب جار هاشمي يلقب بالطير فحج سنة من السنين ورجع آخر الناس فقال فيه الحسن\n(أينقص أم يزيد من الرقاعه ... أخو حمق له الدنيا مشاعه)\n(يحج على الجمال ولو تجلى ... لمكة جاءها في بعض ساعه)\nخبرني الصولي قال حدثنا الطالقاني قال حدثنا أحمد بن سليمان بن وهب قال رآني عمي الحسن وأنا أبكي لفراق بعض ألافي فقال\n(ابك فما أنفع ما في البكا ... لأنه للوجد تسهيل)\n(وهو إذا أنت تأملته ... حزن على الخدين محلول)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":16,"spl":"كانوا يتسابقون لحفظ شعره — يتمثل ببيت لحسان بن ثابت","tags":["محمد بن عبد الملك الزيات","السفر والحج"],"loc":3839},
{"id":"b295-36","bab":"الجزء 23","sec":"يتمثل ببيت لحسان بن ثابت","page":"ج23 ص106","text":"أخبرني الصولي قال حدثنا علي بن الصباح قال بلغ الحسن بن رجاء أن الحسن بن وهب عابه بحب الغلمان وكان الحسن بن وهب أشد حبا لهم منه فقال مثلي ومثله كما قال حسان بن ثابت\n(وإني لأغني الناس عن فضل صاحب ... يرى الناس ضلالا وليس بمهتد)\nخبرنا محمد قال حدثنا الحزنبل قال كتب رجل إلى الحسن بن وهب يستميحه فوقع في رقعته\n(الجود طبعي ولكن ليس لي مال ... فكيف يحتال من بالرهن يحتال)\nخبرني الحسن بن علي قال حدثني محمد بن موسى بن حماد قال","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":16,"spl":"كانوا يتسابقون لحفظ شعره — يتمثل ببيت لحسان بن ثابت","tags":["محمد بن عبد الملك الزيات","الرواية والكتابة"],"loc":3840},
{"id":"b295-37","bab":"الجزء 23","sec":"كان شديد الشغف بجارية اسمها بنات","page":"ج23 ص107","text":"كنت أكتب في حداثتي بين يدي الحسن بن وهب وكان شديد الشغف ببنات جارية محمد بن حماد كاتب راشد فكنا يوما عنده وهي تغني وبين أيدينا كانون فحم فتأذت به فأمرت أن يباعد فقال الحسن\n(بأبي كرهت النار حتى أبعدت ... فعلمت ما معناك في إبعادها)\n(هي ضرة لك بالتماع ضيائها ... وبحسن صورتها لدى إيقادها)\n(وأرى صنيعك في القلوب صنيعها ... في شوكها وسيالها وقتادها)\n(شركتك في كل الجهات بحسنها ... وضيائها وصلاحها وفسادها)\nخبرني الصولي قال حدثني الحسين بن يحيى قال كنا عند الحسن بن وهب فقال لو ساعدنا الدهر لجاءتنا بنات فما تكلم بشيء حتى دخلت فقال إني وإياك لكما قال علي بن أمية\n(وفاجأتني والقلب نحوك شاخص ... وذكرك ما بين اللسان إلى القلب)\n(فيا فرحة جاءت على إثر ترحة ... ويا غفلتا عنها وقد نزلت قربي)\nرأت في بعض الكتب دخلت يوما بنات على الحسن بن وهب وهو مخمور فسلمت عليه وقبلت يده فأراد تقبيل يدها فمنعته فرعش فقال\n(أقول وقد حاولت تقبيل كفها ... وبي رعدة أهتز منها وأسكن)\n(فديتك إني أشجع الناس كلهم ... لدى الحرب إلا أنني عنك أجبن)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":17,"spl":"كان شديد الشغف بجارية اسمها بنات — لومه على حبه بنات","tags":["محمد بن عبد الملك الزيات","الجواري والنساء"],"loc":3841},
{"id":"b295-38","bab":"الجزء 23","sec":"شرب على وجه بنات وكتب إلى مولاها","page":"ج23 ص108","text":"أخبرني الصولي قال حدثني محمد بن موسى قال جاءت بنات تسأل الحسن بن وهب من علة نالته فحين رآها دعا برطل فشربه على وجهها وقال قد عوفيت فأقيمي اليوم عندي فأبت وقالت عند مولاي دعوة فأمر بإحضار مائتي دينار فأحضرت فقال هذه مائة لمولاك فابعثي بها إليه ومائة لك فقالت أما هو فأبعث بمائة إليه وأما أنا فوالله لا أخذت المائة الأخرى ولأتصدقن بمثلها لعافيتك ولكن أكتب إليه رقعة تقوم بعذري فأخذ الدواة وكتب إلى مولاها\n(ضرة الشمس والقمر ... متعيني من النظر)\n(متعيني بجلسة ... منك يا أحسن البشر)\n(أشتريها إن بعتنيها ... بسمعي وبالبصر)\n(أذهب السقم سقم طرفك ... ذي الغنج والحور)\n(فأديمي السرور لا ... تمزجي الصفو بالكدر)\n(ليس يبقي علي حبك ... هذا ولا يذر)\n(وأنا منه فأنعمي ... بمقام على خطر)\n(وتغني فداك كل ... مغن لكي أسر)\n(ربع سلمى بذي بقر ... عرضة الريح والمطر)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":17,"spl":"كان شديد الشغف بجارية اسمها بنات — لومه على حبه بنات","tags":["محمد بن عبد الملك الزيات","الوصف والطبيعة"],"loc":3842},
{"id":"b295-39","bab":"الجزء 23","sec":"لومه على حبه بنات","page":"ج23 ص109","text":"حدثني أبو إسحاق بن الضحاك عن أحمد بن سليمان والحكايتان متفقتان متقاربتان أخبرني الصولي قال حدثني الحسين بن يحيى قال حدثني أحمد بن سليمان بن وهب قال قال لي أبي قد عزمت على معاتبة عمك في حبه لبنات فقد شهر بها وافتضج فكن معي وأعني عليه وكان هواي مع عمي فمضيت معه فقال لي أبي وقد أطال عتابه يا أخي جعلت فداك الهوى ألذ وأمتع والرأي أصوب وأنفع فقال عمي متمثلا\n(إذا أمرتك العاذلات بهجرها ... أبت كبد عما يقلن صديع)\n(وكيف أطيع العاذلات وحبها ... يؤرقني والعاذلات هجوع)\nالتفت إلي أبي ينظر ما عندي فتمثلت\n(وإني ليلحاني على فرط حبها ... رجال أطاعتهم قلوب صحائح)\nنهض أبي مغضبا وضمني عمي إليه وقبلني وانصرفت إلى بنات فحدثتها بما جرى وعمي يسمع فأخذت العود فغنت\n(يلومك في مودتها أناس ... لو أنهم برأيك لم يلوموا)\nيه ثقيل أول\nقال أحمد بن سليمان وعذلته عجوز لنا يقال لنا منى فقال لها قومي فانظري إليها واسمعي غناءها ثم لوميني فقامت معه فرأتها وسمعت غناءها فقالت له لست أعاود لومك فيها بعد هذا فأنشأ يقول\n(ويوم سها عنه الزمان فأصبحت ... نواظره قد حار عنها بصيرها)\n(خلوت بمن أهوى به فتكاملت ... سعود أدار النحس عنا مديرها)\n(أما تعذريني يا منى في صبابتي ... بمن وجهها كالشمس يلمع نورها)\nال أحمد بن سليمان كان لعمي كاتب يعرف بإبراهيم نصراني يأنس به فسأل بنات مسألتها عمي أن يجعل رزقه ألف درهم في الشهر فلما شرب أقداحا وطرب وثبت قائمة وقالت يا سيدي لي حاجة فوثب عمي فقام لقيامها فقالت تجعل رزق إبراهيم ألف درهم في الشهر فقال سمعا وطاعة فجلست فأنشأ يقول\n(قامت فقمت ولم أكن لو لم تقم ... لأجل خلقا غيرها فأقوما)\n(شفعت لإبراهيم في أرزاقه ... فوددت أني كنت إبراهيما)\n(فأجبتها إني مطيع أمرها ... وأراه فرضا واجبا محتوما)\n(ما كان أطيب يومنا وأسره ... لو لم يكن بفراقها مختوما)\nال ثم إن عمي صار إلى أبي فأخبره الخبر فأمر أن يجعل لإبراهيم من ماله ألف درهم أخرى لشفاعتها","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":17,"spl":"كان شديد الشغف بجارية اسمها بنات — لومه على حبه بنات","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"loc":3843},
{"id":"b295-40","bab":"الجزء 23","sec":"تأخرت بنات عن عيادته فكتب إليها","page":"ج23 ص110","text":"أخبرني الصولي قال حدثني إسماعيل بن الخطيب قال اعتل الحسن بن وهب فلم تعلم بنات بذلك وتأخرت عن عيادته فكتب إليها\n(عليل أنت أعللته ... فلو أنك عللته)\n(بوعد أن تزوريه ... إذا ما ممكن نلته)\n(قريبا لنفيت الداء ... عنه حين واعدته)\n(وما ضرك لو جاء ... رسول منك أرسلته)\n(فيحكي لك ما قال ... كما يحكي الذي قلته)\n(أما والله لو أن ... الذي يحمل حملته)\n(لما احتاج إلى التعليم ... فيما قد تجاهلته)\nخبرني الصولي قال أحمد بن إسماعيل قال حدثني أحمد بن عبيد الله بن جميل قال أهدى الحسن بن وهب إلى بنات في علة اعتلتها هدايا حسنة وأهدى معها قفص شفانين وكتب إليها\n(شفاء أنين بالشفانين أملت ... لكم نفس من أهدي الشفانين عامدا)\n(كلوها يكل الداء عنكم فإنني ... أزوركم للشوق لازرت عائدا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":18,"spl":"تأخرت بنات عن عيادته فكتب إليها — بينه وبين ابن الزيات","tags":["محمد بن عبد الملك الزيات"],"loc":3844},
{"id":"b295-41","bab":"الجزء 23","sec":"بنات تعتذر عن موافاته فيستحثها من جديد","page":"ج23 ص111","text":"أخبرني عمي قال حدثني ميمون بن هارون قال كتب الحسن بن وهب إلى بنات يوم جمعة يستدعيها فكتبت إليه أن عند مولاها أصدقاء له وقد منعها من المسير إليه فكتب إليها ثانيا يقول\n(يومنا يوم جمعة بأبي أنت ... وعند الوضيع لا كان قوم)\n(سفل مثله يسومونه الخسف ... ويرضاه وهو للوعد سوم)\n(فامنعيهم منك البشاشة حتى ... يتغشاهم من البرد نوم)\n(وليكن منك طول يومك لله ... صلاة إلى المساء وصوم)\n(وارفعي عنهم الغناء وإن نالك ... عذل من الوضيع ولوم)\n(واذكري مغرما بحبك أمسى ... همه أن يديله منك يوم)\nخبرني عمي قال حدثني ميمون بن هارون قال كان الحسن بن وهب يشرب عند محمد بن عبد الله بن طاهر فعرضت سحابة فبرقت ورعدت وقطرت فقال الحسن\n(هطلتنا السماء هطلا دراكا ... عارض المرزمان فيها السماكا)\n(قلت للبرق إذ تألق فيها ... يا زناد السماء من أوراكا)\n(أحبيبا نأيته فبكاكا ... فهو العارض الذي استبكاكا)\n(أم تشبهت بالأمير أبي العباس ... في جوده فلست كذاكا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":18,"spl":"تأخرت بنات عن عيادته فكتب إليها — بينه وبين ابن الزيات","tags":["محمد بن عبد الملك الزيات","اللهو والمزاح"],"loc":3845},
{"id":"b295-42","bab":"الجزء 23","sec":"بينه وبين ابن الزيات","page":"ج23 ص112","text":"أخبرني عمي قال حدثنا أبو العيناء قال طلب محمد بن عبد الملك الزيات الحسن بن وهب وكان قد اصطبح مع بنات فكتب إليه يا سيدي أنا في مجلس بهي وطعام هني وشراب شهي وغناء رضي أفأتحول عنه إلى كد الشقي ووثبت بنات لتقوم فردها وكتب\n(ما بان عنك الذي بنت ... عنه لا عاش بعدك)\n(إن لم يكن عنده الصبر ... والسلو فعندك)\n(وما وجدته إلا ... عبد الرجاء وعبدك)\nاستلبها الرسول ومضى بها إلى محمد فوقع فيها\n(أبا علي أراك الإله ... في الأمر رشدك)\n(إن لم تكن عندي اليوم ... كنت بالشوق عندك)\n(فاهدم محلك عندي ... واجهد لذلك جهدك)\n(فلست أزداد إلا ... رعاية لك ودك)\n(وانعم بمن قلت فيها ... عبد الرجاء وعبدك)\n(أزيل نحسك فيها ... وأطلع الله سعدك)\nرد الرقعة إلى الحسن فلما قرأها خجل وحلف ألا يشرب النبيذ شهرا ولا يفارق مجلس الوزير","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":18,"spl":"تأخرت بنات عن عيادته فكتب إليها — بينه وبين ابن الزيات","tags":["محمد بن عبد الملك الزيات","الجواري والنساء","الخمر"],"loc":3846},
{"id":"b295-43","bab":"الجزء 23","sec":"ولدت بنات من مولاها فأبغضها الحسن","page":"ج23 ص113","text":"أخبرني عمي عن إبراهيم بن المدبر قال ولدت بنات من مولاها ولدا وسمته بإبراهيم فأبغضها الحسن بن وهب وكتب إليها\n(نتج المهرة الهجان هجينا ... ثم سمى الهجين إبراهيما)\n(بخليل الرحمن سميت عبدا ... أم قريع الفتيان ذاك الكريما)\nبعث بالبيتين إليها وكان آخر عهده بها أخبرني الصولي قال حدثنا محمد بن موسى قال\nكان الحسن بن وهب يعشق غلاما روميا لأبي تمام وكان أبو تمام يعشق غلاما خزريا للحسن فرأى أبو تمام يوما الحسن يعبث بغلامه فقال له والله لئن أعنقت إلى الروم لنركضن إلى الخزر فقال له الحسن لو شئت لحكمتنا واحتكمت فقال له أبو تمام ما أشبهك إلا بداود ولا أشبه نفسي إلا بخصميه فقال له لو كان هذا منظوما حفظته فأما المنثور فهو عارض لا حقيقة له فقال أبو تمام\n(أبا علي لصرف الدهر والغير ... وللحوادث والأيام والعبر)\n(أعندك الشمس لم يحظ المغيب بها ... وأنت مضطرب الأحشاء للقمر)\n(أذكرتني أمر داود وكنت فتى ... مصرف القلب في الأهواء والذكر)\n(إن أنت لم تترك السير الحثيث إلى ... جآذر الروم أعنقنا إلى الخزر)\n(إن الغزال له مني محل هوى ... يحل مني محل السمع والبصر)\n(ورب أمنع منه جانبا وحمى ... أمسى ولكنه مني على خطر)\n(جردت منه جنود العزم فانكشفت ... منه غابتها عن تكة هدر)\n(سبحان من سبحته كل جارحة ... ما فيك من طمحان الأير والنظر)\n(أنت المقيم فما تعدو رواحله ... وأيره أبدا منه على سفر)\nال الصولي فحدثني أحمد بن إسحاق قال حدثني محمد بن إسحاق قال قلت لأبي تمام غلامك أطوع للحسن بن وهب من غلام الحسن لك قال أجل والله لأن غلامي يجد عنده ما لا يجده غلامه عندي\nوأنا أعطي غلامه قيلا وقالا وهو يعطي غلامي ثيابا ومالا","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":19,"spl":"ولدت بنات من مولاها فأبغضها الحسن — ابن الزيات يتجسس عليه","tags":["محمد بن عبد الملك الزيات","الهجاء","اللهو والمزاح"],"loc":3847},
{"id":"b295-44","bab":"الجزء 23","sec":"ابن الزيات يتجسس عليه","page":"ج23 ص115","text":"أخبرني الصولي قال حدثني أبو الحسن الأنصاري قال حدثني أبي وحدثني الفضل الكاتب المعروف بفتجاخ أن الحسن بن وهب كان يكتب لمحمد بن عبد الملك الزيات وهو وزير الواثق وكان ابن الزيات قد وقف على ما بين الحسن بن وهب وبين أبي تمام في غلاميهما فتقدم إلى بعض ولده وكانوا يجلسون عند الحسن بن وهب بأن يعلموه بخبرهما وما يكون بينهما\nقال وعزم غلام أبي تمام على الحجامة فكتب إلى الحسن يعلمه بذلك ويسأله التوجيه إليه بنبيذ مطبوخ فوجه إليه بمائة دن ومائة دينار وبخلعة حسنة وبخور كثير وكتب إليه\n(ليت شعري يا أملح الناس عندي ... هل تداويت بالحجامة بعدي)\n(دفع الله عنك لي كل سوء ... باكر رائح وإن خنت عهدي)\n(قد كتمت الهوى بمبلغ جهدي ... فبدا منه غير ما كنت أبدي)\n(وخلعت العذار فليعلم الناس ... بأني إياك أصفي بودي)\n(وليقولوا بما أحبوا إذا كنت ... وصولا ولم ترعني بصد)\n(من عذيري من مقلتيك ومن إشراق ... وجه من دون حمرة خد)\nقال ووضع الرقعة تحت مصلاه وبلغ محمد بن عبد الملك خبر الرقعة فوجه إلى الحسن فشغله بشيء من أمره وأمر من أخذ الرقعة من تحت مصلاه وجاءه بها فقرأها وكتب في ظهرها\n(ليت شعري عن ليت شعرك هذا ... أبهزل تقوله أم بجد)\n(فلئن كنت في المقال محقا ... يابن وهب لقد تغيرت بعدي)\n(وتشبهت بي وكنت أرى أني ... أنا العاشق المتيم وحدي)\n(أترك القصد في الأمور ولولا ... غمرات الهوى لأبصرت رشدي)\n(وأحب الأخ المشارك في الحب ... وإن لم يكن به مثل وجدي)\n(كنديمي أبي علي وحاشا ... لنديمي مثل شقوة وجدي)\n\n(إن مولاي عبد غيري ولولا ... شؤم جدي لكان مولاي عبدي)\n(سيدي سيدي ومولاي من ... أورثني ذلة وأضرع خدي)\nي هذين البيتين الأخيرين لحن من الرمل أظنه لجحظة أو غيره من طبقته قال ثم وضع الرقعة في مكانها فلما قرأها الحسن قال إنا لله افتضحنا عند الوزير وحدث أبا تمام بما كان ووجه إليه بالرقعة فلقيا محمد بن عبد الملك وقالا له إنما جعلنا هذين سببا للمكاتبة بالأشعار لا للريبة فتضاحك\nوقال ومن يظن بكما غير هذا فكان قوله أشد عليهما من الخبر قرأت في بعض الكتب كان الحسن بن وهب يعاشر أبا تمام عشرة متصلة فندب الحسن بن وهب للنظر في أمر بعض النواحي فتشاغل عن عشرة أبي تمام فكتب إليه أبو تمام\n(قالوا جفاك فلا عهد ولا خبر ... ماذا تراه دهاه قلت أيلول)\n(شهر كأن حبال الهجر منه فلا ... عقد من الوصل إلا وهو محلول)\nأجابه الحسن\n(ما عاقني عنك أيلول بلذته ... وطيبه ولنعم الشهر أيلول)\n(لكن توقع وشك البين عن بلد ... تحتله ووكاء العين محلول)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":19,"spl":"ولدت بنات من مولاها فأبغضها الحسن — ابن الزيات يتجسس عليه","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"song":1,"loc":3848},
{"id":"b295-45","bab":"الجزء 23","sec":"هجوه ابن أبي دواد والهيثم الغنوي","page":"ج23 ص117","text":"وقرأت فيه كان بين الحسن بن وهب وبين الهيثم الغنوي وأحمد بن أبي دواد تباعد فقال يهجوهما\n(سألت أبي وكان أبي خبيرا ... بسكان الجزيرة والسواد)\n(فقلت له أهيثم من غني ... فقال كأحمد بن أبي دواد)\n(فإن يك هيثم من جذم قيس ... فأحمد غير شك من إياد)\nخبرني عمي قال حدثني عمر بن نصر الكاتب قال كتب الحسن بن وهب إلى محمد بن معروف الواسطي يسأله أن يصير إليه فكتب إليه محمد\n(وقيتك كل مكروه بنفسي ... وبالأدنين من أهلي وجنسي)\n(أتأذن في التأخر عنك يومي ... على أن ليس غيرك لي بأنس)\nأجابه الحسن بن وهب فقال\n(أقم لا زلت تصبح في سرور ... وفي نعم مواصلة وتمسي)\n(فما لي راحة في حبس من لا ... أراه يكون محبوسا بحبسي)\nوكان الحسن يومئذ معتقلا في مطالبة يطالب بها","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":20,"spl":"هجوه ابن أبي دواد والهيثم الغنوي — كتب إلى بنات","tags":["محمد بن عبد الملك الزيات"],"loc":3849},
{"id":"b295-46","bab":"الجزء 23","sec":"كتب إلى الحسن بن إبراهيم في أمر بنات","page":"ج23 ص118","text":"وجدت في بعض الكتب بغير إسناد كان الحسن بن وهب يعشق بنات جارية محمد بن حماد الكاتب وكان له معها أخبار كثيرة وكان لا يصبر عنها فقدم الحسن بن إبراهيم بن رباح من البصرة وأتصل بها خبرها ووصفها له الحسن بن وهب وصار به إليها فأتم ليلته معها ومرت بينهما أعاجيب ثم خالفه الحسن بن إبراهيم بن رباح وخاتله في أمرها فكتب إليه الحسن بن وهب\n(لا جميل ولا حسن ... خنت عهدي ولم أخن)\n(كملت إذ فعلت ... هذا أعاجيب الزمن)\n(فإلى الله أشتكي ... ما بقلبي من الحزن)\n(رب شكوى من الصديق ... إلى غير ذي شجن)\n(بأبي أنت يا حسن ... يا أخا الطول والمنن)\n(أي رأي أراك ختلي ... في الشادن الأغن)\n(يتخطى إليه دوني ... في حالك الدجن)\n(فترى منه سنة ... تتعالى عن السنن)\n(مع كشفي لك الحديث ... الذي عنك لم يصن)\n(واعتمادي زعمت منك ... على أ حصن الجنن)\n(وعلى خير صاحب ... وعلى خير ما سكن)\n(خجلي من إساءة ... فضحت حسن كل ظن)\n(ثم ممن جرت إلى ... من وفيمن وعند من)\n(إن تكن تلك هفوة ... فهي كالشيء لم يكن)\n(أو تكن بعت خلتي ... بمواف من الثمن)\n(درة البحر من عدن ... ذخر سيف بن ذي يزن)\n(لم يكن قط مثلها ... في معد ولا عدن)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":20,"spl":"هجوه ابن أبي دواد والهيثم الغنوي — كتب إلى بنات","tags":["محمد بن عبد الملك الزيات","الجواري والنساء","الوصف والطبيعة"],"loc":3850},
{"id":"b295-47","bab":"الجزء 23","sec":"كتب إلى بنات","page":"ج23 ص119","text":"فتغافل عن جوابه وأقام على مواصلتها وسماعها وحظر عليها فلم يكن الحسن بن وهب يلقاها فغلظ ذلك عليه وكتب إليها بهذه الأبيات\n(أنكرت معرفتي جعلت لك الفدا ... إنكار سيدة تلاعب سيدا)\n(أنا ذو منعت جفونه أن ترقدا ... وتركته ليل التمام مسهدا)\n(وبريت لحم عظامه فتجردا ... وأزرت مضجعه النساء العودا)\n(انا ذو فإن لم تعرفيني بعد ذا ... فأنا ابن وهب ذو السماحة والندى)\n(أشكو إلى الله الفؤاد المقصدا ... وجوى ثوى تحت الحشا متلددا)\n(وغريرة ما كنت من إشفاقها ... يوما وإن بعد التلاقي مسعدا)\n(يا ظبية في روضة مولية ... جاد الربيع ترابها فتلبدا)\n(هل تجزين الود مني مثله ... أو تصدقين من المواعد موعدا)\n(إني وإن جعل القريض يجول بي ... حتى يغور بما أقول وينجدا)\n(لعلى يقين أن قلبك موجع ... عندي المثال أنا الحمى ولك الفدا)\n(وكما علمت إذا لبست المجسدا ... وثنيت خلف الأذن حاشية الردا)\n(وحبوت جيدك من حليك عسجدا ... ونظمت ياقوتا به وزبرجدا)\n(وشكوت وجدك في الغناء شكاية ... ينسي حنينا والغريض ومعبدا)\n(سيما إذا غنيتني بتعمد ... بأبي وأمي ذاك منك تعمدا)\n(أثوى فأقصر ليلة ليزودا ... ومضى وأخلف من قتيلة موعدا)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":20,"spl":"هجوه ابن أبي دواد والهيثم الغنوي — كتب إلى بنات","tags":["محمد بن عبد الملك الزيات"],"loc":3851},
{"id":"b295-48","bab":"الجزء 23","sec":"ابن رباح يكتب إليه","page":"ج23 ص120","text":"فوقعت الأبيات في يد ابن رباح فقرأها وعلم أنه قد بلغ منه فكتب إليه\n(فدى لك آبائي وحق بأن تفدى ... فدى لك قصدا من ملامك لي قصدا)\n(ولا تلحني في عثرة إن عثرتها ... فلا والذي أمسيت أدعى له عبدا)\n(وعهدك يا نفسي يقيك من الردى ... فأعظم به عندي وأكرم به عهدا)\n(يمين امريء بر صدوق مبرأ ... من الإثم ما حاولت هزلا ولا جدا)\n(سوى ما به أزداد عندك زلفة ... ويكسبني منك المودة والحمدا)\n(أرى الغي إن أومأت للغي طاعة ... لأمرك فضلا عن سوى الغي لي رشدا)\n(وأسعى لما تسعى وأتبع ما ترى ... وفي كل ما يرضيك أستغرق الجهدا)\n(إذا أنا لم أمنحك صفو مودتي ... فمن ذا الذي أصفي له غيرك الودا)\n(ومن ذا الذي أرعى وأشكر والذي ... يؤمل خيرا بعد مني أو رفدا)\n(وأنت ثمالي والمعول والذي ... أشد به أزري فيعصمني شدا)\n(وآثر خلق الله عندي ومن له ... أياد وود لست أحصيهما عدا)\n(فلا تحسبني مائلا عن خليقتي ... لك الدهر حتى أسكن القبر واللحدا)\n(معاذ إلهي ان أرى لك خاذلا ... ولكن عذري واضح أن بي وجدا)\n(بأحسن من أبصرت شخصا وصورة ... وأملح خلق الله كلهم قدا)\n(بمالكة امري وإن كنت مالكا ... لها ففؤادي ليس من حبها يهدا)\n(إذا سألتني أن أقيم عشية ... لأونسها لا أستطيع لها ردا)\n(تراشفني صفو المودة تارة ... وأجني إذا ما شئت من خدها وردا)\n(قبعت بها لما وثقت بحبها ... فلا زينبا أبغي سواها ولا هندا)\n(ولو بذلت لي جنة الخلد منزلا ... وقلت اجتنبها لاجتنبت لها الخلدا)\nفلما قرأها الحسن بن وهب علم أنه قد ندم فكتب إليه\n(حسن يشكو إلى حسن ... فقد طعم النوم والوسن)\n(وهوى أمست مطالبه ... قرنت باليأس في قرن)\n(وحبيب في محلته ... معه في الدار لم يبن)\n(فإذا ما رام زورته ... فهو كالغادين في الظعن)\n(عجبا للشمس لم ترها ... مقلتي حولا ولم ترني)\n(أتراها بعدنا صرمت ... حبنا هذا من اليمن)\n(فقديما كان مطلعها ... بيدي سيف بن ذي يزن)\nكتب إليه ابن رباح\n(حسن يفدي بمهجته ... حسنا من حادث الزمن)\n(ويقيه ما تضمنه ... من دخيل الهم والحزن)\n(هاك عيني فابك واقية ... عينك العبرى على الشجن)\n(وفؤادي فامله حزنا ... من صروف الهم والفتن)\n(إن تكن شمس الضحى حجبت ... عن سليل المجد من يمن)\n(فهي حيرى عن مطالعها ... في سوى قوام ابن ذي يزن)\nم اعتذر إليه ورجع إلى معاشرته وكان لا يحضر دار محمد بن حماد ولا يسمع غناء بنات جاريته إلا مع الحسن بن وهب لا يستأثر بها عليه وقال محمد بن داود الجراح\nحدثني بعض أصحابنا أن الحسن بن وهب أتى أبا إسحاق إبراهيم بن العباس مستعديا على أبي محمد الحسن بن مخلد في أمر بنات جارية محمد بن حماد وكان الحسن بن وهب يتعشقها فأفسدها عليه الحسن بن مخلد ولم يذكر محمد بن داود من خبرهما غير هذا وإنما ذكرت هذه القصة على قلة الفائدة فيها ليتضح خبره مع بنات إذ كان ما مضى ذكره من خبرها لم يقع إلي بروايته","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":21,"spl":"ابن رباح يكتب إليه — أبو تمام يستسقيه نبيذا","tags":["محمد بن عبد الملك الزيات"],"loc":3852},
{"id":"b295-49","bab":"الجزء 23","sec":"أبو تمام يستسقيه نبيذا","page":"ج23 ص122","text":"أخبرني محمد بن يحيى الصولي قال حدثني عبد الرحمن بن أحمد قال\nوجدت بخط محمد بن يزيد كتب أبو تمام إلى الحسن بن وهب يستسقيه نبيذا\n(جعلت فداك عبد الله عندي ... بعقب الهجر منه والبعاد)\n(له لمة من الكتاب بيض ... قضوا حق الزيارة والوداد)\n(وأحسب يومهم إن لم تجدهم ... مصادف دعوة منهم جماد)\n(فكم يوم من الصهباء سار ... وآخر منك بالمعروف غاد)\n(فهذا يستهل على غليلي ... وهذا يستهل على تلادي)\n(فيسقي ذا مذانب كل عرق ... وينزع ذا قرارة كل واد)\n(دعوتهم عليك وكنت ممن ... نعينه على العقد الجياد)\nال فوجه إليه بمائة دينار ومائة دن نبيذا قال محمد بن داود بن الجراح زار الحسن بن وهب وأبو تمام أبا نهشل بن حميد فبدأ أبو تمام فقال\n(أغصك الله أبا نهشل ... )\nم قال للحسن أجز فقال\n(بخد ريم شادن أكحل ... )\nم قال أجزيا أبا نهشل فقال\n(نطمع في الوصل فإن رمته ... صار مع العيوق في منزل)\nخبرني جعفر بن محمد بن قدامة بن زياد الكاتب قال\nكتب الحسن بن وهب إلى أبي تمام وقد قدم من سفر جعلت فداءك ووقاءك وأسعدني الله بما أوفى علي من مقدمك وبلغ الوطر كل الوطر بإنضمام اليد عليك وإحاطة الملك بك وأهلا وسهلا فقرب الله دارا قربتك وأحيا ركابا أدتك وسقى بلادا يلتقي ليلها ونهارها عليك وجعلك الله في أحصن معاقله وأيقظ محارسه وأبعدها على الحوادث مراما برحمته","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":21,"spl":"ابن رباح يكتب إليه — أبو تمام يستسقيه نبيذا","tags":["محمد بن عبد الملك الزيات","السفر والحج"],"loc":3853,"partial":1},
{"id":"b295-50","bab":"الجزء 23","sec":"رد تهمة السرقة عن أبي تمام","page":"ج23 ص124","text":"أخبرني الحسن بن علي قال حدثنا محمد بن موسى قال قال رجل للحسن بن وهب إن أبا تمام سرق من رجل يقال له مكنف من ولد زهير بن أبي سلمى وهو رجل من أهل الجزيرة قصيدته التي يقول فيها\n(كأن بني القعقاع يوم وفاته ... نجوم سماء خر من بينها البدر)\n(توفيت الآمال بعد محمد ... وأصبح في شغل عن السفر السفر)\nقال الحسن هذا دعبل حكاه وأشاعه في الناس وقد كذب وشعر مكنف عندي ثم أخرجه وأخرج هذه القصيدة بعينها فقرأها الرجل فلم يجد فيها شيئا مما قاله أبو تمام في قصيدته ثم دخل دعبل على الحسن بن وهب فقال له يا أبا علي بلغني أنك قلت في أبي تمام كيت وكيت فهبه سرق هذه القصيدة كلها وقبلنا قولك فيه أسرق شعره كله وأتحسن أنت أن تقول كما قال\n(شهدت لقد أقوت مغانيكم بعدي ... ومحت كما محت وشائع من برد)\n(وأنجدتم من بعد إتهام داركم ... فيا دمع أنجدني على ساكني نجد)\nفانخزل دعبل واستحيا فقال له الحسن الندم توبة وهذا الرجل قد توفي ولعلك كنت تعاديه في الدنيا حسدا على حظه منها وقد مات الآن فحسبك من ذكره فقال له أصدقك يا أبا علي ما كان بيني وبينه شيء قط إلا أني سألته أن ينزل لي عن شي استحسنته من شعره فبخل علي به وأما الآن فأمسك عن ذكره فجعل الحسن يضحك من قوله واعترافه بما اعترف به\nأخبرني الحرمي بن أبي العلاء قال حدثنا إسحاق بن محمد النخعي قال كتب إبراهيم بن محمد بن أبي محمد اليزيدي إلى محمد بن حماد الكاتب يهجوه ويعيره بعشق الحسن بن إبراهيم بن رباح والحسن بن وهب جاريته وتغايرهما عليها\n(لي خليطان محكمان يجيدان ... لما يعملانه حاذقان)\n(واحد يعمل القسي فيأتيك ... بها في استقامة الميزان)\n(وفتى يعمل السكاكين في القرن ... مقر بحذقه الثقلان)\n(وهما يطلبان قرنا على رأسك ... فانظر في بعض ما يسألان)\n(قلت هل يؤلم الفتى قطع ما ... فيه تريدان أيها الفتيان)\n(فأجابا بلطف قول وفهم ... قم فإنا إذا لنوكى مدان)\n(فاقطع الآن ما برأسك منها ... إن فيما ترى لمحض بيان)\n(ذاك خير من أن يسمى اسم سوء ... فيقال انظروا إلى القرنان)\n\n(قد كان عتبك مرة مكتوما ... فاليوم أصبح ظاهرا معلوما)\n(نال الأعادي سؤلهم لاهنئوا ... لما رأونا ظاعنا ومقيما)\n(والله لو أبصرتني لأديت لي ... والدمع يجري كالجمان سجوما)\n(هبني أسأت فعادة لك أن ترى ... متجاوزا متطاولا مظلوما)\nلشعر لأحمد بن يوسف الكاتب والغناء لعبيد بن الحسن الناطفي اللطفي ثاني ثقيل بالوسط وفيه خفيف رمل يقال إنه لرذاذ وفيه ثقيل أول مجهول","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":22,"spl":"رد تهمة السرقة عن أبي تمام — أخبار أحمد بن يوسف","tags":["محمد بن عبد الملك الزيات"],"song":1,"loc":3854},
{"id":"b295-51","bab":"الجزء 23","sec":"أخبار أحمد بن يوسف","page":"ج23 ص127","text":"هو أحمد بن يوسف بن صبيح الكاتب وأصله من الكوفة وكان مذهبه الرسائل والإنشاء وله رسائل معروفة وكان يتولى ديوان الرسائل للمأمون ويكنى أبا جعفر وكان موسى بن عبد الملك غلامه وخريجه فذكر محمد بن داود بن الجراح أن أحمد بن سعيد حدثه عن موسى بن عبد الملك\nقال وهب لي أحمد بن يوسف ألفي ألف درهم تفاريق عن ظهر يد وأخوه القاسم بن يوسف أبو محمد شاعر مليح الشعر وكان ينتمي إلى بني عجل ولم يكن أخوه أحمد يدعي ذلك وكان القاسم قد جعل وكده في مدح البهائم ومراثيها فاستغرق أكثر شعره في ذلك منها قوله يرثي شاة\n(عين بكي لعنزنا السوداء ... كالعروس الأدماء يوم الجلاء)\nقوله في الشاهمرك\n(أقفرت منك أبا سعد ... عراص وديار)\nقوله في السنور\n(ألا قل لمجة أو ماردة ... تبكي على الهرة الصائدة)\nقوله في القمري\n(هل لامرىء من أمان ... من طارق الحدثان)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":22,"spl":"رد تهمة السرقة عن أبي تمام — أخبار أحمد بن يوسف","tags":["محمد بن عبد الملك الزيات","المديح"],"loc":3855},
{"id":"b295-52","bab":"الجزء 23","sec":"تبنى جارية اسمها مؤنسة","page":"ج23 ص128","text":"أخبرني محمد بن خلف وكيع قال حدثنا عبد الله بن أبي سعد قال حدثني رجل من ولد عبد الملك بن صالح أن الهشامي قال كان أحمد بن يوسف قد تبنى جارية للمأمون اسمها مؤنسة فأراد المأمون أن يسافر ويحملها فكتب إليه أحمد بن يوسف بهذا الشعر على لسانها وأمر بعض المغنين فغناه به فلما سمعه وقرأ الكتاب أمر بإخراجها إليه وهو\n(قد كان عتبك مرة مكتوما ... )\nقال محمد بن داود حدثني أحمد بن أبي خيثمة الأطروش قال عتب أحمد بن يوسف على جارية له فقال\n(وعامل بالفجور يأمر بالبر ... كهاد يخوض في الظلم)\n(أو كطبيب قد شفه سقم ... وهو يداوي من ذلك السقم)\n(يا واعظ الناس غير متعظ ... نفسك طهر أولا فلا تلم)\nوجدت في بعض الكتب بلا إسناد عتب المأمون على مؤنسة فخرج\nإلى الشماسية متنزها وخلفها عند أحمد بن يوسف الكاتب فرجت أن يذكرها إذا صار في متنزهه فيرسل في حملها فلم يفعل وتمادى في عتبه فسألت أحمد بن يوسف أن يقول على لسانها شعرا ترفعه فقال\n(يا سيدا فقده أغرى بي الحزنا ... لا ذقت بعدك لا نوما ولا وسنا)\n(لا زلت بعدك مطويا على حرق ... أشنا المقام وأشنا الأهل والوطنا)\n(ولا التذذت بكأس في منادمة ... مذ قيل لي إن عبد الله قد ظعنا)\n(ولا أرى حسنا تبدوا محاسنه ... إلا تذكرت شوقا وجهك الحسنا)\nوبعثت به إلى إسحاق الموصلي فغناه به وقيل بل بعثت به إلى سندس فغنته به فاستحسن ذلك وقال لمن هذا الشعر فقال أحمد بن يوسف لمؤنسة يا سيدي تترضاك وتشكو البعد منك فركب من ساعته حتى ترضاها ورضي عنها","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":23,"spl":"تبنى جارية اسمها مؤنسة — تحلى قينة فكتب إلى مولاها","tags":["محمد بن عبد الملك الزيات"],"loc":3856,"partialRef":{"sid":"b295-50","gi":3,"vi":0,"side":0},"partial":1},
{"id":"b295-53","bab":"الجزء 23","sec":"تحلى قينة فكتب إلى مولاها","page":"ج23 ص129","text":"ووجدت في هذا الكتاب قال كنا مع أحمد بن يوسف الكاتب في مجلس وعندنا قينة فتحلاها أحمد بن يوسف فكتب إلى صاحب المنزل\n(أنا رهن للمنايا ... بين إبرام ونقض)\n(من هوى ظبي غرير ... مونق المنظر غض)\n(ليتها جادت بتقبيل ... لخديها وعض)\n(إن عجزتم عن شراها ... لي بفرض أو بقرض)\n(فتمنوا لي جميعا ... أنها قبر لبعضي)\nخبرني عمي قال حدثنا الحسن بن عليل قال ذكر مسعود بن أبي بشر أن أحمد بن يوسف دخل يوما على الفضل بن سهل أو أخيه في يوم دجن فأطال مخاطبته وكان أحمد بن يوسف آنسا به ففتح دواته وكتب إليه\n(أرى غيما تؤلفه جنوب ... وأحسبه سيأتينا بهطل)\n(فوجه الرأي أن تدعو برطل ... فتشربه وتدعو لي برطل)\nدفعها إليه فقرأهما وضحك وقال إن كان هذا عين الرأي قبلناه ولم نرده ثم دعا بالطعام والشراب فأتموا يومهم الغناء في هذين البيتين للقاسم بن زرزور ثاني ثقيل بالوسطى ومما يغنى فيه من شعره\n(صد عني محمد بن سعيد ... أحسن العالمين ثاني جيد)\n(ليس من جفوة يصد ولكن ... يتجنى لحسنه في الصدود)\nالغناء فيه لزرزور خفيف رمل ذكر ذلك إبراهيم بن القاسم بن زرزور عن أبيه ومحمد بن سعيد هذا كان من أولاد الكتاب بسر من رأى وكان أحمد يتعشقه ومن شعره الذي يغنى فيه\n(كم ليلة فيك لا صباح لها ... أحببتها قابضا على كبدي)\n(قد غصت العين بالدموع وقد ... وضعت خدي علىبنان يدي)\n(كأن قلبي إذا ذكرنكم ... فريسة بين ساعدي أسد)\nلغناء لشارية من رواية طباع وفيه خفيف رمل ذكر حبش أنه لأحمد النصيبي وهو خطأ يشبه أن يكون لأحمد بن صدقة أو بعض طبقته\n(الراح والندمان أحسن منظرا ... في كل ملتف الحدائق رائق)\n(فإذا جمعت صفاءه وصفاءها ... فارجم بكل ملمة من حالق)\nالشعر للعطوي والغناء لبنان ثقيل أول بالوسطى وفيه لذكاء وجه الرزة خفيف ثقيل","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":23,"spl":"تبنى جارية اسمها مؤنسة — تحلى قينة فكتب إلى مولاها","tags":["محمد بن عبد الملك الزيات"],"song":4,"loc":3857},
{"id":"b295-54","bab":"الجزء 23","sec":"أخبار العطوي","page":"ج23 ص132","text":"هو محمد بن عبد الرحمن بن أبي عطية مولى بني ليث بن بكر بن عبد مناة بن كنانة ويكنى أبا عبد الرحمن بصري المولد والمنشأ وكان شاعرا كاتبا من شعراء الدولة العباسية واتصل بأحمد بن أبي دواد وتقرب إليه بمذهبه وتقدمه فيه بقوة جداله عليه فلما توفي أحمد نقصت حاله وله فيه مدائح يسيرة ومراث كثيرة منها ما أنشدنيه الأخفش عن كوثرة أخي العطوي\n(حنطته يا نصر بالكافور ... وزففته للمنزل المهجور)\n(هلا ببعض خصاله حنطته ... فيضوع أفق منازل وقبور)\n(تالله لو من نشر أخلاق له ... يعزى إلى التقديس والتطهير)\n(حنطت من سكن الثرى وعلا الربا ... لتزودوه عدة لنشور)\n(فاذهب كما ذهب الوفاء فإنه ... ذهبت به ريحا صبا ودبور)\n(واذهب كما ذهب الشباب فإنه ... قد كان خير مصاحب وعشير)\n(والله ما أبنته لأزيده ... شرفا ولكن نفثه المصدور)\nوأنشدني الأخفش للعطوي أيضا يرثي أحمد بن أبي دواد قال\n(وليس صرير النمش ما تسمعونه ... ولكنه أصلاب قوم تقصف)\n(وليس نسيم المسك ريا حنوطه ... ولكنه ذاك الثناء المخلف)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":24,"spl":"أخبار العطوي — يأخذ قولا لعمر بن الخطاب ويحوله إلى شعر","tags":["محمد بن عبد الملك الزيات","المديح","الجواري والنساء"],"loc":3858},
{"id":"b295-55","bab":"الجزء 23","sec":"فاق جميع نظرائه","page":"ج23 ص132","text":"وذكر محمد بن داود في كتاب الشعراء فقال كان له فن من الشعر لم يسبق إليه ذهب فيه إلى مذهب أصحاب الكلام ففاق جميع نظرائه وخف شعره على كل لسان وروي واستعمله الكتاب واحتذوا معانيه وجعلوه إماما\nقال ابن داود وحدثني المبرد قال كان العطوي وهو عندنا بالبصرة لا ينطق بالشعر ثم ورد علينا شعره لما صار إلى سر من رأى وكنا نتهاداه وكان مقترا عليه رزقه دفرا وسخا منهوما بالنبيذ وله فيه في وصف الصبوح وذكر الندامى والمجالس أحسن قول وليس له قول يسقط فمن ذلك قوله\n(فيئي إلى أهدى السبل ... قولا وعلما وعمل)\n(قاتلها الله لقد ... سامتكما إحدى العضل)\n(تقول هلا رحلة ... تنقلنا خير نقل)\n(أخشى على جائلة الآمال ... جوال الأجل)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":24,"spl":"أخبار العطوي — يأخذ قولا لعمر بن الخطاب ويحوله إلى شعر","tags":["محمد بن عبد الملك الزيات","السفر والحج"],"loc":3859},
{"id":"b295-56","bab":"الجزء 23","sec":"يأخذ قولا لعمر بن الخطاب ويحوله إلى شعر","page":"ج23 ص133","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن يزيد قال سمع العطوي رجلا يحدث أن رجلا قال لعمر بن الخطاب إن فلانا قد\nجمع مالا فقال عمر بن الخطاب فهل جمع له أياما فأخذ العطوي هذا المعنى فقال\n(أرفه بعيش فتى يغدو على ثقة ... إن الذي قسم الأرزاق يرزقه)\n(فالعرض منه مصون لا يدنسه ... والوجه منه جديد ليس يخلقه)\n(جمعت مالا ففكر هل جمعت له ... يا جامع المال أياما تفرقه)\n(المال عندك مخزون لوارثه ... ما المال مالك إلا حين تنفقه)\nمن قوله في الندمان والنبيذ مما يغني فيه ما أنشدنيه الأخفش وغيره من شيوخنا\n(فكم قالوا تمن فقلت كاس ... يطوف بها قضيب في كثيب)\n(وندمان تساقطني حديثا ... كلحظ الحب أو غض الرقيب)\nلغناء في هذين البيتين لذكاء وجه الرزة خفيف رمل","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":24,"spl":"أخبار العطوي — يأخذ قولا لعمر بن الخطاب ويحوله إلى شعر","tags":["محمد بن عبد الملك الزيات","الحب والغزل"],"song":1,"loc":3860},
{"id":"b295-57","bab":"الجزء 23","sec":"يكتب لعلوي يستقيه نبيذا","page":"ج23 ص134","text":"أخبرني عمي قال حدثني كوثرة أخو العطوي قال كان أخي أبو عبد الرحمن يشرب مع أصدقاء له من الكتاب ومعهم قينة يقال لها مصباح من أحسن الناس وجها وأطيبهم غناء فما زالوا في قصف وعزف إلى أن انقطع نبيذهم فبقوا حيارى وكانوا قريبا من منزل أبي العباس أحمد بن الحسين بن موسى بن جعفر بن محمد العلوي وكان صديقا لأبي عبد الرحمن فكتب إليه\n(يابن من طاب في المواليد مذ ... آدم جرا إلى الحسين أبيه)\n(أنا بالقرب منك عند كريم ... قد ألحت عليه شهب سنيه)\n(عنده قينة إذا ما تغنت ... عاد منا الفقيه غير فقيه)\n(تزدهيني وأين مثلي في الفهم ... تغنيه ثم لا تزدهيه)\n(مجلس كالرياض حسنا ولكن ... ليس قطب السرور واللهو فيه)\n(فأقمه بما به يمتري دن عجوز خمارة ممتريه ... )\n(وبأشياخك الكرام إلى السؤدد ... موسى بن جعفر وأبيه)\n(إن تحشمتني وإن كان إلا ... مثل ما يأنس الفتى بأخيه)\nال فلما وصلت الرقعة إلى أبي العباس أرسل إليهم براوية شراب فلم يزالوا يشربون مجتمعين حتى نفدت في أخفض عيش حدثني أبو يعقوب إسحاق بن الضحاك بن الخصيب الكاتب\nقال جاءني يوما أبو عبد الرحمن العطوي بعد وفاة عمي أحمد بن الخصيب بسنتين وكان صديقه وصنيعته فجلس عندي يحادثني حديثه ويبكي ساعة طويلة ثم تغيمت السماء وهطلت فسألته أن يقيم عندي فحلف ألا يفعل إلا بعد أن أحضره من وقتي ما راج من الطعام ولا أتكلف له شيئا ففعلت وجئته بما حضر فقال لي ما فعلت عقد قلت باقية وهي في يومنا هذا مقيمة عندي والساعة تسمع غناءها فقال لي عجل إذن فإن النهار قصير ثم أنشأ يقول\n(أدر الكأس قد تعالى النهار ... ما يميت الهموم إلا العقار)\n(صاح هذا الشتاء فاغد عليها ... إن أيامه لذاذ قصار)\n(أي شيء ألذ من يوم دجن ... فيه كأس على الندامى تدار)\n(وقيان كأنهن ظباء ... فإذا قلن قالت الأوتار)","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":25,"spl":"يكتب لعلوي يستقيه نبيذا — وصف مجلس في يوم رذاذ","tags":["محمد بن عبد الملك الزيات","اللهو والمزاح","الخمر"],"loc":3861,"partial":1},
{"id":"b295-58","bab":"الجزء 23","sec":"وصف مجلس في يوم رذاذ","page":"ج23 ص136","text":"حدثني عمي قال حدثني كوثرة قال كان لأبي عبد الرحمن صديق من الأدباء وكان يتعشق جارية من جواري القيان يقال لها عثعث وكان لا يقدر عليها إلا على لقاء عسير واجتماع يسير فأرسل إليها يوما فأحضرها وأصلح جميع ما يحتاج إليه واتفق أن كان ذلك في يوم رذاذ به من الطيب والحسن ما الله به عليم فكتب إلى صديقه يعرفه الخبر ويسأله المصير إليه ووصف له القصة بشعر فقال\n(يوم مطير وعيش نضير ... وكأس تدور وقدر تفور)\n(وعثعث تأتي إذا جئتنا ... فتسمع منها غناء يصور)\n(وعندي وعندك ما تشتهيه ... شعر يمر وعلم يدور)\n(وإذا كان هذا كما قد وصفت ... فإن التفرق خطب كبير)\n(فقم نصطبح قبل فوت الزمان ... فإن زمان التلهي قصير)\nال فسار إليه صاحبه فمر لهما أحسن يوم وأطيبه وهذا الشعر أخذه العطوي من كلام إسحاق أخبرني به وسواسة بن الموصلي عن حماد عن أبيه قال كان يألفني بعض الأعراب وكان طيبا فجاءني يوما فقلت له لم أرك أمس فقال دعاني صديق لي فقلت صف لي ما كنتم فيه فقال لي كنا في مجلس نظامه سرور بين قدور تفور وكأس\nتدور وغناء يصور وحديث لا يجور وندامى كأنهم البدور قال إسحاق وقلت لأعرابي كان يألفني أين كنت بالأمس قال كنت عند بعض ملوك سر من رأى فأدخلني إلى قبة كإيوان كسرى وأطعمني في قصاع تترى وغنتني جارية سكرى تلعب بالمضراب كأنه مدرى فيا ليتني لقيتها مرة أخرى\nقال إسحاق وقلت لبعض الأعراب طلبتك أمس فلم أجدك فأين كنت قال كنت عند صديق لي فأطعمني بنات التنانير وأطعمني أمهات الأبازير وحلواء الطناجير وسقاني زعاف القوارير وأسمعني غناء الشادن الغرير على العيدان والطنابير قد ملكت بأوقار الدراهم والدنانير","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":25,"spl":"يكتب لعلوي يستقيه نبيذا — وصف مجلس في يوم رذاذ","tags":["محمد بن عبد الملك الزيات","الجواري والنساء"],"loc":3862},
{"id":"b295-59","bab":"الجزء 23","sec":"صديق يهدي إليه جواري ونبيذا","page":"ج23 ص137","text":"قرأت في بعض الكتب بغير إسناد أن العطوي كان يوما جالسا في منزله وطرقه صديق له ممن كان يغني بسر من رأى فقال له قد أهديت إليك جواري اليوم ونبيذا يكفيك وحسبك بالكفاية وأقام عنده فدخل عليه غلام أمرد أحسن من القمر فاحتبسوه وكتب العطوي إلى صديق له من أهل الأدب\n(يومنا طيب به حسن القصف ... وحث الأرطال والكاسات)\n(ما ترى البرق كيف يلمع فيه ... ورشاشا يبل في الساعات)\n(ولدينا ظبي غرير ظريف ... قد غنينا به عن القينات)\n(إن تخلفت بعد ما تصل الرقعة ... عنا فأنت في الأموات)\nأجابه الرجل فقال\n(أنا في إثر رقعتي فاعلمن ذاك ... على أنني من البيات)\n(فافهم الشرط بيننا لا تقل لي ... قد تثاقلت فانصرف بحياتي)\n(لا لسوء لكن لأمتع نفسي ... بحديث الظبي الغرير المواتي)\n\n(أيا بيت ليلى إن ليلى مريضة ... براذان لا خال لديها ولا ابن عم)\n(ويا بيت ليلى لو شهدتك أعولت ... عليك رجال من فصيح ومن عجم)\n(ويا بيت ليلى لا يبست ولا تزل ... بلادك سقياها من الواكف الديم)\nلشعر لمرة بن عبد الله النهدي والغناء لأحمد النصيبي ثقيل أول بالوسطى يقال إنه لحنين","topic":"أخبار محمد بن عبد الملك الزيات ونسبه","topicNo":295,"sp":26,"spl":"صديق يهدي إليه جواري ونبيذا","tags":["محمد بن عبد الملك الزيات","الجواري والنساء"],"song":1,"loc":3863},
{"id":"b296-2","bab":"الجزء 23","sec":"أخبار مرة ونسبه — هجا رجلا من بني نهشل لأنه خطب ليلى عشيقته","page":"ج23 ص138 – ج23 ص139","text":"هو مرة بن عبد الله بن هليل بن يسار أحد بني هلال بن عصم بن نصر بن مازن بن خزيمة بن نهد وليلى هذه من رهطه يقال لها ليلى بنت زهير بن يزيد بن خالد بن عمرو بن سلمة\nنسخت خبرها من كتاب ابن أبي السري قال حدثني ابن الكلبي عن أبيه قال كانت امرأة من بني نهد يقال لها ليلى بنت زهير بن يزيد وكان لها ابن عم يقال له مرة بن عبد الله بن هليل يهواها واشتد شغفه بها فخطبها وأبوا أن يزوجوه وكان لا يخطبها غيره إلا هجاه فخطبها رجل من بني نهشل يقال له إران فقال مرة يهجوه\n(وما كنت أخشى أن تصير بمرة ... من الدهر ليلى زوجة لإران)\n(لمن ليس ذا لب ولا ذا حفيظة ... لعرس ولا ذا منطق وبيان)\n(لقد بليت ليلى بشر بلية ... وقد أنزلت ليلى بدار هوان)\nقال فتزوجها المنجاب بن عبد الله بن مسروق بن سلمة بن سعد من بني زوي بن مالك بن نهد فخرج إلى البعث براذان وهي إذا ذاك مسلحة لأهل الكوفة فخرج بها معه فماتت براذان ودفنت هناك فقدم رجلان من بجيلة من مكتبهما براذان من بني نهد وكانت بجيلة جيران بني نهد بالكوفة فمرا على مجلسهم فسألوهما عمن براذان من بني نهد فأخبراهم بسلامتهم ونعيا إليهم ليلى ومرة في القوم فأنشأ يقول\n(أيا ناعيي ليلى أما كان واحد ... من الناس ينعاها إلي سواكما)\n(ويا ناعيي ليلى ألم نك جيرة ... عليكم لها حق فألا نهاكما)\n(ويا ناعيي ليلى لقد هجتما لنا ... تجاوب نوح في الديار كلاكما)\n(ويا ناعيي ليلى لجلت مصيبة ... بنا فقد ليلى لا أمرت قواكما)\n(ولا عشتما إلا حليفي بلية ... ولا مت حتى يشترى كفناكما)\n(فأشمت والأيام فيها بوائق ... بموتكما إني أحب رداكما)\nوقال فيها أيضا\n(كأنك لم تفجع بشيء تعده ... ولم تصطبر للنائبات من الدهر)\n(ولم تر بؤسا بعد طول غضارة ... ولم ترمك الأيام من حيث لا تدري)\n(سقى جانبي راذان والساحة التي ... بها دفنوا ليلى ملث من القطر)\n(ولا زال خصب حيث حلت عظامها ... براذان يسقى الغيث من هطل غمر)\n(وإن لم تكلمنا عظام وهامة ... هناك وأصداء بقين مع الصخر)\nقال فيها\n(يا قبر ليلى لا يبست ولا تزل ... بلادك تسقيها من الواكف الديم)\n(ويا قبر ليلى غيبت عنك أمها ... وخالتها والناصحون ذوو الذمم)\n(ويا قبر ليلى كم جمال تكنه ... وكم ضم فيك من عفاف ومن كرم)\nساق باقي الأبيات التي فيها الغناء وحكى الهيثم بن عدي عن شيخ من بني نهد أن مرة كان تزوجها وكان مكتبه براذان وأخرجها معه ثم ضرب عليه البعث إلى خراسان فخلفها عند شيخ من أهل منزله هناك وأفرد لها الشيخ دارا كانت فيها ومضى لبعثه ثم قدم بعد حول فلقي فتى من أهل راذان قبل وصوله إلى دارها فسأله عنها فقال أترى القبر الذي بفناء الدار قال نعم قال هو والله قبرها فجاء فأكب عليه يبكي ويندبها وترك مكتبه ولزم قبرها يغدو ويروح إليه حتى لحق بها\n(بأبي أنت يابن من ... لا أسمي لبعض ما)\n(يا شبيه الهلال مثلك ... في الأفق أنجما)\n(راقب الله في ... أسيرك إن كنت مسلما)\nلشعر لعلي بن أمية والغناء لعمر الميداني رمل مطلق","topic":"أخبار مرة ونسبه","topicNo":296,"sp":0,"spl":"أخبار مرة ونسبه — هجا رجلا من بني نهشل لأنه خطب ليلى عشيقته — أخبار علي بن أمية — يخاطب ال","tags":["الهجاء"],"song":1,"loc":3864},
{"id":"b296-4","bab":"الجزء 23","sec":"أخبار علي بن أمية — يخاطب الأطلال","page":"ج23 ص141 – ج23 ص142","text":"علي بن أمية بن أبي أمية وكان أبوه يكتب للمهدي على ديوان بيت المال وديواني الرسائل والخاتم وكان منقطعا إلى إبراهيم بن المهدي وإلى الفضل بن الربيع وقد تقدم خبر أخيه محمد في مواضع من هذا الكتاب\nفحدثني أحمد بن عبيد الله بن عمار قال حدثني عمر بن محمد بن عبد الملك الزيات قال حدثني محمد بن علي بن أمية قال لما قدم علي بن أمية وقال\n(يا ريح ما تصنعين بالدمن ... كم لك من محو منظر حسن)\n(محوت آثارنا وأحدثت ... آثارا بربع الحبيب لم تكن)\n(إن تك يا ربع قد بليت من ... الريح فإني بال من الحزن)\n(قد كان يا ربع فيك لي سكن ... فصرت إذ بان بعده سكني)\n(شبهت ما أبلت الرياح من ... آثار حبيبي الثأى بلا بدن)\n(يا ريح لا تطمسي الرموس ولا ... تمحي رسوم الديار والدمن)\n(حاشاك يا ريح أن تكون على ... العاشق عونا لحادث الزمن)","topic":"أخبار مرة ونسبه","topicNo":296,"sp":0,"spl":"أخبار مرة ونسبه — هجا رجلا من بني نهشل لأنه خطب ليلى عشيقته — أخبار علي بن أمية — يخاطب ال","tags":["الحب والغزل","الوصف والطبيعة"],"song":1,"loc":3865},
{"id":"b296-5","bab":"الجزء 23","sec":"أبو موسى الأعمى يندم على شعر قاله","page":"ج23 ص143","text":"كثر الناس فيه وغناه عمرو الغزال فقال أبو موسى الأعمى\n(يا رب خذني وخذ عليا وخذ ... يا ريح ما تصنعين بالدمن)\n(عجل إلى النار بالثلاثة والرابع ... عمرو الغزال في قرن)\nم ندم وقال هؤلاء أهل بيت وهم إخوتي ولا أحب أن أنشب بيني وبينهم عداوة وشرا فأتى أمية فقال إني قد أذنبت فيما بيني وبينكم ذنبا وقد جئتك مستجيرا بك من فتيانك فدعا بعلي بن أمية فقال يا هذا عمك أبو موسى قد أتاك معتذرا من الشعر الذي قاله قال وما هو فأنشده فقال قد ضجرنا نحن والله منه كما ضجرت أنت وأكثر وأنت آمن من أن يكون منا جواب وأتى محمد بن أمية فقال له مثل ذلك ومضى أبو موسى فأخذ علي بن أمية رقعة فكتب فيها\n(كم شاعر عند نفسه فطن ... ليس لدينا بالشاعر الفطن)\n(قد أخرجت نفسه بغصتها ... يا ريح ما تصنعين بالدمن)\nدفع الرقعة إلى غلام له وقال ادفعها إلى غلام أبي موسى وقل له يقول لك مولاك اذكرني بهذا إذا انصرفت إلى المنزل فلما انصرف إلى المنزل أتاه غلامه بالرقعة فقال ما هذه فقال التي بعثت بها إلي فقال\nوالله ما بعثت إليك رقعة وأظن الفاسق قد فعلها ثم دعا ابنه فقرأها عليه فلما سمع ما فيها قال يا غلام لا تنزع عن البغلة فرجع إلى علي بن أمية فقال نشدتك الله أن تزيد على ما كان فقال له أنت آمن لحن عمرو الغزال في أبيات علي بن أمية رمل بالوسطى\nوقال يوسف بن إبراهيم حدثني إبراهيم بن المهدي قال حدثني محمد بن أيوب المكي أنه كان في خدمة عبيد الله بن جعفر بن المنصور وكان مستخفا لعمرو الغزال محبا له وكان عمرو يستحق ذلك بكل شيء إلا ما يدعيه ويتحقق به من صناعة الغناء وكان ظريفا أديبا نظيف الوجه واللباس معه كل ما يحتاج إليه من آلة الفتوة وكان صالح الغناء ما وقف بحيث يستحق ولم يدع ما يستحقه وأنه كان عند نفسه نظير ابن جامع وإبراهيم وطبقتهما لا يرى لهم عليه فضلا ولا يشك في أن صنعتهم مثل صنعته وكان عبيد الله قليل الفهم بالصناعة فكان يظن أنه قد ظفر منه بكنز من الكنوز فكان أحظى الناس عنده من استحسن غناء عمرو الغزال وصنعته ولم يكن في ندمائه من يفهم هذا ثم استزار عبيد الله بن جعفر أخاه عيسى وكان أفهم منه فقلت له استعن برأي أخيك في عمرو الغزال إنه أفهم منك وكانت أم جعفر كثيرا ما تسأل الرشيد تحويل أخيها عبيد الله وتقديمه والتنويه به فكان عيسى أخوه يعرف الرشيد أنه ضعيف عاجز لا يستحق ذلك فلما زاره عيسى أسمعه غناء عمرو\nفسمع منه سخنة عين فأظهر من السرور والطرب أمرا عظيما ليزيد بذلك عبيد الله بصيرة فيه ويجعله عيسى سببا قويا يشهد عند الرشيد بضعف عقله وعلمت ما أراد وعرفت أن عمرا الغزال أول داخل على الرشيد فلما كان وقت العصر من اليوم الثاني لم نشعر إلا برسول الرشيد قد جاء يطلب عمرا الغزال فوجه إليه وأقبل يلومني ويقول ما أظنك إلا قد فرقت بيني وبين عمرو وكنت غنيا عن الجمع بينه وبين عيسى واتفق أن غنى عمرو الرشيد في هذا الشعر صنعته\n(يا ريح ما تصنعين بالدمن ... كم لك من محو منظر حسن)\nكان صوتا خفيفا مليحا فأطربه ووصله بألف دينار وصار في عداد مغني الرشيد إلا أنه كان يلازم عبيد الله إذا لم يكن له نوبة فأقبلت أتعجب من ذلك واتصلت خدمته إياه ثلاث سنين ثم انصرفا يوما من الشماسية مع عبيد الله بن جعفر فلقيه الخضر بن جبريل وكان في الناس في العسكر فعاتبه عبيد الله على تركه وانقطاعه عنه فقال والله ما أفعل ذلك جهلا بحقك ولا إخلالا بواجبك ولكنا في طريقين متباينين لا يمكن معهما الإجتماع\nقال وما هما ويحك قال أنت على نهاية السرف في محبة عمرو الغزال وأنا على نهاية السرف في بغضه وأنت تتوهم أنه لا يطيب لك عيش إلا به وأنا أتوهم أني إن عاشرته ساعة مت وتقطعت نفسي غيظا وكمدا وما يستقيم مع هذا بيننا عشرة أبدا فقال له عبيد الله إذا كان هذا هكذا فأنا أعفيك منه إذا زرتني فصر إلي آمنا ولم يجلس عبيد الله حتى\nقال لحاجبه لا تدخل اليوم أحدا ولا تستأذن علي لجلوسه ودخلنا فلما وضعت المائدة لم يأكل ثلاث لقم حتى دخل الحاجب فوقف بين يديه وأقبل عمرو الغزال خلفه فرآه من أقصى","topic":"أخبار مرة ونسبه","topicNo":296,"sp":1,"spl":"أبو موسى الأعمى يندم على شعر قاله","tags":[],"loc":3866},
{"id":"b296-6","bab":"الجزء 23","sec":"أبو موسى الأعمى يندم على شعر قاله","page":"ج23 ص143","text":"الصحن فقال له عبيد الله ثكلتك أمك ألم أقل لك لا تدخل علي أحدا من خلق الله فقال له الحاجب امرأته طالق ثلاثا إن كان عنده أن عمرا عندك في هذا المجرى ولو جاء جبريل وميكائيل وكل من خلق الله لم يدخلوا عليك إلا بإذن سوى عمرو فإنك أمرتني أن آذن له خاصة وأن يدخل متى شاء وعلى كل حال\nقال ولم يفرغ الحاجب من كلامه حتى دخل عمرو فجلس على المائدة وتغير وجه الخضر وبانت الكراهة فيه فما أكل أكلا فيه خبز وتبين عبيد الله ذلك ورفعت المائدة وقدم النبيذ فجعل الخضر يشرب شرابا كثيرا لم أكن أعهده يشرب مثله فظننت أنه يريد بذلك أن يستتر من عمرو الغزال وعمرو يتغنى فلا يقتصر وكلما تغنى\nقال له عبيد الله لمن هذا الصوت يا حبيبي فيقول لي وعندنا يومئذ جوار مطربات محسنات وهو يقطع غناءهن بغنائه وتبينت في وجه الخضر العربدة إلى أن\nقال عمرو بعقب صوت هذا لي فوثب الخضر وكشف استه وخري في وسط المجلس على بساط خز لم أر لأحد مثله ثم قال إن كان هذا الغناء لك فهذا الخراء لي فغضب عبيد الله\nوقال له يا خضر أكنت تستطيع أن تفعل أكثر من هذا قال أي والله أيها الأمير ثم وضع رجليه على سلحه ثم أخرجهما فمشى على البساط مقبلا ومدبرا حتى خرج وقد لوثه وهو يقول هذا كله لي وتفرقنا عن المجلس على أقبح حال وأسوئها وشاع الخبر حتى بلغ الرشيد فضحك حتى غلب عليه ودعا الخضر وجعله من ندمائه منذ يومئذ وقال هذا أطيب خلق الله وانكشف عنده عوار عمرو الغزال واسترحنا منه وأمر أن يحجب عنه فسقط يومئذ وقد كان الجواري والغلمان أخذوه ولهجوا به وكان الرشيد يكايد به إبراهيم الموصلي وابن جامع قبل ذلك فسقط غناؤه أيضا منذ يومئذ فما ذكر منه حرف\nبعد ذلك اليوم إلا صنعته في\n(يا ريح ما تصنعين بالدمن ... )\nلولا إعجاب الرشيد به لسقط أيضا","topic":"أخبار مرة ونسبه","topicNo":296,"sp":2,"spl":"أبو موسى الأعمى يندم على شعر قاله — وصف مجلس لهو","tags":["الجواري والنساء"],"loc":3867,"partialRef":{"sid":"b245-11","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b296-7","bab":"الجزء 23","sec":"وصف مجلس لهو","page":"ج23 ص147","text":"حدثني الحسن بن علي عن محمد بن القاسم عن أبي هفان قال كنا في مجلس وعندنا قينة تغنينا وصاحب البيت يهواها فجعلت تكايده وتومىء إلى غيره بالمزح والتجميش وتغيظه بجهدها وهو يكاد يموت قلقا وهما وتنغص عليه يومه ولجت في أمرها ثم سقط المضراب عن يدها فأكبت على الأرض لتأخذه فضرطت ضرطة سمعها جميع من حضر وخجلت فلم تدر ما تقول فأقبلت على عشيقها فقال أيش تشتهي أن أغني لك فقال غني\n(يا ريح ما تصنعين بالدمن ... )\nخجلت وضحك القوم وصاحب الدار حتى أفرطوا فبكت وقامت من المجلس وقالت أنتم والله قوم سفل ولعنة الله على من يعاشركم وغضبت وخرجت وكان علم الله سبب القطيعة بينهما وسلو ذلك الرجل عنها أخبرني ابن عمار وعمي والحسن بن علي قالوا حدثنا عبد الله بن أبي سعد قال حدثنا الحسين بن الضحاك قال كنت في مجلس قد دعينا إليه ومعنا علي بن أمية فعلقت نفسه بقينة دعيت لنا يومئذ فأقبل عليها فقال لها أتغنين قوله\n(خبريني من الرسول إليك ... واجعليه من لا ينم عليك)\n(وأشيري إلي من هو باللحظ ... ليخفى على الذين لديك)\nقالت نعم وغنته لوقتها وزادت فيه هذا البيت فقال\n(وأقلي المزاح في المجلس اليوم ... فإن المزاح بين يديك)\nفطن لما أرادت وسر بذلك ثم أقبلت على خادم واقف فقالت له يا مسرور اسقني فسقاها وفطن ابن أمية أنها أرادت أن تعلمه أن مسرورا هو الرسول فخاطبه فوجده كما يريد وما زال ذلك الخادم يتردد في الرسائل بينهما","topic":"أخبار مرة ونسبه","topicNo":296,"sp":2,"spl":"أبو موسى الأعمى يندم على شعر قاله — وصف مجلس لهو","tags":["اللهو والمزاح","الرواية والكتابة"],"loc":3868,"partialRef":{"sid":"b245-11","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b296-9","bab":"الجزء 23","sec":"أخبار عمر الميداني — إسحاق بن إبراهيم يطلب منه أن يغني بصوته","page":"ج23 ص148 – ج23 ص149","text":"هو رجل من أهل بغداد كان ينزل الميدان فعرف به وكان لا يفارق محمدا وعليا ابني أمية وأبا حشيشة ينادمهم ويغني في أشعارهم وكان منزله قريبا منهم وهو أحد المحسنين المتقدمين في الصنعة والأداء حدثني جحظة قال سمعت ابن دقاق في منزل أبي العبيس بن حمدون يقول سمعت أبا حشيشة والمسدود ومن قبلهما من الطنبوريين فما سمعت منهم أصح غناء ولا أكثر تصرفا من عمر الميداني\nحدثني جحظة قال حدثني علي بن أمية قال دخلت يوما على عمر الميداني وكان له بقال على باب داره ينادمه ولا يفارقه ويقارضه إذا أعسر ويتصرف في حوائجه فإذا حصلت له دراهم دفعها إليه يقبض منها ما رأى لا يسأله عن شيء فوجدت عنده يومئذ هذا البقال فقال لنا عمر معي أربعة دراهم تعطوني منها لعلف حماري درهما والثلاثة لكم فكلوا بها ما أحببتم وعندي نبيذ وأنا أغنيكم والبقال يحضرنا\nمن الأبقال اليابسة ما في حانوته فوجهنا بالبقال فاشترى لنا بدرهم لحما وبدرهم خبزا وبدرهم فاكهة وريحانا وجاءنا من حانوته بحوائج السكباج ونقل فبينا نحن نتوقع الفراغ من القدر إذا بفرانق يدق الباب فأدخله عمر فقال له أجب الأمير إسحاق بن إبراهيم فحلف علينا عمر بالطلاق ألا نبرح ومضى هو وأكلنا السكباج وشربنا وانصرف عشاء وبكر إلي رسوله في السحر أن صر إلي فصرت إليه فقلت أعطني خبرك من النعل إلى النعل\nقال دخلت فوضعت بين يدي مائدة كأنها جزعة يمانية قد فرشت في عراصها الحبر فأكلت وسقيت رطلين ودفع إلي طنبور فدخلت إلى إسحاق فوجدته في الصدر جالسا وخلفه ستارة عن يمينه مخارق\nوعن يساره علويه فقال لي أنت عمر الميداني فقلت نعم فقال أأكلت فقلت نعم قال ها هنا أو في منزلك فقلت بل ها هنا قال أحسنت فغن بصوتك الذي صنعته في\n(يا شبيه الهلال كلل في الأفق أنجما ... )\nهو رمل مطلق فغنيته فضرب الستارة وقال قولوه أنتم فقالوه فقال لمخارق وعلويه كيف تسمعان فقالا هذا والله ذا وذا ذاك فرددته مرارا وشرب عليه وقال لي أنا اليوم على خلوة ولك علي دعوات فانصرف اليوم بسلام فخرجت ودفع إلي الغلام خمسة آلاف درهم فهي هذه والله لا\nاستأثرت عليكم منها بدرهم فلم نزل عنده نقصف حتى نفدت\n(أمين الخالق الباري ... وراعي كل مخلوق)\n(أدر راحك في المعشوق ... من راحة معشوق)\nلشعر لأبي أيوب سليمان بن وهب والغناء للقاسم بن زرزور ثقيل أول بالبنصر من جامع غنائه المأخوذ عن أبيه أبي القاسم عبيد الله بن القاسم","topic":"أخبار مرة ونسبه","topicNo":296,"sp":3,"spl":"أخبار عمر الميداني — إسحاق بن إبراهيم يطلب منه أن يغني بصوته — أخبار سليمان بن وهب وجمل من","tags":["الحب والغزل","اللهو والمزاح"],"song":1,"loc":3869,"partial":1},
{"id":"b296-10","bab":"الجزء 23","sec":"أخبار سليمان بن وهب وجمل من أحاديث تصلح لهذا الكتاب","page":"ج23 ص152","text":"قد تقدم نسبه في أخبار الحسن بن وهب أخيه وانتماؤه في بني الحارث بن كعب وأن أصلهم من قرية يقال لها سار قرمقا من طسوج خسر وسابور من سواد واسط وكان سليمان بن وهب ينكر الإنتساب إلى الحارث بن كعب على أخيه الحسن وعلى أبنه أبي الفضل أحمد بن سليمان بن وهب لشدة تعلقهما به\nأخبرني بذلك محمد بن يحيى وغيره من شيوخنا ومن مشيخة الكتاب أخبرني الصولي قال حدثني الحسن بن يحيى وعون بن محمد الكندي أن جعفر بن محمد كان وزير المهتدي في أول أمره فبلغه عنه تشيع فكرهه\nوقال هذا رافضي لا حاجة لي فيه واستوزر جعفر بن محمد بن عمار فلم يزل على وزارته حتى مضت سنة من خلافة المهتدي ثم قدم موسى بن بغا من الجبل وكاتبه سليمان بن وهب وابنه عبيد الله فاستوزر المهتدي سليمان بن وهب ولقب الوزير حقا لأن من كان قبله كان غير مستحق للوزارة ولا مستقل بها أخبرني محمد بن يحيى الصولي قال حدثني الحسن بن يحيى بن الجماز قال\nلما استوزر سليمان بن وهب جلس للناس فدخل عليه شاعر يقال له هارون بن محمد البالسي فذكر مظلمة له ببلده ثم أنشده\n(زيد في قدرك العلي علو ... يابن وهب من كاتب ووزير)\n(أسفر الشرق منك والغرب عن ضوء ... من العدل فاق ضوء البدور)\n(أنشر الناس غيثكم بعدما كانوا ... رفاتا من قبل يوم النشور)\n(شرد الجور عدلكم فسرحنا ... بينكم بين روضة وسرور)\n(أنت عين الإمام والقرم موسى ... بك تفتر عابسات الأمور)\nوقع في ظلماته بما أراد ووصله بمائتي دينار","topic":"أخبار مرة ونسبه","topicNo":296,"sp":3,"spl":"أخبار عمر الميداني — إسحاق بن إبراهيم يطلب منه أن يغني بصوته — أخبار سليمان بن وهب وجمل من","tags":["السفر والحج","الموت","الرواية والكتابة"],"loc":3870},
{"id":"b296-11","bab":"الجزء 23","sec":"يزيد المهلبي يمدحه فيقضي له حوائجه","page":"ج23 ص153","text":"أخبرني محمد بن يحيى قال حدثنا أحمد بن الخصيب قال لعهدي بيزيد بن محمد المهلبي عند سليمان بن وهب بعد ما استوزره المهتدي وقد أجلسه إلى جانبه وهو ينشده قوله\n(وهبتم لنا يا آل وهب مودة ... فأبقت لنا جاها ومجدا يؤثل)\n(فمن كان للآثام والذل أرضه ... فأرضكم للأجر والعز منزل)\n(رأى الناس فوق المجد مقدار مجدكم ... فقد سألوكم فوق ما كان يسأل)\n(يقصر عن مسعاكم كل آخر ... وما فاتكم ممن تقدم أول)\n(بلغت الذي قد كنت أملته لكم ... وإن كنت لم أبلغ بكم ما أؤمل)\nقطع عليه سليمان الإنشاد وقال له يا أبا خالد فأنت والله عندي كما\nقال عمارة بن عقيل لإبنه\n(أقهقه مسرورا إذا أبت سالما ... وأبكي من الإشفاق حين تغيب)\nقال له يزيد فيسمع مني الوزير آخر الشعر لا أوله وتمم فقال\n(ومالي حق واجب غير أنني ... بجودكم في حاجتي أتوسل)\n(وأنكم أفضلتم وبررتم ... وقد يستتم النعمة المتفضل)\n(وأوليتم فعلا جميلا مقدما ... فعودوا فإن العود بالحر أجمل)\n(وكم محلف قد نال ما رام منكم ... ويمنعنا من مثل ذاك التجمل)\n(وعودتمونا قبل أن نسأل الغنى ... ولا بذل للمعروف والوجه يبذل)\nقال له سليمان لا تبرح والله إلا بقضاء حوائجك كائنة ما كانت ولو لم أستفد من كتبة أمير المؤمنين إلا شكرك لرأيت جنابي بذلك ممرعا وغرسي مثمرا ثم وقع له في رقاع كثيرة كانت بين يديه أخبرني محمد قال حدثنا الحزنبل قال لما ولى المهتدي سليمان بن وهب وزارته قام إليه رجل من ذوي حرفته فقال أنا أعز الله الوزير خادمك المؤمل دولتك السعيد بأيامك المطوي القلب على ودك المنشور اللسان بمدحك المرتهن بشكر نعمتك وقد قال الشاعر\n(وفيت كل أديب ودني ثمنا ... إلا المؤمل دولاتي وأيامي)\n(فإنني ضامن ألا أكافئه ... إلا بتسويغه فضلي وإنعامي)\nوإني لكما قال القيسي ما زلت أمتطي النهار إليك وأستدل بفضلك عليك حتى إذا جنني الليل فقبض البصر ومحا الأثر أقام بدني وسافر أملي والإجتهاد عذر وإذا بلغتك فهو مرادي فقط فقال له سليمان لا عليك فإني عارف بوسيلتك محتاج إلى كفايتك ولست أؤخر عن أمري النظر في أمرك وتوليتك ما يحسن أثره عليك\nوذكر يحيى بن علي بن يحيى عن أبيه قال ما رأيت أظرف من سليمان بن وهب ولا أحسن أدبا خرجنا نتلقاه عند قدومه من الجبل مع موسى بن بغا فقال لي هات الآن يا أبا الحسن حدثني بعجائبكم بعدي وما أظنك تحدثني بأعجب من خبر ضرطة أبي وهب بحضرة القاضي وما سير من خبرها وما قيل فيها حتى قيل\n(ومن العجائب أنها بشهادة ... القاضي فليس يزيلها الإنكار)\nجعل يضحك","topic":"أخبار مرة ونسبه","topicNo":296,"sp":4,"spl":"يزيد المهلبي يمدحه فيقضي له حوائجه","tags":["المديح"],"loc":3871},
{"id":"b296-12","bab":"الجزء 23","sec":"اعترافه بفضل ابن ثوابة","page":"ج23 ص155","text":"قال علي بن الحسين الأصبهاني حضرت أبا عبد الله الباقطاني وهو يتقلد ديوان المشرق وقد تقلد ابن أبي السلاسل ماسبذان ومهرجان قذف وجاءه يأخذ كتبه فجعل يوصيه كما يوصي أصحاب الدواوين العمال فقال ابن أبي السلاسل كأنك استكثرت لي هذا العمل أنت أيضا قد كنت تكتب لأبي العباس بن ثوابة ثم صرت صاحب ديوان فقال له الباقطاني يا جاهل يا مجنون لولا أنه قبيح علي مكافأة مثلك\nلراجعت الوزير أيده الله في أمرك حتى أزيل يدك ومن لي أن أجد مثل ابن ثوابة في هذا الوقت فأكتب له ولا أريد الرياسة ثم أقبل علينا يحدثنا فقال دخلت مع أبي العباس بن ثوابة إلى المهتدي وكان سليمان بن وهب وزيره وكان يدخل إليه الوزير وأصحاب الدواوين والعمال والكتاب فيعملون بحضرته فيوقع إليهم في الأعمال فأمر سليمان أن يكتب عنه عشرة كتب مختلفة إلى جماعة من العمال فأخذ سليمان بيد أبي العباس بن ثوابة ثم\nقال له أنت اليوم أحد ذهنا مني فهلم نتعاون فدخلا بيتا ودخلت معهما وأخذ سليمان خمسة أنصاف وأبو العباس خمسة أنصاف أخر فكتبا الكتب التي أمر بها سليمان ما احتاج أحدهما إلى نسخه وقد أكمل كل واحد منهما ما كتب به صاحبه فاستحسنه وقرظه ثم وضع سليمان الكتب بين يدي المهتدي فقال له وقد قرأها أحسنت يا سليمان ونعم الرجل أنت لولا المعجل والمؤجل وكان سليمان إذا ولي عاملا أخذ منه مالا معجلا وأجل له مالا إلى أن يتسلم عمله فقال له يا أمير المؤمنين هذا قول لا يخلو من أن يكون حقا أو باطلا فإن كان باطلا فليس مثلك من يقوله وإن كان حقا وقد علمت أن الأصول محفوظة فما يضر من يساهمني من عمالي على بعض ما يصل إليهم من بر من غير تحيف للرعية ولا نقص للأموال فقال إذا كان هكذا فلا بأس ثم\nقال له اكتب إلى فلان العامل يقبض ضيعة فلان المصروف المعتقل في يده بباقي ما عليه من المصادرة فقال له أبو العباس بن ثوابة كلنا يا أمير المؤمنين خدمك وأولياؤك وكلنا حاطب في حبلك وساع فيما أرضاك وأيد ملكك أفنمضي ما تأمر به على ما خيلت أم نقول بالحق قال بل قل الحق يا أحمد فقال يا أمير المؤمنين الملك يقين والمصادرة شك أفترى أن أزيل\nاليقين بالشك قال لا قال فقد شهدت للرجل بالملك وصادرته عن شك فيما بينك وبينه وهل خانك أم لا فتجعل المصادرة صلحا فإذا قبضت ضيعته بهذا فقد أزلت اليقين بالشك فقال له صدقت ولكن كيف الوصول إلى المال فقال له أنت لا بد لك من عمال على أعمالك وكلهم يرتزق ويرتفق فيحوز رفقه ورزقه إلى منزله فاجعله أحد عمالك ليصرف هذين الوجهين إلى ما عليه ويسعفه معاملوه فيتخلص بنفسه وضيعته ويعود إليك مالك فأمر سليمان بن وهب بأن يفعل ذلك فلما خرجا من حضرة المهتدي\nقال له سليمان عهدي بهذا الرجل عدوك وكل واحد منكما يسعى على صاحبه فكيف زال ذلك حتى نبت عنه في هذا الوقت نيابة أحييته بها وتخلصت نفسه ونعمته فقال إنما كنت أعاديه وأسعى عليه وهو يقدر على الإنتصاف مني فأما وهو فقير إلي فلا فهذا مما يحظره الدين والصناعة والمروءة فقال له سليمان جزاك الله خيرا أما والله لأشكرن هذه النية لك ولأعتقدنك من أجلها أخا وصديقا ولأجعلن هذا الرجل لك عبدا ما بقي ثم\nقال الباقطاني أفمن كان هذا وزنه وفعله يعاب من كان يكتب له أخبرني محمد بن يحيى الباقطاني قال حدثنا الحسين بن يحيى الباقطاني قال كنت آلف سليمان بن وهب كثيرا وأخدمه وأحادثه وكان يخصني ويأنس بي فأنشدني لنفسه يذكر نكبته في أيام الواثق\n\n(نوائب الدهر أدبتني ... وإنما يوعظ الأريب)\n(قد ذقت حلوا وذقت مرا ... كذاك عيش الفتى ضروب)\n(ما مر بؤس ولا نعيم ... إلا ولي فيهما نصيب)\nيه رمل محدث لا أعرف صانعه وذكر يحيى بن علي بن يحيى أن جفوة نالت أباه من سليمان بن وهب فكتب إليه\n(جفاني أبو أيوب نفسي فداؤه ... فعاتبته كيما يريع ويعتبا)\n(فوالله لولا الضن مني بوده ... لكان سهيل من عتابيه أقربا)\nكتب إليه سليمان\n(ذكرت جفائي وهو من غير شيمتي ... وإني لدان من بعيد تقربا)\n(فكيف بخل لي أضن بوده ... وأصفيه ودا ظاهرا ومغيبا)\n(علي بن يحيى لا عدمت إخاءه ... فما زال في كل الخصال مهذبا)\n(ولكن أشغالا غدت وتواترت ... فلما رأيت الشغل عاق وأتعبا)\n(وكنت إلى عذر الأخلاء إنهم ... كرام وإن كان التواصل أوجبا)\n(فإن يطلب مني عتابك أوبة ... ببر تجدني بالأمانة معتبا)","topic":"أخبار مرة ونسبه","topicNo":296,"sp":5,"spl":"اعترافه بفضل ابن ثوابة","tags":["اللهو والمزاح","الرواية والكتابة"],"song":1,"loc":3872},
{"id":"b296-13","bab":"الجزء 23","sec":"اعترافه بفضل ابن ثوابة","page":"ج23 ص155","text":"خبرني محمد بن العباس اليزيدي عن عمه قال\nكان سليمان بن وهب وهو حدث يتعشق إبراهيم بن سوار بن شداد بن ميمون وكان من أحسن الناس وجها وأملحهم أدبا وظرفا وكان إبراهيم هذا يتعشق جارية مغنية يقال لها رخاص فاجتمعوا يوما فسكر إبراهيم ونام فرأت رخاص سليمان يقبله فلما انتبه لامته وقالت كيف أصفو لك وقد رأيت سليمان يقبلك فهجره إبراهيم فكتب إليه سليمان\n(قل للذي ليس لي من ... جوى هواه خلاص)\n(أئن لثمتك سرا ... وأبصرتني رخاص)\n(وقال لي ذاك قوم ... على اغتيابي حراص)\n(هجرتني وأتتني ... شتيمة وانتقاص)\n(وسر ذاك أناسا ... لهم علينا اختراص)\n(فهاك فاقتص مني ... إن الجروح قصاص)\nأهدي سليمان إلى رخاص هدايا كثيرة فكانوا بعد ذلك يتناوبون يوما عند سليمان ويوما عند إبراهيم ويوما عند رخاص","topic":"أخبار مرة ونسبه","topicNo":296,"sp":6,"spl":"اعترافه بفضل ابن ثوابة — مساجلة بينه وبين أحد أصحابه","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3873},
{"id":"b296-14","bab":"الجزء 23","sec":"مساجلة بينه وبين أحد أصحابه","page":"ج23 ص159","text":"أخبرني الصولي عن أحمد بن الخصيب قال حضرت سليمان بن وهب وقد جاءته رقعة من بعض من وعده أن يصرفه من أصحابه وفيها\n(هبني رضيت منك بالقليل ... أكان في التأويل والتنزيل)\n(أو خبر جاء عن الرسول ... أو حجة في فطر العقول)\n(مستحسن من رجل جليل ... عال له حظ من الجميل)\n(ينقص ما أشاع بالتطويل ... والقول دون الفعل بالتحصيل)\n(ليس كذا وصف الفتى النبيل ... )\nال فكتب له بولاية ناحية وأنفذ إليه مائتي دينار وكتب في رقعة\n(ليس إلى الباطل من سبيل ... إلا لمن يعدل عن تعديل)\n(وقد وفينا لك بالتحصيل ... فاطو الذي كان عن الخليل)\n(فضلا عن الخليط والنزيل ... وعد من القول إلى الجميل)\n(وعف في الكثير والقليل ... تحظ من الرتبة بالجزيل)\nأخبرني محمد بن يحيى عن عبد الله بن الحسين بن سعد عن بعض أهله أنه كتب إلى سليمان بن وهب وهو يتولى شيئا من أعمال الضياع\n(أطال الله إسعادك ... في الآجل والعاجل)\n(أما ترعى لمن أمل ... فضلا حرمة الآمل)\n(وعندي عاجل من رشوة ... يتبعها آجل)\n(وأنت العالم الشاهد ... أني كاتب عامل)\n(فول الكافل الباذل ... دون العاجز الباخل)\n(فما أفشي لك السر ... فعال الأخرق الجاهل)\nال فضحك وأجلسه وكتب في رقعته\n(أبن لي ما الذي تخطب ... شرحا أيها الباذل)\n(وما تعطي إذا وليت ... تعجيلا وما الآجل)\n(أفي الإسلاف تنقيض ... أم الوزن له كامل)\n(وفي الموقوف تضمين ... أم الوعد به حاصل)\n(وهل ميقاته الغلة ... في العام أو القابل)\n(أبن لي ذاك واردد رقعتي ... يا كاتبا عامل)\nفلما قرأها الرجل قطع ما بينه وبينه ورد الرقعة عليه وولاه سليمان ما التمس أخبرني محمد بن يحيى عن موسى البربري قال أهدى سليمان بن وهب إلى سليمان بن عبد الله بن طاهر سلال رطب من ضيعته وكتب إليه يقول\n(أذن الأمير بفضله ... وبجوده وبنيله)\n(لوليه في بره ... بجناه سكر نخله)\n(فبعثت منه بسلة ... تحكي حلاوة عدله)\nخبرني محمد الباقطاني قال كتب سليمان بن وهب بقلم صلب فاعتمد عليه اعتمادا شديدا فصر القلم في يده فقا ل\n(إذا ما حددنا وانتضينا قواطعا ... أصم الذكي السمع منها صريرها)\n(تظل المنايا والعطايا شوارعا ... تدور بما شئنا وتمضي أمورها)\n(تساقط في القرطاس منها بدائع ... كمثل اللآلي نظمها ونثيرها)\n(تقود أبيات البيان بفطنة ... تكشف عن وجه البلاغة نورها)\n(إذا ما خطوب الدهر أرخت ستورها ... تجلت بنا عما تسر ستورها)","topic":"أخبار مرة ونسبه","topicNo":296,"sp":6,"spl":"اعترافه بفضل ابن ثوابة — مساجلة بينه وبين أحد أصحابه","tags":["اللهو والمزاح"],"loc":3874,"partial":1},
{"id":"b296-15","bab":"الجزء 23","sec":"رثاؤه أخاه الحسن","page":"ج23 ص161","text":"قال وأنشدني له يرثي أخاه الحسن\n(مضى مذ مضى عز المعالي وأصبحت ... لآلي الحجا والقول ليس لها نظم)\n(وأضحى نجي الفكر بعد فراقه ... إذا هم بالإفصاح منطقه كظم)\nذكر ابن المسيب أن جماعة تذاكروا لما قبض الموفق على سليمان بن وهب وابنه عبد الله أنه إنما استكتبهما ليقف منهما على ذخائر موسى بن بغا وودائعه فلما استقصى ذلك نكبهما لكثرة مالهما فقال ابن الرومي وكان حاضرا\n(ألم تر أن المال يتلف ربه ... إذا جم آتيه وسد طريقه)\n(ومن جاور الماء الغزير مجمه ... وسد مفيض الماء فهو غريقه)\nمات سليمان بن وهب في محبسه وهو مطالب فرثاه جماعة من الشعراء فممن جود في مرثيته البحتري حيث يقول\n(هذا سليمان بن وهب بعدما ... طالت مساعيه النجوم سموكا)\n(وتنصف الدنيا يدبر أمرها ... سبعين حولا قد تممن دكيكا)\n(أغرت به الأقدار بغت ملمة ... ما كان رس حديثها مأفوكا)\n(أبلغ عبيد الله بارع مذحج ... شرفا ومعطى فضلها تمليكا)\n(ومتى وجدت الناس إلا تاركا ... لحميمه في الترب أو متروكا)\n(بلغ الإرادة إذ فداك بنفسه ... وتود لو تفديه لا يفديكا)\n(إن الرزية في الفقيد فإن هفا ... جزع بلبك فالرزية فيكا)\n(لو ينجلي لك ذخرها من نكبة ... جلل لأضحكك الذي يبكيكا)\n\n(لقد برز الفضل بن يحيى ولم يزل ... يسامي من الغايات ما كان أرفعا)\n(يراه أمير المؤمنين لملكه ... كفيلا لما أعطى من العهد مقنعا)\n(قضى بالتي شدت لهارون ملكه ... وأحيت ليحيى نفسه فتمتعا)\n(فأمست بنو العباس بعد اختلافها ... وآل علي مثل زندي يد معا)\n(لئن كان من أسدى القريض أجاده ... لقد صاغ إبراهيم فيه فأوقعا)\nلشعر لأبان بن عبد الحميد اللاحقي يقوله في الفضل بن يحيى لما قدم يحيى بن عبد الله بن الحسين على أمان الرشيد وعهده والغناء لإبراهيم الموصلي ثاني ثقيل بالبنصر عن أحمد بن المكي وكان الرشيد أمره أن يغني في هذا الشعر وإياه عني أبان بقوله\n(لقد صاغ إبراهيم فيه فأوقعا ... )","topic":"أخبار مرة ونسبه","topicNo":296,"sp":7,"spl":"رثاؤه أخاه الحسن","tags":[],"song":1,"loc":3875,"partial":1},
{"id":"b297-1","bab":"الجزء 23","sec":"أخبار أبان بن عبد الحميد ونسبه","page":"ج23 ص164","text":"أبان بن عبد الحميد بن لاحق بن عفير مولى بني رقاش قال أبو عبيدة بنو رقاش ثلاثة نفر ينسبون إلى أمهم واسمها رقاش وهم مالك وزيد مناة وعامر بنو شيبان بن ذهل بن ثعلبة بن عكابة بن صعب بن علي بن بكر بن وائل\nأخبرني عمي قال حدثنا الحسين بن عليل العنزي قال حدثني أحمد بن مهران مولى البرامكة قال شكا مروان بن أبي حفصة إلى بعض إخوانه تغير الرشيد عليه وإمساك يده عنه فقال له ويحك أتشكو الرشيد بعد ما أعطاك\nقال أو تعجب من ذلك هذا أبان اللاحقي قد أخذ من البرامكة بقصيدة قالها واحدة مثل ما أخذته من الرشيد في دهري كله سوى ما أخذه منهم ومن أشباههم بعدها وكان أبان نقل للبرامكة كتاب كليلة ودمنة فجعله شعرا ليسهل حفظه عليهم وهو معروف أوله\n(هذا كتاب أدب ومحنه ... وهو الذي يدعى كليلة ودمنه)\n(فيه احتيالات وفية رشد ... وهو كتاب وضعته الهند)\nفأعطاه يحيى بن خالد عشرة آلاف دينار وأعطاه الفضل خمسة آلاف دينار ولم يعطه جعفر شيئا وقال ألا يكفيك أن أحفظه فأكون راويتك وعمل أيضا القصيدة التي ذكر فيها مبدأ الخلق وأمر الدنيا وشيئا من المنطق وسماها ذات الحلل ومن الناس من ينسبها إلى أبي العتاهية والصحيح أنها لأبان","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":0,"spl":"أخبار أبان بن عبد الحميد ونسبه — كان وصديقه المعذل يتعابثان بالهجاء","tags":["السفر والحج"],"loc":3876},
{"id":"b297-2","bab":"الجزء 23","sec":"أبو نواس يهجوه وأبان يجيبه","page":"ج23 ص165","text":"أخبرني محمد بن جعفر النحوي صهر المبرد قال حدثنا أبو هفان قال حدثني الجماز قال كان يحيى بن خالد البرمكي قد جعل امتحان الشعراء وترتيبهم في الجوائز إلى أبان بن عبد الحميد فلم يرض أبو نواس المرتبة التي جعله فيها أبان فقال يهجوه بذلك\n(جالست يوما أبانا ... لا در در أبان)\n(حتى إذا ما صلاة ... الأولى دنت لأوان)\n(فقام ثم بها ذو ... فصاحة وبيان)\n(فكلما قال قلنا ... إلى انقضاء الأذان)\n(فقال كيف شهدتم ... بذا بغير عيان)\n(لا أشهد الدهر حتى ... تعاين العينان)\n(فقلت سبحان ربي ... فقال سبحان ماني)\nفقال أبان يجيبه\n(إن يكن هذا النواسي ... بلا ذنب هجانا)\n(فلقد نكناه حينا ... وصفعناه زمانا)\n(هانئ الجربى أبوه ... زاده الله هوانا)\n(سائل العباس واسمع ... فيه من أمك شانا)\n(عجنوا من جلنار ... ليكيدوك عجانا)\nلنار أم أبي نواس وتزوجها العباس بعد أبيه","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":0,"spl":"أخبار أبان بن عبد الحميد ونسبه — كان وصديقه المعذل يتعابثان بالهجاء","tags":["الهجاء","اللهو والمزاح"],"loc":3877},
{"id":"b297-3","bab":"الجزء 23","sec":"كان وصديقه المعذل يتعابثان بالهجاء","page":"ج23 ص166","text":"أخبرنا محمد بن العباس اليزيدي قال حدثنا أبو قلابة عبد الملك بن محمد قال كان أبان اللاحقي صديقا للمعذل بن غيلان وكانا مع صداقتهما\nيتعابثان بالهجاء فيهجوه المعذل بالكفر وينسبه إلى الشؤم ويهجوه أبان وينسبه إلى الفساء الذي تهجى به عبد القيس وبالقصر وكان المعذل قصيرا فسعى في الإصلاح بينهما أبو عيينة المهلبي فقال له أخوه عبد الله وهو أسن منه يا أخي إن في هذين شرا كثيرا ولا بد من أن يخرجاه فدعهما ليكون شرهما بينهما وإلا فرقاه على الناس فقال أبان يهجو المعذل\n(أحاجيكم ما قوس لحم سهامها ... من الريح لم توصل بقد ولا عقب)\n(وليست بشريان وليست بشوحط ... وليست بنبع لا وليست من الغرب)\n(ألا تلك قوس الدحدحي معذل ... بها صار عبديا وتم له النسب)\n(تصك خياشيم الأنوف تعمدا ... وإن كان راميها يريد بها العقب)\n(فإن تفتخر يوما تميم بحاجب ... وبالقوس مضمونا لكسرى بها العرب)\n(فحي ابن عمرو فاخرون بقوسه ... وأسهمه حتى يغلب من غلب)\nال أبو قلابة فقال المعذل في جواب ذلك\n(رأيت أبانا يوم فطر مصليا ... فقسم فكري واستفزني الطرب)\n(وكيف يصلي مظلم القلب دينه ... على دين ماني إن ذاك من العجب)","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":0,"spl":"أخبار أبان بن عبد الحميد ونسبه — كان وصديقه المعذل يتعابثان بالهجاء","tags":["الهجاء","اللهو والمزاح"],"loc":3878},
{"id":"b297-4","bab":"الجزء 23","sec":"هجوه لإبن النضير","page":"ج23 ص168","text":"أخبرني محمد بن يحيى قال حدثنا عون بن محمد الكندي قال كان لأبي النضير حوار يغنين ويخرجن إلى جلة أهل البصرة وكان أبان بن عبد الحميد يهجوه بذلك فمن ذلك قوله\n(غضب الأحمق إذ مازحته ... كيف لو كنا ذكرنا الممرغة)\n(أو ذكرنا أنه لا عبها ... لعبة الجد بمزح الدغدغه)\n(سود الله بخمس وجهه ... دغن أمثال طين الردغة)\n(خنفساوان وبنتا جعل ... والتي تفتر عنها وزغه)\n(يكسر الشعر وإن عاتبته ... في مجال قال هذا في اللغة)\nأنشدني عمي قال أنشدني الكراني قال أنشدني أبو إسماعيل اللاحقي لجده أبان في هجاء أبي النضير وأخبرني الصولي أنه وجدها بخط الكراني\n(إذا قامت بواكيك ... وقد هتكن أستارك)\n(أيثنين على قبرك ... أم يلعن أحجارك)\n(وما تترك في الدنيا ... إذا زرت غدا نارك)\n(ترى في سقر المثوى ... وإبليس غدا جارك)\n(لمن تترك زقيك ... ودنيك وأوتارك)\n(وخمسا من بنات الليل ... قد ألبسن أطمارك)\n(تعالى الله ما أقبح ... إذ وليت أدبارك)\nقال فيه أيضا\n(قيان أبي النضير مثلجات ... غناء مثل شعر أبي النضير)\n(فلا همدان حين نصيف نبغي ... ولا الماهين أيام الحرور)\n(ولا نبغي بقرميسين روحا ... ولا نبلى البغال من المسير)\n(فإن رمت الغناء لديه فاصبر ... إذا ما جئته للزمهرير)","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":1,"spl":"هجوه لإبن النضير — هجوه المعذل","tags":["الهجاء"],"loc":3879},
{"id":"b297-5","bab":"الجزء 23","sec":"هجوه المعذل","page":"ج23 ص169","text":"أخبرني محمد بن يحيى قال حدثنا أبو خليفة وأبو ذكوان والحسن بن علي النهدي قالوا كان المعذل بن غيلان المهري يجالس عيسى بن جعفر بن المنصور وهو يلي حينئذ إمارة البصرة من قبل الرشيد فوهب للمعذل بن غيلان له بيضة عنبر وزنها أربعة أرطال فقال أبان بن عبد الحميد\n(أصلحك الله وقد أصلحا ... إني لا آلوك أن أنصحا)\n(علام تعطي منوي عنبر ... وأحسب الخازن قد أرجحا)\n(من ليس من قرد ولا كلبة ... أبهى ولا أحلى ولا أملحا)\n(رسول يأجوج أتى عنهم ... يخبر أن الروم قد أقبحا)\n(ما بين رجليه إلى رأسه ... شبر فلا شب ولا أفلحا)\nخبرني الصولي قال حدثنا أبو العيناء قال حدثني الحرمازي قال خرج أبان بن عبد الحميد من البصرة طالبا للإتصال بالبرامكة وكان الفضل بن يحيى غائبا فقصده فأقام ببابه مدة مديدة لا يصل إليه فتوسل إلى من وصل له شعرا إليه وقيل إنه توسل إلى بعض بني هاشم ممن شخص مع الفضل وقاله له\n(يا غزير الندى ويا جوهر الجوهر ... من آل هاشم بالبطاح)\n(إن ظني وليس يخلف ظني ... بك في حاجتي سبيل النجاح)\n(إن من دونها لمصمت باب ... أنت من دون قفله مفتاحي)\n(تاقت النفس يا خليل السماح ... نحو بحر الندى مجاري الرياح)\n(ثم فكرت كيف لي واستخرت الله ... عند الإمساء والإصباح)\n(وامتدحت الأمير أصلحه الله ... بشعر مشهر الأوضاح)\nقال هات مديحك فأعطاه شعرا في الفضل في هذا الوزن وقافيته\n(أنا من بغية الأمير وكنز ... من كنوز الأمير ذو أرباح)\n(كاتب حاسب خطيب أديب ... ناصح زائد على النصاح)\n(شاعر مفلق أخف من الريشة ... مما يكون تحت الجناح)\nهي طويلة جدا يقول فيها\n(إن دعاني الأمير عاين مني ... شمريا كالبلبل الصياح)\nقال فدعا به ووصله ثم خص بالفضل وقدم معه فقرب من قلب يحيى بن خالد وصار صاحب الجماعة وزمام أمرهم","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":1,"spl":"هجوه لإبن النضير — هجوه المعذل","tags":["المديح"],"loc":3880}]);
window.__BOOK__['p11'].push([{"id":"b297-6","bab":"الجزء 23","sec":"تقرب إلى الرشيد بهجاء آل أبي طالب","page":"ج23 ص171","text":"أخبرني حبيب بن نصر المهلبي قال حدثني علي بن محمد النوفلي أن أبان بن عبد الحميد عاتب البرامكة على تركهم إيصاله إلى الرشيد وإيصال مديحه إليه فقالوا له وما تريد من ذلك فقال أريد أن أحظى منه بمثل ما يحظى به مروان بن أبي حفصة فقالوا له إن لمروان مذهبا في هجاء آل أبي طالب وذمهم به يحظى وعليه يعطى فاسلكه حتى نفعل قال لا أستحل ذلك قالوا فما تصنع لا يجيء طلب الدنيا إلا بما لا يحل فقال أبان\n(نشدت بحق الله من كان مسلما ... أعم بما قد قلته العجم والعرب)\n(أعم رسول الله أقرب زلفة ... لديه أم ابن العم في رتبة النسب)\n(وأيهما أولى به وبعهده ... ومن ذا له حق التراث بما وجب)\n(فإن كان عباس أحق بتلكم ... وكان علي بعد ذاك على سبب)\n(فأبناء عباس هم يرثونه ... كما العم لإبن العم في الإرث قد حجب)\nوهي طويلة قد تركت ذكرها لما فيه فقال له الفضل ما يرد على أمير المؤمنين اليوم شيء أعجب إليه من أبياتك فركب فأنشدها الرشيد فأمر لأبان بعشرين ألف درهم ثم أتصلت بعد ذلك خدمته الرشيد وخص به أخبرنا أبو العباس بن عمار عن أبي العيناء عن أبي العباس بن رستم قال دخلت مع أبان بن عبد الحميد على عنان جارية الناطفي وهي في\nخيش فقال لها أبان\n(العيش في الصيف خيش ... )\nقالت مسرعة\n(إذ لا قتال وجيش ... )\nأنشدتها أنا لجرير قوله\n(ظللت أواري صاحبي صبابتي ... وهل علقتني من هواك علوق)\nقالت مسرعة\n(إذا عقل الخوف اللسان تكلمت ... بأسراره عين عليه نطوق)\nخبرني الصولي قال حدثنا محمد بن سعيد قال حدثنا عيسى بن إسماعيل عن عبد الله بن محمد بن عثمان بن لاحق قال أولم محمد بن خالد فدعا أبان بن عبد الحميد والعتبي وعبيد الله بن عمرو وسهل بن عبد الحميد والحكم بن قنبر فاحتبس عنهم الغداء فجاء محمد بن خالد فوقف على الباب فقال ألكم أعزكم الله حاجة يمازحهم بذلك فقال أبان\n(حاجتنا فاعجل علينا بها ... من الحشاوى كل طردين)\nقال ابن قنبر بعد ذلك\n(ومن خبيص قد حكت عاشقا ... صفرته زين بتلوين)\nفقال عبيد الله بن عمرو\n(وأتبعوا ذاك بأبية ... فإنكم آيين آبين)\nقال سهل\n(دعنا من الشعر وأوصافه ... واعجل علينا بالأخاوين)\nأحضر الغداء وخلع عليهم ووصلهم","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":2,"spl":"تقرب إلى الرشيد بهجاء آل أبي طالب — تشبيبه بغلام تركي","tags":["الهجاء","المديح"],"loc":3881,"partial":1},
{"id":"b297-7","bab":"الجزء 23","sec":"تشبيبه بغلام تركي","page":"ج23 ص173","text":"أخبرني الصولي قال حدثنا محمد بن زياد قال حدثني أبان بن سعيد الحميدي بن أبان بن عبد الحميد قال اشترى جار لجدي أبان غلاما تركيا بألف دينار وكان أبان يهواه ويخفي ذلك عن مولاه فقال فيه\n(ليتني والجاهل المغرور ... من غر بليت)\n(نلت ممن لا أسمي ... وهو جاري بيت بيت)\n(قبلة تنعش ميتا ... إنني حي كميت)\n(نتساقى الريق بعد الشرب ... من راح كميت)\n(لا أسميه ولكن ... هو في كيت وكيت)\nكان اسمه يتك وقال أبو الفياض سوار بن أبي شراعة\nكان في جوار أبان بن عبد الحميد رجل من ثقيف يقال له محمد بن خالد وكان عدوا لأبان فتزوج بعمارة بنت عبد الوهاب الثقفي وهي أخت عبد المجيد الذي كان ابن مناذر يهواه ورثاه وهي مولاة جنان التي يشبب بها أبو نواس ويقول فيها\n(خرجت تشهد الزفاف جنان ... فاستمالت بحسنها النظاره)\n(قال أهل العروس لما رأوها ... ما دهانا بها سوى عماره)\nال وكانت موسرة فقال أبان بن عبد الحميد يهجوه ويحذرها منه\n(لما رأيت البز والشاره ... والفرش قد ضاقت به الحاره)\n(واللوز والسكر يرمى به ... من فوق ذي الدار وذي الداره)\n(وأحضروا الملهين لم يتركوا ... طبلا ولا صاحب زماره)\n(قلت لماذا قيل أعجوبة ... محمد زوج عماره)\n(لا عمر الله بها بيته ... ولا رأته مدركا ثاره)\n(ماذا رأت فيه وماذا رجت ... وهي من النسوان مختاره)\n(أسود كالسفود ينسى لدى التنور ... بل محراك قياره)\n(يجري على أولاده خمسة ... أرغفة كالريش طياره)\n(وأهله في الأرض من خوفه ... إن أفرطوا في الأكل سياره)\n(ويحك فري وأعصي ذاك بي ... فهذه أختك فراره)\n(إذا غفا بالليل فاستيقظي ... ثم اطفري إنك طفاره)\n(فصعدت نائلة سلما ... تخاف أن تصعده الفاره)\n(سرور غرتها فلا أفلحت ... فإنها اللخناء غراره)\n(لو نلت ما أبعدت من ريقها ... إن لها نفثة سحاره)\nال فلما بلغت قصيدته هذه عمارة هربت فحرم الثقفي من جهتها مالا عظيما قال والثلاثة الأبيات التي أولها\n(فصعدت نائلة سلما ... )\nادها في القصيدة بعد أن هربت","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":2,"spl":"تقرب إلى الرشيد بهجاء آل أبي طالب — تشبيبه بغلام تركي","tags":["الجواري والنساء","الوصف والطبيعة"],"loc":3882,"partial":1},
{"id":"b297-8","bab":"الجزء 23","sec":"ابن مناذر يهجوه","page":"ج23 ص175","text":"أخبرني الأخفش عن المبرد عن أبي وائلة قال كان أبان اللاحقي يولع بابن مناذر ويقول له إنما أنت شاعر في المراثي فإذا مت فلا ترثني فكثر ذلك من أبان عليه حتى أغضبه فقال فيه ابن مناذر\n(غنج أبان ولين منطقه ... يخبر الناس أنه حلقي)\n(داء به تعرفون كلكم ... يا آل عبد الحميد في الأفق)\n(حتى إذا ما المساء جلله ... كان أطباؤه على الطرق)\n(ففرجوا عنه بعض كربته ... بمسبطر مطوق العنق)\nقال وهجاه بمثل هذه القصيدة ولم يجبه أبان خوفا منه وسعي بينهما فأمسك عنه أخبرني الصولي عن محمد بن سعيد عن عيسى بن إسماعيل قال جلس أبان بن عبد الحميد ليلة في قوم فثلب أبا عبيدة فقال يقدح في الأنساب ولا نسب له فبلغ ذلك أبا عبيدة فقال في مجلسه لقد أغفل السلطان كل شيء حتى أغفل أخذ الجزية من أبان اللاحقي وهو وأهله يهود وهذه منازلهم فيها أسفار التوراة وليس فيها مصحف وأوضح الدلالة على يهوديتهم أن أكثرهم يدعي حفظ التوراة ولا يحفظ من القرآن ما يصلي به فبلغ ذلك أبانا فقال\n(لا تنمن عن صديق حديثا ... واستعذ من تسرر النمام)\n(واخفض الصوت إن نطقت بليل ... والتفت بالنهار قبل الكلام)\nأخبرني أبو الحسن الأسدي قال حدثنا عيسى بن إسماعيل تينة قال كنا في مجلس أبي زيد الأنصاري فذكروا أبان بن عبد الحميد فقالوا كان كافرا فغضب أبو زيد وقال كان جاري فما فقدت قرآنه في ليلة قط","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":3,"spl":"ابن مناذر يهجوه — يتنبأ لجاره بالموت المحتم","tags":["الهجاء","الرواية والكتابة"],"loc":3883},
{"id":"b297-9","bab":"الجزء 23","sec":"يتنبأ لجاره بالموت المحتم","page":"ج23 ص176","text":"أخبرنا هاشم بن محمد الخزاعي عن دماذ قال كان لأبان جار وكان يعاديه فاعتل علة طويلة وأرجف أبان بموته ثم صح من علته وخرج فجلس على بابه فكانت علته من السل وكان يكنى أبا الأطول فقال له أبان\n(أبا الأطول طولت ... وما ينجيك تطويل)\n(بك السل ولا والله ... ما يبرأ مسلول)\n(فلا يغررك من ... طبك أقوال أباطيل)\n(أرى فيك علامات ... وللأسباب تأويل)\n(هزالا قد برى جسمك ... والمسلول مهزول)\n(وذبانا حواليك ... فموقوذ ومقتول)\n(وحمى منك في الظهر ... فأنت الدهر مملول)\n(وأعلاما سوى ذاك ... تواريها السراويل)\n(ولو بالفيل مما ... بك عشر ما نجا الفيل)\n(فما هذا على فيك ... قلاع أم دماميل)\n(وما زال مناجيك ... يولي وهو مبلول)\n(لئن كان من الجوف ... لقد سال بك النيل)\n(وذا داء يزجيك ... فلا قال ولا قيل)\nلما أنشده هذا الشعر أرعد واضطرب ودخل منزله فما خرج منه بعد ذلك حتى مات\n(ما تزال الديار في برقة النجد ... لسعدى بقرقرى تبكيني)\n(قد تحيلت كي أرى وجه سعدى ... فإذا كل حيلة تعييني)\n(قلت لما وقفت في سدة الباب ... لسعدى مقالة المسكين)\n(افعلي بي ياربة الخدر خيرا ... ومن الماء شربة فاسقيني)\n(قالت الماء في الركي كثير ... قلت ماء الركي لا يرويني)\n(طرحت دوني الستور وقالت ... كل يوم بعلة تأتيني)\nلشعر لتويت اليمامي والغناء لأبي زكار الأعمى رمل بالوسطى ابتداؤه نشيد من رواية الهشامي","topic":"أخبار أبان بن عبد الحميد ونسبه","topicNo":297,"sp":3,"spl":"ابن مناذر يهجوه — يتنبأ لجاره بالموت المحتم","tags":["الموت"],"song":1,"loc":3884},
{"id":"b298-2","bab":"الجزء 23","sec":"أخبار تويت ونسبه — خبره مع سعدى وصديقاتها","page":"ج23 ص178 – ج23 ص179","text":"تويت لقب واسمه عبد الملك بن عبد العزيز السلولي من أهل اليمامة لم يقع لي غير هذا وجدته بخط أبي العباس بن ثوابة عن عبد الله بن شبيب من أخبار رواها عنه وتويت أحد الشعراء اليماميين من طبقة يحيى بن طالب وبني أبي حفصة وذويهم ولم يفد إلى خليفة ولا وجدت له مديحا في الأكابر والرؤساء فأخمل ذلك ذكره وكان شاعرا فصيحا نشأ باليمامة وتوفي بها\nقال عبد الله بن شبيب كان تويت يهوى أمرأة من أهل اليمامة يقال لها سعدى بنت أزهر وكان يقول فيها الشعر فبلغها شعره من وراء وراء ولم تره فمر بها يوما وهي مع أتراب لها فقلن هذا صاحبك وكان دميما فقامت إليه وقمن معها فضربنه وخرقن ثيابه فاستعدى عليهن فلم يعده الوالي فأنشأ يقول\n(إن الغواني جرحن في جسدي ... من بعد ما قد فرغن من كبدي)\n(وقد شققن الرداء ثمت لم ... يعد عليهن صاحب البلد)\n(لم يعدني الأحول المشوم وقد ... أبصر ما قد صنعن في جسدي)\nقال فلما جرى هذا بينه وبينها عقد له في قلبها رقة وكانت تتعرض له إذا مر بها واجتاز يوما بفنائها فلم تتوار عنه وأرته أنها لم تره فلما وقف مليا سترت وجهها بخمارها فقال تويت\n(ألا أيها الثار الذي ليس نائما ... على ترة إن مت من حبها غدا)\n(خذوا بدمي سعدى فسعدى منيتها ... غداة النقا صادت فؤادا مقصدا)\n(بآية ما ردت غداة لقيتها ... على طرف عينيها الرداء الموردا)\nال ابن شبيب ولقيها راحلة نحو مكة حاجة فأخذ بخطام بعيرها وقال\n(قل للتي بكرت تريد رحيلا ... للحج إذ وجدت إليه سبيلا)\n(ما تصنعين بحجة أو عمرة ... لا تقبلان وقد قتلت قتيلا)\n(أحيي قتيلك ثم حجي وانسكي ... فيكون حجك طاهرا مقبولا)\nقالت له أرسل الخطام خيبك الله وقبحك فأرسله وسارت","topic":"أخبار تويت ونسبه","topicNo":298,"sp":0,"spl":"أخبار تويت ونسبه — خبره مع سعدى وصديقاتها — هجا زوج سعدى يحيى بن أبي حفصة","tags":["المديح"],"loc":3885},
{"id":"b298-3","bab":"الجزء 23","sec":"هجا زوج سعدى يحيى بن أبي حفصة","page":"ج23 ص180","text":"قال عبد الله بن شبيب ثم تزوجها أبو الجنوب يحيى بن أبي حفصة فحجبها وانقطع ما كان بينها وبين تويت فطفق يهجو يحيى فقال\n(عناء سيق للقلب الطروب ... فقد حجبت معذبة القلوب)\n(أقول وقد عرفت لها محلا ... ففاضت عبرة العين السكوب)\n(ألا يا دار سعدى كلمينا ... وما في دار سعدى من مجيب)\n(ولما ضمها وحوى عليها ... تركت لها بعاقبة نصيبي)\n(وقلت زحام مثلك مثل يحيى ... لعمرك ليس بالرأي المصيب)\n(فما لك مثل لمته تدرى ... ومالك مثل بخل أبي الجنوب)\n(إذا فقد الرغيف بكى عليه ... وأتبع ذاك تشقيق الجيوب)\n(يعذب أهله في القرص حتى ... يظلوا منه في يوم عصيب)\nقال أيضا\n(ألا في سبيل الله نفس تقسمت ... شعاعا وقلب للحسان صديق)\n(أفاقت قلوب كن عذبن بالهوى ... زمانا وقلبي ما أراه يفيق)\n(سرقت فؤادي ثم لا ترجعينه ... وبعض الغواني للقولب سروق)\n(عروف الهوى بالوعد حتى إذا جرت ... ببينك غربان لهن نعينق)\n(وردت جمال الحي وانشقت العصا ... وآذن بالبين المشت صدوق)\n(ندمت على ألا تكوني جزيتني ... زعمت وكل الغانيات مذوق)\n(لعلك أن ننأى جميعا بغلة ... تذوقين من حر الهوى وأذوق)\n(عصيت بك الناهين حتى لو أنني ... أموت لما ارعى علي شفيق)","topic":"أخبار تويت ونسبه","topicNo":298,"sp":0,"spl":"أخبار تويت ونسبه — خبره مع سعدى وصديقاتها — هجا زوج سعدى يحيى بن أبي حفصة","tags":["الحب والغزل"],"loc":3886},
{"id":"b298-4","bab":"الجزء 23","sec":"من مختار قوله في سعدى","page":"ج23 ص181","text":"ومن مختار قول تويت في سعدى هذه ما أخذته من رواية عبد الله بن شبيب من قصيدة أولها\n(سنرضي في سعيدى عاذلينا ... بعاقبة وإن كرمت علينا)\nقول فيها\n(لقيت سعيد تمشي في جوار ... بجرعاء النقا فلقيت حينا)\n(سلبن القلب ثم مضين عني ... وقد ناديتهن فما لوينا)\n(فقلت وقد بقيت بغير قلب ... بقلبي يا سعيدى أين أينا)\n(فما تجزين يا سعدى محبا ... يهيم بكم ولا تقضين دينا)\n(فقالوا إذ شكوت المطل منها ... لعمرك من سمعت له قضينا)\n(ومن هذا الذي إن جاء يشكو ... إلينا الحب من سقم شفينا)\n(فهن فواعل بي غير شك ... كما قبلي فعلن بصاحبينا)\n(بعروة والذي بسهام هند ... أصيب فما أقدن ولا ودينا)\nمن مختار قوله فيها\n(سل الأطلال إن نفع السؤال ... وإن لم يربع الركب العجال)\n(عن الخود التي قتلتك ظلما ... وليس بها إذا بطشت قتال)\n(أصابك مقلتان لها وجيد ... وأشنب بارد عذب زلال)\n(أعارك ما تبلت به فؤادي ... من العينين والجيد الغزال)\n(ايا ثارات من قتلته سعدى ... دمي لا تطلبوه لها حلال)\n(أرق لها وأشفق بعد قتلي ... على سعدى وإن قل النوال)\n(وما جادت لنا يوما ببذل ... يمين من سعاد ولا شمال)\nمن قوله فيها أيضا\n(يا بنت أزهر إن ثأري طالب ... بدمي غدا والثأر أجهد طالب)\n(فإذا سمعت براكب متعصب ... ينعي قتيلك فافزعي للراكب)\n(فلأنت من بين الأنام رميتني ... عن قوس متلفة بسهم صائب)\n(لا تأمني شم الأنوف وترتهم ... وتركت صاحبهم كأمس الذاهب)\n(من كان أصبح غالبا لهوى التي ... يهوى فإن هواك أصبح غالبي)\n(قالت وأسبلت الدموع لتربها ... لما اغتررت وأومأت بالحاجب)\n(قولي له بالله يطلق رحله ... حتى يزود أو يروح بصاحب)\nقال فيها أيضا\n(أرق العين من الشوق السهر ... وصبا القلب إلى أم عمر)\n(واعترتني فكرة من حبها ... ويح هذا القلب من طول الفكر)\n(قدر سيق فمن يملكه ... أين من يملك أسباب القدر)\n(كل شيء نالني من حبها ... إن نجت نفسي من الموت هدر)\nقال أيضا\n(لا للرجال لقلبك المتطرف ... والعين إن تر برق نجد تذرف)\n(ولحاجة يوم العبير تعرضت ... كبرت فرد رسولها لم يسعف)\n(يا بنت أزهر ما أراك مثيبتي ... خيرا على ودي لكم وتلطفي)\n(إني وإن خبرت أن حياتنا ... في طرف عينك هكذا لم تطرف)\n(ويظل قلبي من مخافة بينكم ... مثل الجناح معلقا في نفنف)\n(وليظل في هجر الأحبة طالبا ... لرضاك مما جار إن لم تسعف)\n(كأخي الصلاة يغره من مائها ... قطع السراب جرى بقاع صفصف)\n(أهراق نطفته فلما جاءها ... وجد المنية عندها لم تخلف)\n\n(أمنت بإذن الله من كل حادث ... بقربك من خير الورى يابن حارث)\n(إمام حوى إرث النبي محمد ... فأكرم به من إبن عم ووارث)\nلشعر والغناء لمحمد بن الحارث بن بسخنر خفيف رمل بالبنصر مطلق من جامع أغانيه وعن الهشامي","topic":"أخبار تويت ونسبه","topicNo":298,"sp":1,"spl":"من مختار قوله في سعدى — أخبار محمد بن الحارث","tags":["الحب والغزل"],"song":1,"loc":3887},
{"id":"b298-5","bab":"الجزء 23","sec":"أخبار محمد بن الحارث","page":"ج23 ص185","text":"مولى المنصور وأصله من الري من أولاد المرازبه وكان الحارث بن بسخنر أبوه رفيع القدر عند السلطان ومن وجوه قواده وولاه الهادي ويقال الرشيد الحرب والخراج بكور الأهواز كلها فأخبرني حبيب المهلبي\nقال حدثني النوفلي عن محمد بن الحارث بن بسخنر قال كنت بالدير وكان رجل من أهلها يعرض علي الحوائج ويخدمني فيكرمني ويذكر قديمنا ويترحم على أبي فقال لي رجل من أهل تلك الناحية أتعرف سبب شكر هذا لأبيك\nقلت لا قال فإن أباه حدثني وكان يعرف بابن بانة بأن أباك الحارث بن بسخنر اجتاز بهم يريد الأهواز فتلقاه بدجلة العوراء وأهدى له صقورا وبواشق صائدة فقال له الحق بي بالأهواز فقال له يوما إني نظرت في أمور الأعمال بالأهواز فلم أجد شيئا منها يرتفق منه بما قدرت أن أبرك به وقد ساومني التجار بالأهواز بالأرز وقد جعلته لك بالسعر الذي بذلوه وسيأتونني فأعلمهم بذلك فقلت نعم فجاؤوا وخلصوه منه بأربعين ألف دينار فصرت إلى الحارث فأعلمته فقال لي أرضيت بذلك فقلت نعم قال فانصرف\nولما قفل الحارث من الأهواز مر بالمدائن فلقيه الحسين بن محرز المدائني المغني فغناه\n(قد علم الله علا عرشه ... أنى إلى الحارث مشتاق)\nقال له دعني من شوقك إلي وسلني حاجة فإني مبادر فقال له علي دين مائة ألف درهم فقال هي علي وأمر له بها وأصعد","topic":"أخبار تويت ونسبه","topicNo":298,"sp":1,"spl":"من مختار قوله في سعدى — أخبار محمد بن الحارث","tags":[],"loc":3888},
{"id":"b298-6","bab":"الجزء 23","sec":"سار على منهاج إبراهيم بن المهدي","page":"ج23 ص186","text":"وكان محمد بن الحارث من أصحاب إبراهيم بن المهدي والمتعصبين له على إسحاق وعن إبراهيم بن المهدي أخذ الغناء ومن بحره استقى وعلى منهاجه جرى\nأخبرني عيسى بن الحسين الوراق عن محمد بن هارون الهاشمي عن هبة الله بن إبراهيم بن المهدي قال كان المأمون قد ألزم أبي رجلا ينقل إليه كل ما يسمعه من لفظ جدا وهزلا شعرا وغناء ثم لم يثق به فألزمه مكانه محمد بن الحارث بن بسخنر فقال له أيها الأمير قل ما شئت واصنع ما أحببت فوالله لا بلغت عنك أبدا إلا ما تحب وطالت صحبته له حتى أمنه وأنس به وكان محمد يغني بالمعزفة فنقله أبي إلى العود وواظب عليه حتى حذقه ثم\nقال له محمد بن الحارث يوما أنا عبدك وخريجك وصنيعتك فاخصصني بأن أروي عنك صنعتك ففعل وألقى عليه غناءه أجمع فأخذه عنه فما ذهب عليه شيء منه ولا شذ وقال العتابي حدثني محمد بن أحمد بن المكي قال حدثني أبي قال\nكان محمد بن الحارث قليل الصنعة وسمعته يغني الواثق في صنعته في شعر له مدحه به وهو\n(أمنت بإذن الله من كل حادث ... بقربك من خير الورى يابن حارث)\nأمر له بألفي دينار وذكر علي بن محمد الهشامي عن حمدون بن إسماعيل قال كان محمد بن الحارث قد صنع هزجا في هذا الشعر\n(أصبحت عبدا مسترقا ... أبكي الألى سكنوا دمشقا)\n(أعطيتهم قلبي فمن ... يبقى بلا قلب فأبقى)\nطرحه على المسدود فغناه فاسحتسنه محمد بن الحارث منه لطيب مسموع المسدود ثم قال يا مسدود أتحب أن أهبه لك قال نعم قال قد فعلت فكان يغنيه ويدعيه وهو لمحمد بن الحارث","topic":"أخبار تويت ونسبه","topicNo":298,"sp":2,"spl":"سار على منهاج إبراهيم بن المهدي — من ألحانه العشرة","tags":["المديح"],"song":1,"loc":3889},
{"id":"b298-7","bab":"الجزء 23","sec":"من ألحانه العشرة","page":"ج23 ص187","text":"وقال العتابي حدثني شروين المغني المدادي أن صنعة محمد بن الحارث بلغت عشرة أصوات وأنه أخذها كلها عنه وأن منها في طريقه الرمل قال هو أحسن ما صنعه\n(أيا من دعاني فلبيته ... ببذل الهوى وهو لا يبذل)\n(يدل علي بحبي له ... فمن ذاك يفعل ما يفعل)\nلحن محمد بن الحارث في هذا الصوت رمل مطلق وفيه ليزيد حوراء\nثقيل أول وفيه لسليم لحن وجدته في جميع أغانيه غير مجنس أخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد قال حدثني أبو توبة صالح بن محمد عن عمرو بن بانة قال كنت عند محمد بن الحارث بن بسخنر في منزله ونحن مصطبحون في يوم غيم فبينا نحن كذلك إذ جاءتنا رقعة عبد الله بن العباس الربيعي وقد اجتاز بنا مصعدا إلى سر من رأى وهو في سفينة ففضها محمد وقرأها وإذا فيها\n(محمد قد جادت علينا بودقها ... سحائب مزن برقها يتهلل)\n(ونحن من القاطول في شبه مربع ... له مسرح سهل المحلة مبقل)\n(فمر فائزا تفديك نفسي يغنني ... أعن ظعن الحي الالى كنت تسأل)\n(ولا تسقني إلا حلالا فإنني ... أعاف من الأشياء مالا يحلل)\nفقام محمد بن الحارث مستعجلا حافيا حتى نزل إليه فتلقاه وحلف عليه حتى خرج معه وسار به إلى منزله فاصطبحا يومئذ وغناه فائز غلامه هذا الصوت وكان صوته عليه وغناه محمد بن الحارث وجواريه وكل من حضر يومئذ وغنانا عبد الله بن العباس الربيعي أيضا أصواتا وصنع يومئذ هذا الهزج فقال\n(يا طيب يومي بالمطيرة معملا ... للكأس عند محمد بن الحارث)\n(في فتية لا يسمعون لعاذل ... قولا ولا لمسوف أو رائث)\nدثني وسواسه قال حدثني حماد بن إسحاق قال كان أبي يستحسن غناء جواري الحارث بن بسخنر ويعتمد على تعليمهن لجواريه وكان إذا اضطرب على واحدة منهن أو على غيرهن صوت أو وقع فيه اختلاف اعتمد على الرجوع فيه إليهن ولقد غنى مخارق يوما بين يديه صوتا فتزايد فيه الزوائد التي كان يستعملها حتى اضطرب فضحك أبي وقال يا أبا المهنأ قد ساء بعدي أدبك في غنائك فالزم عجائز الحارث بن بسخنر يقومن أودك\n(بنان يد تشير إلى بنان ... تجاوبتا وما يتكلمان)\n(جرى الإيماء بينهما رسولا ... فأحكم وحيه المتناجيان)\n(فلو أبصرته لغضضت طرفا ... عن المتناجيين بلا لسان)\nلشعر لماني الموسوس والغناء لعمر الميداني هزج وفيه لعريب لحن من الهزج أيضا","topic":"أخبار تويت ونسبه","topicNo":298,"sp":2,"spl":"سار على منهاج إبراهيم بن المهدي — من ألحانه العشرة","tags":["الحب والغزل"],"song":2,"loc":3890},
{"id":"b298-9","bab":"الجزء 23","sec":"أخبار ماني الموسوس — أنشد للعريان البصري","page":"ج23 ص189 – ج23 ص190","text":"هو رجل من أهل مصر يكنى أبا الحسن وأسمه محمد بن القاسم شاعر لين الشعر رقيقه لم يقل شيئا إلا في الغزل وماني لقب غلب عليه وكان قدم مدينة السلام ولقيه جماعة من شيوخنا منهم أبو العباس محمد بن عمار وأبو الحسن الأسدي وغيرهما فحدثني أبو العباس بن عمار قال\nكان ماني يألفني وكان مليح الإنشاد حلوه رقيق الشعر غزله فكان ينشدني الشيء ثم يخالط فيقطعه وكان يوما جالسا إلى جنبي فأنشدني للعريان البصري\n(ما أنصفتك العيون لم تكف ... وقد رأيت الحبيب لم يقف)\n(فابك ديارا حل الحبيب بها ... فباع منها الجفاء باللطف)\n(ثم استعارت مسامعا كسد اللوم ... عليها من عاشق كلف)\n(كأنها إذ تقنعت ببلى ... شمطاء ما تستقل من خرف)\n(يا عين إما أريتني سكنا ... غضبان يزوي بوجه منصرف)\n(فمثليه للقلب مبتسما ... في شخص راض علي منعطف)\n(إن تصفيه للقلب منقبضا ... فأنت أشقى منه به فصفي)\n(يقال بالصبر قتل ذي كلف ... كيف وصبري يموت من كلفي)\n(إذا دعا الشوق عبرة لهوى ... فأي جفن يقول لا تكفي)\n(ومستراد للهو تنفسح ... المقلة في حافتيه مؤتلف)\n(قصرت أيامه على نفر ... لا منن بالندى ولا أسف)\n(بحيث إن شئت أن ترى قمرا ... يسعى عليهم بالكأس ذا نطف)","topic":"أخبار تويت ونسبه","topicNo":298,"sp":3,"spl":"أخبار ماني الموسوس — أنشد للعريان البصري — معارضته للعريان","tags":["الحب والغزل"],"loc":3891},
{"id":"b298-10","bab":"الجزء 23","sec":"معارضته للعريان","page":"ج23 ص191","text":"قال فسألته أن يمليها علي ففعل ثم قال اكتب فعارضه أبو الحسن المصري يعني ماني نفسه فقال\n(أقفر مغنى الديار بالنجف ... وحلت عما عهدت من لطف)\n(طويت عنها الرضا مذممة ... لما انطوى غض عيشها الأنف)\n(حللت عن سكرة الصبابة من ... خوف إلهي بمعزل قذف)\n(سئمت ورد الصبا فقد يئست ... مني بنات الخدور والخزف)\n(سلوت عن نهد نسبن إلى ... حسن قوام واللحظ في وطف)\n(يمددن حبل الصبا لمن ألفت ... رجلاه قد المحول والدنف)\n(ومدنف عاد في النحول من الوجد ... إلى مثل رقة الألف)\n(يشارك الطير في النحيب ولا ... يشركنه في النحول والقضف)\n(ومسمعات نهكن أعظمه ... فهو من الضيم غير منتصف)\n(مفتخرات بالجور عجبا كما ... يفخر أهل السفاه بالجنف)\n(وقهوة من نتاج قطربل ... تخطف عقل الفتى بلا عنف)\n(ترجع شرخ الشباب للخرف ... الفاني وتدنى الفتى من الشغف)\nال فبينا هو ينشد إذ نظر إلى إمام المسجد الذي كنا بإزائه قد صعد المئذنة ليؤذن فأمسك عن الإنشاد ونظر إليه وكان شيخا ضعيف الجسم والصوت فأذن أذانا ضعيفا بصوت مرتعش فصعد إليه ماني مسرعا حتى صار معه في رأس الصومعة ثم أخذ بلحيته فصفعه في صلعته صفعة ظننت أنه قد قلع رأسه وجاء لها صوت منكر شديد ثم\nقال له إذا صعدت المنارة لتؤذن فعطعط ولا تمطمط ثم نزل ومضى يعدو على وجهه ولقيت عنتا من عتب الشيخ وشكواه إياي إلى أبي ومشايخ الجيران يقول لهم هذا ابن عمار يجيء بالمجانين فيكتب هذيانهم ويسلطهم على المشايخ فيصفعونهم في الصوامع إذا أذنوا حتى صرت إلى منزله فاعتذرت وحلفت أني إنما أكتب شيئا من شعره وما عرفت ما عمله ولا أحيط به علما","topic":"أخبار تويت ونسبه","topicNo":298,"sp":3,"spl":"أخبار ماني الموسوس — أنشد للعريان البصري — معارضته للعريان","tags":["الحب والغزل","الخمر"],"loc":3892},
{"id":"b298-11","bab":"الجزء 23","sec":"منوسة الجارية تغني وهو يضيف","page":"ج23 ص193","text":"ونسخت من كتاب لإبن البراء حدثني أبي قال عزم محمد بن عبد الله بن طاهر على الصبوح وعنده الحسن بن محمد بن طالوت فقال له محمد كنا نحتاج أن يكون معنا ثالث نأنس به ونلذ في مجاورته فمن ترى أن يكون فقال ابن طالوت لقد خطر ببالي رجل ليس علينا في منادمته ثقل قد خلا من إبرام المجالسين وبرئ من ثقل المؤانسين خفيف الوطأة إذا أدنيته سريع الوثبة إذا أمرته\nقال من هو قال ماني الموسوس قال ما أسأت الإختيار ثم تقدم إلى صاحب الشرطة بطلبه وإحضاره فما كان بأسرع من أن قبض عليه صاحب الشرطة بربع الكرخ فوافى به باب محمد بن عبد الله فأدخل ونظف وأخذ من شعره وألبس ثيابا نظافا وأدخل على محمد بن عبد الله فلما مثل بين يديه سلم فرد عليه\nوقال له أما حان لك أن تزورنا مع شوقنا إليك فقال له ماني أعز الله الأمير الشوق شديد والود عتيد والحجاب صعب والبواب فظ ولو تسهل لنا الإذن لسهلت علينا الزيارة فقال له محمد لقد لطفت في الإستئذان وأمره بالجلوس فجلس وقد كان أطعم قبل أن يدخل فأتى محمد بن عبد الله بجارية لأحدى بنات المهدي يقال لها منوسة وكان يحب السماع منها وكانت تكثر أن تكون عنده فكان أول ما غنته\n(ولست بناس إذ غدوا فتحملوا ... دموعي على الخدين من شدة الوجد)\n(وقولي وقد زالت بعيني حمولهم ... بواكر تحدى لا يكن آخر العهد)\nقال ماني أيأذن لي الأمير قال في ماذا قال في أستحسان ما\nأسمع قال نعم قال أحسنت والله فإن رأيت أن تزيدي مع هذا الشعر هذين البيتين\n(وقمت أدراي الدمع والقلب حائر ... بمقلة موقوف على الضر والجهد)\n(ولم يعدني هذا الأمير بعدله ... على ظالم قد لج في الهجر والصد)\nقال له محمد ومن أي شيء استعديت يا ماني فاستحيا وقال لا من ظلم أيها الأمير ولكن الطرب حرك شوقا كان كامنا فظهر ثم غنت\n(حجبوها عن الرياح لأني ... قلت يا ريح بلغيها السلاما)\n(لو رضوا بالحجاب هان ولكن ... منعوها يوم الرياح الكلاما)\nال فطرب محمد ودعا برطل فشربه فقال ماني ما كان على قائل هذين البيتين لو أضاف إليهما هذين البيتين\n(فتنفست ثم قلت لطيفي ... ويك إن زرت طيفها إلماما)\n(حيها بالسلام سرا وإلا ... منعوها لشقوتي أن تناما)\nقال محمد أحسنت يا ماني ثم غنت\n(يا خليلي ساعة لا تريما ... وعلى ذي صبابة فأقيما)\n(ما مررنا بقصر زينب إلا ... فضح الدمع سرك المكتوما)\nال ماني لولا رهبة الأمير لأضفت إلى هذين البيتين بيتين لا يردان على سمع سامع ذي لب فيصدران إلا عن استحسان لهما فقال محمد الرغبة في حسن ما تأتي به حائلة عن كل رهبة فهات ما عندك فقال\n(ظبية كالهلال لو تلحظ الصخر ... بطرف لغادرته هشيما)\n(وإذا ما تبسمت خلت ما يبدو ... من الثغر لؤلؤا منظوما)\nفقال محمد إن أحسن الشعر ما دام الإنسان يشرب ما كان مكسوا لحنا حسنا تغني به منوسة وأشباهها فإن كسيت شعرك من الألحان مثل ما غنت قبله طاب فقال ذلك إليها فقال له ابن طالوت يا أبا الحسين كيف هي عندك في حسنها وجمالها وغنائها وأدبها قال هي غاية ينتهي إليها الوصف ثم يقف قال قل في ذلك شعرا فقال\n(وكيف صبر النفس عن غادة ... تظلمها إن قلت طاووسه)\n(وجرت إن شبهتها بانة ... في جنة الفردوس مغروسه)\n(وغير عدل إن عدلنا بها ... لؤلؤة في البحر منفوسه)\n(جلت عن الوصف فما فكرة ... تلحقها بالنعت محسوسه)\nقال له ابن طالوت وجب شكرك يا ماني فساعدك دهرك وعطف عليك إلفك ونلت سرورك وفارقت محذورك والله يديم لنا ولك بقاء من ببقائه اجتمع شملنا وطاب يومنا فقال ماني\n(مدمن التخفيف موصول ... ومطيل اللبث مملول)\nأنا أستودعكم الله ثم قام فانصرف فأمر له محمد بن عبد الله بصلة ثم كان كثيرا ما يبعث يطلبه إذا شرب فيبره ويصله ويقيم عنده","topic":"أخبار تويت ونسبه","topicNo":298,"sp":4,"spl":"منوسة الجارية تغني وهو يضيف","tags":["الحب والغزل"],"loc":3893},
{"id":"b298-12","bab":"الجزء 23","sec":"تشبيبه بغلام","page":"ج23 ص195","text":"أخبرني جعفر بن قدامة قال حدثني المبرد قال\nحدثني بعض الكتاب ممن كان ماني يلزمه ويكثر عنده قال لقيني يوما ماني بعد انقطاع طويل عني فقال ما قطعني عنك إلا أني هائم قلت بمن قال بمن إن شئت أن تراه الساعة رأيته فعذرتني قلت فأنا معك فمضى حتى وافى باب الطاق فأراني غلاما جميل الوجه بين يدي بزاز في حانوته فلما رآه الغلام عدا فدخل الحانوت ووقف ماني طويلا ينتظره فلم يخرج فأنشأ يقول\n(ذنبي إليه خضوعي حين أبصره ... وطول شوقي إليه حين أذكره)\n(وما جرحت بطرف العين مهجته ... إلا ومن كبدي يقتص محجره)\n(نفسي على بخله تفديه من قمر ... وإن رماني بذنب ليس يغفره)\n(وعاذل باصطبار القلب يأمرني ... فقلت من أين لي قلب أصبره)\nمضى يعدو ويصيح الموت مخبوء في الكتب\n(وشادن قلبي به معمود ... شيمته الهجران والصدود)\n(لا أسأم الحرص ولا يجود ... والصبر عن رؤيته مفقود)\n(زناره في خصره معقود ... كأنه من كبدي مقدود)\nروضه من - الرجز - والشعر لبكر بن خارجة والغناء للقاسم بن زرزور خفيف رمل بالوسطى","topic":"أخبار تويت ونسبه","topicNo":298,"sp":5,"spl":"تشبيبه بغلام — أخبار بكر بن خارجة حرفته","tags":["الموت"],"song":1,"loc":3894},
{"id":"b298-13","bab":"الجزء 23","sec":"أخبار بكر بن خارجة حرفته","page":"ج23 ص197","text":"كان بكر بن خارجة رجلا من أهل الكوفة مولى لبني أسد وكان وراقا ضيق العيش مقتصرا على التكسب من الوراقة وصرف أكثر ما يكسبه إلى النبيذ وكان معاقرا للشرب في منازل الخمارين وحاناتهم وكان طيب الشعر مليجا مطبوعا طبعا ماجنا فذكر أبو العنبس الصيمري أن محمد بن الحجاج حدثه\nقال رأيت بكر بن خارجة يبكر في كل يوم بقنينتين من شراب إلى خراب من خرابات الحيرة فلا يزال يشربه فيه على صوت هدهد كان يأوي إلى ذلك الخراب إلى أن يسكر ثم ينصرف\nقال وكان يتعشق ذلك الهدهد وحدثني عمي عن ابن مهرويه عن علي بن عبد الله بن سعد قال كان بكر بن خارجة يتعشق غلاما نصرانيا يقال له عيسى بن البراء العبادي الصيرفي وله فيه قصيدة مزدوجة يذكر فيها النصارى وشرائعهم وأعيادهم ويسمي دياراتهم ويفضلهم\nقال وحدثني من شهد دعبلا وقد أنشدني قوله في عيسى بن البراء النصراني العبادي\n(زناره في خصره معقود ... كأنه من كبدي مقدود)\nقال دعبل ما يعلم الله أني حسدت أحدا قط كما حسدت بكرا على هذين البيتين","topic":"أخبار تويت ونسبه","topicNo":298,"sp":5,"spl":"تشبيبه بغلام — أخبار بكر بن خارجة حرفته","tags":["اللهو والمزاح","السفر والحج"],"loc":3895},
{"id":"b298-14","bab":"الجزء 23","sec":"يبكي ويتحسر على الخمر المصبوبة في الطرق","page":"ج23 ص198","text":"وحدثني عمي عن الكراني قال حرم بعض الأمراء بالكوفة بيع الخمر على خماري الحيرة وركب فكسر نبيذهم فجاء بكر يشرب عندهم على عادته فرأى الخمر مصبوبة في الرحاب والطرق فبكى طويلا وقال\n(يا لقومي لما جنى السلطان ... لا يكونن لما أهان الهوان)\n(قهوة في التراب من حلب الكرم ... عقارا كأنها الزعفران)\n(قهوة من مكان سوء لقد صادف ... سعد السعود ذاك المكان)\n(من كميت يبدي المزاج لها ... لؤلؤ نظم والفصل منها جمان)\n(فإذا ما اصطبحتها صغرت في ... القدر تختالها هي الجرذان)\n(كيف صبري عن بعض نفسي وهل يصبر ... عن بعض نفسه الإنسان)\nقال فأنشدتها الجاحظ فقال إن من حق الفتوة أن أكتب هذه الأبيات قائما وما أقدر على ذلك إلا أن تعمدني وقد كان تقوس فعمدته فقام فكتبها قائما وقال محمد بن داود بن الجراح في كتاب الشعراء قال لي محمد بن الحجاج كانت الخمر قد أفسدت عقل بكر بن خارجة في آخر عمره وكان يمدح ويهجو بدرهم وبدرهمين ونحو هذا فاطرح وما رأيت قط أحفظ منه لكل شيء حسن ولا أروى منه للشعر قال وأنشدني بعض أصحابنا له في حال فساد عقله\n(هب لي فديتك درهما ... أو درهمين إلى الثلاثه)\n(إني أحب بني الطفيل ... ولا أحب بني علاثه)\nال ابن الجراح حدثني محمد بن القاسم بن مهرويه قال حدثني بعض أصحابنا الكوفيين قال حضرنا دعوة ليحيى بن أبي يوسف القاضي وبتنا عنده فنمت فما أنبهني إلا صياح بكر يستغيث من العطش فقلت له مالك فاشرب فالدار مليئة ماء قال أخاف قلت من أي شيء قال\nفي الدار كلب كبير فأخاف أن يظنني غزالا فيثب علي ويقطعني ويأكلني فقلت له ويحك يا بكر فالحمير أشبه منك بالغزال قم فاشرب إن كنت عطشان وأنت آمن وكان عقله قد فسد من كثرة الشراب قال وأنشدني له وقد رأى صديقا له قرأ رقعة من صديق له آخر ثم حرقها\n(لم يقو عندي على تحريق قرطاسي ... إلا امرؤ قلبه من صخرة قاسي)\n(إن القراطيس من قلبي بمنزلة ... تحويه كالسمع والعينين في الرأس)\nمما يغنى فيه من شعر بكر بن خارجة\n(قلبي إلى ما ضرني داعي ... يكثر أحزاني وأوجاعي)\n(لقل ما أبقى على ما أرى ... يوشك أن ينعاني الناعي)\n(كيف احتراسي من عدوي إذا ... كان عدوي بين أضلاعي)\n(أسلمني الحب وأشياعي ... لما سعى بي عندها الساعي)\n(لما دعاني حبها دعوة ... قلت له لبيك من داع)\nلغناء لإبراهيم بن المهدي ثقيل أول وفيه لعبد الله بن العباس هزج جميعا عن الهشامي وقيل إن فيه لحنا لإبن جامع وقد ذكر الصولي في أخبار العباس بن الأحنف وشعره أن هذه الأبيات\nللعباس بن الأحنف وذكر محمد بن داود بن الجراح عن أبي هفان أنها لبكر بن خارجة\n(ويلي على ساكن شط الصراه ... من وجنتيه شمت برق الحياه)\n(ما ينقضي من عجب فكرتي ... في خصلة فرط فيها الولاه)\n(ترك المحبين بلا حاكم ... لم يقعدوا للعاشقين القضاه)\nلشعر لإسماعيل القراطيسي والغناء لعباس بن مقام خفيف رمل بالوسطى","topic":"أخبار تويت ونسبه","topicNo":298,"sp":6,"spl":"يبكي ويتحسر على الخمر المصبوبة في الطرق","tags":["الحب والغزل"],"song":2,"loc":3896},
{"id":"b298-15","bab":"الجزء 23","sec":"أخبار إسماعيل القراطيسي بيته ملتقى العابثين","page":"ج23 ص202","text":"هو إسماعيل بن معمر الكوفي مولى الأشاعثة وكان مألفا للشعراء فكان أبو نواس وأبو العتاهية ومسلم وطبقتهم يقصدون منزله ويجتمعون عنده ويقصفون ويدعو لهم القيان وغيرهن من الغلمان ويساعدهم وإياه يعني أبو العتاهية بقوله\n(لقد أمسى القراطيسي ... رئيسا في الكشاخين)\nفي هذه الأبيات التي فيها الغناء يقول القراطيسي\n(وقد أتاني خبر ساءني ... مقالها في السر واسوأتاه)\n(أمثل هذا يبتغي وصلنا ... أما يرى ذا وجهه في المراه)\nخبرني ابن عمار عن ابن مهرويه عن علي بن عمران قال قال\nالقراطيسي قلت للعباس بن الأحنف هل قلت في معنى قولي\n(وقد أتاني خبر ساءني ... مقالها في السر واستوأتاه)\nال نعم وأنشدني\n(جارية أعجبها حسنها ... فمثلها في الناس لم يخلق)\n(خبرتها أني محب لها ... فأقبلت تضحك من منطقي)\n(والتفتت نحو فتاة لها ... كالرشأ الوسنان في قرطق)\n(قالت لها قولي لهذا الفتى ... انظر إلى وجهك ثم أعشق)\nأخبرني الحسن بن مهرويه قال حدثني أحمد بن بشر المرثدي قال مدح إسماعيل القراطيسي الفضل بن الربيع فحرمه فقال\n(ألا قل للذي لم يهده ... الله إلى نفع)\n(لئن أخطأت في مدحيك ... ما أخطأت في منعي)\n(لقد أحللت حاجاتي ... بواد غير ذي زرع)\nخبرني محمد بن جعفر النحوي صهر المبرد عن أبي هفان عن الجماز قال اجتمع يوما أبو نواس وحسين الخليع وأبو العتاهية في الحمام وهم مخمورون فقالوا أين نجتمع فقال القراطيسي\n(ألا قوموا بأجمعكم ... إلى بيت القراطيسي)\n(لقد هيا لنا النزل ... غلام فاره طوسي)\n(وقد هيا الزجاجات ... لنا من أرض بلقيس)\n(وألوانا من الطير ... وألوانا من العيس)\n(وقينات من الحور ... كأمثال الطواويس)\n(فنيكوهن في ذاكم ... وفي طاعة إبليس)\n\n(أبكي إذا غضبت حتى إذا رضيت ... بكيت عند الرضا خوفا من الغضب)\n(فالويل إن رضيت والعول إن غضبت ... إن لم يتم الرضا فالقلب في تعب)\nالشعر لأبي العبر الهاشمي أنشدنيه الأخفش وغيره من أصحابنا وذكره له محمد بن داود بن الجراح والغناء لعلية بنت المهدي ثاني ثقيل بالوسطى عن الهشامي","topic":"أخبار تويت ونسبه","topicNo":298,"sp":7,"spl":"أخبار إسماعيل القراطيسي بيته ملتقى العابثين","tags":["المديح"],"song":1,"loc":3897},
{"id":"b299-2","bab":"الجزء 23","sec":"أخبار أبي العبر ونسبه — كسب بالحمق أضعاف ما كسبه شعراء الجد","page":"ج23 ص204 – ج23 ص205","text":"هو أبو العباس محمد بن أحمد ويلقب حمدونا الحامض بن عبد الله بن عبد الصمد بن علي بن عبد الله بن العباس بن عبد المطلب وكان صالح الشعر مطبوعا يقول الشعر المستوي في أول عمره منذ أيام الأمين وهو غلام إلى أن ولي المتوكل الخلافة فترك الجد وعاد إلى الحمق والشهرة به وقد نيف على الخمسين ورأى أن شعره مع توسطه لا ينفق مع مشاهدته أبا تمام الطائي والبحتري وأبا السمط بن أبي حفصة ونظراءهم\nحدثني عم أبي عبد العزيز بن أحمد قال سمعت حمدون الحامض يذكر أن ابنه أبا العبر ولد بعد خمس سنين خلت من خلافة الرشيد قال وعمر إلى خلافة المتوكل وكسب بالحمق أضعاف ما كسبه كل شاعر كان في عصره بالجد ونفق نفاقا عظيما وكسب في أيام المتوكل مالا جليلا وله فيه أشعار حميدة يمدحه بها ويصف قصره وبرج الحمام والبركة كثيرة المحال مفرطة السقوط لا معنى لذكرها سيما وقد شهرت في الناس فحدثني محمد بن أبي الأزهر قال حدثني الزبير بن بكار قال\nقال لي عمي ويحك ألا يأنف الخليفة لإبن عمه هذا الجاهل مما قد شهر به نفسه وفضح عشيرته والله إنه لعر بني آدم جميعا فضلا عن أهله والأدنين أفلا يردعه ويمنعه من سوء اختياره فقلت إنه ليس بجاهل كما تعتقد وإنما يتجاهل وإن له لأدبا صالحا وشعرا طيبا ثم أنشدته\n(لا أقول الله يظلمني ... كيف أشكو غير متهم)\n(وإذا ما الدهر ضعضعني ... لم تجدني كافر النعم)\n(قنعت نفسي بما رزقت ... وتناهت في العلا هممي)\n(ليس لي مال سوى كرمي ... وبه أمني من العدم)\nقال لي ويحك فلم لا يلزم هذا وشبهه فقلت له والله يا عم لو رأيت ما يصل إليه بهذه الحماقات لعذرته فإن ما استملحت له لم ينفق به فقال عمي وقد غضب أنا لا أعذره في هذا ولو حاز به الدنيا بأسرها لا عذرني الله إن عذرته إذن\nوحدثني مدرك بن محمد الشيباني قال حدثني أبو العنبس الصيمري قال قلت لأبي العبر ونحن في دار المتوكل ويحك أيش يحملك على هذا السخف الذي قد ملأت به الأرض خطبا وشعرا وأنت أديب ظريف مليح الشعر فقال لي يا كشخان أتريد أن أكسد أنا وتنفق أنت أنت أيضا شاعر فهم متكلم فلم تركت العلم وصنعت في الرقاعة نيفا وثلاثين كتابا أحب أن تخبرني لو نفق العقل أكنت تقدم علي البحتري وقد قال في الخليفة بالأمس\n(عن أي ثغر تبتسم ... وبأي طرف تحتكم)\nلما خرجت أنت عليه وقلت\n(في أي سلح ترتطم ... وبأي كف تلتطم)\n(أدخلت رأسك في الرحم ... وعلمت أنك تنهزم)\nأعطيت الجائزة وحرم وقربت وأبعد في حر أمك وحر أم كل عاقل معك فتركته وانصرفت قال مدرك ثم قال لي أبو العنبس قد بلغني أنك تقول الشعر فإن قدرت أن تقوله جيدا جيدا وإلا فليكن باردا باردا مثل شعر أبي العبر وإياك والفاتر فإنه صفع كله","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":0,"spl":"أخبار أبي العبر ونسبه — كسب بالحمق أضعاف ما كسبه شعراء الجد","tags":["أبي العبر","المديح"],"loc":3898},
{"id":"b299-3","bab":"الجزء 23","sec":"له مذهبان متناقضان","page":"ج23 ص207","text":"حدثني جعفر بن قدامة قال حدثني أبو العيناء قال أنشدت أبا العبر\n(ما الحب إلا قبلة ... أو غمز كف وعضد)\n(أو كتب فيها رقى ... أنفذ من نفث العقد)\n(من لم يكن ذا حبه ... فإنما يبغي الولد)\n(ما الحب إلا هكذا ... إن نكح الحب فسد)\nقال لي كذب المأبون وأكل من خراي رطلين وربعا بالميزان فقد أخطأ وأساء ألا قال كما قلت\n(باض الحب في قلبي ... فواويلي إذا فرخ)\n(وما ينفعني حبي ... إذا لم أكنس البربخ)\n(وإن لم يطرح الأصلع ... خرجيه على المطبخ)\nم قال كيف ترى قلت عجبا من العجب قال ظننت أنك تقول لا فأبل يدي وأرفعها ثم سكت فبادرت وانصرفت خوفا من شره حدثني عبد العزيز بن أحمد عم أبي\nقال كان أبو العبر يجلس بسر من رأى في مجلس يجتمع عليه فيه المجان يكتبون عنه فكان يجلس على سلم وبين يديه بلاعة فيها ماء وحمأة وقد سد مجراها وبين يديه قصبة طويلة وعلى رأسه خف وفي رجليه قلنسيتان ومستمليه في جوف بئر وحوله ثلاثة نفر يدقون بالهواوين حتى تكثر الجلبة ويقل السماع ويصيح مستمليه من جوف البئر من يكتب عذبك الله ثم يملي عليهم فإن ضحك أحد ممن حضر قاموا فصبوا على رأسه من ماء البلاعة إن كان وضيعا وإن كان ذا مروءة رشش عليه بالقصبة من مائها ثم يحبس في الكنيف إلى أن ينفض المجلس ولا يخرج منه حتى يغرم درهمين\nقال وكانت كنيته أبا العباس فصيرها أبا العبر ثم كان يزيد فيها في كل سنة حرفا حتى مات وهي أبو العبر طرد طيل طليري بك بك بك حدثني جحظة قال رأيت أبا العبر بسر من رأى وكان أبوه شيخا صالحا وكان لا يكلمه فقال له بعض إخوانه لم هجرت إبنك قال\nفضحني كما تعلمون بما يفعله بنفسه ثم لا يرضى بذلك حتى يهجنني ويؤذيني ويضحك الناس مني فقالوا له وأي شيء من ذاك وبماذا هجنك قال اجتاز علي منذ أيام ومعه سلم فقلت له ولأي شيء هذا معك فقال لا أقول لك فأخجلني وأضحك بي كل من كان عندي فلما أن كان بعد أيام اجتاز بي ومعه سمكة فقلت له أيش تعمل بهذه فقال أنيكها فحلفت لا أكلمه أبدا","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":1,"spl":"له مذهبان متناقضان — مذهبه في الكتابة وفي الصيد","tags":["أبي العبر","الحب والغزل"],"loc":3899},
{"id":"b299-4","bab":"الجزء 23","sec":"مذهبه في الكتابة وفي الصيد","page":"ج23 ص209","text":"أخبرني عم أبي عبد العزيز قال سمعت رجلا سأل أبا العبر عن هذه المحالات التي لا يتكلم بها أي شيء أصلها قال أبكر فأجلس على الجسر ومعي دواة ودرج فأكتب كل شيء أسمعه من كلام الذاهب والجائي والملاحين والمكارين حتى أملأ الدرج من الوجهين ثم أقطعه عرضا وطولا وألصقه مخالفا فيجيء منه كلام ليس في الدنيا أحمق منه\nأخبرني عمي قال رأيت أبا العبر واقفا على بعض آجام سر من رأى وبيده اليسرى قوس جلاهق وعلى يده اليمنى باشق وعلى رأسه قطعة رثة في حبل مشدود بأنشوطة وهو عريان في أيره شعر مفتول مشدود فيه شص قد ألقاه في الماء للسمك وعلى شفته دوشاب ملطخ فقلت له خرب بيتك أيش هذا العمل فقال أصطاد ياكشخان\nيا أحمق بجميع جوارحي إذا مر بي طائر رميته عن القوس وإن سقط قريبا مني أرسلت إليه الباشق والرئة التي على رأسي يجيء الحدأ ليأخذها فيقع في الوهق والدوشاب أصطاد به الذباب وأجعله في الشص فيطلبه السمك ويقع فيه والشص في أيري فإذا مرت به السمكة أحسست بها فأخرجتها\nقال وكان المتوكل يرمي به في المنجنيق إلى الماء وعليه قميص حرير فإذا علا في الهواء صاح الطريق الطريق ثم يقع في الماء فتخرجه السباح قال وكان المتوكل يجلسه على الزلاقة فينحدر فيها حتى يقع في البركة ثم يطرح الشبكة فيخرجه كما يخرج السمك ففي ذلك يقول في بعض حماقاته\n(ويأمر بي الملك ... فيطرحني في البرك)\n(ويصطادني بالشبك ... كأني من السمك)\n(ويضحك كك كك ككك ... ككك كك ككك كك ككك)","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":1,"spl":"له مذهبان متناقضان — مذهبه في الكتابة وفي الصيد","tags":["أبي العبر","اللهو والمزاح","السفر والحج"],"loc":3900},
{"id":"b299-6","bab":"الجزء 23","sec":"عبثه مع إسحاق بن إبراهيم — شعره في غلام أمرد","page":"ج23 ص210 – ج23 ص211","text":"وحدثني جعفر بن قدامة قال قدم أبو العبر بغداد في أيام المستعين وجلس للناس فبعث إسحاق بن إبراهيم فأخذه وحبسه فصاح في الحبس لي نصيحة فأخرج ودعا به إسحاق فقال هات نصيحتك قال على أن تؤمنني قال نعم قال الكشكية أصلحك الله لا تطيب إلا بالكشك فضحك إسحاق وقال هو فيما أرى مجنون فقال لا هو امتخط حوت\nقال أيش هو امتخط حوت ففهم ما قاله وتبسم ثم قال أظن أني فيك مأثوم قال لا ولكنك في ماء بصل فقال أخرجوه عني إلى لعنة الله ولا يقيم ببغداد فأرده إلى الحبس فعاد إلى سر من رأى\nوله أشعار ملاح في الجد منها ما أنشدنيه الأخفش له يخاطب غلاما أمرد\n(أيها الأمرد المولع بالهجر ... أفق ما كذا سبيل الرشاد)\n(فكأني بحسن وجهك قد ألبس ... في عارضيك ثوب حداد)\n(وكأني بعاشقيك وقد بدلت ... فيهم من خلطة ببعاد)\n(حين تنبو العيون عنك كما ينقبض ... السمع عن حديث معاد)\n(فاغتنم قبل أن تصير إلى كان ... وتضحي في جملة الأضداد)\nأنشدني محمد بن داود بن الجراح له وفيه رمل طنبوري محدث أظنه لجحظة\n(داء دفين وهوى بادي ... أظلم فجازيك بمرصاد)\n(يا واحد الأمة في حسنه ... أشمت بي صدك حسادي)\n(قد كدت مما نال مني الهوى ... أخفى على أعين عوادي)\n(عبدك يحيي موته قبلة ... تجعلها خاتمة الزاد)\nخبرني الحسن بن علي قال حدثنا محمد بن القاسم بن مهرويه قال حدثني أحمد بن علي الأنباري قال\nكنا يوما في مجلس يزيد بن محمد المهلبي بسر من رأى فجرى ذكر أبي العبر فجعلوا يذكرون حماقاته وسقوطه فقلت ليزيد كيف كان عندك فقد رأيته فقال ما كان إلا أديبا فاضلا ولكنه رأى الحماقة أنفق وأنفع له فتحامق فقلت له أنشدك أبياتا له أنشدنيها فانظر لو أراد دعبل فإنه أهجى أهل زماننا أن يقول في معناها ما قدر على أن يزيد على ما قال قال أنشدنيها فأنشدته قوله","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":2,"spl":"عبثه مع إسحاق بن إبراهيم — شعره في غلام أمرد — هجوه قاضيين أعورين","tags":["أبي العبر","الحب والغزل"],"song":1,"loc":3901},
{"id":"b299-7","bab":"الجزء 23","sec":"هجوه قاضيين أعورين","page":"ج23 ص212","text":"(رأيت من العجائب قاضيين ... هما أحدوثة في الخافقين)\n(هما اقتسما العمى نصفين فذا ... كما اقتسما قضاء الجانبين)\n(هما فأل الزمان بهلك يحيى ... إذا أفتتح القضاء بأعورين)\n(وتحسب منهما من هز رأسا ... لينظر في مواريث ودين)\n(كأنك قد جعلت عليه دنا ... فتحت بزاله من فرد عين)\nجعل يضحك من قوله ويعجب منه ثم كتب الأبيات أخبرني الحسن بن علي قال حدثنا محمد بن مهرويه قال حدثني ابن أبي أحمد قال قال لي أبو العبر إذا حدثك إنسان بحديث لا تشتهي أن تسمعه فاشتغل عنه بنتف إبطك حتى يكون هو في عمل وأنت في عمل وقال محمد بن داود حدثني أبو عبد الله الدوادي قال\nكان أبو العبر شديد البغض لعلي بن أبي طالب صلوات الله عليه وله في العلويين هجاء قبيح وكان سبب ميتته أنه خرج إلى الكوفة ليرمي بالبندق مع الرماة من أهلها في آجامهم فسمعه بعض الكوفيين يقول في علي صلوات الله عليه قولا قبيحا استحل به دمه فقتله في بعض الآجام وغرقه فيها\n(لقد طال عهدي بالإمام محمد ... وما كنت أخشى أن يطول به عهدي)\n(فأصبحت ذا بعد وداري قريبة ... فواعجبا من قرب داري ومن بعدي)\n(فياليت أن العيد لي عاد مرة ... فإني رأيت العيد وجهك لي يبدي)\n(رأيتك في برد النبي محمد ... كبدر الدجى بين العمامة والبرد)\nلشعر لمروان بن أبي حفصة الأصغر والغناء لبنان خفيف رمل بالبنصر","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":2,"spl":"عبثه مع إسحاق بن إبراهيم — شعره في غلام أمرد — هجوه قاضيين أعورين","tags":["أبي العبر"],"song":1,"loc":3902},
{"id":"b299-8","bab":"الجزء 23","sec":"تقرب إلى المتوكل بهجاء آل أبي طالب","page":"ج23 ص214","text":"هو مروان بن أبي الجنوب بن مروان الأكبر بن أبي حفصة قد تقدم خبره ونسبه ويكنى مروان الأصغر أبا السمط وكان يتشبه بجده في شعره ويمدح المتوكل ويتقرب إليه بهجاء آل أبي طالب فتمكن منه وقرب إليه وكسب معه مالا كثيرا فلما أفضت الخلافة إلى المنتصر تجنب مذهب أبيه في كل أمر فطرده وحلف ألا يدخل إليه أبدا لما كان يسمعه منه في أمير المؤمنين علي رضي الله عنه فأخبرني محمد بن عمران الصيرفي وعمي قالا حدثنا الحسن بن عليل العنزي قال حدثني محمد بن عبد الله بن آدم العبدي قال دخل مروان بن أبي الجنوب على المتوكل فأنشده قوله\n(سلام على جمل وهيهات من جمل ... ويا حبذا جمل وإن صرمت حبلي)\nهي من مشهور شعره وفيها يقول\n(أبوكم علي كان أفضل منكم ... أباه ذوو الشورى وكانوا ذوي عدل)\n(وساء رسول الله إذ ساء بنته ... بخطبته بنت اللعين أبي جهل)\n(أراد على بنت النبي تزوجا ... ببنت عدو الله يا لك من فعل)\n(فذم رسول الله صهر أبيكم ... على منبر الإسلام بالمنطق الفصل)\n(وحكم فيها حاكمين أبوكم ... هما خلعاه خلع ذي النعل للنعل)\n(وقد باعها من بعده الحسن ابنه ... فقد أبطلا دعواكما الرثة الحبل)\n(وخليتموها وهي في غير أهلها ... وطالبتموها حيث صارت إلى الأهل)\nوهب له المتوكل مائة ألف درهم وقال محمد بن داود بن الجراح حدثني محمد بن القاسم قال حدثني أبو هاشم الجبائي قال دخل أبو السمط على المتوكل فأنشده قوله\n(الصهر ليس بوارث ... والبنت لا ترث الإمامه)\n(لو كان حقكم لهم ... قامت على الناس القيامه)\n(أصبحت بين محبكم ... والمبغضين لكم علامه)\nحشا المتوكل فمه بجوهر لا يدرى ما قيمته وحدثني أحمد بن جعفر جحظة قال أنشد أبو السمط المتوكل قوله\n(إني نزلت بساحة المتوكل ... ونزلت في أقصى ديار الموصل)\nقال الفتح بن خاقان فإذا كانا متباعدين هكذا فمن كان الرسول فقال أبو العنبس الصيمري كانت له طيور هدى تحمل إليها كتبه فضحك المتوكل حتى ضرب برجله الأرض وأجزل صلة الصيمري ولم يعط\nأبا السمط شيئا فماتا متهاجرين أخبرني عمي والحسن بن علي قالا حدثنا محمد بن القاسم بن مهرويه قال حدثنا حماد بن أحمد البني قال أخبرني أبو السمط مروان بن أبي الجنوب قال لما صرت إلى المتوكل على الله ومدحته ومدحت ولاة العهود الثلاثة وأنشدته ذلك في قولي\n(سقى الله نجدا والسلام على نجد ... ويا حبذا نجد على الناي والبعد)\n(نظرت إلى نجد وبغداد دونها ... لعلي أرى نجدا وهيهات من نجد)\n(بلاد بها قوم هواهم زيارتي ... ولا شيء أشهى من زيارتهم عندي)\nلما استتممتها أمر لي بمائة ألف درهم وخمسين ثوبا من خاص ثيابه","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":3,"spl":"تقرب إلى المتوكل بهجاء آل أبي طالب","tags":["أبي العبر","الحب والغزل","الهجاء"],"loc":3903},
{"id":"b299-9","bab":"الجزء 23","sec":"عمر الطنبوري يغني بين يدي المتوكل","page":"ج23 ص216","text":"أخبرني علي بن أبي العباس بن أبي طلحة قال حدثني إبراهيم بن محمد أبو إسحاق قال حدثني خالد بن يزيد الكاتب قال دعاني المتوكل ليلة وقد غنى بين يديه عمر الطنبوري في قولي\n(يا مقلتي قتلتماني ... فبقيت رحمة من يراني)\n(من ذا ألوم وأنتما ... بيد الهوى أسلمتماني)\nال ولم يغنه البيت الثالث وهو\n(لعبت بنا أيدي الخطوب ... وغالنا ريب الزمان)\nراهة أن يتطير منه فجعل ينظر إلي وأنا واقف ثم قال لي ويلك\nيا خالد تهرب منا ونحن نطلبك وأنت في غيابات صبواتك وغزلك يا غلام اسقه ثلاثة أقداح في القدح المبرم وهو الذي لا قرار له فإذا أخذه الإنسان لم يقدر أن يضعه من يده فقلت\n(سيدي لا تسقني ... أكثر من رطل نبيذ)\n(إن شربي للذي ... يؤلمني غير لذيذ)\nقال يا غلام إن لم يشرب فاصفعه فقلت\n(سيدي حوصلتي ضييقه ... عن شرب رطل)\n(فمتى زدت عليه ... خفت أن يذهب عقلي)\nقال الفتح هو كما قال يا سيدي لا يطيق الشرب وحضر ابن أبي حفصة فقال لنا المتوكل قولا على البديهة فقلت له هو يا سيدي شيخ الشعراء ومادحك وآباؤه مداح أبائك فأنشأ يقول\n(يا ليت لي ألف عين ... عيناي لا تكفيان)\nقلت له سخنت عينك أنا لي عين واحدة أدعو الله عليها بالعمى منذ ستين سنة أقول\n(يا عين أنت بليتني ... فأراحني الرحمن منك)\nأنت تتمنى ألف عين ثم قال لي المتوكل اهجه فقلت إن الرجل لم يعرض لي فأقبل هو علي وقال قل ما شئت وما عسى أن تقول فقلت\n(زاد البرد يومين ... فقال الناس ما القصه)\n(فقلنا أنشدونا شعر ... مروان بن أبي حفصه)\n(فتى من شهوة النيك ... بحلقوم استه غصه)\n(ولو يرمى ببطيخ ... لوافى دبره رصه)\nقال فضحك المتوكل حتى صفق برجليه الأرض وأفحم مروان ثم أمر لي بجائزة فأخذتها وانصرفت","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":4,"spl":"عمر الطنبوري يغني بين يدي المتوكل — مدح المتوكل فأثابه","tags":["أبي العبر"],"loc":3904},
{"id":"b299-10","bab":"الجزء 23","sec":"مدح المتوكل فأثابه","page":"ج23 ص218","text":"قال ابن أبي طاهر حدثني مروان بن أبي الجنوب قال لما استخلف المتوكل بعثت إلى ابن أبي دواد بقصيدة مدحته فيها وذكرت فيها ابن الزيات ببيتين هما\n(وقيل لي الزيات لاقى حمامه ... فقلت أتاني الله بالفتح والنصر)\n(لقد حفر الزيات بالبغي حفرة ... فألقاه فيها الله بالكفر والغدر)\nال فذكرني ابن أبي دواد للمتوكل فأمر بإحضاري فقيل له نفاه الواثق إلى اليمامة وذلك لميله إليك فقال يحمل فقال له ابن أبي دواد عليه ستة آلاف دينار دين فقال يكتب له بها إلى عامل اليمامة فكتب لي بها وبالحملان والمعونة فقدمت عليه وأنشدته قولي\n(رحل الشباب وليته لم يرحل ... والشيب حل وليته لم يحلل)\nفلما بلغت إلى هذا البيت\n(كانت خلافة جعفر كنبوة ... جاءت بلا طلب ولا بتمحل)\n(وهب الإله لك الخلافة مثل ما ... ورهب النبوة للنبي المرسل)\nأمر لي بخمسين ألف درهم وفي أول هذه القصيدة لعريب ثاني ثقيل بالوسطى والصوت المذكور في أول هذه الأخبار من قصيدة قالها أبو السمط في المنتصر لما ولي الخلافة","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":4,"spl":"عمر الطنبوري يغني بين يدي المتوكل — مدح المتوكل فأثابه","tags":["أبي العبر","المديح"],"song":1,"loc":3905},
{"id":"b299-11","bab":"الجزء 23","sec":"المنتصر يرفض أن يأذن له بالدخول","page":"ج23 ص219","text":"أخبرني بخبره فيها جماعة من أصحابنا منهم محمد بن جعفر النحوي صهر المبرد والحسن بن علي قالا حدثنا محمد بن موسى قال حدثني القاسم بن محمد الكاتب قال حدثني المرزبان بن الفروران حاجب المنتصر قال إن مروان بن أبي حفصة الأصغر المكنى أبا السمط استأذن على المنتصر لما ولي الخلافة فقال والله لا أذنت للكافر ابن الزانية أليس هو القائل\n(وحكم فيها حاكمين أبوكم ... هما خلعاه خلع ذي النعل للنعل)\nولوا له والله لا وصلت إلي أبدا فلما بلغه هذا القول عمل هذا الشعر\n(لقد طال عهدي بالإمام محمد ... وما كنت أخشى أن يطول به عهدي)\nذكر الأبيات كلها قال وسأل بنان بن عمرو فصنع فيه لحنا وغنى به المنتصر فلما سمعه سأل عن قائلها فأخبرته فقال أما الوصول إلي فلا سبيل إليه ولكن أعطوه\nعشرة آلاف درهم يتحمل بها إلى اليمامة أخبرني علي بن العباس بن أبي طلحة الكاتب قال حدثني جعفر بن هارون بن زياد قال حدثني أحمد بن الفضل الكاتب قال لما قال علي بن الجهم هذه القصيدة في المتوكل\n(غتنم جدة الزمان الجديد ... واجعل المهرجان أيمن عيد)\nنشدها وأبو السمط بن أبي حفصة حاضر فغمزه المتوكل على علي بن الجهم وأمره أن يعنته فقال له يا علي أخبرني عن قولك\n(واجعل المهرجان أيمن عيد ... )\nلمهرجان عيد أم يوم لهو إنما العيد ما تعبد الله به الناس مثل الفطر والأضحى والجمعة وأيام التشريق فأما المهرجان والنيروز فإنما هما أعياد المجوس لا يجوز أن يقال لخليفة الله في عباده وخليفة رسول الله في أمته جعل المهرجان عيدا فلم يلتفت إليه وأنشد حتى بلغ قوله\n(نحن أشياعكم من آل خراسان ... أولو قوة وبأس شديد)\n(نحن أبناء هذه الخرق السود ... وأهل التشيع المحمود)\nقال له مروان لو كنتم من أهل التشيع المحمود ما قتل قحطبة جدك وصلبه في عداوة بني العباس فقال له المتوكل ويلك أقتل قحطبة جدك\nقال لا والله يا أمير المؤمنين فأقبل على محمد بن عبد الله بن طاهر فقال له بحياتي الأمر كما قال مروان فقال له محمد وإن كان كما قال فأي ذنب لعلي بن الجهم قد قتل الله أعداءكم وأبقى أولياءكم فضحك المتوكل وقال شهدت والله بها عليه فقال مروان في ذلك\n(غضب ابن الجهم من قولي له ... إن في الحق لقوم مغضبه)\n(يابن جهم كيف تهوى معشرا ... صلبوا جدك فوق الخشبه)\n(يا إمام العدل نصحي لكم ... نصح حق غير نصح الكذبه)\n(إن جدي من رفعتم ذكره ... بكرامات لشكري موجبه)\n(وابن جهم من قتلتم جده ... وتولى ذاك منه قحطبه)\n(فخراسان رأت شيعتكم ... أنه أهل لضرب الرقبه)\n(أتراه بعدها ينصحكم ... لا ورب الكعبة المحتجبه)","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":5,"spl":"المنتصر يرفض أن يأذن له بالدخول — هجاؤه لعلي بن الجهم","tags":["أبي العبر"],"loc":3906,"partial":1},
{"id":"b299-12","bab":"الجزء 23","sec":"هجاؤه لعلي بن الجهم","page":"ج23 ص221","text":"أخبرني علي بن العباس بن أبي طلحة قال حدثني جعفر بن هارون قال حدثني أحمد بن حمدون بن إسماعيل قال بلغ المتوكل أن علي بن الجهم خطب امرأة من قريش فلم يزوجوه فسأل عن السبب في ذلك وعن قصته وعن نسب سامة بن لؤي فحدث بها ثم انتهى حديثهم بأن أبا بكر وعمر رضي الله عنهما لم يدخلاهم في قريش وأن عثمان رضي الله عنه أدخلهم فيه وأن عليا رضي الله عنه أخرجهم منه فارتدوا مع الحارث وأنه قتل من ارتد منهم وسبى بقيتهم وباعهم من مصقلة بن\nهبيرة فضحك المتوكل وبعث إلى علي بن الجهم فأخبره بما قال القوم فأنكر ذلك وقال هذه الدعوى من الرافضة وشتم القوم وكان منهم أبو السمط فقال له\n(إن جهما حين تنسبه ... ليس من عجم ولا عرب)\n(لج في شتمي بلا سبب ... سارق للشعر والنسب)\n(من أناس يدعون أبا ... ماله في الأرض من عقب)\nغضب علي بن الجهم ولم يجبه لأنه كان يحتقره ويستركه وأومأ إليه المتوكل أن يزيده فقال\n(أأنتم من قريش يابن جهم ... وقد باعوكم في من يزيد)\n(أترجو أن تكاثرنا جهارا ... بنسبتكم وقد بيع الجدود)\nال وما زال مروان يهجو علي بن الجهم فما أجابه عن شيء من شعره أنفة منه","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":5,"spl":"المنتصر يرفض أن يأذن له بالدخول — هجاؤه لعلي بن الجهم","tags":["أبي العبر"],"loc":3907},
{"id":"b299-13","bab":"الجزء 23","sec":"مدح أحمد بن أبي دواد فنال مكافأته","page":"ج23 ص222","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا إسحاق بن محمد النخعي قال حدثني الجماز أبو عبد الله قال دخل مروان الأصغر على أحمد بن أبي دواد وقد أصابه الفالج وتماثل قليلا فأنشده\n(لسان أحمد سيف مسه طبع ... من علة فجلاه عنه جاليها)\n(ما ضر أحمد باقي علة درست ... والله يذهب عنه رسم باقيها)\n(قد كان موسى على علات منطقه ... رسائل الله إذ جاءت يؤديها)\n(موسى بن عمران لم ينقص نبوته ... ضعف اللسان وقدما كان يمضيها)\nوصله أحمد رحمه الله تعالى واعتذر إليه أخبرني عمي قال حدثني متوج قال قال أبو السمط دخلت على عبد الله بن طاهر فقال إني تذكرت في ليلتي هذه ذا اليمينين فبت أرقا حزينا باكيا فارثه في مقامك هذا بأبيات تجعل لي طريقا إلى شفاء علتي ولك حكمك ففكرت هنيهة ثم قلت\n(إن المكارم إذ تولى طاهر ... قطع الزمان يمينها وشمالها)\n(لو كافحته يد المنون مجاهرا ... لاقت لوقع سيوفه آجالها)\n(أرسى عماد خليفة في هاشم ... ورمى عماد خلافة فأزالها)\n(بكت الأعنة والأسنة طاهرا ... ولطالما روى النجيع نهالها)\n(ليت المنون تجانبت عن طاهر ... ولوت بذروة من تشاء حبالها)\n(ما كنت لو سلمت يمينا طاهر ... أدري ولا أسل الحوادث مالها)\nقال أحسنت والله فاحتكم فقلت له خمسون ألف درهم أقضي منها دينا وأصلح حالي وأبتاع ضيعة تلاصق ضيعتي فأمر لي بها وقال ربحنا\nوخسرت ولو لم تحتكم لزدتك ولك عندنا عد وعد بعد عد\n(لا تلمني أن أجزعا ... سيدي قد تمنعا)\n(وابلائي إن كان ما ... بيننا قد تقطعا)\n(إن موسى بفضله ... جمع الفضل أجمعا)\nلشعر ليوسف بن الصيقل والغناء لإبراهيم خفيف رمل بالبنصر","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":6,"spl":"مدح أحمد بن أبي دواد فنال مكافأته — نسبه هذا الصوت الذي غناه","tags":["أبي العبر"],"song":1,"loc":3908},
{"id":"b299-14","bab":"الجزء 23","sec":"نسبه","page":"ج23 ص225","text":"هو يوسف بن الحجاج الصيقل يقال إنه من ثقيف ويقال إنه مولى لهم وذكر محمد بن داود بن الجراح أنه كان يلقب لقوة وأنه كان يصحب أبا نواس ويأخذ عنه ويروي له وأبوه الحجاج ين يوسف محدث ثقة\nوروى عنه جماعة من شيوخنا منهم ابن منيع والحسن بن الطيب الشجاع وابن عفير الأنصاري وكان يوسف بن الصيقل كاتبا ومولده ومنشؤه بالكوفة أخبرني إسماعيل بن يونس الشيعي عن ابن شبة\nقال قال أحمد بن صالح الهشامي قال لنا يوسف بن الصيقل يوما ورأى الشعراء بأيديهم الرقاع يطوفون بها فقال صنع الله لكم ثم أقبل على إبراهيم الموصلي فقال له كنا\nنهزل فنأخذ الرغائب وهؤلاء المساكين الآن يجدون فلا يعطون شيئا ثم قال لإبراهيم أتذكر ونحن بجرجان مع موسى الهادي وقد شرب على مستشرف عال جدا وأنت تغنيه هذا الصوت\n(واستدارت رحالهم ... بالرديني شرعا)\nقال هذا لحن مليح ولكني أريد له شعرا غير هذا فإن هذا شعر بارد والتفت إلي فقال اصنع في هذا الوزن شعرا فقلت\n(لا تلمني أن أجزعا ... سيدي قد تمنعا)\nغنيته فيه بذلك اللحن ومرت به إبل ينقل عليها فقال أوقروها لهما مالا فأوقرت مالا وحمل إلينا فاقتسمناه فقال إبراهيم نعم وأصاب كل واحد منا ستين ألف درهم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":6,"spl":"مدح أحمد بن أبي دواد فنال مكافأته — نسبه هذا الصوت الذي غناه","tags":["أبي العبر"],"loc":3909},
{"id":"b299-15","bab":"الجزء 23","sec":"نسبه هذا الصوت الذي غناه","page":"ج23 ص226","text":"\n(فارس يضرب الكتيبة ... حتى تصدعا)\n(في الوغى حين لا يرى ... صاحب القوس منزعا)\n(واستدارت رحالهم ... بالرديني شرعا)\n(ثم ثارت عجاجة ... تحتها الموت منقعا)\nفي هذه الأبيات رمل ينسب إلى ابن سريج وإلى سياط وفيه لإبن جامع خفيف رمل بالبنصر\nأخبرني الحسن بن علي قال حدثنا عبد الله بن أبي سعد عن محمد بن عبد الله العبدي فذكر مثل هذه القصة إلا أنه حكى أنها كانت بالرقة لا بجرجان وأن الرشيد كان صاحبها لا موسى","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":6,"spl":"مدح أحمد بن أبي دواد فنال مكافأته — نسبه هذا الصوت الذي غناه","tags":["أبي العبر"],"song":1,"loc":3910},
{"id":"b299-16","bab":"الجزء 23","sec":"مدح الرشيد فأجازه","page":"ج23 ص227","text":"أخبرني الحسن بن علي العنزي عن محمد بن يونس الربيعي قال حدثني أبو سعيد الجند يسابوري قال لما ورد الرشيد الرقة خرج يوسف بن الصيقل وكمن له في نهر جاف على طريقه وكان لهارون خدم صغار يسميهم النمل يتقدمونه بأيديهم قسي البندق يرمون بها من يعارضه في طريقه فلم يتحرك يوسف حتى وافته قبة هارون على ناقة فوثب إليه يوسف وأقبل الخدم الصغار يرمونه فصاح بهم الرشيد كفوا عنه فكفوا وصاح به يوسف يقول\n(أغيثا تحمل الناقة ... أم تحمل هرونا)\n(أم الشمس أم البدر ... أم الدنيا أم الدينا)\n(الا كل الذي عددت ... قد أصبح مقرونا)\n(على مفرق هارون ... فداه الآدميونا)\nمد الرشيد يده إليه وقال له مرحبا بك يا يوسف كيف كنت بعدي ادن مني فدنا وأمر له بفرس فركبه وسار إلى جانب قبته ينشده ويحدثه\nوالرشيد يضحك وكان طيب الحديث ثم أمر له بمال وأمر بأن يغنى في الأبيات الغناء في هذه الأبيات لإبن جامع خفيف رمل بالبنصر عن الهشامي وقال محمد بن داود كان يوسف فاسقا مجاهرا باللواط وله فيه أشعار فمنها قوله\n(لا تبخلن على النديم ... بردف ذي كشح هضيم)\n(تعلو وينظر حسرة ... نظر الحمار إلى القضيم)\n(وإذا فرغت فلا تقم ... حتى تصوت بالنديم)\n(فإذا أجاب فقل هلم ... إلى شهادة ذي الغريم)\n(واتبع للذتك الهوى ... ودع الملامة للمليم)\nال وهذا الشعر يقوله لصديق له رآه قد علا غلاما له فخاطبه به ومن مشهور قوله في هذا المعنى\n(لا تنيكن ما حييت ... غلاما مكابره)\n(لا تمرن باسته ... دون دفع المؤامره)\n(إن هذا اللواط دين ... تراه الأساوره)\n(وهم فيه منصفون ... بحسن المعاشره)\nمن قوله في هذا المعنى أيضا هذه الأبيات\n(ضع كذا صدرك لي يا سيدي ... واتخذ عندي إلى الحشريدا)\n(إنما ردفك سرج مذهب ... كشف البزيون عنه فبدا)\n(فأعرنيه ولا تبخل به ... ليس يبليه ركوبي أبدا)\n(بل يصفيه ويجلوه ولا ... أثر ترآه فيه أبدا)\n(فادن يا حب وطب نفسا به ... إن ذاك الدين تقضاه غدا)","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":7,"spl":"مدح الرشيد فأجازه — هجا القيان","tags":["أبي العبر"],"song":1,"loc":3911},
{"id":"b299-17","bab":"الجزء 23","sec":"هجا القيان","page":"ج23 ص229","text":"أخبرني إسماعيل بن يونس قال حدثني عمر بن شبة عن أحمد بن صالح الهاشمي قال هجا يوسف بن الصيقل القيان فقال\n(احذر فديتك ما حييت ... حبائل المتشاكلات)\n(فلهن يفلسن الفتى ... وكفى بهن مفلسات)\n(ويل امريء غر تجيه ... رقاعهن مختمات)\n(ورقاعهن إليهم ... برقى القحاب مسطرات)\n(وعلى القيادة رسلهن ... إذا بعثن مدربات)\n(يهدمن أكياس الغني ... من المؤونة والهبات)\n(حفر العلوج سواقيا ... للماء في الأرض الموات)\n(فيصير من إفلاسه ... ومن الندامة في سبات)\nال وشاعت هذه الأبيات وتهاداها الناس وصارت عبثا بالقيان لكل أحد فكانت المغنية إذا عثرت قالت تعس يوسف","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":7,"spl":"مدح الرشيد فأجازه — هجا القيان","tags":["أبي العبر","الهجاء"],"loc":3912},
{"id":"b299-18","bab":"الجزء 23","sec":"الرشيد يختاره للجائزة والموالي يزكونه","page":"ج23 ص230","text":"أخبرني الحسن بن علي قال أخبرني عيسى بن الحسن الآدمي قال حدثني أحمد بن أبي فنن قال أحضر الرشيد عشرة آلاف دينار من ضرب السنة ففرقها حتى بقيت منها ثلاثة آلاف دينار فقال ائتوني شاعرا أهبها له فوجدوا منصورا النمري ببابه فأدخل إليه فأنشده وكان قبيح الإنشاد فقال له الرشيد أعانك الله على نفسك انصرف فقال يا أمير المؤمنين قد دخلت إليك دخلتين لم تعطني فيهما شيئا وهذه الثالثة ووالله لئن حرمتني لا رفعت رأسي بين الشعراء أبدا فضحك الرشيد\nوقال خذها فأخذها ونظر الرشيد إلى الموالي ينظر بعضهم بعضا فقال كأني قد عرفت ما أردتم إنما أردتم أن تكون هذه الدنانير ليوسف بن الصيقل وكان يوسف منقطعا إلى الموالي ينادمهم ويمدحهم فكانوا يتعصبون له فقالوا إي والله يا أمير المؤمنين فقال هاتوا ثلاثة آلاف دينار فأحضرت فأقبل على يوسف فقال هات أنشدنا فأنشده يوسف\n(تصدت له يوم الرصافة زينب ... )\nقال له كأنك امتدحتنا فيها فقال أجل والله يا أمير المؤمنين فقال أنت ممن يوثق بنيته ولا تتهم موالاته هات من ملحك ودع المديح فأنشده قوله\n(العفو يا غضبان ... ما هكذا الخلان)\n(هبني أبتليت بذنب ... أما له غفران)\n(وإن تعاظم ذنب ... ففوقه الهجران)\n(كم قد تقربت جهدي ... لو ينفع القربان)\n(يا رب أنت على ما ... قد حل بي المستعان)\n(ويلي ألست تراني ... أهذي بها يا فلان)\nقال الرشيد ومن فلان هذا ويلك فقال له الفضل بن الربيع هو أبان مولاك يا أمير المؤمنين فقال له الرشيد ولم لم تنشدني كما قلت يا نبطي فقال لأني غضبان عليه\nقال وما أغضبك قال مدت دجلة فهدمت داري وداره فبنى داره وعلاها حتى سترت الهواء عني قال لا جرم ليعطينك الماص بظر أمه عشرة آلاف درهم حتى تبني بناء يعلو على بنائه فتستر أنت الهواء عنه ثم\nقال له خذ في شعرك فأنشده نحوا من هذا الشعر فقال للفضل بن الربيع يا عباس ليس هذا بشعر ما هو إلا لعب أعطوه ثلاثة آلاف درهم مكان الثلاثة آلآلاف الدينار فانصرف الموالي إلى صالح الخازن فقالوا له أعطه ثلاثة آلاف دينار كما أمر له أولا فقال أستأمره ثم أفعل فقالوا له أعطه إياها بضماننا فإن أمضيت له وإلا كانت في أموالنا فدفعها إليه بضمانهم فأمضيت له فكان يوسف يقول بعد ذلك كنا نلعت فنأخذ مثل هذه الأموال وأنتم تقتلون أنفسكم فلا تأخذون شيئا\n(هبت قبيل تبلج الفجر ... هند تقول ودمعها يجري)\n(أنى اعتراك وكنت في عهدي لا ... سرب الدموع وكنت ذا صبر)\nالشعر لرجل من الشراه يقال له عمرو بن الحسن مولى بني تميم يقوله في عبد الله بن يحيى الذي تسميه الخوارج طالب الحق ومن قتل من أصحابه معه يرثيهم والغناء لعبد الله بن أبي العلاء ثاني ثقيل بإطلاق الوتر في مجرى الوسطى عن الهشامي","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":8,"spl":"الرشيد يختاره للجائزة والموالي يزكونه — خبر عبد الله بن يحيى وخروجه ومقتله","tags":["أبي العبر"],"song":2,"loc":3913,"partial":1},
{"id":"b299-19","bab":"الجزء 23","sec":"خبر عبد الله بن يحيى وخروجه ومقتله","page":"ج23 ص232","text":"أخبرني بذلك الحسن بن علي الخفاف قال حدثنا أحمد بن الحارث الخراز عن المدائني عن محمد بن أبي محمد الخزامي وخلاد بن يزيد وعبد الله بن مصعب وعمرو بن هشام وعبد الله بن محمد الثقفي ويعقوب بن داود الثقفي وحريم بن أبي يحيى","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":8,"spl":"الرشيد يختاره للجائزة والموالي يزكونه — خبر عبد الله بن يحيى وخروجه ومقتله","tags":["أبي العبر","الرواية والكتابة"],"loc":3914},
{"id":"b299-21","bab":"الجزء 23","sec":"كان مجتهدا عابدا — رحيله من حضرموت إلى صنعاء","page":"ج23 ص233 – ج23 ص234","text":"أن عبد الله بن يحيى الكندي أحد بني عمرو بن معاوية كان من حضرموت وكان مجتهدا عابدا وكان يقول قبل أن يخرج لقيني رجل فأطال النظر إلي\nوقال ممن أنت فقلت من كندة فقال من أيهم فقلت من بني شيطان قال والله لتملكن ولتبلغن خيلك وادي القرى وذلك بعد أن تذهب إحدى عينيك فذهبت أتخوف ما\nقال وأستخير الله فرأيت باليمن جورا ظاهرا وعسفا شديدا وسيرة في الناس قبيحة فقال لأصحابه ما يحل لنا المقام على ما نرى ولا يسعنا الصبر عليه وكتب إلى عبيدة بن مسلم بن أبي كريمة الذي يقال له كودين مولى بني تميم وكان ينزل في الأزد وإلى غيره من\nالإباضية بالبصرة يشاورهم في الخروج فكتبوا إليه إن استطعت ألا تقيم يوما واحدا فافعل فإن المبادرة بالعمل الصالح أفضل ولست تدري متى يأتي عليك أجلك ولله خيرة من عباده يبعثهم إذا شاء لنصرة دينه ويخص بالشهادة منهم من يشاء وشخص إليه أبو حمزة المختار بن عوف الأزدي أحد بني سلمة وبلج بن عقبة السقوري في رجال من الإباضية فقدموا عليه حضر موت فحثوه على الخروج وأتوه بكتب أصحابه إذا خرجتم فلا تغلوا ولا تغدروا واقتدوا بسلفكم الصالحين وسيروا سيرتهم فقد علمتم أن الذي أخرجهم على السلطان العيث لأعمالهم فدعا أصحابه فبايعوه فقصدوا دار الإمارة وعلى حضرموت إبراهيم بن جبلة بن مخرمة الكندي فأخذوه فحبسوه يوما ثم أطلقوه فأتى صنعاء وأقام عبد الله بن يحيى بحضر موت وكثر جمعه وسموه طالب الحق\nفكتب إلى من كان من أصحابه بصنعاء إني قادم عليكم ثم استخلف على حضر موت عبد الله بن سعيد الحضرمي وتوجه إلى صنعاء سنة تسع وعشرين ومائة في ألفين وبلغ القاسم بن عمر أخا يوسف بن عمر وهو عامل مروان بن محمد على صنعاء مسير عبد الله بن يحيى فاستخلف على\nصنعاء الضحاك بن زمل وخرج يريد الإباضية في سلاح ظاهر وعدة وجمع كثير فعسكر على مسيرة يوم من أبين وخلف فيها الأثقال وتقدمت المقاتلة فلقيه عبد الله بن يحيى بلحج قرية من أبين قريبا من الليل فقال الناس للقاسم أيها الأمير لا تقاتل الخوارج ليلا فأبى وقاتلهم فقتلوا من أصحابه بشرا كثيرا وانهزموا ليلا فمر بعسكره فأمرهم بالرحيل ومضى إلى صنعاء فأقام يوما ثم خرج فعسكر قريبا من صنعاء وخندق وخلف بصنعاء الضحاك بن زمل فأقبل عبد الله بن يحيى فنزل جونين على ميلين من عسكر القاسم فوجه القاسم يزيد بن الفيض في ثلاثة آلاف من أهل الشام وأهل اليمن فكانت بينهم مناوشة ثم تحاجزوا فرجع يزيد إلى القاسم فاستأذنه في بياتهم فأبى أن يأذن له فقال يزيد والله لئن لم تبيتهم ليغمنك فأبى أن يأذن له وأقاموا يومين لا يلتقون فلما كان في الليلة الثالثة أقبل عبد الله بن يحيى فوافاه مع طلوع الفجر فقاتلهم الناس على الخندق فغلبتهم الخوارج عليه ودخلوا عسكرهم والقاسم يصلي فركب وقاتلهم الصلت بن يوسف فقتل في المعركة وقام بأمر الناس يزيد بن الفيض فقاتلهم حتى ارتفع النهار ثم انهزم أهل صنعاء فأراد أبرهة بن الصباح اتباعهم فمنعه عبد\nالله بن يحيى واتبع يزيد بن الفيض القاسم بن عمر فأخبره الخبر فقال القاسم\n(ألا ليت شعري هل أذودن بالقنا ... وبالهندوانيات قبل مماتي)\n(وهل أصبحن الحارثين كليهما ... بطعن وضرب يقطع اللهوات)\nقال ودخل عبد الله بن يحيى صنعاء فأخذ الضحاك بن زمل وإبراهيم بن جبلة بن مخرمة فحبسهما وجمع الخزائن والأموال فأحرزها ثم أرسل إلى الضحاك وإبراهيم فأرسلهما وقال لهما حبستكما خوفا عليكما من العامة وليس عليكما مكروه فأقيما إن شئتما أو اشخصا فخرجا","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":9,"spl":"كان مجتهدا عابدا — رحيله من حضرموت إلى صنعاء","tags":["أبي العبر"],"loc":3915},
{"id":"b299-22","bab":"الجزء 23","sec":"خطبته بعد فتح اليمن","page":"ج23 ص236","text":"فلما استولى عبد الله بن يحيى على بلاد اليمن خطب الناس فحمد الله جل وعز وأثنى عليه وصلى على نبيه ووعظ وذكر وحذر ثم قال إنا ندعوكم إلى كتاب الله تعالى وسنة نبيه وإجابة من دعا إليهما الإسلام ديننا ومحمد نبينا والكعبة قبلتنا والقرآن إمامنا رضينا بالحلال حلالا لا نبغي به بديلا ولا نشتري به ثمنا قليلا وحرمنا الحرام ونبذناه وراء ظهورنا ولا حول ولا قوة إلا بالله وإلى الله المشتكى وعليه المعول من زنى فهو كافر ومن سرق فهو كافر ومن شرب الخمر فهو كافر ومن شك في أنه كافر فهو كافر ندعوكم إلى فرائض بينات وآيات محكمات وآثار\nمقتدى بها ونشهد أن الله صادق فيما وعد عدل فيما حكم وندعو إلى توحيد الرب واليقين بالوعيد والوعد وأداء الفرائض والأمر بالمعروف والنهي عن المنكر والولاية لأهل ولاية الله والعداوة لأعداء الله أيها الناس إن من رحمة الله أن جعل في كل فترة بقايا من أهل العلم يدعون من ضل إلى الهدى ويصبرون على الألم في جنب الله تعالى يقتلون على الحق في سالف الدهور شهداء فما نسيهم ربهم وما كان ربك نسيا أوصيكم بتقوى الله وحسن القيام على ما وكلكم الله بالقيام به فأبلوا لله بلاء حسنا في أمره وزجره أقول قولي هذا وأستغفر الله لي ولكم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":10,"spl":"خطبته بعد فتح اليمن","tags":["أبي العبر","المديح"],"loc":3916},
{"id":"b299-23","bab":"الجزء 23","sec":"وجه أصحابه إلى مكة","page":"ج23 ص237","text":"قالوا وأقام عبد الله بن يحيى بصنعاء أشهرا يحسن السيرة فيهم ويلين جانبه لهم ويكف عن الناس فكثر جمعه وأتته الشراة من كل جانب فلما كان وقت الحج وجه أبا حمزة المختار بن عوف وبلج بن عقبة وأبرهة بن الصباح إلى مكة في تسعمائة\nوقيل بل في ألف ومائة وأمره أن يقيم بمكة إذا صدر الناس ويوجه بلجا إلى الشأم وأقبل المختار إلى مكة فقدمها يوم التروية وعليها عبد الواحد بن سليمان بن عبد الملك وأمه بنت عبد الله بن خالد بن أسيد فكره قتالهم\nوحدثنا من هذا الموضع بخبر أبي حمزة محمد بن جرير الطبري قال حدثنا العباس بن عيسى العقيلي قال حدثنا هارون بن موسى العواري قال حدثنا موسى بن كثير مولى الساعديين قال\nكان أول أمر أبي حمزة وهو المختار بن عوف الأزدي ثم السلمي من أهل البصرة أنه كان يوافي في كل سنة يدعو إلى خلاف مروان بن محمد وآل مروان فلم يزل يختلف كل سنة حتى وافى عبد الله بن يحيى في آخر سنة وذلك سنة ثمان وعشرين ومائة فقال له يا رجل إني أسمع كلاما حسنا وأراك تدعو إلى حق فانطلق معي فإني رجل مطاع في قومي فخرج به حتى ورد حضرموت فبايعه أبو حمزة على الخلافة\nقال وقد كان مر أبو حمزة بمعدن بني سليم وكثير بن عبد الله عامل على المعدن فسمع بعض كلامه فأمر به فجلد أربعين سوطا فلما ظهر أبو حمزة بمكة تغيب كثير حتى كان من أمره ما كان ثم رجع إلى موضعه\nقال فلما كان في العام المقبل تمام سنة تسع وعشرين لم يعلم الناس بعرفة إلا وقد طلعت أعلام عمائم سود خرمية في رؤوس الرماح وهم سبعمائة هكذا\nقال هذا وذكر المدائني أنهم كانوا تسعمائة أو ألفا ومائة ففزع الناس منهم حين رأوهم وقالوا لهم ما لكم وما حالكم فأخبروهم بخلافهم مروان وآل مروان والتبري منهم فراسهلم عبد الواحد بن سليمان وهو يومئذ على المدينة ومكة والموسم ودعاهم إلى الهدنة فقالوا نحن بحجنا أضن وعليه أشح فصالحهم على أنهم جميعا آمنون بعضهم من بعض حتى ينفر الناس النفر الأخير وأصبحوا من غد فوقفوا على حدة بعرفة ودفع عبد الواحد بالناس فلما كانوا بمنى قالوا لعبد الواحد إنك قد أخطأت فيهم ولو حملت عليهم الحاج ما كانوا إلا أكلة رأس فنزل أبو حمزة بقرن الثعالب\nمن منى ونزل عبد الواحد منزل السلطان فبعث عبد الواحد إلى أبي حمزة عبد الله بن حسن بن حسن بن علي عليهم السلام ومحمد بن عبد الله بن عمرو بن عثمان وعبد الرحمن بن القاسم بن محمد بن أبي بكر وعبيد الله بن عمرو بن حفص العمري وربيعة بن عبد الرحمن في رجال من أمثالهم فلما دنوا من قرن الثعالب لقيتهم مسالح أبي حمزة فأخذوهم فدخل بهم على أبي حمزة فوجدوه جالسا وعليه إزار قطراني قد ربطه الحورة في قفاه فلما دنوا تقدم إليه عبد الله بن حسن ومحمد بن عبد الله بن عمرو فنسبهما فلما انتسبا له عبس في وجهيهما وبسر وأظهر الكراهة لهما ثم تقدم إليه بعدهما البكري والعمري فنسبهما فلما انتسبا له هش إليهما وتبسم في وجوههما\nوقال والله ما خرجنا إلا لنسير بسيرة أبويكما فقال له عبد الله بن حسن بن حسن والله ما جئناك لتفاضل بين آبائنا ولكن بعثنا إليك الأمير برسالة وهذا ربيعة يخبركها فلما\nذكر ربيعة نقض العهد قال بلج وإبراهيم وكانا قائدين له الساعة الساعة فأقبل عليهما أبو حمزة وقال معاذ الله أن ننقض العهد أو نخيس به والله لا أفعل ولو قطعت رقبتي هذه ولكن تنقضى هذه الهدنة بيننا وبينكم فلما أبى عليهم خرجوا فابلغوا عبد الواحد","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":11,"spl":"وجه أصحابه إلى مكة","tags":["أبي العبر","الجواري والنساء"],"loc":3917},
{"id":"b299-24","bab":"الجزء 23","sec":"هجو عبد الواحد","page":"ج23 ص239","text":"فلما كان النفر الأول نفر عبد الواحد وخلى مكة لأبي حمزة فدخلها بغير قتال\nقال هارون وأنشدني يعقوب بن طلحة الليثي أبياتا هجي بها عبد الواحد لشاعر لم نحفل به\n(زار الحجيج عصابة قد خالفوا ... دين الإله ففر عبد الواحد)\n(ترك الإمارة والحلائل هاربا ... ومضى يخبط كالبعير الشارد)\n(لو كان والده تخير أمه ... لصفت خلائقه بعرق الوالد)\n(ترك القتال وما به من علة ... إلا الوهون وعرفة من خالد)\nم مضى عبد الواحد حتى دخل المدينة فدعا بالديوان وضرب على الناس البعث وزادهم في العطاء عشرة عشرة قال هارون أخبرني بذلك أبو ضمرة أنس بن عياض أنه كان فيمن اكتتب\nقال ثم محوت أسمي قال هارون وحدثني غير واحد من أصحابنا أن عبد الواحد استعمل عبد العزيز بن عبد الله بن عمرو بن عثمان على الناس فخرجوا فلما كانوا بالحرة لقيتهم جزر منحورة فمضوا فلما كانوا بالعقيق تعلق لواؤهم بسمرة فانكسر الرمح وتشاءم الناس بالخروج ثم ساروا حتى نزلوا قديدا فنزلوها ليلا وكانت قرية قديد من ناحية القصر والمنبر اليوم وكانت الحياض هناك فنزل قوم مغترون ليسوا بأصحاب حرب فلم يرعهم\nإلا القوم قد خرجوا عليهم من الفصل فزعم بعض الناس أن خزاعة دلت أبا حمزة على عورتهم وأدخلوهم عليهم فقتلوهم وكانت المقتلة على قريش وهم كانوا أكثر الناس وفيهم كانت الشوكة فأصيب منهم عدد كثير","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":12,"spl":"هجو عبد الواحد — اليمانيون يشمتون بقريش","tags":["أبي العبر"],"loc":3918},
{"id":"b299-25","bab":"الجزء 23","sec":"اليمانيون يشمتون بقريش","page":"ج23 ص241","text":"قال العباس قال هارون فأخبرني بعض أصحابنا أن رجلا من قريش نظر إلى رجل من أهل اليمن يقول الحمد لله الذي أقر عيني بمقتل قريش فقال له ابنه الحمد لله الذي أذلهم بأيدينا فما كانت قريش تظن أن من نزل على عمان من الأزد عربي\nقال وكان هذان الرجلان مع أهل المدينة فقال القرشي لإبنه يا بني هلم نبدأ بهذين الرجلين قال نعم يا أبت فحملا عليهما فقتلاهما ثم قال لإبنه أي بني تقدم فقاتلا حتى قتلا\nوقال المدائني القرشي كان عمارة بن حمزة بن مصعب بن الزبير والمتكلم بالكلام مع ابنه رجل من الأنصار قال ثم ورد فلال الجيش المدينة وبكى الناس قتلاهم فكانت المرأة تقيم على حميمها النواح فلا تزال المرأة يأتيها الخبر بمقتل حميمها فتنصرف حتى ما يبقى عندها امرأة فأنشدني أبو حمزة هذه الأبيات في قتلى قديد الذين أصيبوا من قومه لبعض أصحابه\n(يالهف نفسي ولهف غير نافعة ... على فوارس بالبطحاء أنجاد)\n(عمرو وعمرو وعبد الله بينهما ... وابناهما خامس والحارث السادي)","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":12,"spl":"هجو عبد الواحد — اليمانيون يشمتون بقريش","tags":["أبي العبر"],"loc":3919},
{"id":"b299-26","bab":"الجزء 23","sec":"مروان يأمر عامله بتوجيه الجيش إلى مكة","page":"ج23 ص242","text":"قال المدائني في خبره كتب عبد الواحد بن سليمان إلى مروان يعتذر من إخراجه عن مكة فكتب مروان إلى عبد العزيز بن عمر بن عبد العزيز وهو عامله على المدينة يأمره بتوجيه الجيش إلى مكة فوجه ثمانية آلاف رجل من قريش والأنصار والتجار أغمار لاعلم لهم بالحرب فخرجوا في الصبغات والثياب الناعمة واللهو لا يظنون أن للخوارج شوكة ولا يشكون أنهم في أيديهم\nوقال رجل من قريش لو شاء أهل الطائف لكفونا أمر هؤلاء ولكنهم داهنوا في أمر الله تعالى والله إن ظفرنا لنسيرن إلى أهل الطائف فلنسبينهم ثم\nقال من يشتري مني سبي أهل الطائف فلما انهزم الناس رجع ذلك الرجل القائل من يشتري مني سبي أهل الطائف في أول المنهزمين فدخل منزله وأراد أن يقول لجاريته أغلقي الباب فقال لها غاق باق دهشا ولم تفهم الجارية قوله حتى أومأ إليها بيده فأغلقت الباب فلقبه أهل المدينة بعد ذلك غاق باق\nقال وكان عبد العزيز بن عمر بن عبد العزيز يعرض الجيش بذي الحليفة فمر به أمية بن عنبسة بن سعيد بن العاص فرحب به وضحك إليه ومر به عمارة بن حمزة بن مصعب بن الزبير فلم يكلمه ولم يلتفت إليه فقال له عمران بن عبد الله بن مطيع وكان ابن خالته أماهما ابنتا عبد الله بن خالد بن أسيد سبحان الله مر بك شيخ من شيوخ قريش فلم تنظر إليه ولم تكلمه ومر بك غلام من بني أمية فضحكت إليه ولاطفته\nأما والله لو قد التقى الجمعان لعلمت أيهما أصبر قال فكان أمية بن عنبسة أول من انهزم ونكب فرسه ومضى وقال لغلامه يا مجيب أما والله لئن أحزرت نفسي هذه الأكلب من الشراة إني لعاجز وقاتل يومئذ عمارة بن حمزة ابن مصعب حتى قتل وتمثل\n(وإني إذا ضن الأمير بإذنه ... على الاذن من نفسي إذا شئت قادر)\nالشعر للأغر بن حماد اليشكري قال ولما بلغ أبا حمزة إقبال أهل المدينة إليه استخلف على مكة إبراهيم بن الصباح وشخص إليهم وعلى مقدمته بلج بن عقبة فلما كان في الليلة التي وافاهم في صبيحتها وأهل المدينة نزول بقديد\nقال لأصحابه إنكم لاقو قومكم غدا وأميرهم فيما بلغني ابن عثمان أول من خالف سيرة الخلفاء وبدل سنة رسول الله وقد وضح الصبح لذي عينين فأكثروا\nذكر الله تعالى وتلاوة القرآن ووطنوا أنفسكم على الصبر وصبحهم غداة الخميس لتسع أو لسبع خلون من صفر سنة ثلاثين ومائة فقال عبد العزيز لغلامه أبغنا علفا قال هو غال قال ويحك البواكي علينا غدا أغلى","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":13,"spl":"مروان يأمر عامله بتوجيه الجيش إلى مكة","tags":["أبي العبر"],"loc":3920},
{"id":"b299-27","bab":"الجزء 23","sec":"رسول أبي حمزة إلى أهل المدينة","page":"ج23 ص243","text":"وأرسل إليهم أبو حمزة بلج بن عقبة ليدعوهم فأتاهم في ثلاثين راكبا فذكرهم الله وسألهم أن يكفوا عنهم وقال لهم خلوا لنا سبيلنا لنسير إلى من ظلمكم وجار في الحكم عليكم ولا تجعلوا حدنا بكم فإنا لا نريد قتالكم فشتمهم أهل المدينة وقالوا يا أعداء الله أنحن نخليكم وندعكم تفسدون في الأرض فقالت الخوارج يا أعداء الله أنحن نفسد في الأرض إنما خرجنا لنكف أهل الفساد ونقاتل من قاتلنا واستأثر بالفيء\nفانظروا لأنفسكم واخلعوا من لم يجعل الله له طاعة فإنه لا طاعة لمن عصى الله وادخلوا في السلم وعاونوا أهل الحق فقال له عبد العزيز ما تقول في عثمان\nقال قد برئ المسلمون منه قبلي وأنا متبع آثارهم ومقتد بهم قال فارجع إلى أصحابك فليس بيننا وبينهم إلا السيف فرجع إلى أبي حمزة فأخبره فقال كفوا عنهم ولا تقاتلوهم حتى يبدأوكم بالقتال فواقفوهم ولم يقاتلوهم فرمى رجل من أهل المدينة في عسكر أبي حمزة بسهم فجرح رجلا فقال أبو حمزة شأنكم الآن بهم فقد حل قتالهم فحملوا عليهم وثبت بعضهم لبعض وراية قريش مع إبراهيم بن عبد الله بن مطيع ثم انكشف أهل المدينة فلم يتبعوهم وكان على مجنبتهم ضمير بن صخر بن أبي الجهم بن حذيفة فكر وكر الناس معه فقاتلوا قليلا ثم انهزموا فلم يبعدوا حتى كروا ثالثة وقاتلهم أبو حمزة فهزمهم هزيمة لم تبق منهم باقية فقال له علي بن الحصين أتبع القوم أو دعني أتبعهم فأقتل المدبر واذفف على الجريح فإن هؤلاء أشر علينا من أهل الشأم فلو قد جاؤوك غدا لرأيت من هؤلاء ما تكره فقال لا أفعل ولا أخالف سيرة أسلافنا وأخذ جماعة منهم أسراء فأراد إطلاقهم فمنعه علي بن الحصين\nوقال له إن لأهل كل زمان سيرة وهؤلاء لم يؤسروا وهم هراب وإنما أسروا وهم يقاتلون ولو قتلوا في ذلك الوقت لم يحرم قتلهم وكذلك الآن قتلهم حلال فدعا بهم فكان إذا رأى رجلا من قريش قتله وإذا رأى رجلا من الأنصار أطلقه فأتي بمحمد بن عبد الله بن عمرو بن عثمان فنسبه فقال أنا رجل من الأنصار فسأل الأنصار عنه فشهدوا له\nفأطلقه فلما ولى قال والله لأعلم أنه قرشي وما حذاوة هذا حذاوة أنصاري ولكن قد أطلقته قال وبلغت قتلى قديد ألفين ومائتين وثلاثين رجلا منهم من قريش أربعمائة وخمسون رجلا ومن الأنصار ثمانون ومن القبائل والموالي ألف وسبعمائة\nقال وكان في قتلى قريش من بني أسد بن عبد العزى أربعون رجلا وقتل يومئذ أمية بن عبد الله بن عمرو بن عثمان خرج يومئذ مقنعا فما كلم أحدا وقاتل حتى قتل وقتل يومئذ سمي مولى أبي بكر الذي يروي عنه مالك بن أنس ودخل بلج المدينة بغير حرب فدخلوا في طاعته وكف عنهم ورجع أبو حمزة إلى مكة وكان على شرطته أبو بكر بن عبد الله بن عمرو من آل سراقة من بني عدي فكان أهل المدينة يقولون لعن الله السراقي ولعن بلجا العراقي","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":14,"spl":"رسول أبي حمزة إلى أهل المدينة","tags":["أبي العبر","السفر والحج"],"loc":3921},
{"id":"b299-28","bab":"الجزء 23","sec":"نائحة المدينة تبكي قتلى قديد وعمر بن الحسن يذكر الوقعة","page":"ج23 ص245","text":"وقالت نائحة أهل المدينة تبكيهم\n(ما للزمان وماليه ... أفنت قديد رجاليه)\n(فلأبكين سريرة ... ولأبكين علانيه)\n(ولأبكين إذا خلوت ... مع الكلاب العاويه)\n(ولأثنين على قديد ... بسوء ما أبلانيه)\nفي هذه الأبيات هزج قديم يشبه أن يكون لطويس أو بعض طبقته وقال عمرو بن الحسن الكوفي مولى بني تميم يذكر وقعة قديد وأمر مكة ودخولهم إياها وأنشدنيها الأخفش عن السكري والأحول وثعلب لعمرو هذا وكان يستجيدها ويفضلها\n(ما بال همك ليس عنك بعازب ... يمري سوابق دمعك المتساكب)\n(وتبيت تكتليء النجوم بمقلة ... عبرى تسر بكل نجم دائب)\n(حذر المنية أن تجيء بداهة ... لم أقض من تبع الشراة مآربي)\n(فأقود فيهم للعدا شنج النسا ... عبل الشوى أسوان ضمر الحالب)\n(متحدرا كالسيد أخلص لونه ... ماء الحسيك مع الحلال اللاتب)\n(أرمي به من جمع قومي معشرا ... بورا إلى جبرية ومعايب)\n(في فتية صبر ألفهم به ... لف القداح يد المفيض الضارب)\n(فندور نحن وهم وفيما بيننا ... كأس المنون تقول هل من شارب)\n(فنظل نسقيهم ونشرب من قنا ... سمر ومرهفة النصول قواضب)\n(بينا كذلك نحن جالت طعنة ... نجلاء بين رها وبين ترائب)\n(جوفاء منهرة ترى تامورها ... ظبتا سنان كالشهاب الثاقب)\n(اهوى لها شق الشمال كأنني ... حفض لقى تحت العجاج العاصب)\n(يا رب أوحيها ولا تتعلقن ... نفسي المنون لدى أكف قرائب)\n(كم من أولي مقة صحبتهم شروا ... فخذلتهم ولبئس فعل الصاحب)\n(متأوهين كأن في أجوافهم ... نارا تسعرها أكف حواطب)\n(تلقاهم فتراهم من راكع ... أو ساجد متضرع أو ناحب)\n(يتلو قوارع تمتري عبراته ... فيجودها مري امري الحالب)\n(سير لجائفة الأمور أطبة ... للصدع ذي النبأ الجليل مدائب)\n(ومبرئين من المعايب أحرزوا ... خصل المكارم أتقياء أطايب)\n(عروا صوارم للجلاد وباشروا ... حد الظباة بآنف وحواجب)\n(ناطوا أمورهم بأمر أخ لهم ... فرمى بهم قحم الطريق اللاحب)\n(متسربلي حلق الحديد كأنهم ... أسد على لحق البطون سلاهب)\n(قيدت من أعلى حضر موت فلم تزل ... تنفي عداها جانبا عن جانب)\n(تحمي أعنتها وتحوي نهبها ... لله أكرم فتية وأسائب)\n(حتى وردن حياض مكة قطنا ... يحكين واردة اليمام القارب)\n(ما إن أتين على أخي حبرية ... إلا تركنهم كأمس الذاهب)\n(في كل معترك لها من هامهم ... فلق وأيد علقت بمناكب)\n(سائل بيوم قديد عن وقعاتها ... تخبرك عن وقعاتها بعجائب)\nقال هارون بن موسى في رواية محمد بن جرير الطبري عن العباس بن عيسى عنه ثم دخل أبو حمزة المدينة سنة ثلاثين ومائة ومضى عبد الواحد بن سليمان إلى الشأم فرقي المنبر فحمد الله وأثنى عليه\nوقال يا أهل المدينة سألناكم عن ولاتكم هؤلاء فأسأتم لعمر الله فيهم القول وسألناكم هل يقتلون بالظن فقلتم نعم وسألناكم هل يستحلون المال الحرام والفرج الحرام فقلتم نعم فقلنا لكم تعالوا نحن وأنتم فنناشدهم الله أن يتنحوا عنا وعنكم ليختار المسلمون لأنفسهم فقتلتم لا تفعلون فقلنا لكم تعالوا نحن وأنتم نلقاهم فإن نظهر نحن وأنتم نأت بمن يقيم فينا كتاب الله وسنة نبيه وإن نظفر نعمل في أحكامكم ونحملكم على سنة نبيكم ونقسم فيئكم بينكم فإن أبيتم وقاتلتمونا دونهم فقاتلناكم فأبعدكم الله وأسحقكم يا أهل المدينة مررت بكم في زمان الأحول هشام بن عبد الملك وقد أصابتكم عاهة في ثماركم فركبتم إليه تسألونه أن يضع خراجكم عنكم فكتب بوضعها عنكم فزاد الغني غنى وزاد الفقير فقرا فقلتم جزاكم الله خيرا فلا جزاه الله خيرا ولا جزاكم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":15,"spl":"نائحة المدينة تبكي قتلى قديد وعمر بن الحسن يذكر الوقعة","tags":["أبي العبر"],"loc":3922},
{"id":"b299-29","bab":"الجزء 23","sec":"أبو حمزة يخطب بأهل المدينة","page":"ج23 ص248","text":"قال هارون وأخبرني يحيى بن زكريا أن أبا حمزة خطب بهذه الخطبة\nرقي المنبر فحمد الله وأثنى عليه وقال أتعلمون يا أهل المدينة أنا لم نخرج من ديارنا وأموالنا أشرا ولا بطرا ولا عبثا ولا لهوا ولا لدولة ملك نريد أن نخوض فيه ولا ثأر قديم نيل منا ولكنا لما رأينا مصابيح الحق قد عطلت وعنف القاتل بالحق وقتل القائم بالقسط ضاقت علينا الأرض بما رحبت وسمعنا داعيا يدعو إلى طاعة الرحمن وحكم القرآن فأجبنا داعي الله ( ومن لا يجب داعي الله فليس بمعجز في الأرض\nفأقبلنا من قبائل شتى النفر منا على بعير واحد عليه زادهم وأنفسهم يتعاورون لحافا واحدا قليلون مستضعفون في الأرض فآوانا الله وأيدنا بنصره وأصبحنا والله بنعمته إخوانا ثم لقينا رجالكم بقديد فدعوناهم إلى طاعة الرحمن وحكم القرآن ودعونا إلى طاعة الشيطان وحكم مروان وآل مروان شتان لعمر الله ما بين الغي والرشد ثم أقبلوا يهرعون ويزفون قد ضرب الشيطان فيهم بجرانه وغلت بدمائهم مراجله وصدق عليهم ظنه وأقبل أنصار الله عصائب وكتائب بكل مهند ذي رونق فدارت رحانا واستدارت رحاهم بضرب يرتاب منه المبطلون وأنتم يا أهل المدينة إن تنصروا مروان وآل مروان يسحتكم الله بعذاب من عنده أو بأيدينا ويشف صدور قوم مؤمنين يا أهل المدينة إن أولكم خير أول وآخركم شر آخر يا أهل المدينة الناس منا ونحن منهم إلا مشركا عابد وثن أو كافرا من أهل الكتاب أما إماما جائرا يا أهل المدينة من زعم أن الله تعالى كلف نفسا فوق طاقتها أو سألها عما لم يؤتها فهو لله عدو ولنا حرب يا أهل المدينة أخبروني عن ثمانية أسهم\nفرضها الله تعالى في كتابه على القوي للضعيف فجاء التاسع وليس له منها ولا سهم واحد فأخذ جميعها لنفسه مكابرا محاربا لربه ما تقولون فيه وفيمن عاونه على فعله يا أهل المدينة بلغني أنكم تنتقصون أصحابي قلتم هم شباب أحداث وأعراب جفاة ويحكم يا أهل المدينة وهل كان أصحاب رسول الله إلا شبابا أحداثا شباب والله مكتهلون في شبابهم غضيضة عن الشر أعينهم ثقيلة عن الباطل أقدامهم قد باعوا أنفسا تموت غدا بأنفس لا تموت أبدا قد خلطوا كلالهم بكلالهم وقيام ليلهم بصيام نهارهم منحنية أصلابهم على أجزاء القرآن كلما مروا بآية خوف شهقوا خوفا من النار وإذا مروا بآية شوق شهقوا شوقا إلى الجنة فلما نظروا إلى السيوف قد أنضيت وإلى الرماح قد أشرعت وإلى السهام قد فوقت وأرعدت الكتيبة بصواعق الموت استخفوا وعيد الكتيبة عند وعيد الله ولم يستخفوا وعيد الله عند وعيد الكتيبة فطوبى لهم وحسن مآب فكم من عين في منقار طائر طالما بكى بها صاحبها من خشية الله وكم من يد قد أبينت عن ساعدها طالما اعتمد عليها صاحبها راكعا وساجدا أقول قولي هذا وأستغفر الله من تقصيرنا وما توفيقي إلا بالله عليه توكلت وإليه أنيب قال هارون وحدثني جدي أبو علقمة قال سمعت أبا حمزة على منبر النبي يقول ( من زنى فهو كافر\nومن سرق فهو كافر ومن شك أنه كافر فهو كافر\n(برح الخفاء فأين ما بك يذهب ... )","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":16,"spl":"أبو حمزة يخطب بأهل المدينة","tags":["أبي العبر","المديح"],"loc":3923,"partial":1},
{"id":"b299-30","bab":"الجزء 23","sec":"أبو حمزة يخطب من جديد بأهل المدينة","page":"ج23 ص251","text":"قال هارون قال جدي كان أبو حمزة قد أحسن السيرة في أهل المدينة حتى استمال الناس وسمع بعضهم كلامه في قوله من زنى فهو كافر قال هارون قال جدي وسمعت أبا حمزة يخطب بالمدينة فحمد الله وأثنى عليه ثم\nقال يا أهل المدينة مالي رأيت رسم الدين فيكم عافيا وآثاره دارسة لا تقبلون عليه عظة ولا تفقهون من أهله حجة قد بليت فيكم جدته وانطمست عنكم سنته ترون معروفه منكرا والمنكر من غيره معروفا إذا انكشفت لكم العبر وأوضحت لكم النذر عميت عنها أبصاركم وصمت عنها أسماعكم ساهين في غمرة لاهين في غفلة تنبسط قلوبكم للباطل إذا نشر وتنقبض عن الحق إذا\nذكر مستوحشة من العلم مستأنسة بالجهل كلما وقعت عليها موعظة زادتها عن الحق نفورا تحملون منها في صدوركم كالحجارة أو أشد قسوة من الحجارة أو لم تبن لكتاب الله الذي لو أنزل على جبل لرأيته خاشعا متصدعا من خشية الله يا أهل المدينة ما تغني عنكم صحة أبدانكم إذا سقمت قلوبكم إن الله قد جعل لكل شيء غالبا يقاد له ويطيع أمره وجعل القلوب غالبة على الأبدان فإذا مالت القلوب ميلا كانت الأبدان لها تبعا وإن القلوب لا تلين لأهلها إلا بصحتها ولا يصححها إلا المعرفة بالله وقوة النية ونفاذ البصيرة ولو استشعرت تقوى الله قلوبكم لأستعملت بطاعة الله أبدانكم يا أهل المدينة داركم دار الهجرة ومثوى رسول الله لما نبت به داره وضاق به قراره وآذاه الأعداء وتجهمت له فنقله إلى قوم لعمري لم يكونوا أمثالكم متوازرين مع الحق على الباطل ومختارين للآجل على العاجل يصبرون\nللضراء رجاء ثوابها فنصروا الله وجاهدوا في سبيله وآووا رسول الله ونصروه واتبعوا النور الذي أنزل معه وآثروا الله على أنفسهم ولو كانت بهم خصاصة قال الله تعلى لهم ولأمثالهم ولمن اهتدى بهداهم ( ومن يوق شح نفسه فأولئك هم المفلحون\nوأنتم أبناؤهم ومن بقي من خلفهم تتركون أن تقتدوا بهم أو تأخذوا بسنتهم عمى القلوب صم الآذان اتبعتم الهوى فأرداكم عن الهدى وأسهاكم فلا مواعظ القرآن تزجركم فتزدجروا ولا تعظكم فتعتبروا ولا توقظكم فتستيقظوا لبئس الخلف أنتم من قوم مضوا قبلكم ما سرتم بسيرتهم ولا حفظتم وصيتهم ولا احتذيتم مثالهم لو شقت عنهم قبورهم فعرضت عليهم أعمالكم فعجبوا كيف صرف العذاب عنكم قال ثم لعن أقواما","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":17,"spl":"أبو حمزة يخطب من جديد بأهل المدينة","tags":["أبي العبر","الحب والغزل","المديح"],"loc":3924},
{"id":"b299-31","bab":"الجزء 23","sec":"خطبة رابعة له","page":"ج23 ص252","text":"قال هارون وحدثني داود بن عبد الله بن أبي الكرام وأخرج إلي خط ابن فضالة النحوي بهذا الخبر أن أبا حمزة بلغه أن أهل المدينة يعيبون أصحابه لحداثة أسنانهم وخفة أحلامهم فبلغه ذلك عنهم فصعد المنبر وعليه كساء غليظ وهو متنكب قوسا عربية فحمد الله وأثنى عليه وصلى على نبيه وآله ثم\nقال يا أهل المدينة قد بلغتني مقالتكم في أصحابي ولولا معرفتي بضعف رأيكم وقلة عقولكم لأحسنت أدبكم ويحكم إن رسول الله أنزل عليه الكتاب وبين له فيه السنن وشرع له فيه الشرائع وبين له فيه ما يأتي وما يذر فلم يكن يتقدم إلا بأمر الله ولا يحجم إلا عن أمر الله حتى قبضه الله\nإليه وقد أدى الذي عليه لم يدعكم من أمركم في شبهة ثم قام من بعده أبو بكر فأخذ بسنته وقاتل أهل الردة وشمر في أمر الله حتى قبضه الله إليه والأمة عنه راضون رحمة الله عليه ومغفرته ثم ولي بعده عمر فأخذ بسنة صاحبيه وجند الأجناد ومصر الأمصار وجبى الفيء فقسمه بين أهله وشمر عن ساقه وحسر عن ذراعه وضرب في الخمر ثمانين وقام في شهر رمضان وغزا العدو في بلادهم وفتح المدائن والحصون حتى قبضه الله إليه والأمة عنه راضون رحمة الله عليه ورضوانه ومغفرته ثم ولي من بعده عثمان بن عفان فعمل في ست سنين بسنة صاحبيه ثم أحدث أحداثا أبطل آخر منها أولا واضطرب حبل الدين بعدها فطلبها كل امرئ لنفسه وأسر كل رجل منهم سريرة أبداها الله عنه حتى مضوا على ذلك ثم ولي علي بن أبي طالب فلم يبلغ من الحق قصدا ولم يرفع له منارا ومضى ثم ولي معاوية بن أبي سفيان لعين رسول الله وابن لعينه وحلف من الأعراب وبقية من الأحزاب مؤلف طليق فسفك الدم الحرام واتخذ عباد الله خولا ومال الله دولا وبغى دينه عوجا ودغلا وأحل الفرج الحرام وعمل بما يشتهيه حتى مضى لسبيله فعل الله به وفعل ثم ولى بعده ابنه يزيد يزيد الخمور ويزيد الصقور ويزيد الفهود ويزيد الصيود ويزيد القرود فخالف القرآن واتبع الكهان ونادم القرد وعمل بما يشتهيه حتى مضى على ذلك لعنه الله وفعل به وفعل ثم ولي مروان بن الحكم طريد لعين رسول الله وآله وابن لعينه فاسق في بطنه وفرجه فالعنوه والعنوا آباءه ثم تداولها بنو مروان بعده أهل بيت اللعنة طرداء رسول الله وآله وقوم من الطلقاء ليسوا من المهاجرين والأنصار ولا التابعين لهم بإحسان فأكلوا\nمال الله أكلا ولعبوا بدين الله لعبا واتخذوا عباد الله عبيدا يورث ذلك الأكبر منهم الأصغر فيالها أمة ما أضيعها وأضعفها والحمد لله رب العالمين ثم مضوا على ذلك من أعمالهم واستخفافهم بكتاب الله تعالى قد نبذوه وراء ظهورهم لعنهم الله فالعنوهم كما يستحقون وقد ولي منهم عمر بن عبد العزيز فبلغ ولم يكد وعجز عن الذي أظهره حتى مضى لسبيله ولم يذكره بخير ولا شر ثم ولي يزيد بن عبد الملك غلام ضعيف سفيه غير مأمون على شيء من أمور المسلمين لم يبلغ أشده ولم يؤانس رشده وقد قال الله عز و جل ( فإن آنستم منهم رشدا فادفعوا إليهم أموالهم\nفأمر أمة محمد في أحكامها وفروجها ودمائها أعظم من ذلك كله وإن كان ذلك عند الله عظيما مأبون في بطنه وفرجه يشرب الحرام ويأكل الحرام ويلبس الحرام ويلبس بردتين قد حيكتا له وقومتا على أهلهما بألف دينار وأكثر وأقل قد أخذت من غير حلها وصرفت في غير وجهها بعد أن ضربت فيها الأبشار وحلقت فيها الأشعار واستحل ما لم يحل الله لعبد صالح ولا لنبي مرسل ثم يجلس حبابة عن يمينه وسلامة عن شماله تغنيانه بمزامير الشيطان ويشرب\nالخمر الصراح المحرمة نصا بعينها حتى إذا أخذت مأخذها فيه وخالطت روحه ولحمه ودمه وغلبت سورتها على عقله مزق حلتيه ثم التفت إليهما فقال أتأذنان لي أن أطير نعم فطر إلى النار إلى لعنة الله وناره حيث لا يردك الله ثم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":18,"spl":"خطبة رابعة له","tags":["أبي العبر","المديح"],"loc":3925},
{"id":"b299-32","bab":"الجزء 23","sec":"خطبة رابعة له","page":"ج23 ص252","text":"ذكر بني أمية وأعمالهم وسيرهم فقال أصابوا إمرة ضائعة وقوما طغاما جهالا لا يقومون لله بحق ولا يفرقون بين الضلالة والهدى ويرون أن بني أمية أرباب لهم فملكوا الأمر وتسلطوا فيه تسلط ربوبية بطشهم بطش الجبابرة يحكمون بالهوى ويقتلون على الغضب ويأخذون بالظن ويعطلون الحدود بالشفاعات ويؤمنون الخونة ويقصون ذوي الأمانة ويأخذون الصدقة في غير وقتها على غير فرضها ويضعونها في غير موضعها فتلك الفرقة الحاكمة بغير ما أنزل الله فالعنوهم لعنهم الله وأما إخواننا من هذه الشيعة فليسوا بإخواننا في الدين لكن سمعت الله عز و جل قال في كتابه ( يا أيها الناس إنا خلقناكم من ذكر وأنثى وجعلناكم شعوبا وقبائل لتعارفوا\nشيعة ظاهرت بكتاب الله وأعلنت الفرية على الله لا يرجعون إلى نظر نافذ في القرآن ولا عقل بالغ في الفقه ولا تفتيش عن حقيقة الصواب قد قلدوا أمرهم أهراءهم وجعلوا دينهم عصبية لحزب لزموه وأطاعوه في جميع ما يقوله لهم غيا كان أو رشدا أو ضلالة أو هدى ينتظرون الدول في رجعة الموتى ويؤمنون بالبعث قبل الساعة ويدعون علم\nالغيب لمخلوق لا يعلم أحدهم ما في داخل بيته بل لا يعلم ما ينطوي عليه ثوبه أو يحويه جسمه ينقمون المعاصي على أهلها ويعلمون إذا ظهروا بها ولا يعرفون المخرج منها جفاة في الدين قليلة عقولهم قد قلدوا أهل بيت من العرب دينهم وزعموا أن موالاتهم لهم تغنيهم عن الأعمال الصالحة وتنجيهم من عقاب الأعمال السيئة ( قاتلهم الله أنى يؤفكون\nفأي هؤلاء الفرق يا أهل المدينة تتبعون أو بأي مذاهبهم تقتدون وقد بلغني مقالتكم في أصحابي وما عبتموه من حداثة أسنانهم ويحكم وهل كان أصحاب رسول الله وآله المذكورون في الخير إلا أحداثا شبابا شباب والله مكتهلون في شبابهم غضيضة عن الشر أعينهم ثقيلة عن الباطل أرجلهم أنظاء عبادة قد نظر الله إليهم في جوف الليل منحنية أصلابهم على أجزاء القرآن كلما مر أحدهم بآية من\nذكر الله بكى شوقا وكلما مر بآية من ذكر الله شهق خوفا كأن زفير جهنم بين أذنيه قد أكلت الأرض جباههم وركبهم ووصلوا كلال الليل بكلال النهار مصفرة ألوانهم ناحلة أجسامهم من طول القيام وكثرة الصيام أنضاء عبادة موفون بعهد الله منتجزون لوعد الله قد شروا أنفسهم حتى إذا التقت الكتيبتان وأبرقت سيوفها وفوقت سهامها وأشرعت رماحها لقو شبا الأسنة وشائك السهام وظباة السيوف بنحورهم ووجوههم وصدورهم فمضى الشاب منهم قدما حتى اختلفت رجلاه على\nعنق فرسه واختضبت محاسن وجهه بالدماء وعفر جبينه بالثرى وانحطت عليه الطير من السماء وتمزقته سباع الأرض فكم من عين في منقار طائر طالما بكى بها صاحبها في جوف الليل من خوف الله وكم من وجه رقيق وجبين عتيق قد فلق بعمد الحديد ثم بكى\nوقال آه آه على فراق الإخوان رحمة الله على تلك الأبدان وأدخل الله أرواحهم الجنان قال هارون بلغني أنه بايعه بالمدينة ناس منهم إنسان هذلي وإنسان سراقي وسكسب الذي كان معلم النحو ثم خرج وخلف بالمدينة بعض أصحابه فسار حتى نزل الوادي وكان مروان قد بعث ابن عطية","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":19,"spl":"خطبة رابعة له","tags":["أبي العبر","الحب والغزل"],"loc":3926},
{"id":"b299-33","bab":"الجزء 23","sec":"مروان ينتخب جيشا بقيادة ابن عطية","page":"ج23 ص257","text":"قال هارون حدثني أبو يحيى الزهري أن مروان انتخب من عسكره أربعة آلاف استعمل عليهم ابن عطية فأمره بالجد في السير وأعطى كل رجل من أصحابه مائة دينار وفرسا عربية وبغلا لثقله وأمره أن يمضي فيقاتلهم\nوقال المدائني بعث عبد الملك بن عطية السعدي أحد بني سعد بن بكر في أربعة آلاف معه فرسان من أهل الشأم ووجوههم منهم شعيب البارقي ورومي بن عامر المري\nوقيل بل هو كلابي وفيهم ألف من أهل الجزيرة وشرطوا على مروان أنهم إذا قتلوا عبد الله بن يحيى وأصحابه رجعوا إلى الجزيرة ولم يقيموا بالحجاز فأجابهم إلى ذلك قالوا فخرج حتى إذا نزل بالمعلى فكان رجل من أهل المدينة يقال له العلاء بن أفلح مولى أبي الغيث يقول\nلقيني وأنا غلام في ذلك اليوم رجل من أصحاب ابن عطية فسألني ما اسمك يا غلام فقلت العلاء فقال ابن من فقلت ابن أفلح قال أعربي أم مولى قلت بل مولى قال مولى من قلت مولى أبي الغيث قال فأين نحن قلت بالمعلى قال فأين نحن غدا قلت بغالب قال فما كلمني حتى أردفني خلفه ثم مضى بي حتى أدخلني على ابن عطية فقال سل هذا الغلام ما اسمه فسألني فرددت عليه القول الذي قلت فسر بذلك ووهب لي دراهم وقال أبو صخر الهذلي حين بلغه قدوم ابن عطية\n(قل للذين استضعفوا لا تعجلوا ... أتاكم النصر وجيش جحفل)\n(عشرون ألفا كلهم مسربل ... يقدمهم جلد القوى مستبسل)\n(دونكم ذا يمن فأقبلوا ... وواجهوا القوم ولا تستخجلوا)\n(عبد المليك القلبي الحول ... أقسم لا يفلى ولا يرجل)\n(حتى يبيد الأعور المضلل ... ويقتل الصباح والمفضل)\nلأعور عبد الله بن يحيى رئيسهم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":20,"spl":"مروان ينتخب جيشا بقيادة ابن عطية — ابن عطية ينتصر على بلج بن عقبة — أهل المدينة يفتكون بال","tags":["أبي العبر","السفر والحج"],"loc":3927},
{"id":"b299-35","bab":"الجزء 23","sec":"ابن عطية ينتصر على بلج بن عقبة — أهل المدينة يفتكون بالخوارج","page":"ج23 ص258 – ج23 ص259","text":"قال المدائني عن رجاله وبعث أبو حمزة بلج بن عقبة في ستمائة رجل ليقاتل عبد الملك بن عطية فلقيه بوادي القرى لأيام خلت من جمادى الأولى سنة ثلاثين ومائة فتواقفوا ودعاهم بلج إلى الكتاب والسنة وذكر بني أمية وظلمهم فشتمهم أهل الشام وقالوا أنتم يا أعداء الله أحق بهذا ممن ذكرتم وقلتم فحمل عليهم بلج وأصحابه فانكشف طائفة من أهل الشام وثبت أبن عطية في عصبة صبروا معه ونادى يا أهل الشام يا أهل الحفاظ ناضلوا عن\nدينكم وأميركم فكروا واصبروا صبرا حسنا وقاتلوا قتالا شديدا فقتل بلج وأكثر أصحابه وانحازت قطعة من أصحابه نحو المائة إلى جبل اعتصموا به فقاتلهم ابن عطية ثلاثة أيام فقتل منهم سبعين رجلا ونجا ثلاثون فرجعوا إلى أبي حمزة ونصب ابن عطية رأس بلج على رمح\nقال واغتم الذين رجعوا إلى أبي حمزة من وادي القرى إلى المدينة وهم الثلاثون ورجعوا وجزعوا من أنهزامهم وقالوا ما فررنا من الزحف فقال لهم أبو حمزة لا تجزعوا فأنا لكم فئة وإلي انصرفتم\nقال المدائني وخرج أبو حمزة من المدينة إلى مكة واستخلف رجلا يقال له المفضل عليها فدعا عمر بن عبد الرحمن بن أسيد بن عبد الرحمن بن يزيد بن الخطاب الناس إلى قتالهم فلم يجد كبير أمر لأن القتل قد كان شاع في الناس وخرج وجوه أهل البلد عنه فاجتمع إلى عمر البربر والزنج وأهل السوق والعبيد فقاتل بهم الشراة فقتل المفضل وعامة أصحابه وهرب الباقون فلم يبق في المدينة منهم أحد فقال في ذلك سهيل أبو البيضاء مولى زينب بنت الحكم بن العاصي\n(ليت مروان رانا ... يوم الإثنين عشيه)\n(إذ غسلنا العار عنا ... وانتضينا المشرفيه)\nقال فلما قدم ابن عطية المدينة أتاه عمر بن عبد الرحمن بن اسيد فقال له أصلحك الله إني جمعت قضي وقضيضي فقاتلت هؤلاء فقتلنا\nمن امتنع من الخروج عن المدينة وأخرجنا الباقين فلقيه أهل المدينة بقضهم وقضيضهم","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":20,"spl":"مروان ينتخب جيشا بقيادة ابن عطية — ابن عطية ينتصر على بلج بن عقبة — أهل المدينة يفتكون بال","tags":["أبي العبر"],"loc":3928},
{"id":"b299-36","bab":"الجزء 23","sec":"مصرع أبي حمزة مع زوجته","page":"ج23 ص260","text":"قال وأقام ابن عطية بالمدينة شهرا وأبو حمزة مقيم بمكة ثم توجه إليه فقال له علي بن حصين العنبري إني قد كنت أشرت عليك يوم قديد وقبله أن تقتل هؤلاء الأسرى كلهم فلم تفعل وعرفتك أنهم سيغدرون فلم تقبل حتى قتلوا المفضل وأصحابنا المقيمين بالمدينة وأنا أشير عليك اليوم أن تضع السيف في هؤلاء فإنهم كفرة فجرة ولو قدم عليك ابن عطية لكانوا أشد عليك منه فقال لا أرى ذلك لأنهم قد دخلوا في الطاعة وأقروا بالحكم ووجب لهم حق الولاية قال إنهم سيغدرون فقال أبعدهم الله ( فمن نكث فإنما ينكث على نفسه\nقال وقدم عبد الملك بن عطية مكة فصير أصحابه فرقتين ولقي الخوارج من وجهين فصير طائفة بالأبطح وصار هو في الطائفة الأخرى بإزاء أبي حمزة فصار أبو حمزة أسفل مكة وصير أبرهة بن الصباح بالأبطح في ثمانين فارسا فقاتلهم أبرهة فانهزم أهل الشأم إلى عقبة منى فوقفوا عليها ثم كروا وقاتلهم فقتل أبرهة كمن له هبار القرشي وهو على جبل دمشق عند بئر ميمون فقتله وتفرق الخوارج وتبعهم أهل الشأم يقتلونهم حتى دخلوا المسجد والتقى أبو حمزة وابن عطية بأسفل مكة فخرج أهل مكة مع ابن عطية فقتل أبو حمزة على فم الشعب وقتلت معه امرأته وهي ترتجز وتقول\n(أنا الجعيداء وبنت الأعلم ... من سال عن اسمي فإسمي مريم)\n(بعت سواري بسيف مخذم ... )\nال وتفرقت الخوارج فأسر أهل الشام منهم أربعمائة فدعا بهم ابن عطية فقال ويلكم ما دعاكم إلى الخروج مع هذا قالوا ضمن لنا الكنة يريدون الجنة وهي لغتهم فقتلهم وصلب أبا حمزة وأبرهة بن الصباح ورجلين من أصحابهم على فم الشعب شعب الخيف ودخل علي بن الحصين دارا من دور قريش فأحدق أهل الشام بالدار فأحرقوها فلما رأى ذلك رمى بنفسه من الدار فقاتلهم وأسر فقتل وصلب مع أبي حمزة ولم يزالوا مصلبين حتى أفضى الأمر إلى بني العباس وحج مهلهل الهجيمي في خلافة أبي العباس فأنزل أبا حمزة ليلا فدفنه ودفن خشبته\nقال المدائني وكان بمكة مخنثان يقال لأحدهما سبكت وللآخر صقرة فكان صقرة يرجف بأهل الشام وكان سبكت يرجف بالإباضية فعرف الخوارج أمرهما فوجهوا إلى سبكت فأخذوه فقتلوه فقال صقرة يا ويله هو والله أيضا مقتول وإنما كنت أنا وسبكت نتكايد ونتكاذب فقتلوه وغدا يجيء أهل الشام فيقتلونني فلما دخل ابن عطية مكة عرف خبرهما فأخذ صقرة فقتله","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":21,"spl":"مصرع أبي حمزة مع زوجته — مذهب ابن عطية","tags":["أبي العبر","الجواري والنساء"],"loc":3929,"partial":1},
{"id":"b299-37","bab":"الجزء 23","sec":"مذهب ابن عطية","page":"ج23 ص261","text":"وقال هارون في خبره أخبرني عبد الملك بن الماجشون قال لما التقى أبو حمزة وابن عطية قال أبو حمزة لا تقاتلوهم حتى تخبروهم فصاح بهم ما تقولون في القرآن والعمل به فصاح ابن عطية نضعه في جوف\nالجوالق قال فما تقولون في مال اليتيم قال نأكل ماله ونفجر بأمه ثم أجاب في أشياء بلغني أنه سأله عنها فلما سمعوا كلامهم قاتلوهم حتى أمسوا فصاحت الشراة ويحك يابن عطية إن الله جل وعز قد جعل الليل سكنا فاسكن ونسكن فأبى وقاتلهم حتى قتلهم جميعا\nقال هارون أخبرني موسى بن كثير أن أبا حمزة خطب أهل المدينة وودعهم ليخرج إلى الحرب فقال يا أهل المدينة إنا خارجون لحرب مروان فإن نظهر نعدل في أحكامكم ونحملكم على سنة نبيكم ونقسم بينكم وإن يكن ما تمنون لنا فسيعلم الذين ظلموا أي منقلب ينقلبون\nقال ووثب الناس على أصحابه حين جاءهم قتله فقتلوهم فكان بشكست ممن قتلوا طلبوه فرقي في درجة كانت في دار أذينة فلحقوه فأنزلوه منها وهو يصيح يا عباد الله فيم تقتلونني قال وأنشدني بعض أصحابنا\n(لقد كان بشكست عبد العزيز ... من أهل القراءة والمسجد)\n(فبعدا لبشكست عبد العزيز ... وأما القران فلا يبعد)\nال هارون وأخبرني بعض أصحابنا أنه رأى رجلا واقفا على سطح يرمي بالحجارة فقيل ويلك أتدري من ترمي مع اختلاط الناس قال والله ما أبالي من رميت إنما هو شام وشار والله ما أبالي أيهما قتلت","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":21,"spl":"مصرع أبي حمزة مع زوجته — مذهب ابن عطية","tags":["أبي العبر","السفر والحج"],"loc":3930},
{"id":"b299-38","bab":"الجزء 23","sec":"مقتل طالب الحق","page":"ج23 ص262","text":"وقال المدائني لما قتل ابن عطية أبا حمزة بعث برأسه مع عروة بن\nزيد بن عطية إلى مروان وخرج إلى الطائف فأقام بها شهرين وتزوج بنت محمد بن عبد الله بن أبي سويد الثقفي واستعمل على مكة رومي بن عامر المري وأتى فل أبي حمزة إلى عبد الله بن يحيى بصنعاء فأقبل معه أصحابه وقد لقبوه طالب الحق يريد قتال ابن عطية وبلغ ابن عطية خبره فشخص إليه فالتقوا بكسة فأكثر أهل الشام القتل فيهم وأخذوا أثقالهم وأموالهم وتشاغلوا بالنهب فركب عبد الله بن يحيى فكشفهم فقتل منهم نحو مائة رجل وقتل قائد من قوادهم يقال له يزيد بن حمل القشيري من أهل قنسرين فذمرهم ابن عطية فكروا وانضم بعضهم إلى بعض وقاتلوا حتى أمسوا فكف بعضهم عن بعض ثم التقوا من غد في موضع كثير الشجر والكرم والحيطان فطال القتال بينهم واستحر القتل في الشراة فترجل عبد الله بن يحيى في ألف فارس فقاتلوا حتى قتلوا جميعا عن آخرهم وانهزم الباقون فتفرقوا في كل وجه ولحق من نجا منهم بصنعاء وولوا عليهم حمامة فقال أبو صخر الهذلي\n(قتلنا دعيسا والذي يكتني الكنى ... أبا حمزة الغاوي المضل اليمانيا)\n(وأبرهة الكندي خاضت رماحنا ... وبلجا صبحناه الحتوف القواضيا)\n(وما تركت أسيافنا منذ جردت ... لمروان جبارا على الأرض عاديا)\nال المدائني وبعث عبد الملك بن عطية رأس عبد الله بن يحيى مع ابنه يزيد بن عبد الملك إلى مروان\nوقال عمرو بن الحصين ويقال الحسن العنبري مولى لهم يرثي عبد الله بن يحيى وأبا حمزة وهذه القصيدة التي في أولها الغناء المذكور أول هذه الأخبار","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":22,"spl":"مقتل طالب الحق","tags":["أبي العبر"],"loc":3931},
{"id":"b299-39","bab":"الجزء 23","sec":"رثاء الخوارج","page":"ج23 ص264","text":"(هبت قبيل تبلج الفجر ... هند تقول ودمعها يجري)\n(أن أبصرت عيني مدامعها ... ينهل واكفها على النحر)\n(أنى اعتراك وكنت عهدي لا ... سرب الدموع وكنت ذا صبر)\n(أقذى بعينك ما يفارقها ... أم عائر أم مالها تذري)\n(أم ذكر إخوان فجعت بهم ... سلكوا سبيلهم على خبر)\n(فأجبتها بل ذكر مصرعهم ... لا غيره عبراتها تمري)\n(يا رب أسلكني سبيلهم ... ذا العرش واشدد بالتقى أزري)\n(في فتية صبروا نفوسهم ... للمشرفية والقنا السمر)\n(تالله ألقى الدهر مثلهم ... حتى أكون رهينة القبر)\n(أوفي بذمتهم إذا عقدوا ... وأعف عند العسر واليسر)\n(متأهلين لكل صالحة ... ناهين من لاقوا عن النكر)\n(صمت إذا احتضروا مجالسهم ... وزن لقول خطيبهم وقر)\n(إلا تجيبهم فإنهم ... رجف القلوب بحضرة الذكر)\n(متأوهون كأن جمر غضا ... للخوف بين ضلوعهم يسري)\n(تلقاهم إلا كأنهم ... لخشوعهم صدروا عن الحشر)\n(فهم كأن بهم جوى مرض ... أو مسهم طرف من السحر)\n(لا ليلهم ليل فيلبسهم ... فيه غواشي النوم بالسكر)\n(إلا كذا خلسا وآونة ... حذر العقاب وهم على ذعر)\n(كم من أخ لك قد فجعت به ... قوام ليلته إلى الفجر)\n(متأوه يتلو قوارع من ... آي القران مفزع الصدر)\n(نصب تجيش بنات مهجته ... بالموت جيش مشاشة القدر)\n(ظمآن وقدة كل هاجرة ... تراك لذته على قدر)\n(تراك ما تهوى النفوس إذا ... رغب النفوس دعت إلى النذر)\n(ومبرأ من كل سيئة ... عف الهوى ذو مرة شزر)\n(والمصطلي بالحرب يسعرها ... بغبارها وبفنية سعر)\n(يجتاحها بأقل ذي شطب ... عضب المضارب قاطع البتر)\n(لا شيء يلقاه أسر له ... من طعنة في ثغرة النحر)\n(نجلاء منهرة تجيش بما ... كانت عواصي جوفه تجري)\n(كخليلك المختار أذك به ... من مقتد في الله أو مشر)\n(خواص غمرة كل متلفة ... في الله تحت العثير الكدر)\n(تراك ذي النخوات مختضبا ... بنجيعه بالطعنة الشزر)\n(وابن الحصين وهل له شبه ... في العرف أنى كان والنكر)\n(بسامة لم تحن أضلعه ... لذوي أخوته على غمر)\n(طلق اللسان بكل محكمة ... رآب صدع العظم ذي الوقر)\n(لم ينفكك في جوفه حزن ... تغلي حرارته وتستشري)\n(ترقى وآونة يخفضها ... بتنفس الصعداء والزفر)\n(ومخالطي بلج وخالصتي ... سم العدو وجابر الكسر)\n(نكل الخصوم إذا هم شغبوا ... وسداد ثلمة عورة الثغر)\n(والخائض الغمرات يخطر في ... وسط الأعادي أيما خطر)\n(بمشطب أو غير ذي شطب ... هام العدا بذبابه يفري)\n(وأخيك أبرهة الهجان أخي ... الحرب العوان ملقح الجمر)\n(بمرشة فرع تثج دما ... ثج الغوي سلافة الخمر)\n(والضارب الأخدود ليس لها ... حد ينهنهها عن السحر)\n(وولي حكمهم فجعت به ... عمرو فواكبدي على عمرو)\n(قوال محكمة وذي فهم ... عف الهوى متثبت الأمر)\n(ومسيب فاذكر وصيته ... لا تنس إما كنت ذا ذكر)\n(فكلاهما قد كان محتبسا ... لله ذا تقوى وذا بر)\n(في مخبتين ولم أسمهم ... كانوا يدي وهم أول نصري)\n(وهم مساعر في الوغى رجح ... وخيار من يمشي على العفر)\n(حتى وفوا لله حيث لقوا ... بعهود لا كذب ولا غدر)\n(فتخالسوا مهجات أنفسهم ... وعداتهم بقواضب بتر)\n(وأسنة أثبتن في لدن ... خطية بأكفهم زهر)\n(تحت العجاج وفوقهم خرق ... يخفقن من سود ومن حمر)\n(فتفرجت عنهم كماتهم ... لم يغمضوا عينا على وتر)\n(فشعارهم نيران حربهم ... ما بين أعلى الشحر فالحجر)\n(صرعى فحاجلة تنوشهم ... وخوامع لحماتهم تفري)","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":23,"spl":"رثاء الخوارج","tags":["أبي العبر","الحب والغزل","الهجاء"],"loc":3932},
{"id":"b299-40","bab":"الجزء 23","sec":"مروان يأمر ابن عطية بالمسير إلى صنعاء","page":"ج23 ص267","text":"قال المدائني وكتب مروان إلى ابن عطية يأمره بالمسير إلى صنعاء ليقاتل من بها من الخوارج فاستخلف ابنه محمد بن عبد الملك على مكة وعلى المدينة الوليد بن عروة بن عطية وتوجه إلى صنعاء ورجع أهل الجزيرة جميعا إلى بلدهم وكذلك كان مروان شرط لهم فلما قرب من صنعاء هرب عامل عبد الله بن يحيى عنها فأخذ أهل صنعاء أثقاله وحملين من مال كان معه فسلموا ذلك إلى ابن عطية وتتبع أصحاب عبد الله بن يحيى في كل موضع يقتلهم وأقام بصنعاء أشهرا ثم خرج عليه رجل من أصحاب عبد الله بن يحيى في آل ذي الكلاع يقال له يحيى بن عبد الله بن عمر بن السباق في جمع كثير بالجند فبعث إليه ابن عطية ابن أخيه عبد الرحمن بن يزيد بن عطية فلقيه\nبالحرب فهزمه وقتل عامة أصحابه وهرب منه فنجا وخرج عليه يحيى بن كرب الحميري بساحل البحر وانضمت إليه شذاذ الإباضية فبعث إليه أبا أمية الكندي في الوضاحية فالتقوا بالساجل فقتل من الإباضية نحو مائة رجل وتحاجزوا عند المساء فهربت الإباضية إلى حضرموت وبها عامل لعبد الله بن يحيى يقال له عبد الله بن معبد الجرمي فصار في جيش كثير واستفحل أمره وبلغ ابن عطية الخبر فاستخلف ابن أخيه عبد الرحمن بن يزيد بن عطية على صنعاء وشخص إلى حضرموت وبلغ عبد الله بن معبد مسير عبد الملك إليهم فجمعوا الطعام وكل ما يحتاجون إليه في مدينة شبام وهي حصن حضرموت مخافة الحصار ثم عزموا على لقاء ابن عطية في الفلاة فخرجوا حتى نزلوا على أربع مراحل من حضر موت في عدد كثير في فلاة وأتاهم ابن عطية فقاتلهم يومه كله فلما أمسى وقد بلغه ما جمعوا في شبام حدر عسكره في بطن حضرموت إلى شبام ليلا ثم أصبح فقاتلهم حتى انتصف النهار ثم تحاجزوا فلما أمسوا تبع عسكره وأصبح الخوارج فلم يروا للقوم أثرا فاتبعوهم وقد سبقوهم إلى الحصن فأخذوا جميع ما فيه وملكوه ونصب ابن عطية عليهم المسالح وقطع عنهم المادة والميرة وجعل يقتل من يقدر عليه ويسبي ويأخذ الأموال","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":24,"spl":"مروان يأمر ابن عطية بالمسير إلى صنعاء — مصرع ابن عطية","tags":["أبي العبر"],"loc":3933},
{"id":"b299-41","bab":"الجزء 23","sec":"مصرع ابن عطية","page":"ج23 ص268","text":"ثم ورد عليه كتاب مروان بن محمد يأمره بالتعجل إلى مكة ليحج بالناس فصالح أهل حضر موت على أن يرد عليهم ما عرفوا من أموالهم ويولي عليهم من يختارون وسالموه فرضي بذلك وسالمهم وشخص إلى مكة\nمتعجلا مخفا ولما نفذ كتاب مروان ندم بعد ذلك بأيام وقال إنا لله قتلت والله ابن عطية هو الآن يخرج مخفا متعجلا ليلحق الحج فيقتله الخوارج فكان كما\nقال تعجل في بضعة عشر رجلا فلما كان بأرض مراد تلففت عليه جماعة فمن كان من تلك الجماعة إباضيا عرفه فقال ما ننتظر بهذا أن ندرك ثأر إخواننا فيه ومن لم يكن إباضيا ظنه من الإباضية وأنه منهزم فلما علم أنهم يريدونه\nقال لهم ويحكم أنا عامل أمير المؤمنين على الحج فلم يلتفتوا إلى ذلك وقتلوه ونصبت الإباضية رأسه فلما فتشوا متاعه وجدوا فيه الكتاب بولايته على الحج فأخذوا من الإباضية رأسه ودفنوه مع جسده\nقال المدائني خرج إليه جمانة وسعيد ابنا الأخنس في جماعة من قومهما من كندة وعرفه جمانة لما لقيه فحمل عليه هو وأخوه ورجل آخر من همدان يقال له رمانة وثلاثة من مراد وخمسة من كندة وقد توجه في طريق مع أربعة نفر من أصحابه وتوجه باقيهم في طريق آخر فقصدوا حيث توجه ابن عطية ووجهوا في آثار أصحابه نحو أربعين رجلا منهم فأدركوهم فقتلوهم وأدرك سعيد وجمانة وأصحابهما ابن عطية فعطف عبد الملك على سعيد فضربه وطعنه جمانة فصرعه عن فرسه ونزل إليه سعيد فقعد على صدره فقال له ابن عطية هل لك يا سعيد في أن تكون أكرم العرب أسيرا فقال يا عدو الله أترى الله كان يمهلك أو تطمع في الحياة وقد قتلت طالب الحق وأبا حمزة وبلجا وأبرهة فقتله وقتل أصحابه جميعا وبعثوا برأسه إلى حضر موت وبلغ ابن أخيه وهو بصنعاء خبره فأرسل شعيبا البارقي في الخيل فقتل الرجال والصبيان وبقر بطون النساء وأخذ الأموال وأخرب القرى وجعل يتتبع البري والنطف حتى لم يبق أحد من قتله ابن عطية ولا\nمن الإباضية إلا قتله ولم يزل مقيما باليمن إلى أن أفضى الأمر إلى بني هاشم وقام بالأمر أبو العباس السفاح تم الجزء الثالث والعشرون من كتاب الأغاني ويليه الجزء الرابع والعشرون وأوله خبر عبد الله بن أبي العلاء","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":24,"spl":"مروان يأمر ابن عطية بالمسير إلى صنعاء — مصرع ابن عطية","tags":["أبي العبر"],"loc":3934},
{"id":"b299-42","bab":"الجزء 24","sec":"خبر عبد الله بن أبي العلاء","page":"ج24 ص5","text":"عبد الله بن أبي العلاء رجل من أهل سر من رأى وكان يأخذ عن إسحاق وطبقته فبرع وله صنعة يسيرة جيدة وابنه أحمد بن عبد الله بن أبي العلاء أحد المحسنين المتقدمين أخذ عن مخارق وعلوية وطبقتهما وعمر إلى آخر أيام المعتضد وكانت فيه عربدة\nوكان عبد الله بن أبي العلاء حسن الوجه والزي ظريفا شكلا حدثني ذكاء وجه الرزة قال قال لي ابن المكي المرتجل كان يقوم دابة عبد الله بن أبي العلاء وثيابه إذا ركب ألف دينار قال وقال لي ابن المكي حدثني أبي قال نظر أحمد بن يوسف الكاتب إلى عبد الله بن أبي العلاء عند إسحاق وهو يطارحه فأقام عند إسحاق وسأله احتباس عبد الله عنده فأمره بذلك فاعتل عليه وقال أريد أن أشيع غازيا يخرج من جيراننا فقال له أحمد بن يوسف\n(لا تخرجن مع الغزاة مشيعا ... إن الغزي يراك أفضل مغنم)\n(ودع الحجيج ولا تشيع وفدهم ... أخشى عليك من الحجيج المحرم)\n(ما أنت إلا غادة ممكورة ... لولا شواربك المحيطة بالفم)\nوقد روي أن هذا الشعر لسعيد بن حميد في عبد الله بن أبي العلاء وهو الصحيح فأقسم عليه إسحاق أن يقيم فأقام وقال لي جعفر بن قدامة وقد تجاذبنا هذا الخبر حدثني حماد بن إسحاق عن أبيه أن العشرة اتصلت بين عبد الله وبين أحمد بن يوسف وتعشقه وأنفق عليه جملة من المال حتى اشتهر به فعاتبه محمد بن عبد الملك الزيات في ذلك فقال له\n(لا تعذلني يا أبا جعفر ... عذل الأخلاء من اللوم)\n(إن استه مشربة حمرة ... كأنها وجنة مكظوم)\nقد قيل إن هذين البيتين لأحمد بن يوسف في موسى بن عبد الملك وكان بعض الشعراء قد أولع بعبد الله بن أبي العلاء يهجوه ويذكر أن أباه أبا العلاء هو سالم السقاء وفيه يقول هذا الشعر\n(كنت في مجلس أنيق جميل ... فأتانا ابن سالم مختالا)\n(فتغنى صوتا فأخطأ فيه ... وابتدا ثانيا فكان محالا)\n(وابتغى خلعة على ذاك منا ... فخلعنا على قفاه النعالا)\nفيه يقول هذا الشاعر أنشدناه ابن عمار وغيره\n(إذا ابن العلاء أقيم عنا ... فأهلا بالمجالس والرحيق)\n(قفاه على أكف الشرب وقف ... وجلده وجهه ميدان ريق)\n\n(أفاطم حييت بالأسعد ... متى عهدنا بك لا تبعدي)\n(تبارك ذو العرش ماذا نرى ... من الحسن في جانب المسجد)\n(فإن شئت آليت بين المقام ... والركن والحجر الأسود)\n(أأنساك ما دام عقلي معي ... أمد به أمد السرمد)\nلشعر لأمية بن أبي عائذ والغناء لحكم الوادي هزج خفيف\nبإطلاق الوتر في مجرى الوسطى عن إسحاق وفيه للأبجر ثقيل أول بالوسطى عن عمرو وقال ابن المكي فيه هزج ثقيل بالبنصر لعمر الوادي وفيه لفليح لحن من رواية بذل ولم يذكر طريقته","topic":"أخبار أبي العبر ونسبه","topicNo":299,"sp":25,"spl":"خبر عبد الله بن أبي العلاء","tags":["أبي العبر"],"song":1,"loc":3935},
{"id":"b300-2","bab":"الجزء 24","sec":"نسب أمية بن أبي عائذ وأخباره — مدحه عبد العزيز بن مروان","page":"ج24 ص10 – ج24 ص11","text":"أمية بن أبي عائذ العمري أحد بني عمرو بن الحارث بن تميم بن سعد بن هذيل شاعر إسلامي من شعر اء الدولة الأموية وهذا أكثر ما وجدته من نسبه في سائر النسخ وكان أمية أحد مداحي بني مروان وله في عبد الملك وعبد العزيز ابني مروان قصائد مشهورة\nفذكر ابن الأعرابي وأبو عبيدة جميعا أنه وفد إلى عبد العزيز إلى مصر وقد امتدحه بقصيدته التي أولها\n(ألا إن قلبي مع الظاعنينا ... حزين فمن ذا يعزي الحزينا)\n(فيالك من روعة يوم بانو ... بمن كنت أحسب ألا يبينا)\nي هذين البيتين للحسين بن محرز خفيف ثقيل عن الهشامي وفي هذه القصيدة يقول\n(إلى سيد الناس عبد العزيز ... أعملت للسير حرفا أمونا)\n(صهابية كعلاة القيون ... من ضرب جوهر ما يخلصونا)\n(إذا أزبدت من تباري المطي ... خلت بها خبلا أو جنونا)\n(تؤم النواعش والفرقدين ... تنصب للقصد منها الجبينا)\n(إلى معدن الخير عبد العزيز ... تبلغنا ظلعا قد حفينا)\n(ترى الأدم والعيس تحت المسوح ... قد عدن من عرق الأين جونا)\n(تسير بمدحي عبد العزيز ... ركبان مكة والمنجدونا)\n(محبرة من صريح الكلام ... ليس كما لفق المحدثونا)\n(وكان امرا سيدا ماجدا ... يصفي العتيق وينفي الهجينا)\nال وطال مقامه عند عبد العزيز وكان يأنس به ووصله صلات سنية فتشوق إلى البادية وإلى أهله فقال لعبد العزيز\n(متى راكب من أهل مصر وأهله ... بمكة من مصر العشية راجع)\n(بلى إنها قد تقطع الخرق ضمر ... تباري السرى والمعسفون الزعازع)\n(متى ما تجزها يا بن مروان تعترف ... بلاد سليمى وهي خوصاء ظالع)\n(وباتت تؤم الدار من كل جانب ... لتخرج واشتدت عليها المصارع)\n(فلما رأت ألا خروج وأنما ... لها من هواها ما تجن الأضالع)\n(تمطت بمجدول سبطر فطالعت ... وماذا من اللوح اليماني تطالع !)\nقال له عبد العزيز اشتقت والله إلى أهلك يا أمية فقال نعم والله أيها الأمير فوصله وأذن له ومما يغنى فيه من شعر أمية\n(تمر كجندلة المنجنيق ... يرمى بها السور يوم القتال)\n(فماذا تخطرف من قلة ... ومن حدب وإكام توالي)\n(ومن سيرها العنق المسبطر ... والعجرفية بعد الكلال)\nلغناء لابن عائشة وقد ذكر في أخباره مع غريبه وأحاديث لابن عائشة في معناه\n\n(أأم نهيك ارفعي الطرف صاعدا ... ولا تيأسي أن يثري الدهر بائس)\n(سيغنيك سيري في البلاد ومطلبي ... وبعل التي لم تخط في الحي جالس)\n(سأكسب مالا أو تبيتن ليلة ... بصدرك من وجد علي وساوس)\n(ومن يطلب المال الممنع بالقنا ... يعش مثريا أو يود فيما يمارس)\nلشعر لعبد الله بن أبي معقل الأنصاري والغناء لسليم خفيف ثقيل بالوسطى عن عمرو وقد ذكر ابن المكي أن فيه لإبراهيم لحنا من الهزج بالوسطى وذكر الهاشمي وحبش أن فيه لإبراهيم ثاني ثقيل وذكر حبش أنه لإسحاق","topic":"نسب أمية بن أبي عائذ وأخباره","topicNo":300,"sp":0,"spl":"نسب أمية بن أبي عائذ وأخباره — مدحه عبد العزيز بن مروان","tags":["المديح"],"song":2,"loc":3936},
{"id":"b301-1","bab":"الجزء 24","sec":"أخبار عبد الله بن أبي معقل ونسبه","page":"ج24 ص15","text":"هو عبد الله بن أبي معقل بن نهيك بن إساف بن عدي بن زيد بن جشم بن حارثة بن الحارث بن الخزرج بن عمرو وهو النبيت ابن مالك بن الأوس بن حارثة بن ثعلبة بن عمرو بن عامر بن حارثة بن امرىء القيس بن ثعلبة بن مازن بن الأزد بن الغوث بن نبت بن مالك بن زيد بن كهلان بن سبأ ابن يشجب بن يعرب بن قحطان شاعر مقل حجازي من شعراء الدولة الأموية وكان يقال لأبيه منهب الورق\nوقيل بل جده المسمى بذلك لأنه كسب مالا فعجب أهل المدينة من كثرته فأباحهم إياه فنهبوه أخبرني الحرمي بن أبي العلاء قال حدثني أبو بكر عبد الله بن جعفر بن مصعب بن عبد الله الزبيري قال حدثني جدي مصعب بن عبد الله عن ابن القداح أنه قال\nهذان البيتان يعني قوله\n(أأم نهيك ارفعي الطرف صاعدا ... )\nالذي بعده لعبد الله بن أبي معقل بن نهيك بن إساف والناس يروونهما لجده وليس ذلك بصحيح هما لعبد الله","topic":"أخبار عبد الله بن أبي معقل ونسبه","topicNo":301,"sp":0,"spl":"أخبار عبد الله بن أبي معقل ونسبه — كان عمه عباد صحابيا — كان محسودا ليساره وسعة ماله","tags":["اللهو والمزاح","السفر والحج"],"loc":3937,"partialRef":{"sid":"b300-2","gi":4,"vi":0,"side":0},"partial":1},
{"id":"b301-3","bab":"الجزء 24","sec":"كان عمه عباد صحابيا — كان محسودا ليساره وسعة ماله","page":"ج24 ص15 – ج24 ص16","text":"وكان عباد بن نهيك بن إساف عمه أدرك النبي وصحبه وصلى معه إلى القبلتين وصلى معه الظهر وصلى معه في ركعتين منها إلى بيت المقدس وركعتين إلى الكعبة وأدرك النبي وهو شيخ كبير لا فضل فيه فوضع عنه الغزو وكان نهيك بن إساف يهاجي أبا الخضر الأشهلي في الجاهلية وأشعارهما موجودة في أشعار الأنصار\nأخبرني الحرمي بن أبي العلاء قال حدثني عبد الله بن جعفر عن جده مصعب عن ابن القداح قال كان ابن أبي معقل محسودا في قومه يجاهرونه بالعداوة ليساره وسعة ماله ويحسدونه وكان بنى قصرا في بني حارثة وسماه مرغما وقال له قائل ما لك ولقومك فقال مالي إليهم ذنب إلا أني أثريت وكنت معدما وبنيت\nمرغما وأنكحت مريم ومريم يعني ابنته مريم وبنت ابنه مريم فأما ابنته مريم فتزوجها حبيب بن الحكم بن أبي العاصي بن أمية وبنت ابنه مسكين بن عبد الله بن أبي معقل وهي مريم تزوجها محمد بن خالد بن الزبير بن العوام\nأخبرني الحرمي قال حدثنا الزبير بن بكار قال حدثني عمي مصعب قال خطب محمد بن خالد بن الزبير وحبيب بن الحكم بن أبي العاصي إلى عبد الله بن أبي معقل ابنته مريم فأرغبه حبيب في الصداق فزوجه إياها ثم شبت مريم بنت مسكين بن عبد الله بن أبي معقل فبرعت في الجمال ولقي محمد بن خالد يوما فقال له يابن خالد إن تكن مريم قد فاتتك فقد يفعت مريم بنت أخيها وما هي بدونها في الجمال وقد آثرتك بها\nقال فتزوجها على عشرين ألفا وقال ابن القداح كان ابن أبي معقل كثير الأسفار في طلب الرزق فلامته امرأته أم نهيك وهي ابنة عمه على ذلك وقد قدم من مصر فلم يلبث أن قال لها جهزيني إلى الكوفة إلى المغيرة بن شعبة فإنه صديقي وقد وليها فجهزته ثم\nقالت لن تزال في أسفارك هذه تتردد حتى تموت فقال لها أو أثري ثم أنشأ يقول\n(أأم نهيك ارفعي الطرف صاعدا ... ولا تيأسي أن يثري الدهر يائس)\nهي قصيدة فيها مما يغنى فيه قوله\n(فلولا ثلاث هن من عيشة الفتى ... وجدك لم أحفل متى قام رامس)\n(فمنهن تحريك الكميت عنانه ... إذا ابتدر النهب البعيد الفوارس)\n(ومنهن سبق العاذلات بشربة ... كأن أخاها - وهو يقظان - ناعس)\n(ومنهن تجريد الأوانس كالدمى ... إذا ابتز عن أكفالهن الملابس)\nالغناء في هذه الأبيات لمقاسة بن ناصح ثقيل أول بالبنصر وفيها للحسين بن محرز خفيف ثقيل من جامع أغانيه وهو لحن معروف مشهور","topic":"أخبار عبد الله بن أبي معقل ونسبه","topicNo":301,"sp":0,"spl":"أخبار عبد الله بن أبي معقل ونسبه — كان عمه عباد صحابيا — كان محسودا ليساره وسعة ماله","tags":["الجواري والنساء"],"song":1,"loc":3938},
{"id":"b301-4","bab":"الجزء 24","sec":"وفوده على مصعب بن الزبير","page":"ج24 ص18","text":"قال ابن القداح ثم قدم المدينة فلم يزل مقيما بها حتى ولي مصعب بن الزبير العراق فوفد إليه ابن أبي معقل ولقيه فدخل إليه يوما وهو يندب الناس إلى غزوة زرنج ويقول من لها\nفوثب عبد الله بن أبي معقل وقال أنا لها فقال له اجلس ثم ندب الناس فانتدب لها مرة ثانية فقال له مصعب اجلس ثم ندبهم ثالثة فقال له عبد الله أنا لها فقال له اجلس فقال له أدنني إليك حتى أكلمك فأدناه فقال قد علمت أنه ما يمنعك مني إلا أنك تعرفني ولو انتدب إليها رجل ممن لا تعرفه لبعثته فلعلك تحسدني أن أصيب خيرا أو أستشهد فأستريح من الدنيا وطلبها فأعجبه قوله وجزالته فولاه فأصاب في وجهه ذلك مالا كثيرا وانصرف إلى المدينة فقال لزوجته ألم أخبرك في شعري أنه\n(سيغنيك سيري في البلاد ومطلبي ... وبعل التي لم تحظ في الحي جالس)\nقالت بلى والله لقد أخبرتني وصدق خبرك قال وفي هذه الغزاة يقول ابن قيس الرقيات\n(إن يعش مصعب فنحن بخير ... قد أتانا من عيشنا ما نرجي)\n(ملك يطعم الطعام ويسقي ... لبن البخت في عساس الخلنج)\n(جلب الخيل من تهامة حتى ... بلغت خيله قصور زرنج)\nوت\n(يقتلننا بحديث ليس يعلمه ... من يتقين ولا مكنونه بادي)\n(فهن ينبذن من قول يصبن به ... مواقع الماء من ذي الغلة الصادي)\nلشعر للقطامي والغناء لإسحاق خفيف ثقيل أول بالوسطى وفيه رمل مجهول","topic":"أخبار عبد الله بن أبي معقل ونسبه","topicNo":301,"sp":1,"spl":"وفوده على مصعب بن الزبير","tags":["السفر والحج"],"song":1,"loc":3939},
{"id":"b302-1","bab":"الجزء 24","sec":"ذكر نسب القطامي وأخباره","page":"ج24 ص21","text":"القطامي لقب غلب عليه واسمه عمير بن شييم وكان نصرانيا وهو شاعر إسلامي مقل مجيد أخبرني عمي قال حدثنا الكراني قال حدثنا العمري عن الهيثم بن عدي عن عبد الله بن عياش عن مجالد عن الشعبي قال قال عبد الملك ابن مروان وأنا حاضر للأخطل يا أخطل أتحب أن لك بشعرك شعر شاعر من العرب قال اللهم لا إلا شاعرا منا مغدف القناع خامل الذكر حديث السن إن يكن في أحد خير فسيكون فيه ولوددت أني سبقته إلى قوله\n(يقتلننا بحديث ليس يعلمه ... من يتقين ولا مكنونه بادي)\n(فهن ينبذن من قول يصبن به ... مواقع الماء من ذي الغلة الصادي)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":0,"spl":"ذكر نسب القطامي وأخباره — صريع الغواني","tags":["الرواية والكتابة"],"loc":3940},
{"id":"b302-2","bab":"الجزء 24","sec":"صريع الغواني","page":"ج24 ص22","text":"أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح قال القطامي أول من لقب صريع الغواني بقوله\n(صريع غوان راقهن ورقنه ... لدن شب حتى شاب سود الذوائب)\nال أبو عمرو الشيباني نزل القطامي في بعض أسفاره بامرأة من محارب قيس فنسبها فقالت أنا من قوم يشتوون القد من الجوع قال ومن هؤلاء ويحك قالت محارب ولم تقره فبات عندها بأسوإ ليلة فقال فيها قصيدة أولها\n(نأتك بليلى نية لم تقارب ... وما حب ليلى من فؤادي بذاهب)\nيقول فيها\n(ولا بد أن الضيف يخبر ما رأى ... مخبر أهل أو مخبر صاحب)\n(سأخبرك الأنباء عن أم منزل ... تضيفتها بين العذيب فراسب)\n(تلفعت في طل وريح تلفني ... وفي طرمساء غير ذات كواكب)\n(إلى حيزبون توقد النار بعدما ... تلفعت الظلماء من كل جانب)\n(تصلى بها برد العشاء ولم تكن ... تخال وميض النار يبدو لراكب)\n(فما راعها إلا بغام مطية ... تريح بمحسور من الصوت لاغب)\n(تقول وقد قربت كوري وناقتي ... إليك فلا تذعر على ركائبي)\n(فلما تنازعنا الحديث سألتها : ... من الحي ؟ قالت : معشر من محارب)\n(من المشتوين القد مما تراهم ... جياعا وريف الناس ليس بعازب)\n(فلما بدا حرمانها الضيف لم يكن ... علي مناخ السوء ضربة لازب)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":0,"spl":"ذكر نسب القطامي وأخباره — صريع الغواني","tags":["الجواري والنساء","الرواية والكتابة"],"loc":3941},
{"id":"b302-3","bab":"الجزء 24","sec":"مدحه عبد الواحد بن سليمان","page":"ج24 ص23","text":"قال أبو عمرو بن العلاء أول ما حرك من القطامي ورفع من ذكره أنه قدم في خلافة الوليد بن\nعبد الملك دمشق ليمدحه فقيل له إنه بخيل لا يعطي الشعراء وقيل بل قدمها في خلافة عمر بن عبد العزيز فقيل له إن الشعر لا ينفق عند هذا ولا يعطي عليه شيئا وهذا عبد الواحد بن سليمان بن عبد الملك فامتدحه فمدحه بقصيدته التي أولها\n(إنا محيوك فاسلم أيها الطلل ... وإن بليت وإن طالت بك الطيل)\nقال له كم أملت من أمير المؤمنين قال أملت أن يعطيني ثلاثين ناقة فقال قد أمرت لك بخمسين ناقة موقرة برا وتمرا وثيابا ثم أمر بدفع ذلك إليه\nوفي أول هذه القصيدة غناء نسبته\n(إنا محيوك فاسلم أيها الطلل ... وإن بليت وإن طالت بك الطيل)\n(يمشين رهوا فلا الأعجاز خاذلة ... ولا الصدور على الأعجاز تتكل)\nلغناء لسليم هزج بالبنصر وقيل إنه لغيره أخبرني ابن عمار قال حدثنا محمد بن عباد قال قال أبو عمرو الشيباني لو قال القطامي بيته\n(يمشين رهوا فلا الأعجاز خاذلة ... ولا الصدور على الأعجاز تتكل)\nي صفة النساء لكان أشعر الناس ولو قال كثير\n(فقلت لها : يا عز كل مصيبة ... إذا وطنت يوما لها النفس ذلت)\nي مرثية أو صفة حرب لكان أشعر الناس\nوأخبرني أحمد بن جعفر جحظة قال حدثني ميمون بن هارون قال حدثني رجل كان يديم الأسفار قال سافرت مرة إلى الشام على طريق البر فجعلت أتمثل بقول القطامي\n(قد يدرك المتاني بعض حاجته ... وقد يكون مع المستعجل الزلل)\nمعي أعرابي قد استأجرت منه مركبي فقال ما زاد قائل هذا الشعر على أن ثبط الناس عن الحزم فهلا قال بعد بيته هذا\n(وربما ضر بعض الناس بطؤهم ... وكان خيرا لهم لو أنهم عجلوا)\nكان السبب في أسر القطامي على ما حكاه من ذكرنا وذكر ابن الكلبي عن عرام بن حازم بن عطية الكلبي قال أغار زفر بن الحارث على أهل المصيخ وبه جماعة من الحاج وغيرهم\nوقد أصاب أول النهار أهل ماء يقال له حصف وفيه سيد بني الجلاح مصاد ابن المغيرة بن أبي جبلة فأسره فأتى به قرقيسيا ثم من عليه وقتل عفيف ابن حسان بن حصين من بني الجلاح ثم مضى زفر إلى المصيخ فاجتمع من بها إلى عمير بن حسان بن عمر بن جبلة فامتنعوا فقال لهم زفر إني لا أريد دماءكم فأعطوا بأيديكم فأبوا وقاتلوا فقتل منهم جماعة كثيرة وقتل معهم رجلان من تغلب يقال لأحدهما جساس والآخر غني وهو أبو جساس وقد قالت له امرأته يا أبا جساس هؤلاء قومك فأتهم حين اجتمعوا وامتنعوا فقال اليوم نزاري وأمس كلبي ما أنا بمفارقهم فقاتل حتى قتل فكانت القتلى يوم المصيخ من كلب ثمانية عشر رجلا والتغلبيين وبقى الماء ليس فيه إلا النساء فلما انصرف عنهم زفر أراد النساء أن يجررن القتلى إلى بئر يقال لها كوكب فلما أردن أن يجررن رجلا قالت وليته من النساء لا يكون فلان تحت رجالكن كلهم فأتت أم عمير بن حسان وهي كيسة بنت أبي فأعلقت في رجله رداءها ثم قالت اجسر عمير فإن أباك كان جسورا ثم ألقت عليه التراب والحطب ليكون بينه وبين أصحابه شيء ثم جعلن كلما ألقين رجلا ألقين عليه التراب والحطب حتى وارتهم القليب ولما بلغ حميد بن حريث بن بحدل ما لقي قومه أقبل حتى أتى تدمر ليجمع أصحابه وليغير على قيس فلما وقعت الدماء نهض بنو نمير وهم يومئذ ببطن الجبل وهو على مياه لهم إلى حميد بن حريث بن بحدل حتى قدم وراءه يتهيأ للغارة واجتمعت إليه كلب وقالوا له إن كنت تبرئنا ببراءتنا وتعرف جوارنا أقمنا وإن كنت تتخوف علينا من\nقومك شيئا لحقنا بقومنا فقال أتريدون أن تكونوا أدلاءهم حتى تنجلي هذه الفتنة فاحتبسهم فيها وخليفته في تدمر رجل من كلب يقال له مطر بن عوص وكان فاتكا فأراد حميدا على قتلهم فأبى وكره الدماء فلما سار حميد وقد عاد زفر أيضا مغيرا ليرده عما يريده فنزل قرية له وبلغه مسير زفر فاغتاظ وأخذ في التعبئة فأتاه مطر وكان خرج معه مشيعا له انتهازا لدماء الذين في يده من النميريين فقال ما أصنع بهؤلاء الأسارى الذين في يدي وقد قتل أهل مصبح فقال وهو لا يعقل من الوجد اذهب فاقتلهم فخرج مطر يركض إلى تدمر تخوف ألا يبدوا له فلما أتى تدمر قتلهم وانتبه حميد بعد ذلك بساعة فقال أين مطر حتى أوصيه قالوا انصرف","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":1,"spl":"مدحه عبد الواحد بن سليمان","tags":["المديح"],"song":1,"loc":3942},
{"id":"b302-4","bab":"الجزء 24","sec":"مدحه عبد الواحد بن سليمان","page":"ج24 ص23","text":"قال أدركوا عدو الله فإني أخاف على من بيده من النميريين وبعث فارسا يركض يمنع مطرا عن قتلهم فأتاه وقد قتل كل من كان في يده من الأسرى إلا رجلين وكانوا ستين رجلا فلما بلغه الرسول رسالة حميد\nقال النميريان الباقيان خل عنا فقد أمرت بتخلية سبيلنا فقال أبعد أهل المصيخ لا والله لا تخبران عنهم ثم قتلهما فلما بلغ زفر قتل النميريين بسط يده على كل من أدرك من كلب واستحل الدماء وأخذ في واد يقال له وادي الجيوش وقد انتشرت به كلب للصيد فلم يدرك به أحدا إلا قتله فقتل أكثر من خمسمائة ولم يلقه حميد ثم انصرف إلى قرقيسياء\nوذكر بعض بني نمير أن زفر أغار على كلب يوم حفير ويوم المصيخ ويوم الفرس فقتل منهم أكثر من ألف رجل قال وأغار عليهم زفر في يوم الإكليل فقتل منهم مقتلة عظيمة واستاق نعما كثيرة\nوذكر عرام قال قتل زفر يوم الإكليل جبير بن ثعلبة من بني الجلاح وحسان بن حصين من بني الجلاح ومحمد بن طفيل بن مطير بن أبي جبلة وعمرو بن حسان بن عوف من بني الجلاح ومحمد بن جبلة بن عوف أخوان لأم وقالت امرأة من بني كلب ترثيهم\n(أبعد من دليت في كوكب ... يا نفس ترجين ثواء الرجال ؟)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":2,"spl":"مدحه عبد الواحد بن سليمان","tags":["الجواري والنساء"],"loc":3943},
{"id":"b302-5","bab":"الجزء 24","sec":"شجاعة عمير بن الحباب يوم الغوير","page":"ج24 ص29","text":"قال لقيط أخبرني بعض بني نمير قال أغار عمير بن الحباب على كلب فأصابهم يوم الغوير ويوم الهبل ويوم كآبة فأما يوم الغوير فإنه أرسل رجلا من بني نمير يقال له كليب بن سلمة عينا له ليعلم له علم ابن بحدل وكانت أم النميري كلبية فكانت تتكلم بكلامهم فكان الحسام بن سالم طريدا فيهم فنذروا به فقتلوه وأخذوا فرسه فلقي كليب بن سلمة رجلا من بني كلب فعرفه فقال من أين جئت فقال من عند الأمير حميد بن حريث\nقال وأين تركته قال بمكان كذا وكذا قال كليب كذبت أنا أحدث به عهدا منك قال فأين تركته أنت قال بغوير الضبع قال لكني فارقته أمس فخرج النميري يسوق الكلبي إلى أصحابه\nقال فوالله إني لو أشاء أن أقتله لقتلته أو آخذه لأخذته فخرج يسوقه حتى إذا نظر إلى القوم أنكرهم فقال والله ما أرى هؤلاء أصحابنا قال ويستدبره النميري فيطعنه عند ناغض كتفه اليمنى حتى أخرج السنان من\nحلمة الثدي وأخطأ المقتل وحرك الكلبي فرسه موليا فاتبعته الخيل حتى يدفع إلى ابن بحدل فانهزم فقتلوا من كلب مقتلة عظيمة واتبع عمير بن بحدل فجعل يقول لفرسه\n(أقدم صدام إنه ابن بحدل ... )\n(لا تدرك الخيل وأنت تدأل ... )\n(ألا تمر مثل مر الأجدل ... )\nال فمضى حميد حتى يدفع إلى الغوير وقد كاد الرمح يناله فانطلق يريد الباب فطعن عمير الباب وكسر رمحه فيه فلم يفلت من تلك الخيل غير حميد وشبل بن الخيتار فلما بلغ ذلك بشر بن مروان قال لخالد بن يزيد ابن معاوية كيف ترى خالي طرد خالك وقال عمير\n(وأفلتنا ركضا حميد بن بحدل ... على سابح غوج اللبان مثابر)\n(ونحن جلبنا الخيل قبا شوازبا ... دقاق الهوادي داميات الدوابر)\n(إذا انتقصت من شأوه الخيل خلفه ... ترامى به فوق الرماح الشواجر)\n(تسائل عن حيي رفيدة بعدما ... قضت وطرا من عبد ود وعامر)\nقال شبل بن الخيتار\n(نجى الحسامية الكبداء مبترك ... من جريها وحثيث الشد مذعور)\n(من بعد ما التثق السربال طعنته ... كأنه بنجيع الورس ممكور)\n(ولى حميد ولم ينظر فوارسه ... قبل التقرة والمغرور مغرور)\n(فقد جزعت غداة الروع إذ لقحت ... أبطال قيس عليها البيض مشجور)\n(يهدي أوائلها سمح خلائقه ... ماضي العنان على الأعداء منصور)\n(يخرجن من برض الإكليل طالعة ... كأنهن جراد الحرة الزور)\nذكر زياد بن يزيد بن عمير بن الحباب عن أشياخ قومه قال أغار عمير بن الحباب على كلب فلقي جمعا لهم بالإكليل في ستمائة أو سبعمائة فقتل منهم فأكثر فقالت هند الجلاحية تحرض كلبا\n(ألا هل ثائر بدماء قوم ... أصابهم عمير بن الحباب !)\n(وهل في عامر يوما نكير ... وحيي عبد ود أو جناب !)\n(فإن لم يثأروا من قد أصابوا ... فكانوا أعبدا لبني كلاب)\n(أبعد بني الجلاح ومن تركتم ... بجانب كوكب تحت التراب)\n(تطيب لغائر منكم حياة ... ألا لا عيش للحي المصاب)\nاجتمعوا فقاتلهم عمير وأصاب فيهم ثم أغار فلقي جمعا منهم بالجوف فقتلهم ثم أغار عليهم بالسماوة فقتل منهم مقتلة عظيمة فقال عمير\n(ألا يا هند هند بني الجلاح ... سقيت الغيث من قلل السحاب)\n(ألما تخبري عنا بأنا ... نرد الكبش أعضب في تباب)\n(ألا يا هند لو عاينت يوما ... لقومك لامتنعت من الشراب)\n(غداة ندوسهم بالخيل حتى ... أباد القتل حي بني جناب)\n(ولو عطفت مواساة حميدا ... لغودر شلوه جزر الذئاب)\nذكر زياد بن يزيد بن عمير بن الحباب عن أشياخ قومه قال خرج عمير فأغار على قومه أيضا يوم الغوير فلما دنا من الغوير وصار بين حميد ودمشق دعا رجلا من بني نمير وقال له سر الآن حتى تأتي حميد بن بحدل فقل له أجب فإن قال من فقل صاحب عقد خرج قبل ذلك بيومين من دمشق فإن جاء معك فلا تهجه حتى تأتيني به فنكون نحن الذين نلي منه ما نريد أن نلي , فإنه إن ركب الحسامية لم يدرك فأتاه النميري فقال أجب\nفقال ومن قال فلان بن فلان صاحب العقد قال فركب ابن بحدل الحسامية ثم خرج يسير في أثر النميري حتى طلع النميري على عمير فقال النميري في نفسه أقتله أنا أحب إلي من أن يقتله عمير لقتله الحسام بن سالم فعطف عليه وولى حميد واتبعه عمير وأصحابه وترك العسكر وأمرهم عمير أن يميلوا إلى القوم فذلك حيث يقول لفرسه\n(أقدم صدام إنه ابن بحدل ... )","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":3,"spl":"شجاعة عمير بن الحباب يوم الغوير","tags":["الحب والغزل"],"loc":3944,"partial":1},
{"id":"b302-6","bab":"الجزء 24","sec":"شجاعة عمير بن الحباب يوم الغوير","page":"ج24 ص29","text":"استباح عسكر ابن بحدل وانصرف ثم أغار عليهم يوم دهمان كما ذكر عون بن حارثة بن عدي بن جبلة أحد بني زهير عن أبيه قال أغار عمير على كلب فأخذ الأموال وقتل الرجال وبلغ ابن بحدل مخرجه من الجزيرة فجمع له ثم خرج يعارضه حتى إذا دنا منهم بعث العين يأخذ لهم أثر القوم فأتاه العين فأخبره أن عميرا قد أتى دهمان فاستباح فيهم ثم خلف عسكره وخرج هو في طلب قوم قد سمع بهم فقال حميد لأصحابه تهيأوا للبيات وليكن شعاركم نحن عباد الله حقا حقا فبيتهم فقتل فيهم فأوجع وانقلب انقلب عمير حين أصبح إلى عسكره حتى إذا أشرف على عسكره رأى ما أنكره من كثرة السواد فقال لأصحابه إني أرى شيئا ما أعرفه وما هو بالذي خلفنا فلما رآهم ابن بحدل قال لأصحابه احملوا عليهم فقتل من الفريقين جميعا فقال ابن مخلاة\n(لقد طار في الآفاق أن ابن بحدل ... حميدا شفي كلبا فقرت عيونها)\nقال منذر بن حسان\n(وبادية الجواعر من نمير ... تنادي وهي سافرة النقاب)\n(تنادي بالجزيرة : يا لقيس ... وقيس بئس فتيان الضراب)\n(قتلنا منهم مائتين صبرا ... وألفا بالتلاع وبالروابي)\n(وأفلتنا هجين بني سليم ... يفدي المهر من حب الإياب)\n(فلولا الله والمهر المفدى ... لغودر وهو غربال الإهاب)\nثم سار عمير وجمع لهم أكثر مما كان تجمع فأغار عليهم فقتل منهم مقتلة واستاق الغنائم وسبى فلما سمعت كلب بإيقاعه تحملت من منازلها هاربة منه فلم يبق منهم أحد في موضع يقدر عمير على الغارة عليه إلا أن يخوض إليهم غيرهم من الأحياء ويخلف مدائن الشام خلف ظهره وصاروا جميعا إلى الغوير فقال عمير في ذلك\n(بشر بني القين بطعن شرج ... يشبع أولاد الضباع العرج)\n(ما زال إمراري لهم ونسجي ... وعقبتي للكور بعد السرج)\n(حتى اتقوني بالظهور الفلج ... هل أجزين يوما بيوم المرج)\n(ويوم دهمان ويوم هرج ... )\nقال رجل من نمير\n(أخذت نساء عبد الله قهرا ... وما أعفيت نسوة آل كلب)\n(صبحناهم بخيل مقربات ... وطعن لا كفاء له وضرب)\n(يبكين ابن عمرو وهو تسفي ... عليه الريح تربا بعد ترب)\n(وسعد قد دنا منه حمام ... بأسمر من رماح الخط صلب)\n(وقد قالت أمامة إذ رأتني : ... بليت وما لقيت لقاء صحب)\n(وقد فقدت معانقتي زمانا ... وشد المعصمين فوبق حقب)\n(لقد بدلت بعدي وجه سوء ... وآثارا بجلدك يا بن كعب)\n(فقلت لها كذلك من يلاقي ... عتاق الخيل تحمل كل صعب)\nقال المجير بن أسلم القشيري\n(أصبحت أم معمر عذلتني ... في ركوبي إلى منادي الصباح)\n(فدعيني أفيد قومك مجدا ... تندبيني به لدى الأنواح)\n(كل حي أذقت نعمى وبؤسى ... ببني عامر الطوال الرماح)\n(وصدمنا كلبا فبين قتيل ... أو سليب مشرد من جراح)\n(وأتونا بكل أجرد صاف ... ورجال معدة وسلاح)\nقال أيضا\n(أبلغ عامرا عني رسولا ... وأبلغ إن عرضت بني جناب)\n(هلم إلى جياد مضمرات ... وبيض لا تفل من الضراب)\n(وسمر في المهزة ذات لين ... نقيم بهن من صعر الرقاب)\n(إذا حشدت سليم حول بيتي ... وعامرها المركب في النصاب)\n(فمن هذا يقارب فخر قومي ... ومن هذا الذي يرجو اغتصابي ؟)\nقال زفر بن الحارث\n(يا كلب قد كلب الزمان عليكم ... وأصابكم مني عذاب مرسل)\n(أيهولنا يا كلب أصدق شدة ... يوم اللقاء أم الهويل الأول)\n(إن السماوة لا سماوة فالحقي ... بالغور فالأفحاص بئس الموئل)\n(فجنوب عكا فالسواحل إنها ... أرض تذوب بها اللقاح وتهزل)\n(أرض المذلة حيث عقت أمكم ... وأبوكم أو حيث مزع بحدل)\nقال عمير بن الحباب\n(وردن على الغوير غوير كلب ... كأن عيونها قلب انتزاح)\n(أقر العين مصرع عبد ود ... وما لاقت سراة بني الجلاح)\n(وقائمة تنادي يا لكلب ... وكلب بئس فتيان الصباح)\nقال عمير أيضا\n(وكلب تركنا جمعهم بين هارب ... حذار المنايا أو قتيل مجدل)\n(وأفلتنا لما التقينا بعاقد ... على سابح عند الجراء ابن بحدل)\n(وأقسم لو لاقيته لعلوته ... بأبيض قطاع الضريبة مقصل)\nوقال عمير أيضا\n(وكلبا تركناهم فلولا أذلة ... أدرنا عليهم مثل راغية البكر)\nقال جهم القشيري\n(يا كلب مهلا عن بني عامر ... فليس فيها الجد بالعاثر)\n(ولى حميد وهو في كربة ... على طويل متنه ضامر)\n(بالأم يفديها وقد شمرت ... كاللبوة الممطولة الكاسر)\n(هلا صبرتم للقنا ساعة ... ولم تكن بالماجد الصابر ؟)\nقال عمير\n(وأفلتنا ركضا حميد بن بحدل ... على سابح غوج اللبان مثابر)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":4,"spl":"شجاعة عمير بن الحباب يوم الغوير","tags":["الحب والغزل","الجواري والنساء"],"loc":3945,"partial":1},
{"id":"b302-7","bab":"الجزء 24","sec":"شجاعة عمير بن الحباب يوم الغوير","page":"ج24 ص29","text":"(إذا انتقصت من شأوه الخيل خلفه ... ترامى به فوق الرماح الشواجرا)\n(لدن غدوة حتى نزلنا عشية ... يمر كمريخ الغلام المخاطر)\nقال عمير\n(يا كلب لم تترك لكم أرماحنا ... بلوى السماوة فالغوير مرادا)\n(يا كلب أحرمنا السماوة فانظري ... غير السماوة في البلاد بلادا)\n(ولقد صككنا بالفوارس جمعكم ... وعديدكم يا كلب حتى بادا)\n(ولقد سبقت بوقعة تركتكم ... يا كلب بالحرب العوان بعادا)\nقال زفر بن الحارث\n(جزى الله خيرا كلما ذر شارق ... سعيدا ولاقته التحية والرحب)\n(وحلحله المغوار لله جده ... فلو لم ينله القتل بادت إذن كلب)\n(بني عبد ود لا نطالب ثأرنا ... من الناس بالسلطان إن شبت الحرب)\n(ولكن بيض الهند تسعر نارنا ... إذا ما خبت نار الأعادي فما تخبو)\n(أبادتكم فرسان قيس فما لكم ... عديد إذا عد الحصى لا ولا عقب)\n(بأيديهم بيض رقاق كأنها ... إذا ما انتضوها في أكفهم الشهب)\n(فسبوهم إن أنتم لم تطالبوا ... بثأركم قد ينفع الطالب السب)\n(وما امتنع الأقوام عنا بنأيهم ... سواء علينا النأي في الحرب والقرب)\nقال عمير\n(شفيت الغليل من قضاعة عنوة ... فظل لها يوم أغر محجل)\n(جزيناهم بالمرج يوما مشهرا ... فلاقوا صباحا ذا وبال وقتلوا)\n(فلم يبق إلا هارب من سيوفنا ... وإلا قتيل في مكر مجدل)\nقال ابن الصفار المحاربي\n(عظمت مصيبة تغلب ابنة وائل ... حتى رأت كلب مصيبتها سوى)\n(شمتوا وكان الله قد أخزاهم ... وتريد كلب أن يكون لها أسا)\n(وبكم بدأنا يال كلب قتلهم ... ولعلنا يوما نعود لكم عسى)\n(أخنت على كلب صدور رماحنا ... ما بين أقبلة الغوير إلى سوا)\n(وعركن بهراء بن عمرو عركة ... شفت الغليل ومسهم منا أذى)\nقال الراعي\n(متى نفترش يوما عليما بغارة ... يكونوا كعوص أو أذل وأضرعا)\n(وحي الجلاح قد تركنا بدارهم ... سواعد ملقاة وهاما مصرعا)\n(ونحن جدعنا أنف كلب ولم ندع ... لبهراء في ذكر من الناس مسمعا)\n(قتلنا لو ان القتل يشفي صدورنا ... بتدمر ألفا من قضاعة أقرعا)\nوقال زفر بن الحارث وذكر أبو عبيدة أنها لعقيل بن علفة\n(أقر العيون أن رهط ابن بحدل ... أذيقوا هوانا بالذي كان قدما)\n(صبحناهم البيض الرقاق ظباتها ... بجانب خبت والوشيج المقوما)\n(وجرداء ملتها الغزاة فكلها ... ترى قلقا تحت الرحالة أهضما)\n(بكل فتى لم تأبر النخل أمه ... ولم يدع يوما للغرائر معكما)\nهذه الحروب التي جرت ببنات قين فلما ألح عمير بالغارات على كلب رحلت حتى نزلت غوري الشام فلما صارت كلب بالموضع الذي صارت قيس انصرفت قيس في بعض ما كانت تنصرف من غزو كلب وهم مع عمير فنزلوا بثني من أثناء الفرات بين منازل بني تغلب وفي بني تغلب امرأة من تميم يقال لها أم دويل ناكحة في بني مالك بن جشم بن بكر وكان دويل من فرسان بني تغلب وكانت لها أعنز بمجنبة فأخذوا من أعنزها أخذها غلام من بني الحريش فشكوا ذلك إلى عمير فلم يشكهم\nوقال معرة الجند فلما رأى أصحابه أنه لم يقدعهم وثبوا على بقية أعنزها فأخذوها وأكلوها فلما أتاها دويل أخبرته بما لقيت فجمع جمعا ثم سار فأغار على بني الحريش فلقي جماعة منهم فقاتلوه فخرج رجل من بني الحريش زعمت تغلب أنه مات بعد\nذلك وأخذ ذودا لامرأة من بني الحريش يقال لها أم الهيثم فبلغ الأخطل الوقعة فلم يدر ما هي وقال وهو براذان\n(أتاني ودوني الزابيان كلاهما ... ودجلة أنباء أمر من الصبر)\n(أتاني بأن ابني نزار تهاديا ... وتغلب أولى بالوفاء وبالغدر)\nلما تبين الخبر قال\n(وجاؤوا بجمع ناصري أم هيثم ... فما رجعوا من ذودها ببعير)\nلما بلغ ذلك قيسا أغارت على بني تغلب بإزاء الخابور فقتلوا منهم","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":5,"spl":"شجاعة عمير بن الحباب يوم الغوير","tags":["المديح","الجواري والنساء"],"loc":3946},
{"id":"b302-8","bab":"الجزء 24","sec":"شجاعة عمير بن الحباب يوم الغوير","page":"ج24 ص29","text":"ثلاثة نفر واستاقوا خمسة وثلاثين بعيرا فخرجت جماعة من تغلب فأتوا زفر ابن الحارث وذكروا له القرابة والجوار وهم بقرقيسيا وقالوا ائتنا برحالنا ورد علينا نعمنا فقال أما النعم فنردها عليكم أو ما قدرنا لكم عليه ونكمل لكم نعمكم من نعمنا إن لم نصبها كلها وندي لكم القتلى قالوا له فدع لنا قريات الخابور ورحل قيسا عنها فإن هذه الحروب لن تطفأ ما داموا مجاورينا فأبى ذلك زفر وأبوا هم أن يرضوا إلا بذلك فناشدهم الله وألح عليهم فقال له رجل من النمر كان معهم والله ما يسرني أنه وقاني حرب قيس كلب أبقع تركته في غنمي اليوم وألح عليهم زفر يطلب إليهم ويناشدهم فأبوا فقال عمير لا عليك لا تكثر فوالله إني لأرى عيون قوم ما يريدون إلا محاربتك فانصرفوا من عنده ثم جمعوا جمعا وأغاروا على ما قرب من قرقيسيا من قرى القيسية فلقيهم عمير بن الحباب فكان النميري الذي تكلم عند زفر أول قتيل وهزم التغلبيين فأعظم ذلك الحيان جميعا قيس وتغلب وكرهوا الحرب وشماتة العدو فذكر سليمان بن عبد الله بن الأصم أن إياس بن الخراز أحد بني عتيبة بن سعد بن زهير وكان شريفا من عيون تغلب دخل قرقيسيا لينظر ويناظر زفر فيما كان بينهم فشد عليه يزيد بن بحزن القرشي فقتله فتذمم زفر من ذلك وكان كريما مجمعا لا يحب الفرقة فأرسل إلى الأمير ابن قرشة بن عمرو بن ربعي بن زفر بن عتيبة بن بعج بن عتيبة بن سعد بن زهير بن جشم بن الأرقم بن بكر بن حبيب بن عمرو بن غنم بن تغلب فقال له هل لك أن تسود بني نزار فتقبل مني الدية عن ابن\nعمك فأجابه إلى ذلك وكان قرشة من أشراف بني تغلب فتلافى زفر ما بين الحيين وأصلح بينهم وفي الصدور ما فيها فوفد عمير على المصعب بن الزبير فأعلمه أنه قد أولج قضاعة بمدائن الشام وأنه لم يبق إلا حي من ربيعة أكثرهم نصارى فسأله أن يوليه عليهم فقال اكتب إلى زفر فإن هو أراد ذلك وإلا ولاك فلما قدم على زفر\nذكر له ذلك فشق عليه ذلك وكره أن يليهم عمير فيحيف بهم ويكون ذلك داعية إلى منافرته فوجه إليهم قوما وأمرهم أن يرفقوا بهم فأتوا أخلاطا من بني تغلب من مشارق الخابور فأعلموهم الذي وجهوا به فأبوا عليهم فانصرفوا إلى زفر فردهم وأعلمهم أن المصعب كتب إليه بذلك ولا يجد بدا من أخذ ذلك منهم أو محاربتهم فقتلوا بعض الرسل\nوذكر ابن الأصم أن زفر لما أتاه ذلك اشتد عليه وكره استفساد بني تغلب فصار إليهم عمير بن الحباب فلقيهم قريبا من ماكسين على شاطىء الخابور بينه وبين قرقيسيا مسيرة يوم فأعظم فيها القتل\nوذكر زياد بن يزيد بن عمير بن الحباب أن القتل استحر ببني عتاب بن سعد والنمر وفيهم أخلاط تغلب ولكن هؤلاء معظم الناس فقتلوهم بها قتلا شديدا وكان زفر بن يزيد أخو الحارث بن جشم له عشرون ذكرا لصلبه وأصيب يومئذ أكثرهم وأسر القطامي الشاعر وأخذت إبله فأصاب عمير وأصحابه شيئا كثيرا من النعم ورئيس تغلب يومئذ عبد الله بن شريح بن مرة بن عبد الله بن عمرو بن كلثوم\nابن مالك بن عتاب بن سعد بن زهير بن جشم فقتل وقتل أخوه وقتل مجاشع بن الأجلح وعمرو بن معاوية من بني خالد بن كعب بن زهير وعبد الحارث بن عبد المسيح الأوسي وسعدان بن عبد يسوع بن حرب وسعد ود ابن أوس من بني جشم بن زهير وجعل عمير يصيح بهم ويلكم لا تستبقوا أحدا ونادى رجل من بني قشير يقال له الندار أنا جار لكل حامل أتتني فهي آمنة فأتته الحبالى فبلغني أن المرأة كانت تشد على بطنها الجفنة من تحت ثوبها تشبيها بالحبلى بما جعل لهن فلما اجتمعن له بقر بطونهن فأفظع ذلك زفر وأصحابه ولام زفر عميرا فيمن بقر من النساء فقال ما فعلته ولا أمرت به فقال في ذلك الصفار المحاربي\n(بقرنا منكم ألفي بقير ... فلم نترك لحاملة جنينا)\nوقال الأخطل يذكر ذلك\n(فليت الخيل قد وطئت قشيرا ... سنابكها وقد سطع الغبار)\n(فنجزيهم ببغيهم علينا ... بني لبنى بما فعل الغدار)\nقال الصفار\n(تمنيت بالخابور قيسا فصادفت ... منايا لأسباب وفاق على قدر)\nقال جرير\n(نبئت أنك بالخابور ممتنع ... ثم انفرجت انفراجا بعد إقرار)\nقال زفر بن الحارث يعاتب عميرا بما كان منه في الخابور\n(ألا من مبلغ عني عميرا ... رسالة عاتب وعليك زاري)\n(أتترك حي ذي كلع وكلب ... وتجعل حد نابك في نزار)\n(كمعتمد على إحدى يديه ... فخانته بوهي وانكسار)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":6,"spl":"شجاعة عمير بن الحباب يوم الغوير","tags":["الحب والغزل"],"loc":3947},
{"id":"b302-9","bab":"الجزء 24","sec":"زفر يخلي سبيل القطامي والقطامي يمدحه","page":"ج24 ص44","text":"ولما أسر القطامي أتى زفر بقرقيسيا فخلى سبيله ورد عليه مائة ناقة كما ذكر أدهم بن عمران العبدي فقال القطامي يمدحه\n(قفي قبل التفرق يا ضباعا ... ولا يك موقف منك الوداعا)\n(قفي فادي أسيرك إن قومي ... وقومك لا أرى لهم اجتماعا)\n(ألم يحزنك أن حبال قيس ... وتغلب قد تباينت انقطاعا)\n(فصارا ما تغبهما أمور ... تزيد سنا حريقتها ارتفاعا)\n(كما العظم الكسير يهاض حتى ... يبت وإنما بدأ انصداعا)\n(فأصبح سيل ذلك قد ترقى ... إلى من كان منزله يفاعا)\n(فلا تبعد دماء ابني نزار ... ولا تقرر عيونك يا قضاعا)\n(ومن يكن استلام إلى ثوي ... فقد أحسنت يا زفر المتاعا)\n(أكفرا بعد رد الموت عني ... وبعد عطائك المائة الرتاعا)\n(فلو بيدي سواك غداة زلت ... بي القدمان لم أرج اطلاعا)\n(إذن لهلكت لو كانت صغار ... من الأخلاق تبتع ابتداعا)\n(فلم أر منعمين أقل منا ... وأكرم عندما اصطنعوا اصطناعا)\n(من البيض الوجوه بني نفيل ... أبت أخلاقهم إلا اتساعا)\n(بني القرم الذي علمت معد ... تفضل قومها سعة وباعا)\nوقال أيضا\n(يا زفر بن الحارث ابن الأكرم ... قد كنت في الحرب قديم المقدم)\n(إذ أحجم القوم ولما تحجم ... إنك وابنيك حفظتم محرمي)\n(وحقن الله بكفيك دمي ... من بعد ما جف لساني وفمي)\n(أنقذتني من بطل معمم ... والخيل تحت العارض المسوم)\n(وتغلب يدعون : يا للأرقم ... )\nقال أيضا\n(يا ناق خبي خببا زورا ... وقلبي منسمك المغبرا)\n(وعارضي الليل إذا ما اخضرا ... سوف تلاقين جوادا حرا)\n(سيد قيس زفر الأغرا ... ذاك الذي بايع ثم برا)\n(ونقض الأقوام واستمرا ... قد نفع الله به وضرا)\n(وكان في الحرب شهابا مرا ... )\nقال أيضا\n(كأن في المركب حين راحا ... بدرا يزيد البصر انفضاحا)\n(ذا بلج ساواك أنى امتاحا ... وقر عينا ورجا الرباحا)\n(ألا ترى ما غشي الأركاحا ... وغشي الخابور والأملاحا)\n(يصفقون بالأكف الراحا ... )\nوقال فيه أيضا هذه القصيدة التي فيها الغناء المذكور بذكر أخبار القطامي\n(ما اعتاد حب سليمى حين معتاد ... ولا تقضى بواقي دينها الطادي)\n(بيضاء محطوطة المتنين بهكنة ... ريا الروادف لم تمغل بأولاد)\n(ما للكواعب ودعن الحياة كما ... ودعنني واتخذن الشيب ميعادي)\n(أبصارهن إلى الشبان مائلة ... وقد أراهن عني غير صداد)\n(إذ باطلي لم تقشع جاهليته ... عني ولم يترك الخلان تقوادي)\n(كنية الحي من ذي القيضة احتملوا ... مستحقين فؤادا ماله فادي)\n(بانوا وكانوا حياتي في اجتماعهم ... وفي تفرقهم قتلي وإقصادي)\n(يقتلننا بحديث ليس يعلمه ... من يتقين ولا مكنونه بادي)\n(فهن ينبذن من قول يصبن به ... مواقع الماء من ذي الغلة الصادي)\nقول فيها في مدح زفر بن الحارث\n(من مبلغ زفر القيسي مدحته ... من القطامي قولا غير إفناد)\n(إني وإن كان قومي ليس بينهم ... وبين قومك إلا ضربة الهادي)\n(مثن عليك بما استبقيت معرفتي ... وقد تعرض مني مقتل بادي)\n(فلن أثيبك بالنعماء مشتمة ... ولن أبدل إحسانا بإفساد)\n(فإن هجوتك ما تمت مكارمتي ... وإن مدحت فقد أحسنت إصفادي)\n(وما نسيت مقام الورد تحبسه ... بيني وبين حفيف الغابة الغادي)\n(لولا كتائب من عمرو تصول بها ... أرديت يا خير من يندو له النادي)\n(إذ لا ترى العين إلا كل سلهبة ... وسابح مثل سيد الردهة العادي)\n(إذ الفوارس من قيس بشكتهم ... حولي شهود وما قومي بشهادي)\n(إذ يعتريك رجال يسألون دمي ... ولو أطعتهم أبكيت عوادي)\n(فقد عصيتهم والحرب مقبلة ... لا بل قدحت زنادا غير صلاد)\n(والصيد آل نفيل خير قومهم ... عند الشتاء إذا ما ضن بالزاد)\n(المانعون غداة الروع جارهم ... بالمشرفية من ماض ومنآد)\n(أيام قومي مكاني منصب لهم ... ولا يظنون إلا أنني رادي)\n(فانتاشني لك من غماء مظلمة ... حبل تضمن إصداري وإيرادي)\n(ولا كردك مالي بعدما كربت ... تبدي الشماتة أعدائي وحسادي)\n(فإن قدرت على خير جزيت به ... والله يجعل أقواما بمرصاد)\nال ابن سلام فلما سمع زفر هذا قال لا أقدرك الله على ذلك وقال أيضا\n(ألا من مبلغ زفر بن عمرو ... وخير القول ما نطق الحكيم)\n(أبي ما يقاد الدهر قسرا ... ولا لهوى المصرف يستقيم)\n(أنوف حين يغضب مستعز ... جنوح يستبد به العزيم)\n(فما آل الحباب إلى نفيل ... إذا عد الممهل والقديم)\n(كأن أبا الحباب إلى نفيل ... حمار عضه فرس عذوم)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":7,"spl":"زفر يخلي سبيل القطامي والقطامي يمدحه","tags":["الحب والغزل"],"loc":3948,"partial":1},
{"id":"b302-10","bab":"الجزء 24","sec":"زفر يخلي سبيل القطامي والقطامي يمدحه","page":"ج24 ص44","text":"(بني لك عامر وبنو كلاب ... أروما ما يوازيه أروم)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":8,"spl":"زفر يخلي سبيل القطامي والقطامي يمدحه","tags":[],"loc":3949},
{"id":"b302-11","bab":"الجزء 24","sec":"القطامي ممن يحسنون ابتداء القصيد","page":"ج24 ص48","text":"أخبرني أحمد بن جعفر جحظة قال حدثني علي بن يحيى المنجم قال سمعت من لا أحصي من الرواة يقولون أحسن الناس ابتداء قصيد في الجاهلية امرؤ القيس حيث يقول\n(ألا عم صباحا أيها الطلل البالي ... )\nحيث يقول\n(قفا نبك من ذكرى حبيب ومنزل ... )\nفي الإسلاميين القطامي حيث يقول\n(إنا محيوك فاسلم أيها الطلل ... )\nوفي المحدثين بشار حيث يقول\n(أبى طلل بالجزع أن يتكلما ... وماذا عليه لو أجاب متيما ؟)\n(وبالفرع آثار لهند وباللوى ... ملاعب ما يعرفن إلا توهما)\nسخت من كتاب أحمد بن الحارث الخراز ولم أسمعه من أحد وهو خبر فيه طول اقتصرت منه على ما فيه من خبر القطامي قال أحمد بن الحارث الخراز حدثني المدائني عن عبد الملك بن مسلم قال قال عبد الملك بن مروان للأخطل وعنده عامر الشعبي أتحب أن لك قياضا بشعرك شعر أحد من العرب أم تحب أنك قلته قال لا والله يا أمير المؤمنين إلا أني وددت أني كنت قلت أبياتا قالها رجل منا مغدف القناع قليل السماع قصير الذراع قال وما قال فأنشد قول القطامي\n(إنا محيوك فاسلم أيها الطلل ... وإن بليت وإن طالت بك الطيل)\n(ليس الجديد به تبقى بشاشته ... إلا قليلا ولا ذو خلة يصل)\n(والعيش لا عيش إلا ما تقر به ... عين ولا حال إلا سوف تنتقل)\n(إن ترجعي من أبي عثمان منجحة ... فقد يهون على المستنجح العمل)\n(والناس من يلق خيرا قائلون له ... ما يشتهي ولأم المخطىء الهبل)\n(قد يدرك المتأني بعض حاجته ... وقد يكون مع المستعجل الزلل)\nتى أتى على آخرها قال الشعبي فقلت له قد قال القطامي أفضل من هذا قال وما قال قلت قال\n(طرقت جنوب رحالنا من مطرق ... ما كنت أحسبها قريب المعنق)\n(قطعت إليك بمثل حيد جداية ... حسن معلق تومتيه مطوق)\n(ومصرعين من الكلال كأنما ... بكروا الغبوق من الرحيق المعتق)\n(متوسدين ذراع كل شملة ... ومفرج عرق المقذ منوق)\n(وجثت على ركب تهد بها الصفا ... وعلى كلاكل كالنقيل المطرق)\n(وإذا سمعن إلى هماهم رفقة ... ومن النجوم غوابر لم تخفق)\n(جعلت تميل خدودها آذانها ... طربا بهن إلى حداء السوق)\n(كالمنصتات إلى الزمير سمعنه ... من رائع لقلوبهن مشوق)\n(فإذا نظرن إلى الطريق رأينه ... لهقا كشاكلة الحصان الأبلق)\n(وإذا تخلف بعدهن لحاجة ... حاد يشسع نعله لم يلحق)\n(وإذا يصيبك - والحوادث جمة - ... حدث حداك إلى أخيك الأوثق)\n(ليت الهموم عن الفؤاد تفرجت ... وخلا التكلم للسان المطلق)\nال فقال عبد الملك بن مروان ثكلت القطامي أمه هذا والله الشعر قال فالتفت إلي الأخطل فقال لي يا شعبي إن لك فنونا في الأحاديث وإنما لنا فن واحد فإن رأيت ألا تحملني على أكتاف قومك فأدعهم حربى فقلت وكرامة لا أعرض لك في شعر أبدا فأقلني هذه المرة ثم التفت إلى عبد الملك بن مروان فقلت يا أمير المؤمنين أسألك أن تستغفر لي الأخطل فإني لا أعاود ما يكره فضحك عبد الملك بن مروان\nوقال يا أخطل إن الشعبي في جواري فقال يا أمير المؤمنين قد بدأته بالتحذير وإذا ترك ما نكره لم نعرض له إلا بما يحب فقال عبد الملك بن مروان للأخطل فعلي ألا يعرض لك إلا بما تحب أبدا فقال له الأخطل أنت تتكفل بذلك يا أمير المؤمنين قال عبد الملك بن مروان أنا أكفل به إن شاء الله تعالى\n(يا بن الذين سما كسرى لجمعهم ... فجللوا وجهه قارا بذي قار)\n(دوخ خراسان بالجرد العتاق وبالبيض ... الرقاق بأيدي كل مسعار)\nلشعر لأبي نجدة واسمه لجيم بن سعد شاعر من بني عجل أخبرني بذلك جماعة من أهله وكان أبو نجدة هذا مع أحمد بن عبد العزيز بن دلف بن أبي دلف منقطعا إليه والغناء لكنيز دبة ولحنه فيه خفيف بالبنصر ابتداؤه نشيد وكان سبب قوله هذا الشعر أن قائدا من قواد أحمد بن عبد العزيز التجأ إلى عمرو بن الليث وهو يومئذ بخراسان فغم ذلك أحمد وأقلقه فدخل عليه أبو نجدة فأنشده هذين البيتين وبعدهما\n(يا من تيمم عمرا يستجير به ... أما سمعت ببيت فيه سيار)\n(المستجير بعمرو عند كربته ... كالمستجير من الرمضاء بالنار)\nسر أحمد بذلك وسري عنه وأمر لأبي نجدة بجائزة وخلع عليه وحمله وغنى فيه كنيز لحنه هذا وهو لحن حسن مشهور في عصرنا هذا فأمر\nلكنيز أيضا بجائزة وخلع عليه وحمله سمعت أبا علي محمد بن المرزبان يحدث أبي رحمه الله بهذا على سبيل المذاكرة وكانت بيننا وبين آل المرزبان مودة قديمة وصهر","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":9,"spl":"القطامي ممن يحسنون ابتداء القصيد","tags":[],"song":1,"loc":3950,"partialRef":{"sid":"b113-8","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b302-12","bab":"الجزء 24","sec":"خبر وقعة ذي قار التي فخر بها في هذا الشعر","page":"ج24 ص54","text":"أخبرنا بخبرها علي بن سليمان الأخفش عن السكري عن محمد ابن حبيب عن ابن الكلبي عن خراش بن إسماعيل وأضفت إلى ذلك رواية الأثرم عن أبي عبيدة\nوعن هشام أيضا عن أبيه قالوا كان من حديث ذي قار أن كسرى أبرويز بن هرمز لما غضب على النعمان ابن المنذر أتى النعمان هانىء بن مسعود بن عامر بن عمرو بن ربيعة بن ذهل ابن شيبان فاستودعه ماله وأهله وولده وألف شكة ويقال أربعة آلاف شكة قال ابن الأعرابي والشكة السلاح كله ووضع وضائع عند أحياء من العرب ثم هرب وأتى طيئا لصهره فيهم\nوكانت عنده فرعة بنت سعيد بن حارثة بن لأم وزينب بنت أوس بن حارثة فأبوا أن يدخلوه جبلهم وأتته بنو رواحة بن ربيعة بن عبس فقالوا له أبيت اللعن أقم عندنا فإنا مانعوك مما نمنع منه أنفسنا فقال ما أحب أن تهلكوا بسببي فجزيتم خيرا ثم خرج حتى وضع يده في يد كسرى فحبسه بساباط ويقال بخانقين وقد مضى خبره مشروحا في أخبار عدي بن زيد قالوا فلما هلك النعمان جعلت بكر بن وائل تغير على السواد فوفد قيس بن\nمسعود بن قيس بن خالد ذي الجدين بن عبد الله بن عمرو إلى كسرى فسأله أن يجعل له أكلا وطعمة على أن يضمن له على بكر بن وائل ألا يدخلوا السواد ولا يفسدوا فيه فأقطعه الأبلة وما والاها وقال هل تكفيك وتكفي أعراب قومك وكانت له حجرة فيها مائة من الإبل للأضياف إذا نحرت ناقة ردت مكانها ناقة أخرى وإياه عنى الشماخ بقوله\n(فادفع بألبانها عنكم كما دفعت ... عنهم لقاح بني قيس بن مسعود)\nال فكان يأتيه من أتاه منهم فيعطيه جلة تمر وكرباسة حتى قدم الحارث بن وعلة بن مجالد بن يثربي بن الديان بن الحارث بن مالك بن شيبان\nابن ذهل بن ثعلبة والمكسر بن حنظلة بن حيي بن ثعلبة بن سيار بن حيي بن حاطبة بن الأسعد بن جذيمة بن سعد بن عجل بن لجيم فأعطاهما جلتي تمر وكرباستين فغضبا وأبيا أن يقبلا ذلك منه فخرجا واستغويا ناسا من بكر بن وائل ثم أغارا على السواد فأغار الحارث على أسافل رودميسان وهي من جرد وأغار المكسر على الأنبار فلقيه رجل من العباديين من أهل الحيرة قد نتجت بعض نوقهم فحملوا الحوار على ناقة وصروا الإبل فقال العبادي لقد صبح الأنبار شر جمل يحمل جملا وجمل برته عود فجعلوا يضحكون من جهله بالإبل قال وأغار بجير بن عائذ بن سويد العجلي ومعه مفروق بن عمرو\nالشيباني على القادسية وطيرناباذ وما والاهما وكلهم ملأ يديه غنيمة فأما مفروق وأصحابه فوقع فيهم الطاعون فموت منهم خمسة نفر مع من موت من أصحابهم فدفنوا بالدجيل وهو رحلة من العذيب يسيرة فقال مفروق\n(أتاني بأنباط السواد يسوقهم ... إلي وأودت رجلتي وفوارسي)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":10,"spl":"خبر وقعة ذي قار التي فخر بها في هذا الشعر","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"loc":3951},
{"id":"b302-13","bab":"الجزء 24","sec":"كسرى وقيس بن مسعود","page":"ج24 ص58","text":"فلما بلغ ذلك كسرى اشتد حنقه على بكر بن وائل وبلغه أن حلقة النعمان وولده وأهله عندهم فأرسل كسرى إلى قيس بن مسعود وهو بالأبلة فقال غررتني من قومك وزعمت أنك تكفينيهم وأمر به فحبس بساباط وأخذ كسرى في تعبئة الجيوش إليهم فقال قيس بن مسعود وهو محبوس من أبيات\n(ألا أبلغ بني ذهل رسولا ... فمن هذا يكون لكم مكاني)\n(أيأكلها ابن وعلة في ظليف ... ويأمن هيثم وابنا سنان ؟)\n(ويأمن فيكم الذهلي بعدي ... وقد وسموكم سمة البيان)\n(ألا من مبلغ قومي ومن ذا ... يبلغ عن أسير في الإوان)\nعني الإيوان\n(تطاول ليله وأصاب حزنا ... ولا يرجو الفكاك مع المنان)\nعني بالهيثم وابني سنان الهيثم بن جرير بن يساف بن ثعلبة بن سدوس بن ذهل بن ثعلبة وأبو علباء بن الهيثم وقال قيس بن مسعود ينذر قومه\n(ألا ليتني أرشو سلاحي وبغلتي ... لمن يخبر الأنباء بكر بن وائل)\nيروي لمن يعلم الأنباء\n(فأوصيهم بالله والصلح بينهم ... لينصأ معروف ويزجر جاهل)\n(وصاة امرىء لو كان فيكم أعانكم ... على الدهر والأيام فيها الغوائل)\n(فإياكم والطف لا تقربنه ... ولا البحر إن الماء للبحر واصل)\n(ولا أحبسنكم عن بغا الخير إنني ... سقطت على ضرغامة فهو آكل)\nواه ابن الأعرابي فقال\nي أنه معين لهم يقود الخيل إليكم\nقال وقال قيس أيضا ينذرهم\n(تمناك من ليلى مع الليل خائل ... وذكر لها في القلب ليس يزايل)\n(أحبك حب الخمر ما كان حبها ... إلي وكل في فؤادي داخل)\n(ألا ليتني أرشو سلاحي وبغلتي ... فيخبر قومي اليوم ما أنا قائل)\n(فإنا ثوينا في شعوب وإنهم ... غزتهم جنود جمة وقبائل)\n(وإن جنود العجم بيني وبينكم ... فيا فلجي يا قوم إن لم تقاتلوا)\nال فلما وضح لكسرى واستبان أن مال النعمان وحلقته وولده عند ابن مسعود بعث إليه كسرى رجلا يخبره أنه قال له إن النعمان إنما كان عاملي وقد استودعك ماله وأهله والحلقة فابعث بها إلي ولا تكلفني أن أبعث إليك ولا إلى قومك بالجنود تقتل المقاتلة وتسبي الذرية فبعث إليه هانىء إن الذي بلغك باطل وما عندي قليل ولا كثير وإن يكن الأمر كما\nقيل فإنما أنا أحد رجلين إما رجل استودع أمانة فهو حقيق أن يردها على من استودعه إياها ولن يسلم الحر أمانته أو رجل مكذوب عليه فليس ينبغي للملك أن يأخذه بقول عدو أو حاسد\nقال وكانت الأعاجم قوما لهم حلم قد سمعوا ببعض علم العرب وعرفوا أن هذا الأمر كائن فيهم فلما ورد عليه كتاب هانىء بهذا حملته الشفقة أن يكون ذلك قد اقترب فأقبل حتى قطع الفرات فنزل غمر بني مقاتل وقد أحنقه ما صنعت بكر بن وائل في السواد ومنع هانىء إياه ما منعه","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":11,"spl":"كسرى وقيس بن مسعود","tags":["الوصف والطبيعة"],"loc":3952},
{"id":"b302-14","bab":"الجزء 24","sec":"كسرى يستشير إياس بن قبيصة","page":"ج24 ص60","text":"قال ودعا كسرى إياس بن قبيصة الطائي وكان عامله على عين\nالتمر وما والاها إلى الحيرة وكان كسرى قد أطعمه ثلاثين قرية على شاطىء الفرات فأتاه في صنائعه من العرب الذين كانوا بالحيرة فاستشاره في الغارة على بكر بن وائل\nوقال ماذا ترى وكم ترى أن نغزيهم من الناس فقال له إياس إن الملك لا يصلح أن يعصيه أحد من رعيته وإن تطعني لم تعلم أحدا لأي شيء عبرت وقطعت الفرات فيروا أن شيئا من أمر العرب قد كربك ولكن ترجع وتضرب عنهم وتبعث عليهم العيون حتى ترى غرة منهم ثم ترسل حلبة من العجم فيها بعض القبائل التي تليهم فيوقعون بهم وقعة الدهر ويأتونك بطلبتك فقال له كسرى أنت رجل من العرب وبكر بن وائل أخوالك وكانت أم إياس أمامة بنت مسعود أخت هانىء بن مسعود فأنت تتعصب لهم ولا تألوهم نصحا فقال إياس رأي الملك أفضل فقام إليه عمرو بن عدي بن زيد العبادي وكان كاتبه وترجمانه بالعربية في أمور العرب فقال له أقم أيها الملك وابعث إليهم بالجنود يكفوك فقام إليه النعمان بن زرعة بن هرمي من ولد السفاح التغلبي فقال أيها الملك إن هذا الحي من بكر بن وائل إذا قاظوا بذي قار تهافتوا تهافت الجراد في النار فعقد للنعمان ابن زرعة على تغلب والنمر وعقد لخالد بن يزيد البهراني على قضاعة وإياد\nوعقد لإياس بن قبيصة على جميع العرب ومعه كتيبتاه الشهباء والدوسر فكانت العرب ثلاثة آلاف وعقد للهامرز على ألف من الأساورة وعقد لخنابرين على ألف وبعث معهم باللطيمة وهي عير كانت تخرج من العراق فيها البز والعطر والألطاف توصل إلى باذام عامله باليمن\nوقال إذا فرغتم من عدوكم فسيروا بها إلى اليمن وأمر عمرو بن عدي أن يسير بها وكانت العرب تخفرهم وتجيرهم حتى تبلغ اللطيمة اليمن وعهد كسرى إليهم إذا شارفوا بلاد بكر بن وائل ودنوا منها أن يبعثوا إليهم النعمان بن زرعة فإن أتوكم بالحلقة ومائة غلام منهم يكونون رهنا بما أحدث سفهاؤهم فاقبلوا منهم وإلا فقاتلوهم وكان كسرى قد أوقع قبل ذلك ببني تميم يوم الصفقة فالعرب وجلة خائفة منه وكانت حرقة بنت حسان بن النعمان بن المنذر يومئذ في بني سنان هكذا في هذه الرواية وقال ابن الكلبي حرقة بنت النعمان وهي هند والحرقة لقب\nوهذا هو الصحيح فقالت تنذرهم\n(ألا أبلغ بني بكر رسولا ... فقد جد النفير بعنقفير)\n(فليت الجيش كلهم فداكم ... ونفسي والسرير وذا السرير)\n(كأني حين جد بهم إليكم ... معلقة الذوائب بالعبور)\n(فلو أني أطقت لذاك دفعا ... إذن لدفعته بدمي وزيري)\nلما بلغ بكر بن وائل الخبر سار هانىء بن مسعود حتى انتهى إلى ذي قار فنزل به وأقبل النعمان بن زرعة وكانت أمه قلطف بنت النعمان بن معد يكرب التغلبي وأمها الشقيقة بنت الحارث الوصاف العجلي حتى نزل على ابن أخته مرة بن عمرو بن عبد الله بن معاوية بن عبد الله بن قيس بن سعد بن عجل فحمد الله النعمان وأثنى عليه ثم\nقال إنكم أخوالي وأحد طرفي وإن الرائد لا يكذب أهله وقد أتاكم ما لا قبل لكم به من أحرار فارس وفرسان العرب والكتيبتان الشهباء والدوسر وإن في هذا الشر خيارا ولأن يفتدي بعضكم بعضا خير من أن تصطلموا فانظروا هذه الحلقة فادفعوها وادفعوا رهنا من أبنائكم إليه بما أحدث سفهاؤكم فقال له\nالقوم ننظر في أمرنا وبعثوا إلى من يليهم من بكر بن وائل وبرزوا ببطحاء ذي قار بين الجلهتين قال الأثرم جلهة الوادي ما استقبلك منه واتسع لك وقال ابن الأعرابي جلهة الوادي مقدمه مثل جلهة الرأس إذا ذهب شعره يقال رأس أجله قال وكان مرداس بن أبي عامر السلمي مجاورا فيهم يومئذ فلما رأى الجيوش قد أقبلت إليهم حمل عياله فخرج عنهم وأنشأ يقول يحرضهم بقوله\n(أبلغ سراة بني بكر مغلغلة ... إني أخاف عليهم سربة الدار)\n(إني أرى الملك الهامرز منصلتا ... يزجي جيادا وركبا غير أبرار)\n(لا تلقط البعر الحولي نسوتهم ... للجائزين على أعطان ذي قار)\n(فإن أبيتم فإني رافع ظعني ... ومنشب في جبال اللوب أظفاري)\n(وجاعل بيننا وردا غواربه ... ترمي إذا ما ربا الوادي بتيار)\nبا ارتفع وطال وقوله وردا غواربه أراد البحر","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":12,"spl":"كسرى يستشير إياس بن قبيصة","tags":["المديح","الجواري والنساء"],"loc":3953},
{"id":"b302-15","bab":"الجزء 24","sec":"أبو الفرج يعطي رأيه في حكاية مرداس","page":"ج24 ص64","text":"قال علي بن الحسين الأصفهاني هذه الحكاية عندي في أمر مرداس بن أبي عامر خطأ لأن وقعة ذي قار\nكانت بعد هجرة النبي وكانت بين بدر وأحد ومرداس بن أبي عامر وحرب بن أمية أبو أبي سفيان ماتا في وقت واحد كانا مرا بالقرية وهي غيضة ملتفة الشجر فأحرقا شجرها ليتخذاها مزرعة فكانت تخرج من الغيضة حيات بيض فتطير حتى تغيب ومات حرب ومرداس بعقب ذلك فتحدث قومهما أن الجن قتلتهما لإحراقهما منازلهم من الغيضة وذلك قبل مبعث النبي بحين ثم كانت بين أبي سفيان وبين العباس بن مرداس منازعة في هذه القرية ولهما في ذلك خبر ليس هذا موضعه وأظن أن هذه الأبيات للعباس بن مرداس بن أبي عامر رجع الحديث إلى سياقته في حديث ذي قار قال وجعلت بكر بن وائل حين بعثوا إلى من حولهم من قبائل بكر لا ترفع\nلهم جماعة إلا قالوا سيدنا في هذه فرفعت لهم جماعة فقالوا سيدنا في هذه فلما دنوا إذا هم بعبد عمرو بن بشر بن مرثد فقالوا لا ثم رفعت لهم أخرى فقالوا في هذه سيدنا فإذا هو جبلة بن باعث بن صريم اليشكري فقالوا لا فرفعت أخرى فقالوا في هذه سيدنا فإذا هو الحارث بن وعلة ابن مجالد الذهلي فقالوا لا ثم رفعت لهم أخرى فقالوا في هذه سيدنا فإذا فيها الحارث بن ربيعة بن عثمان التيمي من تيم الله فقالوا لا ثم رفعت لهم أخرى أكبر مما كان يجيء فقالوا لقد جاء سيدنا فإذا رجل أصلع الشعر عظيم البطن مشرب حمرة فإذا هو حنظلة بن ثعلبة بن سيار بن حيي ابن حاطبة بن الأسعد بن جذيمة بن سعد بن عجل فقالوا يا أبا معدان قد طال انتظارنا وقد كرهنا أن نقطع أمرا دونك وهذا ابن أختك النعمان بن زرعة قد جاءنا والرائد لا يكذب أهله\nقال فما الذي أجمع عليه رأيكم واتفق عليه ملؤكم قالوا قال إن اللخي أهون من الوهي وإن في الشر خيارا ولأن يفتدي بعضكم بعضا خير من أن تصطلحوا جميعا\nقال حنظلة فقبح الله هذا رأيا لا تجر أحرار فارس غرلها ببطحاء ذي قار وأنا أسمع الصوت ثم أمر بقبته فضربت بوادي ذي قار ثم نزل ونزل الناس فأطافوا به ثم\nقال لهانىء بن مسعود يا أبا أمامة إن ذمتكم ذمتنا عامة وإنه لن يوصل إليك حتى تفنى أرواحنا فأخرج هذه الحلقة ففرقها بين قومك فإن تظفر فسترد عليك وإن تهلك فأهون مفقود فأمر بها فأخرجت ففرقها بينهم ثم قال حنظلة للنعمان لولا أنك\nرسول لما أبت إلى قومك سالما فرجع النعمان إلى أصحابه فأخبرهم بما رد عليه القوم فباتوا ليلتهم مستعدين للقتال وباتت بكر بن وائل يتأهبون للحرب فلما أصبحوا أقبلت الأعاجم نحوهم وأمر حنظلة بالظعن جميعا فوقفها خلف الناس ثم\nقال يا معشر بكر بن وائل قاتلوا عن ظعنكم أو دعوا فأقبلت الأعاجم يسيرون على تعبئة فلما رأتهم بنو قيس بن ثعلبة انصرفوا فلحقوا بالحي فاستخفوا فيه فسمي حي بني قيس بن ثعلبة\nقال وهو على موضع خفي فلم يشهدوا ذلك اليوم وكان ربيعة بن غزالة السكوني ثم التجيبي يومئذ هو وقومه نزولا في بني شيبان فقال يا بني شيبان أما لو أني كنت منكم لأشرت عليكم برأي مثل عروة العكم فقالوا فأنت والله من أوسطنا فأشر علينا فقال لا تستهدفوا لهذه الأعاجم فتهلككم بنشابها ولكن تكردسوا لهم كراديس فيشد عليهم كردوس فإذا أقبلوا عليه شد الآخر فقالوا فإنك قد رأيت رأيا ففعلوا فلما التقى الزحفان وتقارب القوم قام حنظلة بن ثعلبة فقال يا معشر بكر بن وائل إن النشاب الذي مع الأعاجم يعرفكم فإذا\nأرسلوه لم يخطئكم فعاجلوهم باللقاء وابدأوهم بالشدة ثم قام هانىء بن مسعود فقال يا قوم مهلك معذور خير من نجاء معرور وإن الحذر لا يدفع القدر وإن الصبر من أسباب الظفر المنية ولا الدنية واستقبال الموت خير من استدباره والطعن في الثغر خير وأكرم من الطعن في الدبر يا قوم جدوا فما من الموت بد فتح لو كان له رجال أسمع صوتا ولا أرى قوما يا آل بكر شدوا واستعدوا وإلا تشدوا تردوا ثم قام شريك بن عمرو بن شراحيل بن مرة بن همام فقال يا قوم إنما تهابونهم أنكم ترونهم عند الحفاظ أكثر منكم وكذلك أنتم في أعينهم فعليكم بالصبر فإن الأسنة تردي الأعنة يا آل بكر قدما قدما ثم قام عمرو بن جبلة بن باعث بن صريم اليشكري فقال\n(يا قوم لا تغرركم هذي الخرق ... ولا وميض البيض في الشمس برق)\n(من لم يقاتل منكم هذي العنق ... فجنبوه الراح واسقوه المرق)","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":13,"spl":"أبو الفرج يعطي رأيه في حكاية مرداس","tags":["اللهو والمزاح"],"loc":3954},
{"id":"b302-16","bab":"الجزء 24","sec":"أبو الفرج يعطي رأيه في حكاية مرداس","page":"ج24 ص64","text":"م قام حنظلة بن ثعلبة إلى وضين راحلة امرأته فقطعه ثم تتبع الظعن يقطع وضنهن لئلا يفر عنهن الرجال فسمي يومئذ مقطع الوضين والوضين بطان الناقة قالوا وكانت بنو عجل في الميمنة بإزاء خنابرين وكانت بنو شيبان في الميسرة بإزاء كتيبة الهامرز وكانت أفناء بكر بن وائل في القلب فخرج\nأسوار من الأعاجم مسور في أذنيه درتان من كتيبة الهامرز يتحدى الناس للبراز فنادى في بني شيبان فلم يبرز له أحد حتى إذا دنا من بني يشكر برز له يزيد بن حارثة أخو بني ثعلبة بن عمرو فشد عليه بالرمح فطعنه فدق صلبه وأخذ حليته وسلاحه فذلك قول سويد بن أبي كاهل يفتخر\n(ومنا يزيد إذ تحدى جموعكم ... فلم تقربوه المرزبان المسهر)\n(وبارزه منا غلام بصارم ... حسام إذا لاقى الضريبة يبتر)\nم إن القوم اقتتلوا صدر نهارهم أشد قتال رآه الناس إلى أن زالت الشمس فشد الحوفزان واسمه الحارث ابن شريك على الهامرز فقتله وقتلت بنو عجل خنابرين وضرب الله وجوه الفرس فانهزموا وتبعتهم بكر ابن وائل فلحق مرثد بن الحارث بن ثور بن حرملة بن علقمة بن عمرو بن سدوس النعمان بن زرعة فأهوى له طعنا فسبقه النعمان بصدر فرسه فأفلته فقال مرثد في ذلك\n(وخيل تبارى للطعان شهدتها ... فأغرقت فيها الرمح والجمع محجم)\n(وأفلتني النعمان قاب رماحنا ... وفوق قطاة المهر أزرق لهذم)\nقال ولحق أسود بن بجير بن عائذ بن شريك العجلي النعمان بن زرعة فقال له يا نعمان هلم إلي فأنا خير آسر لك وخير لك من العطش قال ومن أنت قال الأسود بن بجير فوضع يده في يده فجز ناصيته وخلى سبيله وحمله الأسود على فرس له وقال له انج على هذه فإنها أجود من فرسك وجاء الأسود بن بجير على فرس النعمان بن زرعة وقتل خالد بن يزيد البهراني قتله الأسود بن شريك بن عمرو وقتل يومئذ عمرو بن عدي بن زيد العبادي الشاعر فقالت أمه ترثيه\n(ويح عمرو بن عدي من رجل ... حان يوما بعدما قيل كمل)\n(كان لا يعقل حتى ما إذا ... جاء يوم يأكل الناس عقل)\n(أيهم دلاك عمرو للردى ... وقديما حين المرء الأجل)\n(ليت نعمان علينا ملك ... وبني لي حي لم يزل)\n(قد تنظرنا لغاد أوبة ... كان لو أغنى عن المرء الأمل)\n(بان منه عضد عن ساعد ... بؤس للدهر وبؤسى للرجل)\nال وأفلت إياس بن قبيصة على فرس له كانت عند رجل من بني تيم الله يقال له أبو ثور فلما أراد إياس أن يغزوهم أرسل إليه أبو ثور بها فنهاه أصحابه أن يفعل فقال والله ما في فرس إياس ما يعز رجلا ولا يذله وما كنت لأقطع رحمه فيها فقال إياس\n(غذاها أبو ثور فلما رأيتها ... دخيس دواء لا أضيع غذاؤها)\n(فأعددتها كفأ ليوم كريهة ... إذا أقبلت بكر تجر رشاؤها)\nال وأتبعتهم بكر بن وائل يقتلونهم بقية يومهم وليلتهم حتى أصبحوا\nمن الغد وقد شارفوا السواد ودخلوه فذكروا أن مائة من بكر بن وائل وسبعين من عجل وثلاثين من أفناء بكر بن وائل أصبحوا وقد دخلوا السواد في طلب القوم فلم يفلت منهم كبير أحد وأقبلت بكر بن وائل على الغنائم فقسموها بينهم وقسموا تلك اللطائم بين نسائهم فذلك قول الديان بن جندل\n(إن كنت ساقية يوما على كرم ... فاسقي فوارس من ذهل بن شيبانا)\n(واسقي فوارس حاموا عن ديارهم ... واعلي مفارقهم مسكا وريحانا)\nال فكان أول من انصرف إلى كسرى بالهزيمة إياس بن قبيصة وكان لا يأتيه أحد بهزيمة جيش إلا نزع كتفيه فلما أتاه إياس سأله عن الخبر فقال هزمنا بكر بن وائل فأتيناك بنسائهم فأعجب ذلك كسرى وأمر له بكسوة وإن إياسا استأذنه عند ذلك فقال إن أخي مريض بعين التمر فأردت أن آتيه وإنما أراد أن يتنحى عنه فأذن له كسرى فترك فرسه الحمامة وهي التي كانت عند أبي ثور بالحيرة وركب نجيبة فلحق بأخيه ثم أتى كسرى رجل من أهل الحيرة وهو بالخورنق فسأل هل دخل على الملك أحد فقالوا\nنعم إياس فقال ثكلت إياسا أمه وظن أنه قد حدثه بالخبر فدخل عليه فحدثه بهزيمة القوم وقتلهم فأمر به فنزعت كتفاه","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":14,"spl":"أبو الفرج يعطي رأيه في حكاية مرداس","tags":[],"loc":3955},
{"id":"b302-18","bab":"الجزء 24","sec":"وقعة ذي قار بعد وقعة بدر بأشهر — الشعراء بعد النصر","page":"ج24 ص71 – ج24 ص72","text":"قال وكانت وقعة ذي قار بعد وقعة بدر بأشهر ورسول الله بالمدينة فلما بلغه ذلك قال هذا يوم انتصفت فيه العرب من العجم وبي نصروا قال ابن الكلبي\nوأخبرني أبي عن أبي صالح عن ابن عباس قال ذكرت وقعة ذي قار عند النبي فقال \" ذلك يوم انتصفت فيه العرب من العجم وبي نصروا \" وروي أن النبي مثلت له الوقعة وهو بالمدينة فرفع يديه فدعا لبني شيبان أو لجماعة ربيعة بالنصر ولم يزل يدعو لهم حتى أري هزيمة الفرس وروي أنه\nقال \" إيها بني ربيعة اللهم انصر بني ربيعة \" فهم إلى الآن إذا حاربوا دعوا بشعار النبي ودعوته لهم وقال قائلهم يا رسول الله وعدك فإذا دعوا بذلك نصروا\nوقال أبو كلبة التيمي يفخر بيوم ذي قار\n(لولا فوارس لا ميل ولا عزل ... من اللهازم ما قظتم بذي قار)\n(ما زلت مفترسا أجساد أفتية ... تثير أعطافها منها بآثار)\n(إن الفوارس من عجل هم أنفوا ... من أن يخلوا لكسرى عرصة الدار)\n(لاقوا فوارس من عجل بشكتها ... ليسوا إذا قلصت حرب بأغمار)\n(قد أحسنت ذهل شيبان وما عدلت ... في يوم ذي قار فرسان ابن سيار)\n(هم الذين أتوهم عن شمائلهم ... كما تلبس وراد بصدار)\nأجابه الأعشى فقال\n(أبلغ أبا كلبة التيمي مألكة ... فأنت من معشر - والله - أشرار)\n(شيبان تدفع عنك الحرب آونة ... وأنت تنبح نبح الكلب في الغار)\nوقال بكير الأصم\n(إن كنت ساقية المدامة أهلها ... فاسقي على كرم بني همام)\n(وأبا ربيعة كلها ومحلما ... سبقوا بأنجد غاية الأيام)\n(زحفوا بجمع لا ترى أقطاره ... لقحت به حرب لغير تمام)\n(عرب ثلاثة آلف وكتيبة ... ألفان عجم من بني الفدام)\n(ضربوا بني الأحرار يوم لقوهم ... بالمشرفي على شؤون الهام)\n(وغدا ابن مسعود فأوقع وقعة ... ذهبت لهم في معرق وشآم)\nقال الأعشى\n(فدى لبني ذهل بن شيبان ناقتي ... وراكبها يوم اللقاء وقلت)\n(هم ضربوا بالحنو حنو قراقر ... مقدمة الهامرز حتى تولت)\nوقال بعض شعراء ربيعة في يوم ذي قار\n(ألا من لليل لا تغور كواكبه ... وهم سرى بين الجوانح جانبه)\n(ألا هل أتاها أن جيشا عرمرما ... بأسفل ذي قار أبيدت كتائبه)\n(فما حلقة النعمان يوم طلبتها ... بأقرب من نجم السماء تراقبه)\nقال الأعشى\n(حلفت بالملح والرماد وبالعزى ... وباللات تسلم الحلقه)\n(حتى يظل الهمام منجدلا ... ويقرع النبل طرة الدرقه)\nقال ابن قرد الخنزير التيمي\n(ألا أبلغ بني ذهل رسولا ... فلا شتما أردت ولا فسادا)\n(هززت الحاملين لكي يعودوا ... إذا يوم من الحدثان عادا)\n(وجدت الرفد رفد بني لجيم ... إذا ما قلت الأرفاد زادا)\n(هم ضربوا الكتائب يوم كسرى ... أمام الناس إذ كرهوا الجلادا)\n(وهم ضربوا القباب ببطن فلج ... وذادوا عن محارمنا ذيادا)\nوقال الأعشى في ذلك\n(لو أن كل معد كان شاركنا ... في يوم ذي قار ما أخطاهم الشرف)\n(لما أتونا كأن الليل يقدمهم ... مطبق الأرض تغشاها لهم سدف)\n(بطارق وبنو ملك مرازبة ... من الأعاجم في آذانها النطف)\n(من كل مرجانة في البحر أحرزها ... تيارها ووقاها طينها الصدف)\n(وظعننا خلفنا تجري مدامعها ... أكبادها وجلا مما ترى تجف)\n(يحسرن عن أوجه قد عاينت عبرا ... ولاحها غبرة ألوانها كسف)\n(ما في الخدود صدود عن وجوههم ... ولا عن الطعن في اللبات منحرف)\n(عودا على بدئهم ما إن يلبثهم ... كر الصقور بنات الماء تختطف)\n(لما أمالوا إلى النشاب أيديهم ... ملنا ببيض فظل الهام يقتطف)\n(وخيل بكر فما تنفك تطحنهم ... حتى تولوا وكاد اليوم ينتصف)\nقال حريم بن الحارث التيمي\n(وإن لجيما أهل عز وثروة ... وأهل أياد لا ينال قديمها)\n(هم منعوا في يوم قار نساءنا ... كما منع الشول الهجان قرومها)\n(إذا قيل يوما أقدموا يتقدموا ... وهل يمنع المخزاة إلا صميمها)\nال ولم يزل قيس بن مسعود في سجن كسرى بساباط حتى مات فيه\n(خليلي ما صبري على الزفرات ... وما طاقتي بالهم والعبرات)\n(تساقط نفسي كل يوم وليلة ... على إثر ما قد فاتها حسرات)\nلشعر للقحيف العقيلي والغناء لإبراهيم الموصلي رمل بالوسطى عن عمرو بن بانة وذكر الهشامي أن الرمل لعلوية وأن لحن إبراهيم من الثقيل الأول بالوسطى","topic":"ذكر نسب القطامي وأخباره","topicNo":302,"sp":15,"spl":"وقعة ذي قار بعد وقعة بدر بأشهر — الشعراء بعد النصر","tags":["الهجاء","اللهو والمزاح"],"song":1,"loc":3956},
{"id":"b303-1","bab":"الجزء 24","sec":"أخبار القحيف ونسبه","page":"ج24 ص76","text":"القحيف بن حمير أحد بني قشير بن مالك بن خفاجة بن عقيل بن كعب بن ربيعة بن عامر بن صعصعة شاعر مقل من شعراء الإسلام","topic":"أخبار القحيف ونسبه","topicNo":303,"sp":0,"spl":"أخبار القحيف ونسبه","tags":[],"loc":3957},
{"id":"b303-2","bab":"الجزء 24","sec":"أخباره مع خرقاء","page":"ج24 ص77","text":"وكان يشبب بخرقاء التي كان ذو الرمة يشبب بها فأخبرني محمد بن خلف بن وكيع وعمي قالا حدثنا هارون بن محمد بن عبد الملك عن العدوي عن أبي الحسن المدائني عن الصباح بن الحجاج عن أبيه قال مررت بخرقاء وهي بفلج فقالت أقضيت حجك وأتممته فقلت\nنعم فقالت لم تفعل شيئا فقلت ولم فقالت لأنك لم تلمم بي ولا سلمت علي أو ما سمعت قول ذي الرمة\n(تمام الحج أن تقف المطايا ... على خرقاء واضعة اللثام)\nقال هيهات يا خرقاء ذهب ذاك منك فقالت لا تقل ذاك أما سمعت قول القحيف عمك\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)\nخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عبد الله بن إبراهيم الجمحي قال حدثني أبو الشبل المعدي قال نسب ذو الرمة بخرقاء البكائية وكانت أصبح من القبس وبقيت بقاء طويلا فنسب بها القحيف العقيلي فقال\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال حدثني أبو غسان دماذ قال كبرت خرقاء حتى جاوزت تسعين سنة وأحبت أن تنفق ابنتها وتخطب فأرسلت إلى القحيف العقيلي وسألته أن يشبب بها فقال\n(لقد أرسلت خرقاء نحوي جريها ... لتجعلني خرقاء ممن أضلت)\n(وخرقاء لا تزداد إلا ملاحة ... ولو عمرت تعمير نوح وجلت)\nقال عمرو بن أبي عمرو الشيباني\nكان القحيف العقيلي يتحدث إلى امرأة من عبس وقد جاورهم وأقام عندهم شهرا وهام بها عشقا وكان يخبرها أن له نعما ومالا وهويته العبسية وكان من أجمل الرجال وأشطهم فلما طال عليها واستحيا من كذبه إياها في ماله ارتحل عنهم وقال\n(تقول لي أخت عبس : ما أرى إبلا ... وأنت تزعم من والاك صنديد)\n(فقلت يكفي مكان اللوم مطرد ... فيه القتير بسمر القين مشدود)\n(وشكة صاغها وفراء كاملة ... وصارم من سيوف الهند مقدود)\n(إني ليرعى رجال لي سوامهم ... لي العقائل منها والمقاحيد)\nقال أبو عمرو كان الوليد بن يزيد بن عبد الملك ولى علي بن المهاجر بن عبد الله الكلابي اليمامة فلما قتل الوليد بن يزيد جاءه المهير بن سلمى الحنفي فقال له إن الوليد قد قتل وإن لك علي حقا وكان أبوك لي مكرما وقد قتل صاحبك فاختر خصلة من ثلاث إن شئت أن تقيم فينا وتكون كأحدنا فافعل وإن شئت أن تتحول عنا إلى دار عمك فتنزلها أنت ومن معك إلى أن يرد أمر الخليفة المولى فتعمل بما يأمر به فافعل وإن شئت فخذ من المال\nالمجتمع ما شئت والحق بدار قومك فأنف علي بن المهاجر من ذلك ولم يقبله وقال للمهير أنت تعزلني يا بن اللخناء فخرج المهير مغضبا والتف معه أهل اليمامة وكان مع علي ستمائة رجل من أهل الشام ومثلهم من قومه وزواره فدعاهم المهير\nوذكر لهم رأيه فأبوا عليه وقاتلوه وجاء سهم عائر فوقع في كبد صانع من أهل اليمامة فقال المهير احملوا عليهم فحملوا عليهم فانهزموا وقتل منهم نفر ودخلوا القصر وأغلقوا الباب وكان من جذوع فدعا المهير بالسعف فأحرقه ودخل أصحابه فأخذوا ما في القصر وقام عبد الله بن النعمان القيسي في نفر من قومه فحموا بيت المال ومنعوا منه فلم يقدر عليه المهير وجمع المهير جيشا يريد أن يغزو بهم بني عقيل وبني كلاب وسائر بطون بني عامر فقال القحيف بن حمير لما بلغه ذلك\n(أمن أهل الأراك عفت ربوع ... نعم سقيا لهم لو تستطيع)\n(زيارتهم ولكن أحضرتنا ... هموم ما يزال لها مشيع)\nنى في هذين البيتين إبراهيم فيما ذكره هو في كتابه ولم يذكر طريقته\n(كأن البين جرعني زعافا ... من الحيات مطعمه فظيع)\n(وماء قد وردت على جباه ... حمام حائم وقطا وقوع)\nمما يغنى فيه من هذه القصيدة\n(جعلت عمامتي صلة لدلوي ... إليه حين لم ترد النسوع)\n(لأسقي فتية ومنقبات ... أضر بنقيها سفر وجيع)\nال أبو الفرج غنى في هذين البيتين سليم خفيف رمل بالوسطى ذكر ذلك حبش\n(لقد جمع المهير لنا فقلنا : ... أتحسبنا تروعنا الجموع ؟)\n(سترهبنا حنيفة إن رأتنا ... وفي أيماننا البيض اللموع)\n(عقيل تغتزي وبنو قشير ... توارى عن سواعدها الدروع)\n(وجعدة والحريش ليوث غاب ... لهم في كل معركة صريع)\n(فنعم القوم في اللزبات قومي ... بنو كعب إذا جحد الربيع)\n(كهول معقل الطرداء فيهم ... وفتيان غطارفة فروع)\n(فمهلا يا مهير فأنت عبد ... لكعب سامع لهم مطيع)","topic":"أخبار القحيف ونسبه","topicNo":303,"sp":1,"spl":"أخباره مع خرقاء","tags":[],"song":2,"loc":3958},
{"id":"b303-3","bab":"الجزء 24","sec":"أخباره مع خرقاء","page":"ج24 ص77","text":"ال وبعث المهير رجلا من بني حنيفة يقال له المندلف بن إدريس الحنفي إلى الفلج وهو منزل لبني جعدة وأمره أن يأخذ صدقات بني كعب جميعا فلما بلغهم خبره أرسلوا في أطرافهم يستصرخون عليه فأتاهم أبو لطيفة\nابن مسلمة العقيلي في عالم من عقيل فقتلوا المندلف وصلبوه فقال القحيف في ذلك\n(أتانا بالعقيق صريخ كعب ... فحن النبع والأسل النهال)\n(وحالفنا السيوف ومضمرات ... سواء هن فينا والعيال)\n(تعادى شزبا مثل السعالي ... ومن زبر الحديد لها نعال)\nقال أيضا ويروى لنجدة الخفاجي\n(لقد منع الفرائض عن عقيل ... بطعن تحت ألوية وضرب)\n(ترى منه المصدق يوم وافى ... أطل على معاشره بصلب)\nال أبو عمرو في أخباره ونظر بعض فقهاء أهل مكة إلى القحيف وهو يحد النظر إلى امرأة فنهاه عن ذلك وقال له أما تتقي الله تنظر هذا النظر إلى غير حرمة لك وأنت محرم فقال القحيف\n(أقسمت لا أنسى وإن شطت النوى ... عرانينهن الشم والأعين النجلا)\n(ولا المسك من أعطافهن ولا البرى ... ضممن وقد لوينها قضبا خدلا)\n(يقول لي المفتي وهن عشية ... بمكة يلمحن المهدبة السحلا)\n(تق الله لا تنظر إليهن يا فتى ... وما خلتني في الحج ملتمسا وصلا)\n(وإن صبا ابن الأربعين لسبة ... فكيف مع اللائي مثلن بنا مثلا)\n(عواكف بالبيت الحرام وربما ... رأيت عيون القوم من نحوها نجلا)\n\n(كففنا عن بني ذهل ... وقلنا : القوم إخوان)\n(عسى الأيام أن يرجعن ... قوما كالذي كانوا)\n(فلما صرح الشر ... وأمسى وهو عريان)\n(ولم يبق سوى العدوان ... دناهم كما دانوا)\nلشعر للفند الزماني والغناء لعبد الله بن دحمان خفيف رمل بالبنصر عن بذل والهشامي وابن المكي وتمام هذا الشعر\n(شددنا شدة الليث ... غدا والليث غضبان)\n(بضرب فيه تفجيع ... وتأييم وإرنان)\n(وطعن كفم الزق ... غذا والزق ملآن)\n(وفي العدوان للعدوان ... توهين وإقران)\n(وبعض الحلم عند الجهل ... للذلة إذعان)\n(وفي الشر نجاة حين ... لا ينجيك إحسان)\nوله دناهم كما دانوا أي جزيناهم ومثله قول الآخر\n(إنا كذاك ندين الناس بالدين ... )\nالتأييم ترك النساء أيامى والإرنان والرنة البكاء والعويل والإقران الطاقة للشيء قال الله عز و جل ( وما كنا له مقرنين\nأي مطيقين","topic":"أخبار القحيف ونسبه","topicNo":303,"sp":2,"spl":"أخباره مع خرقاء","tags":[],"song":1,"loc":3959,"partial":1},
{"id":"b304-1","bab":"الجزء 24","sec":"أخبار الفند الزماني ونسبه","page":"ج24 ص85","text":"الفند لقب غلب عليه شبه بالفند من الجبل وهو القطعة العظيمة لعظم خلقه واسمه شهل بن شيبان بن ربيعة بن زمان بن مالك بن صعب بن علي ابن بكر بن وائل وكان أحد فرسان ربيعة المشهورين المعدودين وشهد حرب بكر وتغلب وقد قارب المائة السنة فأبلى بلاء حسنا وكان مشهده في يوم التحالق الذي يقول فيه طرفة\n(سائلوا عنا الذي يعرفنا ... بقوانا يوم تحلاق اللمم)\n(يوم تبدي البيض عن أسؤقها ... وتلف الخيل أعراج النعم)\nقد مضى خبره في مقتل كليب\nفأخبرني محمد بن الحسن بن دريد قال حدثني عمي عن العباس بن هشام عن أبيه قال أرسلت بنو شيبان في محاربتهم بني تغلب إلى بني حنيفة يستنجدونهم فوجهوا إليهم بالفند الزماني في سبعين رجلا وأرسلوا إليهم إنا قد بعثنا إليكم ألف رجل\nوقال ابن الكلبي لما كان يوم التحالق أقبل الفند الزماني إلى بني شيبان وهو شيخ كبير قد جاوز مائة سنة ومعه بنتان له شيطانتان من شياطين الإنس فكشفت إحداهما عنها وتجردت وجعلت تصيح ببني شيبان ومن معهم من بني بكر\n(وعا وعا وعا وعا ... )\n(حر الجواد والتظى ... )\n(وملئت منه الربى ... )\n(يا حبذا يا حبذا ... )\n(الملحقون بالضحى ... )\nم تجردت الأخرى واقبلت تقول\n(إن تقبلوا نعانق ... ونفرش النمارق)\n(أو تدبروا نفارق ... فراق غير وامق)\nقال والتقى الناس يومئذ فأصعد عوف بن مالك بن ضبيعة بن قيس ابن ثعلبة ابنته على جمل له في ثنية قضة حتى إذا توسطها ضرب عرقوبي الجمل ثم نادى\n(أنا البرك أنا البرك ... )\n(أنزل حيث أدرك ... )\nم نادى ومحلوفة لا يمر بي رجل من بكر بن وائل إلا ضربته بسيفي هذا أفي كل يوم تفرون فيعطف القوم فقاتلوا حتى ظفروا فانهزمت تغلب قال ابن الكلبي ولحق الفند الزماني رجلا من بني تغلب يقال له مالك بن عوف قد طعن صبيا من صبيان بكر بن وائل فهو في رأس قناته وهو يقول يا ويس أم الفرخ فطعنه الفند وهو وراءه ردف له فأنفذهما جميعا وجعل يقول\n(أيا طعنة ما شيخ ... كبير يفن بالي)\n(تفتيت بها إذ كره ... الشكة أمثالي)\n(تقيم المأتم الأعلى ... على جهد وإعوال)\n(كجيب الدفنس الورهاء ... ريعت بعد إجفال)\nيروى قد ريعت بإجفال","topic":"أخبار الفند الزماني ونسبه","topicNo":304,"sp":0,"spl":"أخبار الفند الزماني ونسبه","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3960,"partial":1},
{"id":"b304-2","bab":"الجزء 24","sec":"أخبار عبد الله بن دحمان","page":"ج24 ص89","text":"عبد الله بن دحمان الأشقر المغني وقد تقدم خبر أبيه وأخيه الزبير وكان عبد الله في جنبة إبراهيم بن المهدي ومتعصبا له وكان أخوه الزبير في جنبة إسحاق الموصلي ومتعصبا له فكان كل واحد منهما يرفع من صاحبه ويشيد بذكره فعلا الزبير بتقديم إسحاق له لتمكن إسحاق وقبول الناس منه ولم يرتفع عبد الله بذكر إبراهيم له مع غض إسحاق منه وكان الزبير على كل حال يتقدم أخاه عبد الله\nفأخبرني الحسين بن يحيى عن حماد عن أبيه قال كان أبي كثيرا ما يقول ما رأيت أقل عقلا ومعرفة ممن يقول إن دحمان كان فاضلا والله ما يساوي غناؤه كله فلسين وأشبه الناس به صوتا وصنعة وبلادة وبردا ابنه عبد الله ولكن المحسن والله المجمل المؤدي الضارب المطرب ابنه الزبير\nوقال يوسف بن إبراهيم كان أبو إسحاق يؤثر عبد الله بن دحمان ويقدمه وإذا صنع صوتا عرضه على أبي إسحاق فيقومه له ويصلحه مضادة لأخيه الزبير في أمره لميل الزبير إلى إسحاق وتعصبه له وأوصله إلى الرشيد مع المغنين عدة مرات أخرج له في جميعها جائزة\n(أقول لما أتاني ثم مصرعه ... لا يبعد الرمح ذو النصلين والرجل)\n(التارك القرن مصفرا أنامله ... كأنه من عقار قهوة ثمل)\n(ليس بعل كبير لا شباب له ... لكن أثيلة صافي الوجه مقتبل)\n(يجيب بعد الكرى لبيك داعيه ... مجذامة لهواه قلقل عجل)\nوله لا يبعد الرمح يعني ابنه الذي رثاه شبهه بالرمح في نفاذه وحدته والنصلان السنان والزج والرجل يعني به ابنه أيضا من الرجلة يصفه بها أو أنه عنى لا يبعد الرجل ورمحه والعل الكبير السن الصغير الجسم ويقال أيضا للقراد عل والمقتبل المقبل وقوله مجذامة لهواه يعني أنه يقطع هواه ولا يتبعه فيما يغض من قدره وقلقل خفيف سريع والمتقلقل الخفيف الشعر للمتنخل الهذلي والغناء لمعبد وله فيه لحنان\nأحدهما من القدر الأوسط من الثقيل الأول بإطلاق الوتر في مجرى البنصر عن إسحاق والآخر خفيف ثقيل بالبنصر عن عمرو وذكر الهشامي أن للغريض لحنا من الثقيل الأول ابتداؤه\n(ليس بعل كبير لا شباب له ... )\nوالذي بعده وأن لجميلة فيه خفيف ثقيل وفيه ثاني ثقيل ينسب إلى ابن سريج وأظنه ليحيى المكي وقال حبش فيه لعبد الله بن العباس ثقيل أول بالبنصر","topic":"أخبار الفند الزماني ونسبه","topicNo":304,"sp":1,"spl":"أخبار عبد الله بن دحمان","tags":[],"song":1,"loc":3961,"partial":1},
{"id":"b305-2","bab":"الجزء 24","sec":"أخبار المتنخل ونسبه — مقتل ابنه أثيلة ورثاؤه له","page":"ج24 ص91 – ج24 ص92","text":"المتنخل لقب واسمه مالك بن عويمر بن عثمان بن سويد بن حبيش ابن خناعة بن الديل بن عادية بن صعصعة بن كعب بن طابخة بن لحيان بن هذيل بن مدركة بن إلياس بن مضر بن نزار هذه رواية ابن الكلبي وأبي عمرو وروى السكري عن الرياشي عن الأصمعي وعن ابن حبيب عن أبي عبيدة وابن الأعرابي أن اسمه مالك بن عويمر بن عثمان بن حبيش بن عادية بن صعصعة بن كعب بن طابخة بن لحيان بن هذيل ويكنى أبا أثيلة من شعراء هذيل وفحولهم وفصحائهم\nوهذه القصيدة يرثي بها ابنه أثيلة قتلته بنو سعد بن فهم بن عمرو بن قيس بن عيلان بن مضر وكان من خبر مقتله فيما ذكر أبو عمرو الشيباني\nأنه خرج في نفر من قومه يريد الغارة على فهم فسلكوا النجدية حتى إذا بلغوا السراة أتاه رجل فقال أين تريدون قالوا نريد فهما فقال ألا أدلكم على خير من ذلكم وعلى قوم دارهم خير من دار فهم هذه دار بني حوف عندكم فانصبوا عليهم على الكداء حتى تبيتوا بني حوف فقبلوا منه وانحرفوا عن طريقهم وسلكوا في شعب في ظهر الطريق حتى نفذوه ثم سلكوا على السمرة فمروا بدار بني قريم بالسرو وقد لصقت سيوفهم بأغمادهم من الدم فوجدوا إياس بن المقعد في الدار وكان سيدا فقال من أين أقبلتم فقالوا أتينا بني حوف فدعا لهم بطعام وشراب حتى إذا أكلوا وشربوا دلهم على الطريق وركب معهم حتى أخذوا سنن قصدهم فأتوا بني حوف وإذا هم قد اجتمعوا مع بطن من فهم للرحيل عن دارهم فلقيهم أول من الرجال على الخيل فعرفوهم فحملوا عليهم وأطردوهم ورموهم فأثبتوا أثيلة جريحا ومضوا لطيتهم وعاد إليه أصحابه فأدركوه ولا تحامل به فأقاموا عليه حتى مات ودفنوه في موضعه فلما رجعوا سألهم عنه المتنخل فدامجوه وستروه ثم أخبره بعضهم بخبره فقال يرثيه\n(ما بال عينك تبكي دمعها خضل ... كما وهى سرب الأخراب منبزل)\n(لا تفتأ الدهر من سح بأربعة ... كأن إنسانها بالصاب مكتحل)\n(تبكي على رجل لم تبل جدته ... خلى عليها فجاجا بينها خلل)\n(وقد عجبت وهل بالدهر من عجب ... أنى قتلت وأنت الحازم البطل)\n(ويل امه رجلا تأبى به غبنا ... إذا تجرد لا خال ولا بخل)\nال من الخيلاء ويروى خذل\n(السالك الثغرة اليقظان كالئها ... مشي الهلوك عليها الخيعل الفضل)\n(والتارك القرن مصفرا أنامله ... كأنه من عقار قهوة ثمل)\n(مجدلا يتسقى جلده دمه ... كما يقطر جذع الدومة القطل)\n(ليس بعل كبير لا شباب به ... لكن أثيلة صافي الوجه مقتبل)\n(يجيب بعد الكرى لبيك داعيه ... مجذامة لهواه قلقل عجل)\n(حلو ومر كعطف القدح مرته ... في كل آن أتاه الليل ينتعل)\n(فاذهب فأي فتى في الناس أحرزه ... من حتفه ظلم دعج ولا جبل)\n(فلو قتلت ورجلي غير كارهة الإدلاج ... فيها قبيض الشد والنسل)\n(إذن لأعملت نفسي في غزاتهم ... أو لابتعثت به نوحا له زجل)\n(أقول لما أتاني الناعيان به : ... لا يبعد الرمح ذو النصلين والرجل)\n(رمح لنا كان لم يفلل ننوء به ... توفى به الحرب والعزاء والجلل)\n(رباء شماء لا يدنو لقلتها ... إلا السحاب وإلا النوب والسبل)\nقال أبو عمرو الشيباني كان عمرو بن عثمان أبو المتنخل يكنى أبا مالك فهلك فرثاه المتنخل فقال\n(ألا من ينادي أبا مالك ... أفي أمرنا أمره أم سواه)\n(فوالله ما إن أبو مالك ... بوان ولا بضعيف قواه)\n(ولا بألد له نازع ... يعادي أخاه إذا ما نهاه)\n(ولكنه هين لين ... كعالية الرمح عرد نساه)\n(إذا سدته سدت مطواعة ... ومهما وكلت إليه كفاه)\n(أبو مالك قاصر فقره ... على نفسه ومشيع غناه)","topic":"أخبار المتنخل ونسبه","topicNo":305,"sp":0,"spl":"أخبار المتنخل ونسبه — مقتل ابنه أثيلة ورثاؤه له","tags":["الوصف والطبيعة"],"loc":3962},
{"id":"b305-3","bab":"الجزء 24","sec":"أبو جعفر محمد بن علي يتمثل بشعره","page":"ج24 ص95","text":"حدثني أبو عبيد الصيرفي قال حدثنا الفضل بن الحسن البصري قال حدثنا أحمد بن راشد قال حدثني عمي سعيد بن خيثم قال كان أبو جعفر\nمحمد بن علي عليهما السلام إذا نظر إلى أخيه زيد تمثل\n(لعمرك ما إن أبو مالك ... بواه ولا بضعيف قواه)\n(ولا بألد له نازع ... يعادي أخاه إذا ما نهاه)\n(ولكنه هين لين ... كعالية الرمح عرد نساه)\n(إذا سدته سدت مطواعة ... ومهما وكلت إليه كفاه)\n(أبو مالك قاصر فقره ... على نفسه ومشيع غناه)\nثم يقول لقد أنجبت أم ولدتك يا زيد اللهم اشدد أزري بزيد أخبرني محمد بن العباس اليزيدي قال حدثنا الرياشي عن الأصمعي قال أجود طائية قالتها العرب قصيدة المتنخل\n(عرفت بأجدث فنعاف عرق ... علامات كتحبير النماط)\n(كأن مزاحف الحيات فيها ... قبيل الصبح آثار السياط)\nي هذين البيتين غناء\n(عجبت لسعي الدهر بيني وبينها ... فلما انقضى ما بيننا سكن الدهر)\n(فيا هجر ليلى قد بلغت بي المدى ... وزدت على ما لم يكن بلغ الهجر)\n(ويا حبها زدني جوى كل ليلة ... ويا سلوة الأيام موعدك الحشر)\n(أما والذي أبكى وأضحك والذي ... أمات وأحيا والذي أمره الأمر)\n(لقد تركتني أحسد الوحش أن أرى ... أليفين منها لا يروعهما الزجر)\nلشعر لأبي صخر الهذلي والغناء لمعبد في الأول والثاني من الأبيات ثاني ثقيل بالوسطى عن عمرو ولابن سريج في الرابع والخامس ثقيل أول ولعريب فيهما أيضا ثقيل أول آخر وهو الذي فيه استهلال وللواثق فيهما رمل ولابن سريج أيضا ثاني ثقيل في الثالث وما بعده عن أحمد بن المكي وذكر ابن المكي أن الثقيل الثاني بالوسطى لجده يحيى المكي","topic":"أخبار المتنخل ونسبه","topicNo":305,"sp":1,"spl":"أبو جعفر محمد بن علي يتمثل بشعره","tags":[],"song":1,"loc":3963},
{"id":"b306-3","bab":"الجزء 24","sec":"أخبار أبي صخر الهذلي ونسبه — موالاته لبني مروان — خبره مع عبد الملك","page":"ج24 ص97 – ج24 ص98 – ج24 ص100","text":"هو عبد الله بن سلم السهمي أحد بني مرمض وهذا أكثر ما وجدته من نسبه في نسخة السكري وهي أتم النسخ مما يأثره عن الرياشي عن الأصمعي وعن الأثرم عن أبي عبيدة وعن ابن حبيب عن ابن الأعرابي\nهو شاعر إسلامي من شعراء الدولة الأموية وكان مواليا لبني مروان متعصبا لهم وله في عبد الملك بن مروان مدائح وفي أخيه عبد العزيز وعبد العزيز بن عبد الله بن خالد بن أسيد وحبسه ابن الزبير إلى أن قتل فأخبرني يحيى بن أحمد بن الجون مولى بني أمية لقيته بالرقة\nقال حدثني الفيض بن عبد الملك قال حدثني مولاي عن أبيه عن مسلمة بن الوليد القرشي عن عبد العزيز بن عمر بن عبد العزيز قال لما ظهر عبد الله بن الزبير بالحجاز وغلب عليها بعد موت يزيد بن معاوية وتشاغل بنو أمية بالحرب بينهم في مرج راهط وغيره دخل عليه أبو\nصخر الهذلي في هذيل وقد جاؤوا ليقبضوا عطاءهم وكان عارفا بهواه في بني أمية فمنعه عطاءه فقال علام تمنعني حقا لي وأنا امرؤ مسلم ما أحدثت في الإسلام حدثا ولا أخرجت من طاعة يدا\nقال عليك بني أمية فاطلب عندهم عطاءك قال إذن أجدهم سباطا أكفهم سمحة أنفسهم بذلاء لأموالهم وهابين لمجتديهم كريمة أعراقهم شريفة أصولهم زاكية فروعهم قريبا من رسول الله نسبهم وسببهم ليسوا إذا نسبوا بأذناب ولا وشائظ ولا أتباع ولا هم في قريش كفقعة القاع لهم السؤدد في الجاهلية والملك في الإسلام لا كمن لا يعد في عيرها ولا نفيرها ولا حكم آباؤه في نقيرها ولا قطميرها ليس من أحلافها المطيبين ولا من ساداتها المطعمين ولا من جودائها الوهابين ولا من هاشمها المنتخبين ولا عبد شمسها المسودين\nوكيف تقابل الرؤوس بالأذناب وأين النصل من الجفن والسنان من الزج والذنابى من القدامى وكيف يفضل الشحيح على الجواد والسوقة على الملك والمجيع بخلا على المطعم فضلا فغضب ابن الزبير حتى ارتعدت فرائصه وعرق جبينه واهتز من قرنه إلى قدمه وامتقع لونه ثم\nقال له يابن البوالة على عقبيها يا جلف يا جاهل أما والله لولا الحرمات الثلاث حرمة الإسلام وحرمة الحرم وحرمة الشهر الحرام لأخذت الذي فيه عيناك ثم أمر به إلى سجن عارم فحبس به مدة ثم استوهبته هذيل ومن له بين قريش خؤولة في هذيل فأطلقه بعد سنة وأقسم ألا يعطيه عطاء مع المسلمين أبدا\nفلما كان عام الجماعة وولي عبد الملك وحج لقيه أبو صخر فلما رآه عبد الملك قربه وأدناه وقال له إنه لم يخف علي خبرك مع الملحد ولا ضاع لك عندي هواك وموالاتك فقال أما إذا شفى الله منه نفسي ورأيته قتيل سيفك وصريع أوليائك مصلوبا مهتوك الستر مفرق الجمع فما أبالي ما فاتني من الدنيا ثم استأذنه أبو صخر في الإنشاد فأذن له فمثل بين يديه قائما وأنشأ يقول\n(عفت ذات عرق عصلها فرئامها ... فدهناؤها وحش وأجلي سوامها)\n(على أن مرسى خيمة خف أهلها ... بأبطح محلال وهيهات عامها)\n(إذا اعتلجت فيها الرياح فأدرجت ... عشيا جرى في جانبيها قمامها)\n(وإن معاجي في الديار وموقفي ... بدراسة الربعين بال ثمامها)\n(لجهل ولكني أسلي ضمانة ... يضعف أسرار الفؤاد سقامها)\n(فأقصر فلا ما قد مضى لك راجع ... ولا لذة الدنيا يدوم دوامها)\n(وفد أمير المؤمنين الذي رمى ... بجأواء جمهور تسيل إكامها)\n(من أرض قرى الزيتون مكة بعدما ... غلبنا عليها واستحل حرامها)\nقول رمى مكة بالرجال من أهل الشام وهي أرض الزيتون\n(وإذ عاث فيها الناكثون وأفسدوا ... فخيفت أقاصيها وطار حمامها)\n(فشج بهم عرض الفلاة تعسفا ... إذا الأرض أخفى مستواها سوامها)\n(فصبحهم بالخيل تزحف بالقنا ... وبيضاء مثل الشمس يبرق لامها)\n(لهم عسكر ضافي الصفوف عرمرم ... وجمهورة يثني العدو انتقامها)\n(فطهر منهم بطن مكة ماجد ... أبى الضيم والميلاء حين يسامها)\n(فدع ذا وبشر شاعري أم مالك ... بأبيات ما خزي طويل عرامها)\nشاعري أم مالك رجلان من كنانة كانا مع ابن الزبير يمدحانه ويحرضانه على أبي صخر لعداوة كانت بينهما وبينه\n(فإن تبد تجدع منخراك بمدية ... مشرشرة حرى حديد حسامها)\n(وإن تخف عنا أو تخف من أذاتنا ... تنوشك نابا حية وسمامها)\n(فلولا قريش لاسترقت عجوزكم ... وطال على قطبي رحاها احتزامها)\nال فأمر له عبد الملك بما فاته من العطاء ومثله صلة من ماله وكساه وحمله","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":0,"spl":"أخبار أبي صخر الهذلي ونسبه — موالاته لبني مروان — خبره مع عبد الملك","tags":["المديح"],"loc":3964},
{"id":"b306-4","bab":"الجزء 24","sec":"عبد العزيز بن أسيد يطلب من الهذلي أن يرثيه وهو حي","page":"ج24 ص102","text":"ونسخت من كتاب أبي سعيد السكري عن محمد بن حبيب عن ابن الأعرابي وأبي عبيدة قالا\nكان أبو صخر الهذلي منقطعا إلى أبي خالد عبد العزيز بن عبد الله بن خالد بن أسيد مداحا له فقال له يوما ارثني يا أبا صخر وأنا حي حتى أسمع كيف تقول وأين مراثيك لي بعدي من مديحك إياي في حياتي\nفقال أعيذك بالله أيها الأمير من ذلك بل يبقيك الله ويقدمني قبلك\nفقال ما من ذلك بد قال فرثاه بقصيدته التي يقول فيها\n(أبا خالد نفسي وقت نفسك الردى ... وكان بها من قبل عثرتك العثر)\n(لتبكك يا عبد العزيز قلائص ... أضر بها نص الهواجر والزجر)\n(سمون بنا يجتبن كل تنوفة ... تضل بها عن بيضهن القطا الكدر)\n(فما قدمت حتى تواتر سيرها ... وحتى أنيخت وهي ظالعة دبر)\n(ففرج عن ركبانها الهم والطوى ... كريم المحيا ماجد واجد صقر)\n(أخو شتوات تقتل الجوع داره ... لمن جاء ولا ضيق الفناء ولا وعر)\n(ولا تهنئ الفتيان بعدك لذة ... ولا بل هام الشامتين بك القطر)\n(وإن تمس رمسا بالرصافة ثاويا ... فما مات يا بن العيص نائلك الغمر)\n(وذي ورق من فضل مالك ماله ... وذي حاجة قد رشت ليس له وفر)\n(فأمسى مريحا بعد ما قد يؤوبه ... وكل به المولى وضاق به الأمر)\nال فأضعف له عبد العزيز جائزته ووصله وأمر أولاده فرووا القصيدة وقال أبو عمرو الشيباني كان لأبي صخر ابن يقال له داود لم يكن له ولد غيره فمات فجزع عليه جزعا شديدا حتى خولط فقال يرثيه\n(لقد هاجني طيف لداود بعدما ... دنت فاستقلت تاليات الكواكب)\n(وما في ذهول النفس عن غير سلوة ... رواح من السقم الذي هو غالبي)\n(وعندك لو يحيا صداك فنلتقي ... شفاء لمن غادرت يوم التناضب)\n(فهل لك طب نافعي من علاقة ... تهيمني بين الحشا والترائب)\n(تشكيتها إذ صدع الدهر شعبنا ... فأمست وأعيت بالرقى والطبائب)\n(ولولا يقيني أنما الموت عزمة ... من الله حتى يبعثوا للمحاسب)\n(لقلت له فيما ألم برمسه : ... هل أنت غدا غاد معي فمصاحبي)\n(وماذا ترى في غائب لا يغبني ... فلست بناسيه وليس بآئب)\n(سألت مليكي إذ بلاني بفقده ... وفاة بأيدي الروم بين المقانب)\n(ثنوني وقد قدمت ثأري بطعنة ... تجيش بموار من الجوف ثاعب)\n(فقد خفت أن ألقي المنايا وإنني ... لتابع من وافى حمام الجوالب)\n(ولما أطاعن في العدو تنفلا ... إلى الله أبغي فضله وأضارب)\n(وأعطف وراء المسلمين بطعنة ... على دبر مجل من العيش ذاهب)\nقال أبو عمرو بلغ أبا صخر أن رجلا من قومه عابه وقدح فيه فقال أبو صخر في ذلك\n(ولقد أتاني ناصح عن كاشح ... بعدواة ظهرت وقبح أقاول)\n(أفحين أحكمني المشيب فلا فتى ... غمر ولا قحم وأعصل بازلي)\n(ولبست أطوار المعيشة كلها ... بمؤبدات للرجال دواغل)\n(أصبحت تنقصني وتقرع مروتي ... بطرا ولم يرعب شعابك وابلي)\n(وتنلك أظفاري ويبرك مسحلي ... بري الشسيب من السراء الذابل)\n(فتكون للباقين بعدك عبرة ... وأطأ جبينك وطأة المتثاقل)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":1,"spl":"عبد العزيز بن أسيد يطلب من الهذلي أن يرثيه وهو حي","tags":["المديح"],"loc":3965},
{"id":"b306-5","bab":"الجزء 24","sec":"الهذلي وأم حكيم","page":"ج24 ص105","text":"وقال أبو عمرو وكان أبو صخر الهذلي يهوى امرأة من قضاعة مجاورة فيهم يقال لها ليلى بنت سعد وتكنى أم حكيم وكانا يتواصلان برهة من دهرهما ثم تزوجت ورحل بها زوجها إلى قومه فقال في ذلك أبو صخر\n(ألم خيال طارق متأوب ... لأم حكيم بعدما نمت موصب)\n(وقد دنت الجوزاء وهي كأنها ... ومرزمها بالغور ثور وربرب)\n(فبات شرابي في المنام مع المنى ... غريض اللمى يشفي جوى الحزن أشنب)\n(قضاعية أدنى ديار تحلها ... قناة وأنى من قناة المحصب)\n(سراج الدجى تغتل بالمسك طفلة ... فلا هي متفال ولا اللون أكهب)\n(دميثة ما تحت الثياب عميمة ... هضيم الحشا بكر المجسة ثيب)\n(تعلقتها خودا لذيذا حديثها ... ليالي لا تحمى ولا هي تحجب)\n(فكان لها ودي ومحض علاقتي ... وليدا إلى أن رأسي اليوم أشيب)\n(فلم أر مثلي أيأست بعد علمها ... بودي ولا مثلي على اليأس يطلب)\n(ولو تلتقي أصداؤنا بعد موتنا ... ومن دون رمسينا من الأرض سبسب)\n(لظل صدى رمسي ولو كنت رمة ... لصوت صدى ليلى يهش ويطرب)\nقصيدة أبي صخر التي فيها الغناء المذكور من مختار شعر هذيل وأولها\n(لليلى بذات الجيش دار عرفتها ... وأخرى بذات البين آياتها سطر)\n(وقفت برسميها فلما تنكرا ... صدفت وعيني دمعها سرب همر)\n(وفي الدمع إن كذبت بالحب شاهد ... يبين ما أخفي كما بين البدر)\n(صبرت فلما غال نفسي وشفها ... عجاريف نأي دونها غلب الصبر)\n(إذا لم يكن بين الخليلين ردة ... سوى ذكر شيء قد مضى درس الذكر)\nهذا البيت خاصة رواه الزبير بن بكار لنصيب\n(إذا قلت هذا حين أسلو يهيجني ... نسيم الصبا من حيث يطلع الفجر)\n(وإني لتعروني لذكراك فترة ... كما انتفض العصفور بلله القطر)\n(هجرتك حتى قيل لا يعرف الهوى ... وزرتك حتى قيل ليس له صبر)\n(صدقت أنا الصب المصاب الذي به ... تباريح حب خامر القلب أو سحر)\n(أما والذي أبكى وأضحك والذي ... أمات وأحيا والذي أمره الأمر)\n(لقد تركتني أحسد الوحش أن أرى ... أليفين منها لم يروعهما الزجر)\n(فيا هجر ليلى قد بلغت بي المدى ... وزدت على ما لم يكن بلغ الهجر)\n(ويا حبها زدني جوى كل ليلة ... ويا سلوة الأيام موعدك الحشر)\n(عجبت لسعي الدهر بيني وبينها ... فلما انقضى ما بيننا سكن الدهر)\n(فليست عشيات الحمى برواجع ... لنا أبدا ما أورق السلم النضر)\n\n(وإني لآتيها لكيما تثيبني ... وأوذنها بالصرم ما وضح الفجر)\n(فما هو إلا أن أراها فجاءة ... فأبهت لا عرف لدي ولا نكر)\n(تكاد يدي تندى إذا ما لمستها ... وينبت في أطرافها الورق الخضر)\nي هذه الأبيات ثقيل أول قديم مجهول وفي البيت الأخير لعريب خفيف ثقيل وقد أضافت إليه بيتا ليس من الشعر وهو\n(أبى القلب إلا حبها عامرية ... لها كنية \" عمرو \" وليس لها \" عمرو \")","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":2,"spl":"الهذلي وأم حكيم","tags":["الحب والغزل"],"song":1,"loc":3966},
{"id":"b306-6","bab":"الجزء 24","sec":"الهادي يطرب لشعره ويشق قميصه","page":"ج24 ص108","text":"أخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق قال حدثني أبي عن جدي قال دخلت يوما على موسى الهادي وهو مصطبح فقال لي يا إبراهيم غنني فإن أطربتني فلك حكمك فغنيته\n(وإني لتعروني لذكراك فترة ... كما انتفض العصفور بلله القطر)\nضرب بيده إلى جنب دراعته فشقها حتى انتهى به إلى صدره ثم غنيته\n(أما والذي أبكى وأضحك والذي ... أمات وأحيا والذي أمره الأمر)\n(لقد تركتني أحسد الوحش أن أرى ... أليفين منها لا يروعهما الزجر)\nشق دراعته حتى انتهى إلى آخرها ثم غنيته\n(فيا حبها زدني جوى كل ليلة ... ويا سلوة الأيام موعدك الحشر)\nشق جبة كانت تحت الدراعة حتى هتكها ثم غنيته\n(عجبت لسعي الدهر بيني وبينها ... فلما انقضى ما بيننا سكن الدهر)\nشق قميصا كان تحت ثيابه حتى بدا جسمه ثم قال أحسنت والله فاحتكم فقلت تهب لي يا أمير المؤمنين عين مروان بالمدينة فغضب حتى دارت عيناه في رأسه ثم قال لا ولا كرامة أردت أن تجعلني أحدوثة للناس وتقول أطربته فحكمني فحكمت فأمضى حكمي ثم قال لإبراهيم الحراني خذ بيد هذا الجاهل وأدخله بيت مال الخاصة فإن أخذ كل شيء فيه فلا تمنعه منه فدخلت معه فأخذت مالا جليلا وانصرفت\nومما يغنى فيه من شعر أبي صخر الهذلي قوله من قصيدة له\n(بيد الذي شعف الفؤاد بكم ... فرج الذي ألقى من الهم)\n(هم من اجلك ليس يكشفه ... إلا مليك جائز الحكم)\n(فاستيقني أن قد كلفت بكم ... ثم افعلي ما شئت عن علم)\n(قد كان صرم في الممات لنا ... فعجلت قبل الموت بالصرم)\nلشعر لأبي صخر الهذلي والغناء للغريض ثقيل أول بالوسطى عن عمرو وفيه لسياط ثقيل أول آخر بالبنصر ابتداؤه نشيد\n(فاستيقني أن قد كلفت بكم ... )\nهكذا ذكر الهشامي أيضا وذكر أن لحن الغريض ثاني ثقيل وأن فيه لابن جامع خفيف رمل أخبرني علي بن سليمان الأخفش قال حدثنا محمد بن الحسن الحرون قال حدثني الكسروي قال\nلقي إبراهيم النظام غلاما أمرد فاستحسنه فقال له يا بني لولا أنه قد سبق من قول الحكماء ما جعلوا به السبيل لمثلي إلى مثلك في قولهم لا ينبغي لأحد أن يكبر عن أن يسأل كما لا ينبغي لأحد أن يصغر عن أن يقول لما أنست إلى مخاطبتك ولا هششت لمحادثتك ولكنه سبب الإخاء وعقد المودة ومحلك من قلبي محل الروح من جسد الجبان فقال له الغلام وهو لا يعرفه لئن\nقلت ذاك أيها الرجل لقد قال الأستاذ إبراهيم النظام الطبائع تجاذب ما شاكلها بالمجانسة وتميل إلى ما يوافقها بالمؤانسة وكياني مائل إلى كيانك بكليتي ولو كان ما أنطوي لك عليه عرضا ما اعتددت به ودا ولكنه جوهر جسمي فبقاؤه ببقاء النفس وعدمه بعدمها وأقول كما قال الهذلي\n(فاستيقني أن قد كلفت بكم ... ثم افعلي ما شئت عن علم)\nقال له النظام إنما خاطبتك بما سمعت وأنت عندي غلام مستحسن ولو علمت أنك بهذه المنزلة لرفعتك إلى رتبتها قال أبو الحسن الأخفش فأخذ أبو دلف هذا المعنى فقال\n(أحبك يا جنان وأنت مني ... محل الروح من جسد الجبان)\n(ولو أني أقول مكان نفسي ... لخفت عليك بادرة الزمان)\n(لإقدامي إذا ما الخيل خامت ... وهاب كماتها حر الطعان)\nتمام أبيات أبي صخر الميمية التي ذكرت فيها الغناء الأخير وخبره أنشدنيها\nالأخفش عن السكري عن أصحابه\n(ولما بقيت ليبقين جوى ... بين الجوانح مضرع جسمي)\n(ويقر عيني وهي نازحة ... ما لا يقر بعين ذي الحلم)\n(أطلال نعم إذ كلفت بها ... يأدين هذا القلب من نعم)\n(ولو أنني أسقى على سقمي ... بلمى عوارضها شفى سقمي)\n(ولقد عجبت لنبل مقتدر ... يسط الفؤاد بها ولا يدمي)\n(يرمي فيجرحني برميته ... فلو انني أرمي كما يرمي)\n(أو كان قلب إذ عزمت له ... صرمي وهجري كان ذا عزم)\n(أو كان لي غنم بذكركم ... أمسيت قد أثريت من غنم)\nخبرني الحسين بن يحيى عن حماد عن أبيه عن أبي عبد الله الأنصاري عن غرير بن طلحة الأرقمي قال قال لي أبو السائب المخزومي وكان من أهل الفضل والنسك هل لك في أحسن الناس غناء\nقلت نعم وكان علي يومئذ طيلسان لي أسميه من غلظه وثقله مقطع الأزرار فخرجنا حتى جئنا إلى الجبانة إلى دار مسلم بن يحيى الأرت صاحب الخمر مولى بني زهرة فأذن لنا فدخلنا بيتا طوله اثنتا عشرة ذراعا في مثلها وسمكة في السماء ست عشرة ذراعا ما فيه إلا نمرقتان قد ذهبت منهما اللحمة وبقي السدى وفراش محشو ليفا وكرسيان من خشب قد تقلع عنهما الصبغ من","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":3,"spl":"الهادي يطرب لشعره ويشق قميصه","tags":[],"song":1,"loc":3967,"partial":1},
{"id":"b306-7","bab":"الجزء 24","sec":"الهادي يطرب لشعره ويشق قميصه","page":"ج24 ص108","text":"قدمهما وبينهما مرفقتان محشوتان بالليف ثم طلعت علينا عجوز كلفاء عجفاء كأن شعرها شعر ميت عليها قرقل هروي أصفر غسيل كأن وركيها في خيط من رسحها حتى جلست فقلت لأبي السائب بأبي أنت وأمي ما هذه قال اسكت فتناولت عودا فضربت وغنت\n(بيد الذي شغف الفؤاد بكم ... فرج الذي ألقى من الهم)\nال غرير فحسنت والله في عيني وجاء نقاء وصفاء فأذهب الكلف من وجهها وزحف أبو السائب وزحفت معه ثم غنت\n(برح الخفاء فأي ما بك تكتم ... ولسوف يظهر ما يسر فيعلم)\n(مما تضمن من غريرة قلبه ... يا قلب إنك بالحسان لمغرم)\n(يا ليت أنك يا حسام بأرضنا ... تلقي المراسي دائما وتخيم)\n(فتذوق لذة عيشنا ونعيمه ... ونكون أجوارا فماذا تنقم)\nلغناء لحكم خفيف رمل بالوسطى عن الهشامي فقال أبو السائب إن نقم هذا فيعض بظر أمه وزحف وزحفت معه حتى قاربت النمرقة وربت العجفاء في عيني كما يربو السويق شيب بماء قربة\nثم غنت\n(يا طول ليلي أعالج السقما ... إذ حل دون الأحبة الحرما)\n(ما كنت أخشى فراق بينكم ... فاليوم أضحى فراقكم عزما)\nلغناء للغريض ثقيل أول بالوسطى في مجراها وله أيضا فيه خفيف ثقيل بإطلاق الوتر في مجرى البنصر جميعا عن إسحاق قال غرير فألقيت طيلساني وتناولت شاذكونة فوضعتها على رأسي وصحت كما يصاح بالمدينة الدخن بالنوى وقام أبو السائب وتناول ربعة فيها قوارير دهن كانت في البيت فوضعها على رأسه وصاح ابن الأرت صاحب الجارية وكان ألثغ قواليلي قواليلي يريد قواريري قواريري أسألك بالله فلم يلتفت أبو السائب إلى قوله وحرك رأسه مرحا فاضطربت القوارير وتكسرت وسال الدهن على وجه أبي السائب وظهره وصدره ثم وضع الربعة\nوقال لها لقد هجت لي داء قديما قال ومكثنا نختلف إليها سنين في كل جمعة يومين وقال ثم بعث عبد الرحمن بن معاوية بن هشام من الأندلس فاشتريت له العجفاء وحملت إليه\n(ألا هل إلى ريح الخزامى ونظرة ... إلى قرقرى قبل الممات سبيل)\n(فيا أثلاث القاع من بطن توضح ... حنيني إلى أطلالكن طويل)\n(ويا أثلات القاع قلبي موكل ... بكن وجدوى خيركن قليل)\n(ويا أثلات القاع قد مل صحبتي ... وقوفي فهل في ظلكن مقيل ؟)\nلشعر ليحيى بن طالب الحنفي والغناء لعلوية خفيف رمل بالوسطى عن عمرو وفيه لإبراهيم لحن ماخوري بالوسطى وفيه لعريب رمل ولمتيم خفيف رمل آخر عن الهشامي وفيه لابن المكي خفيف ثقيل من كتابه وذكر ابن المعتز أن لحن عريب ومتيم جميعا من الرمل","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":4,"spl":"الهادي يطرب لشعره ويشق قميصه — جارية تعرف به","tags":["الجواري والنساء"],"song":3,"loc":3968},
{"id":"b306-8","bab":"الجزء 24","sec":"أخبار يحيى بن طالب","page":"ج24 ص115","text":"يحيى بن طالب شاعر من أهل اليمامة ثم من بني حنيفة لم يقع إلي نسبه وهو من شعراء الدولة العباسية مقل وكان فصيحا شاعرا غزلا فارسا وركبه دين في بلده فهرب إلى الري وخرج مع بعث إليها فمات بها وقد ذكر ذلك في هذه القصيدة فقال\n(أريد رجوعا نحوكم فيصدني ... إذا رمته دين علي)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":4,"spl":"الهادي يطرب لشعره ويشق قميصه — جارية تعرف به","tags":["اللهو والمزاح","الموت"],"loc":3969},
{"id":"b306-9","bab":"الجزء 24","sec":"الرشيد يأمر بقضاء دينه الذي هرب بسببه","page":"ج24 ص116","text":"حدثني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه قال غنى أبي الرشيد في شعر يحيى بن طالب\n(ألا هل إلى شم الخزامى ونظرة ... إلى قرقرى قبل الممات سبيل)\nفأطربه فسأله عن قائل الشعر فذكره له وأعلمه أنه حي وأنه هرب من دين عليه وأنشده قوله\n(أريد رجوعا نحوكم فيصدني ... إذا رمته دين علي)\nأمر الرشيد أن يكتب إلى عامل الري بقضاء دينه وإعطائه نفقة وإنفاذه إليه على البريد فوصل الكتاب يوم مات يحيى بن طالب","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":4,"spl":"الهادي يطرب لشعره ويشق قميصه — جارية تعرف به","tags":[],"loc":3970},
{"id":"b306-10","bab":"الجزء 24","sec":"جارية تعرف به","page":"ج24 ص117","text":"أخبرنا محمد بن خلف وكيع وعمي قالا حدثنا عبد الله بن شبيب قال حدثني الجهم بن المغيرة قال كنا عند حترش بن ثمال القريظي بضرية فمرت بنا جارية صفراء مولدة فقال لي حترش استفتح كلامها فانظر فإنها ظريفة فقلت لها يا جارية أين نشأت قالت بقرقرى فقلت لها أين من شعبعب فضحكت ثم قالت بين الحوض والعطن قلت فمن الذي يقول\n(يا صاحبي فدت نفسي نفوسكما ... عوجا علي صدور الأبغل السنن)\n(ثم ارفعا الطرف ننظر صبح خامسة ... لقرقرى يا عناء النفس بالوطن)\n(يا ليت شعري والإنسان ذو أمل ... والعين تذرف أحيانا من الحزن)\n(هل أجعلن يدي للخد مرفقة ... على شعبعب بين الحوض والعطن ؟)\nالتفتت إلى حترش بن ثمال فقالت أخبره بقائلها فقال ما أعرفه فقالت بلى هذا يقوله شاعرنا وظريف بلادنا وغزلها فقال لها حترش\nويحك ومن ذلك فقالت أشهد إن كنت لا تعرفه وأنت من هذا البلد إنها لسوأة ذلك يحيى بن طالب الحنفي أقسم بالله ما منعك من معرفته إلا غلظ الطبع وجفاء الخلق فجعل يضحك من قولها وتعجبنا منها","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":4,"spl":"الهادي يطرب لشعره ويشق قميصه — جارية تعرف به","tags":["الجواري والنساء","اللهو والمزاح"],"loc":3971},
{"id":"b306-11","bab":"الجزء 24","sec":"يرفض ركوب البحر للتجارة","page":"ج24 ص117","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا أبو غسان دماذ عن أبي عبيدة قال قال رجل ليحيى بن طالب الحنفي لو ركبت معي في البحر وشغلت مالك في تجاراته لأثريت وحسنت حالك فقال يحيى بن طالب\n(لشربك بالأنقاء رنقا وصافيا ... أعف وأعفى من ركوبك في البحر)\n(إذا أنت لم تنظر لنفسك خاليا ... أحاطت بك الأحزان من حيث لا تدري)\nحدثني محمد بن خلف بن المرزبان قال حدثنا عبد الله بن أبي سعد قال حدثني أبو علي الحنفي قال حدثني عمي عن علي بن عمر قال غني الرشيد يوما بشعر يحيى بن طالب\n(ألا هل إلى شم الخزامى ونظرة ... إلى قرقرى قبل الممات سبيل)\nذكر الخبر كما ذكره حماد بن إسحاق إلا أنه قال فوجده قد مات قبل وصول البريد بشهر","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":5,"spl":"يرفض ركوب البحر للتجارة — حنينه إلى قرقرى","tags":["الموت"],"loc":3972},
{"id":"b306-12","bab":"الجزء 24","sec":"خرج إلى مكة فتشوق إلى صاحبته في اليمامة","page":"ج24 ص118","text":"أخبرني هاشم بن محمد الخزاعي قال حدثنا عبد الرحمن ابن أخي الأصمعي عن عمه قال\nكان يحيى بن طالب يجالس امرأة من قومه ويألفها ثم خرج مع والي اليمامة إلى مكة وابتاع منه الوالي إبلا بتأخير فلما صار إلى مكة عزل الوالي فلوى يحيى بماله مدة فضاق صدره وتشوق إلى اليمامة وصاحبته التي كان يتحدث إليها فقال\n(تصبرت عنها كارها وهجرتها ... وهجرانها عندي أمر من الصبر)\n\n(إذا ارتحلت نحو اليمامة رفقة ... دعاني الهوى واهتاج قلبي للذكر)\n(كأن فؤادي كلما عن ذكرها ... جناحا غراب رام نهضا إلى وكر)\nلغناء للزف ثقيل أول عن الهشامي في هذين البيتين وقال فيها\n(مداينة السلطان باب مذلة ... وأشبه شيء بالقناعة والفقر)\n(إذا أنت لم تنظر لنفسك خاليا ... أحاطت بك الأحزان من حيث لا تدري)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":5,"spl":"يرفض ركوب البحر للتجارة — حنينه إلى قرقرى","tags":["الحب والغزل","الجواري والنساء"],"song":1,"loc":3973},
{"id":"b306-13","bab":"الجزء 24","sec":"حنينه إلى قرقرى","page":"ج24 ص119","text":"أخبرني الحسين بن يحيى عن حماد عن أبيه قال قال أبو الذيال الحنفي خرج يحيى بن طالب الحنفي من اليمامة يريد خراسان على البريد فقال وهو بقومس\n(أقول لأصحابي ونحن بقومس ... نراوح أكتاف المحذفة الجرد)\n(بعدنا وعهد الله من أهل قرقرى ... وفيها الألى نهوى وزدنا على البعد)\nخبرنا الحسن بن علي قال حدثنا محمد بن موسى بن حماد قال حدثني عبد الله بن بشر عن أبي فراس الهيثم بن فراس الكلابي قال كنت مع أبي ونحن قاصدون اليمامة فلما رأيناها لقينا رجل فقال له أبي أين قرقرى\nقال وراءك قال فأين شعبعب قال بإزائه قال أرني ذلك فأراه إياه حتى عرفه فقال لي ارجع بنا إلى الموضع فقلت له يا أبت قد تعبنا وتعبت ركائبنا فما لك هناك\nقال إنك لأحمق ارجع ويلك فرجعت معه حتى أتى شعبعب وصار إلى الحوض والعطن وأناخ راحلته وقال لي أنخ فأنخت ونزل فنظر إلى شعبعب وقرقرى ساعة ثم اضطجع بين الحوض والعطن اضطجاعة ويده تحت خده ثم قام فركب فقلت يا أبت ما أردت بهذا فقال يا جاهل أما سمعت قول يحيى بن طالب\n(هل أجعلن يدي للخد مرفقة ... على شعبعب بين الحوض والعطن)\nفليس عجزا أن نكون قد أتينا عليهما وهما أمنية المتمني فلا ننال ما تمناه منهما وقد قدرت عليه فجعلت أعجب من قوله وفعله","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":5,"spl":"يرفض ركوب البحر للتجارة — حنينه إلى قرقرى","tags":["الرواية والكتابة"],"loc":3974},
{"id":"b306-14","bab":"الجزء 24","sec":"بعض من صفاته","page":"ج24 ص120","text":"أخبرنا محمد بن جعفر النحوي قال حدثني طلحة بن عبد الله الطلحي قال حدثنا أبو العالية عن رجل من بني حنيفة قال كان يحيى بن طالب جوادا شاعرا جميلا حمالا لأثقال قومه\nومغارمهم سمحا يقري الأضياف ما تشاء أن ترى في فتى خصلة جميلة إلا رأيتها فيه فدخلت عليه وهو في آخر رمق فسألته عن خبره وسليته وقلت له ما طابت به نفسه ثم أنشدني قوله\n(ما أنا كالقول الذي قلت إن زوى ... محلي عن مالي حذار النوائب)\n(بمنزلة بين الطريقين قابلت ... بوادي كحيل كل ماش وراكب)\n(حللت على رأس اليفاع ولم أكن ... كمن لاذ من خوف القرى بالحواجب)\n(فلا تسأل الضيفان من هم وأدنهم ... هم الناس من معروف وجه وجانب)\n(وقولوا إذا ما الضيف حل بنجوة ... ألا في سبيل الله يحيى بن طالب)\nقال أبو العالية كحيل نخل بناحية فران دون قرقرى وهناك كان منزل يحيى بن طالب صوت وقد جمع معه كل ما يغنى فيه من القصيدة\n(لعمرك إني يوم بصرى وناقتي ... لمختلفا الأهواء مصطحبان)\n(متى تحملي شوقي وشوقك تظلعي ... ومالك بالحمل الثقيل يدان)\n(ألا يا غرابي دمنة الدار خبرا ... أبالبين من عفراء تنتحبان)\n(فإن كان حقا ما تقولان فانهضا ... بلحمي إلى وكريكما فكلاني)\n(ولا يعلمن الناس ما كان ميتتي ... ولا يأكلن الطير ما تذران)\n(جعلت لعراف اليمامة حكمه ... وعراف حجر إن هما شفياني)\n(فما تركا من حيلة يعلمانها ... ولا رقية إلا وقد رقياني)\n(وقالا : شفاك الله والله ما لنا ... بما حملت منك الضلوع يدان)\n(كأن قطاة علقت بجناحها ... على كبدي من شدة الخفقان)\nلشعر لعروة بن حزام والغناء لإبراهيم الموصلي في الأربعة الأبيات الأول ثقيل أول بالوسطى ولعريب في الرابع والخامس والسادس والتاسع هزج مطلق في مجرى البنصر عن إسحاق وفي السابع وما بعده إلى آخرها ثقيل أول ينسب إلى أبي العبيس بن حمدون وإلى غيره","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":6,"spl":"بعض من صفاته — قصة حبه عفراء","tags":[],"loc":3975},
{"id":"b306-15","bab":"الجزء 24","sec":"أخبار عروة بن حزام","page":"ج24 ص122","text":"هو عروة بن حزام بن مهاصر أحد بني حزام بن ضبة بن عبد بن كبير ابن عذرة شاعر إسلامي أحد المتيمين الذين قتلهم الهوى لا يعرف له شعر إلا في عفراء بنت عمه عقال بن مهاصر وتشبيبه بها","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":6,"spl":"بعض من صفاته — قصة حبه عفراء","tags":["الحب والغزل","الجواري والنساء"],"loc":3976},
{"id":"b306-16","bab":"الجزء 24","sec":"قصة حبه عفراء","page":"ج24 ص123","text":"أخبرني بخبرها جماعة من الرواة فمنه ما أخبرني به الحسن بن علي بن محمد الآدمي قال حدثنا عمر بن محمد بن عبد الملك الزيات قال حدثني موسى بن عيسى الجعفري عن الأسباط بن عيسى العذري\nوأخبرني الحسين بن يحيى المرداسي ومحمد بن مزيد بن أبي الأزهر عن حماد بن إسحاق عن أبيه عن رجاله وأخبرني أحمد بن عبد العزيز الجوهري قال\nحدثنا عمر بن شبة وأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار عمن أسند إليه وأخبرني إبراهيم بن أيوب الصائغ عن ابن قتيبة وقد سقت رواياتهم وجمعتها\nقال الأسباط بن عيسى وروايته كأنها أتم الروايات وأشدها اتساقا أدركت شيوخ الحي يذكرون أنه كان من حديث عروة بن حزام وعفراء بنت عقال أن حزاما هلك وترك ابنه عروة صغيرا في حجر عمه عقال بن مهاصر وكانت عفراء تربا لعروة يلعبان جميعا ويكونان معا حتى ألف كل واحد منهما صاحبه إلفا شديدا وكان عقال يقول لعروة لما يرى من إلفهما أبشر فإن عفراء امرأتك إن شاء الله فكانا كذلك حتى لحقت عفراء بالنساء ولحق عروة بالرجال فأتى عروة عمة له يقال لها هند بنت مهاصر فشكا إليها ما به من حب عفراء\nوقال لها في بعض ما يقول لها يا عمة إني لأكلمك وأنا منك مستح ولكن لم أفعل هذا حتى ضقت ذرعا بما أنا فيه فذهبت عمته إلى أخيها فقالت له يا أخي قد أتيتك في حاجة أحب أن تحسن فيها الرد فإن الله يأجرك بصلة رحمك فيما أسألك فقال لها قولي فلن تسألي حاجة إلا رددتك بها قالت تزوج عروة بن أخيك بابنتك عفراء فقال ما عنه مذهب ولا هو دون رجل يرغب فيه ولا بنا عنه رغبة ولكنه ليس بذي مال وليست عليه عجلة فطابت نفس عروة وسكن بعض السكون","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":6,"spl":"بعض من صفاته — قصة حبه عفراء","tags":["الجواري والنساء","اللهو والمزاح","الرواية والكتابة"],"loc":3977},
{"id":"b306-18","bab":"الجزء 24","sec":"أم عفراء تشترط مهرا غاليا — يودع عفراء والحي","page":"ج24 ص124 – ج24 ص125","text":"وكانت أمها سيئة الرأي فيه تريد لابنتها ذا مال ووفر وكانت عرضة ذلك كمالا وجمالا فلما تكاملت سنه وبلغ أشده عرف أن رجلا من قومه ذا يسار ومال كثير يخطبها فأتى عمه فقال يا عم قد عرفت حقي وقرابتي وإني ولدك وربيت في حجرك وقد بلغني أن رجلا يخطب عفراء فإن\nأسعفته بطلبته قتلتني وسفكت دمي فأنشدك الله ورحمي وحقي فرق له وقال له يا بني أنت معدم وحالنا قريبة من حالك ولست مخرجها إلى سواك وأمها قد أبت أن تزوجها إلا بمهر غال فاضطرب واسترزق الله تعالى فجاء إلى أمها فألطفها وداراها فأبت أن تجيبه إلا بما تحتكمه من المهر وبعد أن يسوق شطره إليها فوعدها بذلك وعلم أنه لا ينفعه قرابة ولا غيرها إلا بالمال الذي يطلبونه فعمل على قصد ابن عم له موسر كان مقيما باليمن فجاء إلى عمه وامرأته فأخبرهما بعزمه فصوباه ووعداه ألا يحدثا حدثا حتى يعود\nوصار في ليلة رحيله إلى عفراء فجلس عندها ليلة هو وجواري الحي يتحدثون حتى أصبحوا ثم ودعها وودع الحي وشد على راحلته وصحبه في طريقه فتيان من بني هلال بن عامر كانا يألفانه وكان حياهم متجاورين وكان في طول سفره ساهيا يكلمانه فلا يفهم فكرة في عفراء حتى يرد القول عليه مرارا حتى قدم على ابن عمه فلقيه وعرفه حاله وما قدم له فوصله وكساه وأعطاه مائة من الإبل فانصرف بها إلى أهله وقد كان رجل من أهل الشام من أسباب بني أمية نزل في حي عفراء فنحر ووهب وأطعم وكان ذا مال عظيم فرأى عفراء وكان منزله قريبا من\nمنزلهم فأعجبته وخطبها إلى أبيها فاعتذر إليه وقال قد سميتها إلى ابن أخ لي يعدلها عندي وما إليها لغيره سبيل فقال له إني أرغبك في المهر\nقال لا حاجة لي بذلك فعدل إلى أمها فوافق عندها قبولا لبذله ورغبة في ماله فأجابته ووعدته وجاءت إلى عقال فآدته وصخبت معه وقالت أي خير في عروة حتى تحبس ابنتي عليه وقد جاءها الغني يطرق عليها بابها والله ما ندري أعروة حي أم ميت وهل ينقلب إليك بخير أم لا فتكون قد حرمت ابنتك خيرا حاضرا ورزقا سنيا فلم تزل به حتى\nقال لها فإن عاد لي خاطبا أجبته فوجهت إليه أن عد إليه خاطبا فلما كان من غد نحر جزرا عدة وأطعم ووهب وجمع الحي معه على طعامه وفيهم أبو عفراء فلما طعموا أعاد القول في الخطبة فأجابه وزوجه وساق إليه المهر وحولت إليه عفراء وقالت قبل أن يدخل بها\n(يا عرو إن الحي قد نقضوا ... عهد الإله وحاولوا الغدرا)\nي أبيات طويلة فلما كان الليل دخل بها زوجها وأقام فيهم ثلاثا ثم ارتحل بها إلى الشام وعمد أبوها إلى قبر عتيق فجدده وسواه وسأل الحي كتمان أمرها","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":7,"spl":"أم عفراء تشترط مهرا غاليا — يودع عفراء والحي — يعرف حقيقة زواج عفراء فيدخل إليها","tags":["الجواري والنساء"],"loc":3978},
{"id":"b306-19","bab":"الجزء 24","sec":"يعرف حقيقة زواج عفراء فيدخل إليها","page":"ج24 ص126","text":"وقدم عروة بعد أيام فنعاها أبوها إليه وذهب به إلى ذلك القبر فمكث\nيختلف إليه أياما وهو مضنى هالك حتى جاءته جارية من الحي فأخبرته الخبر فتركهم وركب بعض إبله وأخذ معه زادا ونفقة ورحل إلى الشام فقدمها وسأل عن الرجل فأخبر به ودل عليه فقصده وانتسب له إلى عدنان فأكرمه وأحسن ضيافته فمكث أياما حتى أنسوا به ثم\nقال لجارية لهم هل لك في يد تولينيها قالت نعم قال تدفعين خاتمي هذا إلى مولاتك فقالت سوءة لك أما تستحي لهذا القول فأمسك عنها ثم أعاد عليها\nوقال لها ويحك هي والله بنت عمي وما أحد منا إلا وهو أعز على صاحبه من الناس جميعا فاطرحي هذا الخاتم في صبوحها فإذا أنكرت عليك فقولي لها اصطبح ضيفك قبلك ولعله سقط منه فرقت الأمة وفعلت ما أمرها به فلما شربت عفراء اللبن رأت الخاتم فعرفته فشهقت ثم قالت اصدقيني عن الخبر فصدقتها فلما جاء زوجها قالت له أتدري من ضيفك هذا\nقال نعم فلان بن فلان للنسب الذي انتسب له عروة فقالت كلا والله يا هذا بل هو عروة بن حزام ابن عمي وقد كتم نفسه حياء منك وقال عمر بن شبة في خبره بل جاء ابن عم له فقال أتركتم هذا الكلب الذي قد نزل بكم هكذا في داركم يفضحكم فقال له ومن تعني قال عروة بن حزام العذري ضيفك هذا قال أو إنه لعروة بل أنت والله الكلب وهو الكريم القريب","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":7,"spl":"أم عفراء تشترط مهرا غاليا — يودع عفراء والحي — يعرف حقيقة زواج عفراء فيدخل إليها","tags":["الجواري والنساء","اللهو والمزاح","السفر والحج"],"loc":3979},
{"id":"b306-21","bab":"الجزء 24","sec":"شهامة زوج عفراء وطيبته — ينشد عراف اليمامة","page":"ج24 ص127 – ج24 ص128","text":"قالوا جميعا ثم بعث إليه فدعاه وعاتبه على كتمانه نفسه إياه وقال له بالرحب والسعة نشدتك الله إن رمت هذا المكان أبدا وخرج وتركه مع عفراء\nيتحدثان وأوصى خادما له بالاستماع عليهما وإعادة ما تسمعه منهما عليه فلما خلوا تشاكيا ما وجدا بعد الفراق فطالت الشكوى وهو يبكي أحر بكاء ثم أتته بشراب وسألته أن يشربه فقال والله ما دخل جوفي حرام قط ولا ارتكبته منذ كنت ولو استحللت حراما لكنت قد استحللته منك فأنت حظي من الدنيا وقد ذهبت مني وذهبت بعدك فما أعيش وقد أجمل هذا الرجل الكريم وأحسن وأنا مستحي منه ووالله لا أقيم بعد علمه مكاني وإني عالم أني أرحل إلى منيتي فبكت وبكى وانصرف فلما جاء زوجها أخبرته الخادمة بما دار بينهما فقال يا عفراء امنعي ابن عمك من الخروج فقالت لا يمتنع هو والله أكرم وأشد حياء من أن يقيم بعد ما جرى بينكما فدعاه\nوقال له يا أخي اتق الله في نفسك فقد عرفت خبرك وإنك إن رحلت تلفت والله لا أمنعك من الاجتماع معها أبدا ولئن شئت لأفارقنها ولأنزلن عنها لك فجزاه خيرا وأثنى عليه\nوقال إنما كان الطمع فيها آفتي والآن قد يئست وقد حملت نفسي على اليأس والصبر فإن اليأس يسلي ولي أمور ولا بد لي من رجوعي إليها فإن وجدت من نفسي قوة على ذلك وإلا رجعت إليكم وزرتكم حتى يقضي الله من أمري ما يشاء فزودوه وأكرموه وشيعوه فانصرف فلما رحل عنهم نكس بعد صلاحه وتماثله وأصابه غشي وخفقان فكان كلما أغمي عليه ألقي على وجهه خمار لعفراء زودته إياه فيفيق\nقال ولقيه في الطريق ابن مكحول عراف اليمامة فرآه وجلس عنده وسأله عما به وهل هو خبل أو جنون فقال له عروة ألك علم بالأوجاع قال نعم فأنشأ يقول\n(وما بي من خبل ولا بي جنة ... ولكن عمي يا أخي كذوب)\n(أقول لعراف اليمامة داوني ... فإنك إن داويتني لطبيب)\n(فواكبدا أمست رفاتا كأنما ... يلذعها بالموقدات طبيب)\n(عشية لا عفراء منك بعيدة ... فتسلو ولا عفراء منك قريب)\n(عشية لا خلفي مكر ولا الهوى ... أمامي ولا يهوى هواي غريب)\n(فوالله لا أنساك ما هبت الصبا ... وما عقبتها في الرياح جنوب)\n(وإني لتغشاني لذكراك هزة ... لها بين جلدي والعظام دبيب)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":8,"spl":"شهامة زوج عفراء وطيبته — ينشد عراف اليمامة — يموت فترثيه عفراء وتموت بعده","tags":["الحب والغزل","المديح","السفر والحج"],"loc":3980},
{"id":"b306-22","bab":"الجزء 24","sec":"يخاطب صاحبيه بقصته","page":"ج24 ص129","text":"وقال أيضا يخاطب صاحبيه الهلاليين بقصته\n(خليلي من عليا هلال بن عامر ... بصنعاء عوجا اليوم وانتظراني)\n(ولا تزهدا في الذخر عندي وأجملا ... فإنكما بي اليوم مبتليان)\n(ألما على عفراء إنكما غدا ... بوشك النوى والبين معترفان)\n(فيا واشيي عفراء ويحكما بمن ... وما وإلى من جئتما تشيان)\n(بمن لو أراه عانيا لفديته ... ومن لو رآني عانيا لفداني)\n(متى تكشفا عني القميص تبينا ... بي الضر من عفراء يا فتيان)\n(إذن تريا لحما قيلا وأعظما ... بلين وقلبا دائم الخفقان)\n(وقد تركتني لا أعي لمحدث ... حديثا وإن ناجيته ونجاني)\n(جعلت لعراف اليمامة حكمه ... وعراف حجر إن هما شفياني)\n(فما تركا من حيلة يعرفانها ... ولا شربة إلا وقد سقياني)\n(ورشا على وجهي من الماء ساعة ... وقاما مع العواد يبتدران)\n(وقالا : شفاك الله والله ما لنا ... بما ضمنت منك الضلوع يدان)\n(فويلي على عفراء ويلا كأنه ... على الصدر والأحشاء حد سنان)\n(أحب ابنة العذري حبا وإن نأت ... ودانيت فيها غير ما متداني)\n\n(إذا رام قلبي هجرها حال دونه ... شفيعان من قلبي لها جدلان)\nنته شارية ولحنه من الثقيل الأول\n(إذا قلت : لا قالا : بلى ثم أصبحا ... جميعا على الرأي الذي يريان)\n(تحملت من عفراء ما ليس لي به ... ولا للجبال الراسيات يدان)\n(فيا رب أنت المستعان على الذي ... تحملت من عفراء منذ زمان)\n(كأن قطاة علقت بجناحها ... على كبدي من شدة الخفقان)\nي تحملت من عفراء والذي بعده ثقيل أول يقال إنه لأبي العبيس بن حمدون","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":8,"spl":"شهامة زوج عفراء وطيبته — ينشد عراف اليمامة — يموت فترثيه عفراء وتموت بعده","tags":["اللهو والمزاح"],"song":1,"loc":3981},
{"id":"b306-23","bab":"الجزء 24","sec":"يموت فترثيه عفراء وتموت بعده","page":"ج24 ص130","text":"قال فلم يزل في طريقه حتى مات قبل أن يصل إلى حيه بثلاث ليال وبلغ عفراء خبر وفاته فجزعت جزعا شديدا وقالت ترثيه\n(ألا أيها الركب المخبون ويحكم ... بحق نعيتم عروة بن حزام)\n(فلا تهنأ الفتيان بعدك لذة ... ولا رجعوا من غيبة بسلام)\n(وقل للحبالى : لا ترجين غائبا ... ولا فرحات بعده بغلام)\nال ولم تزل تردد هذه الأبيات وتندبه بها حتى ماتت بعده بأيام قلائل","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":8,"spl":"شهامة زوج عفراء وطيبته — ينشد عراف اليمامة — يموت فترثيه عفراء وتموت بعده","tags":["الموت"],"loc":3982},
{"id":"b306-24","bab":"الجزء 24","sec":"خبر عن معرفته بتزويجها","page":"ج24 ص131","text":"وذكر عمر بن شبة في خبره أنه لم يعلم بتزويجها حتى لقي الرفقة التي هي فيها وأنه كان توجه إلى\nابن عم له بالشام لا باليمن فلما رآها وقف دهشا ثم قال\n(فما هي إلا أن أراها فجاءة ... فأبهت حتى ما أكاد أجيب)\n(وأصدف عن رأيي الذي كنت أرتئي ... وأنسى الذي أزمعت حين تغيب)\n(ويظهر قلبي عذرها ويعينها ... علي فما لي في الفؤاد نصيب)\n(وقد علمت نفسي مكان شفائها ... قريبا وهل ما لا ينال قريب ؟)\n(حلفت برب الساجدين لربهم ... خشوعا وفوق الساجدين رقيب)\n(لئن كان برد الماء حران صاديا ... إلي حبيبا إنها لحبيب)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":9,"spl":"خبر عن معرفته بتزويجها — خبر موته","tags":[],"loc":3983},
{"id":"b306-25","bab":"الجزء 24","sec":"لم ينفعه وعظ ولا دواء","page":"ج24 ص132","text":"وقال أبو زيد في خبره ثم عاد من عند عفراء إلى أهله وقد ضني ونحل وكانت له أخوات وخالة وجدة فجعلن يعظنه ولا ينفع وجئن بأبي كحيلة رباح بن شداد مولى بني ثعيلة وهو عراف حجر ليداويه فلم ينفعه دواؤه وذكر أبو زيد قصيدته النونية التي تقدم ذكرها وزاد فيها\n(وعينان ما أوفيت نشزا فتنظرا ... مآقيهما إلا هما تكفان)\n(سوى أنني قد قلت يوما لصاحبي ... ضحى وقلوصانا بنا تخدان)\n(ألا حبذا من حب عفراء واديا ... نعام وبزل حيث يلتقيان)\nوقال أبو زيد وكان عروة يأتي حياض الماء التي كانت إبل عفراء تردها فيلصق صدره بها فيقال له مهلا فإنك قاتل نفسك فاتق الله فلا يقبل حتى أشرف على التلف وأحس بالموت فجعل يقول\n(بي اليأس والداء الهيام سقيته ... فإياك عني لا يكن بك ما بيا)","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":9,"spl":"خبر عن معرفته بتزويجها — خبر موته","tags":["الموت"],"loc":3984},
{"id":"b306-26","bab":"الجزء 24","sec":"خبر موته","page":"ج24 ص133","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثني عبد الملك بن عبد العزيز بن الماجشون عن أبي السائب قال أخبرني ابن أبي عتيق قال والله إني لأسير في أرض عذرة إذا بامرأة تحمل غلاما جزلا ليس يحمل مثله فعجبت لذلك حتى أقبلت به فإذا له لحية فدعوتها فجاءت فقلت لها ويحك ما هذا فقالت هل سمعت بعروة ابن حزام فقلت نعم قالت هذا والله عروة فقلت له أنت عروة فكلمني وعيناه تذرفان وتدوران في رأسه وقال نعم أنا والله القائل\n(جعلت لعراف اليمامة حكمه ... وعراف حجر إن هما شفياني)\n(فقالا : نعم نشفي من الداء كله ... وقاما مع العواد يبتدران)\n(فعفراء أحظى الناس عندي مودة ... وعفراء عني المعرض المتواني)\nال وذهبت المرأة فما برحت من الماء حتى سمعت الصيحة فسألت\nعنها فقيل مات عروة بن حزام قال عبد الملك فقلت لأبي السائب ومن أي شيء مات أظنه شرق فقال سخنت عيناك بأي شيء شرق قلت بريقه وأنا أريد العبث بأبي السائب أفترى أحدا يموت من الحب\nقال والله لا تفلح أبدا نعم يموت خوفا أن يتوب الله عليه أخبرني عمي قال حدثنا الكراني عن العمري عن الهيثم بن عدي عن هشام بن عروة عن أبيه عن النعمان بن بشير\nقال ولاني عثمان رضي الله عنه صدقات سعد هذيم وهم بلي وسلامان وعذرة وضبة بن الحارث ووائل بنو زيد فلما قبضت الصدقة قسمتها في أهلها فلما فرغت وانصرفت بالسهمين إلى عثمان رضي الله عنه إذا أنا ببيت مفرد عن الحي فملت إليه فإذا أنا بفتى راقد في فناء البيت وإذا بعجوز من ورائه في كسر البيت فسلمت عليه فرد علي بصوت ضعيف فسألته ما لك فقال\n(كأن قطاة علقت بجناحها ... على كبدي من شدة الخفقان)\nذكر الأبيات النونية المعروفة ثم شهق شهقة خفيفة كانت نفسه فيها فنظرت إلى وجهه فإذا هو قد قضى فقلت أيتها العجوز من هذا الفتى منك قالت ابني فقلت إني أراه قد قضى فقالت وأنا والله أرى ذلك فقامت فنظرت في وجهه ثم قالت فاظ ورب محمد قال فقلت لها يا أماه من\nهو فقالت عروة بن حزام أحد بني ضبة وأنا أمه فقلت لها ما بلغ به ما أرى قالت الحب والله ما سمعت له منذ سنة كلمة ولا أنه إلا اليوم فإنه أقبل علي ثم قال\n(من كان من أمهاتي باكيا أبدا ... فاليوم إني أراني اليوم مقبوضا)\n(يسمعنينه فإني غير سامعه ... إذا علوت رقاب القوم معروضا)\nال فما برحت من الحي حتى غسلته وكفنته وصليت عليه ودفنته","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":9,"spl":"خبر عن معرفته بتزويجها — خبر موته","tags":["الحب والغزل"],"loc":3985},
{"id":"b306-27","bab":"الجزء 24","sec":"موت عفراء","page":"ج24 ص135","text":"وذكر أبو زيد عمر بن شبة في خبره هذه القصة عن عروة بن الزبير فقال هذين البيتين بحضرته\n(من كان من أخواتي باكيا أبدا ... )\nال فحضرنه فبرزن والله كأنهن الدمى فشققن جيوبهن وضربن خدودهن فأبكين كل من حضر وقضى من يومه وبلغ عفراء خبره فقامت لزوجها فقالت يا هناه قد كان من خبر ابن عمي ما كان بلغك ووالله ما عرفت منه قط إلا الحسن الجميل وقد مات في وبسببي ولا بد لي من أن أندبه وأقيم مأتما عليه\nقال افعلي فما زالت تندبه ثلاثا حتى توفيت في اليوم الرابع وبلغ معاوية بن أبي سفيان خبرهما فقال لو علمت بحال هذين الحرين الكريمين لجمعت بينهما وروي هذا الخبر عن هارون بن موسى القروي عن محمد بن الحارث المخزومي عن هشام بن عبد الله عن عكرمة عن هشام بن عروة عن أبيه\nأنه كان شاهدا ذلك اليوم ولم يذكر النعمان بن بشير في خبره وذكر هارون بن مسلمة عن غصين بن براق عن أم جميل الطائية أن عفراء كانت يتيمة في حجر عمها عمه فعرضها عليه فأباها ثم طال المدى وانصرف عروة في يوم عيد بعد أن صلى صلاة العيد فرآها وقد زينت فرأى منها جمالا بارعا وقدمت له تحفة فنال منها وهو ينظر إليها ثم خطبها إلى عمه فمنعه ذلك مكافأة لما كان من كراهته لها لما عرضها عليه وزوجها رجلا غيره فخرج بها إلى الشام وتمادى في حبها حتى قتله","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":10,"spl":"موت عفراء — طوف حول الكعبة","tags":["الموت"],"loc":3986,"partial":1},
{"id":"b306-28","bab":"الجزء 24","sec":"طوف حول الكعبة","page":"ج24 ص136","text":"حدثنا محمد بن خلف وكيع قال حدثنا عبد الله بن شبيب قال حدثنا أبو بكر بن أبي شيبة وغيره عن سليمان بن عبد العزيز بن عمران الزهري قال حدثني خارجة المكي أنه رأى عروة بن حزام يطاف به حول البيت قال فدنوت منه فقلت من أنت فقال الذي أقول\n(أفي كل يوم أنت رام بلادها ... بعينين إنساناهما غرقان)\n(ألا فاحملاني بارك الله فيكما ... إلى حاضر الروحاء ثم ذراني)\nقلت له زدني فقال لا والله ولا حرفا أخبرني علي بن سليمان الأخفش قال حدثني أبو سعيد السكري قال حدثني محمد بن حبيب قال ذكر الكلبي عن أبي صالح قال كنت مع ابن عباس بعرفة فأتاه فتيان يحملون بينهم فتى لم يبق منه إلا\nخياله فقالوا له يا بن عم رسول الله ادع له فقال وما به فقال الفتى\n(بنا من جوى الأحزان في الصدر لوعة ... تكاد لها نفس الشفيق تذوب)\n(ولكنما أبقى حشاشة معول ... على ما به عود هناك صليب)\nال ثم خفت في أيديهم فإذا هو قد مات فقال ابن عباس\n(هذا قتيل الحب لا عقل ولا قود ... )\nم ما رأيت ابن عباس سأل الله جل وعز في عشيته إلا العافية مما ابتلي به ذلك الفتى قال وسألنا عنه فقيل هذا عروة بن حزام\n(أعالي أعلى الله جدك عاليا ... وأسقى برياك العضاه البواليا)\n(أعالي ما شمس النهار إذا بدت ... بأحسن مما تحت برديك عاليا)\n(أعالي لو أن النساء ببلدة ... وأنت بأخرى لاتبعتك ماضيا)\n(أعالي لو أشكو الذي قد أصابني ... إلى غصن رطب لأصبح ذاويا)\nلشعر للقتال الكلابي وقد أدخل بعض الرواة الأول من هذه الأبيات مع أبيات سحيم عبد بني الحسحاس التي أولها\n(فما بيضة بات الظليم يحفها ... )\nي لحن واحد وذكرت ذلك في موضعه وأفردته على حدته وأتيت به على حقيقته والغناء لابن سريج ثاني ثقيل بالسبابة في مجرى الوسطى وذكر الهشامي أن فيه لأبي كامل ثاني ثقيل لا أدري أهذا يعني أم غيره ووافقه إبراهيم في لحن أبي كامل ولم يجنسه وزعم أن فيه لحنا آخر لابن عباد وفيه ثقيل أول ذكر ابن المكي أنه لمعبد وذكر الهشامي أنه ليحيى منحول إلى معبد وذكر حبش أنه لطويس وفي هذه القصيدة يقول القتال\n(أعالي أخت المالكيين نولي ... بما ليس مفقودا وفيه شفائيا)\n(أصارمتي أم العلاء وقد رمى ... بي الناس في أم العلاء المراميا)\n(أيا إخوتي لا أصبحن بمضلة ... تشيب إذا عدت علي النواصيا)\n(فراد لديك القوم واشعب بحقهم ... كما كنت لو كنت الطريد مراديا)\n(وشمر ولا تجعل عليك غضاضة ... ولا تنس يابن المضرحي بلائيا)\nلهذه القصيدة أخبار تذكر في مواضعها ها هنا إن شاء الله تعالى","topic":"أخبار أبي صخر الهذلي ونسبه","topicNo":306,"sp":10,"spl":"موت عفراء — طوف حول الكعبة","tags":["الحب والغزل"],"song":1,"loc":3987,"partialRef":{"sid":"b289-10","gi":1,"vi":0,"side":0},"partial":1},
{"id":"b307-1","bab":"الجزء 24","sec":"أخبار القتال ونسبه","page":"ج24 ص138","text":"القتال لقب غلب عليه لتمرده وفتكه واسمه عبد الله بن المضرحي ابن عامر الهصان بن كعب بن عبد الله بن أبي بكر بن كلاب بن ربيعة بن عامر ابن صعصعة ويكنى أبا المسيب وأمه عمرة بنت حرقة بن عوف بن شداد بن ربيعة بن عبد الله بن أبي بكر بن كلاب وقد ذكرها في شعره وفخر بها فقال\n(لقد ولدتني حرة ربعية ... من اللاء لم يحضرن في القيظ ذبذبا)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":0,"spl":"أخبار القتال ونسبه — شعره وهو يستتر في عماية","tags":["الجواري والنساء"],"loc":3988},
{"id":"b307-3","bab":"الجزء 24","sec":"يهرب بعد أن يقتل ابن عمه — قتل زيادا وقال","page":"ج24 ص139 – ج24 ص140","text":"نسخت من كتاب لمحمد بن داود بن الجراح خبره وذكر أن عبد الله ابن سليمان السجستاني دفعه إليه وأخبره أنه سمعه من عمر بن شبة وأجاز له\nروايته وأخبرني بأكثر رواية عمر بن شبة هذه الأخفش عن السكري عنه في أخبار اللصوص وجمعت ذلك أجمع قال عمر بن شبة حدثني حميد بن مالك بن يسار المسمعي قال حدثني شداد بن عقبة بن رافع بن زمل بن شعيب بن الحارث بن عامر بن كعب بن عبد الله بن أبي بكر بن كلاب وكانت أم رافع جنوب بنت القتال\nوحدثني شيخ من بني أبي بكر بن كلاب يكنى أبا خالد أيضا بحديث القتال قال أبو خالد كان القتال قتال ربيعة بن عبد الله بن أبي بكر بن كلاب يتحدث إلى ابنة عم له يقال لها العالية بنت عبيد الله وكان لها أخ غائب يقال له زياد بن عبيد الله فلما قدم رأى القتال يتحدث إلى أخته فنهاه وحلف لئن رآه ثانية ليقتلنه فلما كان بعد ذلك بأيام رآه عندها فأخذ السيف وبصر به القتال فخرج هاربا وخرج في إثره فلما دنا منه ناشده القتال بالله والرحم فلم يلتفت إليه فبينا هو يسعى وقد كاد يلحقه وجد رمحا مركوزا وقال السكري وجد سيفا فأخذه وعطف على زياد فقتله وقال\n(نهيت زيادا والمقامة بيننا ... وذكرته أرحام سعر وهيثم)\n(فلما رأيت أنه غير منته ... أملت له كفي بلدن مقوم)\n(ولما رأيت أنني قد قتلته ... ندمت عليه أي ساعة مندم)\nوقال أيضا\n(نهيت زيادا والمقامة بيننا ... وذكرته بالله حولا مجرما)\n(فلما رأيت أنه غير منته ... ومولاي لا يزداد إلا تقدما)\n(أملت له كفي بأبيض صارم ... حسام إذا ما صادف العظم صمما)\n(بكف امرىء لم تخدم الحي أمه ... أخي نجدات لم يكن متهضما)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":0,"spl":"أخبار القتال ونسبه — شعره وهو يستتر في عماية","tags":["الجواري والنساء","الخمر"],"loc":3989},
{"id":"b307-4","bab":"الجزء 24","sec":"شعره وهو يستتر في عماية","page":"ج24 ص141","text":"ثم خرج هاربا وأصحاب القتيل يطلبونه فمر بابنة عم له تدعى زينب متنحية عن الماء فدخل عليها فقالت له ويحك ما دهاك قال ألقي علي ثيابك فألقت عليه ثيابها وألبسته برقعها وكانت تمس حناء فأخذ الحناء فلطخ بها يديه وتنحت عنه ومر الطلب به فلما أتوا البيت قالوا وهم يظنون أنه زينب أين الخبيث فقال لهم أخذ هاهنا لغير الوجه الذي أراد أن يأخذه فلما عرف أن قد بعدوا أخذ في وجه آخر فلحق بعماية وعماية جبل فاستتر فيه وقال في ذلك\n(فمن مبلغ فتيان قومي أنني ... تسميت لما شبت الحرب زينبا)\n(وأرخيت جلبابي على نبت لحيتي ... وأبديت للناس البنان المخضبا)\nقال أيضا\n(جزى الله عنا والجزاء بكفه ... عماية خيرا أم كل طريد)\n(فما يزدهيها القوم إن نزلوا بها ... وإن أرسل السلطان كل بريد)\n(حمتني منها كل عنقاء عيطل ... وكل صفا جم القلات كؤود)\nمكث بعماية زمانا يأتيه أخ له بما يحتاج إليه وألفه نمر في الجبل كان يأوي معه في شعب","topic":"أخبار القتال ونسبه","topicNo":307,"sp":0,"spl":"أخبار القتال ونسبه — شعره وهو يستتر في عماية","tags":[],"loc":3990},
{"id":"b307-5","bab":"الجزء 24","sec":"صاحبه نمر مفترس","page":"ج24 ص142","text":"وأخبرني عبد الله بن مالك قال حدثني محمد بن حبيب عن ابن الكلبي قال كان القتال الكلابي أصاب دما فطلب به فهرب إلى جبل يقال له عماية فأقام في شعب من شعابه وكان يأوي إلىذلك الشعب نمر فراح إليه كعادته فلما رأى القتال كشر عن أنيابه ودلع لسانه فجرد القتال سيفه من جفنه فرد النمر لسانه فشام القتال سيفه فربض بإزائه وأخرج براثنه فسل القتال سهامه من كنانته فضرب بيده وزأر فأوتر القتال\nقوسه وأنبض وترها فسكن النمر وألفه فقال ابن الكلبي في هذا الخبر ووافقه عمر بن شبة في روايته كان النمر يصطاد الأروى فيجيء بما يصطاده فيلقيه بين يدي القتال فيأخذ منه ما يقوته ويلقي الباقي للنمر فيأكله وكان القتال يخرج إلى الوحش فيرمي بنبله فيصيب منه الشيء بعد الشيء فيأتي به الكهف فيأخذ لقوته بعضه ويلقي الباقي للنمر وكان القتال إذا ورد الماء قام عليه النمر حتى يشرب ثم يتنحى القتال عنه ويرد النمر فيقوم عليه القتال حتى يشرب فقال القتال في ذلك من قصيدة له\n(ولي صاحب في الغار يعدل صاحبا ... أبا الجون إلا أنه لا يعلل)\nبو الجون صديق له كان يأنس به فشبهه به وفي رواية عمر بن شبة أخي الجون فإن القتال كان له أخ اسمه الجون فشبهه به\n(كلانا عدو لا يرى في عدوه ... مهزا وكل في العدواة مجمل)\n(إذا ما التقينا كان أنس حديثنا ... صماتا وطرف كالمعابل أطحل)\n(لنا مورد قلت بأرض مضلة ... شريعتنا : لأينا جاء أول)\n(تضمنت الأروي لنا بشوائنا ... كلانا له منها سديف مخردل)\n(فأغلبه في صنعة الزاد إنني ... أميط الأذى عنه وما إن يهلل)\nي ما يسمي الله تعالى عند صيده","topic":"أخبار القتال ونسبه","topicNo":307,"sp":1,"spl":"صاحبه نمر مفترس — يعير أخواله بفعلتهم","tags":["الموت","الرواية والكتابة"],"loc":3991},
{"id":"b307-6","bab":"الجزء 24","sec":"خبر وليمة أبي سفيان","page":"ج24 ص144","text":"أخبرني اليزيدي قال حدثني عمي الفضل عن إسحاق الموصلي وأخبرني به محمد بن جعفر الصيدلاني عن الفضل عن إسحاق وأخبرني به وسواسة ابن الموصلي عن حماد عن أبيه قال قال أبو المجيب أو شداد بن عقبة دعا رجل من الحي يقال له أبو سفيان القتال الكلابي إلى وليمة فجلس القتال ينتظر رسوله ولا يأكل حتى انتصف النهار وكانت عنده فقرة من حوار فقال لامرأته\n(فإن أبا سفيان ليس بمولم ... فقومي فهاتي فقرة من حوارك)\nال إسحاق فقلت له ثم مه قال لم يأت بعده بشيء إنما أرسله يتيما فقلت له لمه أفلا أزيدك إليه بيتا آخر ليس بدونه قال بلى فقلت\n(فبيتك خير من بيوت كثيرة ... وقدرك خير من وليمة جارك)\nقال بأبي أنت وأمي والله لقد أرسلته مثلا وما انتظرت به العرب وإنك لبز طراز ما رأيت بالعراق مثله وما يلام الخليفة أن يدنيك ويؤثرك ويتملح بك ولو كان الشباب يشترى لابتعته لك بإحدى يدي ويمنى عيني\nوعلى أن فيك بحمد الله بقية تسر الودود وترغم الحسود","topic":"أخبار القتال ونسبه","topicNo":307,"sp":1,"spl":"صاحبه نمر مفترس — يعير أخواله بفعلتهم","tags":[],"loc":3992},
{"id":"b307-7","bab":"الجزء 24","sec":"كان له ابنان المسيب وعبد السلام","page":"ج24 ص144","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثني عمر بن شبة قال كان للقتال ابنان يقال لأحدهما المسيب وللآخر عبد السلام ولعبد السلام يقول\n(عبد السلام تأمل هل ترى ظعنا ... إني كبرت وأنت اليوم ذو بصر)\n(لا يبعد الله فتيانا أقول لهم ... بالأبرق الفرد لما فاتني نظري)\n(ألا ترون بأعلى عاسم ظعنا ... نكبن فحلين واستقبلن ذا بقر)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":1,"spl":"صاحبه نمر مفترس — يعير أخواله بفعلتهم","tags":["اللهو والمزاح"],"loc":3993},
{"id":"b307-8","bab":"الجزء 24","sec":"يعير أخواله بفعلتهم","page":"ج24 ص145","text":"وقال أبو زيد عمر بن شبة من رواية ابن داود عنه حدثني سعيد بن مالك قال حدثني شداد بن عقبة قال اقتتل بنو جعفر بن كلاب وبنو العجلان بن كعب بن ربيعة بن صعصعة فقتلت بنو جعفر بن كلاب رجلا من بني العجلان\nقال شداد وكانت جدة القتال أم أبيه عجلانية وهي خولة بنت قيس بن زياد بن مالك بن العجلان فاستبطأ القتال أخواله بني العجلان في الطلب بثأرهم من بني جعفر وجعل يحضهم ويحرضهم فقال في ذلك وقد بلغه أنهم أخذوا من بني جعفر دية المقتول فعيرهم بما فعلوا وقال\n(لعمري لحي من عقيل لقيتهم ... بخطمة أو لاقيتهم بالمناسك)\n(عليهم من الحوك اليماني بزة ... على أرحبيات طوال الحوارك)\n(أحب إلى نفسي وأملح عندها ... من السروات آل قيس بن مالك)\n(إذا ما لقيتم عصبة جعفرية ... كرهتم بني اللكعاء وقع النيازك)\n(فلستم بأخوالي فلا تصلبنني ... ولكنما أمي لإحدى العواتك)\n(قصار العماد لا ترى سرواتهم ... مع الوفد جثامون عند المبارك)\n(قتلتم فلما أن طلبتم عقلتم ... كذلك يؤتى بالذليل كذلك)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":1,"spl":"صاحبه نمر مفترس — يعير أخواله بفعلتهم","tags":["الجواري والنساء"],"loc":3994},
{"id":"b307-9","bab":"الجزء 24","sec":"هروبه من السجن وشعره في ذلك","page":"ج24 ص146","text":"وقال ابن حبيب خرج ابن هبار القرشي إلى الشام في تجارة أو إلى بعض بني أمية فاعترضه جماعة فيهم القتال الكلابي وغيره فقتلوه وأخذوا ماله وشاع خبره فاتهم به جماعة من بني كلاب وغيرهم من فتاك العرب فأخذوا وحبسوا أخذهم عامل مروان بن الحكم فوجههم إليه وهو بالمدينة فحبسهم ليبحث عن الأمر ثم يقتل قتلة ابن هبار فلما خشي القتال أن يعلم أمره ورأى أصحابه ليس فيهم\nغناء اغتال السجان فقتله وخرج هو ومن كان معه من السجن فهربوا فقال يذكر ذلك\n(أميم أثيبي قبل جد التزيل ... أثيبي بوصل أو بصرم معجل)\n(أميم وقد حملت ما حمل امرؤ ... وفي الصرم إحسان إذا لم تنولي)\nهي قصيدة طويلة يقول فيها\n(وإني وذكري أم حسان كالفتى ... متى ما يذق طعم المدامة يجهل)\n(ألا حبذا تلك البلاد وأهلها ... لو ان عذابي بالمدينة ينجلي)\n(برزت لها من سجن مروان غدوة ... فآنستها بالأيم لم تتحول)\n(وآنست حيا بالمطالي وجاملا ... أبابيل هطلي بين راع ومهمل)\n(نظرت وقد جلى الدجى طامس الصوى ... بسلع وقرن الشمس لم يترجل)\n(وشبت لنا نار لليلى صباحه ... يذكى بعود جمرها وقرنفل)\n(يضيء سناها وجه ليلى كأنما ... يضيء سناها وجه أدماء مغزل)\n(علا عظمها واستعجلت عن لداتها ... وشبت شبابا وهي لما تسربل)\n(ولما رأيت الباب قد حيل دونه ... وخفت لحاقا من كتاب مؤجل)\n(حملت على المكروه نفسا شريفة ... إذا وطئت لم تستقد للتذلل)\n(وكالىء باب السجن ليس بمنته ... وكان فراري منه ليس بمؤتلي)\n(إذا قلت رفهني من السجن ساعة ... وتمم بها النعمى علي وأفضل)\n(يشد وثاقا عابسا ويغلني ... إلى حلقات من عمود موصل)\n(فقلت له والسيف يعضب رأسه ... أنا ابن أبي التيماء غير المنحل)\n(عرفت نداي من نداه وشيمتي ... وريحا تغشاني إذا اشتد مسحلي)\n(تركت عتاق الطير تحجل حوله ... على عدواء كالحوار المجدل)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":2,"spl":"هروبه من السجن وشعره في ذلك — يذكر قتل ابن هبار","tags":["السفر والحج"],"loc":3995},
{"id":"b307-10","bab":"الجزء 24","sec":"يذكر قتل ابن هبار","page":"ج24 ص148","text":"وقال أبو زيد في خبره وأنشدني شداد للقتال الكلابي يذكر قتل ابن هبار\n(تركت ابن هبار لدى الباب مسندا ... وأصبح دوني شابة وأرومها)\n(بسيف امرىء ما إن أخبر باسمه ... وإن حقرت نفسي إلي همومها)\nكذا روى ابن حبيب وعمر بن شبة ونسخت من كتاب للشاهيني بخطه فيه شعر للقتال وأخبار من أخباره قال حبس القتال في دم ابن عمه الذي قتله فحبس زمانا في السجن ثم كان بين ابن هبار القرشي وبين ابن عم له من قريش إحنة فبلغ ابن عمه\nأن القتال محبوس في سجن المدينة فأتاه فقال له أرأيت إن أنا أخرجتك أتقتل ابن عمي المعروف بابن هبار قال نعم قال فإني سأرسل إليك بحديدة في طعامك فعالج بها قيدك حتى تفكه ثم البسه حتى لا تنكر فإذا خرجت إلى الوضوء فاهرب من الحرس فإني جالس لك ومخلصك ومعطيك فرسا تنجو عليه وسيفا تمتنع به فإن خلصك ذلك وإلا فأبعدك الله فقال قد رضيت\nقال وكان أهل المدينة يخرجون المحتبسين إذا أمسوا للوضوء ومعهم الحرس ففعل ما أمره به وأتاه القرشي فخلصه وآواه حتى أمسك عنه الطلب ثم جاء به وأعطاه سيفا فقتل ابن عمه المعروف بابن هبار ووهب له نجيبا فنجا عليه وقال\n(تركت ابن هبار لدى الباب مسندا ... وأصبح دوني شابة وأرومها)\n(بسيف امرىء لا أخبر الناس باسمه ... ولو أجهشت نفسي إلي همومها)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":2,"spl":"هروبه من السجن وشعره في ذلك — يذكر قتل ابن هبار","tags":["السفر والحج","الرواية والكتابة"],"loc":3996},
{"id":"b307-11","bab":"الجزء 24","sec":"خبره مع علية بنت شيبة","page":"ج24 ص149","text":"وقال أبو زيد عمر بن شبة فيما رواه عن أصحابه مر القتال بعلية بنت شيبة بن عامر بن ربيعة بن كعب بن عمرو بن عبد ابن أبي بكر وأخويها جهم وأويس فسألها زماما فأبت أن تعطيه وكانت جدتهم أم أبيهم أمة يقال لها أم حدير وكانت لقريظة بن حذيفة بن عمار بن ربيعة بن كعب بن عبد بن أبي بكر فولدت له أم هؤلاء واسمها نجيبة\nفولدت له علية هذه فقال القتال يهجوهم\n(يا قبح الله صبيانا تجيء بهم ... أم الهنيبر من زند لها واري)\n(من كل أعلم منشق مشافره ... ومؤذن ما وفى شبرا بمشبار)\n(يا ويح شيماء لم تنبذ بأحرار ... مثلي إذا ما اعتراني بعض زواري)\n(إن القريظين لم يدعوك كنتهم ... فأقصري آل مسعود ودينار)\n(أما الإماء فما يدعونني ولدا ... إذا تحدث عن نقضي وإمراري)\n(يا بنت أم حدير لو وهبت لنا ... ثنتين من محكم بالقد أوتاري)\n(إما جديدا وإما باليا خلقا ... عاد العذارى لقطعيه بأسيار)\n(لكان ردءا قليلا واعتجنت له ... صهباء مقعها حاجي وأسفاري)\n(أنا ابن أسماء أعمامي لها وأبي ... إذا ترامى بنو الإموان بالعار)\n(قد جرب الناس عودي يقرعون به ... وأقصروا عن صليب غير خوار)\n(ما أرضع الدهر إلا ثدي واضحة ... لواضح الوجه يحمي حوزة الجار)\n(يستلب القرن مهريه وصعدته ... حقا وينزع عنه ذات أزرار)\n(من آل سفيان أو ورقاء يمنعها ... تحت العجاجة طعن غير عوار)\n(يمنعها كل مذرور بصعدته ... نضح الدباء على عريان مغوار)\n(تسمع فيهم إذا استسمعت واعية ... عزف القيان وقولا يال عرعار)\n(طوال أنضية الأعناق لم يجدوا ... ريح الإماء إذا راحت بأزفار)\n(والقوم أعلم أنا من خيارهم ... إذا تقلدت عضبا غير ميشار)\n(فرا بسيري وبرد الليل يضربني ... عرض الفلاة ببنيان وأكوار)\n(أما الرواسم أطلاحا فتعرفني ... إذا اعتصبت على رأسي بأطمار)\n(ولم أنازع بني السوداء فيئهم ... والعظلميات من يعر وأمهار)\n(فكل سوداء لم تحلق عقيقتها ... كأن أصداغها يطلين بالقار)\n(لقد شرتني بنو بكر فما ربحت ... ولا رأيت عليها جزأة الشاري)\n(إن العروق إذا استنزعتها نزعت ... والعرق يسري إذا ما عرس الساري)\nخبرني حبيب بن نصر المهلبي قال حدثنا عمر بن شبة قال أنشدني الأصمعي للقتال رائية يقول فيها\n(إن العروق إذا استنزعتها نزعت ... والعرق يسري إذا ما عرس الساري)\n(قد جرب الناس عودي يقرعون به ... فأقصروا عن صليب غير خوار)\nقال لقد أحسن وأجاد لولا أنه أفسدها بقوله إذا طلب جعلا فلم\nيعطه وكان في دناءة نفسه يشبه الحطيئة وكان فارسا شاعرا شجاعا","topic":"أخبار القتال ونسبه","topicNo":307,"sp":3,"spl":"خبره مع علية بنت شيبة — هجاؤه قومه","tags":["الجواري والنساء","الوصف والطبيعة","الرواية والكتابة"],"loc":3997},
{"id":"b307-12","bab":"الجزء 24","sec":"هجاؤه قومه","page":"ج24 ص152","text":"وقال السكري في روايته زوج القتال ابنته أم قيس واسمها قطاة رذاذ بن الأخرم بن مالك بن مطرف بن كعب بن عوف بن عبد بن أبي بكر فمكثت عنده زمانا وولدت له أولادا ثم أغارها فشكت إلى أبيها فاستعدى عليه ورماه بخادمها وجاء رذاذ بالبينة على قذفه إياه بالأمة فأقيم ليضرب فلم تنتصر له عشيرته وقامت عشيرة رذاذ فاستوهبوا حده من صاحبهم فوهبه لهم وكانت عشيرة القتال تبغضه لكثرة جناياته وما يلحقها من أذاه ولا تمنعه من مكروه فقال يهجو قومه\n(إذا ما لقيتم راكبا متعمما ... فقولوا له : ما الراكب المتعمم ؟)\n(فإن يك من كعب بن عبد فإنه ... لئيم المحيا حالك اللون أدهم)\n(دعوت أبا كعب ربيعة دعوة ... وفوقي غواشي الموت تنحى وتنجم)\n(ولم أك أدري أنه ثكل أمه ... إذا قيل للأحرار في الكربة اقدموا)\n(فلو كنت من قوم كرام أعزة ... لحاميت عني حين أحمى وأضرم)\n(دعوت فكم أسمعت من كل مؤذن ... قبيح المحيا شانه الوجه والفم)\n(سوى أن آل الحارث الخير ذببوا ... بأعيط لا وغل ولا متهضم)\n(ألا إنهم قومي وقوم ابن مالك ... بنو أم ذئب وابن كبشة خيثم)\n(ولكنما قومي قماشة حاطب ... يجمعها بالكف والليل مظلم)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":3,"spl":"خبره مع علية بنت شيبة — هجاؤه قومه","tags":["الجواري والنساء","الوصف والطبيعة","الخمر"],"loc":3998},
{"id":"b307-13","bab":"الجزء 24","sec":"طلاقه إحدى زوجيه","page":"ج24 ص153","text":"قال أبو زيد وحدثني شداد بن عتبة قال كانت عند القتال بنت ورقاء بن الهيثم بن الهصان وكان جارا لبني الحصين بن الحويرث بن كعب بن عبد بن أبي بكر وكانت لها ضرة عنده يقال لها أم رياح بنت ميسرة بن نفير بن الهصان وهي أم جنوب بنت القتال فخرج القتال في سفر له فلما آب منه أقبل حين أناخ إلى أهله فوجد عند بنت ورقاء جرير بن الحصين فلما رأى جرير القتال نهض فسأل القتال عنه فقالت له امرأته أم رياح وهي صفية ويقال صفيفة بنت الحارث بن الهصان إن هذا البيت لبيت لا نزال نسمع فيه ما لا يعجبنا فطلق القتال بنت ورقاء وهي حامل فولدت له بعد طلاقها المسيب ابنه وقال السكري في خبره فقال القتال في ذلك\n(ولما أن رأيت بني حصين ... بهم جنف إلى الجارات باد)\n(خلعت عذارها ولهيت عنها ... كما خلع العذار من الجواد)\n(وقلت لها : عليك بني حصين ... فما بيني وبينك من عواد)\n(أناديها بأسفل واردات ... نكدت أبا المسيب من تنادي ؟)\nفي رواية السكري\n(أناديها وما يوم كيوم ... قضى فيه امرؤ وطر الفؤاد)\n(فرحت كأنني سيف صقيل ... وعزت جارة ابن أبي قراد)","topic":"أخبار القتال ونسبه","topicNo":307,"sp":4,"spl":"طلاقه إحدى زوجيه — جرير يضرب أنف القتال","tags":["الجواري والنساء","السفر والحج","الخمر"],"loc":3999},
{"id":"b307-14","bab":"الجزء 24","sec":"جرير يضرب أنف القتال","page":"ج24 ص154","text":"قال ثم إن كلاب بن ورقاء بن حذيفة بن عمار بن ربيعة بن كعب بن عبد بن أبي بكر نحر جزورا وصنع طعاما وجمع القوم عليه وقال كلوا أيها الفتيان فإن الطعام فيكم خير منه في الشيوخ فقال القتال أنا والله خير للفتيان منك أرى المرأة قد أعجبت أحدهم فأطلقها له وفي القوم جرير بن الحصين الذي كان وجده عند امرأته فرفع جرير السوط فضرب به أنف القتال ثم إنهم أعطوا القتال حقه فلم يقبله حتى أدرك ابناه المسيب وعبد السلام\nوقال السكري حتى احتلم ولده الأربعة وهم حبيب وعبد الرحمن وعبد الحي وعمير وأمهم ريا بنت نفر بن عامر بن كعب بن أبي بكر فحملهم على الخيل حين أظلم الليل ثم أتى بهم بني حصين فلقي لقاحا لهم ثمانين فأشمرها وبات يسوقها لا تتخلف ناقة إلا عقرها حتى حبسها على الحصى حين طلعت الشمس والحصى ماء لعبد الله بن أبي بكر فحبسها وزجرهم عنها حتى جاء بنو حصين فعقلوا له من ضربته أربعين بكرة وأهدرت الضربة وإنما أخذ الأربعين بكرة مكرها لأن قومه أجبروه على ذلك\nقال شداد وفي ابنه عبد السلام يقول\n(عبد السلام تأمل هل ترى ظعنا ... إني كبرت وأنت اليوم ذو بصر)\n(لا يبعد الله فتيانا أقول لهم ... بالأبرق الفرد لما فاتني نظري)\n(يا هل ترون بأعلى عاصم ظعنا ... نكبن فحلين واستقبلن ذا بقر)\n(صلى على عمرة الرحمن وابنتها ... ليلى وصلى على جاراتها الأخر)\n(هن الحرائر لا ربات أحمرة ... سود المحاجر لا يقرأن بالسور)\nقال أبو زيد وحدثني شداد بن عقبة قال أتى الأخرم بن مالك بن مطرف بن كعب بن عوف بن عبد بن أبي بكر ومحصن بن الحارث بن الهصان في نفر من بني أبي بكر القتال وهو محبوس فشرطوا عليه ألا يذكر عالية في شعره وهي التي ينسب بها في أشعاره فضمن ذلك لهم فأخرجوه من السجن عشاء ثم راح القوم من السجن وراح القتال معهم حتى إذا كان في بعض الليل انحدر يسوق بهم ويقول\n(قلت له يا أخرم بن مال ... )\n(إن كنت لم تزر على وصالي ... )\n(ولم تجدني فاحش الخلال ... )\n(فارفع لنا من قلص عجال ... )\n(مستوسقات كالقطا عبال ... )\n(لعلنا نطرق أم عال ... )\n(تخيري خيرت في الرجال ... )\n(بين قصير باعه تنبال ... )\n(وأمه راعية الجمال ... )\n(تبيت بين القدر والجعال ... )\n(أذاك أم منخرق السربال ... )\n(كريم عم وكريم خال ... )\n(متلف مال ومفيد مال ... )\n(ولا تزال آخر الليالي ... )\n(قلوصه تعثر في النقال ... )\nلنقال المناقلة قال شداد فنزل القوم فربطوه ثم آلوا ألا يحلوه حتى يوثق لهم بيمين ألا يذكرها أبدا ففعل وحلوه قال وهي امرأة من بني نصر بن معاوية وكانت زوجة رجل من أشراف الحي","topic":"أخبار القتال ونسبه","topicNo":307,"sp":4,"spl":"طلاقه إحدى زوجيه — جرير يضرب أنف القتال","tags":["الجواري والنساء","اللهو والمزاح"],"loc":4000,"partial":1},
{"id":"b307-15","bab":"الجزء 24","sec":"يقتل جارية عمه","page":"ج24 ص156","text":"قال وحدثني أبو خالد قال كانت لعم القتال سرية فقال له القتال لا تطأها فإنا قوم نبغض أن تلد فينا الإماء فعصاه عمه فضربها القتال بسيفه فقتلها فادعى عمه أنه قتلها وفي بطنها جنين منه فمشى القتال إليها فأخرجها من قبرها\nوذهب معه بقوم عدول وشق بطنها وأخرج رحمها حتى رأوه لا حمل فيه فكذبوا عمه فقال في ذلك\n(أنا الذي انتشلتها انتشالا ... ثم دعوت غلمة أزوالا)\n(فصدعوا وكذبوا ما قالا ... )\nال وأنشدني له أيضا\n(أنا الذي ضربتها بالمنصل ... عند القرين السائل المفضل)\n(ضربا بكفي بطل لم ينكل ... )\nقول أنا ابن فارس وابن فارس وقال السكري في روايته أراد القتال أن يتزوج بنت المحلق بن حنتم فتزوجها عبد الرحمن بن صاغر البكائي فلقي مولاة لها يقال لها جون فقال لها ما فعلت قالت تزوجها عبد الرحمن بن صاغر فقال ما لها ولعبد الرحمن فقالت له ذاك ابن فارس عراد قال فأنا ابن فارس ذي الرحل وأنا ابن فارس العوجاء ثم انصرف وأنشأ يقول\n(يا بنت جون أبانت بنت شداد ؟ ... نعم لعمري لغور بعد إنجاد)\n(لمطلع الشمس ما هذا بمنحدر ... نحو الربيع ولا هذا بإصعاد)\n(قالت فوارس عراد فقلت لها : ... وفيم أمي من فرسان عراد)\n(فرسان ذي الرحل والعوجاء وابنتها ... فدى لهم رهط رداد وشداد)\nالقصيدة التي في أولها الغناء المذكور يقولها القتال يحض أخاه وعشيرته\nعلى تخلصه من المطالبة التي يطالب بها في قتل زياد بن عبيد الله واحتمال العقل عنه ويلومهم في قعودهم عن المطالبة بثأر لهم قبل بني جعفر بن كلاب وكان السبب في ذلك فيما ذكره عمر بن شبة عن حميد بن مالك عن أبي خالد الكلابي\nقال كان عمرو بن سلمة بن سكن بن قريظ بن عبد بن أبي بكر أسلم فحسن إسلامه ووفد إلى النبي فاستقطعه حمى بين الشقراء والسعدية والسعدية ماء لعمرو بن سلمة والشقراء ماء لبني قتادة بن سكن بن قريظ وهي رحبة طولها تسعة أميال في ستة أميال فأقطعه إياها فأحماها ابنه جحوش فاسترعاه نفر من بني جعفر بن كلاب خيلهم وفيهم أحدر بن بشر بن عامر بن مالك بن جعفر فأرعاهم فحملوا نعمهم مع خيلهم بغير إذنه فأخبر بذلك فغضب وأراد إخراجهم منه فقاتلوه فكانت بينهم شجاج بالعصي والحجارة من غير رمي ولا طعان ولا تسايف فظهر عليهم جحوش ثم تداعوا إلى الصلح ومشت السفراء بينهم على أن يدعوا جميعا الجراحات فتواعدوا للصلح بالغداة وأخ لجحوش يقال له سعيد في حلقه سلعة وهو شنج متنح عن الحي عند امرأة من بني أبي بكر ترقيه فرجع إلى أخيه ومعه رجلان من قومه يقال لأحدهما محرز بن يزيد وللآخر الأخدر بن الحارث فلقيهم قراد بن الأخدر بن بشر بن عامر بن مالك وابن عمه أبو ذر بن أشهل ورجل آخر من الجعفريين فحمل قراد على سعيد فطعنه فقتله فحذف محرز ابن يزيد فرس قراد فعقرها فأردفه أبو ذر خلفه ولحقوا بأصحابهم الجعفريين\nوأوقد جحوش بن عمرو نار الحرب في رأس جرعاء طويلة فاجتمعت إليه بنو أبي بكر وخرج قراد هاربا إلى بشر بن مروان وهو ابن عمته حتى إذا كان بالقنان حميت عليه الشمس فأناخ إلى بيت امرأة من بني أسد فقال في بيتها فبينا هو نائم إذ نبهته الأسدية فقالت له ما دهاك ويحك انظر إلى الطير تحوم حول ناقتك فخرج يمشي إلى ناقته فإذا هي قد خدجت والطير تمزق ولدها فجاء فأخبرها فقالت إن لك لخبرا فأصدقني عنه فلعله أن يكون لك فيه فائدة فأخبرها أنه مطلوب بدم فهو هارب طريد قالت فهل وراءك أحد تشفق عليه فقال أخ لي يقال له جبأة وهو أحب الناس إلي قالت فإنه في أيدي أعدائك فارجع أو امض فخرج لوجهه إلى بشر\nقال ولما حرض القتال قومه على الطلب بثأرهم في الجعفريين وعيرهم بالقعود عنهم مضى جميعهم لقتال بني جعفر فقال لهم الجعفريون يا قومنا ما لنا في قتالكم حاجة وقاتل صاحبكم قد هرب وهذا أخوه جبأة فاقتلوه فرضوا بذلك فأخذوا جبأة فلما صاروا بأسود العين قدمه جحوش فضرب عنقه بأخيه سعيد","topic":"أخبار القتال ونسبه","topicNo":307,"sp":5,"spl":"يقتل جارية عمه","tags":[],"loc":4001,"partial":1},
{"id":"b307-16","bab":"الجزء 24","sec":"قصيدة تحريض","page":"ج24 ص159","text":"ومما قاله القتال في تحريضهم في قصيدة طويلة\n(فيا لأبي بكر ويا لجحوش ... ولله مولى دعوة لا يجابها)\n(أفي كل عام لا تزال كتيبة ... ذؤيبية تهفو عليكم عقابها)\n(لهم جزر منكم عبيط كأنه ... وقاع الملوك فتكها واغتصابها)\n(وأنتم عديد في حديد وشكة ... وغاب رماح يوجف القلب غابها)\n(يسقى ابن بشر ثم يمسح بطنه ... وحولي رجال ما يسوغ شرابها)\n(فما الشر كل الشر لا خير بعده ... على الناس إلا أن تذل رقابها)\n(نساء ابن بشر بدن ونساؤنا ... بلايا عليها كل يوم سلابها)\n(تنام فتقضي نومة الليل عرسه ... وأم سعيد ما تنام كلابها)\n(فإن نحن لم نغضب لهم فنثيبهم ... وكل يد موف إلينا ثوابها)\n(فنحن بنو اللائي زعمتم وأنتم ... بنو محصنات لم تدنس ثيابها)\n\n(ألا لله درك من ... فتى قوم إذا رهبوا)\n(وقالوا : من فتى للحرب ... يرقبنا ويرتقب)\n(فكنت فتاهم فيها ... إذا يدعى لها يثب)\n(ذكرت أخي فعاودني ... صداع الرأس والوصب)\n(كما يعتاد ذات البو ... بعد سلوها الطرب)\n(فدمع العين من برحاء ... ما في الصدر ينسكب)\n(كما أودى بماء الشنة ... المخروزة السرب)\n(على عبد بن زهرة طول ... هذا الليل أكتئب)\nلشعر لأبي العيال الهذلي والغناء لمعبد ثقيل أول بالخنصر في مجرى الوسطى عن إسحاق وابن المكي وغيرهما مما لا يشك فيه من صنعته وفي\nالثالث والرابع من الأبيات لمالك خفيف ثقيل عن الهشامي ومن الناس من ينسبه إلى معبد أيضا وفي الأول والثاني والثالث لمعبد أيضا خفيف رمل بالوسطى عن عمرو بن بانة وذكر الهشامي وحماد بن إسحاق أنه لابن عائشة وفيه لمالك هزج بالبنصر فيما ذكر حبش","topic":"أخبار القتال ونسبه","topicNo":307,"sp":6,"spl":"قصيدة تحريض","tags":["الوصف والطبيعة"],"song":1,"loc":4002},
{"id":"b308-2","bab":"الجزء 24","sec":"أخبار أبي العيال ونسبه — كتب قصيدة فأبكى معاوية والناس","page":"ج24 ص161 – ج24 ص162","text":"أبو العيال بن أبي عنترة وقال أبو عمرو الشيباني ابن أبي عنبر بالباء ولم أجد له نسبا يتجاوز هذا في شيء من الروايات وهو أحد بني خناعة بن سعد ابن هذيل وهذا أكثر ما وجدته من نسبه شاعر فصيح مقدم من شعراء هذيل مخضرم أدرك الجاهلية والإسلام ثم أسلم فيمن أسلم من هذيل وعمر إلى خلافة معاوية وهذه القصيدة يرثي بها ابن عمه عبد بن زهرة ويقال إنه كان أخاه لأمه أيضا\nأخبرني محمد بن العباس اليزيدي فيما قرأته عليه من شعر هذيل عن الرياشي عن الأصمعي ونسخت أيضا خبره الذي أذكره من نسخة أبي عمرو الشيباني قالا كان عبد بن زهرة غزا الروم في أيام معاوية وقال أبو عمرو خاصة مع يزيد بن معاوية في غزاته التي أغزاه أبوه إياها فأصيب في تلك الغزاة جماعة من المسلمين من رؤسائهم وحماتهم وكانت شوكة الروم شديدة قتل فيها عبد العزيز بن زرارة الكلابي وعبد بن زهرة\nالهذلي وخلق من المسلمين ثم فتح الله عليهم وكان أبو العيال حاضرا تلك الغزاة فكتب إلى معاوية قصيدة قرأها وقرئت على الناس فبكى الناس وبكى معاوية بكاء شديدا جزعا لما كتب به والقصيدة\n(من أبي العيال أخي هذيل فاعلموا ... قولي ولا تتجمجموا ما أرسل)\n(أبلغ معاوية بن صخر آية ... يهوي إليه بها البريد الأعجل)\n(والمرء عمرا فأته بصحيفة ... مني يلوح بها كتاب منمل)\nا تتجمجموا لا تكتموا والمنمل كأن سطوره آثار نمل\n(وإلى ابن سعد إن أؤخره فقد ... أزرى بنا في قسمه إذ يعدل)\n(وإلى أولي الأحلام حيث لقيتهم ... أهل البقية والكتاب المنزل)\nي ديوان الرجل حيث البقية والكتاب المنزل\n(أنا لقينا بعدكم بديارنا ... من جانب الأمراج يوما يسأل)\n(أمرا تضيق به الصدور ودونه ... مهج النفوس وليس عنه معدل)\n(في كل معترك ترى منا فتى ... يهوي كعزلاء المزادة تزغل)\nزغل تدفع دفعا\n(أو سيدا كهلا يمور دماغه ... أو جانحا في رأس رمح يسعل)\nيسعل يشرق بالدم\n(وترى النبال تعير في أقطارنا ... شمسا كأن نصالهن السنبل)\n(وترى الرماح كأنما هي بيننا ... أشطان بئر يوغلون ونوغل)\n(حتى إذا رجب تولى فانقضى ... وجماديان وجاء شهر مقبل)\n(شعبان قدرنا لوقت رحيلهم ... تسعا يعد لها الوفاء وتكمل)\n(وتجردت حرب يكون حلابها ... علقا ويمريها الغوي المبطل)\n(فاستقبلوا طرف الصعيد إقامة ... طورا وطورا رحلة فتحملوا)","topic":"أخبار أبي العيال ونسبه","topicNo":308,"sp":0,"spl":"أخبار أبي العيال ونسبه — كتب قصيدة فأبكى معاوية والناس","tags":[],"loc":4003},
{"id":"b308-3","bab":"الجزء 24","sec":"قصيدة بدر بن عامر","page":"ج24 ص164","text":"قال الأصمعي وأبو عمرو وكان أبو العيال وبدر بن عامر وهما جميعا من بني خناعة بن سعد بن هذيل يسكنان مصر وكانا خرجا إليها في خلافة عمر بن الخطاب رضوان الله عليه وأبو العيال معه ابن أخ له فبينا ابن أخي أبي العيال قائم عند قوم ينتضلون إذ أصابه سهم فقتله فكان فيه بعض الهيج فخاصم في ذلك أبو العيال واتهم بدر بن عامر وخشي أن يكون ضلعه مع خصمائه فاجتمعا في ذلك في مجلس فتناثا فقال بدر بن عامر\n(بخلت فطيمة بالذي توليني ... إلا الكلام وقل ما يجديني)\n(ولقد تناهى القلب حين نهيته ... عنها وقد يغوي إذا يعصيني)\n(أفطيم هل تدرين كم من متلف ... جاوزت لا مرعى ولا مسكون ؟)\nقول فيها\n(وأبو العيال أخي ومن يعرض له ... منكم بسوء يؤذني ويسوني)\n(إني وجدت أبا العيال ورهطه ... كالحصن شد بجندل موضون)\n(أعيا الغرانيق الدواهي دونه ... فتركنه وأبر بالتحصين)\n(أسد تفر الأسد من وثباته ... بعوارض الرجاز أو بعيون)\n(ولصوته زجل إذا آنسته ... جر الرحى بشعيره المطحون)\n(وإذا عددت ذوي الثقات وجدته ... ممن يصول به إلي يميني)\nأجابه أبو العيال فقال\n(إن البلاء لدى المقاوس معرض ... ما كان من غيب ورجم ظنون)\nي الديوان لدى المقاوس مخرج والمقوس الحبل الذي يمد به على صدور الخيل أي فما كان عنده من خير أو شر فسيخرج عند الرهان والعدو\n(وإذا الجواد ونى وأخلف منسرا ... ضمرا فلا توقن له بيقين)\n(لو كان عندك ما تقول جعلتني ... كنزا لريب الدهر غير ضنين)\n(ولقد رمقتك في المجالس كلها ... فإذا وأنت تعين من يبغيني)\n(هلا درأت الخصم حين رأيتهم ... جنفا علي بألسن وعيون)\n(وزجرت عني كل أشوس كاشح ... ترع المقالة شامخ العرنين)\nأجابه بدر بن عامر فقال\n(أقسمت لا أنسى منيحة واحد ... حتى تخيط بالبياض قروني)\n(حتى أصير بمسكن أثوي به ... لقرار ملحدة العداء شطون)\n(ومنحتني جداء حين منحتني ... شحصا بمالئة الحلاب لبون)\nلشحص ما ليس فيه لبن من المال\n(وحبوتك النصح الذي لا يشترى ... بالمال فانظر بعد ما تحبوني)\n(وتأمل السبت الذي أحذوكه ... فانظر بمثل إمامه فاحذوني)\nأجابه أبو العيال\n(أقسمت لا أنسى شباب قصيدة ... أبدا فما هذا الذي ينسيني)\n(ولسوف تنساها وتعلم أنها ... تبع لآبية العصاب زبون)\n(ومنحتني فرضيت رأي منيحتي ... فإذا بها والله طيف جنون)\n(جهراء لا تألو إذا هي أظهرت ... بصرا ولا من حاجة تغنيني)\n(قرب حذاءك قاحلا أو لينا ... فتمن في التخصير والتلسين)\n(وارجع منحتك التي أتبعتها ... هوعا وحد مذلق مسنون)\nلهما في هذا المعنى نقائض طوال يطول ذكرها وليست لها طلاوة إلا ما يستفاد في شعر أمثالهما من الفصاحة وإنما ذكرت ما ذكرت ها هنا منها لأني لم أجد لهذا الشاعر خبرا غير ما ذكرته\n(ألم تسأل بعارمة الديارا ... عن الحي المفارق أين سارا ؟)\n(بل ساءلتها فأبت جوابا ... وكيف سؤالك الدمن القفارا ؟)\nلشعر للراعي والغناء لإسحاق خفيف ثقيل أول بالبنصر عن عمرو وابن جامع وإسحاق","topic":"أخبار أبي العيال ونسبه","topicNo":308,"sp":1,"spl":"قصيدة بدر بن عامر","tags":["الحب والغزل"],"song":1,"loc":4004},
{"id":"b309-2","bab":"الجزء 24","sec":"نسب الراعي وأخباره — قصيدة يمدح بها سعيد بن عبد الرحمن","page":"ج24 ص167 – ج24 ص168","text":"هو عبيد بن حصين بن معاوية بن جندل بن قطن بن ربيعة بن عبد الله بن الحارث بن نمير بن عامر بن صعصعة بن معاوية بن بكر بن هوازن بن منصور بن عكرمة بن خصفة بن قيس بن عيلان بن مضر ويكنى أبا جندل والراعي لقب غلب عليه لكثرة وصفه الإبل وجودة نعته إياها وهو شاعر فحل من شعراء الإسلام وكان مقدما مفضلا حتى اعترض بين جرير والفرزدق فاستكفه جرير فأبى أن يكف فهجاه ففضحه وقد ذكرت بعض أخباره في ذلك مع أخبار جرير وأتممتها هنا\nوقصيدة الراعي هذه يمدح بها سعيد بن عبد الرحمن بن عتاب بن أسيد ابن أبي العيص بن أمية وفيها يقول\n(ترجي من سعيد بني لؤي ... أخي الأعياص أنواء غزارا)\n(تلقى نوأهن سرار شهر ... وخير النوء ما لقي السرارا)\n(خليل تعزب العلات عنه ... إذا ما حان يوما أن يزارا)\n(متى ما تأته ترجو نداه ... فلا بخلا تخاف ولا اعتذارا)\n(هو الرجل الذي نسبت قريش ... فصار المجد فيها حيث صارا)\n(وأنضاء تحن إلى سعيد ... طروقا ثم عجلن ابتكارا)\n(على أكوارهن بنو سبيل ... قليل نومهم إلا غرارا)\n(حمدن مزاره ولقين منه ... عطاء لم يكن عدة ضمارا)","topic":"نسب الراعي وأخباره","topicNo":309,"sp":0,"spl":"نسب الراعي وأخباره — قصيدة يمدح بها سعيد بن عبد الرحمن — يسيء إلى جرير بعد أن يقضي للفرزدق","tags":["الهجاء","المديح"],"loc":4005},
{"id":"b309-3","bab":"الجزء 24","sec":"يسيء إلى جرير بعد أن يقضي للفرزدق عليه","page":"ج24 ص169","text":"أخبرني علي بن سليمان الأخفش قال حدثنا الحسن بن الحسين السكري عن الرياشي عن الأصمعي قال وذكره المغيرة بن حجناء قال حدثني أبي عن أبيه\nقال كان راعي الإبل يقضي للفرزدق على جرير ويفضله وكان راعي الإبل قد ضخم أمره وكان من أشعر الناس فلما أكثر من ذلك خرج جرير إلى رجال من قومه فقال ألا تعجبون لهذا الرجل الذي يقضي للفرزدق علي ويفضله وهو يهجو قومه وأنا أمدحهم\nقال جرير ثم ضربت رأيي فيه فخرجت ذات يوم أمشي إليه قال ولم يركب جرير دابته وقال والله ما يسرني أن يعلم أحد بسيري إليه قال وكان لراعي الإبل وللفرزدق وجلسائهما حلقة بأعلى المربد بالبصرة يجلسون فيها قال فخرجت أتعرض لها لألقاه من حيال حيث كنت أراه\nثم إذا انصرف من مجلسه لقيته وما يسرني أن يعلم أحد حتى إذا هو قد مر على بغلة له وابنه جندل يسير وراءه راكبا مهرا له أحوى محذوف الذنب وإنسان يمشي معه ويسأله عن بعض السبب فلما استقبلته\nقلت له مرحبا بك يا أبا جندل وضربت بشمالي إلى معرفة بغلته ثم قلت يا أبا جندل إن قولك يستمع وإنك تفضل علي الفرزدق تفضيلا قبيحا وأنا أمدح قومك وهو يهجوهم وهو ابن عمي وليس منك ولا عليك كلفة في أمري معه وقد يكفيك من ذلك هين وأن تقول إذا ذكرنا كلاهما شاعر كريم فلا تحمل منه لائمة ولا مني\nقال فبينا أنا وهو كذلك وهو واقف علي لا يرد جوابا لقولي إذ لحق بالراعي ابنه جندل فرفع كرمانية معه فضرب بها عجز بغلته ثم قال أراك واقفا على كلب بني كليب كأنك تخشى منه شرا أو ترجو منه خيرا فضرب البغلة ضربة شديدة فزحمتني زحمة وقعت منها قلنسوتي فوالله لو يعوج علي الراعي لقلت سفيه غوي يعني جندلا ابنه ولكنه لا والله ما عاج علي فأخذت قلنسوتي فمسحتها وأعدتها على رأسي وقلت\n(أجندل ما تقول بنو نمير ... إذا ما الأير في است أبيك غابا)\nال فسمعت الراعي يقول لابنه أما والله لقد طرحت قلنسوته طرحة مشؤومة قال جرير ولا والله ما كانت القلنسوة بأغيظ أمره إلي لو كان عاج علي","topic":"نسب الراعي وأخباره","topicNo":309,"sp":0,"spl":"نسب الراعي وأخباره — قصيدة يمدح بها سعيد بن عبد الرحمن — يسيء إلى جرير بعد أن يقضي للفرزدق","tags":["المديح","الجواري والنساء","الخمر"],"loc":4006},
{"id":"b309-4","bab":"الجزء 24","sec":"حول قصيدته فغض الطرف","page":"ج24 ص170","text":"فانصرف جرير مغضبا حتى إذا صلى العشاء ومنزله في علية قال ارفعوا\nإلي باطية من نبيذ وأسرجوا لي فأسرجوا له وأتوه بباطية من نبيذ فجعل يهينم فسمعته عجوز في الدار فطلعت في الدرجة حتى إذا نظرت إليه فإذا هو على الفراش عريان لما هو فيه فانحدرت فقالت ضيفكم مجنون رأيت منه كذا وكذا فقالوا لها اذهبي لطيتك نحن أعلم به وبما يمارس فما زال كذلك حتى كان السحر فإذا هو يكبر قد قالها ثمانين بيتا فلما بلغ إلى قوله\n(فغض الطرف إنك من نمير ... فلا كعبا بلغت ولا كلابا)\nذاك حين كبر ثم قال أخزيته والله أخزيته ورب الكعبة ثم أصبح حتى إذا عرف أن الناس قد جلسوا في مجالسهم بالمربد وكان جرير يعرف مجلس الراعي ومجلس الفرزدق فدعا بدهن فادهن وكف رأسه وكان حسن الشعر ثم\nقال يا غلام أسرج لي فأسرج له حصانا ثم قصد مجلسهم حتى إذا كان بموضع السلام لم يسلم ثم قال يا غلام قل لعبيد الراعي أبعثتك نسوتك تكسبهن المال بالعراق والذي نفس جرير بيده لترجعن إليهن بما يسوءهن ولا يسرهن ثم اندفع في القصيدة فأنشدها فنكس الفرزدق رأسه وأطرق راعي الإبل فلو انشقت له الأرض لساخ فيها وأرم القوم حتى إذا فرغ منها سار فوثب راعي الإبل من ساعته فركب بغلته بشر وعر وتفرق أهل المجلس وصعد الراعي إلى منزله الذي كان ينزله ثم\nقال لأصحابه ركابكم ركابكم فليس لكم ها هنا مقام فضحكم والله جرير فقال له بعضهم ذلك شؤمك وشؤم جندل ابنك قال فما اشتغلوا بشيء غير ترحلهم قالوا فسرنا والله إلى أهلنا سيرا ما ساره أحد\nوهم بالشريف وهو أعلى دار بني نمير فحلف راعي الإبل أنهم وجدوا في أهلهم قول جرير\n(فغض الطرف إنك من نمير ... )\nتناشده الناس وأقسم بالله ما بلغه إنسان قط وإن لجرير لأشياعا من الجن فتشاءمت به بنو نمير وسبوه وسبوا ابنه فهم إلى الآن يتشاءمون بهم وبولدهم وأخبرني بهذا الخبر عمي قال حدثنا الكراني قال حدثني النضر بن عمرو عن أبي عبيدة بمثله أو نحو منه وقال في خبره أجئت توقر إبلك لنسائك برا وتمرا والله لأحملن إلى أعجازها كلاما يبقى ميسمه عليهن ما بقي الليل والنهار يسوؤك وإياهن استماعه وقال في خبره أيضا فلما قال\n(فغض الطرف إنك من نمير ... )\nثب وثبة دق رأسه السقف فجاء له صوت هائل وسمعت عجوز كانت ساكنة في علو ذلك الموضع صوته فصاحت يا قوم ضيفكم والله مجنون فجئنا إليه وهو يحبو ويقول غضضته والله أخزيته والله فضحته ورب الكعبة فقلت له ما لك يا أبا حزرة فأنشدنا القصيدة ثم غدا بها عليه","topic":"نسب الراعي وأخباره","topicNo":309,"sp":1,"spl":"حول قصيدته فغض الطرف — الحجاج يسأل جريرا عمن هجاه من الشعراء","tags":["اللهو والمزاح","السفر والحج"],"loc":4007,"partialRef":{"sid":"b75-2","gi":5,"vi":0,"side":0},"partial":1},
{"id":"b309-5","bab":"الجزء 24","sec":"الحجاج يسأل جريرا عمن هجاه من الشعراء","page":"ج24 ص172","text":"وذكر ابن الكلبي عن النهشلي عن مسحل بن كسيب عن جرير في خبره مع الحجاج لما سأله عمن هجاه من الشعراء قال قال لي الحجاج ما لك وللراعي فقلت أيها الأمير قدم البصرة وليس بيني وبينه عمل فبلغني أنه قال في قصيدة له\n(يا صاحبي دنا الرواح فسيرا ... غلب الفرزدق في الهجاء جريرا)\nقال أيضا في كلمة له\n(رأيت الجحش جحش بني كليب ... تيمم حوض دجلة ثم هابا)\nأتيته وقلت يا أبا جندل إنك شيخ مضر وقد بلغني تفضيلك الفرزدق علي فإن أنصفتني وفضلتني كنت أحق بذلك لأني مدحت قومك وهجاهم وذكر باقي الخبر نحوا مما ذكره من تقدم\nوقال في خبره فقلت له إن أهلك بعثوك مائرا وبئس والله المائر أنت وإنما بعثني أهلي لأقعد لهم على قارعة هذا المربد فلا يسبهم أحد إلا سببته فإن علي نذرا إن كحلت عيني بغمض حتى أخزيك فما أصبحت حتى وفيت بيميني قال ثم غدوت عليه فأخذت بعنانه فما فارقني حتى أنشدته إياها فلما بلغت قولي\n(أجندل ما تقول بنو نمير ... إذا ما الأير في است أبيك غابا ؟)\nال فأرسل يدي ثم قال يقولون شرا والله","topic":"نسب الراعي وأخباره","topicNo":309,"sp":1,"spl":"حول قصيدته فغض الطرف — الحجاج يسأل جريرا عمن هجاه من الشعراء","tags":["الهجاء","المديح"],"loc":4008},
{"id":"b309-6","bab":"الجزء 24","sec":"جرير يهجوه أمام الفرزدق","page":"ج24 ص173","text":"أخبرني علي بن سليمان الأخفش قال حدثني محمد بن الحسن بن الحرون قال قال أبو عبيدة\nأنشد جرير الراعي هذه القصيدة والفرزدق حاضر فلما بلغ فيها قوله\n(بها برص بأسفل إسكتيها ... )\nطى الفرزدق عنفقته بيده فقال جرير\n(كعنفقة الفرزدق حين شابا ... )\nقال الفرزدق أخزاك الله والله لقد علمت أنك لا تقول غيرها قال فسمع رجل كان حاضرا أبا عبيدة يحدث بها فحلف يمينا جزما أن الفرزدق لقن جريرا هذا المصراع بتغطية عنفقته ولو لم يفعل لما انتبه لذلك وما كان هذا بيتا قاله متقدما وإنما انتبه لذلك أخبرنا أبو خليفة\nقال حدثنا محمد بن سلام قال أخبرني أبو الغراف قال الذي هاج التهاجي بين جرير والراعي أن الراعي كان يسأل عن جرير والفرزدق فيقول الفرزدق أكرمهما وأشعرهما فلقيه جرير فاستعذره من نفسه ثم ذكر باقي الخبر مثل ما تقدم وزاد فيه أن الراعي قال لابنه جندل لما ضرب بغلته\n(ألم تر أن كلب بني كليب ... أراد حياض دجلة ثم هابا)\nنفرت البغلة فزحمته حتى سقطت قلنسوة جرير فقال الراعي لابنه أما والله لتكونن فعلة مشؤومة عليك وليهجوني وإياك فليته لا يجاوزنا ولا يذكر نسوتنا وعلم الراعي أنه قد أساء وندم فتزعم بنو نمير أنه حلف ألا يجيب\nجريرا سنة غضبا على ابنه وأنه مات قبل أن تمضي سنة ويقول غير بني نمير إنه كمد لما سمعها فمات كمدا","topic":"نسب الراعي وأخباره","topicNo":309,"sp":2,"spl":"جرير يهجوه أمام الفرزدق — يعترف بتفوق جرير عليه في الهجاء","tags":["الجواري والنساء","الموت"],"loc":4009,"partialRef":{"sid":"b75-15","gi":2,"vi":0,"side":0},"partial":1},
{"id":"b309-7","bab":"الجزء 24","sec":"يعترف بتفوق جرير عليه في الهجاء","page":"ج24 ص175","text":"أخبرني محمد بن العباس اليزيدي وأبو الحسن علي بن سليمان الأخفش قالا حدثنا أبو سعيد السكري عن محمد بن حبيب وإبراهيم بن سعدان عن أبي عبيدة وسعدان والمفضل وعمارة بن عقيل وأخبرنا به أبو خليفة عن محمد ابن سلام عن أبي البيداء قالوا جميعا مر راكب بالراعي وهو يتغنى\n(وعاو عوى من غير شيء رميته ... بقافية أنفاذها تقطر الدما)\n(خروج بأفواه الرواة كأنها ... قرا هندواني إذا هز صمما)\nسمعها الراعي فأتبعه رسولا وقال له من يقول هذين البيتين قال جرير فقال الراعي أألام أن يغلبني هذا والله لو اجتمع الجن والأنس على صاحب هذين البيتين ما أغنوا فيه شيئا قال ابن سلام خاصة في خبره وهذان البيتان لجرير في البعيث وكذلك كان خبره معه اعترضه في غير شيء أخبرنا أبو خليفة قال أخبرنا محمد بن سلام قال\nكان الراعي من رجال العرب ووجوه قومه وكان يقال له في شعره كأنه يعتسف الفلاة بغير دليل أي أنه لا يحتذي شعر شاعر ولا يعارضه وكان مع ذلك بذيا هجاء لعشيرته فقال له جرير\n(وقرضك في هوازن شر قرض ... تهجنهم وتمتدح الوطابا)","topic":"نسب الراعي وأخباره","topicNo":309,"sp":2,"spl":"جرير يهجوه أمام الفرزدق — يعترف بتفوق جرير عليه في الهجاء","tags":["الهجاء"],"loc":4010},
{"id":"b309-8","bab":"الجزء 24","sec":"نسب بامرأة من بني عبد شمس","page":"ج24 ص176","text":"أخبرنا أبو خليفة قال أخبرنا محمد بن سلام قال قال أبو الغراف جاور راعي الإبل بني سعد بن زيد مناة بن تميم فنسب بامرأة منهم من بني عبد شمس ثم أحد بني وابشي فقال\n(بني وابشي قد هوينا جواركم ... وما جمعتنا نية قبلها معا)\n(خليطين من حيين شتى تجاورا ... جميعا وكانا بالتفرق أمتعا)\n(أرى أهل ليلى لا يبالي أميرهم ... على حالة المحزون أن يتصدعا)\nقال فيها أيضا\n(تذكر هذا القلب هند بني سعد ... سفاها وجهلا ما تذكر من هند)\n(تذكر عهدا كان بيني وبينها ... قديما وهل أبقت لك الحرب من عهد ؟)\nي هذين البيتين لحن من الثقيل الأول بالوسطى وذكر الهشامي أنه لنبيه وذكر قمري وذكاء وجه الرزة أنه لبنان قال ابن سلام فلما بلغهم شعره أزعجوه وأصابوه بأذى فخرج عنهم وقال فيهم\n(أرى إبلي تكالأ راعياها ... مخافة جارها الدنس الذميم)\n(وقد جاورتهم فرأيت سعدا ... شعاع الأمر عازبة الحلوم)\n(مغانيم القرى سرقا إذا ما ... أجنت ظلمة الليل البهيم)\n(فأمي أرض قومك إن سعدا ... تحملت المخازي عن تميم)\nخبرنا أبو خليفة عن محمد بن سلام عن عبد القاهر بن السري قال وفد الراعي إلى عبد الملك بن مروان فقال لأهل بيته تروحوا إلى هذا الشيخ فإني أراه منجبا أخبرنا محمد بن الحسن بن دريد قال حدثنا أبو حاتم عن أبي عبيدة عن يونس قال قدم جندل بن الراعي على بلال بن أبي بردة وقد مدحه وكان يكثر ذكر أبيه ووصفه فقال له بلال أليس أبوك الذي يقول في بنت عمه وأمها امرأة من قومه\n(فلما قضت من ذي الأراك لبانة ... أرادت إلينا حاجة لا نريدها)\nقد كان بعد هجاء جرير إياه مغلبا فقال له جندل لئن كان جرير غلبه لما أمسك عنه عجزا ولكنه أقسم غضبا علي ألا يجيبه سنة فأين أنت عن قوله في عدي بن الرقاع العاملي\n(لو كنت من أحد يهجى هجوتكم ... يا بن الرقاع ولكن لست من أحد)\n(تأبى قضاعة لم تعرف لكم نسبا ... وابنا نزار وأنتم بيضة البلد)\nال فضحك بلال وقال له أما في هذا فقد صدقت","topic":"نسب الراعي وأخباره","topicNo":309,"sp":3,"spl":"نسب بامرأة من بني عبد شمس","tags":["الهجاء","المديح"],"song":1,"loc":4011},
{"id":"b309-9","bab":"الجزء 24","sec":"يترفع عن طلب حاجة لنفسه","page":"ج24 ص178","text":"أخبرني محمد بن عمران الصيرفي وعمي قالا حدثنا الحسن بن عليل العنزي قال حدثنا محمد بن عبد الرحمن عن ابن عائشة قال لما أنشد عبيد بن حصين الراعي عبد الملك بن مروان قوله\n(فإن رفعت بهم رأسا نعشتهم ... وإن لقوا مثلها من قابل فسدوا)\nال له عبد الملك فتريد ماذا قال ترد عليهم صدقاتهم فتنعشهم فقال عبد الملك هذا كثير قال أنت أكثر منه قال قد فعلت فسلني حاجة تخصك قال قد قضيت حاجتي\nقال سل حاجتك لنفسك قال ما كنت لأفسد هذه المكرمة حدثني أحمد بن محمد بن سعيد الهمذاني قال حدثنا يحيى بن الحسن العلوي قال حدثنا إسماعيل بن يعقوب عن عثمان بن نمير عن أبيه\nقال كنت عند العباس بن محمد في يوم شات فدخل عليه موسى بن عبد الله بن حسن فقال له العباس بن محمد يا أبا الحسن ما لي أراك متغيرا فقال له موسى والله إني لأعرق مما كان اليوم\nقال وما كان يا أبا الحسن فقال ذاك أن أمير المؤمنين أخرج لي وللعباس بن الحسن خمسين ألفا للعباس منها ثلاثون ألفا والله ما أجد لي ولكم مثلا إلا ما قال أخو بني العنبر وجاور\nهو وراعي الإبل في بني سعد بن زيد مناة فكانوا إذا مدحهم الراعي أخذوا مال العنبري فأعطوه الراعي فقال العنبري في ذلك\n(أيقطع موصول ويوصل جانب ... أسعد بن زيد عمرك الله أجملي)\n(فإنا بأرض ها هنا غير طائل ... متى تعلفوا بالرغم والخسف نأكل)\nال فقال له العباس إنكم نازعتم القوم ثوبهم وكان عباس وأهله أعوانا له على حذية منكم ومع ذلك فعباس الذي يقول لبنت حيدة المحاربية يرثيها\n(أتت دون الفراش فأبشرتنا ... مصيبتنا بأخت بني حداد)\n(كأن الموت لا يعني سوانا ... عشية نحوها يحدوه حادي)\n(فإن خليفة الله المرجى ... وغيث الناس في الإزم الشداد)\n(تطاول ليله فعداك حتى ... كأنك لا تثوب إلى معاد)\n(يظل - وحق ذاك - كأن شوكا ... عليه العين تطرف من سهاد)\n(فليت نفوسنا حقا فدتها ... وكل طريف مال أو تلاد)\nجندل بن الراعي شاعر وهو القائل وفي شعره هذا صنعة\n(طلبت الهوى الغوري حتى بلغته ... وسيرت في نجدية ما كفانيا)\n(وقلت لحلمي لا تنزعني عن الصبا ... وللشيب لا تذعر علي الغوانيا)\nلشعر لجندل بن الراعي والغناء لإسحاق خفيف ثقيل بالبنصر عن عمرو من جامع إسحاق وقال الهشامي وله فيه أيضا ثاني ثقيل وهو لحن مشهور وما وجدناه في جامعه ولعله شذ عنه أو غلط الهشامي في نسبته إليه\nوقال حبش فيه أيضا لإسحاق خفيف رمل","topic":"نسب الراعي وأخباره","topicNo":309,"sp":4,"spl":"يترفع عن طلب حاجة لنفسه — ملاحاة بينه وبين امرأته","tags":["الحب والغزل","المديح"],"song":1,"loc":4012}]);
window.__BOOK__['p11'].push([{"id":"b309-10","bab":"الجزء 24","sec":"ملاحاة بينه وبين امرأته","page":"ج24 ص180","text":"أخبرني جعفر بن قدامة قال حدثني أبو عبد الله الهشامي قال قال إسحاق قال أبو عبيدة كانت لجندل بن الراعي امرأة من بني عقيل وكان بخيلا فنظر إليها يوما وقد هزلت وتخدد لحمها فأنشأ يقول\n(عقيلية أما أعالي عظامها ... فعوج وأما لحمها فقليل)\nقالت مجيبة له عن ذلك\n(عقيلية حسناء أزرى بلحمها ... طعام لديك ابن الرعاء قليل)\nجعل جندل يسبها ويضربها وهي تقول قلت فأجبت وكذبت فصدقت فما غضبك\n(أصبح الحبل من سلامة ... رثا مجذذا)\n(حبذا أنت يا سلامة ... ألفين حبذا)\n(ثم ألفين مضعفيين ... وألفين هكذا)\n(في صميم الأحشاء مني ... وفي القلب قد حذا)\n(حذوة من صبابة ... تركته مفلذا)\nالشعر لعمار ذي كبار والغناء لحكم الوادي هزج بالوسطى عن الهشامي قال الهشامي وذكر يحيى المكي أنه لسليم الوادي لا لحكم","topic":"نسب الراعي وأخباره","topicNo":309,"sp":4,"spl":"يترفع عن طلب حاجة لنفسه — ملاحاة بينه وبين امرأته","tags":["الحب والغزل"],"song":1,"loc":4013},
{"id":"b310-2","bab":"الجزء 24","sec":"أخبار عمار ذي كبار ونسبه — كان أعشى ضعيف النظر","page":"ج24 ص180 – ج24 ص181","text":"هو عمار بن عمرو بن عبد الأكبر يلقب ذا كبار همداني صليبة كوفي وجدت ذلك في كتاب محمد بن عبد الله الحزنبل وكان لين الشعر ماجنا خميرا معاقرا للشراب وقد حد فيه مرات وكان يقول شعرا ظريفا يضحك من أكثره شديد التهافت جم السخف وله أشياء صالحة نذكر أجودها في هذا الموضع من أخباره ومنتخب أشعاره وكان هو وحماد الراوية ومطيع بن إياس يتنادمون ويجتمعون على شأنهم لا يفترقون وكلهم كان متهما بالزندقة\nوعمار ممن نشأ في دولة بني أمية ولم أسمع له بخبر في الدولة العباسية ولا كان مع شهوة الناس لشعره واستطابتهم إياه ينتجع أحدا ولا يبرح الكوفة لعشاء بصره وضعف نظره\nفأخبرني محمد بن مزيد قال حدثنا حماد بن إسحاق عن أبيه عن الهيثم بن عدي عن حماد الراوية وأخبرني به محمد بن خلف بن المرزبان قال حدثنا أحمد بن الهيثم الفراسي قال حدثنا العمري عن الهيثم بن عدي عن حماد الراوية ولفظ الرجلين كالمتقارب قال استقدمني هشام بن عبد الملك في خلافته وأمر لي بصلة سنية وحملان فلما دخلت عليه استنشدني قصيدة الأفوه الأودي\n(لنا معاشر لم يبنوا لقومهم ... وإن بنى قومهم ما أفسدوا عادوا)\nال فأنشدته إياها ثم استنشدني قول أبي ذؤيب الهذلي\n(أمن المنون وريبها تتوجع ... )\nأنشدته إياها ثم استنشدني قول عدي بن زيد\n(أرواح مودع أم بكور ... )\nأنشدته إياها فأمر لي بمنزل وجراية وأقمت عنده شهرا فسألني عن\nأشعار العرب وأيامها ومآثرها ومحاسن أخلاقها وأنا أخبره وأنشده ثم أمر لي بجائزة وخلعة وحملان وردني إلى الكوفة فعلمت أن أمره مقبل","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":0,"spl":"أخبار عمار ذي كبار ونسبه — كان أعشى ضعيف النظر — الوليد بن يزيد يجيزه على قصيدته","tags":["اللهو والمزاح","الخمر"],"loc":4014,"partialRef":{"sid":"b10-5","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b310-3","bab":"الجزء 24","sec":"الوليد بن يزيد يجيزه على قصيدته","page":"ج24 ص183","text":"ثم استقدمني الوليد بن يزيد بعده فما سألني عن شيء من الجد إلا مرة واحدة ثم جعلت أنشده بعدها في ذلك النحو فلا يلتفت إليه ولا يهش إلى شيء منه حتى جرى ذكر عمار بن ذي كبار فتشوقه وسأل عنه وما ظننت أن شعر عمار شيء يراد أو يعبأ به ثم قال لي هل عندك شيء من شعره فقلت نعم أنا أحفظ قصيدة له وكنت لكثرة عبثي به قد حفظتها فأنشدته قصيدته التي يقول فيها\n(حبذا أنت يا سلامة ... ألفين حبذا)\n(أشتهي منك منك ... مكانا مجنبذا)\n(مفعما في قبالة ... بين ركنين ربذا)\n(مدغما ذا مناكب ... حسن القد محتذى)\n(رابيا ذا مجسة ... أخنسا قد تقنفذا)\n(لم تر العين مثله ... في منام ولا كذا)\n(تامكا كالسنام إذ ... بذ عنه مقذذا)\n(ملء كفي ضجيعها ... نال منها تفخذا)\n(لو تأملته دهشت ... وعاينت جهبذا)\n(طيب العرف والمجسة ... واللمس هربذا)\n(فأجا فيه فيه فيه ... بأير كمثل ذا)\n(ليت أيري وليت حرك ... جميعا تآخذا)\n(فأخذ ذا بشعر ذا ... وأخذ ذا بقعر ذا)\nال فضحك الوليد حتى سقط على قفاه وصفق بيديه ورجليه وأمر بالشراب فأحضر وأمرني بالإنشاد فجعلت أنشده هذه الأبيات وأكررها عليه وهو يشرب ويصفق حتى سكر وأمر لي بحلتين وثلاثين ألف درهم فقبضتها ثم\nقال لي ما فعل عمار فقلت حي كميت قد عشي بصره وضعف جسمه ولا حراك به فأمر له بعشرة آلاف درهم فقلت له ألا أخبر أمير المؤمنين بشيء يفعله لا ضرر عليه فيه وهو أحب إلى عمار من الدنيا بحذافيرها لو سيقت إليه فقال وما ذاك\nقلت إنه لا يزال ينصرف من الحانات وهو سكران فترفعه الشرط فيضرب الحد فقد قطع بالسياط وهو لا يدع الشراب ولا يكف عنه فتكتب بألا يعرض له فكتب إلى عامله بالعراق ألا يرفع إليه أحد من الحرس عمارا في سكر ولا غيره إلا ضرب الرافع له حدين وأطلق عمارا فأخذت المال وجئته به وقلت له ما ظننت أن الله يكسب أحدا بشعرك نقيرا ولا يسأل عنه عاقل حتى كسبت بأوضع شيء قلته ثلاثين ألفا\nقال عز علي فذلك لقلة شكرك يا بن الزانية فهات نصيبي منها فقلت لقد استغنيت عن ذلك بما خصصت به ودفعت إليه العشرة آلاف درهم فقال وصلك الله يا أخي وجزاك الله خيرا ولكنها سبب هلاكي وقتلي لأني أشرب بها ما دام معي منها درهم وأضرب أبدا حتى أموت فقلت له لقد كفيتك ذلك وهذا عهد أمير المؤمنين ألا تضرب وأن يضرب كل من يرفعك حدين\nفقال والله لأنا أشد فرحا بهذا من فرحي بالمال فجزيت خيرا من أخ وصديق وقبض المال فلم يزل يشرب حتى مات وبقيته عنده","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":0,"spl":"أخبار عمار ذي كبار ونسبه — كان أعشى ضعيف النظر — الوليد بن يزيد يجيزه على قصيدته","tags":[],"loc":4015},
{"id":"b310-4","bab":"الجزء 24","sec":"خبره مع امرأته","page":"ج24 ص184","text":"نسخت من كتاب الحزنبل المشتمل على شعر عمار وأخباره أن عمارا ذا كبار كانت له امرأة يقال لها دومة بنت رباح وكان يكنيها أم عمار وكانت قد تخلقت بخلقه في شرب الشراب والمجون والسفه حتى صارت تدخل الرجال عليها وتجمعهم على الفواحش ثم حجت في إمارة يوسف بن عمر فقال لها عمار\n(اتقي الله قد حججت وتوبي ... لا يكونن ما صنعت خبالا)\n(ويك يا دوم لا تدومي على الخمر ... ولا تدخلي عليك الرجالا)\n(إن بالمصر يوسفا فاحذريه ... لا تصيري للعالمين نكالا)\n(وثقيف إن تثقفنك بحد ... لم يساو الإهاب منك قبالا)\n(قد مضى ما مضى وقد كان ما كان ... وأودى الشباب منك فزالا)","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":1,"spl":"خبره مع امرأته — طلق امرأته واشترى جارية حسناء","tags":["الجواري والنساء","الخمر","الرواية والكتابة"],"loc":4016},
{"id":"b310-5","bab":"الجزء 24","sec":"طلق امرأته واشترى جارية حسناء","page":"ج24 ص185","text":"قال فضربته دومة وخرقت ثيابه ونتفت لحيته وقالت أتجعلني غرضا لشعرك فطلقها واشترى جارية حسناء فزادت في أذاه وضربه غيرة عليه فشكاها إلى يوسف بن عمر فوجه إليها بخدم من خدمه وأمرهم بضربها وكسر نبيذها وإغرامها ثياب عمار ففعلوا ذلك وبلغوا منها الرضا لعمار فقال في ذلك عمار\n(إن عرسي لا هداها ... الله بنت لرباح)\n(كل يوم تفزع الجلاس ... منها بالصياح)\n(وربوخ حين تؤتى ... وتهيا للنكاح)\n(كلب دباغ عقور ... هر من بعد نباح)\n(ولها لون كداجي الليل ... من غير صباح)\n(ولسان صارم كالسيف ... مشحوذ النواحي)\n(يقطع الصخر ويفريه ... كما تفري المساحي)\n(عجل الله خلاصي ... من يديها وسراحي)\n(تتعب الصاحب والجار ... وتبغي من تلاحي)\n(زعمت أني بخيل ... وقد أخنى بي سماحي)\n(ورأت كفي صفرا ... من تلادي ولقاحي)\n(كذبت بنت رباح ... حين همت باطراحي)\n(حاتم لو كان حيا ... عاش في ظل جناحي)\n(ولقد أهلكت مالي ... في ارتياحي وسماحي)\n(ثم ما أبقيت شيئا ... غير زادي وسلاحي)\n(وكميت بين أشطان ... جواد ذي مراح)\n(يسبق الخيل بتقريب ... وشد كالرياح)\n(ثم غارت وتجنت ... وأجدت في الصياح)\n(لابتياعي أملح النسوان ... من فيء الرماح)\n(دمية المحراب حسنا ... وحكت بيض الأداحي)\n(هي أشهى لصدى ... الظمآن من برد القراح)\n(قلت : يا دومة بيني ... إن في البين صلاحي)\n(فأنا اليوم طليق ... من إساري ذو ارتياح)\n(لست عمن ظفرت كفي ... بها اليوم بصاح)\n(أنا مجنون بريم ... مخطف الخصر رداح)\n(مشبع الدملج والخلخال ... جوال الوشاح)\n(إن عمار بن عمرو ... ذا كبار ذو امتداح)\n(وهجاء سار في الناس ... لا يمحوه ماحي)\n(أبدا ما عاش ذو روح ... ونودي بالفلاح)\nال وكان لعمار جار يبيع الرؤوس يقال له غلام أبي داود فطرق عمارا قوم كانوا يعاشرونه ويدعونه فقالوا أطعمنا واسقنا ولم يكن عنده شيء يومئذ فبعث إلى صاحب الرؤوس يسأله أن يوجه إليه بثلاثة أرؤس ليعطيه ثمنها إذا جاءه شيء فلم يفعل فباع قميصا له واشترى للقوم ما يصلحهم وشربوا عنده فلما أصبح القوم خرج إلى المحلة وأهلها مجتمعون فأنشأ يقول\n(غلام لأبي داود ... يدعى سالق الروس)\n(وفي حجزته قمل ... كأمثال الجواميس)\n(فمن ذا يشتري الروس ... وقد عشش في الروس)\n(رؤوس قد أراحت كرؤوس ... في النواويس)\n(تحاكي أوجه الموتى ... وريحا كالكراييس)\n(ينقي القمل منهن ... إذا باع بتدليس)\nال فشاعت الأبيات في الناس فلم يقرب أحد ذلك الرجل ولا اشترى منه شيئا فقام من موضعه ذلك وعطل حانوته","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":1,"spl":"خبره مع امرأته — طلق امرأته واشترى جارية حسناء","tags":["الهجاء"],"loc":4017},
{"id":"b310-6","bab":"الجزء 24","sec":"ينفق ماله في الخمور والفجور","page":"ج24 ص188","text":"قال وحضر عمار ذو كبار مع همدان لقبض عطائه فقال له خالد بن عبد الله ما كنت لأعطيك شيئا فقال ولم أيها الأمير قال لأنك تنفق مالك في الخمور والفجور فقال هيهات ذلك وهل بقي لي أرب في هذا وأنا الذي أقول\n(أير عمار أصبح اليوم ... رخوا قد انكسر)\n(ألداء يرى به ... أم من الهم والضجر ؟)\n(أم به أخذة فقد ... تطلق الأخذة النشر)\n(فلئن كان قوس اليوم ... أو عضه الكبر)\n(فلقدما قضى ونال ... من اللذة الوطر)\n(ولقد كنت منعطفا ... وأبدا قائم الذكر)\n(وأنا اليوم لو أرى ... الحور عندي لما انتشر)\n(ساقط رأسه على ... خصيتيه به زور)\n(كلما سمته النهوض ... إلى كوة عثر)\nقال فضحك خالد وأمر له بعطائه فلما قبضه قضى منه دينه وأصلح حاله وعاد لشأنه وقال\n(أصبح اليوم أير عمار ... قد قام واسبطر)\n(أخذ الرزق فاستشاط ... قياما من البطر)\n(فهو اليوم كالشظاظ ... من النعظ والأشر)\n(يترك القرن في المكر ... صريعا وما فتر)\n(يشرع العود للطعان ... إذا انصاع ذو الخور)\n(سلم نعم الضجيع أنت ... لنا ليلة الخصر)\n(ليلة الرعد والبروق ... مع الغيم والمطر)\n(ليتني قد لقيتكم ... في خلاء من البشر)\n(فنشرنا حديثنا ... عندكم كل منتشر)\n(خاليا ليلة التمام ... بسلمى إلى السحر)\n(فهي كالدرة النقية ... والوجه كالقمر)\nال وخرج عمار في بعض أسفاره ومعه رجل يعرف بدندان فلما بلغا إلى الفرات نزلا على قرية يقال لها ناباذ وأرادا العبور فلم يجدا معبرا فقال له دندان أنا أعبرك فنزل معه فلما توسطا الفرات خلى عنه فبعد جهد ما نجا فقال عمار في ذلك\n(كاد دندان بأن يجعلني ... يوم ناباذ طعاما للسمك)\n(قلت : دندان أغثني فمضى ... وأنا أعلو وأهوي في الدرك)\n(ولقد أوقعني في ورطة ... شيبت رأسي وعاينت الملك)\n(ليت دندان بكفي أسد ... أو قتيلا ثاويا فيمن هلك)","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":2,"spl":"ينفق ماله في الخمور والفجور — خبره مع خالد القسري","tags":["اللهو والمزاح","الوصف والطبيعة"],"loc":4018},
{"id":"b310-7","bab":"الجزء 24","sec":"خبره مع خالد القسري","page":"ج24 ص190","text":"أخبرني أبو الحسن الأسدي قال حدثنا محمد بن صالح بن النطاح عن أبي اليقظان قال دخل عمار ذو كبار على خالد القسري بالكوفة فلما مثل بين يديه صاح به أيها الأمير\n(أخلقت ريطتي وأودى القميص ... وإزاري والبطن طاو خميص)\nقال خالد فنصنع ماذا ما كل من أخلقت ثيابه كسوناه فقال\n(وخلا منزلي فلا شيء فيه ... لست ممن يخشى عليه اللصوص)\nقال له خالد ذلك من سوء فعلك وشربك الخمر بما تعطاه فقال\n(واستحل الأمير حبس عطائي ... خالد إن خالدا لحريص)\nقال خالد وقد غضب على ماذا ثكلتك أمك قال\n(ذو اجتهاد على العبادة والخير ... ولكن في رزقنا تعويص)\nقال على ماذا تقبض العطاء ولا غناء فيك عن المسلمين فقال\n(رخص الله في الكتاب لذي العذر ... وما عند خالد ترخيص)\nقال أولم نرخص لذي العذر أن يقيم ويبعث مكانه رسولا فقال\n(كلف البائس الفقير بديلا ... هل له عنه معدل أو محيص)\n(العليل الكبير ذا العرج الظالع ... أعشى بعينه تلحيص)\n(يا أبا الهيثم المبارك جد لي ... بعطاء ما شانه تنغيص)\n(وبرزقي فإننا قد رزحنا ... من ضياع وللعيال بصيص)\n(كبصيص الفرخين ضمهما العش ... وغاذيهما أسير قنيص)\nال فدمعت عينا خالد فأمر له بعطائه وهذه الأبيات من قصيدة يقول فيها\n(وترى البيت مقشعرا قواء ... من نواحيه دورق وأصيص)\n(وبجاد ممزق وخوان ... ندرت رجله وأخرى رهيص)\n(ولقد كان ذا قوائم ملس ... تؤكل اللحم فوقه والخبيص)\n(شطنت هكذا شوارد بالمصر ... وعني لم يلهه التربيص)\n(وتولى في كل بحر وبر ... همه العرس فيه والتحصيص)\n(متعال علي آخر محبور ... يغاديه بطة ومصوص)\n(وشواء ملهوج ورءوس ... وصيود قد حازها التقنيص)\n(ثم لا بد يلتقي الوزن بالقسط ... لدى الحشر فاحذروا أن يبوصوا)\n(أكثروا الملك جانبا واجمعوه ... سوف يودي بذلك التنقيص)\nنسخت من كتاب الحزنبل أن عمارا وقف على عاصم بن عقيل بن جعدة بن هبيرة المخزومي فقال له\n(عاصم يا بن عقيل ... أفسح العالم باعا)\n(وارث المجد قديما ... ساميا ينمي ارتفاعا)\n(عن هبير وابنه جعدة ... فاحتل التلاعا)\nقال له عاصم أسمعت يا عمار فقل فقد أبلغت في الثناء فقال\n(اكسني أصلحك الله ... قميصا وصقاعا)\n(وأرحني من ثياب ... باليات تتداعى)\n(طال ترقيعي لها حتى ... لقد صارت رقاعا)\n(كلها لا شيء فيها ... غير قمل تتساعى)\n(لم تزل تولي الذي يرجوك ... برا واصطناعا)\nنزع عاصم جبة كانت عليه وأمر غلامه فجعل تحتها قميصا ودفعها إليه وأمر له بمائتي درهم","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":2,"spl":"ينفق ماله في الخمور والفجور — خبره مع خالد القسري","tags":["المديح","اللهو والمزاح"],"loc":4019},
{"id":"b310-8","bab":"الجزء 24","sec":"قصيدة أخرى كثيرة المرذول","page":"ج24 ص192","text":"فأما القصيدة الذالية التي استحسنها الوليد وسأل حمادا الراوية عنها فإنها كثيرة المرذول ولكنها مضحكة طيبة من الشعر المرذول وفيها يقول\n(أنت وجدا بها كمغضي ... جفون على القذى)\n(لم يقل قائل من الناس ... قولا كنحو ذا)\n(تحت حر وصلته ... صار شعرا مهذذا)\n(قول عمار ذي كبار ... فيا حسن ما احتذى)\n(عللاني بذكرها ... واسقياني محذذا)\n(تترك الأذن سخنة ... أرجوانا بها خذا)","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":3,"spl":"قصيدة أخرى كثيرة المرذول — سبب نظمه إحدى قصائده","tags":["اللهو والمزاح","الرواية والكتابة"],"loc":4020},
{"id":"b310-9","bab":"الجزء 24","sec":"متفرقات من غزله","page":"ج24 ص193","text":"ومن صالح شعره قوله\n(شجا قلبي غزال ذو ... دلال واضح السنه)\n(أسيل الخد مربوب ... وفي منطقه غنه)\n(ألا إن الغواني قد ... برى جسمي هواهنه)\n(وقالوا : شفك الحور ... هوى قلت لهم : إنه)\n(ولكني على ذاك ... معنى بأذاهنه)\n(أراح الله عمارا ... من الدنيا ومنهنه)\n(بعيدات قريبات ... فلا كان ولا كنه)\n(فقد أذهل مني العقل ... والقلب شجاهنه)\n(يمنين الأباطيل ... ويجحدن الذي قلنه)\nقوله أيضا\n(يا دوم دام صلاحكم ... وسقاك ربي صفوة الديم)\n(من كل دان مسبل هطل ... متتابع سح من الرهم)\n(ترد الوحوش إليه سارعة ... والطير أفواجا من القحم)\n(قلقلت من وجد بكم كبدي ... وصدعت صدعا غير ملتئم)\n(وتركتني لعواذلي غرضا ... كاللحم متركا على الوضم)\n(برح الخفاء وقد علمت به ... إني لحبك غير مكتتم)\n(أخفيته حتى وهى جلدي ... وبرى فؤادي واستباح دمي)\n(يا أحسن الثقلين كلهم ... وأتم من يخطو على قدم)\n(يصبو الحليم لحسن بهجتها ... ويزيده ألما إلى ألم)\n(تفتر عن سمطين من برد ... متفلج عن حسن مبتسم)\n(كالأقحوان لغب سارية ... جنح العشاء ينير في الظلم)\n(حم اللثات يروق ناظره ... ما عيب من روق ولا قصم)\n(تومي بكف رطبة خضبت ... وأنامل ينطفن كالعنم)\n(وبمقلة حوراء ساجية ... وبحاجب كالنون بالقلم)\n(والجيد منها جيد مغزلة ... تحنو إلى خشف بذي سلم)\n(وكدمية المحراب ماثلة ... والفرع جثل النبت كالحمم)\n(وكأن ريقتها إذا رقدت ... راح يفوح بأطيب النسم)","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":3,"spl":"قصيدة أخرى كثيرة المرذول — سبب نظمه إحدى قصائده","tags":[],"loc":4021},
{"id":"b310-10","bab":"الجزء 24","sec":"سبب نظمه إحدى قصائده","page":"ج24 ص195","text":"أخبرني الحرمي بن أبي العلاء قال حدثنا الحسن بن أحمد بن طالب الديناري قال حدثني إسحاق بن إبراهيم الموصلي قال قال حماد الراوية أرسل الوليد بن يزيد إلي بمائتي دينار وأمر يوسف بن عمر بحملي على البريد فقلت يسألني عن مآثر طرفيه قريش أو ثقيف فنظرت في كتابي ثقيف وقريش حتى حفظتهما فلما قدمت عليه سألني عن أشعار بلي فأنشدته منها ما حفظته ثم قال لي أنشدني في الشراب وعنده قوم من وجوه أهل الشام فأنشدته لعمار ذي كبار\n(أصبح القوم قهوة ... في أباريق تحتذى)\n(من كميت مدامة ... حبذا تلك حبذا)\n(تترك الأذن شربها ... أرجوانا بها خذا)\nقال أعدها فأعدتها فقال لخدمه خذوا آذان القوم قال فأتينا بالشراب فسقينا حتى ما درينا متى نقلنا ثم حملنا فطرحنا في دار الضيفان فما أيقظنا إلا حر الشمس وجعل شيخ من أهل الشام يشتمني ويقول فعل الله بك وفعل أنت صنعت بنا هذا\n(شطت ولم تثب الرباب ... ولعل للكلف الثواب)\n(نعب الغراب فراعني ... بالبين إذ نعب الغراب)\nروضه من الضرب الثالث من العروض الثالثة من الكامل والشعر لعبد الله بن مصعب الزبيري والغناء لحكم الوادي ثاني ثقيل بإطلاق الوتر في مجرى البنصر عن إسحاق","topic":"أخبار عمار ذي كبار ونسبه","topicNo":310,"sp":3,"spl":"قصيدة أخرى كثيرة المرذول — سبب نظمه إحدى قصائده","tags":[],"song":1,"loc":4022},
{"id":"b311-2","bab":"الجزء 24","sec":"أخبار عبد الله بن مصعب ونسبه — المهدي يعجب بشعره فيكتبه","page":"ج24 ص196 – ج24 ص197","text":"عبد الله بن مصعب بن ثابت بن عبد الله بن الزبير بن العوام بن خويلد بن أسد بن عبد العزى بن قصي بن كلاب بن مرة بن كعب بن لؤي بن غالب شاعر فصيح خطيب ذو عارضة وبيان واعتبار بين الرجال وكلام في المحافل وقد نادم أوائل الخلفاء من بني العباس وتولى لهم أعمالا وكان خرج مع محمد بن عبد الله بن الحسن بن الحسين بن علي بن أبي طالب بالمدينة على أبي جعفر المنصور فيمن خرج من آل الزبير فلما قتل محمد استتر عنه وقيل بل كان استتاره مدة يسيرة إلى أن حج أبو جعفر المنصور وآمن الناس جميعا فظهر\nأخبرني الحرمي بن أبي العلاء قال حدثنا الزبير بن بكار قال حدثنا عمي وفليح بن إسماعيل عن الربيع بن يونس بن محمد بن أبي فروة قال دخلت على المهدي وإذا هو يكتب على الأرض بفحمة قول عبد الله بن مصعب\n(فإن يحجبوها أو يحل دون وصلها ... مقالة واش أو وعيد أمير)\n(فلن يمنعوا عيني من دائم البكا ... ولن يخرجوا ما قد أجن ضميري)\n(وما برح الواشون حتى بدت لنا ... بطون الهوى مقلوبة لظهور)\n(إلى الله أشكو ما ألاقي من الجوى ... ومن نفس يعتادني وزفير)\nيقول أحسن والله عبد الله بن مصعب ما شاء وهذه الأبيات تنسب إلى المجنون أيضا وفيها بيتان فيهما غناء ليزيد حوراء خفيف رمل بالوسطى من رواية عمرو بن بانة ويقال إنه للزبير بن دحمان وذكر حبش أن فيهما لإسحاق خفيف ثقيل أول بالوسطى","topic":"أخبار عبد الله بن مصعب ونسبه","topicNo":311,"sp":0,"spl":"أخبار عبد الله بن مصعب ونسبه — المهدي يعجب بشعره فيكتبه","tags":["الحب والغزل"],"loc":4023},
{"id":"b311-3","bab":"الجزء 24","sec":"شعره في جارية يهواها","page":"ج24 ص198","text":"أخبرني أحمد بن عبد العزيز الجوهري قال حدثنا عمر بن شبة قال حدثني محمد بن الحسن بن زياد ونسخت هذا الخبر من كتاب أبي سعد العدوي عن أبي الطرماح مولى آل مصعب بن الزبير من أهل ضرية وروايته أتم أن عبد الله بن مصعب لما ولي اليمامة مر بالحوأب يوما وهو ماء لبني أبي بكر بن كلاب وهو الذي ذكره النبي لعائشة فرأى على الماء جارية منهم فهويها وهويته وقال\n(يا جمل للواله المستعبر الوصب ... ماذا تضمن من حزن ومن نصب ؟)\n(أنى أتيحت له للحين جارية ... في غير ما أمم منها ولا صقب)\n(جارية من أبي بكر كلفت بها ... ممن يحل من الحصاء والحوب)\n(من غير معرفة إلا تعرضها ... حينا لذلك إن الحين مجتلبي)\n(قامت تعرض لي عمدا فقلت لها : ... يا عمرك الله هل تدرين ما حسبي)\n(بين الحواري والصديق في نسب ... ينهى عن الفحش مثلي غير مؤتشب)\n(ولا أدب إلى الجارات منسربا ... تالله إني لعزهاة عن الريب)\nخطبها وكانت العرب لا تنكح الرجل امرأة شبب بها قبل خطبته فلم يزوجوها إياه فلما يئست منه قالت\n(إذا خدرت رجلي ذكرت ابن مصعب ... فإن قيل عبد الله خف فتورها)\n(ألا ليتني صاحبت ركب ابن مصعب ... إذا ما مطاياه اتلأبت صدورها)\n(لقد كنت أبكي واليمامة دونه ... فكيف إذا التفت عليه قصورها ؟)\nال أبو الطرماح في خبره وكان لها إخوة شرش غير فقتلوها أخبرنا ببعض هذه القصة ابن عمار عن أحمد بن سليمان بن أبي شيخ عن أبيه عن أبي عمر الزهري وذكر الشعرين جميعا والألفاظ قريبة\nوأخبرني أحمد بن عبيد الله بن عمار قال حدثني علي بن محمد النوفلي عن أبي عمر الزهري قال حدثني أبي أن عبد الله بن مصعب خاصم رجلا من ولد عمر بن الخطاب بحضرة المهدي فقال له عبد الله بن مصعب أنا ابن صفية قال هي أدنتك من الظل ولولاها لكنت ضاحيا وكنت بين الفرث والحوية قال أنا ابن الحواري قال له العمري بل أنت ابن وردان المكاري قال وكان يقال إن أمه كانت تهوى رجلا يكري الحميريقال له وردان فكان من يسبه ينسبه إليه وقال فيه الشاعر\n(أتدعى حواري الرسول سفاهة ... وأنت لوردان الحمير سليل)\nقال والله لأنا بأبي أشبه من التمرة بالتمرة والغراب بالغراب قال له العمري كذبت وإلا فأخبرني ما بال آل الزبير ثط اللحى وأنت ألحى وما لهم سمرا جعادا وأنت أحمر سبط\nقال ألي تقول هذا يا بن قتيل أبي لؤلؤة قال العمري يا بن قتيل ابن جرموز على ضلالة أتعيرني أن قتل أبي رجل نصراني وهو أمير المؤمنين قائما يصلي في محرابه وقد قتل أباك رجل مسلم بين الصفين يدفعه عن باطل ويدعوه إلى حق فأنا أقول رحم الله ابن جرموز فقل أنت رحم الله أبا لؤلؤة ثم أقبل على المهدي فقال ألا تسمع يا أمير المؤمنين ما يقول عائد الكلب في عمر بن الخطاب وقد عرفت ما كان بينه وبين ابيك العباس بن عبد المطلب وابنه عبد الله من المودة وتعلم ما بين جده عبد الله بن الزبير وبين جدك عبد الله بن العباس\nمن العداوة فأعن يا أمير المؤمنين أولياءك على أعدائك فوثب رجل من آل طلحة فقال له يا أمير المؤمنين ألا تكف هذين السفيهين عن تناول أعراض أصحاب رسول الله وتكلم الناس بينهما وتوسطوا كلامهما وأكثروا فأمر المهدي بكفهما والتفريق بينهما","topic":"أخبار عبد الله بن مصعب ونسبه","topicNo":311,"sp":1,"spl":"شعره في جارية يهواها","tags":[],"loc":4024},
{"id":"b311-4","bab":"الجزء 24","sec":"لقب عائد الكلب لبيتين قالهما","page":"ج24 ص201","text":"قال النوفلي وكان عبد الله بن مصعب يلقب عائد الكلب لقوله\n(ما لي مرضت فلم يعدني عائد ... منكم ويمرض كلبكم فأعود ؟)\n(وأشد من مرضي علي صدودكم ... وصدود عبدكم علي شديد)\nلقب عائد الكلب قال ابن عمار هكذا حفظي عن النوفلي وقد يزيد القول وينقص لحكم الوادي في هذين البيتين اللذين أولهما\n(ما لي مرضت فلم يعدني عائد ... منكم ويمرض كلبكم فأعود)\nحنان خفيف ثقيل بالوسطى عن إبراهيم وحبش ورمل بالوسطى عن الهشامي أخبرنا أحمد بن عبيد الله بن عمار قال حدثني أحمد بن سليمان بن أبي شيخ قال أنشد الأحيحي المهدي قصيدة مدحه بها وكان عبد الله بن مصعب حاضرا فحسده على إقبال المهدي عليه وكان المهدي يحبه فجعل يخاطب المهدي ويحدثه فقال له أمسك فما يشغلني كلامك عنه فقطع الأحيحي الإنشاد ثم أقبل على المهدي فقال له\n(عبد مناف أبو أبوتنا ... وعبد شمس وهاشم توم)\n(بحران خر العوام بينهما ... فالتطما والبحار تلتطم)\nفقال له المهدي كذاك هو فدع هذا المعنى وعد إلى ما كنت فيه وخجل عبد الله فما انتفع بنفسه يومئذ قال ابن عمار فحدثني بعض شيوخنا قال كنت عند مصعب بن عبد الله الزبيري يوما وقد جرى ذكر الأحيحي فأنشدته هذين البيتين فتغير لونه ثم قال لي نعم قد كان خاطب أبي بهما فأمضه فلما قمنا عنه قال لي ويحك أتنشد رجلا كنت تتعلم منه وتأخذ عنه هجاء في أبيه فقلت له دعني فإني أحببت أن أغض من كبره قال وكان في مصعب بعض ذلك\n(زارت سليمى وكان الحي قد رقدا ... ولم تخف من عدو كاشح رصدا)\n(لقد وفت لك سلمى بالذي وعدت ... لكن عقبة لم يوف الذي وعدا)\nروضه من البسيط الشعر لابن مفرغ الحميري والغناء لابن سريج رمل بالوسطى عن أحمد بن المكي وفيه لعواد لحن من كتاب إبراهيم غير مجنس وقد تقدمت أخبار ابن مفرغ مستقصاة فيما قبل هذا من الكتاب فاستغنى عن إعادتها ها هنا وإعادة شيء منها إذ كان قد مضى منها ما فيه كفاية ولله الحمد\n(ما شأن عيننك طلة الأجفان ... مما تفيض مريضة الإنسان)\n(مطروفة تهمي الدموع كأنها ... وشل تشلشل دائم التهتان)\nلشعر لعمارة بن عقيل والغناء لمتيم ثاني ثقيل بالوسطى","topic":"أخبار عبد الله بن مصعب ونسبه","topicNo":311,"sp":2,"spl":"لقب عائد الكلب لبيتين قالهما","tags":["الهجاء"],"song":2,"loc":4025},
{"id":"b312-2","bab":"الجزء 24","sec":"أخبار عمارة ونسبه — ختمت الفصاحة به","page":"ج24 ص202 – ج24 ص203","text":"عمارة هو ابن عقيل بن بلال بن جرير بن عطية بن الخطفي وقد تقدم نسبه ونسب جده في أول الكتاب ويكنى عمارة أبا عقيل شاعر مقدم فصيح وكان يسكن بادية البصرة ويزور الخلفاء في الدولة العباسية فيجزلون صلته ويمدح قوادهم وكتابهم فيحظى منهم بكل فائدة وكان النحويون بالبصرة يأخذون عنه اللغة\nأخبرني علي بن سليمان الأخفش قال سمعت محمد بن يزيد يقول ختمت الفصاحة في شعر المحدثين بعمارة بن عقيل أخبرني محمد بن عمران الصيرفي والحسن بن علي والصولي قالوا حدثنا الحسن بن عليل العنزي قال سمعت سلم بن خالد بن معاوية بن أبي عمرو بن العلاء يقول كان جدي أبو عمرو يقول ختم الشعر بذي الرمة ولو رأى جدي\nعمارة بن عقيل لعلم أنه أشعر في مذاهب الشعراء من ذي الرمة قال العنزي ولعمري لقد صدق وسمعت سلما يقول هو أشد استواء في شعره من جرير لأن جريرا سقط في شعره وضعف وما وجدوا لعمارة سقطة واحدة في شعره قال العنزي وحدثني أحمد بن الحكم بن بشر بن أبي عمرو بن العلاء قال أتيت عمارة أسأله عن شيء أكتبه عنه فقال لي من أنت فقلت أنا ابن الحكم بن بشر بن أبي عمرو بن العلاء فقال لي كان أبوك صديقي ثم أنشدني\n(بنى لكم العلاء بناء صدق ... وتعمر ذاك يا حكم بن بشر)\n(فما مدحي لكم لأصيب مالا ... ولكن مدحكم زين لشعري)","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":0,"spl":"أخبار عمارة ونسبه — ختمت الفصاحة به — بينه وبين فروة بن حميصة","tags":["عمارة","المديح"],"loc":4026},
{"id":"b312-3","bab":"الجزء 24","sec":"كان هجاء خبيث اللسان","page":"ج24 ص204","text":"حدثني محمد بن يحيى الصولي قال حدثنا أبو ذكوان قال حدثنا أبو محلم قال هجا عمارة بن عقيل امرأة ثم أتته في حاجة بعد ذلك فجعل يعتذر إليها فقالت له خفض عليك يا أخي فلو ضر الهجاء أحدا لقتلك وقتل أباك وجدك قال مؤلف هذا الكتاب وكان عمارة هجاء خبيث اللسان فهجا فروة بن حميصة الأسدي وطال التهاجي بينهما فلم يغلب أحدهما صاحبه حتى قتل فروة\nوأخبرني محمد بن يحيى قال : حدثنا أبو ذكوان قال قال لي عمارة ما هاجيت شاعرا قط إلا كفيت مؤونته في سنة أو أقل من سنة إما أن يموت أو يقتل أو أفحمه حتى هاجاني أبو الرديني العكلي فخنقني بالهجاء ثم هجا بني نمير فقال\n(أتوعدني لتقتلني نمير ... متى قتلت نمير من هجاها ؟)\nكفانيه بنو نمير فقتلوه فقتلت بنو عكل وهم يومئذ ثلاثمائة رجل أربعة آلاف رجل من بني نمير وقتلت لهم شاعرين رأس الكلب وشاعرا آخر","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":0,"spl":"أخبار عمارة ونسبه — ختمت الفصاحة به — بينه وبين فروة بن حميصة","tags":["عمارة","الهجاء"],"loc":4027},
{"id":"b312-4","bab":"الجزء 24","sec":"بينه وبين فروة بن حميصة","page":"ج24 ص205","text":"أخبرني محمد بن يحيى الصولي قال حدثني العنزي قال حدثني محمد بن عبد الله بن آدم العبدي قال حدثني عمارة بن عقيل قال كنت جالسا مع المأمون فإذا أنا بهاتف يهتف من خلفي ويقول\n(نجى عمارة منا أن مدته ... فيها تراخ وركض السابح النقل)\n(ولو ثقفناه أوهينا جوانحه ... بذابل من رماح الخط معتدل)\n(فإن أعناقكم للسيف محلبة ... وإن مالكم المرعي كالهمل)\n(إذ لا يوطن عبد الله مهجته ... على النزال ولا لصا بني حمل)\nال وهذا الشعر لفروة بن حميصة في قال فدخلني من ذلك ما الله\nيعلمه وما ظننت أن شعر فروة وقع إلى من هنالك ثم خرج علي بن هشام من المجلس وهو يضحك فقلت يا أبا الحسن أتفعل بي مثل هذا وأنا صديقك فقال ليس عليك في هذا شيء فقلت من أين وقع إليك شعر فروة قال وهل بقي كتاب إلا وهو عندي فقلت يا أمير المؤمنين أهجى في دارك وبحضرتك فضحك فقلت يا أمير المؤمنين أنصفني فقال دع هذا وأخبرني بخبر هذا الرجل وما كان بينك وبينه فأنشدته قصيدتي فيه فلما انتهيت إلى قولي\n(ما في السوية أن تجر عليهم ... وتكون يوم الروع أول صادر)\nعجب المأمون هذا البيت فقال لي المأمون ألهذه القصيدة نقيضة قلت نعم قال فهاتها فقلت له أؤذي سمعي بلساني فقال علي ذلك فانشدته إياها فلما بلغت إلى قوله\n(وابن المراغة جاحر من خوفنا ... باد بمنزلة الذليل الصاغر)\n(يخشى الرياح بأن تكون طليعة ... أو أن تحل به عقوبة قادر)\nقال لي أوجعك يا عمارة فقلت ما أوجعته به أكثر","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":0,"spl":"أخبار عمارة ونسبه — ختمت الفصاحة به — بينه وبين فروة بن حميصة","tags":["عمارة"],"loc":4028},
{"id":"b312-5","bab":"الجزء 24","sec":"بيت من شعره قتل فروة","page":"ج24 ص206","text":"أخبرني محمد قال حدثني الحسن قال حدثني محمد بن عبد الله بن آدم قال حدثني عمارة قال إنما قتل فروة قولي له\n(ما في السوية أن تجر عليهم ... وتكون يوم الروع أول صادر)\nلما أحاطت به طيء وقد كان في معاذ وموئل وكان كثير الظفر بهم كثير العفو عمن قدر عليه منهم فقالوا له والله لا عرضنا لك ولا أوصلنا إليك\nسوءا فامض لطيتك ولكن الوتر معك فإن لنا فيهم ثأرا فقال فروة فأنا إذا كما قال ابن المراغة\n(ما في السوية أن تجر عليهم ... وتكون يوم الروع أول صادر)\nفلم يزل يحمي أصحابه وينكي في القوم حتى اضطرهم إلى قتله وكان جمعهم أضعاف جمعه أخبرني محمد قال حدثني الحسن قال حدثني محمد بن عبد الله بن آدم قال قيل لعمارة أقتلت فروة فقال والله ما قتلته ولكني أقتلته أي سببت له سببا قتل به","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":1,"spl":"بيت من شعره قتل فروة — عمرو بن مسعدة يصله فيمدحه","tags":["عمارة"],"loc":4029},
{"id":"b312-6","bab":"الجزء 24","sec":"بالغ في وصف كرمه فلامه المأمون","page":"ج24 ص207","text":"أخبرني محمد قال حدثنا الحسن قال حدثني محمد بن عبد الله قال حدثني عمارة قال رحت إلى المأمون فكان ربما قرب إلي الشيء من الشراب أشربه بين يديه وكان يأمر بكتب كثير مما أقوله فقال لي يوما كيف قلت قالت مفداة ونظر إلي نظرا منكرا فقلت يا أمير المؤمنين مفداة امرأتي وكانت نظرت إلي وقد افتقرت وساءت حالي قال فكيف قلته فأنشدته\n(قالت مفداة لما أن رأت أرقي ... والهم يعتادني من طيفه لمم)\n(أنهيت مالك في الأدنين آصرة ... وفي الأباعد حتى حفك العدم)\n(فاطلب إليهم تجد ما كنت من حسن ... تسدي إليهم فقد ثابت لهم صرم)\n(فقلت : عاذلتي أكثرت لائمتي ... ولم يمت حاتم هزلا ولا هرم)\nال فنظر إلي المأمون مغضبا وقال لقد علت همتك أن ترقى بنفسك إلى هرم وقد خرج من ماله في إصلاح قومه","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":1,"spl":"بيت من شعره قتل فروة — عمرو بن مسعدة يصله فيمدحه","tags":["عمارة","اللهو والمزاح"],"loc":4030},
{"id":"b312-7","bab":"الجزء 24","sec":"عمرو بن مسعدة يصله فيمدحه","page":"ج24 ص208","text":"أخبرني محمد بن يحيى الصولي قال حدثني العنزي قال حدثني محمد بن عبد الله قال حدثنا عمارة قال استشفعت بعلي بن هشام في أن يؤذن لي في الانصراف فقال ما أفعل ذلك لأنك تنشد أمير المؤمنين إذا خلوت به وتخبره عن وقائعك وفعالك ثم تخبره أنك مظلوم وقد أخذ هذا أمير المؤمنين عليك ثم تذاكرنا فقال أما تذكر أبا الرازي حين أوقع بقومك وأقعوا به ثم تدخل على أمير المؤمنين مغضبا فتقول\n(علام نزار الخيل تفأى رؤوسنا ... وقد أسلمت مع النبي نزار)\nهي أبيات قالها حين قتلهم أبو الرازي وكان عمارة قد خرج من عند المأمون فنظر إلى رؤوس أصحابه فدخل فأنشد هذا البيت قال وأكره أن تتبعك نفسي أمير المؤمنين فيجد على من كلمه فيك فعليك بعمرو بن مسعدة وأبي عباد فإنهما يكتبان بين يدي أمير المؤمنين ويخلوان معه ويمازحانه فأتيت أبا عباد فذكرت له التشوق إلى العيال وسألته الاستئذان فصاح في وجهي وقال مقامك أحب إلى أمير المؤمنين من ظعنك وما أفعل ما يكرهه فذهبت من فوري إلى عمرو بن مسعدة فدخلت عليه وهو يختضب فشكوت إليه الأمر\nفقال يا أبا عقيل لقد أذنت لك في ساعة ما أظهر فيها لأحد ولي حاجة قلت وما هي قال ألف درهم تجعل لك في كيس تشتري بها عبدا يؤنسك في طريقك ولست أقصر فيما تحب فتلعثمت ساعة وتلكأت فقال حقا لئن لم تأخذها لا كلمتك فأخذتها وانصرفت وأنا أقول\n(عمرو بن مسعدة الكريم فعاله ... خير وأمجد من أبي عباد)\n(من لم يزمزم والداه ولم يكن ... بالري علج بطانة وحصاد)\n(بصرته سبل الرشاد فما اهتدى ... لسبيل مكرمة ولا لرشاد)\n(وعرفت إذ علقت يدي بعنانه ... أني علقت عنان غير جواد)\n(لو كان يعلم إذ يشيح تحرقي ... في كل مكرمة ولين قيادي)\n(عرف المصدق رأيه أني امرؤ ... يفني العطاء طرائفي وتلادي)\n(وأصون عرضي بالسخاء وإن غدت ... غبر المحاجر شعثا أولادي)\nخبرني محمد بن يحيى قال حدثنا العنزي قال حدثني سلم بن خالد قال أنشد عمارة قصيدة له فقال فيها الأرياح والأمطار فقال له أبو حاتم السجستاني هذا لا يجوز إنما هو الأرواح فقال لقد جذبني إليها طبعي فقال له أبو حاتم قد اعترضه علمي فقال أما تسمع قولهم رياح فقال له أبو حاتم هذا خلاف ذلك قال صدقت ورجع","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":1,"spl":"بيت من شعره قتل فروة — عمرو بن مسعدة يصله فيمدحه","tags":["عمارة"],"loc":4031},
{"id":"b312-8","bab":"الجزء 24","sec":"يمدح الواثق","page":"ج24 ص209","text":"حدثنا محمد بن يحيى قال حدثنا الحسن قال حدثنا العنزي قال\nقدم عمارة البصرة أيام الواثق فأتاه علماء البصرة وأنا معهم وكنت غلاما فأنشدهم قصيدة يمدح فيها الواثق فلما بلغ إلى قوله\n(وبقيت في السبعين أنهض صاعدا ... فمضى لداتي كلهم فتشعبوا)\nكى على ما مضى من عمره فقالوا له أملها علينا قال لا أفعل حتى أنشدها أمير المؤمنين فإني مدحت رجلا مرة بقصيدة فكتبها مني رجل ثم سبقني بها إليه ثم خرج إلى الواثق فلما قدم أتوه وأنا معهم فأملاها عليهم ثم حدثهم فقال أدخلني إسحاق بن إبراهيم على الواثق فأمر لي بخلعة وجائزة فجاءني بهما خادم فقلت قد بقي من خلعتي شيء\nقال وما بقي قلت خلع علي المأمون خلعة وسيفا فرجع إلى الواثق فأخبره فأمره بإدخالي فقال يا عمارة ما تصنع بسيف أتريد أن تقتل به بقية الأعراب الذين قتلتهم بمقالك\nقلت لا والله يا أمير المؤمنين ولكن لي شريك في نخيل لي باليمامة ربما خانني فيه فلعلي أجربه عليه فضحك وقال نأمر لك به قاطعا فدفع إلي سيفا من سيوفه أخبرنا الصولي\nقال حدثني يزيد بن محمد المهلبي قال حدثني النخعي قال لما قدم عمارة إلى بغداد قال لي كلم لي المأمون وكان النخعي من ندماء المأمون قال فما زلت أكلمه حتى أوصلته إليه فأنشده هذه القصيدة\n(حتام قلبك بالحسان موكل ... كلف بهن وهن عنه ذهل)\nلما فرغ قال لي يا نخعي ما أدري أكثر ما قال إلا أن أقيسه وقد أمرت له لكلامك فيه بعشرين ألف درهم","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":2,"spl":"يمدح الواثق","tags":["عمارة"],"loc":4032},
{"id":"b312-9","bab":"الجزء 24","sec":"يقدم خالد بن يزيد على تميم بن خزيمة","page":"ج24 ص211","text":"حدثني الصولي قال حدثني الحسن قال حدثني محمد بن عبد الله بن آدم العبدي قال كانت بنو تميم اجتمعت ببغداد على عمارة حين قال شعره الذي يقدم فيه خالد بن يزيد على تميم بن خزيمة فقالوا له قطع الله رحمك وأهانك وأذلك أتقدم غلاما من ربيعة على شيخ من بني تميم بن خزيمة وهو مع ذلك من بيت تميم ولاموه فقال\n(صهوا يا تميم إن شيبان وائل ... بطرفهم عنكم أضن وأرغب)\n(أأن سمت برذونا بطرف غضبتم ... علي وما في السوق والسوم مغضب)\n(فإن أكرمت أو أنجبت أم خالد ... فزند الرياحيين أورى وأثقب)\nال ثم حدثنا عمارة قال قال لي علي بن هشام وفيه عصبية على العرب قد علمت مكانك مني وقيامي بأمرك حتى قربك أمير المؤمنين المأمون والمائة الألف التي وصلتك أنا سببها وها هنا من بني عمك من هو أقرب إليك وأجدر أن يعينني على ما قبل أمير المؤمنين لك فقلت ومن هو\nقال تميم بن خزيمة قال قلت إيه قال وخالد بن يزيد بن مزيد قلت سآتيهما فبعث معي شاكريا من شاكريته حتى وقف بي على باب تميم فلما نظر إلي غلمانه أنكروا أمري فدنا الشاكري فقال أعلموا الأمير أن على الباب ابن جرير الشاعر جاء مسلما فتوانوا وخرج غلام أعرف أنه غلام الأمير فحجبني فدخلني من ذاك ما الله به عالم فقلت للشاكري أين منزل خالد فقال اتبعني فما كان إلا قليلا حتى وقف بي على بابه ودخل بعض\nغلمانه يطلب الإذن فما كان إلا قليلا حتى خرج في قميصه وردائه يتبعه حشمه فقال لي بعض القوم هذا خالد قد أقبل إليك قال فأردت أن أنزل إليه فوثب وثبة فإذا هو معي آخذ بعضدي يريد أن أتكىء عليه فجعلت أقول جعلني الله فداك أنزل فيأبى حتى أخذ بعضدي فأنزلني وأدخلني وقرب إلي الطعام والشراب فأكلت وشربت وأخرج إلي خمسة آلاف درهم\nوقال يا أبا عقيل ما آكل إلا بالدين وأنا على جناح من ولاية أمير المؤمنين فإن صحت لي لم أدع أن أغنيك وهذه خمسة أثواب خز قد آثرتك بها كنت قد ادخرتها قال عمارة فخرجت وأنا أقول\n(أأترك إن قلت دراهم خالد ... زيارته إني إذا للئيم)\n(فليت بثوبيه لنا كان خالد ... وكان لبكر بالثراء تميم)\n(فيصبح فينا سابق متمهل ... ويصبح في بكر أغم بهيم)\n(فقد يسلع المرء اللئيم اصطناعه ... ويعتل نقد المرء وهو كريم)\nال اليزيدي يسلع أي تكثر سلعته والسلعة المتاع أخبرني الصولي قال حدثني الحسن قال حدثني محمد بن عبد الله قال حدثني عمارة قال لما بلغ خالد بن يزيد هذا الشعر\nقال لي يا أبا عقيل أبلغك أن أهلي يرتضون مني ببديل كما رضيت بنو تميم بتميم بن خزيمة فقلت إنما طلبت حظ نفسي وسقت مكرمة إلى أهلي لو جاز ذلك فما زال يضاحكني أخبرني الصولي قال حدثنا الحسن قال سمعت عبد الله بن محمد النباحي يقول سمعت عمارة يقول ما هجيت بشيء أشد علي من بيت فروة\n(وابن المراغة جاحر من خوفنا ... بالوشم منزلة الذليل الصاغر)\nخبرني محمد بن يحيى قال حدثني الحسن بن عليل العنزي قال حدثني النباجي قال لما قال عمارة يمدح خالدا\n(تأبى خلائق خالد وفعاله ... إلا تجنب كل أمر عائب)\n(فإذا حضرت الباب عند غدائه ... أذن الغداء لنا برغم الحاجب)\nقيه خالد فقال له أوجبت والله علي حقا ما حييت","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":3,"spl":"يقدم خالد بن يزيد على تميم بن خزيمة — أجود شعره ما هجا به الأشراف","tags":["عمارة"],"loc":4033},
{"id":"b312-10","bab":"الجزء 24","sec":"أجود شعره ما هجا به الأشراف","page":"ج24 ص213","text":"قال العنزي وسمعت سلم بن خالد يقول قلت لعمارة ما أجود شعرك قال ما هجوت به الأشراف فقلت ومن هم قال بنو أسد وهل هاجاني أشرف من بني أسد قال العنزي وحدثني أبو الأشهب الأسدي من ولد بشر بن أبي خازم قال لما أنشد فروة بن حميصة قول عمارة فيه\n(ما في السوية أن تجر عليهم ... وتكون يوم الروع أول صادر)\nال والله ما قتلني إلا هذا البيت فلما تكاثرت عليه الخيل يوم قتل قيل له انج بنفسك قال كلا والله لا حققت قول عمارة فصبر حتى قتل وكان فروة من أحسن الناس وجها وشعرا وقدا لو كان امرأة لانتحرت عليه بنو أسد","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":3,"spl":"يقدم خالد بن يزيد على تميم بن خزيمة — أجود شعره ما هجا به الأشراف","tags":["عمارة","الجواري والنساء"],"loc":4034},
{"id":"b312-11","bab":"الجزء 24","sec":"هجاؤه أكرم هجاء","page":"ج24 ص214","text":"أخبرني محمد بن يحيى الصولي قال حدثني العنزي قال حدثني علي بن مسلم قال أنشدت يعقوب بن السكيت قصيدة عمارة التي رد فيها على رجاء بن هارون أخي بني تيم اللات بن ثعلبة التي أولها\n(حي الديار كأنها أسطار ... بالوحي يدرس صحفها الأحبار)\n(لعب البلى بجديدها وتنفست ... عرصاتها الأرواح والأمطار)\nال أبو علي وهذا البيت الذي أخطأ فيه عمارة فقال الأرياح فرده عليه أبو حاتم السجستاني وهو يتغيظ فلما بلغ إلى قوله\n(وجموع أسعد إذ تعض رؤوسهم ... بيض يطير لوقعهن شرار)\n(حتى إذا عزموا الفرار وأسلموا ... بيضا حواصن ما بهن قرار)\n(لحقت حفيظتنا بهن ولم نزل ... دون النساء إذا فزعن نغار)\nال ابن السكيت لله دره ما سمعت هجاء قط أكرم من هذا أخبرني محمد بن يحيى قال : وفد عمارة على المتوكل فعمل فيه شعرا فلم يأت بشيء ولم يقارب وكان عمارة قد اختل وانقطع في آخر عمره فصار إلى إبراهيم بن سعدان المؤدب وكان قد\nروى عنه شعره القديم كله فقال له أحب أن تخرج إلي أشعاري كلها لأنقل ألفاظها إلى مدح الخليفة فقال لا والله أو تقاسمني جائزتك فحلف له على ذلك فأخرج إليه شعره وقلب قصيدة إلى المتوكل وأخذ بها منه عشرة آلاف درهم وأعطى إبراهيم بن سعدان نصفها والله أعلم\n\n(تفرق أهلي من مقيم وظاعن ... فللله دري أي أهلي اتبع)\n(أقام الذين لا أبالي فراقهم ... وشط الذين بينهم أتوقع)\nلشعر للمتلمس والغناء لمتيم خفيف ثقيل بالوسطى","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":4,"spl":"هجاؤه أكرم هجاء — لقبه واسمه ونسبه","tags":["عمارة"],"song":1,"loc":4035},
{"id":"b312-12","bab":"الجزء 24","sec":"لقبه واسمه ونسبه","page":"ج24 ص216","text":"المتلمس لقب غلب عليه ببيت قاله وهو\n(فهذا أوان العرض جن ذبابه ... زنابيره والأزرق المتلمس)\nاسمه جرير بن عبد المسيح بن عبد الله بن دوفن بن حرب بن وهب بن جلي بن أحمس بن ضبيعة بن ربيعة بن نزار قال ابن حبيب فيما أخبرنا به عبد الله بن مالك النحوي عنه ضبيعات العرب ثلاث كلها من ربيعة ضبيعة بن ربيعة وهم هؤلاء ويقال ضبيعة أضجم وضبيعة بن قيس بن ثعلبة وضبيعة بن عجل بن لجيم\nقال وكان العز والشرف والرئاسة على ربيعة في ضبيعة أضجم وكان سيدها الحارث بن الأضجم وبه سميت ضبيعة أضجم وكان يقال للحارث حارث الخير بن عبد الله بن دوفن بن حرب وإنما لقب بذلك لأنه أصابته لقوة فصار أضجم ولقب بذلك ولقبت به قبيلته\nثم انتقلت الرئاسة عن بني ضبيعة فصارت في عنزة وهو عامر بن أسد بن ربيعة بن نزار وكان يلي ذلك فيهم القدار أحد بني الحارث بن الدول بن صباح ابن عتيك بن أسلم بن يذكر بن عنزة ثم انتقلت الرئاسة عنهم فصارت في عبد القيس فكان يليها فيهم الأفكل وهو عمرو هنا انقطع ما ذكره الأصفهاني رحمه الله\nوروى أبو عبيدة وغيره هذا الخبر على نص ما مضى عن ابن حبيب وقال الأفكل هو عمرو بن الجعيد بن صبرة بن الديل بن شن بن أفصى بن دعمي بن جديلة بن أسد بن ربيعة ثم انتقل الأمر إلى النمر بن قاسط فكان يلي ذلك منهم عامر الضحيان بن سعد بن الخزرج بن تيم الله ابن النمر وإنما سمي الضحيان لأنه كان يقعد بهم في الضحى فيقضي بينهم ثم انتقل الأمر إلى بني يشكر بن بكر بن وائل فكان يلي ذلك منهم الحارث بن غبر بن غنم بن حبيب بن كعب بن يشكر ثم انتقل الأمر إلى بني تغلب فصار يليه ربيعة بن مرة بن الحارث بن زهير بن جشم بن بكر بن حبيب بن عمرو بن غنم بن تغلب ثم وليه بعده ابنه كليب فكان من أمره في البسوس ما كان فاختلفت أمورهم وذهبت رياستهم","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":4,"spl":"هجاؤه أكرم هجاء — لقبه واسمه ونسبه","tags":["عمارة","الرواية والكتابة"],"loc":4036},
{"id":"b312-13","bab":"الجزء 24","sec":"المتلمس وأخواله","page":"ج24 ص217","text":"وكان المتلمس في أخواله بني يشكر ويقال إنه ولد فيهم ومكث فيهم حتى كادوا يغلبون على نسبه فسأل الملك وهو عمرو ابن هند\nمضرط الحجارة وهو محرق وإنما سمي محرقا لأنه حرق باليمامة مائة من تميم فسأل الملك يوما وهو عنده الحارث بن التوأم اليشكري عن المتلمس وعن نسبه فأراد أن يدعيه فقال المتلمس في ذلك\n(تعيرني أمي رجال ولن ترى ... أخا كرم إلا بأن يتكرما)\n(ومن كان ذا عرض كريم ولم يصن ... له حسبا كان اللئيم المذمما)\n(أحارث إنالو تساط دماؤنا ... تزايلن حتى لا يمس دم دما)\n(أمنتفيا من نصر بهثة خلتني ... ألا إنني منهم وإن كنت أينما)\nهثة ابن حرب بن وهب بن جلي بن أحمس بن ضبيعة\n(وإن نصابي إن سألت وأسرتي ... من الناس قوم يقتنون المزنما)\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\n(فلو غير أخوالي أرادوا نقيصتي ... جعلت لهم فوق العرانين ميسما)\n(وهل لي أم غيرها إن ذكرتها ... أبى الله إلا أن أكون لها ابنما)\n(وقد كنت ترجو أن أكون لعقبكم ... زنيما فما أجررت أن أتكلما)\nقال محمد بن سلام المتلمس هو جرير بن عبد المسيح بن عبد الله بن ربيعة بن دوفن بن حرب وسائر النسب على ما تقدم قال والمتلمس خال طرفة بن العبد وكان طرفة قد هجاه وقال ابن قتيبة هو المتلمس بن عبد العزى ويقال ابن عبد المسيح من بني ضبيعة ابن ربيعة ثم من بني دوفن وأخواله بنو يشكر واسمه جرير وقال أبو حاتم عن الأصمعي اسمه جرير بن زيد ويقال اسمه عمرو بن الحارث ويقال اسمه عبد المسيح بن جرير","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":5,"spl":"المتلمس وأخواله — المتلمس من الشعراء المقلين المفلقين","tags":["عمارة","الهجاء","اللهو والمزاح"],"loc":4037},
{"id":"b312-14","bab":"الجزء 24","sec":"المتلمس من الشعراء المقلين المفلقين","page":"ج24 ص219","text":"والمتلمس من شعراء الجاهلية المقلين المفلقين وجعله ابن سلام في الطبقة السابعة من شعراء الجاهلية وقرن به سلامة بن جندل\nوحصين بن الحمام والمسيب بن علس وقال ابن قتيبة قال أبو عبيدة واتفقوا على أن أشعر المقلين في الجاهلية ثلاثة المتلمس والمسيب ابن علس وحصين بن الحمام المري قال ابن قتيبة وكان للمتلمس ابن يقال له عبد المنان أدرك الإسلام وكان شاعرا وهلك ببصرى ولا عقب له وقال أبو عبيدة كانت ضبيعة بن ربيعة رهط المتلمس حلفاء لبني ذهل بن ثعلبة بن عكابة فوقع بينهم نزاع ومخاصمة فقال المتلمس يعاتب بني ذهل\n(ألم تر أن المرء رهن منية ... صريع لعافي الطير أو سوف يرمس)\n(فلا تقبلن ضيما مخافة ميتة ... وموتن بها حرا وجلدك أملس)\n(فمن حذر الأيام ما حز أنفه ... قصير وخاض الموت بالسيف بيهس)\n(نعامة لما صرع القوم رهطه ... تبين في أثوابه كيف يلبس)\n(وما الناس إلا ما رأوا وتحدثوا ... وما العجز إلا أن يضاموا فيجلسوا)\n(ألم تر أن الجون أصبح راسيا ... تطيف به الأيام ما يتأيس)\nلجون جبل أو حصن جعله جونا للونه ما يتأيس أي لا يؤثر فيها الدهر يقول فليس الإنسان كالحجارة والجبال التي لا تؤثر فياه الأيام ولكنه غرض للحوادث فلا ينبغي له أن يقبل ضيما رجاء الحياة وقال الرياشي الجون حصن اليمامة ويقال إنه أعيا تبعا\n(عصى تبعا أيام أهلكت القرى ... يطان عليه بالصفيح ويكلس)\n(هلم إليها قد أثيرت زروعها ... ودارت عليها المنجنون تكدس)\n(وذاك أوان العرص جن ذبابه ... زنابيره والأزرق المتلمس)\n(فإن تقبلوا بالود نقبل بمثله ... وإلا فإنا نحن آبى وأشمس)\n(يكون نذير من ورائي جنة ... ويمنعني منهم جلي وأحمس)\nنذير ابن بهثة بن حرب بن وهب بن جلي بن أحمس بن ضبيعة وقال أبو عمرو نذير ابن ضبيعة بن نزار\n(وإن يك عنا في حبيب تثاقل ... فقد كان منا مقنب ما يعرس)\nراد حبيب فخفف وهو حبيب بن كعب بن يشكر بن بكر بن وائل يقول إن تثاقلوا عنا وقطعوا الرحم فإن لقومي غزى ما يعرس ما يعرس في الغزو","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":5,"spl":"المتلمس وأخواله — المتلمس من الشعراء المقلين المفلقين","tags":["عمارة","السفر والحج","الموت"],"loc":4038},
{"id":"b312-15","bab":"الجزء 24","sec":"حديث بيهس","page":"ج24 ص222","text":"فأما حديث بيهس الذي ضرب به المثل فإن أبا عبيدة قال مدركو الأوتار في الجاهلية ثلاثة سيف بن ذي يزن الحميري وبيهس الفزاري وقصير صاحب جذيمة الأزدي وقد مضى خبر قصير وسيف في موضعهما من هذا الكتاب\nوروى أبو حاتم عن الأصمعي أن بيهسا الفزاري غزا ربعه قوم فأغاروا على إخوته وأهل بيته وقتلوهم أجمعين وأسروا بيهسا فلما نزلوا بعض المنازل راجعين نحروا جزورا فأكلوا وقالوا ظللوا البقية فقال بيهس لكن بالأثلات لحم لا يظلل يعني أجساد من أصيب من قومه فذهبت مثلا فلطمه رجل منهم وجعل\nيدخل رجليه في يدي سرباله فقال له رجل منهم لم تلبس هذا اللبس وجعل يعلمه كيف يلبس وكان يقال إن به طرقة يعني جنونا فقال\n(البس لكل عيشة لبوسها ... إما نعيمها وإما بوسها)\nلطمه الرجل الذي كان لطمه مرة أخرى فقال له بيهس لو نكلت عن الأولى لم تعد إلى الثانية فقال بعضهم إن مجنون فزارة هذا ليتعرض للقتل فخلوا عنه فخلوه فلما أتى أهله جعل نساؤه يتحفنه فقال يا حبذا الترات لولا الذلة فذهبت مثلا فاجتمع عليه الغم مع ما به من قلة العقل فجعلت أمه تعاتبه ويشتد عليها ذلك منه فقالت لو كان فيك خير لقتلت مع قومك فقال لو خيرت لاخترت فذهبت مثلا ثم جمع جمعا وغزا القوم الذين وتروه ومعه خال له فوجدوهم في وهدة من الأرض كبيرة فدفعه خاله عليهم وكان جسيما طويلا وإنما سمي نعامة لذلك فقاتل القوم وهو يقول مكره أخوك لا بطل فذهبت مثلا وقتل القوم وأدرك بثأره\nوقال يعقوب بن السكيت في كتاب الأمثال روي مثله عن أبي عبيدة وروى هذا الخبر أيضا أبو عبيد القاسم بن سلام واللفظ ليعقوب وروايته أتم الروايات\nقال كان بيهس وهو رجل من بني غراب بن فزارة بن ذبيان بن بغيض سابع سبعة إخوة فأغار عليهم ناس من أشجع بن ريث بن غطفان وبينهم حرب وهم في إبلهم فقتلوا ستة نفر منهم وبقي بيهس وكان يحمق وكان أصغرهم فأرادوا قتله ثم قالوا ما تريدون من قتل مثل هذا أيحسب عليكم برجل ولا خير فيه فتركوه فقال دعوني أتوصل معكم إلى الحي\nفإنكم إن تركتموني وحدي أكلتني السباع وقتلني العطش ففعلوا فأقبل معهم فنزل منزلا فنحروا جزورا في يوم شديد الحر فقال بعضهم ظللوا لحمكم لا يفسد فقال بيهس لكن بالأثلات لحم لا يظلل فقالوا إنه لمنكر وهموا أن يقتلوه ثم تركوه ففارقهم حين انشعب طريق أهله فأتى أمه فقالت ما جاء بك من بين إخوتك فقال لو خيرك القوم لاخترت فأرسلها مثلا ثم إن أمه تعطفت عليه ورقت له فقال الناس قد أحبت أم بيهس بيهسا ورقت له فقال بيهس ثكل أرأمها ولدا فأرسلها مثلا أي عطفها ثم جعلت تعطيه ثياب إخوته ومتاعهم فيلبسها فقال يا حبذا الترات لولا الذلة فذهبت مثلا ثم أتى على ذلك ما شاء الله ثم إنه مر على نسوة من قومه وهن يصلحن امرأة يردن أن يهدينها لبعض القوم الذين قتلوا إخوته فكشف عن استه ثوبه وغطى رأسه به فقلن ويلك ما تصنع يا بيهس فقال\n(البس لكل عيشة لبوسها ... إما نعيمها وإما بوسها)\nأرسلها مثلا فلما أتى على ذلك ما شاء الله جعل يتتبع قتلة إخوته فيقتلهم ويتقصاهم حتى قتل منهم ناسا كثيرا فقال بيهس\n(يا لها نفسا يا لها إنني ... لها الطعم والسلامه)\n(فقد قتل القوم إخوتها ... بكل واد زقاء هامه)\n(فلأطرقن قوما وهم نيام ... وأبركن بركة النعامه)\nبهذا البيت لقب نعامة\n(قابض رجل باسط أخرى ... والسيف أقدمه أمامه)\nم أخبر أن ناسا من أشجع في غار يشربون فيه فانطلق إلى خال له يقال له أبو حشر فقال له هل لك في غار فيه ظباء لعلنا نصيب منهن فقال نعم فانطلق بيهس بأبي حشر حتى إذا قام على فم الغار دفع أبا حشر في فم الغار فقال ضربا أبا حشر فقال بعض قومهم إن أبا حشر لبطل فقال أبو حشر مكره أخوك لا بطل فكان بيهس مثلا في العرب فقال بعض شعراء بني تغلب\n(لقمان منتصرا وقس ناطقا ... ولأنت أجرأ صولة من بيهس)\nقال الزبير بن بكار قتل إخوة بيهس نصر بن دهمان الأشجعي وأراد قتل بيهس فقيل له إنه أحمق فأعده لأمه تسكن إليه فلما بلغوا قال نصر ظللوا ذلك اللحم فذاك حيث يقول نعامة لكن بالأثلات لحم لا يظلل ففزع منه نصر فقيل له كلمة جاءت من أحمق","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":6,"spl":"حديث بيهس","tags":["عمارة"],"loc":4039},
{"id":"b312-17","bab":"الجزء 24","sec":"حديث بيهس — أول من قال مكره أخوك لا بطل","page":"ج24 ص222 – ج24 ص226","text":"قال الزبير الأثلات شجر وهو الطرفاء قال أبو عبيد الأثلات موضع وقد روي أن هذا المثل مكره أخوك لا بطل لغير نعامة أو خاله أبي حشر روي أن عبيد بن شرية الجرهمي وهو أحد المعمرين حدث معاوية ابن أبي سفيان في حديث فيه طول\nأن مالك بن جبير سأل حارثة بن عبد العزى في مجلس علقمة بن علاثة الجعفري عن أول من قال مكره أخوك لا بطل فقال حارثة أول من قال ذلك جرول بن نهشل بن درام بن كعب وكان جبانا هيوبا قد عرف الناس ذلك منه غير أنه كان ذا خلق كامل وإن حيا من أحياء العرب أغاروا على بني دارم وهم خلوف فاستاقوا أموالهم ونساءهم وسيدهم يومئذ نهشل بن دارم أبو جرول فخرج واجتمع إليه قومه فنادى فيهم أيما رجل لم يأتنا برأس أو أسير أو ظعينة فهو نفي منا ولحقتهم بنو دارم فاقتتلوا قتالا شديدا حتى كثرت القتلى في الفريقين جميعا وأصحابه في ذلك يأتونه بالرؤوس والأسرى والظعائن وكان لنهشل ستة إخوة وهو سابعهم عبد الله ونهشل ومجاشع وأبان وجرير وفقيم وخيبري هؤلاء بنو دارم بن كعب فساد القوم كلهم يومئذ مجاشع وذلك لأنه أتاه بما فرض على ثلاثين رجلا بعشرة رؤوس وعشرة أسارى وعشرة ظعائن فقسمها فيمن لم يكن قتل ولا أسر ولا استنقذ وإن جرولا أتى عمه مجاشعا فقال يا عم أعطني منها رأسا فقال له عمه يا جرول إن الهمام يصدق الحسام فسار جرول متذمرا حتى حمل على ناحية الجمهور على رجل يسوق ظعينة فلما رآه الرجل خشيه لكمال خلقه وهو لا يعرفه وكان قد سمع بخبر جرول وجبنه فلما دنا منه جرول هم الرجل بترك الظعينة فقال أنا جرول بن نهشل في\nالحسب المؤثل فعطف عليه الرجل فقال يا جرول بن نهشل إن الوهل فشل وليس هكذا البطل والقول يرفعه العمل ثم إنه طعن فرمى جرولا طعنة فكبا جواده فأخذه وكتفه ثم ساقه وهو يقول\n(إذا ما لقيت امرأ في الوغى ... فذكر بنفسك يا جرول)\nتى انتهى به إلى قائد الجيش ورئيس القوم وكان قد عرف جبن جرول فقال له يا جرول ما عهدناك تقاتل الأبطال ولا تحب النزال فقال جرول مكره أخوك لا بطل فأعطاه رأس رجل من بني دارم ثم\nقال انطلق فالجبن شر من الإسار فعمد إليه الذي كان أسره فجرحه وقال له جئت تستنقذ الظعائن يا لها من ظعينة ما كان أضيعها ثم خلى سبيله وجرول يرى أن الرأس الذي أعطي من رؤوس حزبه فأتى أباه فقال يا أبت هكذا تلقى الأبطال وتسلم الأنفال الجدع خير من النفي ثم\nقال هذا رأس رجل قتلته فنظر إلى الرأس فإذا رأس رجل من أصحابه فجاء إخوة المقتول فقالوا أقيدونا جرولا بأخينا فإنه قتله فلما رأى جرول الشر وما وقع فيه أخبر أباه والقوم الخبر فعرفوا جبنه وأنه لم يكن يقتل الرجال فخلوا عنه وقالت عمرة أخت المقتول ترثي أخاها وتذكر جرولا\n(ألا يا قتيلا ما قتيلا معاشر ... ثوى بين أحجار صريعا وجندل)\n(وقد يصبح الخيل المغيرة فيهم ... ويسرع كر المهر في كل جحفل)\n(ويهدي ضلول القوم في ليلة السرى ... أمين القوى في القوم ليس بزمل)\n(فأدى إلينا رأسه ثم جرول ... فلله ماذا كان من فعل جرول)\n(فشلت يداه يوم يحمل رأسه ... إلى نهشل والقوم حضرة نهشل)","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":7,"spl":"حديث بيهس — أول من قال مكره أخوك لا بطل — رجع الخبر إلى حديث المتلمس","tags":["عمارة"],"loc":4040},
{"id":"b312-18","bab":"الجزء 24","sec":"رجع الخبر إلى حديث المتلمس","page":"ج24 ص228","text":"وروى أبو محمد عبد الله بن رستم عن يعقوب بن السكيت قال قدم المتلمس وطرفة بن العبد على عمرو بن هند فقال\n(قولا لعمرو بن هند غير متئب ... يا أخنس الأنف والأضراس كالعدس)\nبه أضراسه بالعدس في صغرها وسوادها\n(ملك النهار وأنت الليل مومسة ... ماء الرجال على فخذيك كالقرس)\n(لو كنت كلب قنيص كنت ذا جدد ... تكون أربته في آخر المرس)\n(لعوا حريصا يقول القانصان له ... قبحت ذا أنف وجه ثم منتكس)\nلمومسة الفاجرة وأراد بالقرس القريس وهو الجامد والقنيص القانص والقنيص أيضا الصيد والأربة العقدة والمرس الحبل أي هو أخس الكلاب فقلادته أخس القلائد وقال ابن الكلبي هذا الشعر لعبد عمرو بن عمار يهجو به الأبيرد الغساني وبسببه قتل عبد عمرو","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":7,"spl":"حديث بيهس — أول من قال مكره أخوك لا بطل — رجع الخبر إلى حديث المتلمس","tags":["عمارة","الحب والغزل"],"loc":4041},
{"id":"b312-19","bab":"الجزء 24","sec":"صحيفة المتلمس","page":"ج24 ص229","text":"وكان طرفة قد هجا عمرو بن هند أيضا بعدة قصائد فلما قدما عليه كتب لهما إلى عامله على البحرين وهجر وكان عامله عليهما فيما يزعمون ربيعة بن الحارث العبدي\nوقال لهما انطلقا فاقبضا جوائزكما فخرجا فزعموا أنهما هبطا النجف قال المتلمس يا طرفة إنك غلام حديث السن والملك من عرفت حقده وغدره وكلانا قد هجاه فلست آمنا أن يكون قد أمر بشر فهلم فلننظر في كتبنا هذه فإن يكن قد أمر لنا بخير مضينا فيه وإن تكن الأخرى لم نهلك أنفسنا فأبى طرفة أن يفك خاتم الملك وحرض المتلمس طرفة فأبى وعدل المتلمس إلى غلام من غلمان الحيرة عبادي فأعطاه الصحيفة ولا يدري ممن هي فقرأها فقال ثكلت المتلمس أمه فانتزع المتلمس الصحيفة من الغلام واكتفى بذلك من قوله واتبع طرفة فلم يلحقه وألقى الصحيفة في نهر الحيرة ثم خرج هاربا إلى الشام فقال المتلمس في ذلك\n(وألقيتها بالثني من جنب كافر ... كذلك أقنوا كل قط مضلل)\n(رضيت لها بالماء لما رأيتها ... يجول بها التيار في كل جدول)\nال أبو عمرو كافر نهر بالحيرة وقال غيره كافر نهر قد ألبس الأرض وغطاها وقال أبو عمرو أقنو أحفظ وقال غيره أقنو أجزي يقال لأقنونك قناوتك أي لأجزينك بفعلك والقط الصحيفة فيقول حفظي لهذا الكتاب أن أرمي به في الماء وقال المتلمس أيضا وقد كان فيما يقال قال لطرفة حين قرأ كتابه تعلمن أن الذي في صحيفتك مثل الذي في صحيفتي قال طرفة إن كان\nاجترأ عليك فلم يكن ليجترىء علي ولا ليغرني ولا ليقدم علي فلما غلبه صار المتلمس إلى الشام وقال\n(من مبلغ الشعراء عن أخويهم ... نبأ فتصدقهم بذاك الأنفس)\n(أودى الذي علق الصحيفة منهما ... ونبا حذار حبائه المتلمس)\n(ألقى صحيفته ونجت كوره ... وجناء مجمرة المناسم عرمس)\n(عيرانة طبخ الهواجر لحمها ... فكأن نقبتها أديم أملس)\n(أجد إذا ضمرت تعزز لحمها ... وإذا تشد بنسعها لا تنبس)\n(وتكاد من جزع يطير فؤادها ... إن صاح مكاء الضحا متنكس)\nلوجناء الضخمة الغليظة الصلبة كأنها لصلابتها ضربت بمواجن القصار واحدتها ميجنة وهي مدقتة ومجمرة المناسم مجتمعة لطيفة في صلابة وعظم الأخفاف من الهجنة وليس من صفة النجائب والعرمس الناقة الصلبة شبهت بالعرمس وهي الصخرة الصلبة وتعزز تشدد وتنبس تنطق وتصيح وطبخ الهواجر لحمها أي سافرت عليها حتى انجرد شعرها ونقبتها لونها والمكاء طائر يطير في الجو ثم يتنكس\nوقال محمد بن موسى الكاتب زعموا أن الكتب لم تزل في قديم الدهر منشورة غير مختومة ولا معنونة فلما قرأ المتلمس صحيفته التي كتبها له عمرو بن هند إلى عامله بالبحرين واطلع على سره فيها ختمت الكتب\nوروي عن الرياشي عن عمرو بن بكير عن الهيثم بن عدي عن حماد الراوية عن سماك بن عمرو قال أخبرني عبيد راوية الأعشى ورأيته بالحيرة زمن معاوية شيخا كبيرا قال أخبرني الأعشى قال حدثني المتلمس قال","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":8,"spl":"صحيفة المتلمس","tags":["عمارة","الهجاء"],"loc":4042},
{"id":"b312-20","bab":"الجزء 24","sec":"المتلمس وطرفة عند عمرو بن هند","page":"ج24 ص231","text":"قدمت أنا وطرفة بن العبد على عمرو بن هند وكان غلاما معجبا تائها يتخلج في مشيته بين يديه فنظر إليه نظرة كادت تقتلعه من الأرض وكان عمرو لا يبتسم ولا يضحك وكانت العرب تسميه مضرط الحجارة وملك ثلاثا وخمسين سنة وكانت العرب تهابه هيبة شديدة له يقول الذهاب العجلي\n(أبى القلب أن يهوى السدير وأهله ... وإن قيل عيش بالسدير غرير)\n(فلا أنذروا الحي الذي نزلوا به ... وإني لمن لم يأته لنذير)\n(به البق والحمى وأسد خفية ... وعمرو بن هند يعتدي ويجور)\nال المتلمس فقلت لطرفة إني لأخاف عليك من نظرته إليك هذه مع ما قلت قال كلا فكتب لنا كتابا إلى المكعبر كتب ولم نره وختم ولم نره لي كتاب وله كتاب وكان المكعبر عامله على عمان والبحرين فخرجنا حتى إذا هبطنا بذي الركاب من النجف إذا أنا بشيخ على يساري يتبرز ومعه كسرة يأكلها وهو يقصع القمل فقلت تالله ما رأيت شيخا أحمق\nوأضعف وأقل عقلا منك قال وما تنكر قلت تتبرز وتأكل وتقصع القمل قال أدخل طيبا وأخرج خبيثا وأقتل عدوا وأحمق مني الذي يحمل حتفه بيمينه لا يدري ما فيه قال فنبهني وكأنما كنت نائما فإذا غلام من أهل الحيرة فقلت يا غلام تقرأ قال نعم قلت اقرأه فإذا فيه من عمرو بن هند إلى المكعبر إذا جاءك كتابي هذا مع المتلمس فاقطع يديه ورجليه وادفنه حيا فألقيت الصحيفة في النهر فذلك حيث أقول\n(وألقيتها بالثني من جنب كافر ... )\nلبيتين وقلت يا طرفة معك مثلها قال كلا ما كان ليفعل ذلك في عقر داري قال فأتى المكعبر فقطع يديه ورجليه ودفنه حيا ففي ذلك يقول المتلمس\n(من مبلغ الشعراء عن أخويهم ... نبأ فتصدقهم بذاك الأنفس)\n(أودى الذي علق الصحيفة منهما ... ونجا حذار حبائه المتلمس)\n(ألق الصحيفة لا أبالك إنه ... يخشى عليك من الحباء النقرس)\n(ألقى صحيفته ونجت كوره ... وجناء مجمرة الفراسن عرمس)\n(أجد إذا ضمرت تعزز لحمها ... وإذا تشد بنسعها لا تنبس)\nوقال ابن قتيبة كان المتلمس ينادم عمرو بن هند هو وطرفة بن العبد فهجواه فكتب لهما إلى عامله بالبحرين كتابين أوهمهما أنه أمر لهما بجائزة وكتب إليه يأمره بقتلهما فخرجا حتى إذا كانا بالنجف إذا بشيخ عن يسار الطريق يحدث ويأكل من خبز في يده ويتناول القمل من ثيابه فيقصعه فقال المتلمس ما رأيت كاليوم شيخا أحمق فقال الشيخ وما رأيت من حمقي أخرج خبيثا وأدخل طيبا وأقتل عدوا أحمق والله مني من يحمل حتفه بيده فاستراب المتلمس بقوله وطلع غلام من الحيرة فقال له المتلمس\nأتقرأ يا غلام قال نعم ففك صحيفته ودفعها إليه فإذا فيها أما بعد فإذا أتاك المتلمس فاقطع يديه ورجليه وادفنه حيا فقال لطرفة ادفع إليه صحيفتك يقرأها ففيها والله ما في صحيفتي فقال طرفة كلا لم يكن ليجترىء علي فقذف المتلمس صحيفته في نهر الحيرة وقال\n(قذفت بها بالثني من جنب كافر ... )\nوأخذ نحو الشام وأخذ طرفة نحو البحرين فضرب المثل بصحيفة المتلمس","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":9,"spl":"المتلمس وطرفة عند عمرو بن هند","tags":["عمارة","الحب والغزل"],"loc":4043,"partialRef":{"sid":"b312-19","gi":0,"vi":0,"side":0},"partial":1},
{"id":"b312-21","bab":"الجزء 24","sec":"عمرو بن هند يحرم عليه حب العراق","page":"ج24 ص233","text":"(آليت حب العراق الدهر آكله ... والحب يأكله في القرية السوس)\nأتى بصرى فهلك بها وروى أبو بكر محمد بن عليب الفارسي عن أبيه عن الغلابي عن ابن بكار أن الفرزدق قدم المدينة على سعيد بن العاصي وهو واليها لمعاوية ابن أبي سفيان عند هربه من زياد فدخلها وسعيد يعشي الناس وهو جالس على منبر والناس على كراسي وكان الحطيئة وكعب بن جعيل حاضرين فتقدم الفرزدق وحدر اللثام عن وجهه ثم قال هذا مقام العائذ\nبك من رجل لم يصب دما ولا مالا فقال سعيد قد أجرتك إن لم تكن أصبت دما ولا مالا فمن أنت قال أنا همام بن غالب بن صعصعة وقد أثنيت على الأمير فإن رأى أن يأذن لي لأسمعه ثنائي فعل قال هات فأنشده قصيدته التي يقول فيها\n(عليك بني أمية فاستجرهم ... وخذ منهم لما تخشى حبالا)\n(فإن بني أمية من قريش ... بنوا لبيوتهم عمدا طوالا)\nتى انتهى إلى قوله\n(ترى الغر الجحاجح من قريش ... إذا ما الخطب في الحدثان عالا)\nحرم عمرو بن هند على المتلمس حب العراق فقال\n(بني عم النبي ورهط عمرو ... وعثمان الألى عظموا فعالا)\n(قياما ينظرون إلى سعيد ... كأنهم يرون به هلالا)\nقوله ورهط عمرو يريد بني هاشم واسم هاشم عمرو بن عبد مناف فقال مروان وكان إلى جانب سعيد يا فرزدق فهلا قلت قعودا قال لا والله إلا قائما على رجليك يا أبا عبد الملك فحقدها مروان وقال كعب بن جعيل هذه والله الرؤيا التي رأيتها البارحة قال سعيد وما رأيت قال رأيت كأني في سكك المدينة فإذا أنا بابن قترة أراد أن يتناولني فاتقيته وقام الحطيئة فشق ما بين رجلين حتى تجاوزهما إلى الفرزدق فقال\nله قل ما شئت فقد أدركت من مضى ولا يدركك من بقي ثم قال لسعيد هذا والله الشعر لا ما كنا نعلل به أنفسنا منذ اليوم وزاد الغلابي في حكايته هذه\nقال وقد ذكر محمد بن سلام عن أبي يحيى الضبي أن الحطيئة لما قال للفرزدق هذه المقالة قال كعب بن جعيل فضله على نفسك ولا تفضله على غيرك فقال الحطيئة والله أفضله على نفسي وغيري ثم\nقال له يا غلام أنجدت أمك قال بل أنجد أبي ثم أقام الفرزدق بالمدينة يختلف إلى بيوت القيان بها فلما وليها مروان بعد سعيد وفي قلبه على الفرزدق ما فيه وقد كان مروان نهاه في صدر ولايته عن المداخل التي كان يدخلها\nوعن قول الخنى في شعره فبعث إليه ألم أنهك عن الإفصاح بالخنى والإقرار بالفسق أخرج عن المدينة فإني عاهدت الله لئن أصبتك بها بعد ثلاثة لأقطعن لسانك","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":10,"spl":"عمرو بن هند يحرم عليه حب العراق","tags":["عمارة","الحب والغزل"],"loc":4044},
{"id":"b312-22","bab":"الجزء 24","sec":"الفرزدق ومروان","page":"ج24 ص235","text":"وأخبرنا أبو بكر بن دريد ها هنا قال فقال الفرزدق\n(توعدني وأجلني ثلاثا ... كما وعدت لمهلكها ثمود)\nال الغلابي فحدثني العباس بن بكار قال بعث إليه مروان بكتاب مختوم وقال توصله إلى عاملي فقد كتبت إليه أن يدفع إليك ثلاثمائة دينار فإذا أصبحت فاغد حتى تودعني وكتب إلى عامله أن يضربه مائة سوط ويحبسه ثم ندم مروان فقال يعمد إلى الكتاب\nفيفتحه ويقرأ ما فيه فيهجوني وأهل بيتي فلما أصبح غدا عليه الفرزدق فقال له مروان إني قد قلت في هذه الليلة أبياتا فاقرأها فقال الفرزدق وما قلت قال قلت\n(قل للفرزدق والسفاهة كاسمها ... إن كنت تارك ما نهيتك فاجلس)\n(ودع المدينة إنها مذمومة ... واقصد لمكة أولبيت المقدس)\n(وإن اجتنبت من الأمور عظيمة ... فاعمد لنفسك بالزماع الأكيس)\nفطن الفرزدق لما أراد فقال\n(يا مرو إن مطيتي محبوسة ... ترجو الحباء وربها لم ييأس)\n(وحبوتني بصحيفة مختومة ... يخشى علي بها حباء النقرس)\n(ألق الصحيفة يا فرزدق لا تكن ... نكداء مثل صحيفة المتلمس)\nم رمى بالصحيفة في وجهه وخرج حتى أتى سعيد بن العاصي وعنده الحسن والحسين وعبد الله بن جعفر عليهم السلام فأخبرهم الخبر فأمر له كل واحد منهم بمائة دينار وراحلة فأخذ ذلك وتوجه إلى البصرة وصار إلى مروان جماعة من أهله فندموه على فعله وقالوا له تعرضت لشاعر مضر فندم وبعث إليه رسولا ومعه مائة دينار وراحلة فأوصل ذلك إليه وصار حتى قدم البصرة\nرجع الخبر إلى حديث المتلمس وقال أبو عبيدة لما بلغ النعمان بن المنذر لحوق المتلمس بالشام وكانت غسان قتلت أباه يوم عين أباغ شق عليه لحوقه بغسان وحلف ألا يدخل العراق ولا يطعم بها حتى يموت فقال المتلمس وروى أبو محمد بن رستم عن ابن السكيت أن عمرو بن هند كتب إلى عماله على الريف ليأخذوا المتلمس ويمنعوه من الميرة فقال المتلمس\n(يا آل بكر ألا لله أمكم ... طال الثواء وثوب العجز ملبوس)\n(أغنيت شأني فأغنوا اليوم شأنكم ... واستحمقوا في مراس الحرب أو كيسوا)\n(إن علافا ومن باللوذ من حضن ... لما رأوا أنه دين خلابيس)\nلاف هو ربان بن حلوان بن عمران بن الحافي بن قضاعة وحضن جبل معروف واللوذ نواحيه يقول قد ثويتم على العجز لا تطلبون يوم طرفة ويقال أمر خلابيس وهو الأمر فيه اختلاط لا واحد لها وقال ابن النحاس حضن جبل منجد يقال إن علافا كانوا بهذا الجبل فلما أوذوا تحولوا إلى عمان وقال خلابيس أمر فيه عور واختلاط وفساد ويقال أمر خلابيس إذا كان متفرقا","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":11,"spl":"الفرزدق ومروان","tags":["عمارة","الحب والغزل"],"loc":4045},
{"id":"b312-23","bab":"الجزء 24","sec":"سامة بن لؤي بن غالب","page":"ج24 ص237","text":"(ردوا عليهم جمال الحي فارتحلوا ... والظلم ينكره القوم الأكاييس)\nيروى\n(شدوا الجمال بأكوار على عجل ... والضيم ينكره القوم المكاييس)\n(كانوا كسامة إذ شعف منازله ... ثم استمرت به البزل القناعيس)\nروى يعقوب\n(كونوا كسامة إذ خلى مساكنه ... )\nريد سامة بن لؤي بن غالب قال ابن الكلبي وكان من سببه أنه جلس هو وأخواه كعب وعامر ابنا لؤي يشربون فوقع بينهم كلام ففقأ سامة عين عامر وخرج إلى عمان مغاضبا\nوقال أبو عبيدة بل فقأ عين سعد أخيه وقال أبو العباس الأحول لما غاضب سامة بن لؤي قومة خرج إلى عمان فأبى الضيم وكان ينزل بكبكب وهو الجبل الأحمر وراء عرفة فتركه ومضى والمكاييس جمع مكياس قال وشعاف الجبل أعاليه وأراد أنه كان منزله بمكة وهي أعلى البلاد وقال غيره شعف موضع بالبحرين\n(حنت قلوصي بها والليل مطرق ... بعد الهدوء وشاقتها النواقيس)\nطرق يقال تطرق أي ركب بعض ظلمته بعضا يقول حنت\nناقتي إلى الشام وشاقتها النواقيس لأن غسان كانوا نصارى\n(معقولة ينظر التشريق راكبها ... كأنه من هوى للرمل مسلوس)\nيروى\n(كأنه طرف للرمل مسلوس ... )\nيريد بالتشريق أيام التشريق أي ينظرها لرمي الجمار ثم يذهب إلى الشام وكان حج حين هرب والمسلوس والمألوس الذاهب العقل وقال ابن النحاس يريد بالتشريق إشراق الشمس\n(وقد أضاء سهيل بعد ما هجعوا ... كأنه ضرم بالكف مقبوس)\n(أنى طربت ولم تلحي على طرب ... ودون إلفك أمرات أماليس)\n(حنت إلى نخلة القصوى فقلت لها ... بسل حرام ألا تلك الدهاريس)\nلأمرات والأماليس التي لا نبات بها ونخلة معرفة غير مصروف وهو واد مما يلي نجدا ونخلة القصوى طريق الشام وبسل حرام والدهاريس الدواهي ولا واحد لها وحكى علي بن سليمان الأخفش عن أبي العباس الأحول أن واحدها دهرس\n(أمي شآمية إذ لا عراق لنا ... قوما نودهم إذ قومنا شوس)\nمي أي اقصدي شآمية أي ناحية شامية والأشوس الذي ينظر إليك نظر البغضة\n(لن تسلكي سبل البوباة منجدة ... ما عاش عمرو ولا ما عاش قابوس)\nوروى الأصمعي\n(ما عشت عمرو ولا ما عشت قابوس ... )\nعلى النداء والبوباة ثنية في طريق نجد ينحدر منها إلى العراق وعمرو وقابوس ابنا المنذر\n(آليت حب العراق الدهر آكله ... والحب يأكله في القرية السوس)\n(لم تدر بصرى بما آليت من قسم ... ولا دمشق إذا ديس الكداديس)\nقول لم تدر بلاد الشام بيمينك فتبرها وتمنعني حبها كما منعتني حب العراق والكداديس جمع كدس على غير قياس ويروى إذا ديس الفراديس والفراديس درب يقال له درب الفراديس وقال ابن النحاس الفراديس موضع بدمشق أي إذا درست الزروع التي عند الفراديس وقال الأصمعي الفراديس البساتين واحدها فردوس أي لم تبلغ الشام يمينك لهوانك عليها يهزأ به وقوله\n(والحب يأكله في القرية السوس ... )\nكثرته عندهم\n(فإن تبدلت من قومي عديكم ... إني إذا لضعيف العقل مألوس)\n(كم دون مية من مستعمل قذف ... ومن فلاة بها تستودع العيس)\n(ومن ذرا علم ناء مسافته ... كأنه في حباب الماء مغموس)\n(جاوزته بأمون ذات معجمة ... ترمي بكلكلها والرأس معكوس)\nويروى من دوية قذف ويروى تنجو بكلكلها والمستعمل الطريق الموطأ والقذف البعيد يقول إن العيس لبعد هذا الطريق تسقط فيه فيتركونها ويريد كأن العلم إذا انغمس في السراب مغموس في الماء والأمون يؤمن عثارها وخورها ومعجمتها خبرها من عجمت العود إذا عضضته لتنظر صلابته ويقال المعجمة الصلابة ومعكوس بالزمام لنشاطها وروي أن أبا عمرو بن العلاء لقي الفرزدق فاستنشده بعض شعره فأنشده\n(كم دون مية من مستعمل قذف ... ومن فلاة بها تستودع العيس)\nقال له أبو عمرو أو هذا لك يا أبا فراس فقال اكتمها علي والله لضوال الشعر أحب إلي من ضوال الإبل","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":12,"spl":"سامة بن لؤي بن غالب","tags":["عمارة","الحب والغزل"],"loc":4046,"partialRef":{"sid":"b312-21","gi":0,"vi":0,"side":1},"partial":1},
{"id":"b312-24","bab":"الجزء 24","sec":"المتلمس يهرب إلى الشام ويقول شعرا","page":"ج24 ص241","text":"وقال أبو عبيدة لما لحق المتلمس بالشام هاربا من عمرو بن هند وهند أمه وهي بنت الحارث بن عمرو بن حجر آكل المرار بن معاوية الكندي وهو عمرو بن المنذر بن الأسود بن النعمان بن المنذر بن امرىء القيس بن النعمان بن امرىء القيس بن عمرو بن عدي بن نصر بن ربيعة بن عمرو بن الحارث بن سعود بن مالك بن عمم وهو عدي بن نمارة بن لخم\nوقال ابن الكلبي إنما سمي عمما لأنه أول من تعم وذلك حين كتب له عمرو بن هند ولطرفة فقرأ المتلمس كتابه فلما رأى الداهية هرب وسار طرفة إلى عامل البحرين فقتله فقال المتلمس يذكر لحاقه بالشام ويحرض قوم طرفة على الطلب بدمه\n(إن العراق وأهله كانوا الهوى ... فإذا نآني ودهم فليبعد)\n(فلتتركنهم بليل ناقتي ... تدع السماك وتهتدي بالفرقد)\nإن السماك يمان والفرقد شآمي\n(تعدو إذا وقع الممر بدفها ... عدو النحوص تخاف ضيق المرصد)\n(أجد إذا استنفرتها من مبرك ... حلبت مغابنها برب معقد)\nلممر السوط المفتول والنحوص الحائل من الأتن والأجد الموثقة الخلق ومغابنها أرفاغها شبه عرق تلك المواضع بالرب\n(وإذا الركاب تواكلت بعد السرى ... وجرى السراب على متون الجدجد)\n(مرحت وصاح المرو من أخفافها ... جذب القرينة بالنجاء الأجرد)\nلجدجد الصلب من الأرض يقال جدد وجدجد والمرو حجارة بيض والقرينة بعيران في حبل فإذا أفلت أحدهما لم يأل جهدا والأجرد الحثيث السريع\n(لبلاد قوم لا يرام هديهم ... وهدي قوم آخرين هو الردي)\n(كطريفة بن العبد كان هديهم ... ضربوا صميم قذاله بمهند)\nلهدي الجار هنا والهدي أيضا الأسير يقول إن جار غسان لا يضام ولا يرام بسوء\n(إن الخيانة والمغالة والخنى ... والغدر تتركه ببادة مفسد)\n(ملك يلاعب أمه وقطينه ... رخو المفاصل أيره كالمرود)\nيريد عمرو بن هند والقطين الحشم رماه بالمجوسية ونكاح الأمهات ويقال بل أراد أن به تأسفا\n(بالباب يرصد كل طالب حاجة ... فإذا خلا فالمرء غير مسدد)\n(وإذا حللت ودون بيتي غاوة ... فابرق بأرضك ما بدا لك وارعد)\nاوة موضع بالشام أو باليمامة ويقال هي أرض دون بني حنيفة يقول تهددني ما بدا لك فإني لا أبالي بوعيدك\n(أبني قلابة لم تكن عاداتكم ... أخذ الدنية قبل خطة معصد)\n(لم يرحض السوءات عن أحسابكم ... نعم الحواثر إذ نساق لمعبد)\n(فالعبد دونكم اقتلوا بأخيكم ... كالعير أبرز جنبه للمطرد)\nال يعقوب قال ابن الكلبي قلابة بنت الحارث بن قيس بن الحارث بن ذهل من بني يشكر تزوجها سعد بن مالك بن ضبيعة بن قيس بن ثعلبة فولدت له مرثدا وكهفا وقميئة ومرقشا الشاعر الأكبر وقال غير ابن الكلبي قلابة امرأة من بني يشكر وهي بعض جدات طرفة وهي بنت عوف ابن الحارث اليشكري ويقال هي قلابة بنت رهم ومعضد بن عمرو الذي ولي قتل طرفة وهو ابن الحواثر من عبد القيس وقال غيره معضد الذي جاء بالإبل لدية طرفة فدفعها إلى قومه وقال يعقوب\nإن الذي قتل طرفة رجل من عبد القيس ثم من الحواثر يقال له أبو ريشة وإن الحواثر ودته إلى أبيه وقومه لما كان من قتل صاحبهم إياه وقال ابن الكلبي الحواثر هم ربيعة وجبيل ابنا عمرو بن عوف بن وديعة بن لكيز ابن أفصى بن عبد القيس وعمرو بن عوف بن عمرو بن عوف ابن بكر بن عوف بن أنمار وحوثرة هو ربيعة بن عمرو وإنما حضر هؤلاء معه فسموا الحواثر والحوثرة حشفة الرجل وإنما سمي حوثرة لأنه ساوم بقدح بعكاظ أو بمكة فاستصغره فقال لصاحبه لو وضعت فيه حوثرتي لملاته فبذلك سمي حوثرة ومعبد بن العبد أخو طرفة\nوقال ابن الكلبي كان عمرو بن هند ودى طرفة من نعم كان أصابه من الحواثر يقول لن يغسل عنكم العار أخذكم الدية دون أن تثأروا به وتقتلوا عمرو بن هند الذي هو كالحمار أعرض جنبه للرمح أي أمكن\nوروى أبو عبيدة قبل خطة معصد بالصاد غير المعجمة أي يفعل به من العصد وهو النكاح يريد به عمرو بن هند وقال غيرهم إن عمرو بن هند انتفى من قتل طرفة وزعم أنه لم يأمر الحوثري بقتله فأخذت ديته من الحوثري لأنه قتل بيده فدفعت إلى معبد بن العبد أخي طرفة","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":13,"spl":"المتلمس يهرب إلى الشام ويقول شعرا","tags":["عمارة","الحب والغزل"],"loc":4047},
{"id":"b312-25","bab":"الجزء 24","sec":"المتلمس شاعر بني ضبيعة","page":"ج24 ص245","text":"وروى ابن الكلبي عن محراش بن إسماعيل العجلي ورواه المفضل الضبي قالا كان المتلمس شاعر ربيعة في زمانه وإنه وقف على مجلس لبني ضبيعة بن قيس بن ثعلبة فاستنشدوه فأنشدهم شعرا فقال فيه\n(وقد أتناسى الهم عند احتضاره ... بناج عليه الصيعرية مكدم)\nالصيعرية سمة تكون للإناث خاصة فقال له طرفة وهو غلام استنوق الجمل أي وصفت الجمل بوصف الناقة وخلطت فذهبت كلمته مثلا وقال الكميت بن زيد\n(هززتكم لو أن فيكم مهزة ... وذكرت ذا التأنيث فاستنوق الجمل)\nقال ابن السكيت في كتاب الأمثال زعموا أن المتلمس صاحب الصحيفة كان أشعر أهل زمانه وهو أحد بني ضبيعة بن ربيعة بن نزار وأنه وقف ذات يوم على مجلس لبني قيس ابن ثعلبة وطرفة بن العبد يلعب مع الغلمان يستمعون فزعموا أن المتلمس أنشد هذا البيت\n(وقد أتناسى الهم عند احتضاره ... بناج عليه الصيعرية مكدم)\nالصيعرية فيما يزعمون سمة توسم بها النوق باليمن دون الجمال فقال طرفة استنوق الجمل فأرسلها مثلا فضحك القوم فغضب المتلمس ونظر إلى لسان طرفة وقال ويل لهذا من هذا يعني رأسه من لسانه وقال أبو محمد بن رستم حدثني أبو يعقوب بن السكيت قال\nعاب طرفة وهو غلام على المسيب بن علس بيتا قاله في قصيدته وهو قوله\n(وقد أتناسى الهم عند احتضاره ... بناج عليه الصيعرية مكدم)\nلصيعرية سمة تكون على الإناث خاصة مكدم غليظ\n(كميت كناز اللحم أو حميرية ... مواشكة تنفي الحصى بمثلم)\nناز مكتنز اللحم مواشكة سريعة وملثم خف قد لثمته الحجارة\n(كأن على أنسائه عذق خصبة ... تدلى من الكافور غير مكمم)\nبه هلب ذنبه بكباسة الخصبة وهي الدقلة والجمع الخصاب وغير مكمم غير مغطى فقال طرفة وهو لا يعرفه استنوق الجمل أي إن هذه السمة لا تكون إلا على الناقة فقال له المسيب ارجع إلى أهلك بوامئة وهي الداهية فقال له طرفة لو عاينت هن أمك هناك فقال له المسيب من أنت قال طرفة بن العبد فأعرض عنه المسيب","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":14,"spl":"المتلمس شاعر بني ضبيعة — الأصمعي يقول المتلمس من الفحول","tags":["عمارة","اللهو والمزاح","السفر والحج"],"loc":4048},
{"id":"b312-26","bab":"الجزء 24","sec":"الأصمعي يقول المتلمس من الفحول","page":"ج24 ص246","text":"وقال ابن النحاس قال الأصمعي المتلمس من الفحول وقال أبو عبيدة لم يسبق المتلمس إلى قوله\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\n(وما كنت إلا مثل قاطع كفه ... بكف له أخرى فأصبح أجذما)\n(يداه أصابت هذه حتف هذه ... فلم تجد الأخرى عليها تقدما)\n(فلما استقاد الكف بالكف لم يجد ... له دركا في أن تبينا فأحجما)\n(فأطرق إطراق الشجاع ولو يرى ... مساغا لنابيه الشجاع لصمما)\nال وذو الحلم عامر بن الظرب العدواني لما كبر قال لأهله إن جرت في حكومتي فاقرعوني بعصا","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":14,"spl":"المتلمس شاعر بني ضبيعة — الأصمعي يقول المتلمس من الفحول","tags":["عمارة"],"loc":4049},
{"id":"b312-27","bab":"الجزء 24","sec":"لمن قرعت العصا","page":"ج24 ص247","text":"وقال أبو رياش قرع العصا مثل تدعيه دوس وهم من أزد السراة لعمرو بن حممة وتدعيه قيس لعامر بن الظرب العدواني وتدعيه بنو قيس بن ثعلبة لسعد بن مالك بن ضبيعة\nفأما ما تدعيه دوس لعمرو بن حممة فالخبر فيه وفي عامر بن الظرب واحد وهو أنه كان كل واحد منهما حكما للعرب يتحاكمون إليه في كل معضلة وعمرو بن حممة في هذا الحديث أشهر وذلك أن العرب أتوه يتحاكمون إليه فغلط في بعض حكومته وكان الشيخ قد أسن وتغير فقالت له بنته إنك قد صرت تهم في حكمك يقال وهم الرجل إذا غلط وذهب وهمي إلى كذا أي ظني وأوهم إذا أسقط فقال لابنته إذا رأيت ذلك فاقرعي لي العصا وكانت إذا قرعت له بالعصا ثاب إليه حلمه فأصاب في حكمه وأما ما تدعيه بنو قيس بن ثعلبة فيزعمون أن سعد بن مالك بن ضبيعة ابن قيس أتى النعمان الأكبر ومعه خيل بعضها يقاد وبعضها أعراء مهملة فلما انتهى إلى النعمان سأله عنها فقال له سعد إني لم أقد هذه لأمنعها ولم أعر هذه لأهبها فسأله النعمان عن أرضه هل أصابها غيث يحمد أثره أو\nروى شجره فقال سعد أما المطر فغزير وأما الورق فشكير وأما النافذة فساهرة وأما الحازرة فشبعى نائمة وأما الرمثاء فقد امتلأت مساربها وابتلت جنائبها ويروى الدهناء بدل الرمثاء وأما النبائث فغدر لا تطلع وأما الحذف فعراب لا تنكع تقتر إذا ترتع الشكير ساعة نبته والنافذة ضرب من الغنم وكذلك الحازرة أيضا والرمثاء أرض والنبائث تراب والحذف غنم صغار وتنكع تمنع وتقتر تطلب القرارة وهي بقية القدر ويقال تقتر تطلب القرار وهي صغار الغنم فقال النعمان وحسده على ما رأى من ذرابة لسانه وأبيك إنك لمفوه فإن شئت آتيك بما تعيا عن جوابه فقال سعد شئت إن لم يكن منك إفراط ولا إبعاط والإبعاط مجاوزة القدر فأمر النعمان وصيفا له\nفلطمه وإنما أراد أن يتعدى في القول فيقتله فقال له ما جواب هذه قال سعد سفيه مأمور فأرسلها مثلا فقال النعمان للوصيف الطمه أخرى فلطمه فقال ما جواب هذه\nقال لو نهي عن الأولى لم يعد للأخرى فأرسلها مثلا فقال النعمان للوصيف الطمه أخرى ففعل فقال له ما جواب هذه قال ملك يؤدب عبده فقال الطمه أخرى ففعل فقال ما جواب هذه\nقال ملكت فاسجح فأرسلها مثلا فقال له النعمان أجبت فاقعد فمكث عنده ما مكث ثم بدا للنعمان أن يبعث رائدا يرتاد له الكلأ فبعث عمرو بن مالك أخا سعد بن مالك فأبطأ عليه فأغضبه ذلك فأقسم إن جاء حامدا أو ذاما ليقتلنه فلما قدم عمرو على النعمان دخل عليه والناس عنده وسعد قاعد لديه مع الناس وقد كان سعد عرف بما أقسم به النعمان من يمينه فقال سعد أتأذن لي أيها الملك فاكلمه\nقال إن كلمته قطعت لسانك قال فأشير إليه قال إن أشرت إليه قطعت يدك قال فأومىء إليه قال إذا أنزع حدقتك قال فاقرع له العصا قال وما يدريه ما تقول العصا فاقرع له فتناول عصا من بعض جلسائه فوضعها بين يديه وأخذ عصاه التي كانت معه وأخوه قائم فقرع بعصاه العصا قرعة واحدة فنظر إليه أخوه ثم أومأ بالعصا نحوه فعرف أنه يقول له مكانك ثم قرع العصا قرعة واحدة ثم رفعها إلى السماء ومسح عصاه بالأخرى فعرف أنه يقول له لم أجد جدبا ثم قرع العصا مرارا بطرف عصاه ثم رفعها شيئا فعرف أنه يقول ولا نباتا ثم قرع العصا قرعة وأقبل بها نحو النعمان فعرف أنه يقول له كلمه فأقبل عمرو بن مالك حتى قام بين يدي النعمان فقال له النعمان هل حمدت خصبا أو ذممت جدبا فقال عمرو لم أذمم جدبا ولم أحمد خصبا الأرض مشكلة لا خصبها يعرف ولا جدبها يوصف رائدها واقف ومنكرها عارف وآمنها خائف فقال له النعمان أولى لك بذلك نجوت فنجا وهو أول من قرعت له العصا وعمرو هذا هو الحشام أخو سعد فقال سعد لقرعه العصا\n(قرعت العصا حتى تبين صاحبي ... ولم تك لولا ذاك للقوم تقرع)\n(فقال رأيت الأرض ليس بممحل ... ولا سارح فيها على الرعي يشبع)\n(سواء فلا جدب فيعرف جدبها ... ولا صابها غيث غزير فتمرع)\n(فنجى بها حوباء نفس كريمة ... وقد كاد لولا ذاك فيهم يقطع)","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":15,"spl":"لمن قرعت العصا","tags":["عمارة","الجواري والنساء"],"loc":4050},
{"id":"b312-28","bab":"الجزء 24","sec":"أول من قرع العصا وقرعت له","page":"ج24 ص250","text":"وقد روى عبيد بن شرية الجرهمي أن حارثة بن عبد العزى سأل مالك بن جبير عن أول من قرع العصا وقرعت له وعن قول الشاعر\n(وزعمتم أن لا حلوم لنا ... إن العصا قرعت لذي الحلم)\nقال مالك على الخبير سقطت وبالعليم أحطت إن أول من قرع العصا سعد بن مالك أخو بني كنانة حين أتى الملك المنذر بن النعمان ومعه خيل بعضها تقاد مهيأة والأخرى مهملة\nوذكر الخبر نحو ما ذكره أبو رياش وفي الألفاظ زيادة ونقصان والمعنى واحد وذكر الجاحظ أن عامر بن الظرب العدواني حكم العرب في الجاهلية لما أسن واعتراه النسيان أمر بنته أن تقرع بالعصا إذا هو فهه عن الحكم وجار عن القصد وكانت من حكيمات بنات العرب حتى جاوزت في ذلك مقدار صحر بنت لقمان وهند بنت الخس وجمعة بنت\nحابس بن مليل الإياديين وكان يقال لعامر ذو الحلم ولذلك قال الحارث بن وعلة\n(وزعمتم أن لا حلوم لنا ... إن العصا قرعت لذي الحلم)\nقال المتلمس\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\nقال الفرزدق بن غالب\n(فإن كنت أستأني حلوم مجاشع ... فإن العصا كانت لذي الحلم تقرع)\nمن ذلك حديث سعد بن مالك بن ضبيعة بن قيس بن ثعلبة واعتزام الملك على قتل أخيه إن هو لم يصب ضميره فقال له سعد أبيت اللعن أتدعني حتى أقرع العصا له بهذه العصا أختها فقال له الملك وما علمه بذلك أي مما تقول العصا فقرع بها مرة وأشار بها مرة ثم رفعها ثم وضعها ففهم المعنى فأخبره ونجا من القتل","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":16,"spl":"أول من قرع العصا وقرعت له — من الشام يهجو","tags":["عمارة"],"loc":4051},
{"id":"b312-29","bab":"الجزء 24","sec":"من الشام يهجو","page":"ج24 ص251","text":"رجع الحديث إلى خبر المتلمس وروى أبو حاتم عن الأصمعي أن المتلمس هجا عمرو بن هند بعد لحاقه بالشام فقال\n(أطردتني حذر الهجاء ولا ... واللات والأنصاب ماتئل)\n(ورهنتني هندا وعرضك في ... صحف تلوح كأنها خلل)\n(شر الملوك وشرها حسبا ... في الناس من علموا ومن جهلوا)\n(بئس الفحولة حين جد بهم ... عرك الرهان وبئس ما نجلوا)\n(أعني الخؤولة والعموم فهم ... كالطبن ليس لبيته حول)\nال والطبن بكسر الطاء وفتحها لعبة يلعب بها الصبيان في الأعراب وهي بالفارسية السدر وإنما يصفه بالضعف قال أبو النجم\n(من ذكر آيات ورسم لاحي ... كالطبن في مختلف الرياح)\nيروى أيضا الطبن وروي أن عمر بن عبد العزيز رحمه الله جلس يعترض الناس ويكتب الزمنى فوقف عليه أعرابي فأنشأ يقول\n(إن تكتبوا الزمنى فإني لزمن ... من ظاهر الداء وداء مستكن)\n(أبيت أهوي في شياطين ترن ... مختلف نجواهم حن وجن)\n(فبتن يلعبن حوالي الطبن ... )\nقال زمنوا هذا ثم وقف عليه شيخ منهم فقال له ما زمانتك فقال الأعرابي\n(فوالله ما أدري أأدركت أمة ... على عهد ذي القرنين أم كنت أقدما)\n(متى تنزعا عني القميص تبينا ... جناجن لم يكسين لحما ولا دما)\nقال عمر زمنوا هذا فإنه لا يدري متى ولد وقوله حن وجن فإن الجن سفلة الجن وقال الجاحظ الجن ضربان حن وجن كما يقال ناس ونسناس والشعر الذي فيه الغناء المذكور بسببه خبر المتلمس يقوله المتلمس حين فارق أخواله من بني يشكر","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":16,"spl":"أول من قرع العصا وقرعت له — من الشام يهجو","tags":["عمارة"],"loc":4052,"partial":1},
{"id":"b312-30","bab":"الجزء 24","sec":"المتلمس منوط في بني عمرو بن مرة","page":"ج24 ص252","text":"وروى أبو حاتم عن الأصمعي أن المتلمس ولد في أخواله من بني\nيشكر ونشأ فيهم حتى كادوا يغلبون عليه فسأل الملك عنه الحارث بن التوأم اليشكري والحارث بن جلدة فقال ممن المتلمس فقالا هو منوط في بني عمرو بن مرة أي إنه من ضبيعة مرة ومرة منا وهو ساقط بين الحيين ففارق أخواله ولحق بقومه بني ضبيعة وقال في ذلك\n(تفرق أهلي من مقيم وظاعن ... فلله دري أي أهلي أتبع)\n(أقام الذين لا أحب جوارهم ... وبان الذين بينهم أتوقع)\nال الرياشي الذي أعرف\n(أقام الذين لا أبالي فراقهم ... )\n(على كلهم آسى وللأصل زلفة ... فزحزح عن الأدنين أن يتصدعوا)\nيقول لا تتباعد عن الأدنين فيصدعوا عنك ويفارقوك وإنما عنى أخواله من بني يشكر وقومه من بني ضبيعة\n(ألكني إلى قومي ضبيعة إنهم ... أناسي فلوموا بعد ذلك أو دعوا)\n(وقد كان أخوالي كريما جوارهم ... ولكن أصل العود من حيث ينزع)\nقول أخوالي كانوا كراما ولكني أذهب إلى أعمامي كما ينزع العرق إلى أصله\n(ولا تحسبني خاذلا متخلفا ... ولا عين صيد من هواي ولعلع)\nين صيد ولعلع من آخر السواد إلى البر فيما بين البصرة والكوفة ولعلع كان سجن الحجاج بن يوسف\nوقال المتلمس في ذلك أيضا\n(لعلك يوما أن يسرك أنني ... شهدت وقد رمت عظامي في قبري)\n(وتصبح مظلوما تسام دنية ... حريصا على مثلي فقيرا إلى نصري)\n(ويهجرك الإخوان بعدي وتبتلى ... وينصرني منك الإله ولا تدري)\n(ولو كنت حيا يوم ذلك لم تسم ... له خطة خسفا وشوورت في الأمر)\nال وفي ذلك يقول\n(ولو غير أخوالي أرادوا نقيصتي ... جعلت لهم فوق العرانين ميسما)\n(أحارث إنا لو تساط دماؤنا ... تزايلن حتى لا يمس دم دما)\nقول لو خلطت دماؤنا ودماؤكم لتزايلت وتميزت من بعد ما بيننا وهذا كما قال الآخر\n(لعمرك إنني وأبا رياح ... على طول التهاجر منذ حين)\n(ليبغضني وأبغضه وأيضا ... يراني دونه وأراه دوني)\n(فلو أنا على حجر ذبحنا ... جرى الدميان بالخبر اليقين)","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":17,"spl":"المتلمس منوط في بني عمرو بن مرة — ما يعاب في شعره وما يتمثل به","tags":["عمارة","السفر والحج","الرواية والكتابة"],"loc":4053,"partialRef":{"sid":"b312-11","gi":2,"vi":1,"side":0},"partial":1},
{"id":"b312-31","bab":"الجزء 24","sec":"ما يعاب في شعره وما يتمثل به","page":"ج24 ص254","text":"قال ابن قتيبة وما يعاب من قول المتلمس قوله\n(أحارث إنا لو تساط دماؤنا ... تزايلن حتى لا يمس دم دما)\nوهذا من الكذب والإفراط ومثله قول رجل من بني شيبان كنت أسيرا مع بني عم لي وفينا جماعة من موالينا في أيدي التغالبة فضربوا أعناق بني عمي وأعناق الموالي على وهدة من الأرض فكنت والله أرى دم العربي ينماز من دم المولى حتى أرى بياض الأرض من بينهما فإذا كان هجينا قام فوقه ولم يعتزل عنه وقال ابن قتيبة ويتمثل من شعر المتلمس بقوله\n(وأعلم علم حق غير ظن ... وتقوى الله من خير العتاد)\n(لحفظ المال أيسر من بغاه ... وضرب في البلاد بغير زاد)\n(وإصلاح القليل يزيد فيه ... ولا يبقى الكثير على الفساد)\nقال أبو علي الحاتمي أشرد مثل قيل في البغض قول المتلمس\n(أحارث إنا لو تساط دماؤنا ... تزايلن حتى لا يمس دم دما)\nكى ذلك أبو عبيدة وزعم أنه أسير مثل في البغض قال وأشرد مثل قيل في الفخر بالأمهات قوله أيضا\n(يعيرني أمي رجال ولن ترى ... أخا كرم إلا بأن يتكرما)\n(وهل لي أم غيرها إن تركتها ... أبى الله إلا أن أكون لها ابنما)\nال\nوأشرد مثل قيل في اعتداد بني العم والكف عن مقاتلتهم بفعلهم قوله\n(وما كنت إلا مثل قاطع كفه ... بكف له أخرى فأصبح أجذما)\n(يداه أصابت هذه حتف هذه ... فلم تجد الأخرى عليها تقدما)\n(فلما استقاد الكف بالكف لم يجد ... له دركا في أن تبينا فأحجما)\n(فأطرق إطراق الشجاع ولو يرى ... مساغا لنابيه الشجاع لصمما)\nال أبو عبيدة يريد أنه فيما صنع به أخواله بمنزلة من قطع إحدى يديه بالأخرى فلو هجاهم وكافأهم كان بمنزلة من قطع يده الأخرى فبقي أجذم فأمسك عنهم قال أبو علي والبيت الأخير يضرب مثلا للرجل يقصر إلى أن تمكنه الفرصة قال أبو عبيدة ولم أسمع لأحد بمثل هذه الأبيات حكمة وأمثالا من أولها إلى آخرها وفيها من الأمثال السائرة ما يضرب مثلا للحكيم يذكر به عند نسيانه\n(لذي الحلم قبل اليوم ما تقرع العصا ... وما علم الإنسان إلا ليعلما)\nفيها من شارد الأمثال\n(إذا لم يزل حبل القرينين يلتوي ... فلا بد يوما من قوى أن تجذما)\nال أبو علي\nوأشرد مثل قيل في حفظ المال وتثميره قوله\n(قليل المال تصلحه فيبقى ... ولا يبقى الكثير مع الفساد)\n(وحفظ المال أيسر من بغاه ... وسير في البلاد بغير زاد)","topic":"أخبار عمارة ونسبه","topicNo":312,"sp":17,"spl":"المتلمس منوط في بني عمرو بن مرة — ما يعاب في شعره وما يتمثل به","tags":["عمارة","الهجاء"],"loc":4054}]);